-- GENERATED by scripts/mealdb/import.mjs. Do not edit by hand.
-- 473 dinner recipes from TheMealDB (https://www.themealdb.com).
insert into public.recipes (source_id, title, category, country, tags, image_url, youtube_url, source_url, ingredients, steps, ingredient_names, allergens, diet_flags)
select source_id, title, category, country, tags, image_url, youtube_url, source_url, ingredients, steps, ingredient_names, allergens, diet_flags
from jsonb_to_recordset($seed$[{"source_id":"52764","title":"Garides Saganaki","category":"Seafood","country":"Greece","tags":["Seafood","Shellfish"],"image_url":"https://www.themealdb.com/images/media/meals/wuvryu1468232995.jpg","youtube_url":"https://www.youtube.com/watch?v=uO0ejc85zSE","source_url":null,"ingredients":[{"name":"Raw king prawns","measure":"500g"},{"name":"Olive oil","measure":"3 tablespoons"},{"name":"Chopped onion","measure":"1"},{"name":"Freshly chopped parsley","measure":"pinch"},{"name":"White wine","measure":"250ml"},{"name":"Chopped tomatoes","measure":"1 (400g) tin"},{"name":"Minced garlic","measure":"1/2 teaspoon"},{"name":"Cubed Feta cheese","measure":"1 (200g) pack"}],"steps":["Place the prawns in a pot and add enough water to cover. Boil for 5 minutes. Drain, reserving the liquid, and set aside.","Heat 2 tablespoons of oil in a saucepan. Add the onion; cook and stir until soft. Mix in the parsley, wine, tomatoes, garlic and remaining olive oil. Simmer, stirring occasionally, for about 30 minutes, or until the sauce is thickened.","While the sauce is simmering, the prawns should become cool enough to handle. First remove the legs by pinching them, and then pull off the shells, leaving the head and tail on.","When the sauce has thickened, stir in the prawns. Bring to a simmer again if the sauce has cooled with the prawns, and cook for about 5 minutes. Add the feta and remove from the heat. Let stand until the cheese starts to melt. Serve warm with slices of crusty bread.","Though completely untraditional, you can add a few tablespoons of stock or passata to this recipe to make a delicious pasta sauce. Toss with pasta after adding the feta, and serve."],"ingredient_names":["raw king prawns","olive oil","chopped onion","freshly chopped parsley","white wine","chopped tomatoes","minced garlic","cubed feta cheese"],"allergens":["dairy","shellfish"],"diet_flags":["pescatarian"]},{"source_id":"52765","title":"Chicken Enchilada Casserole","category":"Chicken","country":"Mexico","tags":["Casserole","Cheasy","Meat"],"image_url":"https://www.themealdb.com/images/media/meals/qtuwxu1468233098.jpg","youtube_url":"https://www.youtube.com/watch?v=EtVkwVKLc_M","source_url":null,"ingredients":[{"name":"Enchilada sauce","measure":"14 oz jar"},{"name":"shredded Monterey Jack cheese","measure":"3 Cups"},{"name":"corn tortillas","measure":"6"},{"name":"chicken breasts","measure":"2"}],"steps":["Cut each chicken breast in about 3 pieces, so that it cooks faster and put it in a small pot. Pour Enchilada sauce over it and cook covered on low to medium heat until chicken is cooked through, about 20 minutes. No water is needed, the chicken will cook in the Enchilada sauce. Make sure you stir occasionally so that it doesn't stick to the bottom.","Remove chicken from the pot and shred with two forks.","Preheat oven to 375 F degrees.","Start layering the casserole. Start with about ¼ cup of the leftover Enchilada sauce over the bottom of a baking dish. I used a longer baking dish, so that I can put 2 corn tortillas across. Place 2 tortillas on the bottom, top with ⅓ of the chicken and ⅓ of the remaining sauce. Sprinkle with ⅓ of the cheese and repeat starting with 2 more tortillas, then chicken, sauce, cheese. Repeat with last layer with the remaining ingredients, tortillas, chicken, sauce and cheese.","Bake for 20 to 30 minutes uncovered, until bubbly and cheese has melted and started to brown on top.","Serve warm."],"ingredient_names":["enchilada sauce","shredded monterey jack cheese","corn tortillas","chicken breasts"],"allergens":["dairy"],"diet_flags":[]},{"source_id":"52769","title":"Kapsalon","category":"Lamb","country":"Netherlands","tags":["Snack"],"image_url":"https://www.themealdb.com/images/media/meals/sxysrt1468240488.jpg","youtube_url":"https://www.youtube.com/watch?v=UIcuiU1kV8I","source_url":null,"ingredients":[{"name":"Fries","measure":"250 Grams"},{"name":"Doner Meat","measure":"500 Grams"},{"name":"Garlic sauce","measure":"Topping"},{"name":"Hotsauce","measure":"Topping"},{"name":"Lettuce","measure":"1 Bulb"},{"name":"Tomato","measure":"1"},{"name":"Cucumber","measure":"3rd"},{"name":"Gouda cheese","measure":"100 Grams"}],"steps":["Cut the meat into strips. Heat oil in a pan and fry the strips for 6 minutes until it's ready.","Bake the fries until golden brown in a deep fryrer. When ready transfer to a backing dish. Make sure the fries are spread over the whole dish.","Cover the fries with a new layer of meat and spread evenly.","Add a layer of cheese over the meat. You can also use grated cheese. When done put in the oven for a few minutes until the cheese is melted.","Chop the lettuce, tomato and cucumber in small pieces and mix together. for a basic salad. As extra you can add olives jalapenos and a red union.","Dived the salad over the dish and Serve with garlicsauce and hot sauce"],"ingredient_names":["fries","doner meat","garlic sauce","hotsauce","lettuce","tomato","cucumber","gouda cheese"],"allergens":["dairy"],"diet_flags":[]},{"source_id":"52770","title":"Spaghetti Bolognese","category":"Beef","country":"Italy","tags":["Pasta","Meat"],"image_url":"https://www.themealdb.com/images/media/meals/sutysw1468247559.jpg","youtube_url":"https://www.youtube.com/watch?v=-gF8d-fitkU","source_url":null,"ingredients":[{"name":"onions","measure":"2"},{"name":"olive oil","measure":"1tbsp"},{"name":"garlic","measure":"1 clove"},{"name":"lean minced beef","measure":"500g"},{"name":"mushrooms","measure":"90g"},{"name":"dried oregano","measure":"1tsp"},{"name":"tomatoes","measure":"400g can"},{"name":"hot beef stock","measure":"300ml"},{"name":"tomato puree","measure":"1tbsp"},{"name":"worcestershire sauce","measure":"1tbsp"},{"name":"spaghetti","measure":"350g"},{"name":"parmesan","measure":"Topping"}],"steps":["Put the onion and oil in a large pan and fry over a fairly high heat for 3-4 mins. Add the garlic and mince and fry until they both brown. Add the mushrooms and herbs, and cook for another couple of mins.","Stir in the tomatoes, beef stock, tomato ketchup or purée, Worcestershire sauce and seasoning. Bring to the boil, then reduce the heat, cover and simmer, stirring occasionally, for 30 mins.","Meanwhile, cook the spaghetti in a large pan of boiling, salted water, according to packet instructions. Drain well, run hot water through it, put it back in the pan and add a dash of olive oil, if you like, then stir in the meat sauce. Serve in hot bowls and hand round Parmesan cheese, for sprinkling on top."],"ingredient_names":["onions","olive oil","garlic","lean minced beef","mushrooms","dried oregano","tomatoes","hot beef stock","tomato puree","worcestershire sauce","spaghetti","parmesan"],"allergens":["dairy","fish","gluten"],"diet_flags":[]},{"source_id":"52771","title":"Spicy Arrabiata Penne","category":"Vegetarian","country":"Italy","tags":["Pasta","Curry"],"image_url":"https://www.themealdb.com/images/media/meals/ustsqw1468250014.jpg","youtube_url":"https://www.youtube.com/watch?v=1IszT_guI08","source_url":null,"ingredients":[{"name":"penne rigate","measure":"1 pound"},{"name":"olive oil","measure":"1/4 cup"},{"name":"garlic","measure":"3 cloves"},{"name":"chopped tomatoes","measure":"1 tin"},{"name":"red chilli flakes","measure":"1/2 teaspoon"},{"name":"italian seasoning","measure":"1/2 teaspoon"},{"name":"basil","measure":"6 leaves"},{"name":"Parmigiano-Reggiano","measure":"sprinkling"}],"steps":["Bring a large pot of water to a boil. Add kosher salt to the boiling water, then add the pasta. Cook according to the package instructions, about 9 minutes.","In a large skillet over medium-high heat, add the olive oil and heat until the oil starts to shimmer. Add the garlic and cook, stirring, until fragrant, 1 to 2 minutes. Add the chopped tomatoes, red chile flakes, Italian seasoning and salt and pepper to taste. Bring to a boil and cook for 5 minutes. Remove from the heat and add the chopped basil.","Drain the pasta and add it to the sauce. Garnish with Parmigiano-Reggiano flakes and more basil and serve warm."],"ingredient_names":["penne rigate","olive oil","garlic","chopped tomatoes","red chilli flakes","italian seasoning","basil","parmigiano-reggiano"],"allergens":["dairy","gluten"],"diet_flags":["pescatarian","vegetarian"]},{"source_id":"52772","title":"Teriyaki Chicken Casserole","category":"Chicken","country":"Japan","tags":["Meat","Casserole"],"image_url":"https://www.themealdb.com/images/media/meals/wvpsxx1468256321.jpg","youtube_url":"https://www.youtube.com/watch?v=4aZr5hZXP_s","source_url":null,"ingredients":[{"name":"soy sauce","measure":"3/4 cup"},{"name":"water","measure":"1/2 cup"},{"name":"brown sugar","measure":"1/4 cup"},{"name":"ground ginger","measure":"1/2 teaspoon"},{"name":"minced garlic","measure":"1/2 teaspoon"},{"name":"cornstarch","measure":"4 Tablespoons"},{"name":"chicken breasts","measure":"2"},{"name":"stir-fry vegetables","measure":"1 (12 oz.)"},{"name":"brown rice","measure":"3 cups"}],"steps":["Preheat oven to 350° F. Spray a 9x13-inch baking pan with non-stick spray.","Combine soy sauce, ½ cup water, brown sugar, ginger and garlic in a small saucepan and cover. Bring to a boil over medium heat. Remove lid and cook for one minute once boiling.","Meanwhile, stir together the corn starch and 2 tablespoons of water in a separate dish until smooth. Once sauce is boiling, add mixture to the saucepan and stir to combine. Cook until the sauce starts to thicken then remove from heat.","Place the chicken breasts in the prepared pan. Pour one cup of the sauce over top of chicken. Place chicken in oven and bake 35 minutes or until cooked through. Remove from oven and shred chicken in the dish using two forks.","*Meanwhile, steam or cook the vegetables according to package directions.","Add the cooked vegetables and rice to the casserole dish with the chicken. Add most of the remaining sauce, reserving a bit to drizzle over the top when serving. Gently toss everything together in the casserole dish until combined. Return to oven and cook 15 minutes. Remove from oven and let stand 5 minutes before serving. Drizzle each serving with remaining sauce. Enjoy!"],"ingredient_names":["soy sauce","water","brown sugar","ground ginger","minced garlic","cornstarch","chicken breasts","stir-fry vegetables","brown rice"],"allergens":["gluten","soy"],"diet_flags":[]},{"source_id":"52773","title":"Honey Teriyaki Salmon","category":"Seafood","country":"Japan","tags":["Fish","Breakfast","DateNight"],"image_url":"https://www.themealdb.com/images/media/meals/xxyupu1468262513.jpg","youtube_url":"https://www.youtube.com/watch?v=4MpYuaJsvRw","source_url":null,"ingredients":[{"name":"Salmon","measure":"1 lb"},{"name":"Olive oil","measure":"1 tablespoon"},{"name":"Soy Sauce","measure":"2 tablespoons"},{"name":"Sake","measure":"2 tablespoons"},{"name":"Sesame Seed","measure":"4 tablespoons"}],"steps":["Mix all the ingredients in the Honey Teriyaki Glaze together. Whisk to blend well. Combine the salmon and the Glaze together.","Heat up a skillet on medium-low heat. Add the oil, Pan-fry the salmon on both sides until it’s completely cooked inside and the glaze thickens.","Garnish with sesame and serve immediately."],"ingredient_names":["salmon","olive oil","soy sauce","sake","sesame seed"],"allergens":["fish","gluten","sesame","soy"],"diet_flags":["pescatarian"]},{"source_id":"52774","title":"Pad See Ew","category":"Chicken","country":"Thailand","tags":["Pasta"],"image_url":"https://www.themealdb.com/images/media/meals/uuuspp1468263334.jpg","youtube_url":"https://www.youtube.com/watch?v=Ohy1DELF4is","source_url":null,"ingredients":[{"name":"rice stick noodles","measure":"6oz/180g"},{"name":"dark soy sauce","measure":"2 tbsp"},{"name":"oyster sauce","measure":"2 tbsp"},{"name":"soy sauce","measure":"2 tsp"},{"name":"white vinegar","measure":"2 tsp"},{"name":"sugar","measure":"2 tsp"},{"name":"water","measure":"2 tbsp"},{"name":"peanut oil","measure":"2 tbsp"},{"name":"garlic","measure":"2 cloves"},{"name":"Chicken","measure":"1 cup"},{"name":"Egg","measure":"1"},{"name":"Chinese broccoli","measure":"4 cups"}],"steps":["Mix Sauce in small bowl.","Mince garlic into wok with oil. Place over high heat, when hot, add chicken and Chinese broccoli stems, cook until chicken is light golden.","Push to the side of the wok, crack egg in and scramble. Don't worry if it sticks to the bottom of the wok - it will char and which adds authentic flavour.","Add noodles, Chinese broccoli leaves and sauce. Gently mix together until the noodles are stained dark and leaves are wilted. Serve immediately!"],"ingredient_names":["rice stick noodles","dark soy sauce","oyster sauce","soy sauce","white vinegar","sugar","water","peanut oil","garlic","chicken","egg","chinese broccoli"],"allergens":["eggs","gluten","peanuts","shellfish","soy"],"diet_flags":[]},{"source_id":"52775","title":"Vegan Lasagna","category":"Vegan","country":"Italy","tags":["Vegan","Pasta"],"image_url":"https://www.themealdb.com/images/media/meals/rvxxuy1468312893.jpg","youtube_url":"https://www.youtube.com/watch?v=VU8cXvlGbvc","source_url":null,"ingredients":[{"name":"green red lentils","measure":"1 cups"},{"name":"Carrots","measure":"1"},{"name":"onion","measure":"1"},{"name":"zucchini","measure":"1 small"},{"name":"coriander","measure":"sprinking"},{"name":"spinach","measure":"150g"},{"name":"lasagne sheets","measure":"10"},{"name":"vegan butter","measure":"35g"},{"name":"flour","measure":"4 tablespoons"},{"name":"soya milk","measure":"300ml"},{"name":"mustard","measure":"1.5 teaspoons"},{"name":"vinegar","measure":"1 teaspoon"}],"steps":["Preheat oven to 180 degrees celcius.","Boil vegetables for 5-7 minutes, until soft. Add lentils and bring to a gentle simmer, adding a stock cube if desired. Continue cooking and stirring until the lentils are soft, which should take about 20 minutes.","Blanch spinach leaves for a few minutes in a pan, before removing and setting aside.","Top up the pan with water and cook the lasagne sheets. When cooked, drain and set aside.","To make the sauce, melt the butter and add the flour, then gradually add the soya milk along with the mustard and the vinegar. Cook and stir until smooth and then assemble the lasagne as desired in a baking dish.","Bake in the preheated oven for about 25 minutes."],"ingredient_names":["green red lentils","carrots","onion","zucchini","coriander","spinach","lasagne sheets","vegan butter","flour","soya milk","mustard","vinegar"],"allergens":["dairy","gluten","soy"],"diet_flags":["pescatarian","vegetarian"]},{"source_id":"52777","title":"Mediterranean Pasta Salad","category":"Seafood","country":"Italy","tags":["Pasta","Baking"],"image_url":"https://www.themealdb.com/images/media/meals/wvqpwt1468339226.jpg","youtube_url":"https://www.youtube.com/watch?v=e52IL8zYmaE","source_url":"https://thelemonsqueezy.com/recipe/mediterranean-pasta-salad/","ingredients":[{"name":"mozzarella balls","measure":"200 g"},{"name":"baby plum tomatoes","measure":"250 g"},{"name":"fresh basil","measure":"1  bunch"},{"name":"farfalle","measure":"350 g"},{"name":"extra virgin olive oil","measure":"3  tablespoons"},{"name":"Green Olives","measure":"40 g"},{"name":"tuna","measure":"200 g"},{"name":"salt","measure":"to taste"},{"name":"pepper","measure":"to taste"}],"steps":["Bring a large saucepan of salted water to the boil","Add the pasta, stir once and cook for about 10 minutes or as directed on the packet.","Meanwhile, wash the tomatoes and cut into quarters. Slice the olives. Wash the basil.","Put the tomatoes into a salad bowl and tear the basil leaves over them. Add a tablespoon of olive oil and mix.","When the pasta is ready, drain into a colander and run cold water over it to cool it quickly.","Toss the pasta into the salad bowl with the tomatoes and basil.","Add the sliced olives, drained mozzarella balls, and chunks of tuna. Mix well and let the salad rest for at least half an hour to allow the flavours to mingle.","Sprinkle the pasta with a generous grind of black pepper and drizzle with the remaining olive oil just before serving."],"ingredient_names":["mozzarella balls","baby plum tomatoes","fresh basil","farfalle","extra virgin olive oil","green olives","tuna","salt","pepper"],"allergens":["dairy","fish"],"diet_flags":["pescatarian"]},{"source_id":"52780","title":"Potato Gratin with Chicken","category":"Chicken","country":"Italy","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/qwrtut1468418027.jpg","youtube_url":"https://www.youtube.com/watch?v=p3u8eiy3yHI","source_url":"https://www.instagram.com/p/BHxR7hYBJ6P","ingredients":[{"name":"Potatoes","measure":"800g"},{"name":"Onions","measure":"3"},{"name":"Olive Oil","measure":"2 tblsp"},{"name":"Chicken Stock","measure":"100ml"},{"name":"Creme Fraiche","measure":"1 pot"},{"name":"Parmesan","measure":"Topping"},{"name":"Chicken Breasts","measure":"4"},{"name":"Bacon","measure":"4"},{"name":"Spinach","measure":"Topping"},{"name":"Peas","measure":"Topping"}],"steps":["15 minute potato gratin with chicken and bacon greens: a gratin always seems more effort and more indulgent than ordinary boiled or roasts, but it doesn't have to take 45mins, it's nice for a change and you can control the calorie content by going with full fat to low fat creme fraiche. (It's always tastes better full fat though obviously!) to serve 4: use 800g of potatoes, finely slice and boil in a pan for about 5-8 mins till firmish, not soft.","Finely slice 3 onions and place in an oven dish with 2 tblsp of olive oil and 100ml of chicken stock.","Cook till the onions are soft then drain the potatoes and pour onto the onions.","Season and spoon over cream or creme fraiche till all is covered but not swimming.","Grate Parmesan over the top then finish under the grill till nicely golden. serve with chicken and bacon, peas and spinach."],"ingredient_names":["potatoes","onions","olive oil","chicken stock","creme fraiche","parmesan","chicken breasts","bacon","spinach","peas"],"allergens":["dairy"],"diet_flags":[]},{"source_id":"52781","title":"Irish stew","category":"Beef","country":"Ireland","tags":["Stew","Meat"],"image_url":"https://www.themealdb.com/images/media/meals/sxxpst1468569714.jpg","youtube_url":"https://www.youtube.com/watch?v=kYH2qJXnSMo","source_url":"http://www.ottolenghi.co.uk/recipes/meat/irish-stew-shop","ingredients":[{"name":"whole wheat","measure":"300g soaked overnight in water"},{"name":"lamb loin chops","measure":"2kg cut into 3cm cubes"},{"name":"olive oil","measure":"120ml"},{"name":"shallots","measure":"24 Skinned"},{"name":"Carrots","measure":"4 large"},{"name":"turnips","measure":"2"},{"name":"celeriac","measure":"1"},{"name":"charlotte potatoes","measure":"350g"},{"name":"white wine","measure":"150ml"},{"name":"caster sugar","measure":"1 tsp"},{"name":"fresh thyme","measure":"4 sprigs"},{"name":"oregano","measure":"4 sprigs"},{"name":"chicken stock","measure":"450ml"}],"steps":["Heat the oven to 180C/350F/gas mark 4. Drain and rinse the soaked wheat, put it in a medium pan with lots of water, bring to a boil and simmer for an hour, until cooked. Drain and set aside.","Season the lamb with a teaspoon of salt and some black pepper. Put one tablespoon of oil in a large, deep sauté pan for which you have a lid; place on a medium-high heat. Add some of the lamb – don't overcrowd the pan – and sear for four minutes on all sides. Transfer to a bowl, and repeat with the remaining lamb, adding oil as needed.","Lower the heat to medium and add a tablespoon of oil to the pan. Add the shallots and fry for four minutes, until caramelised. Tip these into the lamb bowl, and repeat with the remaining vegetables until they are all nice and brown, adding more oil as you need it.","Once all the vegetables are seared and removed from the pan, add the wine along with the sugar, herbs, a teaspoon of salt and a good grind of black pepper. Boil on a high heat for about three minutes.","Tip the lamb, vegetables and whole wheat back into the pot, and add the stock. Cover and boil for five minutes, then transfer to the oven for an hour and a half.","Remove the stew from the oven and check the liquid; if there is a lot, remove the lid and boil for a few minutes."],"ingredient_names":["whole wheat","lamb loin chops","olive oil","shallots","carrots","turnips","celeriac","charlotte potatoes","white wine","caster sugar","fresh thyme","oregano","chicken stock"],"allergens":["gluten"],"diet_flags":[]},{"source_id":"52782","title":"Lamb tomato and sweet spices","category":"Lamb","country":"Morocco","tags":["Sweet"],"image_url":"https://www.themealdb.com/images/media/meals/qtwtss1468572261.jpg","youtube_url":"https://www.youtube.com/watch?v=vaZb1MnFBgA","source_url":"http://www.ottolenghi.co.uk/recipes/meat/lamb-tomato-and-sweet-spices-shop","ingredients":[{"name":"olive oil","measure":"2 tbsp"},{"name":"ginger","measure":"4cm piece finely chopped"},{"name":"garlic","measure":"2 cloves peeled and chopped"},{"name":"tomatoes","measure":"800g peeled and chopped"},{"name":"lemon juice","measure":"2 tbsp"},{"name":"caster sugar","measure":"1 tsp"},{"name":"vine leaves","measure":"50"},{"name":"fennel bulb","measure":"1 large"},{"name":"lamb mince","measure":"400g"},{"name":"onion","measure":"1 medium"},{"name":"potatoes","measure":"1 small peeled and coarsely grated"},{"name":"basmati rice","measure":"2 tbsp"},{"name":"chopped parsley","measure":"2 tbsp"},{"name":"coriander","measure":"2 tbsp chopped"},{"name":"lemon juice","measure":"1 tbsp"},{"name":"garlic","measure":"2 cloves"},{"name":"clove","measure":"½ tsp ground"},{"name":"cinnamon","measure":"½ tsp ground"},{"name":"tomatoes","measure":"2 medium"}],"steps":["Use pickled vine leaves here, preserved in brine. Small delicate leaves are better than the large bristly ones but, if only large leaves are to hand, then trim them to roughly 12 by 12 cms so that you don't get too many layers of leaves around the filling. And remove any stalks. Drain the preserved leaves, immerse them in boiling water for 10 minutes and then leave to dry on a tea towel before use.","Basmati rice with butter and pine nuts is an ideal accompaniment. Couscous is great, too. Serves four.","First make the filling. Put all the ingredients, apart from the tomatoes, in a bowl. Cut the tomatoes in half, coarsely grate into the bowl and discard the skins. Add half a teaspoon of salt and some black pepper, and stir. Leave on the side, or in the fridge, for up to a day. Before using, gently squeeze with your hands and drain away any juices that come out.","To make the sauce, heat the oil in a medium pan. Add the ginger and garlic, cook for a minute or two, taking care not to burn them, then add the tomato, lemon juice and sugar. Season, and simmer for 20 minutes.","While the sauce is bubbling away, prepare the vine leaves. Use any torn or broken leaves to line the base of a wide, heavy saucepan. Trim any leaves from the fennel, cut it vertically into 0.5cm-thick slices and spread over the base of the pan to cover completely.","Lay a prepared vine leaf (see intro) on a work surface, veiny side up. Put two teaspoons of filling at the base of the leaf in a 2cm-long by 1cm-wide strip. Fold the sides of the leaf over the filling, then roll it tightly from bottom to top, in a cigar shape. Place in the pan, seam down, and repeat with the remaining leaves, placing them tightly next to each other in lines or circles (in two layers if necessary).","Pour the sauce over the leaves (and, if needed, add water just to cover). Place a plate on top, to weigh the leaves down, then cover with a lid. Bring to a boil, reduce the heat and cook on a bare simmer for 70 minutes. Most of the liquid should evaporate. Remove from the heat, and leave to cool a little - they are best served warm. When serving, bring to the table in the pan - it looks great. Serve a few vine leaves and fennel slices with warm rice. Spoon the braising juices on top and garnish with coriander."],"ingredient_names":["olive oil","ginger","garlic","tomatoes","lemon juice","caster sugar","vine leaves","fennel bulb","lamb mince","onion","potatoes","basmati rice","chopped parsley","coriander","lemon juice","garlic","clove","cinnamon","tomatoes"],"allergens":[],"diet_flags":[]},{"source_id":"52783","title":"Rigatoni with fennel sausage sauce","category":"Lamb","country":"Italy","tags":["Pasta"],"image_url":"https://www.themealdb.com/images/media/meals/qtqvys1468573168.jpg","youtube_url":"https://www.youtube.com/watch?v=45dpOfESxr8","source_url":"http://www.ottolenghi.co.uk/recipes/meat/rigatoni-with-fennel-sausage-sauce-and-pecorino-and-anchovy-pesto-shop","ingredients":[{"name":"olive oil","measure":"2½ tbsp"},{"name":"Italian fennel sausages","measure":"6 cut into 1.5cm-thick slices"},{"name":"onion","measure":"1 large peeled and chopped"},{"name":"fennel bulb","measure":"1 trimmed and roughly chopped; reserve any fronds to garnish"},{"name":"smoky paprika","measure":"½ tsp"},{"name":"garlic","measure":"1 clove, peeled and sliced"},{"name":"fennel seeds","measure":"2 tsp lightly toasted and then gently crushed"},{"name":"red wine","measure":"100ml"},{"name":"chopped tomatoes","measure":"400g tinned"},{"name":"caster sugar","measure":"½ tsp"},{"name":"pitted black olives","measure":"50g cut in half lengthways"},{"name":"rigatoni","measure":"500g"},{"name":"pecorino","measure":"30g roughly crumbled into 0.5cm pieces"},{"name":"anchovy fillet","measure":"1  rinsed and patted dry"},{"name":"garlic","measure":"1 clove, peeled and crushed"},{"name":"olive oil","measure":"60ml"},{"name":"basil leaves","measure":"50g torn"}],"steps":["Heat a tablespoon of oil in a large saute pan for which you have a lid. Add the sausage pieces and fry on a medium-high heat for 10 minutes, stirring regularly, until golden-brown all over. Transfer the sausages to a plate, then add the onion and fennel to the hot pan and fry for 15 minutes, stirring once in a while, until soft and caramelised; if the pan goes a bit dry, add a teaspoon or so of extra oil. Stir in the paprika, garlic and half the fennel seeds, fry for two minutes more, then pour on the wine and boil for 30 seconds, to reduce by half. Add the tomatoes, sugar, 100ml water, the seared sausage and half a teaspoon of salt, cover and simmer for 30 minutes; remove the lid after 10 minutes, and cook until the sauce is thick and rich. Remove from the heat, stir through the olives and remaining fennel seeds and set aside until you’re ready to serve.","Bring a large pot of salted water to a boil, add the pasta and cook for 12-14 minutes (or according to the instructions on the packet), until al dente. Meanwhile, reheat the sauce. Drain the pasta, return it to the pot, stir in a tablespoon of oil, then divide between the bowls.","Put all the pesto ingredients except the basil in the small bowl of a food processor. Add a tablespoon of water and blitz to a rough paste. Add the basil, then blitz until just combined (the pesto has a much better texture if the basil is not overblended).","Spoon over the ragù and top with a spoonful of pesto. Finish with a sprinkling of chopped fennel fronds, if you have any, and serve at once."],"ingredient_names":["olive oil","italian fennel sausages","onion","fennel bulb","smoky paprika","garlic","fennel seeds","red wine","chopped tomatoes","caster sugar","pitted black olives","rigatoni","pecorino","anchovy fillet","garlic","olive oil","basil leaves"],"allergens":["dairy","fish","gluten"],"diet_flags":[]},{"source_id":"52784","title":"Smoky Lentil Chili with Squash","category":"Vegetarian","country":"United Kingdom","tags":["Pulse"],"image_url":"https://www.themealdb.com/images/media/meals/uwxqwy1483389553.jpg","youtube_url":"https://www.youtube.com/watch?v=pKmqawK2Tqs","source_url":"http://www.wholeheartedeats.com/2016/11/smoky-lentil-chili-squash/","ingredients":[{"name":"Olive Oil","measure":"1 tbls"},{"name":"Onion","measure":"1"},{"name":"Leek","measure":"1 chopped"},{"name":"Garlic","measure":"3 cloves"},{"name":"Cumin","measure":"4 tsp ground"},{"name":"Coriander","measure":"2 tsp ground"},{"name":"Smoked Paprika","measure":"1 tsp"},{"name":"Cinnamon","measure":"1/2 tsp"},{"name":"Chili Powder","measure":"1 tsp"},{"name":"Cocoa","measure":"1 tsp"},{"name":"Dried Oregano","measure":"1/2 tsp"},{"name":"Diced Tomatoes","measure":"1 can"},{"name":"Water","measure":"3 cups"},{"name":"Carrots","measure":"3 chopped"},{"name":"Brown Lentils","measure":"1 1/2 cups"},{"name":"Sea Salt","measure":"1 tsp"},{"name":"Squash","measure":"1 Small"},{"name":"Cashews","measure":"1 Cup"},{"name":"Apple Cider Vinegar","measure":"1 tsp"}],"steps":["Begin by roasting the squash. Slice it into thin crescents and drizzle with a little oil and sprinkle with sea salt. I added a fresh little sage I had in the fridge, but it’s unnecessary. Roast the squash a 205 C (400 F) for 20-30 minutes, flipping halfway through, until soft and golden. Let cool and chop into cubes.","Meanwhile, rinse the lentils and cover them with water. Bring them to the boil then turn down to a simmer and let cook (uncovered) for 20-30 minutes, or until tender. Drain and set aside.","While the lentils are cooking heat the 1 Tbsp. of oil on low in a medium pot. Add the onions and leeks and sauté for 5 or so minutes, or until they begin to soften. Add the garlic next along with the cumin and coriander, cooking for a few more minutes. Add the remaining spices – paprika, cinnamon, chilli, cocoa, Worcestershire sauce, salt, and oregano. Next add the can of tomatoes, the water or stock, and carrots. Let simmer, covered, for 20 minutes or until the veg is tender and the mixture has thickened up. You’ll need to check on the pot periodically for a stir and a top of of liquid if needed.","Add the lentils and chopped roasted squash. Let cook for 10 more minutes to heat through.","Serve with sliced jalapeno, lime wedges, cilantro, green onions, and cashew sour cream.","SIMPLE CASHEW SOUR CREAM","1 Cup Raw Unsalted Cashews","Pinch Sea Salt","1 tsp. Apple Cider Vinegar","Water","Bring some water to the boil, and use it to soak the cashews for at least four hours. Alternatively, you can use cold water and let the cashews soak overnight, but I’m forgetful/lazy, so often use the boil method which is much faster.","After the cashews have soaked, drain them and add to a high speed blender. Begin to puree, slowly adding about 1/2 cup fresh water, until a creamy consistency is reached. You may need to add less or more water to reach the desired consistency.","Add a pinch of sea salt and vinegar (or lemon juice)."],"ingredient_names":["olive oil","onion","leek","garlic","cumin","coriander","smoked paprika","cinnamon","chili powder","cocoa","dried oregano","diced tomatoes","water","carrots","brown lentils","sea salt","squash","cashews","apple cider vinegar"],"allergens":["tree_nuts"],"diet_flags":["pescatarian","vegan","vegetarian"]},{"source_id":"52785","title":"Dal fry","category":"Vegetarian","country":"India","tags":["Curry","Vegetarian","Cake"],"image_url":"https://www.themealdb.com/images/media/meals/wuxrtu1483564410.jpg","youtube_url":"https://www.youtube.com/watch?v=J4D855Q9-jg","source_url":"https://www.instagram.com/p/BO21bpYD3Fu","ingredients":[{"name":"Toor dal","measure":"1 cup"},{"name":"Water","measure":"2-1/2 cups"},{"name":"Salt","measure":"1 tsp"},{"name":"Turmeric","measure":"1/4 tsp"},{"name":"Ghee","measure":"3 tbs"},{"name":"Chopped tomatoes","measure":"1 cup"},{"name":"Cumin seeds","measure":"1/2 tsp"},{"name":"Mustard Seeds","measure":"1/2 tsp"},{"name":"Bay Leaf","measure":"2"},{"name":"Green Chilli","measure":"1 tbs chopped"},{"name":"Ginger","measure":"2 tsp shredded"},{"name":"Cilantro","measure":"2 tbs"},{"name":"Red Pepper","measure":"1/2 tsp"},{"name":"Salt","measure":"1/2 tsp"},{"name":"Sugar","measure":"1 tsp"},{"name":"Garam Masala","measure":"1/4 tsp"}],"steps":["Wash and soak toor dal in approx. 3 cups of water, for at least one hours. Dal will be double in volume after soaking. Drain the water.","Cook dal with 2-1/2 cups water and add salt, turmeric, on medium high heat, until soft in texture (approximately 30 mins) it should be like thick soup.","In a frying pan, heat the ghee. Add cumin seeds, and mustard seeds. After the seeds crack, add bay leaves, green chili, ginger and chili powder. Stir for a few seconds.","Add tomatoes, salt and sugar stir and cook until tomatoes are tender and mushy.","Add cilantro and garam masala cook for about one minute.","Pour the seasoning over dal mix it well and cook for another minute.","Serve with Naan."],"ingredient_names":["toor dal","water","salt","turmeric","ghee","chopped tomatoes","cumin seeds","mustard seeds","bay leaf","green chilli","ginger","cilantro","red pepper","salt","sugar","garam masala"],"allergens":["dairy"],"diet_flags":["pescatarian","vegetarian"]},{"source_id":"52794","title":"Vegan Chocolate Cake","category":"Vegan","country":"United States","tags":["Vegan","Chocolate","Cake"],"image_url":"https://www.themealdb.com/images/media/meals/qxutws1486978099.jpg","youtube_url":"https://www.youtube.com/watch?v=C3pAgB7pync","source_url":null,"ingredients":[{"name":"Self-raising Flour","measure":"1 1/4 cup"},{"name":"coco sugar","measure":"1/2 cup"},{"name":"cacao","measure":"1/3 cup raw"},{"name":"baking powder","measure":"1 tsp"},{"name":"flax eggs","measure":"2"},{"name":"almond milk","measure":"1/2 cup"},{"name":"vanilla","measure":"1 tsp"},{"name":"water","measure":"1/2 cup boiling"}],"steps":["Simply mix all dry ingredients with wet ingredients and blend altogether. Bake for 45 min on 180 degrees. Decorate with some melted vegan chocolate"],"ingredient_names":["self-raising flour","coco sugar","cacao","baking powder","flax eggs","almond milk","vanilla","water"],"allergens":["eggs","gluten","tree_nuts"],"diet_flags":["pescatarian","vegetarian"]},{"source_id":"52795","title":"Chicken Handi","category":"Chicken","country":"India","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/wyxwsp1486979827.jpg","youtube_url":"https://www.youtube.com/watch?v=IO0issT0Rmc","source_url":null,"ingredients":[{"name":"Chicken","measure":"1.2 kg"},{"name":"Onion","measure":"5 thinly sliced"},{"name":"Tomatoes","measure":"2 finely chopped"},{"name":"Garlic","measure":"8 cloves chopped"},{"name":"Ginger paste","measure":"1 tbsp"},{"name":"Vegetable oil","measure":"¼ cup"},{"name":"Cumin seeds","measure":"2 tsp"},{"name":"Coriander seeds","measure":"3 tsp"},{"name":"Turmeric powder","measure":"1 tsp"},{"name":"Chilli powder","measure":"1 tsp"},{"name":"Green chilli","measure":"2"},{"name":"Yogurt","measure":"1 cup"},{"name":"Cream","measure":"¾ cup"},{"name":"fenugreek","measure":"3 tsp Dried"},{"name":"Garam masala","measure":"1 tsp"},{"name":"Salt","measure":"To taste"}],"steps":["Take a large pot or wok, big enough to cook all the chicken, and heat the oil in it. Once the oil is hot, add sliced onion and fry them until deep golden brown. Then take them out on a plate and set aside.","To the same pot, add the chopped garlic and sauté for a minute. Then add the chopped tomatoes and cook until tomatoes turn soft. This would take about 5 minutes.","Then return the fried onion to the pot and stir. Add ginger paste and sauté well.","Now add the cumin seeds, half of the coriander seeds and chopped green chillies. Give them a quick stir.","Next goes in the spices – turmeric powder and red chilli powder. Sauté the spices well for couple of minutes.","Add the chicken pieces to the wok, season it with salt to taste and cook the chicken covered on medium-low heat until the chicken is almost cooked through. This would take about 15 minutes. Slowly sautéing the chicken will enhance the flavor, so do not expedite this step by putting it on high heat.","When the oil separates from the spices, add the beaten yogurt keeping the heat on lowest so that the yogurt doesn’t split. Sprinkle the remaining coriander seeds and add half of the dried fenugreek leaves. Mix well.","Finally add the cream and give a final mix to combine everything well.","Sprinkle the remaining kasuri methi and garam masala and serve the chicken handi hot with naan or rotis. Enjoy!"],"ingredient_names":["chicken","onion","tomatoes","garlic","ginger paste","vegetable oil","cumin seeds","coriander seeds","turmeric powder","chilli powder","green chilli","yogurt","cream","fenugreek","garam masala","salt"],"allergens":["dairy"],"diet_flags":[]},{"source_id":"52796","title":"Chicken Alfredo Primavera","category":"Chicken","country":"Italy","tags":["Pasta","Meat","Dairy"],"image_url":"https://www.themealdb.com/images/media/meals/syqypv1486981727.jpg","youtube_url":"https://www.youtube.com/watch?v=qCIbq8HywpQ","source_url":null,"ingredients":[{"name":"Butter","measure":"2 tablespoons"},{"name":"Olive Oil","measure":"3 tablespoons"},{"name":"Chicken","measure":"5 boneless"},{"name":"Salt","measure":"1 teaspoon"},{"name":"Squash","measure":"1 cut into 1/2-inch cubes"},{"name":"Broccoli","measure":"1 Head chopped"},{"name":"mushrooms","measure":"8-ounce sliced"},{"name":"Pepper","measure":"1 red"},{"name":"onion","measure":"1 chopped"},{"name":"garlic","measure":"3 cloves"},{"name":"red pepper flakes","measure":"1/2 teaspoon"},{"name":"white wine","measure":"1/2 cup"},{"name":"milk","measure":"1/2 cup"},{"name":"heavy cream","measure":"1/2 cup"},{"name":"Parmesan cheese","measure":"1 cup grated"},{"name":"bowtie pasta","measure":"16 ounces"},{"name":"Salt","measure":"pinch"},{"name":"Pepper","measure":"pinch"},{"name":"Parsley","measure":"chopped"}],"steps":["Heat 1 tablespoon of butter and 2 tablespoons of olive oil in a large skillet over medium-high heat.","Season both sides of each chicken breast with seasoned salt and a pinch of pepper.","Add the chicken to the skillet and cook for 5-7 minutes on each side, or until cooked through.","While the chicken is cooking, bring a large pot of water to a boil.","Season the boiling water with a few generous pinches of kosher salt.","Add the pasta and give it a stir.","Cook, stirring occasionally, until al dente, about 12 minutes.","Reserve 1/2 cup of  pasta water before draining the pasta.","Remove the chicken from the pan and transfer it to a cutting board; allow it to rest.","Turn the heat down to medium and dd the remaining 1 tablespoon of butter and olive oil to the same pan you used to cook the chicken.","Add the veggies (minus the garlic) and red pepper flakes to the pan and stir to coat with the oil and butter (refrain from seasoning with salt until the veggies are finished browning).","Cook, stirring often, until the veggies are tender, about 5 minutes.","Add the garlic and a generous pinch of salt and pepper to the pan and cook for 1 minute.","Deglaze the pan with the white wine.","Continue to cook until the wine has reduced by half, about 3 minutes.","Stir in the milk, heavy cream, and reserved pasta water.","Bring the mixture to a gentle boil and allow to simmer and reduce for 2-3 minutes.","Turn off the heat and add the Parmesan cheese and cooked pasta.","Season with salt and pepper to taste.","Garnish with Parmesan cheese and chopped parsley, if desired."],"ingredient_names":["butter","olive oil","chicken","salt","squash","broccoli","mushrooms","pepper","onion","garlic","red pepper flakes","white wine","milk","heavy cream","parmesan cheese","bowtie pasta","salt","pepper","parsley"],"allergens":["dairy","gluten"],"diet_flags":[]},{"source_id":"52797","title":"Spicy North African Potato Salad","category":"Vegetarian","country":"Morocco","tags":["Vegetarian","Spicy"],"image_url":"https://www.themealdb.com/images/media/meals/urtwux1486983078.jpg","youtube_url":"https://www.youtube.com/watch?v=zxBzwJvTK4g","source_url":null,"ingredients":[{"name":"Small Potatoes","measure":"650g/1lb 8 oz"},{"name":"Harissa Spice","measure":"1 tsp"},{"name":"olive oil","measure":"2 tsp"},{"name":"Lemon","measure":"juice of half"},{"name":"Spring onions","measure":"4"},{"name":"Rocket","measure":"150g/6oz"},{"name":"Feta","measure":"80g/3oz"},{"name":"Mint","measure":"20 chopped"},{"name":"Pine nuts","measure":"2 tablespoons"},{"name":"Salt","measure":"Pinch"},{"name":"Pepper","measure":"Pinch"}],"steps":["Cook potatoes - place potatoes in a pot of cold water, and bring to the boil. Boil 20 minutes, or until potatoes are tender. You know they are cooked when you can stick a knife in them and the knife goes straight through.","Combine harissa spice, olive oil, salt and pepper and lemon juice in a small bowl and whisk until combined.","Once potatoes are cooked, drain water and roughly chop potatoes in half.","Add harissa mix and spring onions/green onions to potatoes and stir.","In a large salad bowl, lay out arugula/rocket.","Top with potato mix and toss.","Add fetta, mint and sprinkle over pine nuts.","Adjust salt and pepper to taste."],"ingredient_names":["small potatoes","harissa spice","olive oil","lemon","spring onions","rocket","feta","mint","pine nuts","salt","pepper"],"allergens":["dairy","tree_nuts"],"diet_flags":["pescatarian","vegetarian"]},{"source_id":"52802","title":"Fish pie","category":"Seafood","country":"United Kingdom","tags":["Fish","Pie","Breakfast","Baking"],"image_url":"https://www.themealdb.com/images/media/meals/ysxwuq1487323065.jpg","youtube_url":"https://www.youtube.com/watch?v=2sX4fCgg-UI","source_url":null,"ingredients":[{"name":"Floury Potatoes","measure":"900g"},{"name":"Olive Oil","measure":"2 tbsp"},{"name":"Semi-skimmed Milk","measure":"600ml"},{"name":"White Fish Fillets","measure":"800g"},{"name":"Plain flour","measure":"1 tbsp"},{"name":"Nutmeg","measure":"Grating"},{"name":"Double Cream","measure":"3 tbsp"},{"name":"Jerusalem Artichokes","measure":"200g"},{"name":"Leek","measure":"1 finely sliced"},{"name":"Prawns","measure":"200g peeled raw"},{"name":"Parsley","measure":"Large handful"},{"name":"Dill","measure":"Handful"},{"name":"Lemon","measure":"Grated zest of 1"},{"name":"Gruyère","measure":"25g grated"},{"name":"Lemon","measure":"Juice of 1"}],"steps":["Put the potatoes in a large pan of cold salted water and bring to the boil. Lower the heat, cover, then simmer gently for 15 minutes until tender. Drain, then return to the pan over a low heat for 30 seconds to drive off any excess water. Mash with 1 tbsp olive oil, then season.","Meanwhile put the milk in a large sauté pan, add the fish and bring to the boil. Remove from the heat, cover and stand for 3 minutes. Remove the fish (reserving the milk) and pat dry with kitchen paper, then gently flake into an ovenproof dish, discarding the skin and any bones.","Heat the remaining oil in a pan, stir in the flour and cook for 30 seconds. Gradually stir in 200-250ml of the reserved milk (discard the rest). Grate in nutmeg, season, then bubble until thick. Stir in the cream.","Preheat the oven to 190°C/fan170°C/gas 5. Grate the artichokes and add to the dish with the leek, prawns and herbs. Stir the lemon zest and juice into the sauce, then pour over. Mix gently with a wooden spoon.","Spoon the mash onto the fish mixture, then use a fork to make peaks, which will crisp and brown as it cooks. Sprinkle over the cheese, then bake for 35-40 minutes until golden and bubbling. Serve with wilted greens."],"ingredient_names":["floury potatoes","olive oil","semi-skimmed milk","white fish fillets","plain flour","nutmeg","double cream","jerusalem artichokes","leek","prawns","parsley","dill","lemon","gruyère","lemon"],"allergens":["dairy","fish","gluten","shellfish"],"diet_flags":["pescatarian"]},{"source_id":"52803","title":"Beef Wellington","category":"Beef","country":"United Kingdom","tags":["Meat","Stew"],"image_url":"https://www.themealdb.com/images/media/meals/vvpprx1487325699.jpg","youtube_url":"https://www.youtube.com/watch?v=FS8u1RBdf6I","source_url":"http://www.goodtoknow.co.uk/recipes/164868/Gordon-Ramsay-s-beef-Wellington","ingredients":[{"name":"mushrooms","measure":"400g"},{"name":"English Mustard","measure":"1-2tbsp"},{"name":"Olive Oil","measure":"Dash"},{"name":"Beef Fillet","measure":"750g piece"},{"name":"Parma ham","measure":"6-8 slices"},{"name":"Puff Pastry","measure":"500g"},{"name":"Flour","measure":"Dusting"},{"name":"Egg Yolks","measure":"2 Beaten"}],"steps":["Put the mushrooms into a food processor with some seasoning and pulse to a rough paste. Scrape the paste into a pan and cook over a high heat for about 10 mins, tossing frequently, to cook out the moisture from the mushrooms. Spread out on a plate to cool.","Heat in a frying pan and add a little olive oil. Season the beef and sear in the hot pan for 30 secs only on each side. (You don't want to cook it at this stage, just colour it). Remove the beef from the pan and leave to cool, then brush all over with the mustard.","Lay a sheet of cling film on a work surface and arrange the Parma ham slices on it, in slightly overlapping rows. With a palette knife, spread the mushroom paste over the ham, then place the seared beef fillet in the middle. Keeping a tight hold of the cling film from the edge, neatly roll the Parma ham and mushrooms around the beef to form a tight barrel shape. Twist the ends of the cling film to secure. Chill for 15-20 mins to allow the beef to set and keep its shape.","Roll out the puff pastry on a floured surface to a large rectangle, the thickness of a £1 coin. Remove the cling film from the beef, then lay in the centre. Brush the surrounding pastry with egg yolk. Fold the ends over, the wrap the pastry around the beef, cutting off any excess. Turn over, so the seam is underneath, and place on a baking sheet. Brush over all the pastry with egg and chill for about 15 mins to let the pastry rest.","Heat the oven to 200C, 400F, gas 6.","Lightly score the pastry at 1cm intervals and glaze again with beaten egg yolk. Bake for 20 minutes, then lower the oven setting to 180C, 350F, gas 4 and cook for another 15 mins. Allow to rest for 10-15 mins before slicing and serving with the side dishes of your choice. The beef should still be pink in the centre when you serve it."],"ingredient_names":["mushrooms","english mustard","olive oil","beef fillet","parma ham","puff pastry","flour","egg yolks"],"allergens":["eggs","gluten"],"diet_flags":[]},{"source_id":"52805","title":"Lamb Biryani","category":"Lamb","country":"India","tags":["Curry","Meat"],"image_url":"https://www.themealdb.com/images/media/meals/xrttsx1487339558.jpg","youtube_url":"https://www.youtube.com/watch?v=r7SYVSG5nxo","source_url":"http://www.relishthebite.com/restaurant-style-lamb-biryani/","ingredients":[{"name":"Cashew nuts","measure":"12"},{"name":"Khus khus","measure":"½ tbsp"},{"name":"Cumin seeds","measure":"½ tbsp"},{"name":"Onions","measure":"3 sliced thinly"},{"name":"Ginger garlic paste","measure":"2 tsp"},{"name":"Garlic","measure":"4 whole"},{"name":"Mint","measure":"Leaves"},{"name":"Cilantro","measure":"Leaves"},{"name":"Saffron","measure":"½ tsp dissolved in ½ cup warm milk"},{"name":"Ghee","measure":"2 tbsp"},{"name":"Basmati rice","measure":"2 Cups"},{"name":"Full fat yogurt","measure":"½ cup"},{"name":"Cumin Seeds","measure":"1 tbsp"},{"name":"Bay leaf","measure":"½"},{"name":"Cinnamon","measure":"1 thin piece"},{"name":"Cloves","measure":"3"},{"name":"Cardamom","measure":"2"},{"name":"Lamb","measure":"1 lb"},{"name":"Red Chilli powder","measure":"1 tsp"},{"name":"Biryani masala","measure":"1 tbsp"}],"steps":["Grind the cashew, poppy seeds and cumin seeds into a smooth paste, using as little water as possible. Set aside.","Deep fry the sliced onions when it is hot. Don’t overcrowd the oil. When the onions turn light brown, remove from oil and drain on paper towel. The fried onion will crisp up as it drains. Also fry the cashewnuts till golden brown. Set aside.","Wash the rice and soak in water for twenty minutes.","Meanwhile, take a big wide pan, add oil in medium heat, add the sliced onions, add the blended paste, to it add the green chillies, ginger garlic paste and garlic and fry for a minute.","Then add the tomatoes and sauté them well till they are cooked and not mushy.","Then to it add the red chilli powder, biryani powder, mint, coriander leaves and sauté them well.","Add the yogurt and mix well. I always move the skillet away from the heat when adding yogurt which prevents it from curdling.","Now after returning the skillet back to the stove, add the washed lamb and salt and ½ cup water and mix well. Cook for 1 hour and cook it covered in medium low heat or put it in a pressure cooker for 6 whistles. If the water is not drained totally, heat it by keeping it open.","Take another big pan, add thrice the cup of rice you use, and boil it. When it is boiling high, add the rice, salt and jeera and mix well. After 7 minutes exact or when the rice is 80% done. Switch off and drain the rice.","Now, the layering starts. To the lamb, pat and level it. Add the drained hot rice on the top of it. Garnish with fried onions, ghee, mint, coriander leaves and saffron dissolved in milk.","Cover the dish and bake in a 350f oven for 15 minutes or till the cooked but not mushy. Or cook in the stove medium heat for 12 minutes and lowest heat for 5 minutes. And switch off. Mix and serve hot!","Notes","If you are cooking in oven, do make sure to cook in a big oven safe pan and cover it tight and then keep in oven for the final step.","You can skip biryani masala if you don’t have and add just garam masala (1 tsp and red chilli powder – 3 tsp instead of 1 tsp)","If it is spicy in the end, squeeze some lemon, it will reduce the heat and enhance the flavors also."],"ingredient_names":["cashew nuts","khus khus","cumin seeds","onions","ginger garlic paste","garlic","mint","cilantro","saffron","ghee","basmati rice","full fat yogurt","cumin seeds","bay leaf","cinnamon","cloves","cardamom","lamb","red chilli powder","biryani masala"],"allergens":["dairy","tree_nuts"],"diet_flags":[]},{"source_id":"52806","title":"Tandoori chicken","category":"Chicken","country":"India","tags":["Spicy","Meat"],"image_url":"https://www.themealdb.com/images/media/meals/qptpvt1487339892.jpg","youtube_url":"https://www.youtube.com/watch?v=-CKvt1KNU74","source_url":"http://www.bbcgoodfood.com/recipes/1660651/tandoori-chicken","ingredients":[{"name":"lemons","measure":"2 Juice"},{"name":"paprika","measure":"4 tsp"},{"name":"red onions","measure":"2 finely chopped"},{"name":"chicken thighs","measure":"16 skinnless"},{"name":"vegetable oil","measure":"For brushing"},{"name":"Greek yogurt","measure":"300ml"},{"name":"ginger","measure":"large piece"},{"name":"garlic clove","measure":"4"},{"name":"garam masala","measure":"¾ tsp"},{"name":"ground cumin","measure":"¾ tsp"},{"name":"chilli powder","measure":"½ tsp"},{"name":"turmeric","measure":"¼ tsp"}],"steps":["Mix the lemon juice with the paprika and red onions in a large shallow dish. Slash each chicken thigh three times, then turn them in the juice and set aside for 10 mins.","Mix all of the marinade ingredients together and pour over the chicken. Give everything a good mix, then cover and chill for at least 1 hr. This can be done up to a day in advance.","Heat the grill. Lift the chicken pieces onto a rack over a baking tray. Brush over a little oil and grill for 8 mins on each side or until lightly charred and completely cooked through."],"ingredient_names":["lemons","paprika","red onions","chicken thighs","vegetable oil","greek yogurt","ginger","garlic clove","garam masala","ground cumin","chilli powder","turmeric"],"allergens":["dairy"],"diet_flags":[]},{"source_id":"52807","title":"Baingan Bharta","category":"Vegetarian","country":"India","tags":["Spicy","Bun","Calorific"],"image_url":"https://www.themealdb.com/images/media/meals/urtpqw1487341253.jpg","youtube_url":"https://www.youtube.com/watch?v=-84Zz2EP4h4","source_url":"http://www.vegrecipesofindia.com/baingan-bharta-recipe-punjabi-baingan-bharta-recipe/","ingredients":[{"name":"Aubergine","measure":"1 large"},{"name":"Onion","measure":"½ cup"},{"name":"Tomatoes","measure":"1 cup"},{"name":"Garlic","measure":"6 cloves"},{"name":"Green Chilli","measure":"1"},{"name":"Red Chilli Powder","measure":"¼ teaspoon"},{"name":"Oil","measure":"1.5 tablespoon"},{"name":"Coriander Leaves","measure":"1 tablespoon chopped"},{"name":"salt","measure":"as required"}],"steps":["Rinse the baingan (eggplant or aubergine) in water. Pat dry with a kitchen napkin. Apply some oil all over and","keep it for roasting on an open flame. You can also grill the baingan or roast in the oven. But then you won't get","the smoky flavor of the baingan. Keep the eggplant turning after a 2 to 3 minutes on the flame, so that its evenly","cooked. You could also embed some garlic cloves in the baingan and then roast it.","Roast the aubergine till its completely cooked and tender. With a knife check the doneness. The knife should slid","easily in aubergines without any resistance. Remove the baingan and immerse in a bowl of water till it cools","down.","You can also do the dhungar technique of infusing charcoal smoky flavor in the baingan. This is an optional step.","Use natural charcoal for this method. Heat a small piece of charcoal on flame till it becomes smoking hot and red.","Make small cuts on the baingan with a knife. Place the red hot charcoal in the same plate where the roasted","aubergine is kept. Add a few drops of oil on the charcoal. The charcoal would begin to smoke.","As soon as smoke begins to release from the charcoal, cover the entire plate tightly with a large bowl. Allow the","charcoal smoke to get infused for 1 to 2 minutes. The more you do, the more smoky the baingan bharta will","become. I just keep for a minute. Alternatively, you can also do this dhungar method once the baingan bharta is","cooked, just like the way we do for Dal Tadka.","Peel the skin from the roasted and smoked eggplant.","Chop the cooked eggplant finely or you can even mash it.","In a kadai or pan, heat oil. Then add finely chopped onions and garlic.","Saute the onions till translucent. Don't brown them.","Add chopped green chilies and saute for a minute.","Add the chopped tomatoes and mix it well.","Bhuno (saute) the tomatoes till the oil starts separating from the mixture.","Now add the red chili powder. Stir and mix well.","Add the chopped cooked baingan.","Stir and mix the chopped baingan very well with the onion­tomato masala mixture.","Season with salt. Stir and saute for some more 4 to 5 minutes more.","Finally stir in the coriander leaves with the baingan bharta or garnish it with them. Serve Baingan Bharta with","phulkas, rotis or chapatis. It goes well even with bread, toasted or grilled bread and plain rice or jeera rice."],"ingredient_names":["aubergine","onion","tomatoes","garlic","green chilli","red chilli powder","oil","coriander leaves","salt"],"allergens":[],"diet_flags":["pescatarian","vegan","vegetarian"]},{"source_id":"52808","title":"Lamb Rogan josh","category":"Lamb","country":"India","tags":["Curry","Spicy","Alcoholic"],"image_url":"https://www.themealdb.com/images/media/meals/vvstvq1487342592.jpg","youtube_url":"https://www.youtube.com/watch?v=NZVo32n7iS8","source_url":"http://www.bbcgoodfood.com/recipes/9643/onepan-rogan-josh","ingredients":[{"name":"Onion","measure":"2 quartered"},{"name":"Sunflower Oil","measure":"4 tbsp"},{"name":"Garlic","measure":"4 cloves"},{"name":"Ginger","measure":"Thumb sized peeled and very finely grated"},{"name":"Madras Paste","measure":"2 tbsp"},{"name":"Paprika","measure":"2 tsp"},{"name":"cinnamon stick","measure":"1"},{"name":"Cardamom","measure":"6 bashed to break shells"},{"name":"Cloves","measure":"4"},{"name":"Bay Leaf","measure":"2"},{"name":"Tomato Purée","measure":"1 tbsp"},{"name":"Lamb","measure":"1kg cubed"},{"name":"Greek yogurt","measure":"150ml"},{"name":"Coriander","measure":"Garnish chopped"}],"steps":["Put the onions in a food processor and whizz until very finely chopped. Heat the oil in a large heavy-based pan, then fry the onion with the lid on, stirring every now and then, until it is really golden and soft. Add the garlic and ginger, then fry for 5 mins more.","Tip the curry paste, all the spices and the bay leaves into the pan, with the tomato purée. Stir well over the heat for about 30 secs, then add the meat and 300ml water. Stir to mix, turn down the heat, then add the yogurt.","Cover the pan, then gently simmer for 40-60 mins until the meat is tender and the sauce nice and thick. Serve scattered with coriander, with plain basmati or pilau rice."],"ingredient_names":["onion","sunflower oil","garlic","ginger","madras paste","paprika","cinnamon stick","cardamom","cloves","bay leaf","tomato purée","lamb","greek yogurt","coriander"],"allergens":["dairy"],"diet_flags":[]},{"source_id":"52809","title":"Recheado Masala Fish","category":"Seafood","country":"India","tags":["Fish","Spicy"],"image_url":"https://www.themealdb.com/images/media/meals/uwxusv1487344500.jpg","youtube_url":"https://www.youtube.com/watch?v=FXtCris37nE","source_url":"http://www.flavorsofmumbai.com/fish-recheado-masala-recipe/","ingredients":[{"name":"Mackerel","measure":"4"},{"name":"Red Chilli","measure":"18 dried"},{"name":"Ginger","measure":"1 inch"},{"name":"Garlic","measure":"8 cloves"},{"name":"Pepper","measure":"1.5 tsp"},{"name":"Cumin","measure":"1 tsp"},{"name":"Turmeric","measure":"½ tsp"},{"name":"Cinnamon stick","measure":""},{"name":"Cloves","measure":"4"},{"name":"Cardamom","measure":"2"},{"name":"Sugar","measure":"1 tbsp"},{"name":"Tamarind ball","measure":"2 marble sized"},{"name":"Vinegar","measure":"2.5 tbsp"},{"name":"Oil","measure":"for frying"}],"steps":["Soak all the spices, ginger, garlic, tamarind pulp and kashmiri chilies except oil in vinegar.","Add sugar and salt.","Also add turmeric powder.","Combine all nicely and marinate for 35-40 mins.","Grind the mixture until soft and smooth. Add more vinegar if required but ensure the paste has to be thick so add vinegar accordingly. If the masala paste is thin then it would not stick to the fish.","Rinse the fish slit from the center and give some incision from the top. You could see the fish below for clarity.","Now stuff the paste into the center and into the incision. Coat the entire fish with this paste. Marinate the fish for 30 mins.","Place oil in a shallow pan, once oil is quite hot shallow fry the stuffed mackerels.","Fry until golden brown from both sides","Serve the recheado mackerels hot with salad, lime wedges, rice and curry.","Notes","Ensure the masala paste is thick else the result won't be good.","If you aren't able to find kashmiri chilies then use bedgi chilies or kashmiri red chili powder.","You could use white vinegar or coconut vinegar.","Any left over paste could be stored in the fridge for future use.","Cinnamon could be avoided as it's a strong spice used generally for meat or chicken."],"ingredient_names":["mackerel","red chilli","ginger","garlic","pepper","cumin","turmeric","cinnamon stick","cloves","cardamom","sugar","tamarind ball","vinegar","oil"],"allergens":["fish"],"diet_flags":["pescatarian"]},{"source_id":"52811","title":"Ribollita","category":"Vegetarian","country":"Italy","tags":["Vegetarian"],"image_url":"https://www.themealdb.com/images/media/meals/xrrwpx1487347049.jpg","youtube_url":"https://www.youtube.com/watch?v=BiQUYTBb6eQ","source_url":"https://cooking.nytimes.com/recipes/1016052-ribollita","ingredients":[{"name":"Olive Oil","measure":"5 tablespoons"},{"name":"Onion","measure":"1 chopped"},{"name":"Carrots","measure":"1 chopped"},{"name":"Celery","measure":"1 stalk chopped"},{"name":"Garlic","measure":"1 tablespoon minced"},{"name":"Cannellini Beans","measure":"2 cups"},{"name":"Canned tomatoes","measure":"1"},{"name":"Water","measure":"4 cups"},{"name":"Rosemary","measure":"1 fresh sprig"},{"name":"Thyme","measure":"1 fresh sprig"},{"name":"Kale","measure":"1 pound chopped"},{"name":"Wholegrain Bread","measure":"4 thick slices"},{"name":"Red Onions","measure":"1 thinly sliced"},{"name":"Parmesan","measure":"½ cup freshly grated"}],"steps":["Put 2 tablespoons of the oil in a large pot over medium heat. When it’s hot, add onion, carrot, celery and garlic; sprinkle with salt and pepper and cook, stirring occasionally, until vegetables are soft, 5 to 10 minutes.","Heat the oven to 500 degrees. Drain the beans; if they’re canned, rinse them as well. Add them to the pot along with tomatoes and their juices and stock, rosemary and thyme. Bring to a boil, then reduce heat so the soup bubbles steadily; cover and cook, stirring once or twice to break up the tomatoes, until the flavors meld, 15 to 20 minutes.","Fish out and discard rosemary and thyme stems, if you like, and stir in kale. Taste and adjust seasoning. Lay bread slices on top of the stew so they cover the top and overlap as little as possible. Scatter red onion slices over the top, drizzle with the remaining 3 tablespoons oil and sprinkle with Parmesan.","Put the pot in the oven and bake until the bread, onions and cheese are browned and crisp, 10 to 15 minutes. (If your pot fits under the broiler, you can also brown the top there.) Divide the soup and bread among 4 bowls and serve."],"ingredient_names":["olive oil","onion","carrots","celery","garlic","cannellini beans","canned tomatoes","water","rosemary","thyme","kale","wholegrain bread","red onions","parmesan"],"allergens":["dairy","gluten"],"diet_flags":["pescatarian","vegetarian"]},{"source_id":"52812","title":"Beef Brisket Pot Roast","category":"Beef","country":"United States","tags":["Meat"],"image_url":"https://www.themealdb.com/images/media/meals/ursuup1487348423.jpg","youtube_url":"https://www.youtube.com/watch?v=gh48wM6bPWQ","source_url":"http://www.simplyrecipes.com/recipes/beef_brisket_pot_roast/","ingredients":[{"name":"Beef Brisket","measure":"4-5 pound"},{"name":"Salt","measure":"Dash"},{"name":"Onion","measure":"3"},{"name":"Garlic","measure":"5 cloves"},{"name":"Thyme","measure":"1 Sprig"},{"name":"Rosemary","measure":"1 sprig"},{"name":"Bay Leaves","measure":"4"},{"name":"beef stock","measure":"2 cups"},{"name":"Carrots","measure":"3 Large"},{"name":"Mustard","measure":"1 Tbsp"},{"name":"Potatoes","measure":"4 Mashed"}],"steps":["1 Prepare the brisket for cooking: On one side of the brisket there should be a layer of fat, which you want. If there are any large chunks of fat, cut them off and discard them. Large pieces of fat will not be able to render out completely.","Using a sharp knife, score the fat in parallel lines, about 3/4-inch apart. Slice through the fat, not the beef. Repeat in the opposite direction to make a cross-hatch pattern.","Salt the brisket well and let it sit at room temperature for 30 minutes.","2 Sear the brisket: You'll need an oven-proof, thick-bottomed pot with a cover, or Dutch oven, that is just wide enough to hold the brisket roast with a little room for the onions.","Pat the brisket dry and place it, fatty side down, into the pot and place it on medium high heat. Cook for 5-8 minutes, lightly sizzling, until the fat side is nicely browned. (If the roast seems to be cooking too fast, turn the heat down to medium. You want a steady sizzle, not a raging sear.)","Turn the brisket over and cook for a few minutes more to brown the other side.","3 Sauté the onions and garlic: When the brisket has browned, remove it from the pot and set aside. There should be a couple tablespoons of fat rendered in the pot, if not, add some olive oil.","Add the chopped onions and increase the heat to high. Sprinkle a little salt on the onions. Sauté, stirring often, until the onions are lightly browned, 5-8 minutes. Stir in the garlic and cook 1-2 more minutes.","4 Return brisket to pot, add herbs, stock, bring to simmer, cover, cook in oven: Preheat the oven to 300°F. Use kitchen twine to tie together the bay leaves, rosemary and thyme.","Move the onions and garlic to the sides of the pot and nestle the brisket inside. Add the beef stock and the tied-up herbs. Bring the stock to a boil on the stovetop.","Cover the pot, place the pot in the 300°F oven and cook for 3 hours. Carefully flip the brisket every hour so it cooks evenly.","5 Add carrots, continue to cook: After 3 hours, add the carrots. Cover the pot and cook for 1 hour more, or until the carrots are cooked through and the brisket is falling-apart tender.","6 Remove brisket to cutting board, tent with foil: When the brisket is falling-apart tender, take the pot out of the oven and remove the brisket to a cutting board. Cover it with foil. Pull out and discard the herbs.","7 Make sauce (optional): At this point you have two options. You can serve as is, or you can make a sauce with the drippings and some of the onions. If you serve as is, skip this step.","To make a sauce, remove the carrots and half of the onions, set aside and cover them with foil. Pour the ingredients that are remaining into the pot into a blender, and purée until smooth. If you want, add 1 tablespoon of mustard to the mix. Put into a small pot and keep warm.","8 Slice the meat across the grain: Notice the lines of the muscle fibers of the roast. This is the \"grain\" of the meat. Slice the meat perpendicular to these lines, or across the grain (cutting this way further tenderizes the meat), in 1/4-inch to 1/2-inch slices.","Serve with the onions, carrots and gravy. Serve with mashed, roasted or boiled potatoes, egg noodles or polenta."],"ingredient_names":["beef brisket","salt","onion","garlic","thyme","rosemary","bay leaves","beef stock","carrots","mustard","potatoes"],"allergens":[],"diet_flags":[]},{"source_id":"52813","title":"Kentucky Fried Chicken","category":"Chicken","country":"United States","tags":["Meat","Spicy"],"image_url":"https://www.themealdb.com/images/media/meals/40r49m1763197022.jpg","youtube_url":"https://www.youtube.com/watch?v=PTUxCvCz8Bc","source_url":"http://www.tablespoon.com/recipes/copycat-kfc-original-style-chicken/97c93d14-9d8c-4bc7-96dc-1e0b37e4fcaa","ingredients":[{"name":"Chicken","measure":"1 whole"},{"name":"Oil","measure":"2 quarts neutral frying"},{"name":"Egg White","measure":"1"},{"name":"Flour","measure":"1 1/2 cups"},{"name":"Brown Sugar","measure":"1 tablespoon"},{"name":"Salt","measure":"1 tablespoon"},{"name":"paprika","measure":"1 tablespoon"},{"name":"onion salt","measure":"2 teaspoons"},{"name":"chili powder","measure":"1 teaspoon"},{"name":"black pepper","measure":"1 teaspoon"},{"name":"celery salt","measure":"1/2 teaspoon"},{"name":"sage","measure":"1/2 teaspoon"},{"name":"garlic powder","measure":"1/2 teaspoon"},{"name":"allspice","measure":"1/2 teaspoon"},{"name":"oregano","measure":"1/2 teaspoon"},{"name":"basil","measure":"1/2 teaspoon"},{"name":"marjoram","measure":"1/2 teaspoon"}],"steps":["Preheat fryer to 350°F. Thoroughly mix together all the spice mix ingredients.","Combine spice mix with flour, brown sugar and salt.","Dip chicken pieces in egg white to lightly coat them, then transfer to flour mixture. Turn a few times and make sure the flour mix is really stuck to the chicken. Repeat with all the chicken pieces.","Let chicken pieces rest for 5 minutes so crust has a chance to dry a bit.","Fry chicken in batches. Breasts and wings should take 12-14 minutes, and legs and thighs will need a few more minutes. Chicken pieces are done when a meat thermometer inserted into the thickest part reads 165°F.","Let chicken drain on a few paper towels when it comes out of the fryer. Serve hot."],"ingredient_names":["chicken","oil","egg white","flour","brown sugar","salt","paprika","onion salt","chili powder","black pepper","celery salt","sage","garlic powder","allspice","oregano","basil","marjoram"],"allergens":["eggs","gluten"],"diet_flags":[]},{"source_id":"52814","title":"Thai Green Curry","category":"Chicken","country":"Thailand","tags":["Curry","Mild"],"image_url":"https://www.themealdb.com/images/media/meals/sstssx1487349585.jpg","youtube_url":"https://www.youtube.com/watch?v=LIbKVpBQKJI","source_url":"http://www.bbcgoodfood.com/recipes/3235/thai-green-chicken-curry","ingredients":[{"name":"Potatoes","measure":"225g new"},{"name":"green beans","measure":"100g"},{"name":"sunflower oil","measure":"1 tbsp"},{"name":"garlic","measure":"1 clove"},{"name":"Thai green curry paste","measure":"4 tsp"},{"name":"coconut milk","measure":"400ml"},{"name":"Thai fish sauce","measure":"2 tsp"},{"name":"Sugar","measure":"1 tsp"},{"name":"Chicken","measure":"450g boneless"},{"name":"lime","measure":"2 fresh kaffir leaves"},{"name":"basil","measure":"handfull"},{"name":"Rice","measure":"Boiled"}],"steps":["Put the potatoes in a pan of boiling water and cook for 5 minutes. Throw in the beans and cook for a further 3 minutes, by which time both should be just tender but not too soft. Drain and put to one side.","In a wok or large frying pan, heat the oil until very hot, then drop in the garlic and cook until golden, this should take only a few seconds. Don’t let it go very dark or it will spoil the taste. Spoon in the curry paste and stir it around for a few seconds to begin to cook the spices and release all the flavours. Next, pour in the coconut milk and let it come to a bubble.","Stir in the fish sauce and sugar, then the pieces of chicken. Turn the heat down to a simmer and cook, covered, for about 8 minutes until the chicken is cooked.","Tip in the potatoes and beans and let them warm through in the hot coconut milk, then add a lovely citrussy flavour by stirring in the shredded lime leaves (or lime zest). The basil leaves go in next, but only leave them briefly on the heat or they will quickly lose their brightness. Scatter with the lime garnish and serve immediately with boiled rice."],"ingredient_names":["potatoes","green beans","sunflower oil","garlic","thai green curry paste","coconut milk","thai fish sauce","sugar","chicken","lime","basil","rice"],"allergens":["fish"],"diet_flags":[]},{"source_id":"52816","title":"Roasted Eggplant With Tahini, Pine Nuts, and Lentils","category":"Vegetarian","country":"United States","tags":["Vegetarian","Pulse","Nutty"],"image_url":"https://www.themealdb.com/images/media/meals/ysqrus1487425681.jpg","youtube_url":"https://www.youtube.com/watch?v=HkywCtna9t0","source_url":"http://www.seriouseats.com/recipes/2016/03/roasted-eggplant-tahini-pine-nut-lentil-vegan-experience-recipe.html","ingredients":[{"name":"Olive Oil","measure":"2 tablespoons"},{"name":"Carrots","measure":"2 small cut into chunks"},{"name":"Celery","measure":"2 small stalks"},{"name":"Onion","measure":"1 medium finely diced"},{"name":"Garlic","measure":"6 medium cloves sliced"},{"name":"Brown Lentils","measure":"12 ounces (340g)"},{"name":"Bay Leaves","measure":"2"},{"name":"Water","measure":"4 cups"},{"name":"Salt","measure":"Pinch"},{"name":"Apple Cider Vinegar","measure":"2 teaspoons (10ml)"},{"name":"Pepper","measure":"Pinch"},{"name":"Egg Plants","measure":"2 large"},{"name":"Rosemary","measure":"4 sprigs"},{"name":"Pine nuts","measure":"1/4 cup"},{"name":"Parsley","measure":"2 tablespoons"}],"steps":["For the Lentils: Adjust oven rack to center position and preheat oven to 450°F to prepare for roasting eggplant. Meanwhile, heat 2 tablespoons olive oil in a medium saucepan over medium heat until shimmering. Add carrots, celery, and onion and cook, stirring, until softened but not browned, about 4 minutes. Add garlic and cook, stirring, until fragrant, about 30 seconds. Add lentils, bay leaves, stock or water, and a pinch of salt. Bring to a simmer, cover with the lid partially ajar, and cook until lentils are tender, about 30 minutes. (Top up with water if lentils are at any point not fully submerged.) Remove lid, stir in vinegar, and reduce until lentils are moist but not soupy. Season to taste with salt and pepper, cover, and keep warm until ready to serve.","For the Eggplant: While lentils cook, cut each eggplant in half. Score flesh with the tip of a paring knife in a cross-hatch pattern at 1-inch intervals. Transfer to a foil-lined rimmed baking sheet, cut side up, and brush each eggplant half with 1 tablespoon oil, letting each brushstroke be fully absorbed before brushing with more. Season with salt and pepper. Place a rosemary sprig on top of each one. Transfer to oven and roast until completely tender and well charred, 25 to 35 minutes. Remove from oven and discard rosemary.","To Serve: Heat 2 tablespoons olive oil and pine nuts in a medium skillet set over medium heat. Cook, tossing nuts frequently, until golden brown and aromatic, about 4 minutes. Transfer to a bowl to halt cooking. Stir half of parsley and rosemary into lentils and transfer to a serving platter. Arrange eggplant halves on top. Spread a few tablespoons of tahini sauce over each eggplant half and sprinkle with pine nuts. Sprinkle with remaining parsley and rosemary, drizzle with additional olive oil, and serve."],"ingredient_names":["olive oil","carrots","celery","onion","garlic","brown lentils","bay leaves","water","salt","apple cider vinegar","pepper","egg plants","rosemary","pine nuts","parsley"],"allergens":["eggs","tree_nuts"],"diet_flags":["pescatarian","vegetarian"]},{"source_id":"52817","title":"Stovetop Eggplant With Harissa, Chickpeas, and Cumin Yogurt","category":"Vegetarian","country":"United States","tags":["Vegetarian"],"image_url":"https://www.themealdb.com/images/media/meals/yqwtvu1487426027.jpg","youtube_url":"https://www.youtube.com/watch?v=uYB-1xJp4lg","source_url":"http://www.seriouseats.com/2014/09/one-pot-wonders-stovetop-eggplant-harissa-chickpeas-cumin.html","ingredients":[{"name":"Olive Oil","measure":"4 tablespoons"},{"name":"Egg Plants","measure":"6 small"},{"name":"Harissa Spice","measure":"½ tablespoon"},{"name":"Chickpeas","measure":"1 can"},{"name":"Cherry Tomatoes","measure":"2 cups halved"},{"name":"Greek yogurt","measure":"1 1/2 cups"},{"name":"Ground cumin","measure":"1 tablespoon"},{"name":"Parsley","measure":"½ cup"}],"steps":["Heat the oil in a 12-inch skillet over high heat until shimmering. Add the eggplants and lower the heat to medium. Season with salt and pepper as you rotate the eggplants, browning them on all sides. Continue to cook, turning regularly, until a fork inserted into the eggplant meets no resistance (you may have to stand them up on their fat end to finish cooking the thickest parts), about 20 minutes, lowering the heat and sprinkling water into the pan as necessary if the eggplants threaten to burn or smoke excessively.","Mix the harissa, chickpeas and tomatoes together, then add to the eggplants. Cook until the tomatoes have blistered and broken down, about 5 minutes more. Season with salt and pepper and add water as necessary to thin to a saucy consistency. Meanwhile, combine the yogurt and cumin in a serving bowl. Season with salt and pepper.","Top the eggplant mixture with the parsley, drizzle with more extra virgin olive oil, and serve with the yogurt on the side."],"ingredient_names":["olive oil","egg plants","harissa spice","chickpeas","cherry tomatoes","greek yogurt","ground cumin","parsley"],"allergens":["dairy","eggs"],"diet_flags":["pescatarian","vegetarian"]},{"source_id":"52818","title":"Chicken Fajita Mac and Cheese","category":"Chicken","country":"United States","tags":["Pasta","Cheasy","Meat","Cheesy"],"image_url":"https://www.themealdb.com/images/media/meals/qrqywr1503066605.jpg","youtube_url":"https://www.youtube.com/watch?v=bwTSmLTZKNg","source_url":"http://twistedfood.co.uk/chicken-fajita-mac-n-cheese/","ingredients":[{"name":"macaroni","measure":"500g"},{"name":"chicken stock","measure":"2 cups"},{"name":"heavy cream","measure":"1/2 cup"},{"name":"fajita seasoning","measure":"1 packet"},{"name":"salt","measure":"1 tsp"},{"name":"chicken breast","measure":"3 diced"},{"name":"olive oil","measure":"2 tbsp"},{"name":"onion","measure":"1 small finely diced"},{"name":"red pepper","measure":"2 finely diced"},{"name":"garlic","measure":"2 cloves minced"},{"name":"cheddar cheese","measure":"1 cup"},{"name":"parsley","measure":"garnish chopped"}],"steps":["Fry your onion, peppers and garlic in olive oil until nicely translucent. Make a well in your veg and add your chicken. Add your seasoning and salt. Allow to colour slightly.","Add your cream, stock and macaroni.","Cook on low for 20 minutes. Add your cheeses, stir to combine.","Top with roasted peppers and parsley."],"ingredient_names":["macaroni","chicken stock","heavy cream","fajita seasoning","salt","chicken breast","olive oil","onion","red pepper","garlic","cheddar cheese","parsley"],"allergens":["dairy","gluten"],"diet_flags":[]},{"source_id":"52819","title":"Cajun spiced fish tacos","category":"Seafood","country":"Mexico","tags":["Spicy","Fish"],"image_url":"https://www.themealdb.com/images/media/meals/uvuyxu1503067369.jpg","youtube_url":"https://www.youtube.com/watch?v=N4EdUt0Ou48","source_url":"https://realfood.tesco.com/recipes/cajun-spiced-fish-tacos.html","ingredients":[{"name":"cajun","measure":"2 tbsp"},{"name":"cayenne pepper","measure":"1 tsp"},{"name":"white fish","measure":"4 fillets"},{"name":"vegetable oil","measure":"1 tsp"},{"name":"flour tortilla","measure":"8"},{"name":"avocado","measure":"1 sliced"},{"name":"little gem lettuce","measure":"2 shredded"},{"name":"Spring Onions","measure":"4 shredded"},{"name":"salsa","measure":"1 x 300ml"},{"name":"sour cream","measure":"1 pot"},{"name":"lemon","measure":"1"},{"name":"garlic","measure":"1 clove finely chopped"}],"steps":["Cooking in a cajun spice and cayenne pepper marinade makes this fish super succulent and flavoursome. Top with a zesty dressing and serve in a tortilla for a quick, fuss-free main that's delightfully summery.","On a large plate, mix the cajun spice and cayenne pepper with a little seasoning and use to coat the fish all over.","Heat a little oil in a frying pan, add in the fish and cook over a medium heat until golden. Reduce the heat and continue frying until the fish is cooked through, about 10 minutes. Cook in batches if you don’t have enough room in the pan.","Meanwhile, prepare the dressing by combining all the ingredients with a little seasoning.","Soften the tortillas by heating in the microwave for 5-10 seconds. Pile high with the avocado, lettuce and spring onion, add a spoonful of salsa, top with large flakes of fish and drizzle over the dressing."],"ingredient_names":["cajun","cayenne pepper","white fish","vegetable oil","flour tortilla","avocado","little gem lettuce","spring onions","salsa","sour cream","lemon","garlic"],"allergens":["dairy","fish","gluten"],"diet_flags":["pescatarian"]},{"source_id":"52820","title":"Katsu Chicken curry","category":"Chicken","country":"Japan","tags":["Curry","Meat"],"image_url":"https://www.themealdb.com/images/media/meals/vwrpps1503068729.jpg","youtube_url":"https://www.youtube.com/watch?v=MWzxDFRtVbc","source_url":"http://allrecipes.co.uk/recipe/29578/chicken-katsu-curry.aspx","ingredients":[{"name":"chicken breast","measure":"4 pounded to 1cm thickness"},{"name":"plain flour","measure":"2 tablespoons"},{"name":"egg","measure":"1 beaten"},{"name":"breadcrumbs","measure":"100g fine"},{"name":"vegetable oil","measure":"230ml frying"},{"name":"sunflower oil","measure":"2 tablespoons"},{"name":"onions","measure":"2 sliced"},{"name":"garlic","measure":"5 chopped cloves"},{"name":"carrot","measure":"2 sliced"},{"name":"plain flour","measure":"2 tablespoons"},{"name":"curry powder","measure":"4 teaspoons"},{"name":"chicken stock","measure":"600ml"},{"name":"honey","measure":"2 teaspoons"},{"name":"soy sauce","measure":"4 teaspoons"},{"name":"bay leaf","measure":"1"},{"name":"garam masala","measure":"1 teaspoon"}],"steps":["Prep:15min  ›  Cook:30min  ›  Ready in:45min","For the curry sauce: Heat oil in medium non-stick saucepan, add onion and garlic and cook until softened. Stir in carrots and cook over low heat for 10 to 12 minutes.","Add flour and curry powder; cook for 1 minute. Gradually stir in stock until combined; add honey, soy sauce and bay leaf. Slowly bring to the boil.","Turn down heat and simmer for 20 minutes or until sauce thickens but is still of pouring consistency. Stir in garam masala. Pour the curry sauce through a sieve; return to saucepan and keep on low heat until ready to serve.","For the chicken: Season both sides of chicken breasts with salt and pepper. Place flour, egg and breadcrumbs in separate bowls and arrange in a row. Coat the chicken breasts in flour, then dip them into the egg, then coat in breadcrumbs, making sure you cover both sides.","Heat oil in large frying pan over medium-high heat. Place chicken into hot oil and cook until golden brown, about 3 or 4 minutes each side. Once cooked, place on kitchen paper to absorb excess oil.","Pour curry sauce over chicken, serve with white rice and enjoy!"],"ingredient_names":["chicken breast","plain flour","egg","breadcrumbs","vegetable oil","sunflower oil","onions","garlic","carrot","plain flour","curry powder","chicken stock","honey","soy sauce","bay leaf","garam masala"],"allergens":["eggs","gluten","soy"],"diet_flags":[]},{"source_id":"52821","title":"Laksa King Prawn Noodles","category":"Seafood","country":"Malaysia","tags":["Shellfish","Seafood"],"image_url":"https://www.themealdb.com/images/media/meals/rvypwy1503069308.jpg","youtube_url":"https://www.youtube.com/watch?v=OcarztU8cYo","source_url":"https://www.bbcgoodfood.com/recipes/prawn-laksa-curry-bowl","ingredients":[{"name":"Olive Oil","measure":"1 tbsp"},{"name":"Red Chilli","measure":"1 finely sliced"},{"name":"Thai red curry paste","measure":"2 ½ tbsp"},{"name":"vegetable stock cube","measure":"1"},{"name":"coconut milk","measure":"400ml can"},{"name":"fish sauce","measure":"2 tsp"},{"name":"rice noodles","measure":"100g"},{"name":"lime","measure":"2 juice of 1, the other halved"},{"name":"king prawns","measure":"150g"},{"name":"coriander","measure":"½ small pack"}],"steps":["Heat the oil in a medium saucepan and add the chilli. Cook for 1 min, then add the curry paste, stir and cook for 1 min more. Dissolve the stock cube in a large jug in 700ml boiling water, then pour into the pan and stir to combine. Tip in the coconut milk and bring to the boil.","Add the fish sauce and a little seasoning. Toss in the noodles and cook for a further 3-4 mins until softening. Squeeze in the lime juice, add the prawns and cook through until warm, about 2-3 mins. Scatter over some of the coriander.","Serve in bowls with the remaining coriander and lime wedges on top for squeezing over."],"ingredient_names":["olive oil","red chilli","thai red curry paste","vegetable stock cube","coconut milk","fish sauce","rice noodles","lime","king prawns","coriander"],"allergens":["fish","shellfish"],"diet_flags":["pescatarian"]},{"source_id":"52822","title":"Toad In The Hole","category":"Pork","country":"United Kingdom","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/ytuvwr1503070420.jpg","youtube_url":"https://www.youtube.com/watch?v=t1dWkDrC330","source_url":"http://www.deliciousmagazine.co.uk/recipes/georgina-fuggles-horseradish-and-vine-tomato-toad-in-the-hole/","ingredients":[{"name":"sausages","measure":"8"},{"name":"vegetable oil","measure":"3 tbsp"},{"name":"plain flour","measure":"100g"},{"name":"eggs","measure":"2 medium"},{"name":"horseradish","measure":"1 tbsp grated"},{"name":"milk","measure":"225ml"},{"name":"cherry tomatoes","measure":"200g"}],"steps":["Preheat the oven to 200°C/fan180°C/gas 6. fry sausages in a non-stick pan until browned.","Drizzle vegetable oil in a 30cm x 25cm x 6cm deep roasting tray and heat in the oven for 5 minutes.","Put the plain flour in a bowl, crack in the medium free-range eggs, then stir in the grated horseradish. Gradually beat in the semi-skimmed milk. Season.","Put the sausages into the hot roasting tray and pour over the batter. Top with cherry tomatoes on the vine and cook for 30 minutes until puffed and golden."],"ingredient_names":["sausages","vegetable oil","plain flour","eggs","horseradish","milk","cherry tomatoes"],"allergens":["dairy","eggs","gluten"],"diet_flags":[]},{"source_id":"52823","title":"Salmon Prawn Risotto","category":"Seafood","country":"Italy","tags":["Fish"],"image_url":"https://www.themealdb.com/images/media/meals/xxrxux1503070723.jpg","youtube_url":"https://www.youtube.com/watch?v=V2PMvBv52IE","source_url":"http://www.rangemaster.co.uk/rangemaster-owners/recipes-ideas-inspiration/recipes/mains/prawn-and-hot-smoked-salmon-risotto-with-asparagus","ingredients":[{"name":"butter","measure":"50g/2oz"},{"name":"onion","measure":"1 finely chopped"},{"name":"rice","measure":"150g"},{"name":"white wine","measure":"125ml"},{"name":"vegetable stock","measure":"1 litre hot"},{"name":"lemon","measure":"The juice and zest of one"},{"name":"King Prawns","measure":"240g large"},{"name":"salmon","measure":"150g"},{"name":"asparagus","measure":"100g tips blanched briefly in boiling water"},{"name":"black pepper","measure":"ground"},{"name":"Parmesan","measure":"50g shavings"}],"steps":["Melt the butter in a thick-based pan and gently cook the onion without colour until it is soft.","Add the rice and stir to coat all the grains in the butter","Add the wine and cook gently stirring until it is absorbed","Gradually add the hot stock, stirring until each addition is absorbed. Keep stirring until the rice is tender","Season with the lemon juice and zest, and pepper to taste. (there will probably be sufficient saltiness from the salmon to not need to add salt) Stir gently to heat through","Serve scattered with the Parmesan and seasonal vegetables.","Grill the salmon and gently place onto the risotto with the prawns and asparagus"],"ingredient_names":["butter","onion","rice","white wine","vegetable stock","lemon","king prawns","salmon","asparagus","black pepper","parmesan"],"allergens":["dairy","fish","shellfish"],"diet_flags":["pescatarian"]},{"source_id":"52824","title":"Beef Sunday Roast","category":"Beef","country":"United Kingdom","tags":["MainMeal"],"image_url":"https://www.themealdb.com/images/media/meals/ssrrrs1503664277.jpg","youtube_url":"https://www.youtube.com/watch?v=2l3-dBdNehY","source_url":"https://www.bbcgoodfood.com/recipes/9020/best-yorkshire-puddings","ingredients":[{"name":"Beef","measure":"8 slices"},{"name":"Broccoli","measure":"12 florets"},{"name":"Potatoes","measure":"1 Packet"},{"name":"Carrots","measure":"1 Packet"},{"name":"plain flour","measure":"140g"},{"name":"Eggs","measure":"4"},{"name":"milk","measure":"200ml"},{"name":"sunflower oil","measure":"drizzle (for cooking)"}],"steps":["Cook the Broccoli and Carrots in a pan of boiling water until tender.","Roast the Beef and Potatoes in the oven for 45mins, the potatoes may need to be checked regularly to not overcook.","To make the Yorkshire puddings:","Heat oven to 230C/fan 210C/gas 8. Drizzle a little sunflower oil evenly into 2 x 4-hole Yorkshire pudding tins or a 12-hole non-stick muffin tin and place in the oven to heat through","To make the batter, tip 140g plain flour into a bowl and beat in four eggs until smooth. Gradually add 200ml milk and carry on beating until the mix is completely lump-free. Season with salt and pepper. Pour the batter into a jug, then remove the hot tins from the oven. Carefully and evenly pour the batter into the holes. Place the tins back in the oven and leave undisturbed for 20-25 mins until the puddings have puffed up and browned. Serve immediately.","Plate up and add the Gravy as desired."],"ingredient_names":["beef","broccoli","potatoes","carrots","plain flour","eggs","milk","sunflower oil"],"allergens":["dairy","eggs","gluten"],"diet_flags":[]},{"source_id":"52826","title":"Braised Beef Chilli","category":"Beef","country":"Mexico","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/uuqvwu1504629254.jpg","youtube_url":"https://www.youtube.com/watch?v=z4kSoJgsu6Y","source_url":"http://www.telegraph.co.uk/food-and-drink/recipes/braised-beef-chilli-con-carne/","ingredients":[{"name":"Beef","measure":"1kg"},{"name":"Onions","measure":"3"},{"name":"Garlic","measure":"4 cloves"},{"name":"Olive oil","measure":"Dash"},{"name":"Chorizo","measure":"300g"},{"name":"Cumin","measure":"2 tsp"},{"name":"Allspice","measure":"2 tsp"},{"name":"Cloves","measure":"1 tsp"},{"name":"Cinnamon stick","measure":"1 large"},{"name":"Bay Leaves","measure":"3"},{"name":"Oregano","measure":"2 tsp dried"},{"name":"Ancho Chillies","measure":"2 ancho"},{"name":"Balsamic Vinegar","measure":"3 tbsp"},{"name":"Plum Tomatoes","measure":"2 x 400g"},{"name":"Tomato Ketchup","measure":"2 tbsp"},{"name":"Dark Brown Sugar","measure":"2 tbsp"},{"name":"Borlotti Beans","measure":"2 x 400g tins"}],"steps":["Preheat the oven to 120C/225F/gas mark 1.","Take the meat out of the fridge to de-chill. Pulse the onions and garlic in a food processor until finely chopped. Heat 2 tbsp olive oil in a large casserole and sear the meat on all sides until golden.","Set to one side and add another small slug of oil to brown the chorizo. Remove and add the onion and garlic, spices, herbs and chillies then cook until soft in the chorizo oil. Season with salt and pepper and add the vinegar, tomatoes, ketchup and sugar.","Put all the meat back into the pot with 400ml water (or red wine if you prefer), bring up to a simmer and cook, covered, in the low oven.","After 2 hours, check the meat and add the beans. Cook for a further hour and just before serving, pull the meat apart with a pair of forks."],"ingredient_names":["beef","onions","garlic","olive oil","chorizo","cumin","allspice","cloves","cinnamon stick","bay leaves","oregano","ancho chillies","balsamic vinegar","plum tomatoes","tomato ketchup","dark brown sugar","borlotti beans"],"allergens":[],"diet_flags":[]},{"source_id":"52827","title":"Massaman Beef curry","category":"Beef","country":"Thailand","tags":["Curry"],"image_url":"https://www.themealdb.com/images/media/meals/tvttqv1504640475.jpg","youtube_url":"https://www.youtube.com/watch?v=mVxgZSCU9_g","source_url":"https://www.bbcgoodfood.com/recipes/420631/beef-massaman-curry","ingredients":[{"name":"Peanuts","measure":"85g"},{"name":"Coconut cream","measure":"400ml can"},{"name":"Massaman curry paste","measure":"4 tbsp"},{"name":"Beef","measure":"600g stewing cut into strips"},{"name":"Potatoes","measure":"450g waxy"},{"name":"Onion","measure":"1 cut thin wedges"},{"name":"Lime","measure":"4 leaves"},{"name":"Cinnamon stick","measure":"1"},{"name":"Tamarind paste","measure":"1 tbsp"},{"name":"Brown sugar","measure":"1 tbsp palm or soft light"},{"name":"Fish Sauce","measure":"1 tbsp"},{"name":"chilli","measure":"1 red deseeded and finely sliced, to serve"},{"name":"Jasmine Rice","measure":"to serve"}],"steps":["Heat oven to 200C/180C fan/gas 6, then roast the peanuts on a baking tray for 5 mins until golden brown. When cool enough to handle, roughly chop. Reduce oven to 180C/160C fan/gas 4.","Heat 2 tbsp coconut cream in a large casserole dish with a lid. Add the curry paste and fry for 1 min, then stir in the beef and fry until well coated and sealed. Stir in the rest of the coconut with half a can of water, the potatoes, onion, lime leaves, cinnamon, tamarind, sugar, fish sauce and most of the peanuts. Bring to a simmer, then cover and cook for 2 hrs in the oven until the beef is tender.","Sprinkle with sliced chilli and the remaining peanuts, then serve straight from the dish with jasmine rice."],"ingredient_names":["peanuts","coconut cream","massaman curry paste","beef","potatoes","onion","lime","cinnamon stick","tamarind paste","brown sugar","fish sauce","chilli","jasmine rice"],"allergens":["fish","peanuts"],"diet_flags":[]},{"source_id":"52828","title":"Vietnamese Grilled Pork (bun-thit-nuong)","category":"Pork","country":"Vietnam","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/qqwypw1504642429.jpg","youtube_url":"https://www.youtube.com/watch?v=Q3qcQcENzbU","source_url":"http://www.hungryhuy.com/bun-thit-nuong-recipe-vietnamese-grilled-bbq-pork-with-rice-vermicelli-vegetables/","ingredients":[{"name":"Pork","measure":"1.5 pounds sliced"},{"name":"Rice Vermicelli","measure":"1 package thin"},{"name":"Egg Rolls","measure":"4-6"},{"name":"Challots","measure":"3 tablespoons minced"},{"name":"Garlic","measure":"1.5 tablespoons minced garlic"},{"name":"Sugar","measure":"¼ cup"},{"name":"Fish Sauce","measure":"1 tablespoon"},{"name":"Soy sauce","measure":"½ tablespoon thick"},{"name":"Pepper","measure":"½ tablespoon"},{"name":"Olive Oil","measure":"3 tablespoons"},{"name":"Cucumber","measure":"Sliced"},{"name":"Mint","measure":"Leaves"},{"name":"Peanuts","measure":"Crushed"}],"steps":["Slice the uncooked pork thinly, about ⅛\". It helps to slightly freeze it (optional).","Mince garlic and shallots. Mix in a bowl with sugar, fish sauce, thick soy sauce, pepper, and oil until sugar dissolves.","Marinate the meat for 1 hour, or overnight for better results.","Bake the pork at 375F for 10-15 minutes or until about 80% cooked. Finish cooking by broiling in the oven until a nice golden brown color develops, flipping the pieces midway.","Assemble your bowl with veggies, noodles, and garnish. Many like to mix the whole bowl up and pour the fish sauce on top, but I like to make individual bites and sauce it slowly."],"ingredient_names":["pork","rice vermicelli","egg rolls","challots","garlic","sugar","fish sauce","soy sauce","pepper","olive oil","cucumber","mint","peanuts"],"allergens":["eggs","fish","gluten","peanuts","soy"],"diet_flags":[]},{"source_id":"52829","title":"Grilled Mac and Cheese Sandwich","category":"Pasta","country":"United States","tags":["Cheesy"],"image_url":"https://www.themealdb.com/images/media/meals/xutquv1505330523.jpg","youtube_url":"https://www.youtube.com/watch?v=PYq31xLj-DY","source_url":"https://leitesculinaria.com/103647/recipes-grilled-mac-and-cheese-sandwich.html","ingredients":[{"name":"Macaroni","measure":"8 ounces (230 grams)"},{"name":"Plain Flour","measure":"1/3 cup"},{"name":"Mustard Powder","measure":"3/4 teaspoon"},{"name":"Garlic powder","measure":"1/2 teaspoon"},{"name":"Kosher salt","measure":"1/2 teaspoon"},{"name":"Black pepper","measure":"1/2 teaspoon"},{"name":"Cayenne pepper","measure":"1/8 teaspoon"},{"name":"Butter","measure":"6 tablespoons (85 grams)"},{"name":"Whole Milk","measure":"1 1/2 cups (360 milliliters)"},{"name":"Heavy Cream","measure":"1 cup (240 milliliters)"},{"name":"Monterey Jack Cheese","measure":"1 pound (455 grams)"},{"name":"Butter","measure":"4 tablespoons (55 grams)"},{"name":"garlic powder","measure":"1 teaspoon"},{"name":"Bread","measure":"16 slices square"},{"name":"Cheddar Cheese","measure":"8 slices mild"},{"name":"Colby Jack Cheese","measure":"8 slices"},{"name":"Butter","measure":"4 tablespoons (55 grams)"}],"steps":["Make the mac and cheese","Bring a medium saucepan of generously salted water (you want it to taste like seawater) to a boil. Add the pasta and cook, stirring occasionally, until al dente, 8 to 10 minutes, or according to the package directions. The pasta should be tender but still chewy.","While the pasta is cooking, in a small bowl, whisk together the flour, mustard powder, garlic powder, salt, black pepper, and cayenne pepper.","Drain the pasta in a colander. Place the empty pasta pan (no need to wash it) over low heat and add the butter. When the butter has melted, whisk in the flour mixture and continue to cook, whisking frequently, until the mixture is beginning to brown and has a pleasant, nutty aroma, about 1 minute. Watch carefully so it does not scorch on the bottom of the pan.","Slowly whisk the milk and cream into the flour mixture until everything is really well combined. Cook, whisking constantly, until the sauce is heated through and just begins to thicken, about 2 minutes. Remove from the heat. Gradually add the cheese while stirring constantly with a wooden spoon or silicone spatula and keep stirring until the cheese has melted into the sauce. Then stir in the drained cooked pasta.","Line a 9-by-13-inch (23-by-33-centimeter) rimmed baking sheet with parchment paper or aluminum foil. Coat the paper or foil with nonstick cooking spray or slick it with butter. Pour the warm mac and cheese onto the prepared baking sheet and spread it evenly with a spatula. Coat another piece of parchment paper with cooking spray or butter and place it, oiled or buttered side down, directly on the surface of the mac and cheese. Refrigerate until cool and firm, about 1 hour.","Make the grilled cheese","Heat a large cast-iron or nonstick skillet over medium-low heat.","In a small bowl, stir together the 4 tablespoons (55 grams) butter and garlic powder until well blended.","Remove the mac and cheese from the refrigerator and peel off the top layer of parchment paper. Carefully cut into 8 equal pieces. Each piece will make 1 grilled mac and cheese sandwich. (You can stash each individual portion in a double layer of resealable plastic bags and refrigerate for up to 3 days or freeze it for up to 1 month.)","Spread 3/4 teaspoon garlic butter on one side of each bread slice. Place half of the slices, buttered-side down, on a clean cutting board. Top each with one slice of Cheddar, then 1 piece of the mac and cheese. (Transfer from the baking sheet by scooting your hand or a spatula under each piece of mac and cheese and then flipping it over onto a sandwich.) Place 1 slice of Jack on top of each. Finish with the remaining bread slices, buttered-side up.","Using a wide spatula, place as many sandwiches in the pan as will fit without crowding it. Cover and cook until the bottoms are nicely browned, about 4 minutes. Turn and cook until the second sides are browned, the cheese is melted, and the mac and cheese is heated through, about 4 minutes more.","Repeat with the remaining ingredients. Cut the sandwiches in half, if desired, and serve."],"ingredient_names":["macaroni","plain flour","mustard powder","garlic powder","kosher salt","black pepper","cayenne pepper","butter","whole milk","heavy cream","monterey jack cheese","butter","garlic powder","bread","cheddar cheese","colby jack cheese","butter"],"allergens":["dairy","gluten"],"diet_flags":["pescatarian","vegetarian"]},{"source_id":"52830","title":"Crock Pot Chicken Baked Tacos","category":"Chicken","country":"Mexico","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/ypxvwv1505333929.jpg","youtube_url":"https://www.youtube.com/watch?v=oqL0mLDBzS4","source_url":"http://www.nobiggie.net/crock-pot-chicken-baked-tacos/","ingredients":[{"name":"Chicken Breasts","measure":"4 - 6"},{"name":"Vinaigrette Dressing","measure":"1 bottle"},{"name":"Cumin","measure":"1½ tablespoon"},{"name":"Smoked Paprika","measure":"1 tablespoon"},{"name":"Garlic","measure":"1 teaspoon"},{"name":"Refried Beans","measure":"1 can"},{"name":"Hard Taco Shells","measure":"12"},{"name":"Shredded Mexican Cheese","measure":"2 cups"},{"name":"Grape Tomatoes","measure":"Halved"},{"name":"Jalapeno","measure":"Sliced and Seeded"},{"name":"Avocado","measure":"Peeled and Sliced"},{"name":"Green Salsa","measure":"2 tablespoons"},{"name":"Sour Cream","measure":"3 tablespoons"},{"name":"Milk","measure":"1 tablespoon"}],"steps":["Put the uncooked chicken breasts in the crock pot. Pour the full bottle of salad dressing over the chicken. Sprinkle the rest of the ingredients over the top and mix them in a bit with a spoon.","Cover your crock pot with the lid and cook on high for 4 hours.","Remove all the chicken breasts from the crock pot and let cool.","Shred the chicken breasts and move to a glass bowl.","Pour most of the liquid over the shredded chicken.","FOR THE TACOS:","Make the guacamole sauce by mixing the avocado and green salsa together. Pour the guacamole mixture through a strainer until smooth and transfer to a squeeze bottle. Cut the tip off the lid of the squeeze bottle to make the opening more wide if needed.","Make the sour cream sauce by mixing the sour cream and milk together until you get a more liquid sour cream sauce. Transfer to a squeeze bottle.","In a 9x 13 glass baking dish, fill all 12+ tacos with a layer of refried beans, cooked chicken and shredded cheese.","Bake at 450 for 10-15 minutes just until the cheese is melted and bubbling.","Out of the oven top all the tacos with the sliced grape tomaotes, jalapeno and cilantro.","Finish with a drizzle of guacamole and sour cream.","Enjoy!"],"ingredient_names":["chicken breasts","vinaigrette dressing","cumin","smoked paprika","garlic","refried beans","hard taco shells","shredded mexican cheese","grape tomatoes","jalapeno","avocado","green salsa","sour cream","milk"],"allergens":["dairy"],"diet_flags":[]},{"source_id":"52831","title":"Chicken Karaage","category":"Chicken","country":"Japan","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/tyywsw1505930373.jpg","youtube_url":"https://www.youtube.com/watch?v=XivddFddthc","source_url":"https://norecipes.com/karaage-recipe","ingredients":[{"name":"Chicken","measure":"450 grams Boneless skin"},{"name":"Ginger","measure":"1 tablespoon"},{"name":"Garlic","measure":"1 clove"},{"name":"Soy sauce","measure":"2 tablespoons"},{"name":"Sake","measure":"1 tablespoon"},{"name":"Granulated sugar","measure":"2 teaspoon"},{"name":"Potato starch","measure":"1/3 cup"},{"name":"Vegetable oil","measure":"1/3 cup"},{"name":"Lemon","measure":"1/3 cup"}],"steps":["Add the ginger, garlic, soy sauce, sake and sugar to a bowl and whisk to combine. Add the chicken, then stir to coat evenly. Cover and refrigerate for at least 1 hour.","Add 1 inch of vegetable oil to a heavy bottomed pot and heat until the oil reaches 360 degrees F. Line a wire rack with 2 sheets of paper towels and get your tongs out. Put the potato starch in a bowl","Add a handful of chicken to the potato starch and toss to coat each piece evenly.","Fry the karaage in batches until the exterior is a medium brown and the chicken is cooked through. Transfer the fried chicken to the paper towel lined rack. If you want the karaage to stay crispy longer, you can fry the chicken a second time, until it's a darker color after it's cooled off once. Serve with lemon wedges."],"ingredient_names":["chicken","ginger","garlic","soy sauce","sake","granulated sugar","potato starch","vegetable oil","lemon"],"allergens":["gluten","soy"],"diet_flags":[]},{"source_id":"52832","title":"Coq au vin","category":"Chicken","country":"France","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/qstyvs1505931190.jpg","youtube_url":"https://www.youtube.com/watch?v=_ise46LADBs","source_url":"https://www.bbcgoodfood.com/recipes/1913655/coq-au-vin","ingredients":[{"name":"Olive Oil","measure":"1½ tbsp"},{"name":"Bacon","measure":"3 rashers (100g) chopped dry-cured"},{"name":"Shallots","measure":"12 small"},{"name":"Chicken Legs","measure":"2 (460g)"},{"name":"Chicken Thighs","measure":"4 (650g)"},{"name":"Chicken Breasts","measure":"2 (280g)"},{"name":"Garlic","measure":"3 finely chopped"},{"name":"Brandy","measure":"3 tbsp"},{"name":"Red Wine","measure":"600ml"},{"name":"Chicken Stock","measure":"150ml"},{"name":"tomato puree","measure":"2 tsp"},{"name":"thyme","measure":"3 sprigs"},{"name":"Rosemary","measure":"2 sprigs"},{"name":"bay leaves","measure":"2"},{"name":"parsley","measure":"garnish"},{"name":"chestnut mushroom","measure":"250g"},{"name":"plain flour","measure":"2 tbsp"},{"name":"butter","measure":"1 tsp"}],"steps":["Heat 1 tbsp of the oil in a large, heavy-based saucepan or flameproof dish. Tip in the bacon and fry until crisp. Remove and drain on kitchen paper. Add the shallots to the pan and fry, stirring or shaking the pan often, for 5-8 mins until well browned all over. Remove and set aside with the bacon.","Pat the chicken pieces dry with kitchen paper. Pour the remaining oil into the pan, then fry half the chicken pieces, turning regularly, for 5-8 mins until well browned. Remove, then repeat with the remaining chicken. Remove and set aside.","Scatter in the garlic and fry briefly, then, with the heat medium-high, pour in the brandy or Cognac, stirring the bottom of the pan to deglaze. The alcohol should sizzle and start to evaporate so there is not much left.","Return the chicken legs and thighs to the pan along with any juices, then pour in a little of the wine, stirring the bottom of the pan again. Stir in the rest of the wine, the stock and tomato purée, drop in the bouquet garni, season with pepper and a pinch of salt, then return the bacon and shallots to the pan. Cover, lower the heat to a gentle simmer, add the chicken breasts and cook for 50 mins-1hr.","Just before ready to serve, heat the oil for the mushrooms in a large non-stick frying pan. Add the mushrooms and fry over a high heat for a few mins until golden. Remove and keep warm.","Lift the chicken, shallots and bacon from the pan and transfer to a warmed serving dish. Remove the bouquet garni. To make the thickener, mix the flour, olive oil and butter in a small bowl using the back of a teaspoon. Bring the wine mixture to a gentle boil, then gradually drop in small pieces of the thickener, whisking each piece in using a wire whisk. Simmer for 1-2 mins. Scatter the mushrooms over the chicken, then pour over the wine sauce. Garnish with chopped parsley."],"ingredient_names":["olive oil","bacon","shallots","chicken legs","chicken thighs","chicken breasts","garlic","brandy","red wine","chicken stock","tomato puree","thyme","rosemary","bay leaves","parsley","chestnut mushroom","plain flour","butter"],"allergens":["dairy","gluten","tree_nuts"],"diet_flags":[]},{"source_id":"52834","title":"Beef stroganoff","category":"Beef","country":"Russia","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/svprys1511176755.jpg","youtube_url":"https://www.youtube.com/watch?v=PQHgQX1Ss74","source_url":"https://www.bbcgoodfood.com/recipes/beef-stroganoff","ingredients":[{"name":"Olive Oil","measure":"1 tbls"},{"name":"Onions","measure":"1"},{"name":"Garlic","measure":"1 clove"},{"name":"Butter","measure":"1 tbsp"},{"name":"Mushrooms","measure":"250g"},{"name":"Beef Fillet","measure":"500g"},{"name":"Plain Flour","measure":"1tbsp"},{"name":"Creme Fraiche","measure":"150g"},{"name":"English Mustard","measure":"1 tbsp"},{"name":"Beef Stock","measure":"100ml"},{"name":"Parsley","measure":"Topping"}],"steps":["Heat the olive oil in a non-stick frying pan then add the sliced onion and cook on a medium heat until completely softened, so around 15 mins, adding a little splash of water if they start to stick at all.","Crush in the garlic and cook for a 2-3 mins further, then add the butter.","Once the butter is foaming a little, add the mushrooms and cook for around 5 mins until completely softened.","Season everything well, then tip onto a plate.","Tip the flour into a bowl with a big pinch of salt and pepper, then toss the steak in the seasoned flour.","Add the steak pieces to the pan, splashing in a little oil if the pan looks particularly dry, and fry for 3-4 mins, until well coloured.","Tip the onions and mushrooms back into the pan.","Whisk the crème fraîche, mustard and beef stock together, then pour into the pan.","Cook over a medium heat for around 5 mins.","Scatter with parsley, then serve with pappardelle or rice."],"ingredient_names":["olive oil","onions","garlic","butter","mushrooms","beef fillet","plain flour","creme fraiche","english mustard","beef stock","parsley"],"allergens":["dairy","gluten"],"diet_flags":[]},{"source_id":"52835","title":"Fettucine alfredo","category":"Pasta","country":"Italy","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/uquqtu1511178042.jpg","youtube_url":"https://www.youtube.com/watch?v=FLEnwZvGzOE","source_url":"https://www.bbcgoodfood.com/recipes/fettucine-alfredo","ingredients":[{"name":"Clotted Cream","measure":"227g"},{"name":"Butter","measure":"25g"},{"name":"Corn Flour","measure":"1 tsp"},{"name":"Parmesan Cheese","measure":"100g"},{"name":"Nutmeg","measure":"Grated"},{"name":"Fettuccine","measure":"250g"},{"name":"Parsley","measure":"Chopped"}],"steps":["In a medium saucepan, stir the clotted cream, butter and cornflour over a low-ish heat and bring to a low simmer. Turn off the heat and keep warm.","Meanwhile, put the cheese and nutmeg in a small bowl and add a good grinding of black pepper, then stir everything together (don’t add any salt at this stage).","Put the pasta in another pan with 2 tsp salt, pour over some boiling water and cook following pack instructions (usually 3-4 mins). When cooked, scoop some of the cooking water into a heatproof jug or mug and drain the pasta, but not too thoroughly.","Add the pasta to the pan with the clotted cream mixture, then sprinkle over the cheese and gently fold everything together over a low heat using a rubber spatula. When combined, splash in 3 tbsp of the cooking water. At first, the pasta will look wet and sloppy: keep stirring until the water is absorbed and the sauce is glossy. Check the seasoning before transferring to heated bowls. Sprinkle over some chives or parsley, then serve immediately."],"ingredient_names":["clotted cream","butter","corn flour","parmesan cheese","nutmeg","fettuccine","parsley"],"allergens":["dairy","gluten"],"diet_flags":["pescatarian","vegetarian"]},{"source_id":"52836","title":"Seafood fideuà","category":"Seafood","country":"Spain","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/wqqvyq1511179730.jpg","youtube_url":"https://www.youtube.com/watch?v=itsFEc8W468","source_url":"https://www.bbcgoodfood.com/recipes/seafood-fideua-paella","ingredients":[{"name":"Mussels","measure":"400g"},{"name":"Prawns","measure":"8"},{"name":"Saffron","measure":"2 pinches"},{"name":"Vermicelli Pasta","measure":"350g"},{"name":"Olive Oil","measure":"5 tblsp"},{"name":"Onions","measure":"1 large"},{"name":"Garlic","measure":"3 cloves"},{"name":"Paprika","measure":"2 tbs"},{"name":"Monkfish","measure":"1 tail"},{"name":"Baby Squid","measure":"4"},{"name":"Fish Stock","measure":"650ml"},{"name":"Tomatoes","measure":"2 large"},{"name":"Lemon","measure":"Juice of 1"},{"name":"Parsley","measure":"Topping"}],"steps":["Boil the kettle. Empty the mussels into a colander and run under cold water. Throw away any with broken shells. Pick through the shells, tapping each one on the side of the sink – they should be closed or should slowly close when tapped – if they stay open, throw them away. If any of the shells still have barnacles or stringy beards attached, pull them off with a cutlery knife and rinse the shells well. Keep in the colander, covered with a cold, damp cloth, until you’re ready to cook. Peel the prawn shells on the body section only – leave the heads and tails intact. Score down the backs and pull out any gritty entrails. Chill until you’re ready to cook.","Put the saffron in a small cup, cover with 50ml kettle-hot water and set aside for 10 mins. If using vermicelli, put in a bowl and crush to little pieces (about 1cm long) with your hands.","Heat the oil in a large frying pan with at least a 3cm lip, or a 40cm paella pan. Add the onion and stir around the pan for 5 mins until soft. Add the garlic and cook for 1 min more, then tip in the vermicelli and cook for 5 mins, stirring from time to time, until the vermicelli is toasted brown. Stir in the paprika.","Keeping the heat moderate, stir through the monkfish, squid and saffron with its water, seasoning well. Spread the ingredients out in an even layer, then pour over the hot stock and scatter the tomatoes on top. Bring to a simmer, then cover the whole dish with a tight-fitting lid (or foil). Turn the heat to medium and cook for 6 mins.","Uncover and stir to incorporate the dry top layer of pasta. Push the mussels into the pasta so the hinges are buried in the bottom of the dish, and they stand straight up. Arrange the prawns on top, cover tightly and cook for another 6 mins or until the mussels are open, the prawns are pink and the pasta is cooked through. Leave to simmer for another 2-3 mins to cook off most of the remaining liquid (leave a little in the pan to prevent the pasta from sticking together). Allow to sit for 2-3 mins, then squeeze over the lemon juice and arrange the wedges on top. Scatter with parsley before serving."],"ingredient_names":["mussels","prawns","saffron","vermicelli pasta","olive oil","onions","garlic","paprika","monkfish","baby squid","fish stock","tomatoes","lemon","parsley"],"allergens":["fish","gluten","shellfish"],"diet_flags":["pescatarian"]},{"source_id":"52837","title":"Pilchard puttanesca","category":"Pasta","country":"Italy","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/vvtvtr1511180578.jpg","youtube_url":"https://www.youtube.com/watch?v=wqZzLAPmr9k","source_url":"https://www.bbcgoodfood.com/recipes/pilchard-puttanesca","ingredients":[{"name":"Spaghetti","measure":"300g"},{"name":"Olive Oil","measure":"1 tbls"},{"name":"Onion","measure":"1 finely chopped"},{"name":"Garlic","measure":"2 cloves minced"},{"name":"Red Chilli","measure":"1"},{"name":"Tomato Puree","measure":"1 tbls"},{"name":"Pilchards","measure":"425g"},{"name":"Black Olives","measure":"70g"},{"name":"Parmesan","measure":"Shaved"}],"steps":["Cook the pasta following pack instructions.","Heat the oil in a non-stick frying pan and cook the onion, garlic and chilli for 3-4 mins to soften.","Stir in the tomato purée and cook for 1 min, then add the pilchards with their sauce.","Cook, breaking up the fish with a wooden spoon, then add the olives and continue to cook for a few more mins.","Drain the pasta and add to the pan with 2-3 tbsp of the cooking water.","Toss everything together well, then divide between plates and serve, scattered with Parmesan."],"ingredient_names":["spaghetti","olive oil","onion","garlic","red chilli","tomato puree","pilchards","black olives","parmesan"],"allergens":["dairy","fish","gluten"],"diet_flags":["pescatarian"]},{"source_id":"52838","title":"Venetian Duck Ragu","category":"Pasta","country":"Italy","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/qvrwpt1511181864.jpg","youtube_url":"https://www.youtube.com/watch?v=oWQDVgjB_Lw","source_url":"https://www.bbcgoodfood.com/recipes/venetian-duck-ragu","ingredients":[{"name":"Olive Oil","measure":"1 tbls"},{"name":"Duck Legs","measure":"4"},{"name":"Onions","measure":"2 finely chopped"},{"name":"Garlic","measure":"2 cloves minced"},{"name":"Cinnamon","measure":"2 tsp ground"},{"name":"Plain Flour","measure":"2 tsp"},{"name":"Red Wine","measure":"250ml"},{"name":"Chopped Tomatoes","measure":"800g"},{"name":"Chicken Stock Cube","measure":"1"},{"name":"Rosemary","measure":"3 sprigs"},{"name":"Bay Leaves","measure":"2"},{"name":"Sugar","measure":"1 tsp"},{"name":"Milk","measure":"2 tbs"},{"name":"Paccheri Pasta","measure":"600g"},{"name":"Parmesan Cheese","measure":"Grated"}],"steps":["Heat the oil in a large pan. Add the duck legs and brown on all sides for about 10 mins. Remove to a plate and set aside. Add the onions to the pan and cook for 5 mins until softened. Add the garlic and cook for a further 1 min, then stir in the cinnamon and flour and cook for a further min. Return the duck to the pan, add the wine, tomatoes, stock, herbs, sugar and seasoning. Bring to a simmer, then lower the heat, cover with a lid and cook for 2 hrs, stirring every now and then.","Carefully lift the duck legs out of the sauce and place on a plate – they will be very tender so try not to lose any of the meat. Pull off and discard the fat, then shred the meat with 2 forks and discard the bones. Add the meat back to the sauce with the milk and simmer, uncovered, for a further 10-15 mins while you cook the pasta.","Cook the pasta following pack instructions, then drain, reserving a cup of the pasta water, and add the pasta to the ragu. Stir to coat all the pasta in the sauce and cook for 1 min more, adding a splash of cooking liquid if it looks dry. Serve with grated Parmesan, if you like."],"ingredient_names":["olive oil","duck legs","onions","garlic","cinnamon","plain flour","red wine","chopped tomatoes","chicken stock cube","rosemary","bay leaves","sugar","milk","paccheri pasta","parmesan cheese"],"allergens":["dairy","gluten"],"diet_flags":[]},{"source_id":"52839","title":"Chilli prawn linguine","category":"Pasta","country":"Italy","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/usywpp1511189717.jpg","youtube_url":"https://www.youtube.com/watch?v=SC17Mc70Db0","source_url":"https://www.bbcgoodfood.com/recipes/1269/chilli-prawn-linguine","ingredients":[{"name":"Linguine Pasta","measure":"280g"},{"name":"Sugar Snap Peas","measure":"200g"},{"name":"Olive Oil","measure":"2 tblsp"},{"name":"Garlic Clove","measure":"2 cloves chopped"},{"name":"Red Chilli","measure":"1 large"},{"name":"King Prawns","measure":"24 Skinned"},{"name":"Cherry Tomatoes","measure":"12"},{"name":"Basil Leaves","measure":"Handful"},{"name":"Lettuce","measure":"Leaves"},{"name":"Bread","measure":"to serve"},{"name":"Fromage Frais","measure":"2 tbsp"},{"name":"Lime","measure":"Grated Zest of 2"},{"name":"Caster Sugar","measure":"2 tsp"}],"steps":["Mix the dressing ingredients in a small bowl and season with salt and pepper. Set aside.","Cook the pasta according to the packet instructions. Add the sugar snap peas for the last minute or so of cooking time.","Meanwhile, heat the oil in a wok or large frying pan, toss in the garlic and chilli and cook over a fairly gentle heat for about 30 seconds without letting the garlic brown. Tip in the prawns and cook over a high heat, stirring frequently, for about 3 minutes until they turn pink.","Add the tomatoes and cook, stirring occasionally, for 3 minutes until they just start to soften. Drain the pasta and sugar snaps well, then toss into the prawn mixture. Tear in the basil leaves, stir, and season with salt and pepper.","Serve with salad leaves drizzled with the lime dressing, and warm crusty bread."],"ingredient_names":["linguine pasta","sugar snap peas","olive oil","garlic clove","red chilli","king prawns","cherry tomatoes","basil leaves","lettuce","bread","fromage frais","lime","caster sugar"],"allergens":["gluten","shellfish"],"diet_flags":["pescatarian"]},{"source_id":"52843","title":"Lamb Tagine","category":"Lamb","country":"Morocco","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/yuwtuu1511295751.jpg","youtube_url":"https://www.youtube.com/watch?v=bR5Cqu84S_k","source_url":"https://www.bbcgoodfood.com/recipes/2303638/family-meals-easy-lamb-tagine-","ingredients":[{"name":"Olive Oil","measure":"2 tblsp"},{"name":"Onion","measure":"1 finely sliced"},{"name":"Carrots","measure":"2 chopped"},{"name":"Lamb Leg","measure":"500g"},{"name":"Garlic","measure":"2 cloves minced"},{"name":"Cumin","measure":"½ tsp"},{"name":"Ginger","measure":"½ tsp"},{"name":"Saffron","measure":"¼ tsp"},{"name":"Cinnamon","measure":"1 tsp"},{"name":"Honey","measure":"1 tblsp"},{"name":"Apricot","measure":"100g"},{"name":"Vegetable Stock Cube","measure":"1"},{"name":"Butternut Squash","measure":"1 medium chopped"},{"name":"Couscous","measure":"Steamed"},{"name":"Parsley","measure":"Chopped"}],"steps":["Heat the olive oil in a heavy-based pan and add the onion and carrot. Cook for 3- 4 mins until softened.","Add the diced lamb and brown all over. Stir in the garlic and all the spices and cook for a few mins more or until the aromas are released.","Add the honey and apricots, crumble in the stock cube and pour over roughly 500ml boiling water or enough to cover the meat. Give it a good stir and bring to the boil. Turn down to a simmer, put the lid on and cook for 1 hour.","Remove the lid and cook for a further 30 mins, then stir in the squash. Cook for 20 – 30 mins more until the squash is soft and the lamb is tender. Serve alongside rice or couscous and sprinkle with parsley and pine nuts, if using."],"ingredient_names":["olive oil","onion","carrots","lamb leg","garlic","cumin","ginger","saffron","cinnamon","honey","apricot","vegetable stock cube","butternut squash","couscous","parsley"],"allergens":["gluten"],"diet_flags":[]},{"source_id":"52844","title":"Lasagne","category":"Pasta","country":"Italy","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/wtsvxx1511296896.jpg","youtube_url":"https://www.youtube.com/watch?v=gfhfsBPt46s","source_url":"https://www.bbcgoodfood.com/recipes/classic-lasagne","ingredients":[{"name":"Olive Oil","measure":"1 tblsp"},{"name":"Bacon","measure":"2"},{"name":"Onion","measure":"1 finely chopped"},{"name":"Celery","measure":"1 Stick"},{"name":"Carrots","measure":"1 medium"},{"name":"Garlic","measure":"2 cloves chopped"},{"name":"Minced Beef","measure":"500g"},{"name":"Tomato Puree","measure":"1 tbls"},{"name":"Chopped Tomatoes","measure":"800g"},{"name":"Honey","measure":"1 tblsp"},{"name":"Lasagne Sheets","measure":"500g"},{"name":"Creme Fraiche","measure":"400ml"},{"name":"Mozzarella Balls","measure":"125g"},{"name":"Parmesan Cheese","measure":"50g"},{"name":"Basil Leaves","measure":"Topping"}],"steps":["Heat the oil in a large saucepan. Use kitchen scissors to snip the bacon into small pieces, or use a sharp knife to chop it on a chopping board. Add the bacon to the pan and cook for just a few mins until starting to turn golden. Add the onion, celery and carrot, and cook over a medium heat for 5 mins, stirring occasionally, until softened.","Add the garlic and cook for 1 min, then tip in the mince and cook, stirring and breaking it up with a wooden spoon, for about 6 mins until browned all over.","Stir in the tomato purée and cook for 1 min, mixing in well with the beef and vegetables. Tip in the chopped tomatoes. Fill each can half full with water to rinse out any tomatoes left in the can, and add to the pan. Add the honey and season to taste. Simmer for 20 mins.","Heat oven to 200C/180C fan/gas 6. To assemble the lasagne, ladle a little of the ragu sauce into the bottom of the roasting tin or casserole dish, spreading the sauce all over the base. Place 2 sheets of lasagne on top of the sauce overlapping to make it fit, then repeat with more sauce and another layer of pasta. Repeat with a further 2 layers of sauce and pasta, finishing with a layer of pasta.","Put the crème fraîche in a bowl and mix with 2 tbsp water to loosen it and make a smooth pourable sauce. Pour this over the top of the pasta, then top with the mozzarella. Sprinkle Parmesan over the top and bake for 25–30 mins until golden and bubbling. Serve scattered with basil, if you like."],"ingredient_names":["olive oil","bacon","onion","celery","carrots","garlic","minced beef","tomato puree","chopped tomatoes","honey","lasagne sheets","creme fraiche","mozzarella balls","parmesan cheese","basil leaves"],"allergens":["dairy","gluten"],"diet_flags":[]},{"source_id":"52846","title":"Chicken & mushroom Hotpot","category":"Chicken","country":"United Kingdom","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/uuuspp1511297945.jpg","youtube_url":"https://www.youtube.com/watch?v=bXKWu4GojNI","source_url":"https://www.bbcgoodfood.com/recipes/chicken-mushroom-hot-pot","ingredients":[{"name":"Butter","measure":"50g"},{"name":"Onion","measure":"1 chopped"},{"name":"Mushrooms","measure":"100g"},{"name":"Plain Flour","measure":"40g"},{"name":"Chicken Stock Cube","measure":"1"},{"name":"Nutmeg","measure":"pinch"},{"name":"Mustard Powder","measure":"pinch"},{"name":"Chicken","measure":"250g"},{"name":"Sweetcorn","measure":"2 Handfuls"},{"name":"Potatoes","measure":"2 large"},{"name":"Butter","measure":"1 knob"}],"steps":["Heat oven to 200C/180C fan/gas 6. Put the butter in a medium-size saucepan and place over a medium heat. Add the onion and leave to cook for 5 mins, stirring occasionally. Add the mushrooms to the saucepan with the onions.","Once the onion and mushrooms are almost cooked, stir in the flour – this will make a thick paste called a roux. If you are using a stock cube, crumble the cube into the roux now and stir well. Put the roux over a low heat and stir continuously for 2 mins – this will cook the flour and stop the sauce from having a floury taste.","Take the roux off the heat. Slowly add the fresh stock, if using, or pour in 500ml water if you’ve used a stock cube, stirring all the time. Once all the liquid has been added, season with pepper, a pinch of nutmeg and mustard powder. Put the saucepan back onto a medium heat and slowly bring it to the boil, stirring all the time. Once the sauce has thickened, place on a very low heat. Add the cooked chicken and vegetables to the sauce and stir well. Grease a medium-size ovenproof pie dish with a little butter and pour in the chicken and mushroom filling.","Carefully lay the potatoes on top of the hot-pot filling, overlapping them slightly, almost like a pie top.","Brush the potatoes with a little melted butter and cook in the oven for about 35 mins. The hot-pot is ready once the potatoes are cooked and golden brown."],"ingredient_names":["butter","onion","mushrooms","plain flour","chicken stock cube","nutmeg","mustard powder","chicken","sweetcorn","potatoes","butter"],"allergens":["dairy","gluten"],"diet_flags":[]},{"source_id":"52847","title":"Pork Cassoulet","category":"Pork","country":"France","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/wxuvuv1511299147.jpg","youtube_url":"https://www.youtube.com/watch?v=MEdHMTD0VCA","source_url":"https://www.bbcgoodfood.com/recipes/jacks-pork-cassoulet","ingredients":[{"name":"Goose Fat","measure":"4 tbsp"},{"name":"Pork","measure":"350g"},{"name":"Onion","measure":"1 large"},{"name":"Garlic","measure":"10"},{"name":"Carrots","measure":"1 thinly sliced"},{"name":"Fennel Seeds","measure":"1 tsp"},{"name":"Red Wine Vinegar","measure":"2 tblsp"},{"name":"Vegetable Stock","measure":"600ml"},{"name":"Tomato Puree","measure":"1 tblsp"},{"name":"Rosemary","measure":"2 sticks"},{"name":"Parsley","measure":"Handful"},{"name":"Haricot Beans","measure":"400g"},{"name":"Breadcrumbs","measure":"2 tblsp"},{"name":"Oil","measure":"drizzle"},{"name":"Bread","measure":"to serve"},{"name":"Broccoli","measure":"to serve"}],"steps":["Heat oven to 140C/120C fan/gas 1. Put a large ovenproof pan (with a tight-fitting lid) on a high heat. Add your fat and diced meat, cook for a few mins to seal the edges, giving it a quick stir to cook evenly. Reduce the heat to low, add the sliced onion, whole garlic cloves, carrot and fennel seeds, and cook gently to soften the veg for a few mins.","Pour over the red wine vinegar, scraping any meaty bits off the bottom of the pan. Add the stock, tomato purée, and half the rosemary and parsley. Bring to the boil and simmer for 10 mins, then season, cover with a lid and put into the oven for 2 hrs, removing the lid for the final hour of cooking. Stir occasionally and add the beans with 30 mins to go.","Remove the pan from the oven and heat the grill. Scatter the top with the remaining herbs and breadcrumbs, drizzle a little oil over the top, and return to the oven for 5-10 mins, until the breadcrumbs are golden. Serve with crusty bread and green veg."],"ingredient_names":["goose fat","pork","onion","garlic","carrots","fennel seeds","red wine vinegar","vegetable stock","tomato puree","rosemary","parsley","haricot beans","breadcrumbs","oil","bread","broccoli"],"allergens":["gluten"],"diet_flags":[]},{"source_id":"52849","title":"Spinach & Ricotta Cannelloni","category":"Vegetarian","country":"Italy","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/wspuvp1511303478.jpg","youtube_url":"https://www.youtube.com/watch?v=rYGaEJjyLQA","source_url":"https://www.bbcgoodfood.com/recipes/531632/spinach-and-ricotta-cannelloni","ingredients":[{"name":"Olive Oil","measure":"3 tbsp"},{"name":"Garlic","measure":"8 cloves chopped"},{"name":"Caster Sugar","measure":"3 tbsp"},{"name":"Red Wine Vinegar","measure":"2 tblsp"},{"name":"Chopped Tomatoes","measure":"3 400g Cans"},{"name":"Basil Leaves","measure":"Bunch"},{"name":"Mascarpone","measure":"2 tubs"},{"name":"Milk","measure":"3 tbsp"},{"name":"Parmesan","measure":"85g"},{"name":"Mozzarella","measure":"2 sliced"},{"name":"Spinach","measure":"1kg"},{"name":"Parmesan","measure":"100g"},{"name":"Ricotta","measure":"3 tubs"},{"name":"Nutmeg","measure":"pinch"},{"name":"Cannellini Beans","measure":"400g"}],"steps":["First make the tomato sauce. Heat the oil in a large pan and fry the garlic for 1 min. Add the sugar, vinegar, tomatoes and some seasoning and simmer for 20 mins, stirring occasionally, until thick. Add the basil and divide the sauce between 2 or more shallow ovenproof dishes (see Tips for freezing, below). Set aside. Make a sauce by beating the mascarpone with the milk until smooth, season, then set aside.","Put the spinach in a large colander and pour over a kettle of boiling water to wilt it (you may need to do this in batches). When cool enough to handle squeeze out the excess water. Roughly chop the spinach and mix in a large bowl with 100g Parmesan and ricotta. Season well with salt, pepper and the nutmeg.","Heat oven to 200C/180C fan/gas 6. Using a piping bag or plastic food bag with the corner snipped off, squeeze the filling into the cannelloni tubes. Lay the tubes, side by side, on top of the tomato sauce and spoon over the mascarpone sauce. Top with Parmesan and mozzarella. You can now freeze the cannelloni, uncooked, or you can cook it first and then freeze. Bake for 30-35 mins until golden and bubbling. Remove from oven and let stand for 5 mins before serving."],"ingredient_names":["olive oil","garlic","caster sugar","red wine vinegar","chopped tomatoes","basil leaves","mascarpone","milk","parmesan","mozzarella","spinach","parmesan","ricotta","nutmeg","cannellini beans"],"allergens":["dairy"],"diet_flags":["pescatarian","vegetarian"]},{"source_id":"52850","title":"Chicken Couscous","category":"Chicken","country":"Morocco","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/qxytrx1511304021.jpg","youtube_url":"https://www.youtube.com/watch?v=GZQGy9oscVk","source_url":"https://www.bbcgoodfood.com/recipes/13139/onepan-chicken-couscous","ingredients":[{"name":"Olive Oil","measure":"1 tbsp"},{"name":"Onion","measure":"1 chopped"},{"name":"Chicken Breast","measure":"200g"},{"name":"Ginger","measure":"pinch"},{"name":"Harissa Spice","measure":"2 tblsp"},{"name":"Dried Apricots","measure":"10"},{"name":"Chickpeas","measure":"220g"},{"name":"Couscous","measure":"200g"},{"name":"Chicken Stock","measure":"200ml"},{"name":"Coriander","measure":"Handful"}],"steps":["Heat the olive oil in a large frying pan and cook the onion for 1-2 mins just until softened.","Add the chicken and fry for 7-10 mins until cooked through and the onions have turned golden.","Grate over the ginger, stir through the harissa to coat everything and cook for 1 min more.","Tip in the apricots, chickpeas and couscous, then pour over the stock and stir once.","Cover with a lid or tightly cover the pan with foil and leave for about 5 mins until the couscous has soaked up all the stock and is soft.","Fluff up the couscous with a fork and scatter over the coriander to serve.","Serve with extra harissa, if you like."],"ingredient_names":["olive oil","onion","chicken breast","ginger","harissa spice","dried apricots","chickpeas","couscous","chicken stock","coriander"],"allergens":["gluten"],"diet_flags":[]},{"source_id":"52851","title":"Nutty Chicken Curry","category":"Chicken","country":"India","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/yxsurp1511304301.jpg","youtube_url":"https://www.youtube.com/watch?v=nSQNfZxOdeU","source_url":"https://www.bbcgoodfood.com/recipes/11753/nutty-chicken-curry","ingredients":[{"name":"Red Chilli","measure":"1 large"},{"name":"Ginger","measure":"0.5"},{"name":"Garlic","measure":"1 large"},{"name":"Coriander","measure":"Bunch"},{"name":"Sunflower Oil","measure":"1 tbsp"},{"name":"Chicken Breasts","measure":"4"},{"name":"Peanut Butter","measure":"5 tblsp"},{"name":"Chicken Stock","measure":"150ml"},{"name":"Greek Yogurt","measure":"200g"}],"steps":["Finely slice a quarter of the chilli, then put the rest in a food processor with the ginger, garlic, coriander stalks and one-third of the leaves.","Whizz to a rough paste with a splash of water if needed.","Heat the oil in a frying pan, then quickly brown the chicken chunks for 1 min.","Stir in the paste for another min, then add the peanut butter, stock and yogurt.","When the sauce is gently bubbling, cook for 10 mins until the chicken is just cooked through and sauce thickened.","Stir in most of the remaining coriander, then scatter the rest on top with the chilli, if using.","Eat with rice or mashed sweet potato."],"ingredient_names":["red chilli","ginger","garlic","coriander","sunflower oil","chicken breasts","peanut butter","chicken stock","greek yogurt"],"allergens":["dairy","peanuts"],"diet_flags":[]},{"source_id":"52852","title":"Tuna Nicoise","category":"Seafood","country":"France","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/yypwwq1511304979.jpg","youtube_url":"https://www.youtube.com/watch?v=3_UAxkx0u6U","source_url":"https://www.bbcgoodfood.com/recipes/9529/winter-tuna-nioise","ingredients":[{"name":"Potatoes","measure":"450g"},{"name":"Olive Oil","measure":"2 tblsp"},{"name":"Eggs","measure":"4"},{"name":"Red Wine Vinegar","measure":"1 tbls"},{"name":"Capers","measure":"2 tblsp"},{"name":"Sunflower Oil","measure":"50g"},{"name":"Red Onions","measure":"½"},{"name":"Spinach","measure":"100g"},{"name":"Tuna","measure":"400g"}],"steps":["Heat oven to 200C/fan 180C/gas 6. Toss the potatoes with 2 tsp oil and some seasoning. Tip onto a large baking tray, then roast for 20 mins, stirring halfway, until crisp, golden and cooked through.","Meanwhile, put eggs in a small pan of water, bring to the boil, then simmer for 8-10 mins, depending on how you like them cooked. Plunge into a bowl of cold water to cool for a few mins. Peel away the shells, then cut into halves.","In a large salad bowl, whisk together the remaining oil, red wine vinegar, capers and chopped tomatoes. Season, tip in the onion, spinach, tuna and potatoes, then gently toss together. Top with the eggs, then serve straight away."],"ingredient_names":["potatoes","olive oil","eggs","red wine vinegar","capers","sunflower oil","red onions","spinach","tuna"],"allergens":["eggs","fish"],"diet_flags":["pescatarian"]},{"source_id":"52863","title":"Vegetarian Casserole","category":"Vegetarian","country":"United Kingdom","tags":["Casserole","Vegetarian"],"image_url":"https://www.themealdb.com/images/media/meals/vptwyt1511450962.jpg","youtube_url":"https://www.youtube.com/watch?v=oHmKE9mWtWM","source_url":"https://www.bbcgoodfood.com/recipes/1993645/vegetarian-casserole","ingredients":[{"name":"Rapeseed Oil","measure":"1"},{"name":"Onion","measure":"1"},{"name":"Garlic","measure":"3 cloves"},{"name":"Paprika","measure":"1 tsp"},{"name":"Cumin","measure":"½ tsp"},{"name":"Thyme","measure":"1 tblsp"},{"name":"Carrots","measure":"3 Medium"},{"name":"Celery","measure":"2 small stalks"},{"name":"Red Pepper","measure":"1"},{"name":"Yellow Pepper","measure":"1"},{"name":"Tomato","measure":"2 x 400g tins"},{"name":"Vegetable Stock Cube","measure":"250ml"},{"name":"Courgettes","measure":"2 sliced"},{"name":"Thyme","measure":"2 sprigs"},{"name":"Lentils","measure":"250g"}],"steps":["Heat the oil in a large, heavy-based pan. Add the onions and cook gently for 5 – 10 mins until softened.","Add the garlic, spices, dried thyme, carrots, celery and peppers and cook for 5 minutes.","Add the tomatoes, stock, courgettes and fresh thyme and cook for 20 - 25 minutes.","Take out the thyme sprigs. Stir in the lentils and bring back to a simmer. Serve with wild and white basmati rice, mash or quinoa."],"ingredient_names":["rapeseed oil","onion","garlic","paprika","cumin","thyme","carrots","celery","red pepper","yellow pepper","tomato","vegetable stock cube","courgettes","thyme","lentils"],"allergens":[],"diet_flags":["pescatarian","vegan","vegetarian"]},{"source_id":"52864","title":"Mushroom & Chestnut Rotolo","category":"Vegetarian","country":"United Kingdom","tags":["Vegetarian","Nutty"],"image_url":"https://www.themealdb.com/images/media/meals/ssyqwr1511451678.jpg","youtube_url":"https://www.youtube.com/watch?v=GNN7_ZSJ5YE","source_url":"https://www.bbcgoodfood.com/recipes/mushroom-chestnut-rotolo","ingredients":[{"name":"Mushrooms","measure":"30g"},{"name":"Chestnuts","measure":"240g"},{"name":"Challots","measure":"3"},{"name":"Garlic","measure":"3 cloves"},{"name":"Rosemary","measure":"3 sprigs"},{"name":"Wild Mushrooms","measure":"500g"},{"name":"Soy Sauce","measure":"2 tblsp"},{"name":"White Wine","measure":"125ml"},{"name":"Lasagne Sheets","measure":"350g"},{"name":"Breadcrumbs","measure":"4 tbsp"},{"name":"Sage","measure":"1/2 handful"},{"name":"Truffle Oil","measure":"to serve"}],"steps":["Soak the dried mushrooms in 350ml boiling water and set aside until needed. Blitz ¾ of the chestnuts with 150ml water until creamy. Roughly chop the remaining chestnuts.","Heat 2 tbsp olive oil in a large non-stick frying pan. Fry the shallots with a pinch of salt until softened, then add the garlic, chopped chestnuts and rosemary, and fry for 2 mins more. Add the wild mushrooms, 2 tbsp oil and some seasoning. Cook for 3 mins until they begin to soften. Drain and roughly chop the dried mushrooms (reserve the soaking liquid), then add those too, along with the soy sauce, and fry for 2 mins more.","Whisk the wine, reserved mushroom liquid and chestnut cream together to create a sauce. Season, then add half to the mushroom mixture in the pan and cook for 1 min until the sauce becomes glossy. Remove and discard the rosemary sprigs, then set the mixture aside.","Heat oven to 180C/160C fan/gas 4. Bring a large pan of salted water to the boil and get a large bowl of ice water ready. Drop the lasagne sheets into the boiling water for 2 mins or until pliable and a little cooked, then immediately plunge them into the cold water. Using your fingers, carefully separate the sheets and transfer to a clean tea towel. Spread a good spoonful of the sauce on the bottom two thirds of each sheet, then, rolling away from yourself, roll up the shorter ends. Cut each roll in half, then position the rolls of pasta cut-side up in a pie dish that you are happy to serve from at the table. If you have any mushroom sauce remaining after you’ve rolled up all the sheets, simply push it into some of the exposed rolls of pasta.","Pour the rest of the sauce over the top of the pasta, then bake for 10 mins or until the pasta no longer has any resistance when tested with a skewer.","Meanwhile, put the breadcrumbs, the last 2 tbsp olive oil, sage leaves and some seasoning in a bowl, and toss everything together. Scatter the rotolo with the crumbs and sage, then bake for another 10 mins, until the top is golden and the sage leaves are crispy. Leave to cool for 10 mins to allow the pasta to absorb the sauce, then drizzle with a little truffle oil, if you like, before taking your dish to the table."],"ingredient_names":["mushrooms","chestnuts","challots","garlic","rosemary","wild mushrooms","soy sauce","white wine","lasagne sheets","breadcrumbs","sage","truffle oil"],"allergens":["gluten","soy","tree_nuts"],"diet_flags":["pescatarian","vegan","vegetarian"]},{"source_id":"52865","title":"Matar Paneer","category":"Vegetarian","country":"India","tags":["Curry","Vegetarian"],"image_url":"https://www.themealdb.com/images/media/meals/xxpqsy1511452222.jpg","youtube_url":"https://www.youtube.com/watch?v=wlseYNqwLNs","source_url":"https://www.bbcgoodfood.com/recipes/matar-paneer","ingredients":[{"name":"Sunflower Oil","measure":"1 tbls"},{"name":"Paneer","measure":"225g"},{"name":"Ginger","measure":"2"},{"name":"Cumin","measure":"1 tsp"},{"name":"Turmeric","measure":"1 tsp"},{"name":"Coriander","measure":"1 tsp"},{"name":"Green Chilli","measure":"1"},{"name":"Tomato","measure":"4 large"},{"name":"Peas","measure":"150g"},{"name":"Garam Masala","measure":"1 tsp"},{"name":"Coriander","measure":"Small bunch"},{"name":"Naan Bread","measure":"to serve"}],"steps":["Heat the oil in a frying pan over high heat until it’s shimmering hot.","Add the paneer, then turn the heat down a little.","Fry until it starts to brown at the edges, then turn it over and brown on each side – the paneer will brown faster than you think, so don’t walk away.","Remove the paneer from the pan and drain on kitchen paper.","Put the ginger, cumin, turmeric, ground coriander and chilli in the pan, and fry everything for 1 min.","Add the tomatoes, mashing them with the back of a spoon and simmer everything for 5 mins until the sauce smells fragrant.","Add a splash of water if it’s too thick. Season well.","Add the peas and simmer for a further 2 mins, then stir in the paneer and sprinkle over the garam masala.","Divide between two bowls, top with coriander leaves and serve with naan bread, roti or rice."],"ingredient_names":["sunflower oil","paneer","ginger","cumin","turmeric","coriander","green chilli","tomato","peas","garam masala","coriander","naan bread"],"allergens":["dairy","gluten"],"diet_flags":["pescatarian","vegetarian"]},{"source_id":"52866","title":"Squash linguine","category":"Vegetarian","country":"Italy","tags":["Pasta","Light"],"image_url":"https://www.themealdb.com/images/media/meals/wxswxy1511452625.jpg","youtube_url":"https://www.youtube.com/watch?v=xHZ-PoGwTLQ","source_url":"https://www.bbcgoodfood.com/recipes/creamy-squash-linguine","ingredients":[{"name":"Butternut Squash","measure":"350g"},{"name":"Garlic","measure":"3 parts"},{"name":"Olive Oil","measure":"3 tbs"},{"name":"Linguine Pasta","measure":"350g"},{"name":"Sage","measure":"Small bunch"}],"steps":["Heat oven to 200C/180C fan/gas 6.","Put the squash and garlic on a baking tray and drizzle with the olive oil.","Roast for 35-40 mins until soft. Season.","Cook the pasta according to pack instructions.","Drain, reserving the water.","Use a stick blender to whizz the squash with 400ml cooking water.","Heat some oil in a frying pan, fry the sage until crisp, then drain on kitchen paper.","Tip the pasta and sauce into the pan and warm through. Scatter with sage."],"ingredient_names":["butternut squash","garlic","olive oil","linguine pasta","sage"],"allergens":["gluten"],"diet_flags":["pescatarian","vegan","vegetarian"]},{"source_id":"52867","title":"Vegetarian Chilli","category":"Vegetarian","country":"United Kingdom","tags":["Chilli"],"image_url":"https://www.themealdb.com/images/media/meals/wqurxy1511453156.jpg","youtube_url":"https://www.youtube.com/watch?v=D0bFRVH_EqU","source_url":"https://www.bbcgoodfood.com/recipes/veggie-chilli","ingredients":[{"name":"Roasted Vegetables","measure":"400g"},{"name":"Kidney Beans","measure":"1 can"},{"name":"Chopped Tomatoes","measure":"1 can"},{"name":"Mixed Grain","measure":"1 Packet"}],"steps":["Heat oven to 200C/180C fan/ gas 6. Cook the vegetables in a casserole dish for 15 mins. Tip in the beans and tomatoes, season, and cook for another 10-15 mins until piping hot. Heat the pouch in the microwave on High for 1 min and serve with the chilli."],"ingredient_names":["roasted vegetables","kidney beans","chopped tomatoes","mixed grain"],"allergens":[],"diet_flags":["pescatarian","vegan","vegetarian"]},{"source_id":"52868","title":"Kidney Bean Curry","category":"Vegetarian","country":"India","tags":["Curry"],"image_url":"https://www.themealdb.com/images/media/meals/sywrsu1511463066.jpg","youtube_url":"https://www.youtube.com/watch?v=Tp_PMWvIKzo","source_url":"https://www.bbcgoodfood.com/recipes/kidney-bean-curry","ingredients":[{"name":"Vegetable Oil","measure":"1 tbls"},{"name":"Onion","measure":"1 finely chopped"},{"name":"Garlic","measure":"2 cloves chopped"},{"name":"Ginger","measure":"1 part"},{"name":"Coriander","measure":"1 Packet"},{"name":"Cumin","measure":"1 tsp"},{"name":"Paprika","measure":"1 tsp"},{"name":"Garam Masala","measure":"2 tsp"},{"name":"Chopped Tomatoes","measure":"400g"},{"name":"Kidney Beans","measure":"400g"},{"name":"Basmati Rice","measure":"to serve"}],"steps":["Heat the oil in a large frying pan over a low-medium heat. Add the onion and a pinch of salt and cook slowly, stirring occasionally, until softened and just starting to colour. Add the garlic, ginger and coriander stalks and cook for a further 2 mins, until fragrant.","Add the spices to the pan and cook for another 1 min, by which point everything should smell aromatic. Tip in the chopped tomatoes and kidney beans in their water, then bring to the boil.","Turn down the heat and simmer for 15 mins until the curry is nice and thick. Season to taste, then serve with the basmati rice and the coriander leaves."],"ingredient_names":["vegetable oil","onion","garlic","ginger","coriander","cumin","paprika","garam masala","chopped tomatoes","kidney beans","basmati rice"],"allergens":[],"diet_flags":["pescatarian","vegan","vegetarian"]},{"source_id":"52869","title":"Tahini Lentils","category":"Vegetarian","country":"Morocco","tags":["Pulse"],"image_url":"https://www.themealdb.com/images/media/meals/vpxyqt1511464175.jpg","youtube_url":"https://www.youtube.com/watch?v=8kRlmz8pW0I","source_url":"https://www.bbcgoodfood.com/recipes/veggie-tahini-lentils","ingredients":[{"name":"Tahini","measure":"50g"},{"name":"Lemon","measure":"zest and juice of 1"},{"name":"Olive Oil","measure":"2 tblsp"},{"name":"Red Onions","measure":"1 chopped"},{"name":"Garlic","measure":"1 clove peeled crushed"},{"name":"Yellow Pepper","measure":"1 thinly sliced"},{"name":"Green Beans","measure":"200g"},{"name":"Courgettes","measure":"1 sliced"},{"name":"Kale","measure":"100g shredded"},{"name":"Lentils","measure":"250g pack"}],"steps":["In a jug, mix the tahini with the zest and juice of the lemon and 50ml of cold water to make a runny dressing. Season to taste, then set aside.","Heat the oil in a wok or large frying pan over a medium-high heat. Add the red onion, along with a pinch of salt, and fry for 2 mins until starting to soften and colour. Add the garlic, pepper, green beans and courgette and fry for 5 min, stirring frequently.","Tip in the kale, lentils and the tahini dressing. Keep the pan on the heat for a couple of mins, stirring everything together until the kale is wilted and it’s all coated in the creamy dressing."],"ingredient_names":["tahini","lemon","olive oil","red onions","garlic","yellow pepper","green beans","courgettes","kale","lentils"],"allergens":["sesame"],"diet_flags":["pescatarian","vegan","vegetarian"]},{"source_id":"52870","title":"Chickpea Fajitas","category":"Vegetarian","country":"Mexico","tags":["Vegetarian"],"image_url":"https://www.themealdb.com/images/media/meals/tvtxpq1511464705.jpg","youtube_url":"https://www.youtube.com/watch?v=LGY3V7EGpT0","source_url":"https://www.bbcgoodfood.com/recipes/chickpea-fajitas","ingredients":[{"name":"Chickpeas","measure":"400g"},{"name":"Olive Oil","measure":"1 tblsp"},{"name":"Paprika","measure":"pinch"},{"name":"Tomatoes","measure":"2 small cut chunks"},{"name":"Red Onions","measure":"1 finely sliced"},{"name":"Red Wine Vinegar","measure":"2 tsp"},{"name":"Avocado","measure":"1"},{"name":"Lime","measure":"Juice of 1"},{"name":"Lime","measure":"Chopped"},{"name":"Sour Cream","measure":"100g"},{"name":"Harissa Spice","measure":"2 tsp"},{"name":"Corn Tortillas","measure":"4"},{"name":"Coriander","measure":"to serve"}],"steps":["Heat oven to 200C/180C fan/gas 6 and line a baking tray with foil. Drain the chickpeas, pat dry and tip onto the prepared baking tray. Add the oil and paprika, toss to coat, then roast for 20-25 mins until browned and crisp, shaking halfway through cooking.","Meanwhile, put the tomatoes and onion in a small bowl with the vinegar and set aside to pickle. Put the avocado in another bowl and mash with a fork, leaving some larger chunks. Stir in the lime juice and season well. Mix the soured cream with the harissa and set aside until ready to serve.","Heat a griddle pan until nearly smoking. Add the tortillas , one at a time, charring each side until hot with griddle lines.","Put everything on the table and build the fajitas : spread a little of the harissa cream over the tortilla, top with roasted chickpeas, guacamole, pickled salsa and coriander, if you like. Serve with the lime wedges for squeezing over."],"ingredient_names":["chickpeas","olive oil","paprika","tomatoes","red onions","red wine vinegar","avocado","lime","lime","sour cream","harissa spice","corn tortillas","coriander"],"allergens":["dairy"],"diet_flags":["pescatarian","vegetarian"]},{"source_id":"52871","title":"Yaki Udon","category":"Vegetarian","country":"Japan","tags":["LowCalorie"],"image_url":"https://www.themealdb.com/images/media/meals/wrustq1511475474.jpg","youtube_url":"https://www.youtube.com/watch?v=5Iy0MCowSvA","source_url":"https://www.bbcgoodfood.com/recipes/yaki-udon","ingredients":[{"name":"Udon Noodles","measure":"250g"},{"name":"Sesame Seed Oil","measure":"2 tbs"},{"name":"Onion","measure":"1 sliced"},{"name":"Cabbage","measure":"0.25"},{"name":"Shiitake Mushrooms","measure":"10"},{"name":"Spring Onions","measure":"4"},{"name":"Mirin","measure":"4 tbsp"},{"name":"Soy Sauce","measure":"2 tbs"},{"name":"Caster Sugar","measure":"1 tblsp"},{"name":"Worcestershire Sauce","measure":"1 tblsp"}],"steps":["Boil some water in a large saucepan.","Add 250ml cold water and the udon noodles. (As they are so thick, adding cold water helps them to cook a little bit slower so the middle cooks through).","If using frozen or fresh noodles, cook for 2 mins or until al dente; dried will take longer, about 5-6 mins.","Drain and leave in the colander.","Heat 1 tbsp of the oil, add the onion and cabbage and sauté for 5 mins until softened.","Add the mushrooms and some spring onions, and sauté for 1 more min.","Pour in the remaining sesame oil and the noodles.","If using cold noodles, let them heat through before adding the ingredients for the sauce – otherwise tip in straight away and keep stir-frying until sticky and piping hot.","Sprinkle with the remaining spring onions."],"ingredient_names":["udon noodles","sesame seed oil","onion","cabbage","shiitake mushrooms","spring onions","mirin","soy sauce","caster sugar","worcestershire sauce"],"allergens":["fish","gluten","sesame","soy"],"diet_flags":["pescatarian"]},{"source_id":"52872","title":"Spanish Tortilla","category":"Vegetarian","country":"Spain","tags":["Egg","Light"],"image_url":"https://www.themealdb.com/images/media/meals/quuxsx1511476154.jpg","youtube_url":"https://www.youtube.com/watch?v=JceGMNG7rpU","source_url":"https://www.bbcgoodfood.com/recipes/spanish-tortilla","ingredients":[{"name":"Onion","measure":"1 sliced"},{"name":"Olive Oil","measure":"4 tbsp"},{"name":"Butter","measure":"25g"},{"name":"Potatoes","measure":"400g"},{"name":"Garlic","measure":"6 cloves"},{"name":"Eggs","measure":"8"},{"name":"Parsley","measure":"Handful"},{"name":"Baguette","measure":"1"},{"name":"Vine Tomatoes","measure":"4"},{"name":"Olive Oil","measure":"drizzle"}],"steps":["Put a large non-stick frying pan on a low heat. Cook the onion slowly in the oil and butter until soft but not brown – this should take about 15 mins. Add the potatoes, cover the pan and cook for a further 15-20 mins, stirring occasionally to make sure they fry evenly.","When the potatoes are soft and the onion is shiny, crush 2 garlic cloves and stir in, followed by the beaten eggs.","Put the lid back on the pan and leave the tortilla to cook gently. After 20 mins, the edges and base should be golden, the top set but the middle still a little wobbly. To turn it over, slide it onto a plate and put another plate on top, turn the whole thing over and slide it back into the pan to finish cooking. Once cooked, transfer to a plate and serve the tortilla warm or cold, scattered with the chopped parsley.","To accompany, take slices of warmed baguette, stab all over with a fork and rub with the remaining garlic, pile on grated tomatoes and season with sea salt and a drizzle of olive oil."],"ingredient_names":["onion","olive oil","butter","potatoes","garlic","eggs","parsley","baguette","vine tomatoes","olive oil"],"allergens":["dairy","eggs","gluten"],"diet_flags":["pescatarian","vegetarian"]},{"source_id":"52873","title":"Beef Dumpling Stew","category":"Beef","country":"United Kingdom","tags":["Stew","Baking"],"image_url":"https://www.themealdb.com/images/media/meals/uyqrrv1511553350.jpg","youtube_url":"https://www.youtube.com/watch?v=6NgheY-r5t0","source_url":"https://www.bbc.co.uk/food/recipes/beefstewwithdumpling_87333","ingredients":[{"name":"Olive Oil","measure":"2 tbs"},{"name":"Butter","measure":"25g"},{"name":"Beef","measure":"750g"},{"name":"Plain Flour","measure":"2 tblsp"},{"name":"Garlic","measure":"2 cloves minced"},{"name":"Onions","measure":"175g"},{"name":"Celery","measure":"150g"},{"name":"Carrots","measure":"150g"},{"name":"Leek","measure":"2 chopped"},{"name":"Swede","measure":"200g"},{"name":"Red Wine","measure":"150ml"},{"name":"Beef Stock","measure":"500g"},{"name":"Bay Leaf","measure":"2"},{"name":"Thyme","measure":"3 tbs"},{"name":"Parsley","measure":"3 tblsp chopped"},{"name":"Plain Flour","measure":"125g"},{"name":"Baking Powder","measure":"1 tsp"},{"name":"Suet","measure":"60g"},{"name":"Water","measure":"Splash"}],"steps":["Preheat the oven to 180C/350F/Gas 4.","For the beef stew, heat the oil and butter in an ovenproof casserole and fry the beef until browned on all sides.","Sprinkle over the flour and cook for a further 2-3 minutes.","Add the garlic and all the vegetables and fry for 1-2 minutes.","Stir in the wine, stock and herbs, then add the Worcestershire sauce and balsamic vinegar, to taste. Season with salt and freshly ground black pepper.","Cover with a lid, transfer to the oven and cook for about two hours, or until the meat is tender.","For the dumplings, sift the flour, baking powder and salt into a bowl.","Add the suet and enough water to form a thick dough.","With floured hands, roll spoonfuls of the dough into small balls.","After two hours, remove the lid from the stew and place the balls on top of the stew. Cover, return to the oven and cook for a further 20 minutes, or until the dumplings have swollen and are tender. (If you prefer your dumplings with a golden top, leave the lid off when returning to the oven.)","To serve, place a spoonful of mashed potato onto each of four serving plates and top with the stew and dumplings. Sprinkle with chopped parsley."],"ingredient_names":["olive oil","butter","beef","plain flour","garlic","onions","celery","carrots","leek","swede","red wine","beef stock","bay leaf","thyme","parsley","plain flour","baking powder","suet","water"],"allergens":["dairy","gluten"],"diet_flags":[]},{"source_id":"52874","title":"Beef and Mustard Pie","category":"Beef","country":"United Kingdom","tags":["Meat","Pie"],"image_url":"https://www.themealdb.com/images/media/meals/sytuqu1511553755.jpg","youtube_url":"https://www.youtube.com/watch?v=nMyBC9staMU","source_url":"https://www.bbc.co.uk/food/recipes/beef_and_mustard_pie_58002","ingredients":[{"name":"Beef","measure":"1kg"},{"name":"Plain Flour","measure":"2 tbs"},{"name":"Rapeseed Oil","measure":"2 tbs"},{"name":"Red Wine","measure":"200ml"},{"name":"Beef Stock","measure":"400ml"},{"name":"Onion","measure":"1 finely sliced"},{"name":"Carrots","measure":"2 chopped"},{"name":"Thyme","measure":"3 sprigs"},{"name":"Mustard","measure":"2 tbs"},{"name":"Egg Yolks","measure":"2 free-range"},{"name":"Puff Pastry","measure":"400g"},{"name":"Green Beans","measure":"300g"},{"name":"Butter","measure":"25g"},{"name":"Salt","measure":"pinch"},{"name":"Pepper","measure":"pinch"}],"steps":["Preheat the oven to 150C/300F/Gas 2.","Toss the beef and flour together in a bowl with some salt and black pepper.","Heat a large casserole until hot, add half of the rapeseed oil and enough of the beef to just cover the bottom of the casserole.","Fry until browned on each side, then remove and set aside. Repeat with the remaining oil and beef.","Return the beef to the pan, add the wine and cook until the volume of liquid has reduced by half, then add the stock, onion, carrots, thyme and mustard, and season well with salt and pepper.","Cover with a lid and place in the oven for two hours.","Remove from the oven, check the seasoning and set aside to cool. Remove the thyme.","When the beef is cool and you're ready to assemble the pie, preheat the oven to 200C/400F/Gas 6.","Transfer the beef to a pie dish, brush the rim with the beaten egg yolks and lay the pastry over the top. Brush the top of the pastry with more beaten egg.","Trim the pastry so there is just enough excess to crimp the edges, then place in the oven and bake for 30 minutes, or until the pastry is golden-brown and cooked through.","For the green beans, bring a saucepan of salted water to the boil, add the beans and cook for 4-5 minutes, or until just tender.","Drain and toss with the butter, then season with black pepper.","To serve, place a large spoonful of pie onto each plate with some green beans alongside."],"ingredient_names":["beef","plain flour","rapeseed oil","red wine","beef stock","onion","carrots","thyme","mustard","egg yolks","puff pastry","green beans","butter","salt","pepper"],"allergens":["dairy","eggs","gluten"],"diet_flags":[]},{"source_id":"52875","title":"Chicken Ham and Leek Pie","category":"Chicken","country":"United Kingdom","tags":["Pie","Meat"],"image_url":"https://www.themealdb.com/images/media/meals/xrrtss1511555269.jpg","youtube_url":"https://www.youtube.com/watch?v=xr-CpPE_lNk","source_url":"https://www.bbc.co.uk/food/recipes/creamy_chicken_ham_and_03877","ingredients":[{"name":"Chicken Stock","measure":"450ml"},{"name":"Chicken Breast","measure":"3"},{"name":"Butter","measure":"75g"},{"name":"Leek","measure":"2 sliced"},{"name":"Garlic","measure":"2 cloves minced"},{"name":"Plain Flour","measure":"50g"},{"name":"Milk","measure":"200ml"},{"name":"White Wine","measure":"3 tbs"},{"name":"Double Cream","measure":"150ml"},{"name":"Ham","measure":"150g"},{"name":"Sea Salt","measure":"spinkling"},{"name":"Pepper","measure":"pinch"},{"name":"Plain Flour","measure":"350g"},{"name":"Butter","measure":"200g"},{"name":"Free-range Egg, Beaten","measure":"1"},{"name":"Cold Water","measure":"1 tbls"},{"name":"Free-range Egg, Beaten","measure":"1"}],"steps":["Heat the chicken stock in a lidded saucepan. Add the chicken breast and bring to a low simmer. Cover with a lid and cook for 10 minutes. Remove the chicken breasts from the water with tongs and place on a plate. Pour the cooking liquor into a large jug.","Melt 25g/1oz of the butter in a large heavy-based saucepan over a low heat. Stir in the leeks and fry gently for two minutes, stirring occasionally until just softened. Add the garlic and cook for a further minute. Add the remaining butter and stir in the flour as soon as the butter has melted. Cook for 30 seconds, stirring constantly.","Slowly pour the milk into the pan, just a little at a time, stirring well between each adding. Gradually add 250ml/10fl oz of the reserved stock and the wine, if using, stirring until the sauce is smooth and thickened slightly. Bring to a gentle simmer and cook for 3 minutes.","Season the mixture, to taste, with salt and freshly ground black pepper. Remove from the heat and stir in the cream. Pour into a large bowl and cover the surface of the sauce with cling ilm to prevent a skin forming. Set aside to cool.","Preheat the oven to 200C/400F/Gas 6. Put a baking tray in the oven to heat.","For the pastry, put the flour and butter in a food processor and blend on the pulse setting until the mixture resembles fine breadcrumbs. With the motor running, add the beaten egg and water and blend until the mixture forms a ball. Portion off 250g/10oz of pastry for the lid.","Roll the remaining pastry out on a lightly floured surface, turning the pastry frequently until around 5mm/¼in thick and 4cm/1½in larger than the pie dish. Lift the pastry over the rolling pin and place it gently into the pie dish. Press the pastry firmly up the sides, making sure there are no air bubbles. Leave the excess pastry overhanging the sides.","Cut the chicken breasts into 3cm/1¼in pieces. Stir the chicken, ham and leeks into the cooled sauce. Pour the chicken filling into the pie dish. Brush the rim of the dish with beaten egg. Roll out the reserved pastry for the lid.","Cover the pie with the pastry lid and press the edges together firmly to seal. Trim any excess pastry.","Make a small hole in the centre of the pie with the tip of a knife. Glaze the top of the pie with beaten egg. Bake on the preheated tray in the centre of the oven for 35-40 minutes or until the pie is golden-brown all over and the filling is piping hot."],"ingredient_names":["chicken stock","chicken breast","butter","leek","garlic","plain flour","milk","white wine","double cream","ham","sea salt","pepper","plain flour","butter","free-range egg, beaten","cold water","free-range egg, beaten"],"allergens":["dairy","eggs","gluten"],"diet_flags":[]},{"source_id":"52876","title":"Minced Beef Pie","category":"Beef","country":"United Kingdom","tags":["Pie","Meat"],"image_url":"https://www.themealdb.com/images/media/meals/xwutvy1511555540.jpg","youtube_url":"https://www.youtube.com/watch?v=QY47h-uqq5g","source_url":"https://www.bbc.co.uk/food/recipes/mincedbeefpie_89198","ingredients":[{"name":"Vegetable Oil","measure":"2 tbs"},{"name":"Minced Beef","measure":"500g"},{"name":"Onion","measure":"1 chopped"},{"name":"Tomato Puree","measure":"1 tbls"},{"name":"Plain Flour","measure":"1 ½ tbsp"},{"name":"Mushrooms","measure":"75g"},{"name":"Beef Stock","measure":"250ml"},{"name":"Worcestershire Sauce","measure":"Dash"},{"name":"Shortcrust Pastry","measure":"400g"},{"name":"Egg Yolks","measure":"1"}],"steps":["Preheat the oven to 200C/400F/Gas 6.","Heat the oil in a deep frying pan and fry the beef mince for 4-5 minutes, breaking it up with a wooden spoon as it browns.","Add the onion and cook for 2-3 minutes, then stir in the tomato purée and cook for 2-3 more minutes. Stir in the flour and cook for a further minute, then add the chopped mushrooms, the stout or beef stock and a couple of dashes of Worcestershire sauce. Bring to the boil, then reduce the heat, cover the pan with a lid and leave to simmer for 20 minutes. Set aside and leave to cool, then turn the meat mixture into a one litre pie dish.","Roll out the pastry on a floured work surface until it is slightly larger than the pie dish. Gently drape the pastry over the dish, pressing firmly onto the edges. Trim, then shape the edges into a fluted shape.","Cut some leaf shapes out of the pastry trimmings and decorate the top of the pie, sticking them to the pastry with the beaten egg yolk.","Make three or four slits in the pastry to allow the steam to escape, then brush the pie with the rest of the beaten egg yolk and bake in the oven for 20-25 minutes, or until golden-brown.","To serve, slice into wedges."],"ingredient_names":["vegetable oil","minced beef","onion","tomato puree","plain flour","mushrooms","beef stock","worcestershire sauce","shortcrust pastry","egg yolks"],"allergens":["eggs","fish","gluten"],"diet_flags":[]},{"source_id":"52877","title":"Lamb and Potato pie","category":"Lamb","country":"United Kingdom","tags":["Pie"],"image_url":"https://www.themealdb.com/images/media/meals/sxrpws1511555907.jpg","youtube_url":"https://www.youtube.com/watch?v=NCyPaaUNYUk","source_url":"https://www.bbc.co.uk/food/recipes/lambandpotatopie_83913","ingredients":[{"name":"Lamb Shoulder","measure":"500g"},{"name":"Flour","measure":"1 tbls"},{"name":"Vegetable Oil","measure":"Dash"},{"name":"Onion","measure":"1 sliced"},{"name":"Carrots","measure":"2 sliced"},{"name":"Vegetable Stock","measure":"350ml/12fl"},{"name":"Potatoes","measure":"500g"},{"name":"Shortcrust Pastry","measure":"450g"},{"name":"Eggs","measure":"To Glaze"}],"steps":["Dust the meat with flour to lightly coat.","Heat enough vegetable oil in a large saucepan to fill the base, and fry the onion and meat until lightly browned. Season with salt and pepper.","Add the carrots, stock and more seasoning to taste.","Bring to the boil, cover and reduce the heat to a simmer. Simmer for at least an hour or until the meat is tender. Take your time cooking the meat, the longer you leave it to cook, the better the flavour will be.","Preheat the oven to 180C/350F/Gas 4.","Add the drained potato cubes to the lamb.","Turn the mixture into a pie dish or casserole and cover with the shortcrust pastry. Make three slits in the top of the pastry to release any steam while cooking.","Brush with beaten egg and bake for about 40 minutes, until the pastry is golden brown.","Serve."],"ingredient_names":["lamb shoulder","flour","vegetable oil","onion","carrots","vegetable stock","potatoes","shortcrust pastry","eggs"],"allergens":["eggs","gluten"],"diet_flags":[]},{"source_id":"52878","title":"Beef and Oyster pie","category":"Beef","country":"United Kingdom","tags":["Pie"],"image_url":"https://www.themealdb.com/images/media/meals/wrssvt1511556563.jpg","youtube_url":"https://www.youtube.com/watch?v=ONX74yP6JnI","source_url":"https://www.bbc.co.uk/food/recipes/beef_and_oyster_pie_65230","ingredients":[{"name":"Beef","measure":"900g"},{"name":"Olive Oil","measure":"3 tbs"},{"name":"Shallots","measure":"3"},{"name":"Garlic","measure":"2 cloves minced"},{"name":"Bacon","measure":"125g"},{"name":"Thyme","measure":"1 tbs chopped"},{"name":"Bay Leaf","measure":"2"},{"name":"Stout","measure":"330ml"},{"name":"Beef Stock","measure":"400ml"},{"name":"Corn Flour","measure":"2 tbs"},{"name":"Oysters","measure":"8"},{"name":"Plain Flour","measure":"400g"},{"name":"Salt","measure":"pinch"},{"name":"Butter","measure":"250g"},{"name":"Eggs","measure":"To Glaze"}],"steps":["Season the beef cubes with salt and black pepper. Heat a tablespoon of oil in the frying pan and fry the meat over a high heat. Do this in three batches so that you don’t overcrowd the pan, transferring the meat to a large flameproof casserole dish once it is browned all over. Add extra oil if the pan seems dry.","In the same pan, add another tablespoon of oil and cook the shallots for 4-5 minutes, then add the garlic and fry for 30 seconds. Add the bacon and fry until slightly browned. Transfer the onion and bacon mixture to the casserole dish and add the herbs.","Preheat the oven to 180C/350F/Gas 4.","Pour the stout into the frying pan and bring to the boil, stirring to lift any stuck-on browned bits from the bottom of the pan. Pour the stout over the beef in the casserole dish and add the stock. Cover the casserole and place it in the oven for 1½-2 hours, or until the beef is tender and the sauce is reduced.","Skim off any surface fat, taste and add salt and pepper if necessary, then stir in the cornflour paste. Put the casserole dish on the hob – don’t forget that it will be hot – and simmer for 1-2 minutes, stirring, until thickened. Leave to cool.","Increase the oven to 200C/400F/Gas 6. To make the pastry, put the flour and salt in a very large bowl. Grate the butter and stir it into the flour in three batches. Gradually add 325ml/11fl oz cold water – you may not need it all – and stir with a round-bladed knife until the mixture just comes together. Knead the pastry lightly into a ball on a lightly floured surface and set aside 250g/9oz for the pie lid.","Roll the rest of the pastry out until about 2cm/¾in larger than the dish you’re using. Line the dish with the pastry then pile in the filling, tucking the oysters in as well. Brush the edge of the pastry with beaten egg.","Roll the remaining pastry until slightly larger than your dish and gently lift over the filling, pressing the edges firmly to seal, then trim with a sharp knife. Brush with beaten egg to glaze. Put the dish on a baking tray and bake for 25-30 minutes, or until the pastry is golden-brown and the filling is bubbling."],"ingredient_names":["beef","olive oil","shallots","garlic","bacon","thyme","bay leaf","stout","beef stock","corn flour","oysters","plain flour","salt","butter","eggs"],"allergens":["dairy","eggs","gluten","shellfish"],"diet_flags":[]},{"source_id":"52879","title":"Chicken Parmentier","category":"Chicken","country":"France","tags":["Meat","Dairy"],"image_url":"https://www.themealdb.com/images/media/meals/uwvxpv1511557015.jpg","youtube_url":"https://www.youtube.com/watch?v=tiG-xlmeyjg","source_url":"https://www.bbc.co.uk/food/recipes/chicken_parmentier_25434","ingredients":[{"name":"Potatoes","measure":"1.5kg"},{"name":"Butter","measure":"30g"},{"name":"Double Cream","measure":"5 tblsp"},{"name":"Egg Yolks","measure":"2"},{"name":"Butter","measure":"30g"},{"name":"Shallots","measure":"7"},{"name":"Carrots","measure":"3 chopped"},{"name":"Celery","measure":"2 sticks"},{"name":"Garlic Clove","measure":"1 finely chopped"},{"name":"White Wine","measure":"4 tbsp"},{"name":"Tomato Puree","measure":"1 tbls"},{"name":"Tinned Tomatos","measure":"400g"},{"name":"Chicken Stock","measure":"350ml"},{"name":"Chicken","measure":"600g"},{"name":"Black Olives","measure":"16"},{"name":"Parsley","measure":"2 tbs"},{"name":"Gruyere cheese","measure":"50g"}],"steps":["For the topping, boil the potatoes in salted water until tender. Drain and push through a potato ricer, or mash thoroughly. Stir in the butter, cream and egg yolks. Season and set aside.","For the filling, melt the butter in a large pan. Add the shallots, carrots and celery and gently fry until soft, then add the garlic. Pour in the wine and cook for 1 minute. Stir in the tomato purée, chopped tomatoes and stock and cook for 10–15 minutes, until thickened. Add the shredded chicken, olives and parsley. Season to taste with salt and pepper.","Preheat the oven to 180C/160C Fan/Gas 4.","Put the filling in a 20x30cm/8x12in ovenproof dish and top with the mashed potato. Grate over the Gruyère. Bake for 30–35 minutes, until piping hot and the potato is golden-brown."],"ingredient_names":["potatoes","butter","double cream","egg yolks","butter","shallots","carrots","celery","garlic clove","white wine","tomato puree","tinned tomatos","chicken stock","chicken","black olives","parsley","gruyere cheese"],"allergens":["dairy","eggs"],"diet_flags":[]},{"source_id":"52880","title":"McSinghs Scotch pie","category":"Lamb","country":"United Kingdom","tags":["Pie"],"image_url":"https://www.themealdb.com/images/media/meals/vssrtx1511557680.jpg","youtube_url":"https://www.youtube.com/watch?v=1nArqhRyszw","source_url":"https://www.bbc.co.uk/food/recipes/mcsinghs_scotch_pie_98356","ingredients":[{"name":"Cumin","measure":"2 tsp"},{"name":"Rapeseed Oil","measure":"1 tbs"},{"name":"Red Onions","measure":"2 finely chopped"},{"name":"Garlic Clove","measure":"6"},{"name":"Green Chilli","measure":"3 finely chopped"},{"name":"Red Pepper","measure":"1 finely chopped"},{"name":"Nutmeg","measure":"1 tsp"},{"name":"Coriander","measure":"2 tsp"},{"name":"Lamb Mince","measure":"1kg"},{"name":"Pepper","measure":"1 tsp"},{"name":"Coriander","measure":"3 tbs"},{"name":"Plain Flour","measure":"340g"},{"name":"Salt","measure":"½ tsp"},{"name":"Milk","measure":"90 ml"},{"name":"Lard","measure":"150g"},{"name":"Egg Yolks","measure":"Beaten"}],"steps":["Heat a large frying pan and toast the cumin seeds for a few minutes, then set aside. Heat the oil in the same pan and fry the onion, garlic, chilli, pepper and a good pinch of salt for around eight minutes, until there is no moisture left. Remove from the heat, stir in the toasted cumin seeds, ground mace (or nutmeg) and ground coriander. Leave to cool.","In a large bowl mix together the minced lamb, white pepper, fresh coriander, and the cooled spiced onion mixture until combined. Set aside, covered, in the fridge.","Preheat the oven to 200C/400F/Gas 6 and generously grease a 20cm/8in diameter loose-bottomed or springform round cake tin with lard.","To make the pastry, sift the flour and salt in a large bowl and make a well in the centre.","Put the milk, lard and 90ml/3fl oz of water in a saucepan and heat gently. When the lard has melted, increase the heat and bring to the boil.","Pour the boiling liquid into the flour, and use a wooden spoon to combine until cool enough to handle. Bring together into a ball.","Dust a work surface with flour and, working quickly, knead the dough briefly – it will be soft and moist. Set aside a third of the pastry and roll the rest out on a well-floured surface. Line the pie dish with the pastry, pressing it right up the sides until it pokes just over the top of the tin.","Add the filling into the pastry-lined tin bit by bit. As you reach the top, form a slight peak. Roll out the reserved pastry and top the pie with it. Pinch the edges to seal and trim the excess. Poke a hole in the top of the pie and insert a small tube made from aluminium foil to allow steam to escape.","Brush the top of the pie with a little beaten egg yolk, and bake in the preheated oven for 30 minutes (put a tray on the shelf below to catch any drips). Then reduce the temperature to 160C/325F/Gas 3 and cook for a further 1¼ hours until golden-brown. Leave to cool completely before refrigerating for two hours, or overnight.","Run a knife around the edge of the pie, remove from the tin and serve with chutneys, salads or pickles."],"ingredient_names":["cumin","rapeseed oil","red onions","garlic clove","green chilli","red pepper","nutmeg","coriander","lamb mince","pepper","coriander","plain flour","salt","milk","lard","egg yolks"],"allergens":["dairy","eggs","gluten"],"diet_flags":[]},{"source_id":"52881","title":"Steak and Kidney Pie","category":"Beef","country":"United Kingdom","tags":["Pie"],"image_url":"https://www.themealdb.com/images/media/meals/qysyss1511558054.jpg","youtube_url":"https://www.youtube.com/watch?v=oTw5tPt4KmA","source_url":"https://www.bbc.co.uk/food/recipes/steakandkidneypie_73308","ingredients":[{"name":"Puff Pastry","measure":"300g"},{"name":"Egg White","measure":"Beaten"},{"name":"Egg Yolks","measure":"Beaten"},{"name":"Vegetable Oil","measure":"2 tbs"},{"name":"Beef","measure":"70 ml"},{"name":"Lamb Kidney","measure":"200g"},{"name":"Onions","measure":"2 chopped"},{"name":"Plain Flour","measure":"30g"},{"name":"Beef Stock","measure":"85 ml"},{"name":"Salt","measure":"pinch"},{"name":"Pepper","measure":"pinch"},{"name":"Worcestershire Sauce","measure":"Dash"}],"steps":["Preheat the oven to 220C/425F/Gas 7","Heat the vegetable oil in a large frying pan, and brown the beef all over. (You may need to do this in batches.) Set aside, then brown the kidneys on both sides in the same pan. Add the onions and cook for 3-4 minutes.","Return the beef to the pan, sprinkle flour over and coat the meat and onions","Add the stock to the pan, stir well and bring to the boil.","Turn the heat down and simmer for 1½ hours without a lid. If the liquid evaporates too much, add more stock.","Remove from the heat. Add salt, pepper and Worcestershire sauce and allow to cool completely. Place the cooked meat mixture into a pie dish.","Roll out the pastry to 5mm/¼in thick and 5cm/2in larger than the dish you are using.","Using a rolling pin, lift the pastry and place it over the top of the pie dish. Trim and crimp the edges with your fingers and thumb.","Brush the surface with the beaten egg mixture and bake for 30-40 minutes until golden-brown and puffed.","Serve with creamy mash and steamed vegetables to soak up the gravy."],"ingredient_names":["puff pastry","egg white","egg yolks","vegetable oil","beef","lamb kidney","onions","plain flour","beef stock","salt","pepper","worcestershire sauce"],"allergens":["eggs","fish","gluten"],"diet_flags":[]},{"source_id":"52882","title":"Three Fish Pie","category":"Seafood","country":"United Kingdom","tags":["Fish","Seafood","Dairy","Pie"],"image_url":"https://www.themealdb.com/images/media/meals/spswqs1511558697.jpg","youtube_url":"https://www.youtube.com/watch?v=Ds1Jb8H5Sg8","source_url":"https://www.bbc.co.uk/food/recipes/three_fish_pie_58875","ingredients":[{"name":"Potatoes","measure":"1kg"},{"name":"Butter","measure":"Knob"},{"name":"Milk","measure":"Dash"},{"name":"Gruyere","measure":"50g"},{"name":"Butter","measure":"75g"},{"name":"Leek","measure":"2 sliced"},{"name":"Plain Flour","measure":"75g"},{"name":"White Wine","measure":"150ml"},{"name":"Milk","measure":"568ml"},{"name":"Parsley","measure":"2 tbs chopped"},{"name":"Salmon","measure":"250g"},{"name":"Haddock","measure":"250g"},{"name":"Smoked Haddock","measure":"250g"},{"name":"Eggs","measure":"6"}],"steps":["Preheat the oven to 200C/400F/Gas 6 (180C fan).","Put the potatoes into a saucepan of cold salted water. Bring up to the boil and simmer until completely tender. Drain well and then mash with the butter and milk. Add pepper and taste to check the seasoning. Add salt and more pepper if necessary.","For the fish filling, melt the butter in a saucepan, add the leeks and stir over the heat. Cover with a lid and simmer gently for 10 minutes, or until soft. Measure the flour into a small bowl. Add the wine and whisk together until smooth.","Add the milk to the leeks, bring to the boil and then add the wine mixture. Stir briskly until thickened. Season and add the parsley and fish. Stir over the heat for two minutes, then spoon into an ovenproof casserole. Scatter over the eggs. Allow to cool until firm.","Spoon the mashed potatoes over the fish mixture and mark with a fork. Sprinkle with cheese.","Bake for 30-40 minutes, or until lightly golden-brown on top and bubbling around the edges."],"ingredient_names":["potatoes","butter","milk","gruyere","butter","leek","plain flour","white wine","milk","parsley","salmon","haddock","smoked haddock","eggs"],"allergens":["dairy","eggs","fish","gluten"],"diet_flags":["pescatarian"]},{"source_id":"52884","title":"Lancashire hotpot","category":"Lamb","country":"United Kingdom","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/uttrxw1511637813.jpg","youtube_url":"https://www.youtube.com/watch?v=w6TS5J8YRA4","source_url":"https://www.bbcgoodfood.com/recipes/9099/lancashire-hotpot","ingredients":[{"name":"Butter","measure":"100g"},{"name":"Lamb","measure":"900g"},{"name":"Lamb Kidney","measure":"3"},{"name":"Onions","measure":"2 medium"},{"name":"Carrots","measure":"4 sliced"},{"name":"Plain Flour","measure":"25g"},{"name":"Worcestershire Sauce","measure":"2 tsp"},{"name":"Chicken Stock","measure":"500ml"},{"name":"Bay Leaves","measure":"2"},{"name":"Potatoes","measure":"900g"}],"steps":["Heat oven to 160C/fan 140C/gas 3. Heat some dripping or butter in a large shallow casserole dish, brown the lamb in batches, lift to a plate, then repeat with the kidneys.","Fry the onions and carrots in the pan with a little more dripping until golden. Sprinkle over the flour, allow to cook for a couple of mins, shake over the Worcestershire sauce, pour in the stock, then bring to the boil. Stir in the meat and bay leaves, then turn off the heat. Arrange the sliced potatoes on top of the meat, then drizzle with a little more dripping. Cover, then place in the oven for about 1½ hrs until the potatoes are cooked.","Remove the lid, brush the potatoes with a little more dripping, then turn the oven up to brown the potatoes, or finish under the grill for 5-8 mins until brown."],"ingredient_names":["butter","lamb","lamb kidney","onions","carrots","plain flour","worcestershire sauce","chicken stock","bay leaves","potatoes"],"allergens":["dairy","fish","gluten"],"diet_flags":[]},{"source_id":"52887","title":"Kedgeree","category":"Seafood","country":"United Kingdom","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/utxqpt1511639216.jpg","youtube_url":"https://www.youtube.com/watch?v=_Pw1I1-SItE","source_url":"https://www.bbcgoodfood.com/recipes/10421/kedgeree","ingredients":[{"name":"Smoked Haddock","measure":"300g"},{"name":"Bay Leaves","measure":"2"},{"name":"Milk","measure":"300ml"},{"name":"Eggs","measure":"4"},{"name":"Parsley","measure":"Handful"},{"name":"Coriander","measure":"Handful"},{"name":"Vegetable Oil","measure":"2 tbs"},{"name":"Onion","measure":"1 chopped"},{"name":"Coriander","measure":"1 tsp"},{"name":"Curry Powder","measure":"2 tsp"},{"name":"Rice","measure":"300g"}],"steps":["For the rice, heat the oil in a large, lidded pan, add the onion, then gently fry for 5 mins until softened but not coloured. Add the spices, season with salt, then continue to fry until the mix start to go brown and fragrant; about 3 mins.","Add the rice and stir in well. Add 600ml water, stir, then bring to the boil. Reduce to a simmer, then cover for 10 mins. Take off the heat and leave to stand, covered, for 10-15 mins more. The rice will be perfectly cooked if you do not lift the lid before the end of the cooking.","Meanwhile, put the haddock and bay leaves in a frying pan, cover with the milk, then poach for 10 mins until the flesh flakes. Remove from the milk, peel away the skin, then flake the flesh into thumbsize pieces. Place the eggs in a pan, cover with water, bring to the boil, then reduce to a simmer. Leave for 4½-5 mins, plunge into cold water, then peel and cut the eggs into quarters. Gently mix the fish, eggs, parsley, coriander and rice together in the pan. Serve hot, sprinkled with a few extra herbs."],"ingredient_names":["smoked haddock","bay leaves","milk","eggs","parsley","coriander","vegetable oil","onion","coriander","curry powder","rice"],"allergens":["dairy","eggs","fish"],"diet_flags":["pescatarian"]},{"source_id":"52904","title":"Beef Bourguignon","category":"Beef","country":"France","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/vtqxtu1511784197.jpg","youtube_url":"https://www.youtube.com/watch?v=SQnr4Z-7rok","source_url":"https://www.bbcgoodfood.com/recipes/5032/beef-bourguignon","ingredients":[{"name":"Goose Fat","measure":"3 tsp"},{"name":"Beef Shin","measure":"600g"},{"name":"Bacon","measure":"100g"},{"name":"Challots","measure":"350g"},{"name":"Chestnut Mushroom","measure":"250g"},{"name":"Garlic Clove","measure":"2 sliced"},{"name":"Bouquet Garni","measure":"1"},{"name":"Tomato Puree","measure":"1 tbs"},{"name":"Red Wine","measure":"750 ml"},{"name":"Celeriac","measure":"600g"},{"name":"Olive Oil","measure":"2 tbs"},{"name":"Thyme","measure":"sprigs of fresh"},{"name":"Rosemary","measure":"sprigs of fresh"},{"name":"Bay Leaf","measure":"2"},{"name":"Cardamom","measure":"4"}],"steps":["Heat a large casserole pan and add 1 tbsp goose fat. Season the beef and fry until golden brown, about 3-5 mins, then turn over and fry the other side until the meat is browned all over, adding more fat if necessary. Do this in 2-3 batches, transferring the meat to a colander set over a bowl when browned.","In the same pan, fry the bacon, shallots or pearl onions, mushrooms, garlic and bouquet garni until lightly browned. Mix in the tomato purée and cook for a few mins, stirring into the mixture. This enriches the bourguignon and makes a great base for the stew. Then return the beef and any drained juices to the pan and stir through.","Pour over the wine and about 100ml water so the meat bobs up from the liquid, but isn’t completely covered. Bring to the boil and use a spoon to scrape the caramelised cooking juices from the bottom of the pan – this will give the stew more flavour.","Heat oven to 150C/fan 130C/gas 2. Make a cartouche: tear off a square of foil slightly larger than the casserole, arrange it in the pan so it covers the top of the stew and trim away any excess foil. Then cook for 3 hrs. If the sauce looks watery, remove the beef and veg with a slotted spoon, and set aside. Cook the sauce over a high heat for a few mins until the sauce has thickened a little, then return the beef and vegetables to the pan.","To make the celeriac mash, peel the celeriac and cut into cubes. Heat the olive oil in a large frying pan. Tip in the celeriac and fry for 5 mins until it turns golden. Season well with salt and pepper. Stir in the rosemary, thyme, bay and cardamom pods, then pour over 200ml water, enough to nearly cover the celeriac. Turn the heat to low, partially cover the pan and leave to simmer for 25-30 mins.","After 25-30 mins, the celeriac should be soft and most of the water will have evaporated. Drain away any remaining water, then remove the herb sprigs, bay and cardamom pods. Lightly crush with a potato masher, then finish with a glug of olive oil and season to taste. Spoon the beef bourguignon into serving bowls and place a large spoonful of the celeriac mash on top. Garnish with one of the bay leaves, if you like."],"ingredient_names":["goose fat","beef shin","bacon","challots","chestnut mushroom","garlic clove","bouquet garni","tomato puree","red wine","celeriac","olive oil","thyme","rosemary","bay leaf","cardamom"],"allergens":["tree_nuts"],"diet_flags":[]},{"source_id":"52906","title":"Flamiche","category":"Vegetarian","country":"France","tags":["Tart"],"image_url":"https://www.themealdb.com/images/media/meals/wssvvs1511785879.jpg","youtube_url":"https://www.youtube.com/watch?v=vT0q5c880Rg","source_url":"http://www.deliciousmagazine.co.uk/recipes/flamiche-flemish-leek-tart/","ingredients":[{"name":"Butter","measure":"75g"},{"name":"Leek","measure":"1kg"},{"name":"Salt","measure":"½ tsp"},{"name":"Creme Fraiche","measure":"300ml"},{"name":"Egg","measure":"1"},{"name":"Egg Yolks","measure":"3"},{"name":"Nutmeg","measure":"¼ teaspoon"},{"name":"Plain Flour","measure":"225g"},{"name":"Salt","measure":"½ tsp"},{"name":"Butter","measure":"60g"},{"name":"Lard","measure":"60g"},{"name":"Cheddar Cheese","measure":"50g"},{"name":"Water","measure":"2 tbs"}],"steps":["For the pastry, sift the flour and salt into the bowl of a food processor, add the butter and lard, then whizz together briefly until the mixture looks like fine breadcrumbs. Tip the mixture into a bowl, then stir in the cheese and enough of the water for the mixture to come together. Tip out onto a lightly floured surface and knead briefly until smooth. Roll out thinly and line a 23cm x 4cm loose-?bottomed fluted flan tin. Prick the base with a fork. Chill for 20 minutes.","Melt the 75g butter in a saucepan over a low heat, then add the leeks and the salt. Cover and cook for ?10 minutes until soft. Uncover the pan, increase the heat and cook ?for 2 minutes, stirring occasionally, until the liquid has evaporated. Spoon onto a plate and leave to cool.","Preheat the oven to 200°C/fan180°C/gas 6. Line the pastry case with baking paper and baking beans or rice and blind bake for 15-20 minutes until the edges are biscuit-coloured. Remove the paper and beans/rice and return the case to the oven for 7-10 minutes until the base is crisp and lightly golden. Remove and set aside. Reduce the oven temperature to 190°C/fan170°C/gas 5.","Put the crème fraîche into a bowl with the whole egg, egg yolks and nutmeg. Lightly beat together, then season. Stir in the leeks. Spoon ?the mixture into the tart case and bake for 35-40 minutes until set ?and lightly golden. Remove from ?the oven and leave for 10 minutes. Take out of the tin and serve."],"ingredient_names":["butter","leek","salt","creme fraiche","egg","egg yolks","nutmeg","plain flour","salt","butter","lard","cheddar cheese","water"],"allergens":["dairy","eggs","gluten"],"diet_flags":[]},{"source_id":"52908","title":"Ratatouille","category":"Vegetarian","country":"France","tags":["Vegetables","SideDish"],"image_url":"https://www.themealdb.com/images/media/meals/wrpwuu1511786491.jpg","youtube_url":"https://www.youtube.com/watch?v=BFdQUgAFtGU","source_url":"https://www.bbcgoodfood.com/recipes/2903/ratatouille","ingredients":[{"name":"Aubergine","measure":"2 large"},{"name":"Courgettes","measure":"4"},{"name":"Yellow Pepper","measure":"2"},{"name":"Tomato","measure":"4 large"},{"name":"Olive Oil","measure":"5 tbs"},{"name":"Basil","measure":"Bunch"},{"name":"Onion","measure":"1 medium"},{"name":"Garlic Clove","measure":"3 finely chopped"},{"name":"Red Wine Vinegar","measure":"1 tsp"},{"name":"Sugar","measure":"1 tsp"}],"steps":["Cut the aubergines in half lengthways. Place them on the board, cut side down, slice in half lengthways again and then across into 1.5cm chunks. Cut off the courgettes ends, then across into 1.5cm slices. Peel the peppers from stalk to bottom. Hold upright, cut around the stalk, then cut into 3 pieces. Cut away any membrane, then chop into bite-size chunks.","Score a small cross on the base of each tomato, then put them into a heatproof bowl. Pour boiling water over the tomatoes, leave for 20 secs, then remove. Pour the water away, replace the tomatoes and cover with cold water. Leave to cool, then peel the skin away. Quarter the tomatoes, scrape away the seeds with a spoon, then roughly chop the flesh.","Set a sauté pan over medium heat and when hot, pour in 2 tbsp olive oil. Brown the aubergines for 5 mins on each side until the pieces are soft. Set them aside and fry the courgettes in another tbsp oil for 5 mins, until golden on both sides. Repeat with the peppers. Don’t overcook the vegetables at this stage, as they have some more cooking left in the next step.","Tear up the basil leaves and set aside. Cook the onion in the pan for 5 mins. Add the garlic and fry for a further min. Stir in the vinegar and sugar, then tip in the tomatoes and half the basil. Return the vegetables to the pan with some salt and pepper and cook for 5 mins. Serve with basil."],"ingredient_names":["aubergine","courgettes","yellow pepper","tomato","olive oil","basil","onion","garlic clove","red wine vinegar","sugar"],"allergens":[],"diet_flags":["pescatarian","vegan","vegetarian"]},{"source_id":"52911","title":"Summer Pistou","category":"Vegetarian","country":"France","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/rqtxvr1511792990.jpg","youtube_url":"https://www.youtube.com/watch?v=fyeqZJKEXp0","source_url":"https://www.bbcgoodfood.com/recipes/summer-pistou","ingredients":[{"name":"Rapeseed Oil","measure":"1 tbs"},{"name":"Leek","measure":"2 finely chopped"},{"name":"Courgettes","measure":"1 large"},{"name":"Vegetable Stock","measure":"1L"},{"name":"Cannellini Beans","measure":"400g"},{"name":"Green Beans","measure":"200g"},{"name":"Tomatoes","measure":"3 chopped"},{"name":"Garlic Clove","measure":"3 chopped"},{"name":"Basil","measure":"Small pack"},{"name":"Parmesan","measure":"40g"}],"steps":["Heat the oil in a large pan and fry the leeks and courgette for 5 mins to soften.","Pour in the stock, add three-quarters of the haricot beans with the green beans, half the tomatoes, and simmer for 5-8 mins until the vegetables are tender.","Meanwhile, blitz the remaining beans and tomatoes, the garlic and basil in a food processor (or in a bowl with a stick blender) until smooth, then stir in the Parmesan.","Stir the sauce into the soup, cook for 1 min, then ladle half into bowls or pour into a flask for a packed lunch. Chill the remainder.","Will keep for a couple of days."],"ingredient_names":["rapeseed oil","leek","courgettes","vegetable stock","cannellini beans","green beans","tomatoes","garlic clove","basil","parmesan"],"allergens":["dairy"],"diet_flags":["pescatarian","vegetarian"]},{"source_id":"52918","title":"Fish Stew with Rouille","category":"Seafood","country":"France","tags":["Fish","Seafood","Shellfish"],"image_url":"https://www.themealdb.com/images/media/meals/vptqpw1511798500.jpg","youtube_url":"https://www.youtube.com/watch?v=fp9Lqx2EUco","source_url":"https://www.bbcgoodfood.com/recipes/532640/summer-fish-stew-with-rouille","ingredients":[{"name":"Prawns","measure":"6 large"},{"name":"Olive Oil","measure":"3 tbs"},{"name":"Dry White Wine","measure":"150ml"},{"name":"Fish Stock","measure":"200ml"},{"name":"Fennel","measure":"1 small finely diced"},{"name":"Onion","measure":"1 small finely diced"},{"name":"Garlic","measure":"3 cloves Chopped"},{"name":"Potatoes","measure":"1 large"},{"name":"Orange","measure":"1"},{"name":"Star Anise","measure":"1"},{"name":"Bay Leaf","measure":"1"},{"name":"Harissa Spice","measure":"1 1/2 tsp"},{"name":"Tomato Puree","measure":"2 tbs"},{"name":"Chopped Tomatoes","measure":"400g"},{"name":"Mussels","measure":"Handful"},{"name":"White Fish","measure":"200g"},{"name":"Thyme","measure":"2"},{"name":"Bread","measure":"to serve"}],"steps":["Twist the heads from the prawns, then peel away the legs and shells, but leave the tails intact. Devein each prawn. Fry the shells in 1 tbsp oil for 5 mins, until dark pink and golden in patches. Add the wine, boil down by two thirds, then pour in the stock. Strain into a jug, discarding the shells.","Heat the rest of the oil in a deep frying pan or casserole. Add the fennel, onion and garlic, season, then cover and gently cook for 10 mins until softened. Meanwhile, peel the potato and cut into 2cm-ish chunks. Put into a pan of cold water, bring to the boil and cook for 5 mins until almost tender. Drain in a colander.","Peel a strip of zest from the orange. Put the zest, star anise, bay and ½ tsp harissa into the pan. Fry gently, uncovered, for 5-10 mins, until the vegetables are soft, sweet and golden.","Stir in the tomato purée, cook for 2 mins, then add the tomatoes and stock. Simmer for 10 mins until the sauce thickens slightly. Season to taste. The sauce can be made ahead, then reheated later in the day. Meantime, scrub the mussels or clams and pull away any stringy beards. Any that are open should be tapped sharply on the worktop – if they don’t close after a few seconds, discard them.","Reheat the sauce if necessary, then stir the potato, chunks of fish and prawns very gently into the stew. Bring back to the boil, then cover and gently simmer for 3 mins. Scatter the mussels or clams over the stew, then cover and cook for 2 mins more or until the shells have opened wide. Discard any that remain closed. The chunks of fish should flake easily and the prawns should be pink through. Scatter with the thyme leaves.","To make the quick rouille, stir the rest of the harissa through the mayonnaise. Serve the stew in bowls, topped with spoonfuls of rouille, which will melt into the sauce and enrich it. Have some good bread ready, as you’ll definitely want to mop up the juices."],"ingredient_names":["prawns","olive oil","dry white wine","fish stock","fennel","onion","garlic","potatoes","orange","star anise","bay leaf","harissa spice","tomato puree","chopped tomatoes","mussels","white fish","thyme","bread"],"allergens":["fish","gluten","shellfish"],"diet_flags":["pescatarian"]},{"source_id":"52920","title":"Chicken Marengo","category":"Chicken","country":"France","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/qpxvuq1511798906.jpg","youtube_url":"https://www.youtube.com/watch?v=U33HYUr-0Fw","source_url":"https://www.bbcgoodfood.com/recipes/3146682/chicken-marengo","ingredients":[{"name":"Olive Oil","measure":"1 tbs"},{"name":"Mushrooms","measure":"300g"},{"name":"Chicken Legs","measure":"4"},{"name":"Passata","measure":"500g"},{"name":"Chicken Stock Cube","measure":"1"},{"name":"Black Olives","measure":"100g"},{"name":"Parsley","measure":"Chopped"}],"steps":["Heat the oil in a large flameproof casserole dish and stir-fry the mushrooms until they start to soften.","Add the chicken legs and cook briefly on each side to colour them a little.","Pour in the passata, crumble in the stock cube and stir in the olives.","Season with black pepper – you shouldn’t need salt.","Cover and simmer for 40 mins until the chicken is tender.","Sprinkle with parsley and serve with pasta and a salad, or mash and green veg, if you like."],"ingredient_names":["olive oil","mushrooms","chicken legs","passata","chicken stock cube","black olives","parsley"],"allergens":[],"diet_flags":[]},{"source_id":"52921","title":"Provençal Omelette Cake","category":"Vegetarian","country":"France","tags":["Egg"],"image_url":"https://www.themealdb.com/images/media/meals/qwtrtp1511799242.jpg","youtube_url":"https://www.youtube.com/watch?v=B7isFo2uP2k","source_url":"https://www.bbcgoodfood.com/recipes/6428/provenal-omelette-cake","ingredients":[{"name":"Eggs","measure":"10"},{"name":"Olive Oil","measure":"1 tbs"},{"name":"Courgettes","measure":"2 finely chopped"},{"name":"Spring Onions","measure":"3 finely chopped"},{"name":"Red Pepper","measure":"4"},{"name":"Garlic Clove","measure":"1 clove peeled crushed"},{"name":"Red Chilli","measure":"1"},{"name":"Cream Cheese","measure":"300g"},{"name":"Milk","measure":"6 tblsp"},{"name":"Chives","measure":"4 tbs"},{"name":"Basil","measure":"2 tbs"},{"name":"Rocket","measure":"to serve"},{"name":"Parmesan","measure":"to serve"}],"steps":["Break the eggs into two bowls, five in each. Whisk lightly and season with salt and pepper. Heat the oil in a pan, add the courgettes and spring onions, then fry gently for about 10 mins until softened. Cool, then stir into one bowl of eggs with a little salt and pepper. Add the roasted peppers to the other bowl of eggs with the garlic, chilli, salt and pepper.","Heat a little oil in a 20-23cm frying pan, preferably non-stick. Pour the eggs with courgette into a measuring jug, then pourabout one-third of the mixture into the pan, swirling it to cover the base of the pan. Cook until the egg is set and lightly browned underneath, then cover the pan with a plate and invert the omelette onto it. Slide it back into the pan to cook the other side. Repeat with the remaining mix to make two more omelettes, adding a little oil to the pan each time. Stack the omelettes onto a plate. Make three omelettes in the same way with the red pepper mixture, then stack them on a separate plate.","Now make the filling. Beat the cheese to soften it, then beat in the milk to make a spreadable consistency. Stir in the herbs, salt and pepper. Line a deep, 20-23cm round cake tin with cling film (use a tin the same size as the frying pan). Select the best red pepper omelette and place in the tin, prettiest side down. Spread with a thin layer of cheese filling, then cover with a courgette omelette. Repeat, alternating the layers, until all the omelettes and filling are in the tin, finishing with an omelette. Flip the cling film over the omelette, then chill for up to 24 hrs.","To serve, invert the omelette cake onto a serving plate and peel off the cling film. Pile rocket on the top and scatter over the cheese, a drizzle of olive oil and a little freshly ground black pepper. Serve cut into wedges."],"ingredient_names":["eggs","olive oil","courgettes","spring onions","red pepper","garlic clove","red chilli","cream cheese","milk","chives","basil","rocket","parmesan"],"allergens":["dairy","eggs"],"diet_flags":["pescatarian","vegetarian"]},{"source_id":"52926","title":"Tourtiere","category":"Pork","country":"Canada","tags":["Pie","MainMeal","BBQ","Cake"],"image_url":"https://www.themealdb.com/images/media/meals/ytpstt1511814614.jpg","youtube_url":"https://www.youtube.com/watch?v=A96hbwobKKs","source_url":"https://www.bbcgoodfood.com/recipes/531644/spiced-pork-and-potato-pie","ingredients":[{"name":"Potatoes","measure":"1 medium"},{"name":"Sunflower Oil","measure":"1 tsp"},{"name":"Minced Pork","measure":"500g"},{"name":"Onion","measure":"1 finely chopped"},{"name":"Garlic Clove","measure":"1 finely chopped"},{"name":"Cinnamon","measure":"¼ tsp"},{"name":"Allspice","measure":"¼ tsp"},{"name":"Nutmeg","measure":"¼ tsp"},{"name":"Vegetable Stock","measure":"100ml"},{"name":"Shortcrust Pastry","measure":"400g"},{"name":"Egg","measure":"To Glaze"}],"steps":["Heat oven to 200C/180C fan/gas 6. Boil the potato until tender, drain and mash, then leave to cool. Heat the oil in a non-stick pan, add the mince and onion and quickly fry until browned. Add the garlic, spices, stock, plenty of pepper and a little salt and mix well. Remove from the heat, stir into the potato and leave to cool.","Roll out half the pastry and line the base of a 20-23cm pie plate or flan tin. Fill with the pork mixture and brush the edges of the pastry with water. Roll out the remaining dough and cover the pie. Press the edges of the pastry to seal, trimming off the excess. Prick the top of the pastry case to allow steam to escape and glaze the top with the beaten egg.","Bake for 30 mins until the pastry is crisp and golden. Serve cut into wedges with a crisp green salad. Leftovers are good cold for lunch the next day, served with a selection of pickles."],"ingredient_names":["potatoes","sunflower oil","minced pork","onion","garlic clove","cinnamon","allspice","nutmeg","vegetable stock","shortcrust pastry","egg"],"allergens":["eggs","gluten"],"diet_flags":[]},{"source_id":"52927","title":"Montreal Smoked Meat","category":"Beef","country":"Canada","tags":["Speciality","Snack","StrongFlavor"],"image_url":"https://www.themealdb.com/images/media/meals/uttupv1511815050.jpg","youtube_url":"https://www.youtube.com/watch?v=g5oCDoyxbBk","source_url":"http://www.meatwave.com/blog/montreal-smoked-meat-recipe","ingredients":[{"name":"Beef Brisket","measure":"1"},{"name":"Salt","measure":"3 tbs"},{"name":"Black Pepper","measure":"3 tbs"},{"name":"Coriander","measure":"1 tbs"},{"name":"Sugar","measure":"1 tbs"},{"name":"Bay Leaf","measure":"1 tsp"},{"name":"Cloves","measure":"1 tsp"},{"name":"Black Pepper","measure":"3 tbs"},{"name":"Coriander","measure":"1 tbs"},{"name":"Paprika","measure":"1 tbs"},{"name":"Garlic","measure":"1 tbs"},{"name":"Onion","measure":"1 tbs"},{"name":"Dill","measure":"1 tbs"},{"name":"English Mustard","measure":"1 tsp"},{"name":"Celery Salt","measure":"1 tbs"},{"name":"Red Pepper Flakes","measure":"1 tsp"}],"steps":["To make the cure, in a small bowl mix together salt, pink salt, black pepper, coriander, sugar, bay leaf, and cloves. Coat entire brisket with the cure and place in an extra-large resealable plastic bag. Place in the coldest part of the refrigerator and cure for 4 days, flipping brisket twice a day.","Remove brisket from bag and wash as much cure off as possible under cold running water. Place brisket in a large container and fill with water and let soak for 2 hours, replacing water every 30 minutes. Remove from water and pat dry with paper towels.","To make the rub, mix together black pepper, coriander, paprika, garlic powder, onion powder, dill weed, mustard, celery seed, and crushed red papper in a small bowl. Coat entire brisket with the rub.","Fire up smoker or grill to 225 degrees, adding chunks of smoking wood chunks when at temperature. When wood is ignited and producing smoke, place brisket in, fat side up, and smoke until an instant read thermometer registers 165 degrees when inserted into thickest part of the brisket, about 6 hours.","Transfer brisket to large roasting pan with V-rack. Place roasting pan over two burners on stovetop and fill with 1-inch of water. Bring water to a boil over high heat, reduce heat to medium, cover roasting pan with aluminum foil, and steam brisket until an instant read thermometer registers 180 degrees when inserted into thickest part of the meat, 1 to 2 hours, adding more hot water as needed.","Transfer brisket to cutting board and let cool slightly. Slice and serve, preferably on rye with mustard."],"ingredient_names":["beef brisket","salt","black pepper","coriander","sugar","bay leaf","cloves","black pepper","coriander","paprika","garlic","onion","dill","english mustard","celery salt","red pepper flakes"],"allergens":[],"diet_flags":[]},{"source_id":"52930","title":"Pate Chinois","category":"Beef","country":"Canada","tags":["MainMeal","Alcoholic"],"image_url":"https://www.themealdb.com/images/media/meals/yyrrxr1511816289.jpg","youtube_url":"https://www.youtube.com/watch?v=QRFqnLkEv3I","source_url":"https://www.ricardocuisine.com/en/recipes/5541-pate-chinois-shepherd--s-pie-","ingredients":[{"name":"Potatoes","measure":"4 cups"},{"name":"Butter","measure":"60ml"},{"name":"Milk","measure":"½ cup"},{"name":"Minced Beef","measure":"450g"},{"name":"Onion","measure":"1 finely chopped"},{"name":"Creamed Corn","measure":"500ml"},{"name":"Paprika","measure":"to taste"},{"name":"Parsley","measure":"to taste"},{"name":"Salt","measure":"Dash"},{"name":"Pepper","measure":"Dash"}],"steps":["In a large pot of salted water, cook the potatoes until they are very tender. Drain.","With a masher, coarsely crush the potatoes with at least 30 ml (2 tablespoons) of butter. With an electric mixer, purée with the milk. Season with salt and pepper. Set aside.","With the rack in the middle position, preheat the oven to 190 °C (375 °F).","In a large skillet, brown the onion in the remaining butter. Add the meat and cook until golden brown. Season with salt and pepper. Remove from the heat.","Lightly press the meat at the bottom of a 20-cm (8-inch) square baking dish. Cover with the corn and the mashed potatoes. Sprinkle with paprika and parsley.","Bake for about 30 minutes. Finish cooking under the broiler. Let cool for 10 minutes."],"ingredient_names":["potatoes","butter","milk","minced beef","onion","creamed corn","paprika","parsley","salt","pepper"],"allergens":["dairy"],"diet_flags":[]},{"source_id":"52933","title":"Rappie Pie","category":"Chicken","country":"Canada","tags":["Pie"],"image_url":"https://www.themealdb.com/images/media/meals/ruwpww1511817242.jpg","youtube_url":"https://www.youtube.com/watch?v=Ys2kZnTVXAM","source_url":"http://allrecipes.com/recipe/234025/rappie-pie/","ingredients":[{"name":"Butter","measure":"2 tbs"},{"name":"Onions","measure":"2 chopped"},{"name":"Chicken Stock","measure":"4 qt"},{"name":"Chicken Breast","measure":"1.5kg"},{"name":"Potatoes","measure":"4kg"},{"name":"Salt","measure":"2 tbs"},{"name":"Black Pepper","measure":"1tbsp"}],"steps":["Preheat oven to 400 degrees F (200 degrees C). Grease a 10x14x2-inch baking pan.","Heat margarine in a skillet over medium heat; stir in onion. Cook and stir until onion has softened and turned translucent, about 5 minutes. Reduce heat to low and continue to cook and stir until onion is very tender and dark brown, about 40 minutes more.","Bring chicken broth to a boil in a large pot; stir in chicken breasts, reduce heat, and simmer until chicken is no longer pink at the center, about 20 minutes. Remove from heat. Remove chicken breasts to a plate using a slotted spoon; reserve broth.","Juice potatoes with an electric juicer; place dry potato flesh into a bowl and discard juice. Stir salt and pepper into potatoes; stir in enough reserved broth to make the mixture the consistency of oatmeal. Set remaining broth aside.","Spread half of potato mixture evenly into the prepared pan. Lay cooked chicken breast evenly over potatoes; scatter caramelized onion evenly over chicken. Spread remaining potato mixture over onions and chicken to cover.","Bake in the preheated oven until golden brown, about 1 hour. Reheat chicken broth; pour over individual servings as desired."],"ingredient_names":["butter","onions","chicken stock","chicken breast","potatoes","salt","black pepper"],"allergens":["dairy"],"diet_flags":[]},{"source_id":"52934","title":"Chicken Basquaise","category":"Chicken","country":"France","tags":["Meat"],"image_url":"https://www.themealdb.com/images/media/meals/wruvqv1511880994.jpg","youtube_url":"https://www.youtube.com/watch?v=emfm6TwsVhg","source_url":"https://www.rivercottage.net/recipes/chicken-basquaise","ingredients":[{"name":"Chicken","measure":"1.5kg"},{"name":"Butter","measure":"25g"},{"name":"Olive Oil","measure":"6 tblsp"},{"name":"Red Onions","measure":"2 sliced"},{"name":"Red Pepper","measure":"3 Large"},{"name":"Chorizo","measure":"130g"},{"name":"Sun-Dried Tomatoes","measure":"8"},{"name":"Garlic","measure":"6 cloves sliced"},{"name":"Basmati Rice","measure":"300g"},{"name":"Tomato Puree","measure":"drizzle"},{"name":"Paprika","measure":"½ tsp"},{"name":"Bay Leaves","measure":"4"},{"name":"Thyme","measure":"Handful"},{"name":"Chicken Stock","measure":"350ml"},{"name":"Dry White Wine","measure":"180g"},{"name":"Lemons","measure":"2"},{"name":"Black Olives","measure":"100g"},{"name":"Salt","measure":"to serve"},{"name":"Pepper","measure":"to serve"}],"steps":["Preheat the oven to 180°C/Gas mark 4. Have the chicken joints ready to cook. Heat the butter and 3 tbsp olive oil in a flameproof casserole or large frying pan. Brown the chicken pieces in batches on both sides, seasoning them with salt and pepper as you go. Don't crowd the pan - fry the chicken in small batches, removing the pieces to kitchen paper as they are done.","Add a little more olive oil to the casserole and fry the onions over a medium heat for 10 minutes, stirring frequently, until softened but not browned. Add the rest of the oil, then the peppers and cook for another 5 minutes.","Add the chorizo, sun-dried tomatoes and garlic and cook for 2-3 minutes. Add the rice, stirring to ensure it is well coated in the oil. Stir in the tomato paste, paprika, bay leaves and chopped thyme. Pour in the stock and wine. When the liquid starts to bubble, turn the heat down to a gentle simmer. Press the rice down into the liquid if it isn't already submerged and place the chicken on top. Add the lemon wedges and olives around the chicken.","Cover and cook in the oven for 50 minutes. The rice should be cooked but still have some bite, and the chicken should have juices that run clear when pierced in the thickest part with a knife. If not, cook for another 5 minutes and check again."],"ingredient_names":["chicken","butter","olive oil","red onions","red pepper","chorizo","sun-dried tomatoes","garlic","basmati rice","tomato puree","paprika","bay leaves","thyme","chicken stock","dry white wine","lemons","black olives","salt","pepper"],"allergens":["dairy"],"diet_flags":[]},{"source_id":"52935","title":"Steak Diane","category":"Beef","country":"France","tags":["DateNight","Expensive","Meat","MainMeal","Cheasy"],"image_url":"https://www.themealdb.com/images/media/meals/vussxq1511882648.jpg","youtube_url":"https://www.youtube.com/watch?v=9rWZNHkrsNg","source_url":"https://www.saveur.com/article/Recipes/Classic-Steak-Diane","ingredients":[{"name":"Canola Oil","measure":"2 tbs"},{"name":"Beef Fillet","measure":"4"},{"name":"Beef Stock","measure":"1 1/2 cup"},{"name":"Butter","measure":"2 tbs"},{"name":"Garlic","measure":"2 cloves minced"},{"name":"Challots","measure":"1 medium finely diced"},{"name":"Mushrooms","measure":"4 oz"},{"name":"Brandy","measure":"¼ cup"},{"name":"Heavy Cream","measure":"¼ cup"},{"name":"Dijon Mustard","measure":"1 tbs"},{"name":"Worcestershire Sauce","measure":"1 tbs"},{"name":"Tabasco Sauce","measure":"Dash"},{"name":"Parsley","measure":"1 tbs minced"},{"name":"Chives","measure":"1 tbs minced"},{"name":"Salt","measure":"to taste"},{"name":"Pepper","measure":"to taste"}],"steps":["Heat oil in a 12\" skillet over medium-high heat.","Season steaks with salt and pepper, and add to skillet; cook, turning once, until browned on both sides and cooked to desired doneness, about 4 to 5 minutes for medium-rare.","Transfer steaks to a plate, and set aside.","Return skillet to high heat, and add stock; cook until reduced until to 1⁄2 cup, about 10 minutes.","Pour into a bowl, and set aside.","Return skillet to heat, and add butter; add garlic and shallots, and cook, stirring, until soft, about 2 minutes.","Add mushrooms, and cook, stirring, until they release any liquid and it evaporates and mushrooms begin to brown, about 2 minutes.","Add cognac, and light with a match to flambée; cook until flame dies down.","Stir in reserved stock, cream, Dijon, Worcestershire, and hot sauce, and then return steaks to skillet; cook, turning in sauce, until warmed through and sauce is thickened, about 4 minutes.","Transfer steak to serving plates and stir parsley and chives into sauce; pour sauce over steaks to serve."],"ingredient_names":["canola oil","beef fillet","beef stock","butter","garlic","challots","mushrooms","brandy","heavy cream","dijon mustard","worcestershire sauce","tabasco sauce","parsley","chives","salt","pepper"],"allergens":["dairy","fish","gluten"],"diet_flags":[]},{"source_id":"52936","title":"Saltfish and Ackee","category":"Seafood","country":"Jamaica","tags":["Speciality"],"image_url":"https://www.themealdb.com/images/media/meals/vytypy1511883765.jpg","youtube_url":"https://www.youtube.com/watch?v=nbfNyZbdn2I","source_url":"https://www.bbc.co.uk/food/recipes/saltfish__ackee_with_64803","ingredients":[{"name":"Salt Cod","measure":"450g"},{"name":"Ackee","measure":"400g"},{"name":"Onion","measure":"1 chopped"},{"name":"Paprika","measure":"1 tsp"},{"name":"Curry Powder","measure":"2 tsp"},{"name":"Jerusalem Artichokes","measure":"2 tsp"},{"name":"Hotsauce","measure":"1 tsp"},{"name":"Red Pepper","measure":"1 sliced"},{"name":"Yellow Pepper","measure":"1 sliced"},{"name":"Tomatoes","measure":"200g"},{"name":"Salt","measure":"to taste"},{"name":"Pepper","measure":"to taste"},{"name":"Self-raising Flour","measure":"250g"},{"name":"Suet","measure":"30g"},{"name":"Salt","measure":"pinch"},{"name":"Olive Oil","measure":"for frying"}],"steps":["For the saltfish, soak the salt cod overnight, changing the water a couple of times.","Drain, then put the cod in a large pan of fresh water and bring to the boil. Drain again, add fresh water and bring to the boil again.","Simmer for about five minutes, or until cooked through, then drain and flake the fish into large pieces. Discard any skin or bones.","For the dumplings, mix the flour and suet with a pinch of salt and 250ml/9fl oz water to make a dough.","Wrap the mixture in clingfilm and leave in the fridge to rest.","Open the can of ackee, drain and rinse, then set aside.","Heat a tablespoon of olive oil in a pan and fry the onion until softened but not brown.","Add the spices, seasoning, pepper sauce and sliced peppers and continue to fry until the peppers are tender.","Add the chopped tomatoes, then the salt cod and mix together. Lastly stir in the ackee very gently and leave to simmer until ready to serve.","When you’re almost ready to eat, heat about 1cm/½in vegetable oil in a frying pan and heat until just smoking.","Shape the dumpling mix into plum-size balls and shallow-fry until golden-brown. (CAUTION: hot oil can be dangerous. Do not leave the pan unattended.)","Drain the dumplings on kitchen paper and serve with the saltfish and ackee."],"ingredient_names":["salt cod","ackee","onion","paprika","curry powder","jerusalem artichokes","hotsauce","red pepper","yellow pepper","tomatoes","salt","pepper","self-raising flour","suet","salt","olive oil"],"allergens":["fish","gluten"],"diet_flags":[]},{"source_id":"52937","title":"Jerk chicken with rice & peas","category":"Chicken","country":"Jamaica","tags":["Chilli","Curry"],"image_url":"https://www.themealdb.com/images/media/meals/tytyxu1515363282.jpg","youtube_url":"https://www.youtube.com/watch?v=qfchrS2D_v4","source_url":"https://www.bbcgoodfood.com/recipes/2369635/jerk-chicken-with-rice-and-peas","ingredients":[{"name":"Chicken Thighs","measure":"12"},{"name":"Lime","measure":"1/2"},{"name":"Spring Onions","measure":"1  bunch"},{"name":"Ginger","measure":"1 tbs chopped"},{"name":"Garlic","measure":"3 cloves"},{"name":"Onion","measure":"1/2"},{"name":"Red Chilli","measure":"3 chopped"},{"name":"Thyme","measure":"1/2 teaspoon"},{"name":"Lime","measure":"Juice of 1"},{"name":"Soy Sauce","measure":"2 tbs"},{"name":"Vegetable Oil","measure":"2 tbs"},{"name":"Brown Sugar","measure":"3 tbs"},{"name":"Allspice","measure":"1 tbs"},{"name":"Basmati Rice","measure":"200g"},{"name":"Coconut Milk","measure":"400g"},{"name":"Spring Onions","measure":"1  bunch"},{"name":"Thyme","measure":"2 sprigs"},{"name":"Garlic","measure":"2 cloves chopped"},{"name":"Allspice","measure":"1 tbs"},{"name":"Kidney Beans","measure":"800g"}],"steps":["To make the jerk marinade, combine all the ingredients in a food processor along with 1 tsp salt, and blend to a purée. If you’re having trouble getting it to blend, just keep turning off the blender, stirring the mixture, and trying again. Eventually it will start to blend up – don’t be tempted to add water, as you want a thick paste.","Taste the jerk mixture for seasoning – it should taste pretty salty, but not unpleasantly, puckering salty. You can now throw in more chillies if it’s not spicy enough for you. If it tastes too salty and sour, try adding in a bit more brown sugar until the mixture tastes well balanced.","Make a few slashes in the chicken thighs and pour the marinade over the meat, rubbing it into all the crevices. Cover and leave to marinate overnight in the fridge.","If you want to barbecue your chicken, get the coals burning 1 hr or so before you’re ready to cook. Authentic jerked meats are not exactly grilled as we think of grilling, but sort of smoke-grilled. To get a more authentic jerk experience, add some wood chips to your barbecue, and cook your chicken over slow, indirect heat for 30 mins. To cook in the oven, heat to 180C/160C fan/gas 4. Put the chicken pieces in a roasting tin with the lime halves and cook for 45 mins until tender and cooked through.","While the chicken is cooking, prepare the rice & peas. Rinse the rice in plenty of cold water, then tip it into a large saucepan with all the remaining ingredients except the kidney beans. Season with salt, add 300ml cold water and set over a high heat. Once the rice begins to boil, turn it down to a medium heat, cover and cook for 10 mins.","Add the beans to the rice, then cover with a lid. Leave off the heat for 5 mins until all the liquid is absorbed. Squeeze the roasted lime over the chicken and serve with the rice & peas, and some hot sauce if you like it really spicy."],"ingredient_names":["chicken thighs","lime","spring onions","ginger","garlic","onion","red chilli","thyme","lime","soy sauce","vegetable oil","brown sugar","allspice","basmati rice","coconut milk","spring onions","thyme","garlic","allspice","kidney beans"],"allergens":["gluten","soy"],"diet_flags":[]},{"source_id":"52938","title":"Jamaican Beef Patties","category":"Beef","country":"Jamaica","tags":["Snack","Spicy"],"image_url":"https://www.themealdb.com/images/media/meals/wsqqsw1515364068.jpg","youtube_url":"https://www.youtube.com/watch?v=ypQjoiZiTac","source_url":"https://www.thespruce.com/jamaican-beef-patties-recipe-2137762","ingredients":[{"name":"Plain Flour","measure":"4 cups"},{"name":"Salt","measure":"1 tsp"},{"name":"Curry Powder","measure":"1 tsp"},{"name":"Butter","measure":"250g"},{"name":"Water","measure":"1 cup"},{"name":"Minced Beef","measure":"900g"},{"name":"Allspice","measure":"1 tsp"},{"name":"Black Pepper","measure":"1/2 tsp"},{"name":"Vegetable Oil","measure":"2 tbs"},{"name":"Onions","measure":"1 cup"},{"name":"Red Pepper","measure":"Ground"},{"name":"Garlic","measure":"2 tsp ground"},{"name":"Thyme","measure":"1 tbs"},{"name":"Salt","measure":"1/4 tsp"},{"name":"Tomato Ketchup","measure":"2 tbs"},{"name":"Water","measure":"2 cups"},{"name":"Onions","measure":"1/2 cup"},{"name":"Egg","measure":"1 beaten"},{"name":"Water","measure":"1 tbs"},{"name":"Water","measure":"1/4 cup"}],"steps":["Make the Pastry Dough","To a large bowl, add flour, 1 teaspoon salt, and turmeric and mix thoroughly.","Rub shortening into flour until there are small pieces of shortening completely covered with flour.","Pour in 1/2 cup of the ice water and mix with your hands to bring the dough together. Keep adding ice water 2 to 3 tablespoons at a time until the mixture forms a dough.","At this stage, you can cut the dough into 2 large pieces, wrap in plastic and refrigerate for 30 minutes before using it.","Alternatively, cut the dough into 10 to 12 equal pieces, place on a platter or baking sheet, cover securely with plastic wrap and let chill for 30 minutes while you make the filling.","Make the Filling","Add ground beef to a large bowl. Sprinkle in allspice and black pepper. Mix together and set aside.","Heat oil in a skillet until hot.","Add onions and sauté until translucent. Add hot pepper, garlic and thyme and continue to sauté for another minute. Add 1/4 teaspoon salt.","Add seasoned ground beef and toss to mix, breaking up any clumps, and let cook until the meat is no longer pink.","Add ketchup and more salt to taste.","Pour in 2 cups of water and stir. Bring the mixture to a boil then reduce heat and let simmer until most of the liquid has evaporated and whatever is remaining has reduced to a thick sauce.","Fold in green onions. Remove from heat and let cool completely.","Assemble the Patties","Beat the egg and water together to make an egg wash. Set aside.","Now you can prepare the dough in two ways.","First Method: Flour the work surface and rolling pin. If you had cut it into 2 large pieces, then take one of the large pieces and roll it out into a very large circle. Take a bowl with a wide rim (about 5 inches) and cut out three circles.","Place about 3 heaping tablespoons of the filling onto 1/2 of each circle. Dip a finger into the water and moisten the edges of the pastry. Fold over the other half and press to seal.","Take a fork and crimp the edges. Cut off any extra to make it look neat and uniform. Place on a parchment-lined baking sheet and continue to work until you have rolled all the dough and filled the patties.","Second Method: If you had pre-cut the dough into individual pieces, work with one piece of dough at a time. Roll it out on a floured surface into a 5-inch circle or a little larger. Don’t worry if the edges are not perfect.","Place 3 heaping tablespoons of the filling on one side of the circle. Dip a finger into the water and moisten the edges of the pastry. Fold over the other half and press to seal.","Take a fork and crimp the edges. Cut off any extra to make it look neat and uniform. Place on a parchment-lined baking sheet and continue work until you have rolled all the dough and filled the patties.","Frying and Serving the Patties","After forming the patties, place the pans in the refrigerator while you heat the oven to 350 F.","Just before adding the pans with the patties to the oven, brush the patties with egg wash.","Bake patties for 30 minutes or until golden brown.","Cool on wire racks.","Serve warm."],"ingredient_names":["plain flour","salt","curry powder","butter","water","minced beef","allspice","black pepper","vegetable oil","onions","red pepper","garlic","thyme","salt","tomato ketchup","water","onions","egg","water","water"],"allergens":["dairy","eggs","gluten"],"diet_flags":[]},{"source_id":"52940","title":"Brown Stew Chicken","category":"Chicken","country":"Jamaica","tags":["Stew"],"image_url":"https://www.themealdb.com/images/media/meals/sypxpx1515365095.jpg","youtube_url":"https://www.youtube.com/watch?v=_gFB1fkNhXs","source_url":"http://www.geniuskitchen.com/recipe/authentic-jamaican-brown-stew-chicken-347996","ingredients":[{"name":"Chicken","measure":"1 whole"},{"name":"Tomato","measure":"1 chopped"},{"name":"Onions","measure":"2 chopped"},{"name":"Garlic Clove","measure":"2 chopped"},{"name":"Red Pepper","measure":"1 chopped"},{"name":"Carrots","measure":"1 chopped"},{"name":"Lime","measure":"1"},{"name":"Thyme","measure":"2 tsp"},{"name":"Allspice","measure":"1 tsp"},{"name":"Soy Sauce","measure":"2 tbs"},{"name":"Cornstarch","measure":"2 tsp"},{"name":"Coconut Milk","measure":"2 cups"},{"name":"Vegetable Oil","measure":"1 tbs"}],"steps":["Squeeze lime over chicken and rub well. Drain off excess lime juice.","Combine tomato, scallion, onion, garlic, pepper, thyme, pimento and soy sauce in a large bowl with the chicken pieces. Cover and marinate at least one hour.","Heat oil in a dutch pot or large saucepan. Shake off the seasonings as you remove each piece of chicken from the marinade. Reserve the marinade for sauce.","Lightly brown the chicken a few pieces at a time in very hot oil. Place browned chicken pieces on a plate to rest while you brown the remaining pieces.","Drain off excess oil and return the chicken to the pan. Pour the marinade over the chicken and add the carrots. Stir and cook over medium heat for 10 minutes.","Mix flour and coconut milk and add to stew, stirring constantly. Turn heat down to minimum and cook another 20 minutes or until tender."],"ingredient_names":["chicken","tomato","onions","garlic clove","red pepper","carrots","lime","thyme","allspice","soy sauce","cornstarch","coconut milk","vegetable oil"],"allergens":["gluten","soy"],"diet_flags":[]},{"source_id":"52941","title":"Red Peas Soup","category":"Beef","country":"Jamaica","tags":["Soup","SideDish"],"image_url":"https://www.themealdb.com/images/media/meals/sqpqtp1515365614.jpg","youtube_url":"https://www.youtube.com/watch?v=1ogCfDXotMw","source_url":"http://caribbeanpot.com/caribbean-red-peas-soup/","ingredients":[{"name":"Kidney Beans","measure":"2 cups"},{"name":"Carrots","measure":"1 large"},{"name":"Spring Onions","measure":"2 chopped"},{"name":"Thyme","measure":"4 sprigs"},{"name":"Onion","measure":"1 Diced"},{"name":"Black Pepper","measure":"1/2 tsp"},{"name":"Red Pepper","measure":"2 chopped"},{"name":"Garlic Clove","measure":"4 Mashed"},{"name":"Allspice","measure":"1 tbs"},{"name":"Beef","measure":"2 Lbs"},{"name":"Water","measure":"2L"},{"name":"Potatoes","measure":"4"},{"name":"Plain Flour","measure":"1 cup"},{"name":"Water","measure":"1/4 cup"},{"name":"Coconut Milk","measure":"1 cup"}],"steps":["Wash and rinse the dried kidney beans.. then cover with water in a deep bowl. Remember as they soak they will expand to at least triple the size they were originally so add a lot of water to the bowl. Soak them overnight or for at least 2 hrs to make the cooking step go quicker. I tossed out the water they were soaked in after it did the job.","Have your butcher cut the salted pigtail into 2 inch pieces as it will be very difficult to cut with an ordinary kitchen knife. Wash, then place a deep pot with water and bring to a boil. Cook for 20 minutes, then drain + rinse and repeat (boil again in water). The goal is to make the pieces of pig tails tender and to remove most of the salt it was cured in.","Time to start the soup. Place everything in the pot (except the flour and potato), then cover with water and place on a high flame to bring to a boil. As it comes to a boil, skim off any scum/froth at the top and discard. Reduce the heat to a gentle boil and allow it to cook for 1 hr and 15 mins.. basically until the beans are tender and start falling apart.","It’s now time to add the potato (and Yams etc if you’re adding it) as well as the coconut milk and continue cooking for 15 minutes.","Now is a good time to start making the basic dough for the spinner dumplings. Mix the flour and water (add a pinch of salt if you want) until you have a soft/smooth dough. allow it to rest for 5 minutes, then pinch of a tablespoon at a time and roll between your hands to form a cigarette shape.","Add them to the pot, stir well and continue cooking for another 15 minutes on a rolling boil.","You’ll notice that I didn’t add any salt to the pot as the remaining salt from the salted pigtails will be enough to properly season this dish. However you can taste and adjust accordingly. Lets recap the timing part of things so you’re not confused. Cook the base of the soup for 1 hr and 15 minute or until tender, then add the potatoes and cook for 15 minutes, then add the dumplings and cook for a further 15 minutes. Keep in mind that this soup will thicken quite a bit as it cools.","While this is not a traditional recipe to any one specific island, versions of this soup (sometimes called stewed peas) can be found throughout the Caribbean, Latin America and Africa. A hearty bowl of this soup will surely give you the sleepies (some may call it ethnic fatigue). You can certainly freeze the leftovers and heat it up another day."],"ingredient_names":["kidney beans","carrots","spring onions","thyme","onion","black pepper","red pepper","garlic clove","allspice","beef","water","potatoes","plain flour","water","coconut milk"],"allergens":["gluten"],"diet_flags":[]},{"source_id":"52942","title":"Roast fennel and aubergine paella","category":"Vegan","country":"Spain","tags":["Vegan","Paella"],"image_url":"https://www.themealdb.com/images/media/meals/1520081754.jpg","youtube_url":"https://www.youtube.com/watch?v=H5SmjR-fxUs","source_url":"https://www.homestylemag.co.uk/recipe/517/main-courses/roast-fennel-and-aubergine-paella","ingredients":[{"name":"Baby Aubergine","measure":"6 small"},{"name":"Fennel","measure":"4 small"},{"name":"Red Pepper","measure":"1 thinly sliced"},{"name":"Courgettes","measure":"1 medium"},{"name":"Onion","measure":"1 finely chopped"},{"name":"Paella Rice","measure":"300g"},{"name":"Paprika","measure":"1 tsp"},{"name":"Saffron","measure":"pinch"},{"name":"White Wine","measure":"200ml"},{"name":"Vegetable Stock","measure":"700ml"},{"name":"Frozen Peas","measure":"100g"},{"name":"Lemon","measure":"1 chopped"},{"name":"Parsley","measure":"Handful"},{"name":"Salt","measure":"pinch"},{"name":"Black Pepper","measure":"pinch"}],"steps":["1 Put the fennel, aubergine, pepper and courgette in a roasting tray. Add a glug of olive oil, season with salt and pepper and toss around to coat the veggies in the oil. Roast in the oven for 20 minutes, turning a couple of times until the veg are pretty much cooked through and turning golden.","2 Meanwhile, heat a paella pan or large frying pan over a low– medium heat and add a glug of olive oil. Sauté the onion for 8–10 minutes until softened. Increase the heat to medium and stir in the rice, paprika and saffron. Cook for around 1 minute to start toasting the rice, then add the white wine. Reduce by about half before stirring in two-thirds of the stock. Reduce to a simmer and cook for 10 minutes without a lid, stirring a couple of times.","3 Stir in the peas, add some seasoning, then gently mix in the roasted veg. Pour over the remaining stock, arrange the lemon wedges on top and cover with a lid or some aluminium foil. Cook for a further 10 minutes.","4 To ensure you get the classic layer of toasted rice at the bottom of the pan, increase the heat to high until you hear a slight crackle. Remove from the heat and sit for 5 minutes before sprinkling over the parsley and serving."],"ingredient_names":["baby aubergine","fennel","red pepper","courgettes","onion","paella rice","paprika","saffron","white wine","vegetable stock","frozen peas","lemon","parsley","salt","black pepper"],"allergens":[],"diet_flags":["pescatarian","vegan","vegetarian"]},{"source_id":"52943","title":"Oxtail with broad beans","category":"Beef","country":"Jamaica","tags":["Heavy","MainMeal","Speciality"],"image_url":"https://www.themealdb.com/images/media/meals/1520083578.jpg","youtube_url":"https://www.youtube.com/watch?v=DIhxk-98Hz8","source_url":"http://allrecipes.co.uk/recipe/5392/jamaican-oxtail-with-broad-beans.aspx","ingredients":[{"name":"Oxtail","measure":"450g"},{"name":"Onion","measure":"1 chopped"},{"name":"Spring Onions","measure":"1"},{"name":"Garlic","measure":"2 cloves minced"},{"name":"Ginger","measure":"1 tsp"},{"name":"Scotch Bonnet","measure":"1 chopped"},{"name":"Soy Sauce","measure":"2 tbs"},{"name":"Fresh Thyme","measure":"1 chopped"},{"name":"Vegetable Oil","measure":"2 tbs"},{"name":"Water","measure":"350ml"},{"name":"Broad Beans","measure":"200g"},{"name":"Corn Flour","measure":"1 tbs"},{"name":"Water","measure":"2 tbs"}],"steps":["Toss the oxtail with the onion, spring onion, garlic, ginger, chilli, soy sauce, thyme, salt and pepper.","Heat the vegetable oil in a large frying pan over medium-high heat.","Brown the oxtail in the pan until browned all over, about 10 minutes.","Place into a pressure cooker, and pour in 375ml water.","Cook at pressure for 25 minutes, then remove from heat, and remove the lid according to manufacturer's directions.","Add the broad beans and pimento berries, and bring to a simmer over medium-high heat.","Dissolve the cornflour in 2 tablespoons water, and stir into the simmering oxtail.","Cook and stir a few minutes until the sauce has thickened, and the broad beans are tender."],"ingredient_names":["oxtail","onion","spring onions","garlic","ginger","scotch bonnet","soy sauce","fresh thyme","vegetable oil","water","broad beans","corn flour","water"],"allergens":["gluten","soy"],"diet_flags":[]},{"source_id":"52944","title":"Escovitch Fish","category":"Seafood","country":"Jamaica","tags":["Seafood","Spicy","Speciality","Easter"],"image_url":"https://www.themealdb.com/images/media/meals/1520084413.jpg","youtube_url":"https://www.youtube.com/watch?v=nF6DOtGE6k8","source_url":"https://www.africanbites.com/jamaican-escovitched-fish/","ingredients":[{"name":"Red Snapper","measure":"2 Pounds"},{"name":"Vegetable Oil","measure":"1/2 cup"},{"name":"Garlic","measure":"1 clove peeled crushed"},{"name":"Ginger","measure":"1/2 tsp"},{"name":"Thyme","measure":"2 sprigs"},{"name":"Bay Leaf","measure":"1"},{"name":"Red Pepper","measure":"0.5"},{"name":"Yellow Pepper","measure":"0.5"},{"name":"Onion","measure":"1 sliced"},{"name":"Carrots","measure":"1 chopped"},{"name":"Sugar","measure":"1 tbs"},{"name":"Allspice","measure":"1/2 tsp"},{"name":"Worcestershire Sauce","measure":"1 tsp"},{"name":"Scotch Bonnet","measure":"1"},{"name":"Lime","measure":"1"},{"name":"Malt Vinegar","measure":"3/4 cup"},{"name":"Pepper","measure":"pinch"}],"steps":["Rinse fish; rub with lemon or lime, seasoned with salt and pepper or use your favorite seasoning. I used creole seasoning. Set aside or place in the oven to keep it warm until sauce is ready.","In large skillet heat oil over medium heat, until hot, add the fish, cook each side- for about 5-7 minutes until cooked through and crispy on both sides. Remove fish and set aside. Drain oil and leave about 2-3 tablespoons of oil","Add, bay leave, garlic and ginger, stir-fry for about a minute making sure the garlic does not burn","Then add onion, bell peppers, thyme, scotch bonnet, sugar, all spice-continue stirring for about 2-3 minutes. Add vinegar, mix an adjust salt and pepper according to preference. Let it simmer for about 2 more minutes.","Discard bay leave, thyme spring and serve over fish with a side of this bammy. You may make the sauce about 2 days in advance."],"ingredient_names":["red snapper","vegetable oil","garlic","ginger","thyme","bay leaf","red pepper","yellow pepper","onion","carrots","sugar","allspice","worcestershire sauce","scotch bonnet","lime","malt vinegar","pepper"],"allergens":["fish","gluten"],"diet_flags":["pescatarian"]},{"source_id":"52945","title":"Kung Pao Chicken","category":"Chicken","country":"China","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/1525872624.jpg","youtube_url":"https://www.youtube.com/watch?v=QqdcCHQlOe0","source_url":"http://allrecipes.co.uk/recipe/1773/kung-pao-chicken.aspx","ingredients":[{"name":"Sake","measure":"2 tbs"},{"name":"Soy Sauce","measure":"2 tbs"},{"name":"Sesame Seed Oil","measure":"2 tbs"},{"name":"Corn Flour","measure":"2 tbs"},{"name":"Water","measure":"2 tbs"},{"name":"Chicken","measure":"500g"},{"name":"Chilli Powder","measure":"1 tbs"},{"name":"Rice Vinegar","measure":"1 tsp"},{"name":"Brown Sugar","measure":"1 tbs"},{"name":"Spring Onions","measure":"4 Chopped"},{"name":"Garlic Clove","measure":"6 cloves"},{"name":"Water Chestnut","measure":"220g"},{"name":"Peanuts","measure":"100g"}],"steps":["Combine the sake or rice wine, soy sauce, sesame oil and cornflour dissolved in water. Divide mixture in half.","In a glass dish or bowl, combine half of the sake mixture with the chicken pieces and toss to coat. Cover dish and place in refrigerator for about 30 minutes.","In a medium frying pan, combine remaining sake mixture, chillies, vinegar and sugar. Mix together and add spring onion, garlic, water chestnuts and peanuts. Heat sauce slowly over medium heat until aromatic.","Meanwhile, remove chicken from marinade and sauté in a large frying pan until juices run clear. When sauce is aromatic, add sautéed chicken and let simmer together until sauce thickens."],"ingredient_names":["sake","soy sauce","sesame seed oil","corn flour","water","chicken","chilli powder","rice vinegar","brown sugar","spring onions","garlic clove","water chestnut","peanuts"],"allergens":["gluten","peanuts","sesame","soy"],"diet_flags":[]},{"source_id":"52946","title":"Kung Po Prawns","category":"Seafood","country":"China","tags":["BBQ"],"image_url":"https://www.themealdb.com/images/media/meals/1525873040.jpg","youtube_url":"https://www.youtube.com/watch?v=ysiuZm9FIxs","source_url":"https://www.bbcgoodfood.com/recipes/1415664/kung-po-prawns","ingredients":[{"name":"Prawns","measure":"400g"},{"name":"Soy Sauce","measure":"2 tbs"},{"name":"Tomato Puree","measure":"1 tsp"},{"name":"Corn Flour","measure":"1 tsp"},{"name":"Caster Sugar","measure":"1 tsp"},{"name":"Sunflower Oil","measure":"1 tsp"},{"name":"Peanuts","measure":"85g"},{"name":"Chilli","measure":"3 Large"},{"name":"Brown Sugar","measure":"1 tbs"},{"name":"Garlic Clove","measure":"6 cloves"},{"name":"Water Chestnut","measure":"450g"},{"name":"Ginger","measure":"to taste"}],"steps":["Mix the cornflour and 1 tbsp soy sauce, toss in the prawns and set aside for 10 mins. Stir the vinegar, remaining soy sauce, tomato purée, sugar and 2 tbsp water together to make a sauce.","When you’re ready to cook, heat a large frying pan or wok until very hot, then add 1 tbsp oil. Fry the prawns until they are golden in places and have opened out– then tip them out of the pan.","Heat the remaining oil and add the peanuts, chillies and water chestnuts. Stir-fry for 2 mins or until the peanuts start to colour, then add the ginger and garlic and fry for 1 more min. Tip in the prawns and sauce and simmer for 2 mins until thickened slightly. Serve with rice."],"ingredient_names":["prawns","soy sauce","tomato puree","corn flour","caster sugar","sunflower oil","peanuts","chilli","brown sugar","garlic clove","water chestnut","ginger"],"allergens":["gluten","peanuts","shellfish","soy"],"diet_flags":["pescatarian"]},{"source_id":"52947","title":"Ma Po Tofu","category":"Beef","country":"China","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/1525874812.jpg","youtube_url":"https://www.youtube.com/watch?v=IhwPQL9dFYc","source_url":"https://www.chinasichuanfood.com/mapo-tofu-recipe/","ingredients":[{"name":"Tofu","measure":"450g"},{"name":"Minced Beef","measure":"100g"},{"name":"Sesame Seed Oil","measure":"1/2 tbs"},{"name":"Doubanjiang","measure":"1 1/2 tsp"},{"name":"Fermented Black Beans","measure":"1/2 tsp"},{"name":"Pepper","measure":"1 tbs"},{"name":"Salt","measure":"1/2 tsp"},{"name":"Sichuan pepper","measure":"1/2 tsp"},{"name":"Soy Sauce","measure":"1 tbs"},{"name":"Water","measure":"400ml"},{"name":"Olive Oil","measure":"2 tbs"},{"name":"Scallions","measure":"2 chopped"},{"name":"Spring Onions","measure":"4"},{"name":"Garlic","measure":"2 cloves chopped"},{"name":"Ginger","measure":"4 sliced"},{"name":"Water","measure":"2 1/2 tbs"},{"name":"Cornstarch","measure":"1 tbs"}],"steps":["Add a small pinch of salt and sesame oil to minced beef. Mix well and set aside.","Mix 1 tablespoon of cornstarch with 2 and ½ tablespoons of water in a small bowl to make water starch.","Cut tofu into square cubes (around 2cms). Bring a large amount of water to a boil and then add a pinch of salt. Slide the tofu in and cook for 1 minute. Move out and drain.","Get a wok and heat up around 2 tablespoons of oil, fry the minced meat until crispy. Transfer out beef out and leave the oil in.","Fry doubanjiang for 1 minute over slow fire and then add garlic, scallion white, ginger and fermented black beans to cook for 30 seconds until aroma. Then mix pepper flakes in.","Add water to the seasonings and bring to boil over high fire. Gently slide the tofu cubes. Add light soy sauce and beef.Slow the heat after boiling and then simmer for 6-8 minutes. Then add chopped garlic greens.","Stir the water starch and then pour half of the mixture to the simmering pot. Wait for around 30 seconds and then pour the other half. You can slightly taste the tofu and add pinch of salt if not salty enough. By the way, if you feel it is too spicy, add some sugar can milder the taste. But be carefully as the broth is very hot at this point.","Transfer out when almost all the seasonings stick to tofu cubes. Sprinkle Szechuan peppercorn powder (to taste)and chopped garlic greens if using.","Serve immediately with steamed rice."],"ingredient_names":["tofu","minced beef","sesame seed oil","doubanjiang","fermented black beans","pepper","salt","sichuan pepper","soy sauce","water","olive oil","scallions","spring onions","garlic","ginger","water","cornstarch"],"allergens":["gluten","sesame","soy"],"diet_flags":[]},{"source_id":"52948","title":"Wontons","category":"Pork","country":"China","tags":["MainMeal"],"image_url":"https://www.themealdb.com/images/media/meals/1525876468.jpg","youtube_url":"https://www.youtube.com/watch?v=9h9No18ZyCI","source_url":"http://www.geniuskitchen.com/recipe/chinese-wontons-20235","ingredients":[{"name":"Pork","measure":"1lb"},{"name":"Garlic Clove","measure":"3 chopped"},{"name":"Ginger","measure":"1 tsp"},{"name":"Soy Sauce","measure":"1 tbs"},{"name":"Sesame Seed Oil","measure":"1 tsp"},{"name":"Carrots","measure":"3 finely chopped"},{"name":"Celery","measure":"3 finely chopped"},{"name":"Spring Onions","measure":"6 chopped"},{"name":"Wonton Skin","measure":"1 Packet"},{"name":"Oil","measure":"Fry"},{"name":"Water","measure":"Bottle"}],"steps":["Combine pork, garlic, ginger, soy sauce, sesame oil, and vegetables in a bowl.","Separate wonton skins.","Place a heaping teaspoon of filling in the center of the wonton.","Brush water on 2 borders of the skin, covering 1/4 inch from the edge.","Fold skin over to form a triangle, sealing edges.","Pinch the two long outside points together.","Heat oil to 450 degrees and fry 4 to 5 at a time until golden.","Drain and serve with sauce."],"ingredient_names":["pork","garlic clove","ginger","soy sauce","sesame seed oil","carrots","celery","spring onions","wonton skin","oil","water"],"allergens":["gluten","sesame","soy"],"diet_flags":[]},{"source_id":"52949","title":"Sweet and Sour Pork","category":"Pork","country":"China","tags":["Sweet"],"image_url":"https://www.themealdb.com/images/media/meals/1529442316.jpg","youtube_url":"https://www.youtube.com/watch?v=mdaBIhgEAMo","source_url":"https://www.chinahighlights.com/travelguide/chinese-food/cooking/sweet-sour-pork.htm","ingredients":[{"name":"Pork","measure":"200g"},{"name":"Egg","measure":"1"},{"name":"Water","measure":"Dash"},{"name":"Salt","measure":"1/2 tsp"},{"name":"Sugar","measure":"1 tsp"},{"name":"Soy Sauce","measure":"10g"},{"name":"Starch","measure":"10g"},{"name":"Tomato Puree","measure":"30g"},{"name":"Vinegar","measure":"10g"},{"name":"Coriander","measure":"Dash"}],"steps":["Preparation","Crack the egg into a bowl. Separate the egg white and yolk.","Sweet and Sour Pork","Slice the pork tenderloin into strips.","Prepare the marinade using a pinch of salt, one teaspoon of starch, two teaspoons of light soy sauce, and an egg white.","Marinade the pork strips for about 20 minutes.","Put the remaining starch in a bowl. Add some water and vinegar to make a starchy sauce.","Sweet and Sour Pork","Cooking Instructions","Pour the cooking oil into a wok and heat to 190°C (375°F). Add the marinated pork strips and fry them until they turn brown. Remove the cooked pork from the wok and place on a plate.","Leave some oil in the wok. Put the tomato sauce and white sugar into the wok, and heat until the oil and sauce are fully combined.","Add some water to the wok and thoroughly heat the sweet and sour sauce before adding the pork strips to it.","Pour in the starchy sauce. Stir-fry all the ingredients until the pork and sauce are thoroughly mixed together.","Serve on a plate and add some coriander for decoration."],"ingredient_names":["pork","egg","water","salt","sugar","soy sauce","starch","tomato puree","vinegar","coriander"],"allergens":["eggs","gluten","soy"],"diet_flags":[]},{"source_id":"52950","title":"Szechuan Beef","category":"Beef","country":"China","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/1529443236.jpg","youtube_url":"https://www.youtube.com/watch?v=SQGZqZYz7Ms","source_url":"https://sueandgambo.com/pages/szechuan-beef","ingredients":[{"name":"Beef","measure":"1/2 lb"},{"name":"Salt","measure":"1/2 tsp"},{"name":"Sesame Seed Oil","measure":"1 tsp"},{"name":"Pepper","measure":"1 pinch"},{"name":"Egg White","measure":"1"},{"name":"Starch","measure":"3 tbs"},{"name":"Oil","measure":"4 tbs"},{"name":"Ginger","measure":"1 tsp"},{"name":"Garlic","measure":"1 tsp"},{"name":"Onion","measure":"3/4 cup"},{"name":"Carrots","measure":"1/2 cup"},{"name":"Green Pepper","measure":"3/4 cup"},{"name":"Celery","measure":"1 cup"},{"name":"Mushrooms","measure":"1 cup"},{"name":"Cooking wine","measure":"1 tbs"},{"name":"Water","measure":"1 cup"},{"name":"Oyster Sauce","measure":"1 tbs"},{"name":"Hotsauce","measure":"1/2 tsp"},{"name":"Sugar","measure":"1 tsp"},{"name":"Soy Sauce","measure":"1 tbs"}],"steps":["MARINATING THE BEEF","In a bowl, add the beef, salt, sesame seed oil, white pepper, egg white, 2 Tablespoon of corn starch and 1 Tablespoon of oil.","STIR FRY","First Cook the beef by adding 2 Tablespoon of oil until the beef is golden brown.","Set the beef aside","In a wok add 1 Tablespoon of oil, minced ginger, minced garlic and stir-fry for few seconds.","Next add all of the vegetables and then add sherry cooking wine and 1 cup of water.","To make the sauce add oyster sauce, hot pepper sauce, and sugar.","add the cooked beef and 1 spoon of soy sauce","To thicken the sauce, whisk together 1 Tablespoon of cornstarch and 2 Tablespoon of water in a bowl and slowly add to your stir-fry until it's the right thickness."],"ingredient_names":["beef","salt","sesame seed oil","pepper","egg white","starch","oil","ginger","garlic","onion","carrots","green pepper","celery","mushrooms","cooking wine","water","oyster sauce","hotsauce","sugar","soy sauce"],"allergens":["eggs","gluten","sesame","shellfish","soy"],"diet_flags":[]},{"source_id":"52951","title":"General Tsos Chicken","category":"Chicken","country":"China","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/1529444113.jpg","youtube_url":"https://www.youtube.com/watch?v=wWGwz0iBmvU","source_url":"https://www.skinnytaste.com/general-tsos-chicken/","ingredients":[{"name":"Chicken Breast","measure":"1 1/2"},{"name":"Plain Flour","measure":"3/4 cup"},{"name":"Egg","measure":"1"},{"name":"Starch","measure":"2 tbs"},{"name":"Baking Powder","measure":"1 tbs"},{"name":"Salt","measure":"1 tsp"},{"name":"Onion Salt","measure":"1/2 tsp"},{"name":"Garlic Powder","measure":"1/4 tsp"},{"name":"Water","measure":"3/4 cup"},{"name":"Chicken Stock","measure":"1/2 cup"},{"name":"Duck Sauce","measure":"1/4 cup"},{"name":"Soy Sauce","measure":"3 tbs"},{"name":"Honey","measure":"2 tbs"},{"name":"Rice Vinegar","measure":"1 tbs"},{"name":"Sesame Seed Oil","measure":"2 tbs"},{"name":"Gochujang","measure":"1/2 tbs"},{"name":"Starch","measure":"2 tbs"},{"name":"Garlic","measure":"1 clove"},{"name":"Spring Onions","measure":"2 chopped"},{"name":"Ginger","measure":"1 tsp"}],"steps":["DIRECTIONS:","SAUCE","In a bowl, add 2 Cups of water, 2 Tablespoon soy sauce, 2 Tablespoon white vinegar, sherry cooking wine, 1/4 Teaspoon white pepper, minced ginger, minced garlic, hot pepper, ketchup, hoisin sauce, and sugar.","Mix together well and set aside.","MARINATING THE CHICKEN","In a bowl, add the chicken, 1 pinch of salt, 1 pinch of white pepper, 2 egg whites, and 3 Tablespoon of corn starch","DEEP FRY THE CHICKEN","Deep fry the chicken at 350 degrees for 3-4 minutes or until it is golden brown and loosen up the chicken so that they don't stick together.","Set the chicken aside.","STIR FRY","Add the sauce to the wok and then the broccoli and wait until it is boiling.","To thicken the sauce, whisk together 2 Tablespoon of cornstarch and 4 Tablespoon of water in a bowl and slowly add to your stir-fry until it's the right thickness.","Next add in the chicken and stir-fry for a minute and serve on a plate"],"ingredient_names":["chicken breast","plain flour","egg","starch","baking powder","salt","onion salt","garlic powder","water","chicken stock","duck sauce","soy sauce","honey","rice vinegar","sesame seed oil","gochujang","starch","garlic","spring onions","ginger"],"allergens":["eggs","gluten","sesame","soy"],"diet_flags":[]},{"source_id":"52952","title":"Beef Lo Mein","category":"Beef","country":"China","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/1529444830.jpg","youtube_url":"https://www.youtube.com/watch?v=ZT9LSsNXXe0","source_url":"https://sueandgambo.com/pages/beef-lo-mein","ingredients":[{"name":"Beef","measure":"1/2 lb"},{"name":"Salt","measure":"pinch"},{"name":"Pepper","measure":"pinch"},{"name":"Sesame Seed Oil","measure":"2 tsp"},{"name":"Egg","measure":"1/2"},{"name":"Starch","measure":"3 tbs"},{"name":"Oil","measure":"5 tbs"},{"name":"Noodles","measure":"1/4 lb"},{"name":"Onion","measure":"1/2 cup"},{"name":"Minced Garlic","measure":"1 tsp"},{"name":"Ginger","measure":"1 tsp"},{"name":"Bean Sprouts","measure":"1 cup"},{"name":"Mushrooms","measure":"1 cup"},{"name":"Water","measure":"1 cup"},{"name":"Oyster Sauce","measure":"1 tbs"},{"name":"Sugar","measure":"1 tsp"},{"name":"Soy Sauce","measure":"1 tsp"}],"steps":["MARINATING THE BEEF","In a bowl, add the beef, salt, 1 pinch white pepper, 1 Teaspoon sesame seed oil, 1/2 egg, corn starch,1 Tablespoon of oil and mix together.","BOILING THE THE NOODLES","In a 6 qt pot add your noodles to boiling water until the noodles are submerged and boil on high heat for 10 seconds. After your noodles is done boiling strain and cool with cold water.","STIR FRY","Add 2 Tablespoons of oil, beef and cook on high heat untill beef is medium cooked.","Set the cooked beef aside","In a wok add 2 Tablespoon of oil, onions, minced garlic, minced ginger, bean sprouts, mushrooms, peapods and 1.5 cups of water or until the vegetables are submerged in water.","Add the noodles to wok","To make the sauce, add oyster sauce, 1 pinch white pepper, 1 teaspoon sesame seed oil, sugar, and 1 Teaspoon of soy sauce.","Next add the beef to wok and stir-fry"],"ingredient_names":["beef","salt","pepper","sesame seed oil","egg","starch","oil","noodles","onion","minced garlic","ginger","bean sprouts","mushrooms","water","oyster sauce","sugar","soy sauce"],"allergens":["eggs","gluten","sesame","shellfish","soy"],"diet_flags":[]},{"source_id":"52953","title":"Shrimp Chow Fun","category":"Seafood","country":"China","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/1529445434.jpg","youtube_url":"https://www.youtube.com/watch?v=wzaTcpoFEaY","source_url":"https://sueandgambo.com/pages/shrimp-chow-fun","ingredients":[{"name":"Rice Stick Noodles","measure":"1/2 bag"},{"name":"Prawns","measure":"8 oz"},{"name":"Egg","measure":"1/2"},{"name":"Pepper","measure":"pinch"},{"name":"Sesame Seed Oil","measure":"2 tsp"},{"name":"Cornstarch","measure":"2 tbs"},{"name":"Oil","measure":"4 tbs"},{"name":"Minced Garlic","measure":"1 tsp"},{"name":"Ginger","measure":"1 tsp"},{"name":"Onion","measure":"1/2 cup"},{"name":"Bean Sprouts","measure":"1 cup"},{"name":"Spring Onions","measure":"1/2 cup"},{"name":"Cooking wine","measure":"1 tbs"},{"name":"Oyster Sauce","measure":"1 tbs"},{"name":"Sugar","measure":"1/2 tbs"},{"name":"Vinegar","measure":"1/2 tbs"},{"name":"Soy Sauce","measure":"1 tbs"}],"steps":["SOAK THE RICE NOODLES","Soak the rice noodles overnight untill they are soft","BOIL THE RICE NOODLES","Boil the noodles for 10-15 minutes and then rinse with cold water to stop the cooking process of the noodles.","MARINATING THE SHRIMP","In a bowl add the shrimp, egg, 1 pinch of white pepper, 1 Teaspoon of sesame seed oil, 1 Tablespoon corn starch and 1 tablespoon of oil","Mix together well","STIR FRY","In a wok add 2 Tablespoons of oil, shrimp and stir fry them until it is golden brown","Set the shrimp aside","Add 1 Tablespoon of oil to the work and then add minced garlic, ginger and all of the vegetables.","Add the noodles to the wok","Next add sherry cooking wine, oyster sauce, sugar, vinegar, sesame seed oil, 1 pinch white pepper, and soy sauce","Add back in the shrimp","To thicken the sauce, whisk together 1 Tablespoon of corn starch and 2 Tablespoon of water in a bowl and slowly add to your stir-fry until it's the right thickness."],"ingredient_names":["rice stick noodles","prawns","egg","pepper","sesame seed oil","cornstarch","oil","minced garlic","ginger","onion","bean sprouts","spring onions","cooking wine","oyster sauce","sugar","vinegar","soy sauce"],"allergens":["eggs","gluten","sesame","shellfish","soy"],"diet_flags":["pescatarian"]},{"source_id":"52954","title":"Hot and Sour Soup","category":"Pork","country":"China","tags":["Soup"],"image_url":"https://www.themealdb.com/images/media/meals/1529445893.jpg","youtube_url":"https://www.youtube.com/watch?v=KgV9Zq3aSTo","source_url":"https://sueandgambo.com/pages/chinese-hot-and-sour-soup","ingredients":[{"name":"Mushrooms","measure":"1/3 cup"},{"name":"Wood Ear Mushrooms","measure":"1/3 cup"},{"name":"Tofu","measure":"2/3 Cup"},{"name":"Pork","measure":"1/2 cup"},{"name":"Chicken Stock","measure":"2-1/2 cups"},{"name":"Salt","measure":"1/2 tsp"},{"name":"Sugar","measure":"1/4 tsp"},{"name":"Sesame Seed Oil","measure":"1 tsp"},{"name":"Pepper","measure":"1/4 tsp"},{"name":"Hotsauce","measure":"1/2 tsp"},{"name":"Vinegar","measure":"1-½ cups"},{"name":"Soy Sauce","measure":"1 tsp"},{"name":"Cornstarch","measure":"1 tbs"},{"name":"Water","measure":"2 tbs"},{"name":"Spring Onions","measure":"1/4 cup"}],"steps":["MAKING THE SOUP","In a wok add chicken broth and wait for it to boil.","Next add salt, sugar, sesame seed oil, white pepper, hot pepper sauce, vinegar and soy sauce and stir for few seconds.","Add Tofu, mushrooms, black wood ear mushrooms to the wok.","To thicken the sauce, whisk together 1 Tablespoon of cornstarch and 2 Tablespoon of water in a bowl and slowly add to your soup until it's the right thickness.","Next add 1 egg slightly beaten with a knife or fork and add it to the soup and stir for 8 seconds","Serve the soup in a bowl and add the bbq pork and sliced green onions on top."],"ingredient_names":["mushrooms","wood ear mushrooms","tofu","pork","chicken stock","salt","sugar","sesame seed oil","pepper","hotsauce","vinegar","soy sauce","cornstarch","water","spring onions"],"allergens":["gluten","sesame","soy"],"diet_flags":[]},{"source_id":"52955","title":"Egg Drop Soup","category":"Vegetarian","country":"China","tags":["Soup","Baking","Calorific"],"image_url":"https://www.themealdb.com/images/media/meals/1529446137.jpg","youtube_url":"https://www.youtube.com/watch?v=9XpzHm9QpZg","source_url":"https://sueandgambo.com/pages/egg-drop-soup","ingredients":[{"name":"Chicken Stock","measure":"3 cups"},{"name":"Salt","measure":"1/4 tsp"},{"name":"Sugar","measure":"1/4 tsp"},{"name":"Pepper","measure":"pinch"},{"name":"Sesame Seed Oil","measure":"1 tsp"},{"name":"Peas","measure":"1/3 cup"},{"name":"Mushrooms","measure":"1/3 cup"},{"name":"Cornstarch","measure":"1 tbs"},{"name":"Water","measure":"2 tbs"},{"name":"Spring Onions","measure":"1/4 cup"}],"steps":["In a wok add chicken broth and wait for it to boil.","Next add salt, sugar, white pepper, sesame seed oil.","When the chicken broth is boiling add the vegetables to the wok.","To thicken the sauce, whisk together 1 Tablespoon of cornstarch and 2 Tablespoon of water in a bowl and slowly add to your soup until it's the right thickness.","Next add 1 egg slightly beaten with a knife or fork and add it to the soup slowly and stir for 8 seconds","Serve the soup in a bowl and add the green onions on top."],"ingredient_names":["chicken stock","salt","sugar","pepper","sesame seed oil","peas","mushrooms","cornstarch","water","spring onions"],"allergens":["sesame"],"diet_flags":[]},{"source_id":"52956","title":"Chicken Congee","category":"Chicken","country":"China","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/1529446352.jpg","youtube_url":"https://www.youtube.com/watch?v=kqEfk801E94","source_url":"https://sueandgambo.com/pages/chicken-congee","ingredients":[{"name":"Chicken","measure":"8 oz"},{"name":"Salt","measure":"pinch"},{"name":"Pepper","measure":"pinch"},{"name":"Ginger Cordial","measure":"1 tsp"},{"name":"Ginger","measure":"1 tsp"},{"name":"Spring Onions","measure":"1 tbs"},{"name":"Rice","measure":"1/2 cup"},{"name":"Water","measure":"8 cups"},{"name":"Coriander","measure":"2 oz"}],"steps":["MARINATING THE CHICKEN","In a bowl, add chicken, salt, white pepper, ginger juice and then mix it together well.","Set the chicken aside.","RINSE THE WHITE RICE","Rinse the rice in a metal bowl or pot a couple times and then drain the water.","BOILING THE WHITE RICE","Next add 8 cups of water and then set the stove on high heat until it is boiling. Once rice porridge starts to boil, set the stove on low heat and then stir it once every 8-10 minutes for around 20-25 minutes.","After 25 minutes, this is optional but you can add a little bit more water to make rice porridge to make it less thick or to your preference.","Next add the marinated chicken to the rice porridge and leave the stove on low heat for another 10 minutes.","After an additional 10 minutes add the green onions, sliced ginger, 1 pinch of salt, 1 pinch of white pepper and stir for 10 seconds.","Serve the rice porridge in a bowl","Optional: add Coriander on top of the rice porridge."],"ingredient_names":["chicken","salt","pepper","ginger cordial","ginger","spring onions","rice","water","coriander"],"allergens":[],"diet_flags":[]},{"source_id":"52959","title":"Baked salmon with fennel & tomatoes","category":"Seafood","country":"United Kingdom","tags":["Paleo","Keto","HighFat","Baking","LowCarbs"],"image_url":"https://www.themealdb.com/images/media/meals/1548772327.jpg","youtube_url":"https://www.youtube.com/watch?v=xvPR2Tfw5k0","source_url":"https://www.bbcgoodfood.com/recipes/7745/baked-salmon-with-fennel-and-tomatoes","ingredients":[{"name":"Fennel","measure":"2 medium"},{"name":"Parsley","measure":"2 tbs chopped"},{"name":"Lemon","measure":"Juice of 1"},{"name":"Cherry Tomatoes","measure":"175g"},{"name":"Olive Oil","measure":"1 tbs"},{"name":"Salmon","measure":"350g"},{"name":"Black Olives","measure":"to serve"}],"steps":["Heat oven to 180C/fan 160C/gas 4.","Trim the fronds from the fennel and set aside.","Cut the fennel bulbs in half, then cut each half into 3 wedges.","Cook in boiling salted water for 10 mins, then drain well.","Chop the fennel fronds roughly, then mix with the parsley and lemon zest.","Spread the drained fennel over a shallow ovenproof dish, then add the tomatoes.","Drizzle with olive oil, then bake for 10 mins.","Nestle the salmon among the veg, sprinkle with lemon juice, then bake 15 mins more until the fish is just cooked.","Scatter over the parsley and serve."],"ingredient_names":["fennel","parsley","lemon","cherry tomatoes","olive oil","salmon","black olives"],"allergens":["fish"],"diet_flags":["pescatarian"]},{"source_id":"52960","title":"Salmon Avocado Salad","category":"Seafood","country":"United Kingdom","tags":["Paleo","Keto","LowCarbs","Salad","Alcoholic","Halloween"],"image_url":"https://www.themealdb.com/images/media/meals/1549542994.jpg","youtube_url":"https://www.youtube.com/watch?v=FJiu2S0Xap0","source_url":"https://www.bbcgoodfood.com/recipes/4521/salmon-avocado-and-cucumber-salad","ingredients":[{"name":"Salmon","measure":"400g"},{"name":"Avocado","measure":"3"},{"name":"Cucumber","measure":"1"},{"name":"Spinach","measure":"400g"},{"name":"Mint","measure":"4 tbs"},{"name":"Lime","measure":"zest and juice of 1"},{"name":"Honey","measure":"2 tsp"},{"name":"Olive Oil","measure":"3 tbs"}],"steps":["Season the salmon, then rub with oil.","Mix the dressing ingredients together.","Halve, stone, peel and slice the avocados.","Halve and quarter the cucumber lengthways, then cut into slices.","Divide salad, avocado and cucumber between four plates, then drizzle with half the dressing. Heat a non-stick pan.","Add the salmon and fry for 3-4 mins on each side until crisp but still moist inside.","Put a salmon fillet on top of each salad and drizzle over the remaining dressing. Serve warm."],"ingredient_names":["salmon","avocado","cucumber","spinach","mint","lime","honey","olive oil"],"allergens":["fish"],"diet_flags":["pescatarian"]},{"source_id":"52963","title":"Shakshuka","category":"Vegetarian","country":"Egypt","tags":["Egg","Brunch","Breakfast"],"image_url":"https://www.themealdb.com/images/media/meals/g373701551450225.jpg","youtube_url":"https://www.youtube.com/watch?v=C-3_jYrfdBU","source_url":"https://www.bbcgoodfood.com/recipes/7573/spicy-tomato-baked-eggs","ingredients":[{"name":"Olive Oil","measure":"1 tbs"},{"name":"Red Onions","measure":"2 chopped"},{"name":"Red Chilli","measure":"1 finely chopped"},{"name":"Garlic","measure":"1 clove"},{"name":"Coriander","measure":"Chopped"},{"name":"Cherry Tomatoes","measure":"800g"},{"name":"Caster Sugar","measure":"1 tbs"},{"name":"Eggs","measure":"4"},{"name":"Feta","measure":"Spinkling"}],"steps":["Heat the oil in a frying pan that has a lid, then soften the onions, chilli, garlic and coriander stalks for 5 mins until soft.","Stir in the tomatoes and sugar, then bubble for 8-10 mins until thick.","Can be frozen for 1 month.","Using the back of a large spoon, make 4 dips in the sauce, then crack an egg into each one.","Put a lid on the pan, then cook over a low heat for 6-8 mins, until the eggs are done to your liking.","Scatter with the coriander leaves and serve with crusty bread."],"ingredient_names":["olive oil","red onions","red chilli","garlic","coriander","cherry tomatoes","caster sugar","eggs","feta"],"allergens":["dairy","eggs"],"diet_flags":["pescatarian","vegetarian"]},{"source_id":"52968","title":"Mbuzi Choma (Roasted Goat)","category":"Goat","country":"Kenya","tags":["BBQ","Meat"],"image_url":"https://www.themealdb.com/images/media/meals/cuio7s1555492979.jpg","youtube_url":null,"source_url":null,"ingredients":[{"name":"Goat Meat","measure":"1 kg"},{"name":"Corn Flour","measure":"1 kg"},{"name":"Tomatoes","measure":"2"},{"name":"Salt","measure":"Pinch"},{"name":"Onion","measure":"1"},{"name":"Green Chilli","measure":"1"},{"name":"Coriander Leaves","measure":"1  bunch"}],"steps":["Steps for the Meat:","Roast meat over medium heat for 50 minutes and salt it as you turn it.","Steps for Ugali:","Bring the water and salt to a boil in a heavy-bottomed saucepan. Stir in the cornmeal slowly, letting it fall through the fingers of your hand.","Reduce heat to medium-low and continue stirring regularly, smashing any lumps with a spoon, until the mush pulls away from the sides of the pot and becomes very thick, about 10 minutes.","Remove from heat and allow to cool.","Place the ugali into a large serving bowl. Wet your hands with water, form a ball and serve.","Steps for Kachumbari: Mix the tomatoes, onions, chili and coriander leaves in a bowl.","Serve and enjoy!"],"ingredient_names":["goat meat","corn flour","tomatoes","salt","onion","green chilli","coriander leaves"],"allergens":[],"diet_flags":[]},{"source_id":"52971","title":"Kafteji","category":"Vegetarian","country":"Tunisia","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/1bsv1q1560459826.jpg","youtube_url":"https://www.youtube.com/watch?v=-TFf-Zu-xQU","source_url":"http://allrecipes.co.uk/recipe/12294/kafteji--tunisian-fried-vegetables-.aspx","ingredients":[{"name":"Potatoes","measure":"5 Large"},{"name":"Olive Oil","measure":"2 tbs"},{"name":"Green Pepper","measure":"1"},{"name":"Onions","measure":"5"},{"name":"Ras el hanout","measure":"1 tbs"},{"name":"Pumpkin","measure":"500g"},{"name":"Eggs","measure":"24 Skinned"},{"name":"Salt","measure":"Pinch"},{"name":"Pepper","measure":"Pinch"}],"steps":["Peel potatoes and cut into 5cm cubes.","Pour 1-2 cm of olive oil into a large pan and heat up very hot. Fry potatoes until golden brown for 20 minutes, turning from time to time. Place on kitchen paper to drain.","Cut the peppers in half and remove seeds. Rub a little olive oil on them and place the cut side down on a baking tray. Place them under the grill. Grill until the skin is dark and bubbly. While the peppers are still hot, put them into a plastic sandwich bag and seal it. Take them out after 15 minutes and remove skins.","In the meantime, heat more olive oil another pan. Peel the onions and cut into thin rings. Fry for 15 minutes until golden brown, turning them often. Add the Ras el hanout at the end.","Cut the pumpkin into 5cm cubes and fry in the same pan you used for the potatoes for 10-15 minutes until it is soft and slightly browned. Place on kitchen paper.","Pour the remaining olive oil out of the pan and put all the cooked vegetables into the pan and mix. Whisk eggs and pour them over the vegetables. Put the lid on the pan so that the eggs cook. Put the contents of the pan onto a large chopping board, add salt and pepper and chopped and mix everything with a big knife."],"ingredient_names":["potatoes","olive oil","green pepper","onions","ras el hanout","pumpkin","eggs","salt","pepper"],"allergens":["eggs"],"diet_flags":["pescatarian","vegetarian"]},{"source_id":"52972","title":"Tunisian Lamb Soup","category":"Lamb","country":"Tunisia","tags":["Soup"],"image_url":"https://www.themealdb.com/images/media/meals/t8mn9g1560460231.jpg","youtube_url":"https://www.youtube.com/watch?v=w1qgTQmLRe4","source_url":"http://allrecipes.co.uk/recipe/16694/tunisian-lamb-soup.aspx","ingredients":[{"name":"Lamb Mince","measure":"500g"},{"name":"Garlic","measure":"2 cloves minced"},{"name":"Onion","measure":"1"},{"name":"Spinach","measure":"300g"},{"name":"Tomato Puree","measure":"3 tbs"},{"name":"Cumin","measure":"1 tbs"},{"name":"Chicken Stock","measure":"1 Litre"},{"name":"Harissa Spice","measure":"3 tsp"},{"name":"Chickpeas","measure":"400g"},{"name":"Lemon Juice","measure":"1/2"},{"name":"Macaroni","measure":"150g"},{"name":"Salt","measure":"Pinch"},{"name":"Pepper","measure":"Pinch"}],"steps":["Add the lamb to a casserole and cook over high heat. When browned, remove from the heat and set aside.","Keep a tablespoon of fat in the casserole and discard the rest. Reduce to medium heat then add the garlic, onion and spinach and cook until the onion is translucent and the spinach wilted or about 5 minutes.","Return the lamb to the casserole with the onion-spinach mixture, add the tomato puree, cumin, harissa, chicken, chickpeas, lemon juice, salt and pepper in the pan. Simmer over low heat for about 20 minutes.","Add the pasta and cook for 15 minutes or until pasta is cooked."],"ingredient_names":["lamb mince","garlic","onion","spinach","tomato puree","cumin","chicken stock","harissa spice","chickpeas","lemon juice","macaroni","salt","pepper"],"allergens":["gluten"],"diet_flags":[]},{"source_id":"52973","title":"Leblebi Soup","category":"Vegetarian","country":"Tunisia","tags":["Soup"],"image_url":"https://www.themealdb.com/images/media/meals/x2fw9e1560460636.jpg","youtube_url":"https://www.youtube.com/watch?v=BgRifcCwinY","source_url":"http://allrecipes.co.uk/recipe/43419/leblebi--tunisian-chickpea-soup-.aspx","ingredients":[{"name":"Olive Oil","measure":"2 tbs"},{"name":"Onion","measure":"1 medium finely diced"},{"name":"Chickpeas","measure":"250g"},{"name":"Vegetable Stock","measure":"1.5L"},{"name":"Cumin","measure":"1 tsp"},{"name":"Garlic","measure":"5 cloves"},{"name":"Salt","measure":"1/2 tsp"},{"name":"Harissa Spice","measure":"1 tsp"},{"name":"Pepper","measure":"Pinch"},{"name":"Lime","measure":"1/2"}],"steps":["Heat the oil in a large pot. Add the onion and cook until translucent.","Drain the soaked chickpeas and add them to the pot together with the vegetable stock. Bring to the boil, then reduce the heat and cover. Simmer for 30 minutes.","In the meantime toast the cumin in a small ungreased frying pan, then grind them in a mortar. Add the garlic and salt and pound to a fine paste.","Add the paste and the harissa to the soup and simmer until the chickpeas are tender, about 30 minutes.","Season to taste with salt, pepper and lemon juice and serve hot."],"ingredient_names":["olive oil","onion","chickpeas","vegetable stock","cumin","garlic","salt","harissa spice","pepper","lime"],"allergens":[],"diet_flags":["pescatarian","vegan","vegetarian"]},{"source_id":"52974","title":"Keleya Zaara","category":"Lamb","country":"Tunisia","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/8x09hy1560460923.jpg","youtube_url":"https://www.youtube.com/watch?v=u_OSIChzuL0","source_url":"http://allrecipes.co.uk/recipe/43723/keleya-zaara-tunisian-lamb-with-saffron.aspx","ingredients":[{"name":"Olive Oil","measure":"4 tbs"},{"name":"Lamb","measure":"750g"},{"name":"Saffron","measure":"1 1/2 tsp"},{"name":"Onion","measure":"1 Large Chopped"},{"name":"Water","measure":"25 ml"},{"name":"Parsley","measure":"30g"},{"name":"Butter","measure":"1 tbs"},{"name":"Lemon","measure":"1"}],"steps":["Heat the vegetable oil in a large frying pan over medium-high heat.","Add the lamb and cook until browned on all sides, about 5 minutes.","Season with saffron, salt and pepper to taste; stir in all but 4 tablespoons of the onion, and pour in the water.","Bring to the boil, then cover, reduce heat to medium-low, and simmer until the lamb is tender, about 15 minutes.","Uncover the pan, stir in the butter and allow the sauce reduce 5 to 10 minutes to desired consistency.","Season to taste with salt and pepper, then pour into a serving dish.","Sprinkle with the remaining chopped onions and parsley.","Garnish with lemon wedges to serve."],"ingredient_names":["olive oil","lamb","saffron","onion","water","parsley","butter","lemon"],"allergens":["dairy"],"diet_flags":[]},{"source_id":"52975","title":"Tuna and Egg Briks","category":"Seafood","country":"Tunisia","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/2dsltq1560461468.jpg","youtube_url":"https://www.youtube.com/watch?v=C5n1fN8TGHs","source_url":"http://allrecipes.co.uk/recipe/3096/tunisian-tuna-and-egg-briks.aspx","ingredients":[{"name":"Olive Oil","measure":"2 tbs"},{"name":"Spring Onions","measure":"8"},{"name":"Spinach","measure":"200g"},{"name":"Filo Pastry","measure":"4"},{"name":"Tuna","measure":"1 can"},{"name":"Eggs","measure":"2"},{"name":"Hotsauce","measure":"Dash"},{"name":"Tomatoes","measure":"4 Chopped"},{"name":"Cucumber","measure":"1/4"},{"name":"Lemon Juice","measure":"1 tbs"},{"name":"Apricot Jam","measure":"4 tbs"}],"steps":["Heat 2 tsp of the oil in a large saucepan and cook the spring onions over a low heat for 3 minutes or until beginning to soften. Add the spinach, cover with a tight-fitting lid and cook for a further 2–3 minutes or until tender and wilted, stirring once or twice. Tip the mixture into a sieve or colander and leave to drain and cool.","Using a saucer as a guide, cut out 24 rounds about 12.5 cm (5 in) in diameter from the filo pastry, cutting 6 rounds from each sheet. Stack the filo rounds in a pile, then cover with cling film to prevent them from drying out.","When the spinach mixture is cool, squeeze out as much excess liquid as possible, then transfer to a bowl. Add the tuna, eggs, hot pepper sauce, and salt and pepper to taste. Mix well.","Preheat the oven to 200°C (400°F, gas mark 6). Take one filo round and very lightly brush with some of the remaining oil. Top with a second round and brush with a little oil, then place a third round on top and brush with oil.","Place a heaped tbsp of the filling in the middle of the round, then fold the pastry over to make a half-moon shape. Fold in the edges, twisting them to seal, and place on a non-stick baking sheet. Repeat with the remaining pastry and filling to make 8 briks in all.","Lightly brush the briks with the remaining oil. Bake for 12–15 minutes or until the pastry is crisp and golden brown.","Meanwhile, combine the tomatoes and cucumber in a bowl and sprinkle with the lemon juice and seasoning to taste. Serve the briks hot with this salad and the chutney."],"ingredient_names":["olive oil","spring onions","spinach","filo pastry","tuna","eggs","hotsauce","tomatoes","cucumber","lemon juice","apricot jam"],"allergens":["eggs","fish","gluten"],"diet_flags":["pescatarian"]},{"source_id":"52979","title":"Bitterballen (Dutch meatballs)","category":"Beef","country":"Netherlands","tags":["DinnerParty","HangoverFood","Alcoholic"],"image_url":"https://www.themealdb.com/images/media/meals/lhqev81565090111.jpg","youtube_url":"https://www.youtube.com/watch?v=q8AKfYUtDuM","source_url":"https://www.holland.com/global/tourism/information/traditional-dutch-food/bitterballen.htm","ingredients":[{"name":"Butter","measure":"100g"},{"name":"Flour","measure":"150g"},{"name":"Beef Stock","measure":"700ml"},{"name":"Onion","measure":"30g"},{"name":"Parsley","measure":"1 tbs"},{"name":"Beef","measure":"400g"},{"name":"Salt","measure":"Pinch"},{"name":"Pepper","measure":"Pinch"},{"name":"Nutmeg","measure":"Pinch"},{"name":"Flour","measure":"50g"},{"name":"Eggs","measure":"2 Beaten"},{"name":"Breadcrumbs","measure":"50g"}],"steps":["Melt the butter in a skillet or pan. When melted, add the flour little by little and stir into a thick paste. Slowly stir in the stock, making sure the roux absorbs the liquid. Simmer for a couple of minutes on a low heat while you stir in the onion, parsley and the shredded meat. The mixture should thicken and turn into a heavy, thick sauce.","Pour the mixture into a shallow container, cover and refrigerate for several hours, or until the sauce has solidified.","Take a heaping tablespoon of the cold, thick sauce and quickly roll it into a small ball. Roll lightly through the flour, then the egg and finally the breadcrumbs. Make sure that the egg covers the whole surface of the bitterbal. When done, refrigerate the snacks while the oil in your fryer heats up to 190C (375F). Fry four bitterballen at a time, until golden.","Serve on a plate with a nice grainy or spicy mustard."],"ingredient_names":["butter","flour","beef stock","onion","parsley","beef","salt","pepper","nutmeg","flour","eggs","breadcrumbs"],"allergens":["dairy","eggs","gluten"],"diet_flags":[]},{"source_id":"52980","title":"Stamppot","category":"Pork","country":"Netherlands","tags":["Savory","Breakfast"],"image_url":"https://www.themealdb.com/images/media/meals/hyarod1565090529.jpg","youtube_url":"https://www.youtube.com/watch?v=hTrSXryX31A","source_url":"https://www.thespruceeats.com/stamppot-with-curly-kale-and-rookworst-1128837","ingredients":[{"name":"Potatoes","measure":"1.5kg"},{"name":"Bay Leaf","measure":"2 leaves"},{"name":"Shallots","measure":"2"},{"name":"Butter","measure":"3 tbs"},{"name":"Kale","measure":"750g"},{"name":"Sausages","measure":"2"},{"name":"Milk","measure":"500ml"},{"name":"Nutmeg","measure":"Grated"},{"name":"Salt","measure":"Pinch"},{"name":"Pepper","measure":"Pinch"}],"steps":["Wash and peel the potatoes and cut into similarly sized pieces for even cooking.","In a large soup pot, boil the potatoes and the bay leaves in salted water for 20 minutes. Discard the bay leaves.","If you're not using a bag of ready-cut curly kale, wash the bunches thoroughly under cool running water to get rid of all soil—you wouldn't want that gritty texture in your finished dish. Trim any coarse stems and discard any brown leaves. With a sharp knife, cut the curly kale into thin strips.","Peel and chop the shallots.","In a frying pan or skillet, melt 1 tbsp. of butter and saute the shallots for a few minutes before adding the curly kale and 2 tbsp. of water. Season and cook for about 10 minutes, or until tender.","Warm the milk on the stove or in the microwave.","Drain, shake and dry the potatoes with kitchen towels before mashing with a potato masher or ricer. Working quickly, add the warm milk and the remaining butter. Season to taste with nutmeg, salt, and pepper.","Mix the cooked curly kale through the cooked mashed potato mixture.","Top with slices of the smoked sausage and serve hot with your favorite mustard or gravy.","Serve and enjoy!"],"ingredient_names":["potatoes","bay leaf","shallots","butter","kale","sausages","milk","nutmeg","salt","pepper"],"allergens":["dairy"],"diet_flags":[]},{"source_id":"52982","title":"Spaghetti alla Carbonara","category":"Pasta","country":"Italy","tags":["Pasta","BBQ","Breakfast"],"image_url":"https://www.themealdb.com/images/media/meals/llcbn01574260722.jpg","youtube_url":"https://www.youtube.com/watch?v=_T6jkRvhlkk","source_url":"https://www.bbcgoodfood.com/recipes/ultimate-spaghetti-carbonara-recipe","ingredients":[{"name":"Spaghetti","measure":"320g"},{"name":"Egg Yolks","measure":"6"},{"name":"Salt","measure":"As required"},{"name":"Bacon","measure":"150g"},{"name":"Pecorino","measure":"50g"},{"name":"Black Pepper","measure":"As required"}],"steps":["Put a large saucepan of water on to boil.","Finely chop the 100g pancetta, having first removed any rind. Finely grate 50g pecorino cheese and 50g parmesan and mix them together.","Beat the 3 large eggs in a medium bowl and season with a little freshly grated black pepper. Set everything aside.","Add 1 tsp salt to the boiling water, add 350g spaghetti and when the water comes back to the boil, cook at a constant simmer, covered, for 10 minutes or until al dente (just cooked).","Squash 2 peeled plump garlic cloves with the blade of a knife, just to bruise it.","While the spaghetti is cooking, fry the pancetta with the garlic. Drop 50g unsalted butter into a large frying pan or wok and, as soon as the butter has melted, tip in the pancetta and garlic.","Leave to cook on a medium heat for about 5 minutes, stirring often, until the pancetta is golden and crisp. The garlic has now imparted its flavour, so take it out with a slotted spoon and discard.","Keep the heat under the pancetta on low. When the pasta is ready, lift it from the water with a pasta fork or tongs and put it in the frying pan with the pancetta. Don’t worry if a little water drops in the pan as well (you want this to happen) and don’t throw the pasta water away yet.","Mix most of the cheese in with the eggs, keeping a small handful back for sprinkling over later.","Take the pan of spaghetti and pancetta off the heat. Now quickly pour in the eggs and cheese. Using the tongs or a long fork, lift up the spaghetti so it mixes easily with the egg mixture, which thickens but doesn’t scramble, and everything is coated.","Add extra pasta cooking water to keep it saucy (several tablespoons should do it). You don’t want it wet, just moist. Season with a little salt, if needed.","Use a long-pronged fork to twist the pasta on to the serving plate or bowl. Serve immediately with a little sprinkling of the remaining cheese and a grating of black pepper. If the dish does get a little dry before serving, splash in some more hot pasta water and the glossy sauciness will be revived."],"ingredient_names":["spaghetti","egg yolks","salt","bacon","pecorino","black pepper"],"allergens":["dairy","eggs","gluten"],"diet_flags":[]},{"source_id":"52987","title":"Lasagna Sandwiches","category":"Pasta","country":"United States","tags":["Sandwich"],"image_url":"https://www.themealdb.com/images/media/meals/xr0n4r1576788363.jpg","youtube_url":null,"source_url":null,"ingredients":[{"name":"Sour Cream","measure":"1/4 cup"},{"name":"Chopped Onion","measure":"2 tbs"},{"name":"Dried Oregano","measure":"1/2 tbs"},{"name":"Salt","measure":"1/4 tsp"},{"name":"Bread","measure":"8 slices"},{"name":"Bacon","measure":"8 slices"},{"name":"Tomato","measure":"8 slices"},{"name":"Mozzarella","measure":"4 slices"},{"name":"Butter","measure":"2 1/2 Tbs"}],"steps":["In a small bowl, combine the first four ingredients; spread on four slices of bread. Layer with bacon, tomato and cheese; top with remaining bread.","In a large skillet or griddle, melt 2 tablespoons butter. Toast sandwiches until lightly browned on both sides and cheese is melted, adding butter if necessary.","Nutrition Facts","1 sandwich: 445 calories, 24g fat (12g saturated fat), 66mg cholesterol, 1094mg sodium, 35g carbohydrate (3g sugars, 2g fiber), 21g protein."],"ingredient_names":["sour cream","chopped onion","dried oregano","salt","bread","bacon","tomato","mozzarella","butter"],"allergens":["dairy","gluten"],"diet_flags":[]},{"source_id":"52992","title":"Soy-Glazed Meatloaves with Wasabi Mashed Potatoes & Roasted Carrots","category":"Beef","country":"United States","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/o2wb6p1581005243.jpg","youtube_url":null,"source_url":null,"ingredients":[{"name":"Potatoes","measure":"5"},{"name":"Carrots","measure":"12 ounces"},{"name":"Scallions","measure":"1"},{"name":"Garlic","measure":"2 cloves"},{"name":"Bread","measure":"1 Slice"},{"name":"Garlic Powder","measure":"1"},{"name":"Soy Sauce","measure":"2"},{"name":"Ground Beef","measure":"1"},{"name":"Vegetable Oil","measure":"1 tsp"},{"name":"Sugar","measure":"2 tsp"},{"name":"Butter","measure":"2 tbsp"}],"steps":["Preheat oven to 425 degrees. Wash and dry all produce. Dice potatoes into 1/2-inch pieces. Trim, peel, and cut carrots on a diagonal into 1/2-inch-thick pieces. Trim and thinly slice scallions, separating whites from greens; finely chop whites. Peel and finely chop garlic.","In a medium bowl, soak bread with 2 TBSP water (4 TBSP for 4 servings); break up with your hands until pasty. Stir in beef, sriracha, scallion whites, half the garlic, salt (we used 3/4 tsp kosher salt; 11/2 tsp for 4), and pepper. Form into two 1-inch-tall loaves (four loaves for 4). Place on one side of a baking sheet. Toss carrots on empty side of same sheet with a drizzle of oil, salt, and pepper. (For 4, spread meatloaves out across whole sheet and add carrots to a second sheet.) Bake for 20 minutes (we'll glaze the meatloaves then).","Meanwhile, place potatoes in a medium pot with enough salted water to cover by 2 inches. Bring to a boil and cook until very","tender, 12-15 minutes. Reserve 1/2 cup potato cooking liquid, then drain. While potatoes cook, in a small bowl, combine soy sauce, garlic powder, 1/4 cup ketchup (1/2 cup for 4 servings), and 2 tsp sugar (4 tsp for 4).","Once meatloaves and carrots have baked 20 minutes, remove from oven. Spoon half the ketchup glaze over meatloaves (save","the rest for serving); return to oven until carrots are browned and tender, meatloaves are cooked through, and glaze is tacky, 4-5 minutes more.","Meanwhile, melt 2 TBSP butter (4 TBSP for 4 servings) in pot used for potatoes over medium heat. Add remaining garlic and cook","until fragrant, 30 seconds. Add potatoes and 1/4 tsp wasabi. Mash, adding splashes of reserved potato cooking liquid as necessary until smooth. Season with salt and pepper. (If you like things spicy, stir in more wasabi!)","Divide meatloaves, mashed potatoes, and roasted carrots between plates. Sprinkle with scallion greens and serve with remaining ketchup glaze on the side for dipping."],"ingredient_names":["potatoes","carrots","scallions","garlic","bread","garlic powder","soy sauce","ground beef","vegetable oil","sugar","butter"],"allergens":["dairy","gluten","soy"],"diet_flags":[]},{"source_id":"52993","title":"Honey Balsamic Chicken with Crispy Broccoli & Potatoes","category":"Chicken","country":"United States","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/kvbotn1581012881.jpg","youtube_url":null,"source_url":null,"ingredients":[{"name":"Potatoes","measure":"5"},{"name":"Broccoli","measure":"1"},{"name":"Garlic","measure":"2 cloves"},{"name":"Chicken Breast","measure":"2"},{"name":"Balsamic Vinegar","measure":""},{"name":"Honey","measure":""},{"name":"Chicken Stock","measure":""},{"name":"Butter","measure":"1 tbsp"},{"name":"Vegetable Oil","measure":"1 tbsp"},{"name":"Olive Oil","measure":"1 tbsp"}],"steps":["2 Servings","Preheat oven to 425 degrees. Wash and dry all produce. Cut potatoes into 1/2-inch-thick wedges. Toss on one side of a baking sheet with a drizzle of oil, salt, and pepper. (For 4 servings, spread potatoes out across entire sheet.) Roast on top rack for 5 minutes (we'll add the broccoli then).","Meanwhile, cut broccoli florets into bite-size pieces, if necessary. Peel and finely chop garlic. In a small microwave-safe bowl, combine 1 TBSP olive oil (2 TBSP for 4 servings) and half the garlic. Microwave until garlic sizzles, 30 seconds.","Once potatoes have roasted 5 minutes, remove sheet from oven and add broccoli to empty side; carefully toss with garlic oil, salt, and pepper. (For 4 servings, add broccoli to a second sheet.) Continue roasting until potatoes and broccoli are browned and crispy, 15-20 minutes more.","While veggies roast, pat chicken dry with paper towels; season all over with salt and pepper. Heat a drizzle of oil in a large pan over medium-high heat. Add chicken and cook until browned and cooked through, 5-6 minutes per side. (If chicken browns too quickly, reduce heat to medium.) Turn off heat; set chicken aside to rest. Wash out pan.","Heat pan used for chicken over medium-high heat. Add a drizzle of oil and remaining garlic; cook until fragrant, 30 seconds. Stir in vinegar, honey, stock concentrate, and 1/4 cup water (1/3 cup for 4 servings). Simmer until thick and glossy, 2-3 minutes. Remove from heat and stir in 1 TBSP butter (2 TBSP for 4). Season with salt and pepper.","Return chicken to pan and turn to coat in glaze. Divide chicken, broccoli, and potatoes between plates. Spoon any remaining glaze over chicken and serve."],"ingredient_names":["potatoes","broccoli","garlic","chicken breast","balsamic vinegar","honey","chicken stock","butter","vegetable oil","olive oil"],"allergens":["dairy"],"diet_flags":[]},{"source_id":"52994","title":"Skillet Apple Pork Chops with Roasted Sweet Potatoes & Zucchini","category":"Pork","country":"United States","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/h3ijwo1581013377.jpg","youtube_url":null,"source_url":null,"ingredients":[{"name":"Potatoes","measure":"2"},{"name":"Apples","measure":"1"},{"name":"Garlic","measure":"2 cloves"},{"name":"Lemon","measure":"1"},{"name":"Pork","measure":"2"},{"name":"Zucchini","measure":"1"},{"name":"Chicken Stock","measure":"1"},{"name":"Vegetable Oil","measure":"1 tbsp"},{"name":"Sugar","measure":"1 1/2 tsp"},{"name":"Butter","measure":"2 tbsp"}],"steps":["Serves 2","Adjust racks to top and middle positions and preheat oven to 450 degrees. Wash and dry all produce. Dice sweet potatoes into 1/2-inch pieces. Toss on a baking sheet with a drizzle of oil, salt, and pepper. Roast on top rack for 12 minutes (we'll roast the zucchini then).","Meanwhile, halve and core apple; thinly slice into half-moons. Peel and finely chop garlic. Quarter lemon. Trim and halve zucchini lengthwise; cut crosswise into 1/2-inch-thick half-moons. Toss on a second baking sheet with a drizzle of oil and a pinch of salt and pepper. Set aside.","Pat pork dry with paper towels and season all over with salt and pepper. Heat a drizzle of oil in a large pan over medium-high heat. Add pork and cook until browned and cooked through, 4-5 minutes per side. Turn off heat; transfer to a plate.","Once sweet potatoes have roasted 12 minutes, transfer baking sheet with zucchini to middle rack and continue roasting until both veggies are browned and softened, 12-15 minutes more.","Meanwhile, melt 1 TBSP butter (2 TBSP for 4 servings) in pan used for pork over medium-high heat. Add apple and season with salt and pepper. Cook, scraping up any browned bits from bottom of pan, until apple is slightly softened, 2-3 minutes. Add garlic; cook until fragrant, 30 seconds. Add 1/z cup water (3/4 cup for 4), stock concentrate, and 11/2 tsp sugar (3 tsp for 4). Cook, stirring, until sauce has thickened and apple is very tender, 3-5 minutes. Season with salt and pepper.","Remove pan with apple from heat; stir in 1 TBSP butter (2 TBSP for 4 servings) and a squeeze of lemon juice. Divide pork, zucchini, and sweet potatoes between plates. Top pork with glazed apple sauce. Top zucchini with a squeeze of lemon juice."],"ingredient_names":["potatoes","apples","garlic","lemon","pork","zucchini","chicken stock","vegetable oil","sugar","butter"],"allergens":["dairy"],"diet_flags":[]},{"source_id":"52995","title":"BBQ Pork Sloppy Joes","category":"Pork","country":"United States","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/atd5sh1583188467.jpg","youtube_url":null,"source_url":null,"ingredients":[{"name":"Potatoes","measure":"2"},{"name":"Red Onions","measure":"1"},{"name":"Garlic","measure":"2 cloves"},{"name":"Lime","measure":"1"},{"name":"Bread","measure":"2"},{"name":"Pork","measure":"1 lb"},{"name":"Barbeque Sauce","measure":""},{"name":"Hotsauce","measure":""},{"name":"Tomato Ketchup","measure":""},{"name":"Sugar","measure":""},{"name":"Vegetable Oil","measure":""},{"name":"Salt","measure":""},{"name":"Pepper","measure":""}],"steps":["Preheat oven to 450 degrees. Wash and dry all produce. Cut sweet potatoes into ½-inch-thick wedges. Toss on a baking sheet with a drizzle of oil, salt, and pepper. Roast until browned and tender, 20-25 minutes.","Meanwhile, halve and peel onion. Slice as thinly as possible until you have ¼ cup (½ cup for 4 servings); finely chop remaining onion. Peel and finely chop garlic. Halve lime; squeeze juice into a small bowl. Halve buns. Add 1 TBSP butter (2 TBSP for 4) to a separate small microwave-safe bowl; microwave until melted, 30 seconds. Brush onto cut sides of buns.","To bowl with lime juice, add sliced onion, ¼ tsp sugar (½ tsp for 4 servings), and a pinch of salt. Stir to combine; set aside to quick-pickle.","Heat a drizzle of oil in a large pan over medium-high heat. Add chopped onion and season with salt and pepper. Cook, stirring, until softened, 4-5 minutes. Add garlic and cook until fragrant, 30 seconds more. Add pork and season with salt and pepper. Cook, breaking up meat into pieces, until browned and cooked through, 4-6 minutes.","While pork cooks, in a third small bowl, combine BBQ sauce, pickling liquid from onion, 3 TBSP ketchup (6 TBSP for 4 servings), ½ tsp sugar (1 tsp for 4), and ¼ cup water (⅓ cup for 4). Once pork is cooked through, add BBQ sauce mixture to pan. Cook, stirring, until sauce is thickened, 2-3 minutes. Taste and season with salt and pepper.","Meanwhile, toast buns in oven or toaster oven until golden, 3-5 minutes. Divide toasted buns between plates and fill with as much BBQ pork as you’d like. Top with pickled onion and hot sauce. Serve with sweet potato wedges on the side."],"ingredient_names":["potatoes","red onions","garlic","lime","bread","pork","barbeque sauce","hotsauce","tomato ketchup","sugar","vegetable oil","salt","pepper"],"allergens":["gluten"],"diet_flags":[]},{"source_id":"52996","title":"French Onion Chicken with Roasted Carrots & Mashed Potatoes","category":"Chicken","country":"United States","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/b5ft861583188991.jpg","youtube_url":null,"source_url":null,"ingredients":[{"name":"Chicken Breasts","measure":"2"},{"name":"Carrots","measure":"12 ounces"},{"name":"Potatoes","measure":"5"},{"name":"Onion","measure":"1"},{"name":"Beef Stock","measure":"1"},{"name":"Mozzarella","measure":"1 1/2 cup"},{"name":"Sour Cream","measure":"2 tbsp"},{"name":"Butter","measure":""},{"name":"Sugar","measure":""},{"name":"Vegetable Oil","measure":""},{"name":"Salt","measure":""},{"name":"Pepper","measure":""}],"steps":["Preheat oven to 425 degrees. Wash and dry all produce. Trim, peel, and cut carrots on a diagonal into ¼-inch-thick pieces. Dice potatoes into ½-inch pieces. Halve, peel, and thinly slice onion.","Toss carrots on a baking sheet with a drizzle of oil, salt, and pepper. Roast until browned and tender, 15-20 minutes.","Meanwhile, place potatoes in a medium pot with enough salted water to cover by 2 inches. Bring to a boil and cook until tender, 12-15 minutes. Drain and return potatoes to pot; cover to keep warm.","While potatoes cook, heat a drizzle of oil in a large pan over medium-high heat. Add onion and cook, stirring occasionally, until lightly browned and softened, 8-10 minutes. Sprinkle with 1 tsp sugar (2 tsp for 4 servings). Stir in stock concentrate and 2 TBSP water (¼ cup for 4); season with salt and pepper. Cook until jammy, 2-3 minutes more. Turn off heat; transfer to a small bowl. Wash out pan.","Pat chicken dry with paper towels; season all over with salt and pepper. Heat a drizzle of oil in pan used for onion over medium-high heat. Add chicken and cook until browned and cooked through, 5-6 minutes per side. In the last 1-2 minutes of cooking, top with caramelized onion and cheese. Cover pan until cheese melts. (If your pan doesn’t have a lid, cover with a baking sheet!)","Heat pot with drained potatoes over low heat; mash with sour cream, 2 TBSP butter (4 TBSP for 4 servings), salt, pepper, and a splash of water (or milk, for extra richness) until smooth. Divide chicken, roasted carrots, and mashed potatoes between plates."],"ingredient_names":["chicken breasts","carrots","potatoes","onion","beef stock","mozzarella","sour cream","butter","sugar","vegetable oil","salt","pepper"],"allergens":["dairy"],"diet_flags":[]},{"source_id":"52997","title":"Beef Banh Mi Bowls with Sriracha Mayo, Carrot & Pickled Cucumber","category":"Beef","country":"Vietnam","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/z0ageb1583189517.jpg","youtube_url":null,"source_url":null,"ingredients":[{"name":"Rice","measure":"White"},{"name":"Onion","measure":"1"},{"name":"Lime","measure":"1"},{"name":"Garlic Clove","measure":"3"},{"name":"Cucumber","measure":"1"},{"name":"Carrots","measure":"3 oz"},{"name":"Ground Beef","measure":"1 lb"},{"name":"Soy Sauce","measure":"2 oz"}],"steps":["Add'l ingredients: mayonnaise, siracha","Place rice in a fine-mesh sieve and rinse until water runs clear. Add to a small pot with 1 cup water (2 cups for 4 servings) and a pinch of salt. Bring to a boil, then cover and reduce heat to low. Cook until rice is tender, 15 minutes. Keep covered off heat for at least 10 minutes or until ready to serve.","Meanwhile, wash and dry all produce. Peel and finely chop garlic. Zest and quarter lime (for 4 servings, zest 1 lime and quarter both). Trim and halve cucumber lengthwise; thinly slice crosswise into half-moons. Halve, peel, and medium dice onion. Trim, peel, and grate carrot.","In a medium bowl, combine cucumber, juice from half the lime, ¼ tsp sugar (½ tsp for 4 servings), and a pinch of salt. In a small bowl, combine mayonnaise, a pinch of garlic, a squeeze of lime juice, and as much sriracha as you’d like. Season with salt and pepper.","Heat a drizzle of oil in a large pan over medium-high heat. Add onion and cook, stirring, until softened, 4-5 minutes. Add beef, remaining garlic, and 2 tsp sugar (4 tsp for 4 servings). Cook, breaking up meat into pieces, until beef is browned and cooked through, 4-5 minutes. Stir in soy sauce. Turn off heat; taste and season with salt and pepper.","Fluff rice with a fork; stir in lime zest and 1 TBSP butter. Divide rice between bowls. Arrange beef, grated carrot, and pickled cucumber on top. Top with a squeeze of lime juice. Drizzle with sriracha mayo."],"ingredient_names":["rice","onion","lime","garlic clove","cucumber","carrots","ground beef","soy sauce"],"allergens":["gluten","soy"],"diet_flags":[]},{"source_id":"52998","title":"Corned Beef and Cabbage","category":"Beef","country":"Ireland","tags":["Cheap"],"image_url":"https://www.themealdb.com/images/media/meals/xb97a81583266727.jpg","youtube_url":null,"source_url":null,"ingredients":[{"name":"Beef Brisket","measure":"3 Lbs"},{"name":"Small Potatoes","measure":"10"},{"name":"Carrots","measure":"5"},{"name":"Cabbage","measure":"1 head"}],"steps":["Place corned beef in large pot or Dutch oven and cover with water. Add the spice packet that came with the corned beef. Cover pot and bring to a boil, then reduce to a simmer. Simmer approximately 50 minutes per pound or until tender.","Add whole potatoes and peeled and cut carrots, and cook until the vegetables are almost tender. Add cabbage and cook for 15 more minutes. Remove meat and let rest 15 minutes.","Place vegetables in a bowl and cover. Add as much broth (cooking liquid reserved in the Dutch oven or large pot) as you want. Slice meat across the grain."],"ingredient_names":["beef brisket","small potatoes","carrots","cabbage"],"allergens":[],"diet_flags":[]},{"source_id":"52999","title":"Crispy Sausages and Greens","category":"Pork","country":"Ireland","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/st1ifa1583267248.jpg","youtube_url":null,"source_url":"https://www.bonappetit.com/columns/cooking-without-recipes/article/kale-cabbage-sausage-weeknight-dinner","ingredients":[{"name":"Kale","measure":"1  bunch"},{"name":"Italian Fennel Sausages","measure":"8"},{"name":"Cabbage","measure":"1 Head chopped"},{"name":"Garlic Clove","measure":"8"},{"name":"Onion","measure":"Sliced"},{"name":"Shiitake Mushrooms","measure":"Sliced"},{"name":"Chicken Stock","measure":"1 cup"},{"name":"Salt","measure":""},{"name":"Pepper","measure":""}],"steps":["Preheat the oven to 350°.","Remove the stems from one bunch of Tuscan kale and tear the leaves into 1\" pieces (mustard greens, collards, spinach, and chard are great, too).","Coarsely chop half a head of green cabbage.","Combine the greens in a large baking dish and add 4 cloves of thinly sliced garlic.","Adding some sliced onions and shiitake mushrooms at this point is optional, but highly recommended (I'll sauté the onions and mushrooms in a cast iron baking dish right on the stove before adding to the greens).","Coat the greens with some olive oil and pour ½ cup chicken stock or broth over everything.","Cover the dish with foil and bake until the greens are wilted, about 15 minutes.","Remove foil and season with salt and pepper.","Continue to bake until cabbage is tender, about 20-25 minutes more.","Meanwhile, heat a little olive oil in a large skillet over medium-high.","Prick four sweet Italian sausages with a fork and cook until browned on all sides and cooked through, 10 to 12 minutes.","When the greens are done, slice the sausage and toss into the greens with a splash of your favorite vinegar (I like sherry or red wine)."],"ingredient_names":["kale","italian fennel sausages","cabbage","garlic clove","onion","shiitake mushrooms","chicken stock","salt","pepper"],"allergens":[],"diet_flags":[]},{"source_id":"53000","title":"Vegetable Shepherds Pie","category":"Beef","country":"Ireland","tags":["Baking"],"image_url":"https://www.themealdb.com/images/media/meals/w8umt11583268117.jpg","youtube_url":null,"source_url":null,"ingredients":[{"name":"Potatoes","measure":"3 Lbs"},{"name":"Small Potatoes","measure":"3 Lbs"},{"name":"Salted Butter","measure":"1/2 cup"},{"name":"Mushrooms","measure":"1 oz"},{"name":"Brown Lentils","measure":"3/4 cup"},{"name":"Garlic","measure":"6 cloves"},{"name":"Kosher Salt","measure":"1 tsp"},{"name":"Onion","measure":"3 cups"},{"name":"Tomato Puree","measure":"2 tbsp"},{"name":"Bay Leaves","measure":""},{"name":"Olive Oil","measure":""},{"name":"Dry White Wine","measure":"2 cups"},{"name":"Vegetable Stock","measure":"8 cups"},{"name":"Cornstarch","measure":"2 tbsp"},{"name":"Soy Sauce","measure":"2 tsp"},{"name":"Rosemary","measure":"2 sprigs"},{"name":"Parsley","measure":""},{"name":"Sage","measure":""},{"name":"Chives","measure":""}],"steps":["Add Ingredients:","12 cups chopped mixed vegetables","1   cup chopped fresh mushrooms","1   cup pearl onions","TOPPING:","Preheat oven to 450°. Bake potatoes on a foil-lined baking sheet until tender, about 45 minutes. Let cool slightly, then peel. Press potatoes through a ricer, food mill, or colander into a large bowl. Add butter; stir until well blended. Stir in milk. Season to taste with salt.","FILLING:","Soak dried porcini in 3 cups hot water; set aside. Combine lentils, 1 garlic clove, 1 tsp. salt, and 4 cups water in a medium saucepan. Bring to a boil; reduce heat and simmer, stirring occasionally, until lentils are tender but not mushy, 15–20 minutes. Drain lentils and discard garlic.","Heat 3 Tbsp. oil in a large heavy pot over medium heat. Add onions and cook, stirring occasionally, until soft, about 12 minutes. Add chopped garlic and cook for 1 minute. Stir in tomato paste. Cook, stirring constantly, until tomato paste is caramelized, 2–3 minutes.","Add bay leaves and wine; stir, scraping up any browned bits. Stir in porcini, slowly pouring porcini soaking liquid into pan but leaving any sediment behind. Bring to a simmer and cook until liquid is reduced by half, about 10 minutes. Stir in broth and cook, stirring occasionally, until reduced by half, about 45 minutes.","Strain mixture into a large saucepan and bring to a boil; discard solids in strainer. Stir cornstarch and 2 Tbsp. water in a small bowl to dissolve. Add cornstarch mixture; simmer until thickened, about 5 minutes. Whisk in miso. Season sauce with salt and pepper. Set aside.","Preheat oven to 450°. Toss vegetables and pearl onions with remaining 2 Tbsp. oil, 5 garlic cloves, and rosemary sprigs in a large bowl; season with salt and pepper. Divide between 2 rimmed baking sheets. Roast, stirring once, until tender, 20–25 minutes. Transfer garlic cloves to a small bowl; mash well with a fork and stir into sauce. Discard rosemary. DO AHEAD: Lentils, sauce, and vegetables can be made 1 day ahead. Cover separately; chill.","Arrange lentils in an even layer in a 3-qt. baking dish; set dish on a foil-lined rimmed baking sheet. Toss roasted vegetables with fresh mushrooms and chopped herbs; layer on top of lentils. Pour sauce over vegetables. Spoon potato mixture evenly over.","Bake until browned and bubbly, about 30 minutes. Let stand for 15 minutes before serving."],"ingredient_names":["potatoes","small potatoes","salted butter","mushrooms","brown lentils","garlic","kosher salt","onion","tomato puree","bay leaves","olive oil","dry white wine","vegetable stock","cornstarch","soy sauce","rosemary","parsley","sage","chives"],"allergens":["dairy","gluten","soy"],"diet_flags":[]},{"source_id":"53006","title":"Moussaka","category":"Beef","country":"Greece","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/ctg8jd1585563097.jpg","youtube_url":"https://www.youtube.com/watch?v=8U_29i9Qp5U","source_url":"https://www.bbcgoodfood.com/recipes/must-make-moussaka","ingredients":[{"name":"Beef","measure":"500g"},{"name":"Aubergine","measure":"1 large"},{"name":"Greek Yogurt","measure":"150g"},{"name":"Egg","measure":"1 beaten"},{"name":"Parmesan","measure":"3 tbs"},{"name":"Tomato","measure":"400g"},{"name":"Tomato Puree","measure":"4 tbs"},{"name":"Potatoes","measure":"350g"}],"steps":["Heat the grill to high.","Brown the beef in a deep ovenproof frying pan over a high heat for 5 mins.","Meanwhile, prick the aubergine with a fork, then microwave on High for 3-5 mins until soft.","Mix the yogurt, egg and parmesan together, then add a little seasoning.","Stir the tomatoes, purée and potatoes in with the beef with some seasoning and heat through.","Smooth the surface of the beef mixture with the back of a spoon, then slice the cooked aubergine and arrange on top.","Pour the yogurt mixture over the aubergines, smooth out evenly, then grill until the topping has set and turned golden."],"ingredient_names":["beef","aubergine","greek yogurt","egg","parmesan","tomato","tomato puree","potatoes"],"allergens":["dairy","eggs"],"diet_flags":[]},{"source_id":"53008","title":"Stuffed Lamb Tomatoes","category":"Lamb","country":"Greece","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/u55lbp1585564013.jpg","youtube_url":"https://www.youtube.com/watch?v=KfJp-QfrCz4","source_url":"https://www.bbcgoodfood.com/recipes/stuffed-tomatoes-lamb-mince-dill-rice","ingredients":[{"name":"Tomatoes","measure":"4 large"},{"name":"Sugar","measure":"Pinch"},{"name":"Olive Oil","measure":"4 tbs"},{"name":"Onion","measure":"1 chopped"},{"name":"Garlic Clove","measure":"2 finely chopped"},{"name":"Lamb","measure":"200g"},{"name":"Cinnamon","measure":"1 tbs"},{"name":"Tomato Puree","measure":"2 tbs chopped"},{"name":"Rice","measure":"50g"},{"name":"Chicken Stock","measure":"100ml"},{"name":"Dill","measure":"4 tbs"},{"name":"Chopped Parsley","measure":"2 tbs"},{"name":"Mint","measure":"1 tbs"}],"steps":["Heat oven to 180C/160C fan/gas 4. Slice the tops off the tomatoes and reserve. Scoop out most of the pulp with a teaspoon, being careful not to break the skin. Finely chop the pulp, and keep any juices. Sprinkle the insides of the tomatoes with a little sugar to take away the acidity, then place them on a baking tray.","Heat 2 tbsp olive oil in a large frying pan, add the onion and garlic, then gently cook for about 10 mins until soft but not coloured. Add the lamb, cinnamon and tomato purée, turn up the heat, then fry until the meat is browned. Add the tomato pulp and juice, the rice and the stock. Season generously. Bring to the boil, then simmer for 15 mins or until the rice is tender and the liquid has been absorbed. Set aside to cool a little, then stir in the herbs.","Stuff the tomatoes up to the brim, top tomatoes with their lids, drizzle with 2 tbsp more olive oil, sprinkle 3 tbsp water into the tray, then bake for 35 mins. Serve with salad and crusty bread, hot or cold."],"ingredient_names":["tomatoes","sugar","olive oil","onion","garlic clove","lamb","cinnamon","tomato puree","rice","chicken stock","dill","chopped parsley","mint"],"allergens":[],"diet_flags":[]},{"source_id":"53009","title":"Lamb and Lemon Souvlaki","category":"Lamb","country":"Greece","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/rjhf741585564676.jpg","youtube_url":"https://www.youtube.com/watch?v=krR4rhjR75Y","source_url":"https://www.bbcgoodfood.com/recipes/lamb-lemon-dill-souvlaki","ingredients":[{"name":"Garlic","measure":"2 cloves"},{"name":"Sea Salt","measure":"2 tsp"},{"name":"Olive Oil","measure":"4 tbs"},{"name":"Lemon","measure":"Zest and juice of 1"},{"name":"Dill","measure":"1 tbs"},{"name":"Lamb Leg","measure":"750g"},{"name":"Pita Bread","measure":"To serve"}],"steps":["Pound the garlic with sea salt in a pestle and mortar (or use a small food processor), until the garlic forms a paste.","Whisk together the oil, lemon juice, zest, dill and garlic.","Mix in the lamb and combine well.","Cover and marinate for at least 2 hrs or overnight in the fridge.","If you’re going to use bamboo skewers, soak them in cold water.","If you’ve prepared the lamb the previous day, take it out of the fridge 30 mins before cooking.","Thread the meat onto the soaked or metal skewers.","Heat the grill to high or have a hot griddle pan or barbecue ready.","Cook the skewers for 2-3 mins on each side, basting with the remaining marinade.","Heat the pitta or flatbreads briefly, then stuff with the souvlaki.","Add Greek salad (see 'Goes well with', right) and Tzatziki (below), if you like."],"ingredient_names":["garlic","sea salt","olive oil","lemon","dill","lamb leg","pita bread"],"allergens":["gluten"],"diet_flags":[]},{"source_id":"53010","title":"Lamb Tzatziki Burgers","category":"Lamb","country":"Greece","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/k420tj1585565244.jpg","youtube_url":"https://www.youtube.com/watch?v=s7_TF4ZHjPc","source_url":"https://www.bbcgoodfood.com/recipes/lamb-burgers-tzatziki","ingredients":[{"name":"Bulgur Wheat","measure":"25g"},{"name":"Lamb Mince","measure":"500g"},{"name":"Cumin","measure":"1 tsp"},{"name":"Coriander","measure":"1 tsp"},{"name":"Paprika","measure":"1 tsp"},{"name":"Garlic","measure":"1 clove finely chopped"},{"name":"Olive Oil","measure":"For frying"},{"name":"Bun","measure":"4"},{"name":"Cucumber","measure":"Grated"},{"name":"Greek Yogurt","measure":"200g"},{"name":"Mint","measure":"2 tbs"}],"steps":["Tip the bulghar into a pan, cover with water and boil for 10 mins. Drain really well in a sieve, pressing out any excess water.","To make the tzatziki, squeeze and discard the juice from the cucumber, then mix into the yogurt with the chopped mint and a little salt.","Work the bulghar into the lamb with the spices, garlic (if using) and seasoning, then shape into 4 burgers. Brush with a little oil and fry or barbecue for about 5 mins each side until cooked all the way through. Serve in the buns (toasted if you like) with the tzatziki, tomatoes, onion and a few mint leaves."],"ingredient_names":["bulgur wheat","lamb mince","cumin","coriander","paprika","garlic","olive oil","bun","cucumber","greek yogurt","mint"],"allergens":["dairy","gluten"],"diet_flags":[]},{"source_id":"53011","title":"Chicken Quinoa Greek Salad","category":"Chicken","country":"Greece","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/k29viq1585565980.jpg","youtube_url":"https://www.youtube.com/watch?v=akcrkXYr61M","source_url":"https://www.bbcgoodfood.com/recipes/griddled-chicken-quinoa-greek-salad","ingredients":[{"name":"Quinoa","measure":"225g"},{"name":"Butter","measure":"25g"},{"name":"Red Chilli","measure":"1 chopped"},{"name":"Garlic","measure":"1 clove finely chopped"},{"name":"Chicken Breast","measure":"400g"},{"name":"Olive Oil","measure":"2 tbs"},{"name":"Black Olives","measure":"Handful"},{"name":"Red Onions","measure":"1 chopped"},{"name":"Feta","measure":"100g"},{"name":"Mint","measure":"Chopped"},{"name":"Lemon","measure":"Juice of 1/2"}],"steps":["Cook the quinoa following the pack instructions, then rinse in cold water and drain thoroughly.","Meanwhile, mix the butter, chilli and garlic into a paste. Toss the chicken fillets in 2 tsp of the olive oil with some seasoning. Lay in a hot griddle pan and cook for 3-4 mins each side or until cooked through. Transfer to a plate, dot with the spicy butter and set aside to melt.","Next, tip the tomatoes, olives, onion, feta and mint into a bowl. Toss in the cooked quinoa. Stir through the remaining olive oil, lemon juice and zest, and season well. Serve with the chicken fillets on top, drizzled with any buttery chicken juices."],"ingredient_names":["quinoa","butter","red chilli","garlic","chicken breast","olive oil","black olives","red onions","feta","mint","lemon"],"allergens":["dairy"],"diet_flags":[]},{"source_id":"53012","title":"Gigantes Plaki","category":"Vegetarian","country":"Greece","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/b79r6f1585566277.jpg","youtube_url":"https://www.youtube.com/watch?v=e-2K2iyPASA","source_url":"https://www.bbcgoodfood.com/recipes/gigantes-plaki","ingredients":[{"name":"Butter Beans","measure":"400g"},{"name":"Olive Oil","measure":"3 tbs"},{"name":"Onion","measure":"1 chopped"},{"name":"Garlic Clove","measure":"2 chopped"},{"name":"Tomato Puree","measure":"2 tbs"},{"name":"Tomatoes","measure":"800g"},{"name":"Sugar","measure":"1 tbs"},{"name":"Dried Oregano","measure":"1 tbs"},{"name":"Cinnamon","measure":"Pinch"},{"name":"Chopped Parsley","measure":"2 tbs"}],"steps":["Soak the beans overnight in plenty of water.","Drain, rinse, then place in a pan covered with water.","Bring to the boil, reduce the heat, then simmer for approx 50 mins until slightly tender but not soft. Drain, then set aside.","Heat oven to 180C/160C fan/gas 4.","Heat the olive oil in a large frying pan, tip in the onion and garlic, then cook over a medium heat for 10 mins until softened but not browned.","Add the tomato purée, cook for a further min, add remaining ingredients, then simmer for 2-3 mins.","Season generously, then stir in the beans.","Tip into a large ovenproof dish, then bake for approximately 1 hr, uncovered and without stirring, until the beans are tender.","The beans will absorb all the fabulous flavours and the sauce will thicken.","Allow to cool, then scatter with parsley and drizzle with a little more olive oil to serve."],"ingredient_names":["butter beans","olive oil","onion","garlic clove","tomato puree","tomatoes","sugar","dried oregano","cinnamon","chopped parsley"],"allergens":[],"diet_flags":["pescatarian","vegan","vegetarian"]},{"source_id":"53013","title":"Big Mac","category":"Beef","country":"United States","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/urzj1d1587670726.jpg","youtube_url":"https://www.youtube.com/watch?v=C5J39YnnPsg","source_url":"https://www.delicious.com.au/recipes/finally-recipe-worlds-top-selling-burger-big-mac/5221ee4a-279e-4a0b-8629-f442dc46822e","ingredients":[{"name":"Minced Beef","measure":"400g"},{"name":"Olive Oil","measure":"2 tbs"},{"name":"Sesame Seed Burger Buns","measure":"2"},{"name":"Onion","measure":"Chopped"},{"name":"Iceberg Lettuce","measure":"1/4"},{"name":"Cheese","measure":"2 sliced"},{"name":"Dill Pickles","measure":"2 large"},{"name":"Mayonnaise","measure":"1 cup"},{"name":"White Wine Vinegar","measure":"2 tsp"},{"name":"Pepper","measure":"Pinch"},{"name":"Mustard","measure":"2 tsp"},{"name":"Onion Salt","measure":"1 1/2 tsp"},{"name":"Garlic Powder","measure":"1 1/2 tsp"},{"name":"Paprika","measure":"1/2 tsp"}],"steps":["For the Big Mac sauce, combine all the ingredients in a bowl, season with salt and chill until ready to use.","To make the patties, season the mince with salt and pepper and form into 4 balls using about 1/3 cup mince each. Place each onto a square of baking paper and flatten to form into four x 15cm circles. Heat oil in a large frypan over high heat. In 2 batches, cook beef patties for 1-2 minutes each side until lightly charred and cooked through. Remove from heat and keep warm. Repeat with remaining two patties.","Carefully slice each burger bun into three acrossways, then lightly toast.","To assemble the burgers, spread a little Big Mac sauce over the bottom base. Top with some chopped onion, shredded lettuce, slice of cheese, beef patty and some pickle slices. Top with the middle bun layer, and spread with more Big Mac sauce, onion, lettuce, pickles, beef patty and then finish with more sauce. Top with burger lid to serve.","After waiting half an hour for your food to settle, go for a jog."],"ingredient_names":["minced beef","olive oil","sesame seed burger buns","onion","iceberg lettuce","cheese","dill pickles","mayonnaise","white wine vinegar","pepper","mustard","onion salt","garlic powder","paprika"],"allergens":["dairy","eggs","gluten","sesame"],"diet_flags":[]},{"source_id":"53016","title":"Chick-Fil-A Sandwich","category":"Chicken","country":"United States","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/sbx7n71587673021.jpg","youtube_url":"https://www.youtube.com/watch?v=1WDesu7bUDM","source_url":"https://hilahcooking.com/chick-fil-a-copycat/","ingredients":[{"name":"Chicken Breast","measure":"1"},{"name":"Pickle Juice","measure":"1/4 cup"},{"name":"Egg","measure":"1"},{"name":"Milk","measure":"1/4 cup"},{"name":"Flour","measure":"1/2 cup"},{"name":"Icing Sugar","measure":"1 tbs"},{"name":"Paprika","measure":"1/2 tsp"},{"name":"Salt","measure":"1/2 tsp"},{"name":"Black Pepper","measure":"1/4 tsp"},{"name":"Garlic Powder","measure":"1/4 tsp"},{"name":"Celery Salt","measure":"1/4 tsp"},{"name":"Cayenne Pepper","measure":"1/2 tsp"},{"name":"Olive Oil","measure":"1 cup"},{"name":"Sesame Seed Burger Buns","measure":"1"}],"steps":["Wrap the chicken loosely between plastic wrap and pound gently with the flat side of a meat tenderizer until about 1/2 inch thick all around.","Cut into two pieces, as even as possible.","Marinate in the pickle juice for 30 minutes to one hour (add a teaspoon of Tabasco sauce now for a spicy sandwich).","Beat the egg with the milk in a bowl.","Combine the flour, sugar, and spices in another bowl.","Dip the chicken pieces each into the egg on both sides, then coat in flour on both sides.","Heat the oil in a skillet (1/2 inch deep) to about 345-350.","Fry each cutlet for 2 minutes on each side, or until golden and cooked through.","Blot on paper and serve on toasted buns with pickle slices."],"ingredient_names":["chicken breast","pickle juice","egg","milk","flour","icing sugar","paprika","salt","black pepper","garlic powder","celery salt","cayenne pepper","olive oil","sesame seed burger buns"],"allergens":["dairy","eggs","gluten","sesame"],"diet_flags":[]},{"source_id":"53017","title":"Paszteciki (Polish Pasties)","category":"Beef","country":"Poland","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/c9a3l31593261890.jpg","youtube_url":"https://www.youtube.com/watch?v=qANmR6BBJpQ","source_url":"https://www.food.com/recipe/paszteciki-polish-pasties-117909","ingredients":[{"name":"Flour","measure":"1 cup"},{"name":"Salt","measure":"1/4 tsp"},{"name":"Egg","measure":"1 Yolk"},{"name":"Egg","measure":"1"},{"name":"Butter","measure":"5 tbs"},{"name":"Butter","measure":"6 tblsp"},{"name":"Onion","measure":"1/3 cup"},{"name":"Swede","measure":"1/2 cup"},{"name":"Beef Brisket","measure":"1/2 lb"},{"name":"Eggs","measure":"2 Beaten"},{"name":"Salt","measure":"1 tsp"},{"name":"Pepper","measure":"1/4 tsp"}],"steps":["Sift flour and salt into a large mixing bowl.","Use a spoon to push the egg yolk through a fine sieve into the flour.","Add the raw egg and mix well.","Beat in butter 1 tablespoon at a time.","Place dough on a floured surface and knead until smooth and elastic, then wrap in waxed paper and refrigerate until firm (at least 30 minutes).","In a heavy skillet, melt 2 tablespoons butter over medium heat; saute the onion and rutabaga until the onion is soft and transparent (5 minutes).","Put the onions, rutabaga, and beef through a meat grinder twice if you have one, if not just chop them up as fine as possible.","Melt the remaining 4 tablespoons butter over medium heat, and add the meat mixture.","Cook over low heat, stirring occasionally, until all of the liquid has evaporated and the mixture is thick enough to hold its shape.","Remove from heat and let cool, then stir in 1 egg, and season with salt and pepper.","Preheat oven to 350°F.","On a lightly floured surface, roll the dough out into a 13x8\" rectangle (1/8\" thick).","Spoon the filling down the center of the rectangle lengthwise, leaving about an inch of space on each end.","Lightly brush the long sides with cold water, then fold one of the long sides over the filling and the other side over the top of that.","Brush the short ends with cold water and fold them over the top, enclosing the filling.","Place pastry seam side down on a baking sheet and brush the top evenly with the remaining scrambled egg.","Bake in preheated oven until rich golden brown (30 minutes).","Slice pastry diagonally into 1.5\" long pieces and serve as an appetizer or with soup."],"ingredient_names":["flour","salt","egg","egg","butter","butter","onion","swede","beef brisket","eggs","salt","pepper"],"allergens":["dairy","eggs","gluten"],"diet_flags":[]},{"source_id":"53018","title":"Bigos (Hunters Stew)","category":"Pork","country":"Poland","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/md8w601593348504.jpg","youtube_url":"https://www.youtube.com/watch?v=Oqg_cO4s8ik","source_url":"https://www.allrecipes.com/recipe/138131/bigos-hunters-stew/","ingredients":[{"name":"Bacon","measure":"2 sliced"},{"name":"Kielbasa","measure":"1 lb"},{"name":"Pork","measure":"1 lb"},{"name":"Flour","measure":"1/4 cup"},{"name":"Garlic","measure":"3 chopped"},{"name":"Onion","measure":"1 Diced"},{"name":"Mushrooms","measure":"1 1/2 cup"},{"name":"Cabbage","measure":"4 cups"},{"name":"Sauerkraut","measure":"1 Jar"},{"name":"Red Wine","measure":"1/4 cup"},{"name":"Bay Leaf","measure":"1"},{"name":"Basil","measure":"1 tsp"},{"name":"Marjoram","measure":"1 tsp"},{"name":"Paprika","measure":"1 tbs"},{"name":"Caraway Seed","measure":"1/8 teaspoon"},{"name":"Hotsauce","measure":"1 dash"},{"name":"Beef Stock","measure":"5 Cups"},{"name":"Tomato Puree","measure":"2 tbs"},{"name":"Diced Tomatoes","measure":"1 cup"},{"name":"Worcestershire Sauce","measure":"1 dash"}],"steps":["Preheat the oven to 350 degrees F (175 degrees C).","Heat a large pot over medium heat. Add the bacon and kielbasa; cook and stir until the bacon has rendered its fat and sausage is lightly browned. Use a slotted spoon to remove the meat and transfer to a large casserole or Dutch oven.","Coat the cubes of pork lightly with flour and fry them in the bacon drippings over medium-high heat until golden brown. Use a slotted spoon to transfer the pork to the casserole. Add the garlic, onion, carrots, fresh mushrooms, cabbage and sauerkraut. Reduce heat to medium; cook and stir until the carrots are soft, about 10 minutes. Do not let the vegetables brown.","Deglaze the pan by pouring in the red wine and stirring to loosen all of the bits of food and flour that are stuck to the bottom. Season with the bay leaf, basil, marjoram, paprika, salt, pepper, caraway seeds and cayenne pepper; cook for 1 minute.","Mix in the dried mushrooms, hot pepper sauce, Worcestershire sauce, beef stock, tomato paste and tomatoes. Heat through just until boiling. Pour the vegetables and all of the liquid into the casserole dish with the meat. Cover with a lid.","Bake in the preheated oven for 2 1/2 to 3 hours, until meat is very tender."],"ingredient_names":["bacon","kielbasa","pork","flour","garlic","onion","mushrooms","cabbage","sauerkraut","red wine","bay leaf","basil","marjoram","paprika","caraway seed","hotsauce","beef stock","tomato puree","diced tomatoes","worcestershire sauce"],"allergens":["fish","gluten"],"diet_flags":[]},{"source_id":"53020","title":"Rosol (Polish Chicken Soup)","category":"Chicken","country":"Poland","tags":["Soup"],"image_url":"https://www.themealdb.com/images/media/meals/lx1kkj1593349302.jpg","youtube_url":"https://www.youtube.com/watch?v=AU60fxyxXGw","source_url":"https://polishhousewife.com/rosol-polish-chicken-soup/","ingredients":[{"name":"Chicken Legs","measure":"4 Chopped"},{"name":"Onions","measure":"2 large"},{"name":"Carrots","measure":"5 chopped"},{"name":"Leek","measure":"1 chopped"},{"name":"Celery","measure":"1 small"},{"name":"Cabbage","measure":"1/4"},{"name":"Cloves","measure":"1 whole"},{"name":"Allspice","measure":"1tsp"},{"name":"Bay Leaf","measure":"2"},{"name":"Parsley","measure":"4 sprigs"},{"name":"Dill","measure":"4 sprigs"},{"name":"Pepper","measure":"1 tsp"},{"name":"Salt","measure":"1 tbs"}],"steps":["Add chicken to a large Dutch oven or stock pot","Cover with water","Bring to a boil and simmer for 2 to 2 1/2 hours, skimming any impurities off the top to insure a clear broth","If your pot is big enough, add the vegetables and spices for the last hour of the cooking time","My Dutch oven wasn’t big enough to hold everything, just the chicken and other bones filled the pot, so I cooked the meat/bones for the full cooking time, then removed them, and cooked the vegetables and spices separately","Strain everything out of the broth","Bone the chicken, pulling the meat into large chunks","Slice the carrots","Return the chicken and carrots to the broth","Cook noodles according to package instructions if you’re using them","Add noodles to bowl and then top with hot soup"],"ingredient_names":["chicken legs","onions","carrots","leek","celery","cabbage","cloves","allspice","bay leaf","parsley","dill","pepper","salt"],"allergens":[],"diet_flags":[]},{"source_id":"53021","title":"Golabki (cabbage roll)","category":"Beef","country":"Poland","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/q8sp3j1593349686.jpg","youtube_url":"https://www.youtube.com/watch?v=rBrTkDdoPYg","source_url":"https://www.allrecipes.com/recipe/234975/golabki-stuffed-cabbage-rolls/","ingredients":[{"name":"Cabbage","measure":"1"},{"name":"Butter","measure":"2 tbs"},{"name":"Onion","measure":"1 chopped"},{"name":"Ground Beef","measure":"1 lb"},{"name":"Ground Pork","measure":"1/2 lb"},{"name":"Rice","measure":"1 1/2 cups"},{"name":"Garlic","measure":"1 tsp"},{"name":"Salt","measure":"1 tsp"},{"name":"Black Pepper","measure":"1/4 tsp"},{"name":"Tomato Puree","measure":"3 cans"}],"steps":["Bring a large pot of lightly salted water to a boil. Place cabbage head into water, cover pot, and cook until cabbage leaves are slightly softened enough to remove from head, 3 minutes. Remove cabbage from pot and let cabbage sit until leaves are cool enough to handle, about 10 minutes.","Remove 18 whole leaves from the cabbage head, cutting out any thick tough center ribs. Set whole leaves aside. Chop the remainder of the cabbage head and spread it in the bottom of a casserole dish.","Melt butter in a large skillet over medium-high heat. Cook and stir onion in hot butter until tender, 5 to 10 minutes. Cool.","Stir onion, beef, pork, rice, garlic, 1 teaspoon salt, and 1/4 teaspoon pepper together in a large bowl.","Preheat oven to 350 degrees F (175 degrees C).","Place about 1/2 cup beef mixture on a cabbage leaf. Roll cabbage around beef mixture, tucking in sides to create an envelope around the meat. Repeat with remaining leaves and meat mixture. Place cabbage rolls in a layer atop the chopped cabbage in the casserole dish; season rolls with salt and black pepper.","Whisk tomato soup, tomato juice, and ketchup together in a bowl. Pour tomato soup mixture over cabbage rolls and cover dish wish aluminum foil.","Bake in the preheated oven until cabbage is tender and meat is cooked through, about 1 hour."],"ingredient_names":["cabbage","butter","onion","ground beef","ground pork","rice","garlic","salt","black pepper","tomato puree"],"allergens":["dairy"],"diet_flags":[]},{"source_id":"53023","title":"Sledz w Oleju (Polish Herrings)","category":"Seafood","country":"Poland","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/7ttta31593350374.jpg","youtube_url":"https://www.youtube.com/watch?v=v6I3GZlBkOM","source_url":"https://www.thespruceeats.com/polish-herrings-in-oil-recipe-1135618","ingredients":[{"name":"Herring","measure":"8"},{"name":"Onion","measure":"1 sliced"},{"name":"Olive Oil","measure":"1/2 cup"},{"name":"Allspice","measure":"1 tsp"},{"name":"Pepper","measure":"1 tsp"},{"name":"Bay Leaf","measure":"1"}],"steps":["Soak herring in cold water for at least 1 hour. If very salty, repeat, changing the water each time.","Drain thoroughly and slice herring into bite-size pieces.","Place in a jar large enough to accommodate the pieces and cover with oil, allspice, peppercorns, and bay leaf. Close the jar.","Refrigerate for 2 to 3 days before eating. This will keep refrigerated up to 2 weeks.","Serve with finely chopped onion or onion slices, lemon, and parsley or dill."],"ingredient_names":["herring","onion","olive oil","allspice","pepper","bay leaf"],"allergens":["fish"],"diet_flags":["pescatarian"]},{"source_id":"53025","title":"Ful Medames","category":"Vegetarian","country":"Egypt","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/lvn2d51598732465.jpg","youtube_url":"https://www.youtube.com/watch?v=ixpCabILuxw","source_url":"https://www.epicurious.com/recipes/food/views/ful-medames-352993","ingredients":[{"name":"Broad Beans","measure":"2 cups"},{"name":"Parsley","measure":"1/3 cup"},{"name":"Olive Oil","measure":"Dash"},{"name":"Lemons","measure":"3"},{"name":"Garlic Clove","measure":"4"},{"name":"Cumin","measure":"Sprinking"}],"steps":["As the cooking time varies depending on the quality and age of the beans, it is good to cook them in advance and to reheat them when you are ready to serve. Cook the drained beans in a fresh portion of unsalted water in a large saucepan with the lid on until tender, adding water to keep them covered, and salt when the beans have softened. They take 2–2 1/2 hours of gentle simmering. When the beans are soft, let the liquid reduce. It is usual to take out a ladle or two of the beans and to mash them with some of the cooking liquid, then stir this back into the beans. This is to thicken the sauce.","Serve the beans in soup bowls sprinkled with chopped parsley and accompanied by Arab bread.","Pass round the dressing ingredients for everyone to help themselves: a bottle of extra-virgin olive oil, the quartered lemons, salt and pepper, a little saucer with the crushed garlic, one with chili-pepper flakes, and one with ground cumin.","The beans are eaten gently crushed with the fork, so that they absorb the dressing.","Optional Garnishes","Peel hard-boiled eggs—1 per person—to cut up in the bowl with the beans.","Top the beans with a chopped cucumber-and-tomato salad and thinly sliced mild onions or scallions. Otherwise, pass round a good bunch of scallions and quartered tomatoes and cucumbers cut into sticks.","Serve with tahina cream sauce (page 65) or salad (page 67), with pickles and sliced onions soaked in vinegar for 30 minutes.","Another way of serving ful medames is smothered in a garlicky tomato sauce (see page 464).","In Syria and Lebanon, they eat ful medames with yogurt or feta cheese, olives, and small cucumbers.","Variations","A traditional way of thickening the sauce is to throw a handful of red lentils (1/4 cup) into the water at the start of the cooking.","In Iraq, large brown beans are used instead of the small Egyptian ones, in a dish called badkila, which is also sold for breakfast in the street."],"ingredient_names":["broad beans","parsley","olive oil","lemons","garlic clove","cumin"],"allergens":[],"diet_flags":["pescatarian","vegan","vegetarian"]},{"source_id":"53026","title":"Tamiya","category":"Vegetarian","country":"Egypt","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/n3xxd91598732796.jpg","youtube_url":"https://www.youtube.com/watch?v=mulqW-J3Yy4","source_url":"https://oukosher.org/recipes/tamiya-egyptian-dried-fava-bean-fritters/","ingredients":[{"name":"Broad Beans","measure":"3 cups"},{"name":"Spring Onions","measure":"6"},{"name":"Garlic Clove","measure":"4"},{"name":"Parsley","measure":"1/4 cup"},{"name":"Cumin","measure":"2 tsp"},{"name":"Baking Powder","measure":"1 tsp"},{"name":"Cayenne Pepper","measure":"1/2 tsp"},{"name":"Flour","measure":"Spinkling"},{"name":"Vegetable Oil","measure":"As required"}],"steps":["oak the beans in water to cover overnight.Drain. If skinless beans are unavailable, rub to loosen the skins, then discard the skins. Pat the beans dry with a towel.","Grind the beans in a food mill or meat grinder.If neither appliance is available, process them in a food processor but only until the beans form a paste. (If blended too smoothly, the batter tends to fall apart during cooking.) Add the scallions, garlic, cilantro, cumin, baking powder, cayenne, salt, pepper, and coriander, if using.  Refrigerate for at least 30 minutes.","Shape the bean mixture into 1-inch balls.Flatten slightly and coat with flour.","Heat at least 1½-inches of oil over medium heat to 365 degrees.","Fry the patties in batches, turning once, until golden brown on all sides, about 5 minutes.Remove with a wire mesh skimmer or slotted spoon. Serve as part of a meze or in pita bread with tomato-cucumber salad and tahina sauce."],"ingredient_names":["broad beans","spring onions","garlic clove","parsley","cumin","baking powder","cayenne pepper","flour","vegetable oil"],"allergens":["gluten"],"diet_flags":["pescatarian","vegan","vegetarian"]},{"source_id":"53027","title":"Koshari","category":"Vegetarian","country":"Egypt","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/4er7mj1598733193.jpg","youtube_url":"https://www.youtube.com/watch?v=y0d2ZMZBW4Y","source_url":"https://www.themediterraneandish.com/egyptian-koshari-recipe/","ingredients":[{"name":"Brown Lentils","measure":"1 1/2 cups"},{"name":"Rice","measure":"1 1/2 cups"},{"name":"Coriander","measure":"1/2 tsp"},{"name":"Macaroni","measure":"2 cups"},{"name":"Chickpeas","measure":"Can"},{"name":"Onion","measure":"1 large"},{"name":"Salt","measure":"Sprinking"},{"name":"Vegetable Oil","measure":"1/2 cup"}],"steps":["Cook the lentils. Bring lentils and 4 cups of water to a boil in a medium pot or saucepan over high heat. Reduce the heat to low and cook until lentils are just tender (15-17 minutes). Drain from water and season with a little salt. (Note: when the lentils are ready, they should not be fully cooked. They should be only par-cooked and still have a bite to them as they need to finish cooking with the rice).","Now, for the rice. Drain the rice from its soaking water. Combine the par-cooked lentils and the rice in the saucepan over medium-high heat with 1 tbsp cooking oil, salt, pepper, and coriander. Cook for 3 minutes, stirring regularly. Add warm water to cover the rice and lentil mixture by about 1 1/2 inches (you’ll probably use about 3 cups of water here). Bring to a boil; the water should reduce a bit. Now cover and cook until all the liquid has been absorbed and both the rice and lentils are well cooked through (about 20 minutes).  Keep covered and undisturbed for 5 minutes or so.","Now make the pasta. While the rice and lentils are cooking, make the pasta according to package instructions by adding the elbow pasta to boiling water with a dash of salt and a little oil. Cook until the pasta is al dente. Drain.","Cover the chickpeas and warm in the microwave briefly before serving.","Make the crispy onion topping.","Sprinkle the onion rings with salt, then toss them in the flour to coat. Shake off excess flour.","In a large skillet, heat the cooking oil over medium-high heat, cook the onion rings, stirring often, until they turn a nice caramelized brown. Onions must be crispy, but not burned (15-20 minutes)."],"ingredient_names":["brown lentils","rice","coriander","macaroni","chickpeas","onion","salt","vegetable oil"],"allergens":["gluten"],"diet_flags":["pescatarian","vegan","vegetarian"]},{"source_id":"53028","title":"Shawarma","category":"Chicken","country":"Egypt","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/kcv6hj1598733479.jpg","youtube_url":"https://www.youtube.com/watch?v=3lxUIeKDgic","source_url":"https://www.recipetineats.com/chicken-sharwama-middle-eastern/","ingredients":[{"name":"Chicken Thighs","measure":"1 kg"},{"name":"Coriander","measure":"1 tbs"},{"name":"Cumin","measure":"1 tbs"},{"name":"Cardamom","measure":"1 tbs"},{"name":"Cayenne Pepper","measure":"1 tsp"},{"name":"Paprika","measure":"2 tsp"},{"name":"Lemon Juice","measure":"2 tbs"},{"name":"Olive Oil","measure":"3 tbs"},{"name":"Greek Yogurt","measure":"1 cup"},{"name":"Garlic Clove","measure":"1"},{"name":"Cumin","measure":"1 tsp"},{"name":"Lemon Juice","measure":"Splash"},{"name":"Lettuce","measure":"Sliced"},{"name":"Tomato","measure":"Sliced"},{"name":"Pita Bread","measure":"6"}],"steps":["Combine the marinade ingredients in a large ziplock bag (or bowl).","Add the chicken and use your hands to make sure each piece is coated. If using a ziplock bag, I find it convenient to close the bag then massage the bag to disperse the rub all over each chicken piece.","Marinate overnight or up to 24 hours.","Combine the Yoghurt Sauce ingredients in a bowl and mix. Cover and put in the fridge until required (it will last for 3 days in the fridge).","Heat grill/BBQ (or large heavy based pan on stove) on medium high. You should not need to oil it because the marinade has oil in it and also thigh fillets have fat. But if you are worried then oil your hotplate/grill. (See notes for baking)","Place chicken on the grill and cook the first side for 4 to 5 minutes until nicely charred, then turn and cook the other side for 3 to 4 minutes (the 2nd side takes less time).","Remove chicken from the grill and cover loosely with foil. Set aside to rest for 5 minutes.","TO SERVE","Slice chicken and pile onto platter alongside flatbreads, Salad and the Yoghurt Sauce.","To make a wrap, get a piece of flatbread and smear with Yoghurt Sauce. Top with a bit of lettuce and tomato and Chicken Shawarma. Roll up and enjoy!"],"ingredient_names":["chicken thighs","coriander","cumin","cardamom","cayenne pepper","paprika","lemon juice","olive oil","greek yogurt","garlic clove","cumin","lemon juice","lettuce","tomato","pita bread"],"allergens":["dairy","gluten"],"diet_flags":[]},{"source_id":"53029","title":"Mulukhiyah","category":"Beef","country":"Egypt","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/x372ug1598733932.jpg","youtube_url":"https://www.youtube.com/watch?v=vWc5JzgAkIQ","source_url":"https://chefindisguise.com/2017/05/15/mulukhiyah-a-stew-fit-for-royals/","ingredients":[{"name":"Mulukhiyah","measure":"800g"},{"name":"Onion","measure":"1 chopped"},{"name":"Beef","measure":"300g"},{"name":"Salt","measure":"1 tsp"},{"name":"Water","measure":"1 Litre"},{"name":"Garlic Clove","measure":"1"},{"name":"Olive Oil","measure":"1/2 cup"}],"steps":["Saute the onions in the 3-4 tablespoons olive oil","Add the beef cubes or the chicken cutlets, sear for 3-4 min on each side","Add 1 liter of water or just enough to cover the meat","Cook over medium heat until the meat is done (I usually do this in the pressure cooker and press them for 5 min)","Add the frozen mulukhyia and stir until it thaws completely and then comes to a boil","In another pan add the 1/4 to 1/2 cup of olive oil and the cloves of garlic and cook over medium low heat until you can smell the garlic (don’t brown it, it will become bitter)","Add the oil and garlic to the mulukhyia and lower the heat and simmer for 5-10 minutes","Add salt to taste","Serve with a generous amount of lemon juice.","You can serve it with some short grain rice or some pita bread"],"ingredient_names":["mulukhiyah","onion","beef","salt","water","garlic clove","olive oil"],"allergens":[],"diet_flags":[]},{"source_id":"53031","title":"Egyptian Fatteh","category":"Beef","country":"Egypt","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/rlwcc51598734603.jpg","youtube_url":"https://www.youtube.com/watch?v=WLuOHkDE4A4","source_url":"https://www.food.com/recipe/egyptian-faatah-rice-meat-with-crispy-bread-on-bottom-194764","ingredients":[{"name":"Beef","measure":"1lb"},{"name":"Onion","measure":"1"},{"name":"Chicken Stock Cube","measure":"1"},{"name":"Tomatoes","measure":"2"},{"name":"Garlic Clove","measure":"4"},{"name":"Tomato Puree","measure":"1 tbs"},{"name":"Rice","measure":"2 cups"},{"name":"Noodles","measure":"1/4 cup"},{"name":"Butter","measure":"1/4 cup"},{"name":"Olive Oil","measure":"2 cups"},{"name":"Pita Bread","measure":"1"},{"name":"Cumin","measure":"1 tbs"},{"name":"White Wine Vinegar","measure":"3 tbs"},{"name":"Salt","measure":"To taste"},{"name":"Pepper","measure":"To taste"}],"steps":["To prepare bread for bottom of dish: Take pita bread and rip into bite size pieces. In a frying pan, add about a 1/4 stick of butter, add bread pieces and fry until golden brown and crisp. Put these pieces in a glass baking dish, preferably a square sized dish. Set aside.","Then add to same pan, a little more butter, salt, approximately 2 cloves of crushed fresh garlic, and a teaspoon or so of cumin stir around a bit until you can smell aroma, then add fried bread pieces to this mixture, stir to coat bread and put back into glass baking dish. Set aside.","To prepare meat: put some butter in a pot, stir fry meat until brown, add 1 onion quartered, salt & pepper, 1 cube of chicken bouillon and water to cover meat. Bring to a boil, turn down to simmer, cover and cook until tender, approximately 2 hours. After meat has cooled, take out chunks of meat and put in a bowl, set aside. Reserve soup from the meat separately.","To prepare the rice: Put some butter into a pot, add shareya (fideo noodles) like a handful or so, keep stirring until golden brown, not too dark, but very golden. Then add two cups of rice, stir a little bit until some of the rice turns an opaque white. Add 2-1/4 cups of water and salt to taste. Bring to a boil, cover and turn down to simmer, cook until tender. Test the rice tenderness after about 35 minutes.","Now take some of the soup from meat and add to the top of the bread pieces in baking dish to saturate.Add cooked rice on top of bread pieces. Slowly spoon remainder of soup onto rice, looking at glass dish sides to see level of soup, should reach just to top of rice, don’t worry, this doesn’t have to be exact. Now you’re ready to make the sauce and fry the meat to put on top.","To prepare red sauce: In a pan, add a little oil or butter, crushed tomato, a half teaspoon of tomato paste, salt & pepper, 2 cloves of fresh crushed garlic and cumin. Add also approximately 3 tablespoons of vinegar, stir this until you smell aroma and it is a bit smooth. It should be a bit thick, not watery, but if too thick you can add a bit of water. Spread with a wooden spoon atop the rice to cover.","To fry meat: In a pan add a bit of butter or oil, the meat, just a touch of tomato paste, about a tablespoon of fresh crushed garlic, salt & pepper, a teaspoon of cumin. Cook until meat is golden fried.","Spoon this atop the rice and serve. Enjoy!"],"ingredient_names":["beef","onion","chicken stock cube","tomatoes","garlic clove","tomato puree","rice","noodles","butter","olive oil","pita bread","cumin","white wine vinegar","salt","pepper"],"allergens":["dairy","gluten"],"diet_flags":[]},{"source_id":"53032","title":"Tonkatsu pork","category":"Pork","country":"Japan","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/lwsnkl1604181187.jpg","youtube_url":"https://www.youtube.com/watch?v=aASr5x0d3Ys","source_url":"https://www.bbcgoodfood.com/recipes/tonkatsu-pork","ingredients":[{"name":"Pork Chops","measure":"4"},{"name":"Flour","measure":"100g"},{"name":"Eggs","measure":"2 Beaten"},{"name":"Breadcrumbs","measure":"100g"},{"name":"Vegetable Oil","measure":"Fry"},{"name":"Tomato Ketchup","measure":"2 tbs"},{"name":"Worcestershire Sauce","measure":"2 tbs"},{"name":"Oyster Sauce","measure":"1 tbs"},{"name":"Caster Sugar","measure":"2 tblsp"}],"steps":["Remove the large piece of fat on the edge of each pork loin, then bash each of the loins between two pieces of baking parchment until around 1cm in thickness – you can do this using a meat tenderiser or a rolling pin. Once bashed, use your hands to reshape the meat to its original shape and thickness – this step will ensure the meat is as succulent as possible.","Put the flour, eggs and panko breadcrumbs into three separate wide-rimmed bowls. Season the meat, then dip first in the flour, followed by the eggs, then the breadcrumbs.","In a large frying or sauté pan, add enough oil to come 2cm up the side of the pan. Heat the oil to 180C – if you don’t have a thermometer, drop a bit of panko into the oil and if it sinks a little then starts to fry, the oil is ready. Add two pork chops and cook for 1 min 30 secs on each side, then remove and leave to rest on a wire rack for 5 mins. Repeat with the remaining pork chops.","While the pork is resting, make the sauce by whisking the ingredients together, adding a splash of water if it’s particularly thick. Slice the tonkatsu and serve drizzled with the sauce."],"ingredient_names":["pork chops","flour","eggs","breadcrumbs","vegetable oil","tomato ketchup","worcestershire sauce","oyster sauce","caster sugar"],"allergens":["eggs","fish","gluten","shellfish"],"diet_flags":[]},{"source_id":"53034","title":"Japanese Katsudon","category":"Pork","country":"Japan","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/d8f6qx1604182128.jpg","youtube_url":"https://www.youtube.com/watch?v=voE-MBJqBVk","source_url":"https://www.bbcgoodfood.com/recipes/japanese-katsudon","ingredients":[{"name":"Vegetable Oil","measure":"1 tbs"},{"name":"Onion","measure":"1 large"},{"name":"Pork","measure":"1 chopped"},{"name":"Vegetable Stock","measure":"150ml"},{"name":"Soy Sauce","measure":"1 tbs"},{"name":"Mirin","measure":"1 tsp"},{"name":"Sugar","measure":"1 tsp"},{"name":"Eggs","measure":"2 Beaten"},{"name":"Sushi Rice","measure":"200g"},{"name":"Chives","measure":"Chopped"}],"steps":["Heat the oil in a pan, fry the sliced onion until golden brown, then add the tonkatsu (see recipe here), placing it in the middle of the pan.","Mix the dashi, soy, mirin and sugar together and tip three-quarters of the mixture around the tonkatsu.","Sizzle for a couple of mins so the sauce thickens a little and the tonkatsu reheats.","Tip the beaten eggs around the tonkatsu and cook for 2-3 mins until the egg is cooked through but still a little runny.","Divide the rice between two bowls, then top each with half the egg and tonkatsu mix, sprinkle over the chives and serve immediately, drizzling with a little more soy if you want an extra umami kick."],"ingredient_names":["vegetable oil","onion","pork","vegetable stock","soy sauce","mirin","sugar","eggs","sushi rice","chives"],"allergens":["eggs","gluten","soy"],"diet_flags":[]},{"source_id":"53035","title":"Ham hock colcannon","category":"Pork","country":"Ireland","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/n41ny81608588066.jpg","youtube_url":"https://www.youtube.com/watch?v=aQJAU2iJ730","source_url":"https://www.bbcgoodfood.com/recipes/ham-hock-colcannon","ingredients":[{"name":"Floury Potatoes","measure":"800g"},{"name":"Butter","measure":"50g"},{"name":"Garlic Clove","measure":"3 chopped"},{"name":"Cabbage","measure":"1 chopped"},{"name":"Spring Onions","measure":"8"},{"name":"Double Cream","measure":"100ml"},{"name":"Mustard","measure":"2 tbs"},{"name":"Ham","measure":"180g"},{"name":"Eggs","measure":"4"}],"steps":["Peel and cut the potatoes into even, medium-sized chunks. Put in a large pan filled with cold salted water, bring to the boil and cook for 10-15 mins until a knife can be inserted into the potatoes easily.","Meanwhile, melt the butter in a large sauté pan over a medium heat. Add the garlic, cabbage, spring onions and some seasoning. Stir occasionally until the cabbage is wilted but still retains a little bite, then set aside.","Drain the potatoes, leave to steam-dry for a couple of mins, then mash with the cream, mustard and seasoning in the same saucepan. Stir in the cabbage and ham hock. Keep warm over a low heat.","Reheat the pan you used to cook the cabbage (no need to wash first), add a splash of oil, crack in the eggs and fry to your liking. To serve, divide the colcannon between bowls and top each with a fried egg."],"ingredient_names":["floury potatoes","butter","garlic clove","cabbage","spring onions","double cream","mustard","ham","eggs"],"allergens":["dairy","eggs"],"diet_flags":[]},{"source_id":"53036","title":"Boxty Breakfast","category":"Pork","country":"Ireland","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/naqyel1608588563.jpg","youtube_url":"https://www.youtube.com/watch?v=80W0mCFDIP0","source_url":"https://www.bbcgoodfood.com/recipes/boxty-bacon-eggs-tomatoes","ingredients":[{"name":"Potatoes","measure":"4 large"},{"name":"Spring Onions","measure":"1  bunch"},{"name":"Plain Flour","measure":"100g"},{"name":"Egg White","measure":"1"},{"name":"Milk","measure":"150ml"},{"name":"Bicarbonate Of Soda","measure":"1 tsp"},{"name":"Butter","measure":"3 tbs"},{"name":"Vegetable Oil","measure":"2 tbs"},{"name":"Cherry Tomatoes","measure":"6"},{"name":"Bacon","measure":"12"},{"name":"Egg","measure":"6"}],"steps":["Before you start, put your oven on its lowest setting, ready to keep things warm. Peel the potatoes, grate 2 of them, then set aside. Cut the other 2 into large chunks, then boil for 10-15 mins or until tender. Meanwhile, squeeze as much of the liquid from the grated potatoes as you can using a clean tea towel. Mash the boiled potatoes, then mix with the grated potato, spring onions and flour.","Whisk the egg white in a large bowl until it holds soft peaks. Fold in the buttermilk, then add the bicarbonate of soda. Fold into the potato mix.","Heat a large non-stick frying pan over a medium heat, then add 1 tbsp butter and some of the oil. Drop 3-4 spoonfuls of the potato mixture into the pan, then gently cook for 3-5 mins on each side until golden and crusty. Keep warm on a plate in the oven while you cook the next batch, adding more butter and oil to the pan before you do so. You will get 16 crumpet-size boxty from the mix. Can be made the day ahead, drained on kitchen paper, then reheated in a low oven for 20 mins.","Heat the grill to medium and put the tomatoes in a heavy-based pan. Add a good knob of butter and a little oil, then fry for about 5 mins until softened. Grill the bacon, then pile onto a plate and keep warm. Stack up the boxty, bacon and egg, and serve the tomatoes on the side."],"ingredient_names":["potatoes","spring onions","plain flour","egg white","milk","bicarbonate of soda","butter","vegetable oil","cherry tomatoes","bacon","egg"],"allergens":["dairy","eggs","gluten"],"diet_flags":[]},{"source_id":"53037","title":"Coddled pork with cider","category":"Pork","country":"Ireland","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/7vpsfp1608588991.jpg","youtube_url":"https://www.youtube.com/watch?v=ftn_4mc-65o","source_url":"https://www.bbcgoodfood.com/recipes/irish-coddled-pork-cider","ingredients":[{"name":"Butter","measure":"Knob"},{"name":"Pork Chops","measure":"2"},{"name":"Bacon","measure":"4"},{"name":"Potatoes","measure":"2"},{"name":"Carrots","measure":"1"},{"name":"Swede","measure":"1/2"},{"name":"Cabbage","measure":"1/2"},{"name":"Bay Leaf","measure":"1"},{"name":"Cider","measure":"100ml"},{"name":"Chicken Stock","measure":"100g"}],"steps":["Heat the butter in a casserole dish until sizzling, then fry the pork for 2-3 mins on each side until browned. Remove from the pan.","Tip the bacon, carrot, potatoes and swede into the pan, then gently fry until slightly coloured. Stir in the cabbage, sit the chops back on top, add the bay leaf, then pour over the cider and stock. Cover the pan, then leave everything to gently simmer for 20 mins until the pork is cooked through and the vegetables are tender.","Serve at the table spooned straight from the dish."],"ingredient_names":["butter","pork chops","bacon","potatoes","carrots","swede","cabbage","bay leaf","cider","chicken stock"],"allergens":["dairy"],"diet_flags":[]},{"source_id":"53039","title":"Piri-piri chicken and slaw","category":"Chicken","country":"Portugal","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/hglsbl1614346998.jpg","youtube_url":"https://www.youtube.com/watch?v=_RKwKjskopk","source_url":"https://www.olivemagazine.com/recipes/family/piri-piri-chicken-and-winter-slaw/","ingredients":[{"name":"Chicken","measure":"1.5kg"},{"name":"Red Chilli","measure":"3 chopped"},{"name":"Garlic","measure":"2 cloves"},{"name":"Ginger","measure":"1 tsp"},{"name":"Dried Oregano","measure":"1 tsp"},{"name":"Coriander","measure":"1 tsp"},{"name":"Paprika","measure":"1 tsp"},{"name":"Red Wine Vinegar","measure":"2 tbs"},{"name":"Oil","measure":"2 tbs"},{"name":"Red Onions","measure":"1 sliced"},{"name":"Carrots","measure":"2"},{"name":"Beetroot","measure":"1"},{"name":"Cabbage","measure":"4 leaves"},{"name":"Mayonnaise","measure":"2 tbs"},{"name":"Greek Yogurt","measure":"2 tbs"},{"name":"Red Wine Vinegar","measure":"2 tbs"},{"name":"Cumin Seeds","measure":"1 tsp"}],"steps":["Whizz together all of the marinade ingredients in a small food processor.","Rub the marinade onto the chicken and leave for 1 hour at room temperature.","Heat the oven to 190C/fan 170C/gas 5.","Put the chicken in a roasting tray and cook for 1 hour 20 minutes.","Rest under loose foil for 20 minutes.","While the chicken is resting, mix together the slaw ingredients and season.","Serve the chicken with slaw, fries and condiments."],"ingredient_names":["chicken","red chilli","garlic","ginger","dried oregano","coriander","paprika","red wine vinegar","oil","red onions","carrots","beetroot","cabbage","mayonnaise","greek yogurt","red wine vinegar","cumin seeds"],"allergens":["dairy","eggs"],"diet_flags":[]},{"source_id":"53040","title":"Spring onion and prawn empanadas","category":"Seafood","country":"Portugal","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/1c5oso1614347493.jpg","youtube_url":"https://www.youtube.com/watch?v=Q24haJU-1dI","source_url":"https://www.olivemagazine.com/recipes/fish-and-seafood/spring-onion-and-prawn-empanadas/","ingredients":[{"name":"Spring Onions","measure":"1  bunch"},{"name":"Olive Oil","measure":"Dash"},{"name":"Red Chilli","measure":"1 finely sliced"},{"name":"Garlic","measure":"1 clove"},{"name":"Prawns","measure":"350g"},{"name":"Feta","measure":"75g"},{"name":"Butter","measure":"15g"},{"name":"Plain Flour","measure":"250g"},{"name":"Egg","measure":"1 Seperated"},{"name":"White Wine Vinegar","measure":"1/2 tsp"}],"steps":["To make the dough, rub the butter into the flour and then add the egg white and half the yolk (keep the rest), vinegar, a pinch of salt and enough cold water to make a soft dough. Knead on a floured surface until smooth and then wrap and rest for 30 minutes.","Heat the oven to 180c/fan 160c/gas 4. Trim the green ends of the spring onions and then finely slice the rest. Heat a little oil in a pan and fry them gently until soft but not browned. Add the chilli and garlic, stir and then add the prawns and cook until they are opaque. Season well. Scoop out the prawns and bubble the juices until they thicken, then add back the prawns.","Divide the empanada dough into eight balls and roll out to thin circles on a floured surface. Put some filling on one half of the dough, sprinkle the feta on top and fold the other half over. Trim the edge and then fold and crimp the dough together so the empanada is tightly sealed, put it on an oiled baking sheet either on its side or sitting on its un-crimped edge like a cornish pasty. Repeat with the remaining dough and mixture. Mix the leftover egg yolk with a splash of water and brush the top of the empanadas.","Bake for 30 minutes or until golden and slightly crisp around the edges."],"ingredient_names":["spring onions","olive oil","red chilli","garlic","prawns","feta","butter","plain flour","egg","white wine vinegar"],"allergens":["dairy","eggs","gluten","shellfish"],"diet_flags":["pescatarian"]},{"source_id":"53041","title":"Grilled Portuguese sardines","category":"Seafood","country":"Portugal","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/lpd4wy1614347943.jpg","youtube_url":"https://www.youtube.com/watch?v=JYtMjKa6cdY","source_url":"https://www.olivemagazine.com/recipes/fish-and-seafood/grilled-portuguese-sardines/","ingredients":[{"name":"Sardines","measure":"8"},{"name":"Olive Oil","measure":"2 tbs"},{"name":"Garlic","measure":"3 cloves"},{"name":"Paprika","measure":"1 tbs"},{"name":"Lemon","measure":"1/2"},{"name":"Rosemary","measure":"4 sprigs"},{"name":"Red Chilli","measure":"1"}],"steps":["Put all of the ingredients, except the sardines, into a bowl and mix together with some seasoning.","Pour into a baking dish, add the sardines and toss really well.","Cover and chill for a few hours.","Heat a BBQ or griddle pan until hot.","Cook the sardines for 4-5 minutes on each side or until really caramelised and charred.","Put onto a serving plate, drizzle with oil, sprinkle with a little more paprika and squeeze over the lemon wedges."],"ingredient_names":["sardines","olive oil","garlic","paprika","lemon","rosemary","red chilli"],"allergens":["fish"],"diet_flags":["pescatarian"]},{"source_id":"53042","title":"Portuguese prego with green piri-piri","category":"Beef","country":"Portugal","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/ewcikl1614348364.jpg","youtube_url":"https://www.youtube.com/watch?v=FbIKfcDEPLA","source_url":"https://www.olivemagazine.com/recipes/meat-and-poultry/portuguese-prego-with-green-piri-piri/","ingredients":[{"name":"Garlic","measure":"1 clove"},{"name":"Beef Fillet","measure":"2 small"},{"name":"Olive Oil","measure":"2 tbs"},{"name":"Vinegar","measure":"1 tbs"},{"name":"Parsley","measure":"Leaves"},{"name":"Ciabatta","measure":"2"},{"name":"Rocket","measure":"2 handfulls"},{"name":"Basil Leaves","measure":"Small bunch"},{"name":"Parsley","measure":"Small bunch"},{"name":"Jalapeno","measure":"1"},{"name":"Vinegar","measure":"1 tbs"},{"name":"Spring Onions","measure":"2 chopped"},{"name":"Garlic","measure":"1/2"},{"name":"Caster Sugar","measure":"1/2 tsp"}],"steps":["Rub the garlic over the steaks then put in a sandwich bag and tip in the olive oil, sherry vinegar and parsley stalks. Smoosh everything together, then use a rolling pin to bash the steaks a few times. Leave for 1-2 hours.","To make the sauce, put all the ingredients into a blender with 1 tbsp water and whizz until as smooth as possible. This will make more than you’ll need for the recipe but will keep for a week in an airtight jar.","Heat a griddle or frying pan to high. Brush away the garlic and parsley stalks from the steaks and season well. Sear the steaks for 2 minutes on each side then rest on a plate. Put the ciabatta halves onto the plate, toasted-side down, to soak up any juices.","Slice the steaks then stuff into the rolls with the green sauce and rocket."],"ingredient_names":["garlic","beef fillet","olive oil","vinegar","parsley","ciabatta","rocket","basil leaves","parsley","jalapeno","vinegar","spring onions","garlic","caster sugar"],"allergens":["gluten"],"diet_flags":[]},{"source_id":"53043","title":"Fish fofos","category":"Seafood","country":"Portugal","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/a15wsa1614349126.jpg","youtube_url":"https://www.youtube.com/watch?v=YXUZHK2PrV8","source_url":"https://www.olivemagazine.com/recipes/fish-and-seafood/fish-fofos/","ingredients":[{"name":"Haddock","measure":"600g"},{"name":"Potatoes","measure":"300g"},{"name":"Green Chilli","measure":"1 chopped"},{"name":"Coriander","measure":"3 tbs"},{"name":"Cumin Seeds","measure":"1 tsp"},{"name":"Pepper","measure":"1/2 tsp"},{"name":"Garlic","measure":"3 cloves"},{"name":"Ginger","measure":"2 pieces"},{"name":"Flour","measure":"2 tbs"},{"name":"Eggs","measure":"3"},{"name":"Breadcrumbs","measure":"75g"},{"name":"Vegetable Oil","measure":"For frying"}],"steps":["Put the fish into a lidded pan and pour over enough water to cover. Bring to a simmer and gently poach for 10 minutes over a low heat with the lid on. Drain and flake the fish.","Put the fish, potato, green chilli, coriander, cumin, black pepper, garlic and ginger in a large bowl. Season, add the rice flour, mix well and break in 1 egg. Stir the mixture and divide into 15, then form into small logs. Break the remaining eggs into a bowl and whisk lightly. Put the breadcrumbs into another bowl. Dip each fofo in the beaten egg followed by the breadcrumb mixture. Chill for 20 minutes.","Heat 1cm of oil in a large frying pan over a medium heat. Fry the fofos in batches for 2 minutes on each side, turning gently to get an even golden brown colour all over. Drain on kitchen paper and repeat with the remaining fofos.","For the onion salad, mix together the onion, coriander and lemon juice with a pinch of salt. Serve with the fofos and mango chutney."],"ingredient_names":["haddock","potatoes","green chilli","coriander","cumin seeds","pepper","garlic","ginger","flour","eggs","breadcrumbs","vegetable oil"],"allergens":["eggs","fish","gluten"],"diet_flags":["pescatarian"]},{"source_id":"53044","title":"Portuguese barbecued pork (Febras assadas)","category":"Pork","country":"Portugal","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/cybyue1614349443.jpg","youtube_url":"https://www.youtube.com/watch?v=tVpsZaejyYU","source_url":"https://www.olivemagazine.com/recipes/meat-and-poultry/febras-assadas-portuguese-barbecued-pork-served-with-lemon-and-mayo-on-chips/","ingredients":[{"name":"Pork","measure":"2"},{"name":"White Wine","measure":"200ml"},{"name":"Paprika","measure":"1/2 tsp"},{"name":"Lemon","measure":"2"},{"name":"Lemon Juice","measure":"1/2"},{"name":"Olive Oil","measure":"Dash"},{"name":"Mayonnaise","measure":"To serve"},{"name":"Potatoes","measure":"1 kg"},{"name":"Vegetable Oil","measure":"For frying"}],"steps":["Cut the tenderloins into 5 equal-size pieces leaving the tail ends a little longer. Take a clear plastic bag and slip one of the pieces in. Bash it into an escalope the size of a side-plate with a rolling pin and repeat with the remaining pieces.","Put the wine, paprika, some salt and pepper and the juice of ½ a lemon in a bowl and add the pork. Leave to marinate for 20-30 minutes, while you get your barbecue to the stage where the coals are glowing but there are no flames.","To make the chips, fill a basin with cool water and cut the potatoes into 3cm-thick chips. Soak them in the water for 5 minutes and then change the water. Leave for 5 more minutes. Drain and then pat dry on a towel or with kitchen paper.","Heat the oil in a deep fryer or a deep heavy-based pan with a lid to 130C and lower the chips into the oil (in batches). Blanch for 8-10 minutes. Remove from the oil and drain well. Place on a tray to cool. Reheat the oil to 180C (make sure it’s hot or your chips will be soggy) and lower the basket of chips into the oil (again, do this in batches). Leave to cook for 2 minutes and then give them a little shake. Cook for another minute or so until they are well coloured and crisp to the touch. Drain well for a few minutes, tip into a bowl and sprinkle with sea salt.","The pork will cook quickly so do it in 2 batches. Take the pieces out of the marinade, rub them with oil, and drop them onto the barbecue (you could also use a chargrill). Cook for 1 minute on each side – they may flare up as you do so. This should really be enough time as they will keep on cooking. Take them off the barbecue and pile onto a plate. Repeat with the remaining batch.","Serve by piling a plate with chips, drop the pork on top of each pile and pouring the juices from the plate over so the chips take up the flavours. Top with a spoon of mayonnaise and a wedge of lemon."],"ingredient_names":["pork","white wine","paprika","lemon","lemon juice","olive oil","mayonnaise","potatoes","vegetable oil"],"allergens":["eggs"],"diet_flags":[]},{"source_id":"53045","title":"Portuguese fish stew (Caldeirada de peixe)","category":"Seafood","country":"Portugal","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/do7zps1614349775.jpg","youtube_url":"https://www.youtube.com/watch?v=utv-GpSJypk","source_url":"https://www.olivemagazine.com/recipes/one-pots/portuguese-fish-stew-caldeirada-de-peixe/","ingredients":[{"name":"Onions","measure":"2 finely chopped"},{"name":"Red Pepper","measure":"1 Diced"},{"name":"Coriander","measure":"Small bunch"},{"name":"Red Chilli","measure":"1 small"},{"name":"Garlic","measure":"3 cloves"},{"name":"Dry White Wine","measure":"400ml"},{"name":"Saffron","measure":"Pinch"},{"name":"Bay Leaf","measure":"1"},{"name":"Potatoes","measure":"300g"},{"name":"Plum Tomatoes","measure":"400g"},{"name":"Cod","measure":"600g"},{"name":"Squid","measure":"300g"},{"name":"Tiger Prawns","measure":"8"},{"name":"Clams","measure":"500g"},{"name":"Mussels","measure":"500g"},{"name":"Baguette","measure":"1 sliced"}],"steps":["Heat a drizzle of oil in a large, deep-sided frying pan, and fry the onion and pepper on a medium heat until softened but not browned. Finely chop the coriander stalks (keep the leaves for later), and add to the pan with the chilli and chopped garlic. Fry for another few minutes. Add the wine, saffron and bay leaf and let it simmer until reduced by half.","Add the potatoes, tomatoes, and 300ml water and bring to a gentle boil. Break up the tomatoes with a spoon on the side of the pan and simmer for 20-25 minutes until the potatoes are just tender, and the tomatoes have broken down.","Season well, then gently push the fish into the sauce, and arrange the squid, prawns, clams and mussels on the surface. Put the lid on and cook for 6-8 minutes until the mussel and clam shells have opened, the prawns are cooked and the fish is flaky. Toast the bread, rub lightly with the halved garlic clove and drizzle with olive oil. Serve the stew scatted with chopped coriander leaves, and the toasts for dunking."],"ingredient_names":["onions","red pepper","coriander","red chilli","garlic","dry white wine","saffron","bay leaf","potatoes","plum tomatoes","cod","squid","tiger prawns","clams","mussels","baguette"],"allergens":["fish","gluten","shellfish"],"diet_flags":["pescatarian"]},{"source_id":"53047","title":"Moroccan Carrot Soup","category":"Vegetarian","country":"Morocco","tags":["Soup"],"image_url":"https://www.themealdb.com/images/media/meals/jcr46d1614763831.jpg","youtube_url":"https://www.youtube.com/watch?v=7tDWOpnIhok","source_url":"https://www.sanjeevkapoor.com/Recipe/Moroccan-Carrot-Soup.html","ingredients":[{"name":"Carrots","measure":"6 chopped"},{"name":"Onion","measure":"1 sliced"},{"name":"Garlic Clove","measure":"4"},{"name":"Cumin","measure":"1 tsp"},{"name":"Coriander","measure":"1/2 tsp"},{"name":"Olive Oil","measure":"1 tbs"},{"name":"Garam Masala","measure":"1/4 tsp"},{"name":"Lemon Juice","measure":"1 tsp"}],"steps":["Preheat oven to 180° C.","Combine carrots, onion, garlic, cumin seeds, coriander seeds, salt and olive oil in a bowl and mix well. Transfer on a baking tray.","Put the baking tray in preheated oven and roast for 10-12 minutes or till carrots soften. Remove from heat and cool.","Grind the baked carrot mixture along with some water to make a smooth paste and strain in a bowl.","Heat the carrot mixture in a non-stick pan. Add two cups of water and bring to a boil. Add garam masala powder and mix. Add salt and mix well.","Remove from heat, add lemon juice and mix well.","Serve hot."],"ingredient_names":["carrots","onion","garlic clove","cumin","coriander","olive oil","garam masala","lemon juice"],"allergens":[],"diet_flags":["pescatarian","vegan","vegetarian"]},{"source_id":"53048","title":"Mee goreng mamak","category":"Seafood","country":"Malaysia","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/xquakq1619787532.jpg","youtube_url":"https://www.youtube.com/watch?v=pOJEmDBgtSk","source_url":"https://www.nyonyacooking.com/recipes/mee-goreng-mamak~BkTLRjTuX","ingredients":[{"name":"Peanuts","measure":"50g"},{"name":"Chilli","measure":"15g"},{"name":"Prawns","measure":"10g"},{"name":"Oil","measure":"5 tbs"},{"name":"Water","measure":"750 ml"},{"name":"Tamarind Paste","measure":"1/2 tbs"},{"name":"Potatoes","measure":"250g"},{"name":"Red Onions","measure":"2"},{"name":"Garlic Clove","measure":"4"},{"name":"Cabbage","measure":"30g"},{"name":"Chinese Broccoli","measure":"30g"},{"name":"Tofu","measure":"1"},{"name":"Soy Sauce","measure":"1 tbs"},{"name":"Noodles","measure":"4"},{"name":"Egg","measure":"1"}],"steps":["Heat oil in a pan at medium heat. Then, add peanuts, dried chilies, dried shrimps and dhal. Fry the aromatics until fragrant. Remove from pan and leave aside.","Blend fried ingredients with tamarind paste and water until fine. Then, sauté the blended ingredients in oil heated over low heat. Continue cooking until the oil separates from the paste and turns a darker shade.","Skin and cut potatoes into small chunks and boil them in a pot of water until knife-tender. Once ready, remove them from the pot and leave aside. Discard water.","Slice onion and fried tofu, mince garlic, cut some cabbage and Chinese flowering cabbage (choi sam). Prepare prawn fritters and cut them. Boil noodles to soften them if bought dried. Also mix black soy sauce with water.","To fry one portion of mee goreng mamak, heat oil and add 1/4 of the following ingredients in this order: garlic, onion, paste. Sauté until fragrant. Optionally, add prawns.","Add in 1/4 amount of tofu, boiled potatoes, cabbage, Chinese flowering cabbage and prawn fritters. Sauté for another 30 seconds.","Add noodles to the wok. Add 3 tablespoons of dark soy sauce mixture. Mix evenly for the next 1 minute. Then, move the noodles to the side of the wok. Stir in an egg. Garnish with a slice of lime and slices of green chilies. To cook another plate of noodles, repeat from step 5 onwards."],"ingredient_names":["peanuts","chilli","prawns","oil","water","tamarind paste","potatoes","red onions","garlic clove","cabbage","chinese broccoli","tofu","soy sauce","noodles","egg"],"allergens":["eggs","gluten","peanuts","shellfish","soy"],"diet_flags":["pescatarian"]},{"source_id":"53050","title":"Ayam Percik","category":"Chicken","country":"Malaysia","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/020z181619788503.jpg","youtube_url":"https://www.youtube.com/watch?v=9ytR28QK6I8","source_url":"http://www.curiousnut.com/roasted-spiced-chicken-ayam-percik/","ingredients":[{"name":"Chicken Thighs","measure":"6"},{"name":"Challots","measure":"16"},{"name":"Ginger","measure":"1 1/2"},{"name":"Garlic Clove","measure":"6"},{"name":"Cayenne Pepper","measure":"8"},{"name":"Turmeric","measure":"2 tbs"},{"name":"Cumin","measure":"1 1/2"},{"name":"Coriander","measure":"1 1/2"},{"name":"Fennel","measure":"1 1/2"},{"name":"Tamarind Paste","measure":"2 tbs"},{"name":"Coconut Milk","measure":"1 can"},{"name":"Sugar","measure":"1 tsp"},{"name":"Water","measure":"1 cup"}],"steps":["In a blender, add the ingredients for the spice paste and blend until smooth.","Over medium heat, pour the spice paste in a skillet or pan and fry for 10 minutes until fragrant. Add water or oil 1 tablespoon at a time if the paste becomes too dry. Don't burn the paste. Lower the fire slightly if needed.","Add the cloves, cardamom, tamarind pulp, coconut milk, water, sugar and salt. Turn the heat up and bring the mixture to boil. Turn the heat to medium low and simmer for 10 minutes. Stir occasionally. It will reduce slightly. This is the marinade/sauce, so taste and adjust seasoning if necessary. Don't worry if it's slightly bitter. It will go away when roasting.","When the marinade/sauce has cooled, pour everything over the chicken and marinate overnight to two days.","Preheat the oven to 425 F.","Remove the chicken from the marinade. Spoon the marinade onto a greased (or aluminum lined) baking sheet. Lay the chicken on top of the sauce (make sure the chicken covers the sauce and the sauce isn't exposed or it'll burn) and spread the remaining marinade on the chicken. Roast for 35-45 minutes or until internal temp of the thickest part of chicken is at least 175 F.","Let chicken rest for 5 minutes. Brush the chicken with some of the oil. Serve chicken with the sauce over steamed rice (or coconut rice)."],"ingredient_names":["chicken thighs","challots","ginger","garlic clove","cayenne pepper","turmeric","cumin","coriander","fennel","tamarind paste","coconut milk","sugar","water"],"allergens":[],"diet_flags":[]},{"source_id":"53051","title":"Nasi lemak","category":"Seafood","country":"Malaysia","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/wai9bw1619788844.jpg","youtube_url":"https://www.youtube.com/watch?v=IUIs4C86Ilo","source_url":"https://www.allrecipes.com/recipe/78938/malaysian-nasi-lemak/","ingredients":[{"name":"Coconut Milk","measure":"2 cups"},{"name":"Water","measure":"2 cups"},{"name":"Ginger Paste","measure":"1/4 tsp"},{"name":"Ginger","measure":"1"},{"name":"Bay Leaf","measure":"1"},{"name":"Rice","measure":"2 cups"},{"name":"Eggs","measure":"4"},{"name":"Cucumber","measure":"1"},{"name":"Peanuts","measure":"1 cup"},{"name":"Anchovy Fillet","measure":"4 oz"},{"name":"Vegetable Oil","measure":"2 tbs"},{"name":"Onion","measure":"1"},{"name":"Garlic","measure":"3 cloves"},{"name":"Shallots","measure":"3"},{"name":"Chilli Powder","measure":"2 tsp"},{"name":"Anchovy Fillet","measure":"4 oz"},{"name":"Sugar","measure":"3 tbs"},{"name":"Tamarind Paste","measure":"1/3 cup"}],"steps":["In a medium saucepan over medium heat, stir together coconut milk, water, ground ginger, ginger root, salt, bay leaf, and rice. Cover, and bring to a boil. Reduce heat, and simmer for 20 to 30 minutes, or until done.","Place eggs in a saucepan, and cover with cold water. Bring water to a boil, and immediately remove from heat. Cover, and let eggs stand in hot water for 10 to 12 minutes. Remove eggs from hot water, cool, peel and slice in half. Slice cucumber.","Meanwhile, in a large skillet or wok, heat 1 cup vegetable oil over medium-high heat. Stir in peanuts and cook briefly, until lightly browned. Remove peanuts with a slotted spoon and place on paper towels to soak up excess grease. Return skillet to stove. Stir in the contents of one package anchovies; cook briefly, turning, until crisp. Remove with a slotted spoon and place on paper towels. Discard oil. Wipe out skillet.","Heat 2 tablespoons oil in the skillet. Stir in the onion, garlic, and shallots; cook until fragrant, about 1 or 2 minutes. Mix in the chile paste, and cook for 10 minutes, stirring occasionally. If the chile paste is too dry, add a small amount of water. Stir in remaining anchovies; cook for 5 minutes. Stir in salt, sugar, and tamarind juice; simmer until sauce is thick, about 5 minutes.","Serve the onion and garlic sauce over the warm rice, and top with peanuts, fried anchovies, cucumbers, and eggs."],"ingredient_names":["coconut milk","water","ginger paste","ginger","bay leaf","rice","eggs","cucumber","peanuts","anchovy fillet","vegetable oil","onion","garlic","shallots","chilli powder","anchovy fillet","sugar","tamarind paste"],"allergens":["eggs","fish","peanuts"],"diet_flags":["pescatarian"]},{"source_id":"53052","title":"Roti john","category":"Beef","country":"Malaysia","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/hx335q1619789561.jpg","youtube_url":"https://www.youtube.com/watch?v=cl4YH8wblRs","source_url":"https://www.196flavors.com/malaysia-roti-john/","ingredients":[{"name":"Minced Beef","measure":"1/4 lb"},{"name":"Onion","measure":"1"},{"name":"Eggs","measure":"3"},{"name":"Chilli","measure":"1 tbs"},{"name":"Baguette","measure":"1/2"},{"name":"Salt","measure":"To taste"},{"name":"Pepper","measure":"To taste"},{"name":"Mayonnaise","measure":"Top"}],"steps":["Mix all the ingredients in a bowl.","Heat a pan or griddle with a little vegetable oil.","Pour the mixture onto the pan and place a piece of open-faced baguette on top.","Press on the bread with a spatula and grill for 2 minutes.","Turn the bread over to make it a little crispy.","Remove from pan and cut the bread into small portions.","Add mayonnaise and/or Sambal before cutting the sandwich (optional)."],"ingredient_names":["minced beef","onion","eggs","chilli","baguette","salt","pepper","mayonnaise"],"allergens":["eggs","gluten"],"diet_flags":[]},{"source_id":"53053","title":"Beef Rendang","category":"Beef","country":"Malaysia","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/bc8v651619789840.jpg","youtube_url":"https://www.youtube.com/watch?v=Ot-dmfBaZrA","source_url":"https://rasamalaysia.com/beef-rendang-recipe-rendang-daging/","ingredients":[{"name":"Beef","measure":"1lb"},{"name":"Vegetable Oil","measure":"5 tbs"},{"name":"Cinnamon Stick","measure":"1"},{"name":"Cloves","measure":"3"},{"name":"Star Anise","measure":"3"},{"name":"Cardamom","measure":"3"},{"name":"Coconut Cream","measure":"1 cup"},{"name":"Water","measure":"1 cup"},{"name":"Tamarind Paste","measure":"2 tbs"},{"name":"Lime","measure":"6"},{"name":"Sugar","measure":"1 tbs"},{"name":"Challots","measure":"5"}],"steps":["Chop the spice paste ingredients and then blend it in a food processor until fine.","Heat the oil in a stew pot, add the spice paste, cinnamon, cloves, star anise, and cardamom and stir-fry until aromatic. Add the beef and the pounded lemongrass and stir for 1 minute. Add the coconut milk, tamarind juice, water, and simmer on medium heat, stirring frequently until the meat is almost cooked. Add the kaffir lime leaves, kerisik (toasted coconut), sugar or palm sugar, stirring to blend well with the meat.","Lower the heat to low, cover the lid, and simmer for 1 to 1 1/2 hours or until the meat is really tender and the gravy has dried up. Add more salt and sugar to taste. Serve immediately with steamed rice and save some for overnight."],"ingredient_names":["beef","vegetable oil","cinnamon stick","cloves","star anise","cardamom","coconut cream","water","tamarind paste","lime","sugar","challots"],"allergens":[],"diet_flags":[]},{"source_id":"53055","title":"Cevapi Sausages","category":"Beef","country":"Croatia","tags":["Sausages"],"image_url":"https://www.themealdb.com/images/media/meals/vc08jn1628769553.jpg","youtube_url":"https://www.youtube.com/watch?v=_MpSxSgS7f8","source_url":"https://whereismyspoon.co/cevapi-or-cevapcici-recipe-grilled-sausages-croatian-food/","ingredients":[{"name":"Minced Beef","measure":"500g"},{"name":"Minced Pork","measure":"250g"},{"name":"Onion","measure":"1"},{"name":"Garlic","measure":"4 cloves"},{"name":"Parsley","measure":"3 tblsp chopped"},{"name":"Paprika","measure":"1 tbs"},{"name":"Baking Powder","measure":"3/4 teaspoon"},{"name":"Breadcrumbs","measure":"2 tbs"},{"name":"Water","measure":"3 tbs"},{"name":"Vegetable Stock Cube","measure":"1"},{"name":"Salt","measure":"1 tsp"},{"name":"Pepper","measure":"1 tsp"}],"steps":["Place the ground meat in a bowl. Chop the onion very finely and grate the garlic cloves. Add to the bowl. Add the chopped parsley, all sorts of paprika, baking soda, dried breadcrumbs, water, Vegeta, salt, and pepper.","Mix well with the hand mixer fitted with the dough hooks. Cover the bowl with cling film/ plastic foil and leave to rest for 1 or 2 hours in the refrigerator.","Take portions of the meat mixture, about 50-55 g/ 1.7-1.9 oz/ ¼ cup portions, and form the cevapi. The rolls should be about as thick as your thumb and about 7-10 cm/ 3-4 inches long. I had 18 sausages. The recipe can be easily doubled.","Grill the cevapcici on the hot grill pan or on the barbecue for about 12-14 minutes, turning them several times in between, or until brown and cooked through. I checked by cutting one in the middle and then grilling the following batches for the same period of time.","Serve hot as suggested above. The cevapcici can be reheated in the oven at 180 degrees Celsius/ 350 degrees Fahrenheit for about 10 minutes or until heated through. Check one, if it is not hot enough, give the sausages a few more minutes."],"ingredient_names":["minced beef","minced pork","onion","garlic","parsley","paprika","baking powder","breadcrumbs","water","vegetable stock cube","salt","pepper"],"allergens":["gluten"],"diet_flags":[]},{"source_id":"53056","title":"Croatian lamb peka","category":"Beef","country":"Croatia","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/pn59o51628769837.jpg","youtube_url":"https://www.youtube.com/watch?v=K0ipnz4fwJI","source_url":"https://flawlessfood.co.uk/croatian-lamb-peka/","ingredients":[{"name":"Potatoes","measure":"600g"},{"name":"Courgettes","measure":"1 chopped"},{"name":"Carrots","measure":"1 chopped"},{"name":"Green Pepper","measure":"1 chopped"},{"name":"Aubergine","measure":"1 small"},{"name":"Onion","measure":"1 Large Chopped"},{"name":"Lamb Shoulder","measure":"800g"},{"name":"Garlic Sauce","measure":"1 tbs"},{"name":"Tomato Puree","measure":"1 tbs"},{"name":"Olive Oil","measure":"80 ml"},{"name":"Thyme","measure":"Sprinking"},{"name":"White Wine","measure":"250ml"},{"name":"Pepper","measure":"Pinch"}],"steps":["Preheat oven to 200°C fan / 220°C / 425°F / Gas mark 7","If you have not bought diced lamb, cut your lamb shoulder or leg into large chunks and place to one side.","Chunks of chopped lamb of a red chopping board","Make oil marinade -","Mix 80ml of olive oil in a bowl with garlic puree, sundried tomato puree ,black pepper and salt.","olive oil, gia sundried tomato puree and gia garlic puree and black pepper mixed together in a silver bowl to make Croatian peka","Add potatoes and vegetables into a large lidded casserole dish.","Chopped up vegetables which consist of chopped up red onion, courgette, potatoes red peppers in a cast iron pan","Place diced lamb on top of the vegetables, pour the marinade and wine over the top.","Chunks of lamb covered in in a sundried tomato oil sauce which is on top of chopped red onion, aubergine, courgette and potatoes in a cast iron pan","Add the rosemary, thyme and sage, trying to keep the herbs on top.","So you can easily remove the herb stalks once cooked.","Chunks of lamb coated in a sundried tomato oil sauce and covered with thyme, rosemary and sage which is on top of chopped red onion, aubergine, courgette and potatoes in a cast iron pan","Place lid on the casserole dish and cook for 1hr 30 minute","If you do not have a lid cover very well with kitchen foil","Cast iron dish with lid on in the oven","Take the lid off, remove any thick herb stems. Stir in 2 tbsp of olive oil.","Cook for a further 20-30 mins.","Cooked Croatian Lamb Peka in a cast iron pan in the oven","Serve with fresh homemade bread to dip into the juices."],"ingredient_names":["potatoes","courgettes","carrots","green pepper","aubergine","onion","lamb shoulder","garlic sauce","tomato puree","olive oil","thyme","white wine","pepper"],"allergens":[],"diet_flags":[]},{"source_id":"53057","title":"Traditional Croatian Goulash","category":"Beef","country":"Croatia","tags":["Soup"],"image_url":"https://www.themealdb.com/images/media/meals/n1hcou1628770088.jpg","youtube_url":"https://www.youtube.com/watch?v=ipEz5u2T7KM","source_url":"https://www.chasingthedonkey.com/croatian-recipes-traditional-croatian-goulash/","ingredients":[{"name":"Beef","measure":"500g"},{"name":"Onions","measure":"2 chopped"},{"name":"Carrots","measure":"2 chopped"},{"name":"Garlic","measure":"2 cloves"},{"name":"Bay Leaf","measure":"2"},{"name":"Red Wine","measure":"200ml"},{"name":"Water","measure":"2 Litres"},{"name":"Mustard","measure":"3 tbs"},{"name":"Salt","measure":"1tbsp"},{"name":"Pepper","measure":"1/2 tsp"},{"name":"Paprika","measure":"1/2 tsp"},{"name":"Vegetable Oil","measure":"2 tbs"}],"steps":["Clean the meat from the veins if there are some and cut it into smaller pieces, 3 × 3 cm. Marinate the meat in the mustard and spices and let it sit in the refrigerator for one hour","Heat one tablespoon of pork fat or vegetable oil in a pot and fry the meat on all sides until it gets browned. Once the meat is cooked, transfer it to a plate and add another tablespoon of fat to the pot","Cut the onions very fine, peel the carrots and shred it using a grater. Cook the onions and carrots over low heat for 15 minutes. You can salt the vegetables a little to make them soften faster","Once the vegetables have browned and become slightly mushy, add the meat and bay leaves and garlic. Pour over with wine and simmer for 10-15 minutes to allow the alcohol to evaporate. Now is the right time to add 2/3 the amount of liquid","Cover the pot and cook over low heat for an hour, stirring occasionally. After the first hour, pour over the rest of the water or stock and cook for another 30-45 minutes","Allow the stew to cool slightly and serve it with a sprinkle of chopped parsley and few slices of fresh hot pepper if you like to spice it up a bit","Slice ​​some fresh bread, season the salad and simply enjoying these wonderful flavors"],"ingredient_names":["beef","onions","carrots","garlic","bay leaf","red wine","water","mustard","salt","pepper","paprika","vegetable oil"],"allergens":[],"diet_flags":[]},{"source_id":"53058","title":"Croatian Bean Stew","category":"Beef","country":"Croatia","tags":["Warming","Soup","Beans"],"image_url":"https://www.themealdb.com/images/media/meals/tnwy8m1628770384.jpg","youtube_url":"https://www.youtube.com/watch?v=mrjnQal3S1A","source_url":"https://www.visit-croatia.co.uk/croatian-cuisine/croatian-recipes/","ingredients":[{"name":"Cannellini Beans","measure":"2 cans"},{"name":"Vegetable Oil","measure":"3 tbs"},{"name":"Tomatoes","measure":"2 cups"},{"name":"Challots","measure":"5"},{"name":"Garlic","measure":"2 cloves"},{"name":"Parsley","measure":"Pinch"},{"name":"Chorizo","measure":"1/2 kg chopped"}],"steps":["Heat the oil in a pan.","Add the chopped vegetables and sauté until tender.","Take a pot, empty the beans together with the vegetables into it, put the sausages inside and cook for further 20 minutes on a low heat.","Or, put it in an oven and bake it at a temperature of 180ºC/350ºF for 30 minutes.","This dish is even better reheated the next day."],"ingredient_names":["cannellini beans","vegetable oil","tomatoes","challots","garlic","parsley","chorizo"],"allergens":[],"diet_flags":[]},{"source_id":"53063","title":"Chivito uruguayo","category":"Beef","country":"Uruguay","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/n7qnkb1630444129.jpg","youtube_url":"https://www.youtube.com/watch?v=0PXbbL1QdaA&ab_channel=D%C3%ADadeCocina","source_url":"https://cookpad.com/uy/recetas/116102-chivito-uruguayo","ingredients":[{"name":"Beef Brisket","measure":"2"},{"name":"Bread","measure":"2"},{"name":"Lettuce","measure":"1"},{"name":"Tomato","measure":"1"},{"name":"Ham","measure":"100g"},{"name":"Mozzarella","measure":"100g"},{"name":"Bacon","measure":"100g"},{"name":"Egg","measure":"1"},{"name":"Onion","measure":"1"},{"name":"Pepper","measure":"1"}],"steps":["Crush the meat so that it is finite and we put it on a griddle to brown. Put the eggs, bacon and ham to fry.","Cut the bread in half, put the beef brisket, the fried eggs, the bacon, the ham, the mozzarella, the tomato and the lettuce. Cover with the other half of the bread and serve."],"ingredient_names":["beef brisket","bread","lettuce","tomato","ham","mozzarella","bacon","egg","onion","pepper"],"allergens":["dairy","eggs","gluten"],"diet_flags":[]},{"source_id":"53064","title":"Fettuccine Alfredo","category":"Pasta","country":"Italy","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/0jv5gx1661040802.jpg","youtube_url":"https://www.youtube.com/watch?v=LPPcNPdq_j4","source_url":"https://www.delish.com/cooking/recipe-ideas/a55312/best-homemade-fettuccine-alfredo-recipe/","ingredients":[{"name":"Fettuccine","measure":"1 lb"},{"name":"Heavy Cream","measure":"1/2 cup"},{"name":"Butter","measure":"1/2 cup"},{"name":"Parmesan","measure":"1/2 cup"},{"name":"Parsley","measure":"2 tbsp"},{"name":"Black Pepper","measure":""}],"steps":["Cook pasta according to package instructions in a large pot of boiling water and salt.","Add heavy cream and butter to a large skillet over medium heat until the cream bubbles and the butter melts.","Whisk in parmesan and add seasoning (salt and black pepper).","Let the sauce thicken slightly and then add the pasta and toss until coated in sauce.","Garnish with parsley, and it's ready."],"ingredient_names":["fettuccine","heavy cream","butter","parmesan","parsley","black pepper"],"allergens":["dairy","gluten"],"diet_flags":["pescatarian","vegetarian"]},{"source_id":"53065","title":"Sushi","category":"Seafood","country":"Japan","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/g046bb1663960946.jpg","youtube_url":"https://www.youtube.com/watch?v=ub68OxEypaY","source_url":"https://www.bbcgoodfood.com/recipes/simple-sushi","ingredients":[{"name":"Sushi Rice","measure":"300ml"},{"name":"Rice wine","measure":"100ml"},{"name":"Caster Sugar","measure":"2 tbs"},{"name":"Mayonnaise","measure":"3 tbs"},{"name":"Rice wine","measure":"1 tbs"},{"name":"Soy Sauce","measure":"1 tbs"},{"name":"Cucumber","measure":"1"}],"steps":["TO MAKE SUSHI ROLLS: Pat out some rice. Lay a nori sheet on the mat, shiny-side down. Dip your hands in the vinegared water, then pat handfuls of rice on top in a 1cm thick layer, leaving the furthest edge from you clear.","Spread over some Japanese mayonnaise. Use a spoon to spread out a thin layer of mayonnaise down the middle of the rice.","Add the filling. Get your child to top the mayonnaise with a line of their favourite fillings – here we’ve used tuna and cucumber.","Roll it up. Lift the edge of the mat over the rice, applying a little pressure to keep everything in a tight roll.","Stick down the sides like a stamp. When you get to the edge without any rice, brush with a little water and continue to roll into a tight roll.","Wrap in cling film. Remove the mat and roll tightly in cling film before a grown-up cuts the sushi into thick slices, then unravel the cling film.","TO MAKE PRESSED SUSHI: Layer over some smoked salmon. Line a loaf tin with cling film, then place a thin layer of smoked salmon inside on top of the cling film.","Cover with rice and press down. Press about 3cm of rice over the fish, fold the cling film over and press down as much as you can, using another tin if you have one.","Tip it out like a sandcastle. Turn block of sushi onto a chopping board. Get a grown-up to cut into fingers, then remove the cling film.","TO MAKE SUSHI BALLS: Choose your topping. Get a small square of cling film and place a topping, like half a prawn or a small piece of smoked salmon, on it. Use damp hands to roll walnut-sized balls of rice and place on the topping.","Make into tight balls. Bring the corners of the cling film together and tighten into balls by twisting it up, then unwrap and serve."],"ingredient_names":["sushi rice","rice wine","caster sugar","mayonnaise","rice wine","soy sauce","cucumber"],"allergens":["eggs","fish","gluten","shellfish","soy"],"diet_flags":["pescatarian"]},{"source_id":"53067","title":"Stuffed Bell Peppers with Quinoa and Black Beans","category":"Vegetarian","country":"Mexico","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/b66myb1683207208.jpg","youtube_url":null,"source_url":null,"ingredients":[{"name":"Green Pepper","measure":"4 whole"},{"name":"Olive Oil","measure":"1 tablespoon"},{"name":"Onion","measure":"1 small finely diced"},{"name":"Garlic","measure":"2 cloves minced"},{"name":"Quinoa","measure":"1 cups"},{"name":"Black Beans","measure":"1 can"},{"name":"Sweetcorn","measure":"1 cup"},{"name":"Diced Tomatoes","measure":"1 can"},{"name":"Cumin","measure":"1 teaspoon"},{"name":"Chili Powder","measure":"½ tsp"},{"name":"Smoked Paprika","measure":"½ tsp"},{"name":"Salt","measure":"To taste"},{"name":"Pepper","measure":"To taste"},{"name":"Shredded Mexican Cheese","measure":"1 1/2 cup"},{"name":"Cilantro","measure":"Chopped"}],"steps":["Preheat your oven to 375°F (190°C). Lightly grease a 9x13-inch baking dish or a similar-sized casserole dish.","Place the bell pepper halves in the prepared baking dish, cut side up. Bake for 15-20 minutes, or until slightly softened.","While the bell peppers are baking, prepare the filling. In a large skillet, heat the olive oil over medium heat. Add the chopped onion, and cook for 3-4 minutes, until softened. Add the garlic, and cook for another 1 minute, until fragrant.","Stir in the cooked quinoa, black beans, corn, diced tomatoes, ground cumin, chili powder, smoked paprika, salt, and pepper. Cook for 5-7 minutes, until heated through. Remove the skillet from heat, and stir in 1 cup of the shredded cheese, if using.","Remove the bell peppers from the oven, and carefully stuff each pepper half with the quinoa and black bean mixture. Top the stuffed peppers with the remaining 1/2 cup of shredded cheese, if using.","Return the stuffed peppers to the oven, and bake for another 15-20 minutes, until the cheese is melted and the peppers are tender.","Remove from the oven, and allow the stuffed peppers to cool for 5 minutes before serving. Garnish with fresh chopped cilantro."],"ingredient_names":["green pepper","olive oil","onion","garlic","quinoa","black beans","sweetcorn","diced tomatoes","cumin","chili powder","smoked paprika","salt","pepper","shredded mexican cheese","cilantro"],"allergens":["dairy"],"diet_flags":["pescatarian","vegetarian"]},{"source_id":"53068","title":"Beef Mechado","category":"Beef","country":"Philippines","tags":["Stew","Warming"],"image_url":"https://www.themealdb.com/images/media/meals/cgl60b1683206581.jpg","youtube_url":"https://www.youtube.com/watch?v=jxW3Lj8VjyE","source_url":"https://panlasangpinoy.com/filipino-pinoy-food-tomato-sauce-beef-mechado-recipe/","ingredients":[{"name":"Garlic","measure":"3 cloves"},{"name":"Onion","measure":"1 sliced"},{"name":"Beef","measure":"2 Lbs"},{"name":"Tomato Puree","measure":"8 ounces"},{"name":"Water","measure":"1 cup"},{"name":"Olive Oil","measure":"3 tbs"},{"name":"Lemon","measure":"1 Slice"},{"name":"Potatoes","measure":"1 large"},{"name":"Soy Sauce","measure":"1/4 cup"},{"name":"Black Pepper","measure":"1/2 tsp"},{"name":"Bay Leaves","measure":"2"},{"name":"Salt","measure":"To taste"}],"steps":["Make the beef tenderloin marinade by combining soy sauce, vinegar, ginger, garlic, sesame oil, olive oil, sugar, salt, and ground black pepper in a large bowl. Mix well.","Add the cubed beef tenderloin to the bowl with the beef tenderloin marinade. Gently toss to coat the beef. Let it stay for 1 hour.","Using a metal or bamboo skewer, assemble the beef kebob by skewering the vegetables and marinated beef tenderloin.","Heat-up the grill and start grilling the beef kebobs for 3 minutes per side. This will give you a medium beef that is juicy and tender on the inside. Add more time if you want your beef well done, but it will be less tender.","Transfer to a serving plate. Serve with Saffron rice.","Share and enjoy!"],"ingredient_names":["garlic","onion","beef","tomato puree","water","olive oil","lemon","potatoes","soy sauce","black pepper","bay leaves","salt"],"allergens":["gluten","soy"],"diet_flags":[]},{"source_id":"53069","title":"Bistek","category":"Beef","country":"Philippines","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/4pqimk1683207418.jpg","youtube_url":"https://www.youtube.com/watch?v=xOQON5_S7as","source_url":"https://panlasangpinoy.com/bistek-tagalog-beefsteak-recipe/","ingredients":[{"name":"Beef","measure":"1 lb"},{"name":"Soy Sauce","measure":"5 tablespoons"},{"name":"Lemon","measure":"1"},{"name":"Garlic","measure":"3 cloves"},{"name":"Onion","measure":"3 parts"},{"name":"Olive Oil","measure":"4 tbs"},{"name":"Water","measure":"1 cup"},{"name":"Salt","measure":"1 pinch"}],"steps":["Marinate beef in soy sauce, lemon (or calamansi), and ground black pepper for at least 1 hour. Note: marinate overnight for best result","Heat the cooking oil in a pan then pan-fry half of the onions until the texture becomes soft. Set aside","Drain the marinade from the beef. Set it aside. Pan-fry the beef on the same pan where the onions were fried for 1 minute per side. Remove from the pan. Set aside","Add more oil if needed. Saute garlic and remaining raw onions until onion softens.","Pour the remaining marinade and water. Bring to a boil.","Add beef. Cover the pan and simmer until the meat is tender. Note: Add water as needed.","Season with ground black pepper and salt as needed. Top with pan-fried onions.","Transfer to a serving plate. Serve hot. Share and Enjoy!"],"ingredient_names":["beef","soy sauce","lemon","garlic","onion","olive oil","water","salt"],"allergens":["gluten","soy"],"diet_flags":[]},{"source_id":"53070","title":"Beef Caldereta","category":"Beef","country":"Philippines","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/41cxjh1683207682.jpg","youtube_url":"https://www.youtube.com/watch?v=yI7hTz0ft5k","source_url":"https://www.kawalingpinoy.com/beef-caldereta/","ingredients":[{"name":"Beef","measure":"2kg cut cubes"},{"name":"Beef Stock","measure":"1"},{"name":"Soy Sauce","measure":"1 tbs"},{"name":"Water","measure":"2 cups"},{"name":"Green Pepper","measure":"1 sliced"},{"name":"Red Pepper","measure":"1 sliced"},{"name":"Potatoes","measure":"1 sliced"},{"name":"Carrots","measure":"1 sliced"},{"name":"Tomato Puree","measure":"8 ounces"},{"name":"Peanut Butter","measure":"3  tablespoons"},{"name":"Chilli Powder","measure":"5"},{"name":"Onion","measure":"1 chopped"},{"name":"Garlic","measure":"5 cloves"},{"name":"Olive Oil","measure":"3 tbs"}],"steps":["Heat oil in a cooking pot. Saute onion and garlic until onion softens","Add beef. Saute until the outer part turns light brown.","Add soy sauce. Pour tomato sauce and water. Let boil.","Add Knorr Beef Cube. Cover the pressure cooker. Cook for 30 minutes.","Pan-fry carrot and potato until it browns. Set aside.","Add chili pepper, liver spread and peanut butter. Stir.","Add bell peppers, fried potato and carrot. Cover the pot. Continue cooking for 5 to 7 minutes.","Season with salt and ground black pepper. Serve."],"ingredient_names":["beef","beef stock","soy sauce","water","green pepper","red pepper","potatoes","carrots","tomato puree","peanut butter","chilli powder","onion","garlic","olive oil"],"allergens":["gluten","peanuts","soy"],"diet_flags":[]},{"source_id":"53071","title":"Beef Asado","category":"Beef","country":"Philippines","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/pkopc31683207947.jpg","youtube_url":"https://www.youtube.com/watch?v=lNlK8DVhXXA","source_url":"https://panlasangpinoy.com/beef-asado/","ingredients":[{"name":"Beef","measure":"1.5kg"},{"name":"Beef Stock Concentrate","measure":"1"},{"name":"Tomato Puree","measure":"8 ounces"},{"name":"Water","measure":"3 cups"},{"name":"Soy Sauce","measure":"6 tablespoons"},{"name":"White Wine Vinegar","measure":"1 tbs"},{"name":"Pepper","measure":"2 tbs"},{"name":"Bay Leaf","measure":"4"},{"name":"Lemon","measure":"1/2"},{"name":"Tomato Sauce","measure":"2 tbs"},{"name":"Butter","measure":"3 tbs"},{"name":"Olive Oil","measure":"1/2 cup"},{"name":"Onion","measure":"1 chopped"},{"name":"Garlic","measure":"4 cloves"}],"steps":["Combine beef, crushed peppercorn, soy sauce, vinegar, dried bay leaves, lemon, and tomato sauce. Mix well. Marinate beef for at least 30 minutes.","Put the marinated beef in a cooking pot along with remaining marinade. Add water. Let boil.","Add Knorr Beef Cube. Stir. Cover the pot and cook for 40 minutes in low heat.","Turn the beef over. Add tomato paste. Continue cooking until beef tenderizes. Set aside.","Heat oil in a pan. Fry the potato until it browns. Turn over and continue frying the opposite side. Remove from the pan and place on a clean plate. Do the same with the carrots.","Save 3 tablespoons of cooking oil from the pan where the potato was fried. Saute onion and garlic until onion softens.","Pour-in the sauce from the beef stew. Let boil. Add the beef. Cook for 2 minutes.","Add butter and let it melt. Continue cooking until the sauce reduces to half."],"ingredient_names":["beef","beef stock concentrate","tomato puree","water","soy sauce","white wine vinegar","pepper","bay leaf","lemon","tomato sauce","butter","olive oil","onion","garlic"],"allergens":["dairy","gluten","soy"],"diet_flags":[]},{"source_id":"53072","title":"Crispy Eggplant","category":"Vegetarian","country":"Philippines","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/c7lzrl1683208757.jpg","youtube_url":"https://www.youtube.com/watch?v=4mINk5d2hto","source_url":"https://yummyfood.ph/recipe/crispiest-fried-eggplant/","ingredients":[{"name":"Egg Plants","measure":"1 large"},{"name":"Breadcrumbs","measure":"1 cup"},{"name":"Sesame Seed","measure":"50g"},{"name":"Eggs","measure":"2"},{"name":"Salt","measure":"To taste"},{"name":"Pepper","measure":"To taste"},{"name":"Vegetable Oil","measure":"For frying"}],"steps":["Slice eggplant into 1 cm (0.4-inch) slices. Place them in a bowl and sprinkle them with salt. allow them to sit for 30 minutes to render some of their liquid and bitterness.","After 30 minutes wash eggplant slices from salt and pat dry with a kitchen towel.","In a large bowl/plate place breadcrumbs and sesame seeds. In another bowl beat 2 eggs with pinch salt and pepper.","Heal oil in a large skillet over high heat.","Dip eggplant slices in egg, then in crumbs, and place in hot oil. Fry 2 to 3 minutes on each side, or until golden brown. Drain on a paper towel."],"ingredient_names":["egg plants","breadcrumbs","sesame seed","eggs","salt","pepper","vegetable oil"],"allergens":["eggs","gluten","sesame"],"diet_flags":["pescatarian","vegetarian"]},{"source_id":"53073","title":"Eggplant Adobo","category":"Vegetarian","country":"Philippines","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/y7h0lq1683208991.jpg","youtube_url":"https://www.youtube.com/watch?v=pKXACYjwMns","source_url":"https://salu-salo.com/eggplant-adobo/","ingredients":[{"name":"Egg Plants","measure":"1 lb"},{"name":"Sugar","measure":"2 tbs"},{"name":"Salt","measure":"1 tsp"},{"name":"Pepper","measure":"1 tsp"},{"name":"Garlic","measure":"1 whole"},{"name":"Olive Oil","measure":"3 tbs"},{"name":"Ground Pork","measure":"4 oz"},{"name":"Rice Vinegar","measure":"3 tbs"},{"name":"Soy Sauce","measure":"2 tbs"},{"name":"Bay Leaf","measure":"2"}],"steps":["Slice 1 lb. small Japanese or Italian eggplant (about 3) into quarters lengthwise, then cut crosswise into 2\"-wide pieces. Place in a medium bowl. Add 1 Tbsp. sugar, 1 tsp. Diamond Crystal or ½ tsp. Morton kosher salt, and ½ tsp. freshly ground black pepper. Toss to evenly coat eggplant and let sit at room temperature at least 20 minutes and up to 2 hours.","Peel and thinly slice 8 garlic cloves. Add 3 Tbsp. vegetable oil and half of garlic to a medium Dutch oven or other heavy pot. Cook over medium-high heat, stirring constantly with a wooden spoon, until light golden and crisp, about 5 minutes. Using a slotted spoon, transfer garlic chips to a plate; season lightly with salt.","Place 4 oz. ground pork in same pot and break up into small pieces with wooden spoon. Season with ¼ tsp. Diamond Crystal or Morton kosher salt and cook, undisturbed, until deeply browned underneath, about 5 minutes. Using a slotted spoon, transfer to another plate, leaving fat behind in the pot.","Place eggplant on a clean kitchen towel and blot away any moisture the salt has drawn out.","Working in batches and adding more oil if needed, cook eggplant in the same pot until lightly browned, about 3 minutes per side. Transfer to a plate with pork.","Pour 1½ cups of water into the pot and scrape up browned bits from the bottom with a wooden spoon. Add remaining garlic, 3 Tbsp. coconut vinegar or unseasoned rice vinegar, 2 Tbsp. soy sauce, 2 bay leaves, 1 tsp. freshly ground black pepper, and remaining 1 Tbsp. sugar. Bring to a simmer, then return pork and eggplant to pot. Reduce heat to medium-low, partially cover, and simmer until eggplant is tender and silky and sauce is reduced by half, 20–25 minutes. Taste and season with more salt and pepper and add a little more sugar if needed.","Top with garlic chips and serve with cooked white rice."],"ingredient_names":["egg plants","sugar","salt","pepper","garlic","olive oil","ground pork","rice vinegar","soy sauce","bay leaf"],"allergens":["eggs","gluten","soy"],"diet_flags":[]},{"source_id":"53074","title":"Grilled eggplant with coconut milk","category":"Vegetarian","country":"Philippines","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/bopa2i1683209167.jpg","youtube_url":"https://www.youtube.com/watch?v=ourC5IhljB4","source_url":"https://simplybakings.com/grilled-eggplant-with-coconut-milk/","ingredients":[{"name":"Egg Plants","measure":"6"},{"name":"Coconut Milk","measure":"1 can"},{"name":"Lemon Juice","measure":"1 tbs"},{"name":"Salt","measure":"1 tsp"},{"name":"Red Pepper Flakes","measure":"To taste"},{"name":"Onions","measure":"4 Sticks"}],"steps":[".  Prepare the eggplants for grilling by pricking them all over with a fork.  This is so it won’t burst during the grilling process as the natural water in it heats up.","Grill the eggplants, turning them over frequently to ensure even cooking.  Grill until the skins are dark brown, even black and the eggplant is soft when you touch it.","Soak the grilled eggplant in a bowl of water to cool it down.  Peel the skin off the eggplant.  Place the whole eggplants in a shallow dish (my mom actually cuts the eggplant into small, bite-sized pieces).","In a small mixing bowl, mix together the coconut milk or cream, lemon powder, salt and hot pepper.  Mix until the lemon powder and salt dissolve.  Taste, then adjust the amount of lemon powder, salt and hot pepper to your liking.  Pour the mixture over the eggplant.  Sprinkle the green onions over the eggplant and coconut milk.  Stir gently to combine."],"ingredient_names":["egg plants","coconut milk","lemon juice","salt","red pepper flakes","onions"],"allergens":["eggs"],"diet_flags":["pescatarian","vegetarian"]},{"source_id":"53075","title":"Tortang Talong","category":"Vegetarian","country":"Philippines","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/va668f1683209318.jpg","youtube_url":"https://www.youtube.com/watch?v=eLl8ekOu1MM","source_url":"https://www.sainsburysmagazine.co.uk/recipes/mains/tortang-talong","ingredients":[{"name":"Egg Plants","measure":"4"},{"name":"Eggs","measure":"2"},{"name":"Salt","measure":"1 tsp"},{"name":"Olive Oil","measure":"4 tsp"}],"steps":["Grill the eggplant until the color of skin turns almost black","Let the eggplant cool for a while then peel off the skin. Set aside.","Crack the eggs and place in a bowl","Add salt and beat","Place the eggplant on a flat surface and flatten using a fork.","Dip the flattened eggplant in the beaten egg mixture","Heat the pan and pour the cooking oil","Fry the eggplant (that was dipped in the beaten mixture). Make sure that both sides are cooked. Frying time will take you about 3 to 4 minutes per side on medium heat."],"ingredient_names":["egg plants","eggs","salt","olive oil"],"allergens":["eggs"],"diet_flags":["pescatarian","vegetarian"]},{"source_id":"53077","title":"Cabbage Soup (Shchi)","category":"Vegetarian","country":"Russia","tags":["Soup"],"image_url":"https://www.themealdb.com/images/media/meals/60oc3k1699009846.jpg","youtube_url":"https://www.youtube.com/watch?v=lTjlbqGc_Y8","source_url":"https://www.thespruceeats.com/traditional-russian-cabbage-soup-shchi-recipe-1135534","ingredients":[{"name":"Unsalted Butter","measure":"3 tbs"},{"name":"Onion","measure":"1 large"},{"name":"Cabbage","measure":"1 medium"},{"name":"Carrots","measure":"1"},{"name":"Celery","measure":"1"},{"name":"Bay Leaf","measure":"1"},{"name":"Vegetable Stock","measure":"8 cups"},{"name":"Potatoes","measure":"2 large"},{"name":"Tomatoes","measure":"2 large"},{"name":"Sour Cream","measure":"Garnish"},{"name":"Dill","measure":"Garnish"}],"steps":["Add the butter to a large Dutch oven or other heavy-duty pot over medium heat. When the butter has melted, add the onion and sauté until translucent.","Add the cabbage, carrot, and celery. Sauté until the vegetables begin to soften, stirring frequently, about 3 minutes.","Add the bay leaf and vegetable stock and bring to a boil over high heat. Reduce the heat to low and simmer, covered, until the vegetables are crisp-tender, about 15 minutes.","Add the potatoes and bring it back to a boil over high heat. Reduce the heat to low and simmer, covered, until the potatoes are tender, about 10 minutes.","Add the tomatoes (or undrained canned tomatoes) and bring the soup back to a boil over high heat. Reduce the heat to low and simmer, uncovered, for 5 minutes. Season to taste with salt and pepper.","emove and discard the bay leaf from the pot.","Serve topped with fresh sour cream and fresh dill."],"ingredient_names":["unsalted butter","onion","cabbage","carrots","celery","bay leaf","vegetable stock","potatoes","tomatoes","sour cream","dill"],"allergens":["dairy"],"diet_flags":["pescatarian","vegetarian"]},{"source_id":"53078","title":"Beetroot Soup (Borscht)","category":"Vegetarian","country":"Ukraine","tags":["Soup"],"image_url":"https://www.themealdb.com/images/media/meals/zadvgb1699012544.jpg","youtube_url":"https://www.youtube.com/watch?v=6CXgPVw_-0g","source_url":"https://natashaskitchen.com/classic-russian-borscht-recipe/","ingredients":[{"name":"Beetroot","measure":"3"},{"name":"Olive Oil","measure":"4 tbs"},{"name":"Chicken Stock Cube","measure":"1"},{"name":"Water","measure":"6 cups"},{"name":"Potatoes","measure":"3"},{"name":"Cannellini Beans","measure":"1 can"},{"name":"Dill","measure":"Garnish"}],"steps":["Chop the beetroot, add water and stock cube and cook for 15mins. Add the other ingredients and boil until soft. Finally add the beans and cook for 5mins. Serve in the soup pot."],"ingredient_names":["beetroot","olive oil","chicken stock cube","water","potatoes","cannellini beans","dill"],"allergens":[],"diet_flags":[]},{"source_id":"53079","title":"Fish Soup (Ukha)","category":"Seafood","country":"Russia","tags":["Soup"],"image_url":"https://www.themealdb.com/images/media/meals/7n8su21699013057.jpg","youtube_url":"https://www.youtube.com/watch?v=cS3Yn-y5uVg","source_url":"https://www.curiouscuisiniere.com/ukha-russian-fish-soup/","ingredients":[{"name":"Olive Oil","measure":"2 tbs"},{"name":"Onion","measure":"1 sliced"},{"name":"Carrots","measure":"2 medium"},{"name":"Fish Stock","measure":"3 cups"},{"name":"Water","measure":"3 cups"},{"name":"Potatoes","measure":"4 large"},{"name":"Bay Leaf","measure":"3"},{"name":"Cod","measure":"1"},{"name":"Salmon","measure":"1"}],"steps":["In a medium pot, heat the olive oil over medium-high heat. Add the onions and cook, stirring occasionally until the onions start to caramelize. Add the carrots and cook until the carrots start to soften, about 4 more minutes.","Add the stock, water, potatoes, bay leaves, and black peppercorns. Season with salt and bring to a boil. Reduce heat, cover and cook for 10 minutes. Add the millet and cook for 15 more minutes until millet and potatoes are cooked.","Gently add the fish cubes. Stir and bring the soup to a simmer. The fish will cook through very fast, so make sure to not overcook them. They are done when the flesh is opaque and flakes easily.","Garnish the soup with chopped fresh dill or parsley before serving."],"ingredient_names":["olive oil","onion","carrots","fish stock","water","potatoes","bay leaf","cod","salmon"],"allergens":["fish"],"diet_flags":["pescatarian"]},{"source_id":"53081","title":"Potato Salad (Olivier Salad)","category":"Vegetarian","country":"Russia","tags":["Salad"],"image_url":"https://www.themealdb.com/images/media/meals/ebvuir1699013665.jpg","youtube_url":"https://www.youtube.com/watch?v=RnsWwHcpKiY","source_url":"https://www.sweetandsavorybyshinee.com/russian-potato-salad/","ingredients":[{"name":"Potatoes","measure":"4"},{"name":"Carrots","measure":"3"},{"name":"Salt","measure":"1 tbs"},{"name":"White Wine Vinegar","measure":"1/2 tbs"},{"name":"Eggs","measure":"4"},{"name":"Sausages","measure":"7 oz"},{"name":"Dill","measure":"4 oz"},{"name":"Peas","measure":"1 can"},{"name":"Onions","measure":"4"},{"name":"Mayonnaise","measure":"1 cup"}],"steps":["Cut the potatoes and carrots into small uniform cubes.","Place them in a large pot and fill with water.","Add salt and vinegar. Bring it to a boil over medium high heat, and then reduce the heat to medium and continue to cook until the potatoes are cooked through, about 15 minutes. Drain the potatoes and let it cool to room temperature.","Meanwhile, cut the sausage and pickles into small cubes, and chop the green onions.","Cut the hard-boiled eggs into small cubes as well.","If using fresh dill, chop them as well.","In a large bowl, combine potatoes, carrots, sausage, pickles, peas and green onions.","Add mayo and dill and mix until well combined.","Salt and pepper to taste. Cover with a plastic wrap and refrigerate for at least 1 hour before serving."],"ingredient_names":["potatoes","carrots","salt","white wine vinegar","eggs","sausages","dill","peas","onions","mayonnaise"],"allergens":["eggs"],"diet_flags":[]},{"source_id":"53083","title":"Lamb Pilaf (Plov)","category":"Lamb","country":"Russia","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/kos9av1699014767.jpg","youtube_url":"https://www.youtube.com/watch?v=rllQsUw1hFQ","source_url":"https://www.thespruceeats.com/russian-lamb-pilaf-plov-recipe-1137309","ingredients":[{"name":"Lamb","measure":"50g"},{"name":"Prunes","measure":"120g"},{"name":"Lemon Juice","measure":"1 tbs"},{"name":"Butter","measure":"2 tbs"},{"name":"Onion","measure":"1 chopped"},{"name":"Lamb","measure":"450g"},{"name":"Garlic","measure":"2 cloves"},{"name":"Vegetable Stock","measure":"600ml"},{"name":"Rice","measure":"2 cups"},{"name":"Saffron","measure":"Pinch"},{"name":"Parsley","measure":"Garnish"}],"steps":["Place the raisins and prunes into a small bowl and pour over enough water to cover. Add lemon juice and let soak for at least 1 hour. Drain. Roughly chop the prunes.","Meanwhile, heat the butter in a large pan, add the onion, and cook for 5 minutes. Add cubed lamb, ground lamb, and crushed garlic cloves. Fry for 5 minutes, stirring constantly until browned.","Pour 2/3 cup (150 milliliters) of stock into the pan. Bring to a boil, then lower the heat, cover, and simmer for 1 hour, or until the lamb is tender.","Add the remaining stock and bring to a boil. Add rinsed long-grain white rice and a large pinch of saffron. Stir, then cover, and simmer for 15 minutes, or until the rice is tender.","Add the drained raisins, drained chopped prunes, and salt and pepper to taste. Heat through for a few minutes, then turn out onto a warmed serving dish and garnish with sprigs of flat-leaf parsley."],"ingredient_names":["lamb","prunes","lemon juice","butter","onion","lamb","garlic","vegetable stock","rice","saffron","parsley"],"allergens":["dairy"],"diet_flags":[]},{"source_id":"53085","title":"15-minute chicken & halloumi burgers","category":"Chicken","country":"United States","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/vdwloy1713225718.jpg","youtube_url":"https://www.youtube.com/watch?v=k9Ez0bUbXKc","source_url":"https://www.bbcgoodfood.com/recipes/15-minute-chicken-halloumi-burgers","ingredients":[{"name":"Chicken Breasts","measure":"2"},{"name":"Oil","measure":"1 tbsp"},{"name":"Hotsauce","measure":"4 tbsp"},{"name":"Lemon Juice","measure":"½"},{"name":"Buns","measure":"2"},{"name":"Cheese","measure":"250g"},{"name":"Cabbage","measure":"¼"},{"name":"Mayonnaise","measure":"2 tbsp"},{"name":"Sour Cream","measure":"4 tbsp"},{"name":"Lettuce","measure":"4 leaves"},{"name":"Red Pepper","measure":"2"}],"steps":["Put the chicken breasts between two pieces of baking parchment and use a rolling pin to gently bash them until they are approximately 1cm thick. Cut each chicken breast into two even pieces.","If you're using a frying pan, heat two frying pans over medium-high heat, with one of them containing oil. Fry the chicken in the oiled pan for 3-4 mins on each side until they are cooked through. Season the chicken, reduce the heat, drizzle in the chilli sauce and half of the lemon juice, and cook for an additional 1-2 mins until the sauce is reduced. Remove the chicken from the heat.","If you're using an air-fryer, preheat it to 180C for 4 mins. Add the chicken to the air-fryer and cook for 12 mins. Drizzle over the chilli sauce and half the lemon juice and cook for an additional 1-2 mins until the chicken is cooked through and the sauce is reduced. Remove the chicken and keep it warm.","While the chicken is cooking, toast the buns in the dry frying pan for 30 seconds. Transfer them to a plate. If you're using an air fryer, put the buns in the air fryer for 1-2 mins until they are warm. Increase the air fryer temperature to 200C. Add the halloumi to the air fryer basket and cook for 10 mins, turning halfway through, until it's golden. Toss the cabbage with the mayo and the remaining lemon juice.","Spoon the hummus (or dip of your choice) into the toasted buns, then top with the rocket, chilli chicken, halloumi, and peppers. Drizzle with a little more chilli sauce, spoon over the cabbage, season with black pepper, and top with the bun lids. Serve with any extra cabbage on the side or a green salad."],"ingredient_names":["chicken breasts","oil","hotsauce","lemon juice","buns","cheese","cabbage","mayonnaise","sour cream","lettuce","red pepper"],"allergens":["dairy","eggs","gluten"],"diet_flags":[]},{"source_id":"53091","title":"Falafel Pita Sandwich with Tahini Sauce","category":"Vegetarian","country":"Syria","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/ae6clc1760524712.jpg","youtube_url":"https://www.youtube.com/watch?v=wt8nApxP5fE","source_url":"https://www.allrecipes.com/recipe/266014/falafel-pita-sandwich-with-tahini-sauce/","ingredients":[{"name":"Falafel","measure":"12"},{"name":"Tahini","measure":"1/4 cup"},{"name":"Water","measure":"1/4 cup"},{"name":"Lemon Juice","measure":"2 tablespoons"},{"name":"Garlic","measure":"2 cloves"},{"name":"Paprika","measure":"1/4 tsp"},{"name":"Pita Bread","measure":"6"},{"name":"Lettuce","measure":"1"},{"name":"Tomato","measure":"1"},{"name":"Cucumber","measure":"1/2"},{"name":"Dill Pickles","measure":"1"},{"name":"Red Onions","measure":"1/4"},{"name":"Harissa Spice","measure":"3 tsp"}],"steps":["Preheat the oven to 450 degrees F (230 degrees C). Place falafel on a baking sheet.","Bake in the preheated oven until heated through, 8 to 10 minutes.","While falafel bake, whisk tahini, water, lemon juice, garlic, and paprika together in a bowl.","Cut about 1 inch from the top of each pita to form a pocket. Add 2 falafel to each pita with equal amounts lettuce, tomato, cucumber, pickle, and red onion. Drizzle each with about 1 tablespoon tahini sauce and some harissa."],"ingredient_names":["falafel","tahini","water","lemon juice","garlic","paprika","pita bread","lettuce","tomato","cucumber","dill pickles","red onions","harissa spice"],"allergens":["gluten","sesame"],"diet_flags":["pescatarian","vegan","vegetarian"]},{"source_id":"53092","title":"Fasoliyyeh Bi Z-Zayt (Syrian Green Beans with Olive Oil)","category":"Vegan","country":"Syria","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/21yc5s1760524759.jpg","youtube_url":"https://www.youtube.com/watch?v=_EadiEPxQI0","source_url":"https://www.allrecipes.com/recipe/56161/fasoliyyeh-bi-z-zayt-syrian-green-beans-with-olive-oil/","ingredients":[{"name":"Green Beans","measure":"16 ounces"},{"name":"Olive Oil","measure":"1/4 cup"},{"name":"Salt","measure":"Dash"},{"name":"Garlic","measure":"1 clove"},{"name":"Cilantro","measure":"1/4 cup"}],"steps":["Place the green beans into a large pot, and drizzle with olive oil.","Season with salt to taste, and put the lid on the pot.","Cook over medium-high heat, stirring occasionally, until beans are cooked to your desired doneness.","Syrians like it cooked until the green beans are turning brownish in color.","The idea is not to saute them, but to let them steam in the moisture released by the ice crystals.","Add cilantro and garlic to the beans, and continue to cook just until the cilantro has started to wilt.","Eat as a main course by scooping up with warm pita bread or serve as a side dish."],"ingredient_names":["green beans","olive oil","salt","garlic","cilantro"],"allergens":[],"diet_flags":["pescatarian","vegan","vegetarian"]},{"source_id":"53093","title":"Syrian Spaghetti","category":"Pasta","country":"Syria","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/5fu4ew1760524857.jpg","youtube_url":"https://www.youtube.com/watch?v=MGmaX9Uv_Gs","source_url":"https://www.allrecipes.com/recipe/26303/syrian-spaghetti/","ingredients":[{"name":"Spaghetti","measure":"16 ounces"},{"name":"Tomato Sauce","measure":"8 ounces"},{"name":"Tomato Puree","measure":"6 oz"},{"name":"Cinnamon","measure":"1 teaspoon"},{"name":"Vegetable Oil","measure":"1/4 cup"},{"name":"Salt","measure":"Dash"},{"name":"Pepper","measure":"Dash"}],"steps":["Preheat oven to 350 degrees F (175 degrees C). Grease a 9x13 inch baking dish.","Bring a large pot of lightly salted water to a boil. Add spaghetti and cook for 8 to 10 minutes or until al dente; drain and stir in tomato sauce, tomato paste, cinnamon, oil, salt and pepper. Transfer to prepared dish.","Bake in preheated oven for 1 hour, or until top is crunchy."],"ingredient_names":["spaghetti","tomato sauce","tomato puree","cinnamon","vegetable oil","salt","pepper"],"allergens":["gluten"],"diet_flags":["pescatarian","vegan","vegetarian"]},{"source_id":"53096","title":"Corned Beef Hash","category":"Beef","country":"United Kingdom","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/vz94r81760534692.jpg","youtube_url":"https://www.youtube.com/watch?v=SPr_UnCrYPg","source_url":"https://www.simplyrecipes.com/recipes/corned_beef_hash/","ingredients":[{"name":"Unsalted Butter","measure":"3  tablespoons"},{"name":"Onion","measure":"1 medium chopped"},{"name":"Corned Beef","measure":"3 Cups"},{"name":"Potatoes","measure":"3 chopped"},{"name":"Kosher Salt","measure":"Dash"},{"name":"Black Pepper","measure":"Dash"},{"name":"Freshly Chopped Parsley","measure":"Chopped"}],"steps":["Sauté the onions:","Heat butter in a large skillet (preferably cast iron) on medium heat. Add the onion and cook a few minutes, until translucent.","Add the potatoes and corned beef:","Mix in the chopped corned beef and potatoes. Spread out evenly over the pan. Increase the heat to high or medium high and press down on the mixture with a metal spatula.","Cook until browned and then flip:","Do not stir the potatoes and corned beef, but let them brown. If you hear them sizzling, this is good.","Use a metal spatula to peek underneath and see if they are browning. If nicely browned, use the spatula to flip sections over in the pan so that they brown on the other side. Press down again with the spatula.","If there is too much sticking, you can add a little more butter to the pan. Continue to cook in this manner until the potatoes and the corned beef are nicely browned.","Stir in the parsley and season:","Remove from heat, stir in chopped parsley. Add plenty of freshly ground black pepper, and add salt to taste."],"ingredient_names":["unsalted butter","onion","corned beef","potatoes","kosher salt","black pepper","freshly chopped parsley"],"allergens":["dairy"],"diet_flags":[]},{"source_id":"53098","title":"Cumberland Pie","category":"Beef","country":"United Kingdom","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/pvfkz61761595976.jpg","youtube_url":"https://www.youtube.com/watch?v=r1lnsOTNjws","source_url":"https://www.bbcgoodfood.com/recipes/crispy-topped-cumberland-pie","ingredients":[{"name":"Celery","measure":"2"},{"name":"Onion","measure":"1 chopped"},{"name":"Carrots","measure":"2 large"},{"name":"Bay Leaves","measure":"5"},{"name":"Thyme","measure":"3"},{"name":"Vegetable Oil","measure":"2 tblsp"},{"name":"Butter","measure":"1 tablespoon"},{"name":"Flour","measure":"2 tablespoons"},{"name":"Tomato Puree","measure":"2 tblsp"},{"name":"Worcestershire Sauce","measure":"2 tablespoons"},{"name":"Beef Stock Cubes","measure":"2"},{"name":"Feather blade beef","measure":"800g"},{"name":"Potatoes","measure":"800g"},{"name":"Mature Cheddar","measure":"25g"},{"name":"Parmesan Cheese","measure":"25g"}],"steps":["Heat oven to 160C/140C fan/gas 3. Soften the celery, onion, carrots, bay and 1 thyme sprig in a casserole with 1 tbsp oil and the butter for 10 mins. Stir in the flour, followed by the purée, Worcestershire sauce and stock cubes.","Gradually stir in 600ml hot water, then tip in the beef and bring to a gentle simmer. Cover and cook in the oven for 2 hrs 30 mins, then uncover and cook for 30 mins -1 hr more until the meat is really tender and sauce thickened.","Meanwhile, cook potatoes in a pan of boiling water until they’re not done but about ¾ of the way there.","Transfer meat to a baking dish. Slice spuds into 1cm thick rounds and gently toss with seasoning, the remaining oil and thyme leaves. Layer on the beef, scattering with the cheese as you layer. You can cover and chill the pie now for 1 day, or freeze for up to 3 months.","Increase oven to 200C/180C fan/gas 6 and bake for 30-40 mins until golden and crispy, and sauce bubbling if the dish went in cold. Serve with peas."],"ingredient_names":["celery","onion","carrots","bay leaves","thyme","vegetable oil","butter","flour","tomato puree","worcestershire sauce","beef stock cubes","feather blade beef","potatoes","mature cheddar","parmesan cheese"],"allergens":["dairy","fish","gluten"],"diet_flags":[]},{"source_id":"53099","title":"Aussie Burgers","category":"Beef","country":"Australia","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/44bzep1761848278.jpg","youtube_url":"https://www.youtube.com/watch?v=pSupybydA_U","source_url":"https://www.bbcgoodfood.com/recipes/aussie-burgers","ingredients":[{"name":"Lean Minced Steak","measure":"500g"},{"name":"Cooked Beetroot","measure":"100g"},{"name":"Naan Bread","measure":"2 small"},{"name":"Rocket","measure":"50g"},{"name":"Soured cream and chive dip","measure":"4 tablespoons"}],"steps":["Make the burgers: Tip the meat into a bowl and sprinkle over 1 tsp salt and a good grinding of black pepper.Work with wet hands to mix in the seasoning. Divide into four with your hands and shape into burgers. (It can be frozen at this stage.)","Sort out your ingredients: Slice the beetroot and split the naan breads.","Toast the naans: Heat a griddle pan or barbecue. Griddle the naans on both sides until lightly toasted and set aside. Add the burgers to the grill or barbecue and cook for 2-3 minutes, then turn and cook the other side for a further 2-3 minutes.","Assemble the dish: Set half a toasted naan on each serving plate and put a pile of rocket on each. Top with a burger, then a few slices of beetroot and a dollop of soured cream. Sprinkle with salt and freshly ground black pepper and serve immediately with a big green salad and chips. A glass of red wine wouldn’t go amiss, either."],"ingredient_names":["lean minced steak","cooked beetroot","naan bread","rocket","soured cream and chive dip"],"allergens":["dairy","gluten"],"diet_flags":[]},{"source_id":"53102","title":"Squid, chickpea & chorizo salad","category":"Seafood","country":"Australia","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/wsu0rc1761848482.jpg","youtube_url":"https://www.bbcgoodfood.com/recipes/squid-chickpea-chorizo-salad","source_url":"https://www.bbcgoodfood.com/recipes/squid-chickpea-chorizo-salad","ingredients":[{"name":"Red Pepper","measure":"4"},{"name":"Can of chickpeas","measure":"2 400g Cans"},{"name":"Parsley","measure":"Bunch"},{"name":"Red Chilli","measure":"1"},{"name":"Garlic Clove","measure":"2"},{"name":"Olive Oil","measure":"100 ml"},{"name":"Squid","measure":"600g"},{"name":"Chorizo","measure":"200g"},{"name":"Lemon","measure":"Juice/zest of one"}],"steps":["Cook the peppers whole under a grill, on a barbecue or griddle, until completely charred.","Place the peppers in a bowl, cover with a plate until cool enough to handle, then peel, deseed and finely slice.","In a large bowl mix the peppers and any juices with the chickpeas, parsley, chilli and garlic. Set aside.","Heat a large frying pan until smoking.","Working quickly and carefully, add a splash of oil to the pan, then the squid.","Stir-fry for about 30 secs.","Scatter the chorizo over the squid, continue to cook for 30 secs more, then tip into the bowl with the peppers.","Season everything with salt and pepper, then dress with the remaining oil, lemon juice and lemon zest.","Mix together, pile onto a platter and let everyone help themselves."],"ingredient_names":["red pepper","can of chickpeas","parsley","red chilli","garlic clove","olive oil","squid","chorizo","lemon"],"allergens":["shellfish"],"diet_flags":[]},{"source_id":"53103","title":"Barramundi with Moroccan spices","category":"Seafood","country":"Australia","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/4o4wh11761848573.jpg","youtube_url":null,"source_url":"https://www.bbcgoodfood.com/recipes/barramundi-moroccan-spices","ingredients":[{"name":"barramundi","measure":"2 x 400g"},{"name":"Ground Cumin","measure":"1/2 teaspoon"},{"name":"Coriander","measure":"1/2 tsp"},{"name":"Paprika","measure":"Pinch"},{"name":"Chili Powder","measure":"Pinch"},{"name":"Garlic Clove","measure":"2"},{"name":"Lemon","measure":"Juice of 1"},{"name":"Olive Oil","measure":"5 tablespoons"},{"name":"Coriander","measure":"Bunch"}],"steps":["Tip all the dressing ingredients into a food processor with a pinch of salt and blitz to a dressing. Slash the fish three times on each side, coat with half of the dressing, then set aside to marinate for about 30 mins.","Heat oven to 220C/fan 200C/gas 7. Place the fish on a roasting tray, then cook in the oven for 20 mins until the flesh is firm and the eyes have turned white. Serve the fish with the rest of the dressing and steamed couscous or rice.","KNOW HOW: HOW TO COOK IT: Cooking barramundi on the bone, as we have done here, has its advantages – it will stay more moist during cooking, and some would say that the flavour is enhanced, too. If you want to take out the bones they are easy to locate and less likely to be lodged in the fillet if the fish is cooked whole. Fillets can be simply pan-fried or grilled. If you like trout, you will really enjoy the flavour of barramundi, which lends itself to similar ingredients and cooking methods – citrus flavours are particularly good, as are garlic and wild mushrooms. Simply roasting the fish with some fresh herbs, olive oil and seasoning is delicious, and in the summer months you could barbecue it, too. One thing that you mustn’t miss are the cheeks or ‘pearls’ of the fish, these are simply lovely, moist and really sweet – well worth leaving the head on for!"],"ingredient_names":["barramundi","ground cumin","coriander","paprika","chili powder","garlic clove","lemon","olive oil","coriander"],"allergens":["fish"],"diet_flags":["pescatarian"]},{"source_id":"53105","title":"Spiced smoky barbecued chicken","category":"Chicken","country":"Australia","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/a08uqk1761848682.jpg","youtube_url":null,"source_url":"https://www.bbcgoodfood.com/recipes/spiced-smoky-barbecued-chicken","ingredients":[{"name":"Garlic","measure":"2 cloves"},{"name":"Lemon","measure":"Juice/zest of one"},{"name":"Curry Powder","measure":"2 tblsp"},{"name":"Chilli Flakes","measure":"Pinch"},{"name":"Olive Oil","measure":"3  tablespoons"},{"name":"Chicken Thighs","measure":"12"},{"name":"Rosemary","measure":"Bunch"},{"name":"Rosemary","measure":"Bunch"},{"name":"Thyme","measure":"Bunch"},{"name":"Thyme","measure":"Bunch"},{"name":"Bay Leaves","measure":"2"}],"steps":["Make the marinade.","Smash the garlic with a little salt using a pestle and mortar.","Add the lemon zest and juice, the spice mix, chilli, oil and a good grinding of black pepper. Mix to a paste.","This can be done in a mini food processor.","Toss the chicken in the marinade and set aside while you light the barbecue.","When the barbecue’s hot, lay the bunches of herbs on the grid and put the chicken, skin side up, on top.","Close the lid, if your barbecue has one, and cook the chicken on the smouldering herbs for about 10 minutes until the meat starts to colour.","Turn the chicken and continue to cook for a further 20-30 minutes, turning as necessary, until it is slightly charred from the burnt herbs and cooked through to the bone."],"ingredient_names":["garlic","lemon","curry powder","chilli flakes","olive oil","chicken thighs","rosemary","rosemary","thyme","thyme","bay leaves"],"allergens":[],"diet_flags":[]},{"source_id":"53106","title":"Warm roast asparagus salad","category":"Pork","country":"Australia","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/ktsws11761998344.jpg","youtube_url":"https://www.youtube.com/watch?v=pR_ZfbTxwms","source_url":"https://www.bbcgoodfood.com/recipes/warm-roast-asparagus-salad","ingredients":[{"name":"Asparagus","measure":"500g"},{"name":"Red Wine Vinegar","measure":"2 tbsp"},{"name":"Tomato","measure":"4"},{"name":"Extra Virgin Olive Oil","measure":"1 tbsp"},{"name":"Streaky Bacon","measure":"12"},{"name":"Clear Honey","measure":"1 teaspoon"},{"name":"Jersey Royal Potatoes","measure":"16"},{"name":"Extra Virgin Olive Oil","measure":"2 tblsp"},{"name":"Dijon Mustard","measure":"1 teaspoon"},{"name":"Rocket","measure":"100g"}],"steps":["Preheat the oven to 200C/Gas 6/fan 180C. Snap off the woody ends of the asparagus and discard. Arrange the asparagus in a single layer in a baking tray with sides. Cut the tomatoes in half widthways, nestle them in with the asparagus, season with sea salt and pepper and drizzle with olive oil. Roll each bacon rasher into a tight roll (if large, first cut in half crosswise), and arrange in the tray. Drizzle the bacon rolls with the honey and bake for 20 minutes until the tomatoes are soft and the bacon is crisp.","In the meantime, boil the potatoes until tender. Whisk the vinegar, olive oil, mustard, some sea salt and pepper in a large bowl until blended. Toss the rocket or spinach leaves in half of the dressing, and arrange on a large serving platter.","Drain the potatoes and cut in half. Gently toss them in the rest of the dressing, and arrange on the platter with the asparagus. Tuck in the tomatoes and bacon."],"ingredient_names":["asparagus","red wine vinegar","tomato","extra virgin olive oil","streaky bacon","clear honey","jersey royal potatoes","extra virgin olive oil","dijon mustard","rocket"],"allergens":[],"diet_flags":[]},{"source_id":"53107","title":"Avocado dip with new potatoes","category":"Vegetarian","country":"Australia","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/flrajf1762341295.jpg","youtube_url":null,"source_url":"https://www.bbcgoodfood.com/recipes/avocado-citrus-dip-spicy-spuds-tortilla-chips","ingredients":[{"name":"Avocado","measure":"3 Large"},{"name":"Natural Yoghurt","measure":"200g"},{"name":"Lime","measure":"Zest and juice of 1"},{"name":"Lemon","measure":"Juice of 1/2"},{"name":"Baby New Potatoes","measure":"1.25kg"},{"name":"Olive Oil","measure":"2 tablespoons"},{"name":"Hot Chilli Powder","measure":"1 teaspoon"},{"name":"Cumin Seeds","measure":"1 teaspoon"},{"name":"Tortillas","measure":"200g"}],"steps":["Whizz half the avocado flesh with the yogurt, lime and lemon juice and seasoning. Dice the remaining avocado, then gently stir into the whizzed mix with most of the lime zest. Cover, then chill until ready to serve.","Boil potatoes for 6 mins, then drain well and toss with olive oil, chilli powder and cumin seeds. Now set aside until half an hour before your guests arrive.","Heat oven to 200C/180C fan/gas 6, then roast potatoes for about 30 mins, shaking the tray halfway, until golden and tender. Transfer the dip to one or two bowls, scatter with the remaining lime zest and serve with the hot potatoes, and tortilla chips for dipping."],"ingredient_names":["avocado","natural yoghurt","lime","lemon","baby new potatoes","olive oil","hot chilli powder","cumin seeds","tortillas"],"allergens":["dairy","gluten"],"diet_flags":["pescatarian","vegetarian"]},{"source_id":"53108","title":"Quick salt & pepper squid","category":"Seafood","country":"Australia","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/cp74zo1762341241.jpg","youtube_url":"https://www.youtube.com/watch?v=CxHTj_6sU_A","source_url":"https://www.bbcgoodfood.com/recipes/salt-pepper-squid-0","ingredients":[{"name":"Squid","measure":"400g"},{"name":"Oil","measure":"3  tablespoons"},{"name":"Chinese five spice powder","measure":"1/2 teaspoon"},{"name":"Sesame Seed Oil","measure":"Dash"},{"name":"Coriander","measure":"Sprigs of fresh"},{"name":"sweet chilli sauce","measure":"Drizzle"}],"steps":["Ask the fishmonger to clean the squid; little ones often come ready-cleaned. Using kitchen scissors, cut open the body and open out. Wash well, then pat dry. If you have a large squid, cut the body into four portions, roughly square. Small squid can just be opened up.","Using the tip of a very sharp knife, score the top in a neat criss-cross. Brush with oil and set aside while you heat the barbecue or griddle until ready to cook.","Mix together 2 tsp sea salt, Chinese five-spice and 1 tsp freshly ground black pepper. Sprinkle on both sides of the squid just before cooking, according to taste. You may not need it all. Heat the griddle pan to hot and cook about 1 min each side, until it starts to curl. Remove with tongs to a serving plate and drizzle with a little sesame oil. To serve, garnish with coriander leaves and serve with small bowls of sweet chilli sauce to dip into."],"ingredient_names":["squid","oil","chinese five spice powder","sesame seed oil","coriander","sweet chilli sauce"],"allergens":["sesame","shellfish"],"diet_flags":["pescatarian"]},{"source_id":"53109","title":"Mini chilli beef pies","category":"Beef","country":"Australia","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/6sarfo1762340107.jpg","youtube_url":"https://www.youtube.com/watch?v=PHuU1L92-Ns","source_url":"https://www.bbcgoodfood.com/recipes/mini-chilli-beef-pies","ingredients":[{"name":"Ready rolled shortcrust pastry","measure":"450g"},{"name":"Sunflower Oil","measure":"1 tablespoon"},{"name":"Onion","measure":"1 small"},{"name":"Hot Chilli Powder","measure":"2 tsp"},{"name":"Ground Cumin","measure":"2 tsp"},{"name":"Minced Beef","measure":"250g"},{"name":"Tomato Puree","measure":"85g"},{"name":"Beef Stock","measure":"150ml"},{"name":"Ground Cinnamon","measure":"Pinch"},{"name":"Kidney Beans","measure":"200g"},{"name":"Potatoes","measure":"1 large"},{"name":"Sour Cream","measure":"3  tablespoons"},{"name":"Chopped Chive","measure":"2 tablespoons"}],"steps":["To make chilli, heat oil in a pan and fry onion for 5 mins until soft. Add spices; fry for 1 min. Stir in beef and cook for a few mins. Add tomato purée, stock and cinnamon. Give it a stir, bring to the boil, then simmer for 15-20 mins until very little liquid is left. Add beans 5 mins before the end of cooking. Check seasoning and cool.","Heat oven to 200C/fan 180C/gas 6. Using a 7cm pastry cutter, stamp out 12 circles from the pastry. Use to line a 12-hole mini muffin tray, prick the base of the pastry with a fork, and bake for 10 mins. Remove from oven and cool on a wire tray. Repeat with remaining pastry.","Meanwhile, cook the potato in boiling water until tender. Drain, mash with soured cream and seasoning, then stir through chives. Spoon 1-2 tsp of chilli mix into the pastry cases and top with a tsp of mash. Ruffle mash with a fork; return to the oven for 15 mins or until golden."],"ingredient_names":["ready rolled shortcrust pastry","sunflower oil","onion","hot chilli powder","ground cumin","minced beef","tomato puree","beef stock","ground cinnamon","kidney beans","potatoes","sour cream","chopped chive"],"allergens":["dairy","gluten"],"diet_flags":[]},{"source_id":"53110","title":"Sticky Chicken","category":"Chicken","country":"Australia","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/cj56fs1762340001.jpg","youtube_url":"https://www.youtube.com/watch?v=o8tz2BOltTg","source_url":"https://www.bbcgoodfood.com/recipes/sticky-chicken","ingredients":[{"name":"Chicken drumsticks","measure":"8"},{"name":"Soy Sauce","measure":"2 tblsp"},{"name":"Honey","measure":"1 tablespoon"},{"name":"Olive Oil","measure":"1 tblsp"},{"name":"Tomato Puree","measure":"1 teaspoon"},{"name":"Dijon Mustard","measure":"1 tbsp"}],"steps":["Make 3 slashes on each of the drumsticks.","Mix together the soy, honey, oil, tomato purée and mustard.","Pour this mixture over the chicken and coat thoroughly.","Leave to marinate for 30 mins at room temperature or overnight in the fridge.","Heat oven to 200C/fan 180C/gas 6.","Tip the chicken into a shallow roasting tray and cook for 35 mins, turning occasionally, until the chicken is tender and glistening with the marinade."],"ingredient_names":["chicken drumsticks","soy sauce","honey","olive oil","tomato puree","dijon mustard"],"allergens":["gluten","soy"],"diet_flags":[]},{"source_id":"53112","title":"Kenyan Beef Curry","category":"Beef","country":"Kenya","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/lqampv1762325397.jpg","youtube_url":"https://www.youtube.com/watch?v=NxrOueTLiqA","source_url":"https://tasteoftheplace.com/kenyan-beef-curry/","ingredients":[{"name":"Water","measure":"4 cups"},{"name":"Sirloin Steak tips","measure":"2 Lbs"},{"name":"Garlic Clove","measure":"4"},{"name":"Ground Ginger","measure":"2 teaspoons"},{"name":"Oil","measure":"2 tblsp"},{"name":"Red Onions","measure":"2 medium"},{"name":"Tomato","measure":"4"},{"name":"Paprika","measure":"2 tblsp"},{"name":"Black Pepper","measure":"1/2 teaspoon"},{"name":"Curry Powder","measure":"2 teaspoons"},{"name":"Tomato Puree","measure":"4 tablespoons"},{"name":"Salt","measure":"Dash"},{"name":"Chilli","measure":"1"},{"name":"Cilantro","measure":"Leaves"}],"steps":["Bring the 4 cups of water to a boil in a Dutch oven or soup pot. Add the beef, garlic, and ginger, and stir well. Bring to a gentle simmer, cover, and cook, stirring occasionally, for 20 minutes. If you get any foamy scum on the top, not to worry, simply spoon it away or stir it back in.","Remove from the heat, and drain, but reserve the excess water for later.","Return the pot or Dutch oven to medium heat with the 2 tablespoons of cooking oil. Once the oil is shimmering, add the onions and cook, stirring occasionally, until softened, 5 to 7 minutes.","Add the tomatoes to the onions, and continue cooking, stirring occasionally, until the tomatoes are falling apart, 3 to 5 minutes.","Add the drained beef to the tomato and onion mixture, and stir well. Continue cooking over medium heat for 5 minutes, stirring occasionally.","Add the paprika, pepper, curry powder, tomato paste, and salt to taste, and stir well.","Add back the excess water that was used for cooking the beef, along with enough extra water to cover. Bring to a boil, reduce heat, and simmer, uncovered, stirring occasionally, for about 1 hour, or until the meat is tender and the sauce is thickened. Add additional water if your beef curry begins to dry and stick, or if would like your curry to have more of a soupy consistency.","When the beef curry is ready, remove from the heat, give it a taste, and adjust the seasonings as desired. Garnish with fresh chilis and cilantro."],"ingredient_names":["water","sirloin steak tips","garlic clove","ground ginger","oil","red onions","tomato","paprika","black pepper","curry powder","tomato puree","salt","chilli","cilantro"],"allergens":[],"diet_flags":[]},{"source_id":"53113","title":"Sukuma Wiki","category":"Vegetarian","country":"Kenya","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/60o82j1762341177.jpg","youtube_url":"https://www.youtube.com/watch?v=02hHtPDAxOs","source_url":"https://tasteoftheplace.com/sukuma-wiki/","ingredients":[{"name":"Oil","measure":"2 tablespoons"},{"name":"Red Onions","measure":"2 medium"},{"name":"Kale","measure":"1 lb"},{"name":"Salt","measure":"Dash"},{"name":"Double Cream","measure":"1 cup"}],"steps":["Heat the 2 tablespoons of oil in a large skillet or pot over medium heat until shimmering. Add the onions and cook, stirring occasionally, until softened, 5 to 7 minutes.","Add the shredded kale to the onions and mix well. Turn the heat to medium-low, cover and cook for 5 minutes.","After 5 minutes, remove the lid, add salt to taste, and stir in the cream. Continue cooking for another 5 minutes, uncovered, stirring occasionally. The cream will thicken slightly, making for a deliciously rich creamed kale and onions. Yumm!","Serve it up with your favorite Kenyan stew, and a side of ugali!"],"ingredient_names":["oil","red onions","kale","salt","double cream"],"allergens":["dairy"],"diet_flags":["pescatarian","vegetarian"]},{"source_id":"53115","title":"Red onion pickle","category":"Vegan","country":"Norway","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/ppodrp1762325183.jpg","youtube_url":"https://www.youtube.com/watch?v=3z2jTcsL28g","source_url":"https://www.bbc.co.uk/food/recipes/red_onion_pickle_98165","ingredients":[{"name":"Red Onions","measure":"3 Large"},{"name":"Sea Salt","measure":"2 tsp"},{"name":"Cider Vinegar","measure":"200ml"},{"name":"Granulated Sugar","measure":"50g"},{"name":"Black Pepper","measure":"1 tsp"},{"name":"Bay Leaves","measure":"4"}],"steps":["Peel the onions, cut them in half from top to bottom and finely slice into half-moon pieces. Put in a colander placed over a bowl and sprinkle with salt, lightly turning over the onion pieces with your hands so the surfaces are all covered. Set aside for an hour or so to brine.","Meanwhile put the vinegar, 50ml/2fl oz water and the sugar in a saucepan. Bring to a simmer, stirring to help the sugar dissolve, and cook for a couple of minutes. Set aside.","Pack the onions into the sterilised jars, sprinkling in a little pepper as you go. Cover with the warm vinegar and finish by tucking a couple of bay leaves down the side of the jars. Seal. The onions are best kept in the fridge and used within to 4 weeks."],"ingredient_names":["red onions","sea salt","cider vinegar","granulated sugar","black pepper","bay leaves"],"allergens":[],"diet_flags":["pescatarian","vegan","vegetarian"]},{"source_id":"53117","title":"Nordic smørrebrød with asparagus and horseradish cream","category":"Vegetarian","country":"Norway","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/8a8fu01762772651.jpg","youtube_url":null,"source_url":"https://www.bbc.co.uk/food/recipes/nordic_smorrebrod_69435","ingredients":[{"name":"Creme Fraiche","measure":"150ml"},{"name":"Horseradish","measure":"2 tblsp"},{"name":"Lemon Juice","measure":"1 teaspoon"},{"name":"Salt","measure":"Pinch"},{"name":"Pepper","measure":"Pinch"},{"name":"Vegetable Oil","measure":"Dash"},{"name":"Shallots","measure":"2"},{"name":"Salt","measure":"Pinch"},{"name":"White Asparagus","measure":"8"},{"name":"Asparagus","measure":"8"},{"name":"Rye Bread","measure":"4 slices"},{"name":"Butter","measure":"1 tblsp"},{"name":"västerbottensost cheese","measure":"100g"},{"name":"Dill","measure":"Sprinking"},{"name":"Salt","measure":"Pinch"},{"name":"Black Pepper","measure":"Pinch"}],"steps":["To make the horseradish cream, mix the crème fraîche, grated horseradish, lemon juice, salt and white pepper in a bowl. Refrigerate until serving.","To make the crispy shallots, heat some vegetable oil in a frying pan over a medium heat. Add the sliced shallots and fry until golden brown and crispy.","Remove with a slotted spoon and drain on a plate lined with kitchen paper. Season with a pinch of salt.","To make the open sandwich, bring a large saucepan of salted water to the boil, then blanch half of the asparagus (four white and four green) until tender-crisp, about 2–3 minutes.","Add ice to a bowl of cold water. Use a slotted spoon to remove the asparagus from the boiling water and immediately transfer to the iced water to stop cooking. Thinly slice the remaining asparagus lengthwise to serve raw.","Pre-heat the grill until hot. Spread the rye bread with butter and grill until golden and crisp.","To serve, place the grilled bread slices on serving plates. Arrange both the blanched and raw asparagus on the bread. Drizzle with horseradish cream, then sprinkle grated cheese over the top. Garnish with the crispy shallots and some fresh dill to finish."],"ingredient_names":["creme fraiche","horseradish","lemon juice","salt","pepper","vegetable oil","shallots","salt","white asparagus","asparagus","rye bread","butter","västerbottensost cheese","dill","salt","black pepper"],"allergens":["dairy","gluten"],"diet_flags":["pescatarian","vegetarian"]},{"source_id":"53122","title":"Fiskesuppe (Creamy Norwegian Fish Soup)","category":"Seafood","country":"Norway","tags":["Soup"],"image_url":"https://www.themealdb.com/images/media/meals/raqjbj1762773035.jpg","youtube_url":"https://www.bing.com/videos/riverview/relatedvideo?&q=Fiskesuppe+(Creamy+Norwegian+Fish+Soup)+youtube&qpvt=Fiskesuppe+(Creamy+Norwegian+Fish+Soup)+youtube&mid=BA1D06D0C6BB703F9960BA1D06D0C6BB703F9960&&mcid=1B82C46C54684D60AEB9F663316D725F&FORM=VRDGAR","source_url":"https://scandinaviancookbook.com/fiskesuppe-creamy-norwegian-fish-soup/","ingredients":[{"name":"Fish fillet","measure":"1 lb"},{"name":"Garlic","measure":"1 clove"},{"name":"Potatoes","measure":"2 medium"},{"name":"Carrots","measure":"2"},{"name":"Leek","measure":"1"},{"name":"Butter","measure":"3  tablespoons"},{"name":"Flour","measure":"5 tablespoons"},{"name":"Fish Stock","measure":"4 cups"},{"name":"Milk","measure":"1 cup"},{"name":"Creme Fraiche","measure":"1 1/4 cup"},{"name":"Shrimp","measure":"1 cup"},{"name":"Chives","measure":"1 tablespoon"}],"steps":["▢","Cut the fish fillets in cubes or strips. Crush or chop the garlic. Rinse the vegetables and cut into thin strips.","▢","Heat the butter in a pot and add the garlic. Once the garlic starts to turn golden add the flour, whisking well.","▢","Add the fish stock and continue to whisk until there are no lumps.","▢","Add the vegetables and milk and bring to a boil. Cook for about 10 minutes.","▢","Add the crème fraîche (or sour cream). Bring the soup back to a simmer and once the soup begins to bubble again turn off the heat. Keep the soup on the burner and add the fish. Let the fish cook in the hot soup for 5 minutes. If using shrimp, add right before serving.","▢","Sprinkle with chives (or dill or parsley) before serving."],"ingredient_names":["fish fillet","garlic","potatoes","carrots","leek","butter","flour","fish stock","milk","creme fraiche","shrimp","chives"],"allergens":["dairy","fish","gluten","shellfish"],"diet_flags":["pescatarian"]},{"source_id":"53123","title":"Fårikål (Norwegian National Dish)","category":"Lamb","country":"Norway","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/ttfxxn1762773067.jpg","youtube_url":"https://www.youtube.com/shorts/2mMT71Knp8E","source_url":"https://scandinaviancookbook.com/farikal-national-dish-of-norway/","ingredients":[{"name":"Lamb","measure":"3 Lbs"},{"name":"White Cabbage","measure":"1 head"},{"name":"Whole black peppercorns","measure":"3  tablespoons"},{"name":"Salt","measure":"3 tsp"},{"name":"Water","measure":"1 1/2 cups"},{"name":"Flour","measure":"5 tablespoons"}],"steps":["▢","Cut the lamb into large pieces.","▢","Slice the cabbage into large wedges, keeping the core attached.","▢","Add a layer of lamb pieces to the bottom of a large pot, fatty side down. Sprinkle with peppercorns and salt. Add a layer of cabbage wedges on top. Repeat with more layers of lamb, peppercorns, and cabbage, ending with cabbage on top.","▢","Optional: Sprinkle a couple of tablespoons on top of the lamb for a thicker stew.","▢","Add water to the pot and bring to a boil. Cover and reduce heat. Cook on low heat for 2 – 3 hours, until the lamb gently falls away from the bone.","▢","Serve with boiled potatoes and fresh parsley, covering generously with the fårikål broth."],"ingredient_names":["lamb","white cabbage","whole black peppercorns","salt","water","flour"],"allergens":["gluten"],"diet_flags":[]},{"source_id":"53124","title":"Raspeballer (Norwegian Potato Dumplings)","category":"Pork","country":"Norway","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/hhm7xy1763075871.jpg","youtube_url":"https://www.youtube.com/watch?v=2NFNabRkF04","source_url":"https://scandinaviancookbook.com/raspeballer-norwegian-potato-dumplings/","ingredients":[{"name":"Pork knuckle","measure":"1"},{"name":"Sausages","measure":"1"},{"name":"Potatoes","measure":"1 lb"},{"name":"Red Potatoes","measure":"2 Lbs"},{"name":"Flour","measure":"1 1/4 cup"},{"name":"All purpose flour","measure":"2 tblsp"},{"name":"Salt","measure":"1 teaspoon"},{"name":"Bouillon Cubes","measure":"4"},{"name":"Freshly Chopped Parsley","measure":"Pinch"},{"name":"Swede","measure":"1"},{"name":"Carrots","measure":"2"},{"name":"Cream","measure":"1/4 cup"},{"name":"Butter","measure":"1 tblsp"},{"name":"Nutmeg","measure":"1 teaspoon"}],"steps":["Raspeballer & (Optional) Salted Meat","▢","If you're making pork knuckle, cook it in simmering water for about 3 hours, until the meat falls from the bone. Remove the pork and save the broth to cook the raspeballer.","▢","Boil the boiled potatoes and peel once cooled. Also peel the raw potatoes, and then grate them or run them through a food processor. Use a paper towel to remove some of the moisture from the grated potatoes.","▢","Mash the boiled potatoes in a potato ricer or with a masher. Make sure there are no lumps. Add the grated raw potatoes to the mashed potatoes in a large mixing bowl and stir together. Add the barley flour, all purpose flour, and salt and mix together with your hands until the mixture is fully blended.","▢","You can cook the raspeballer in either vegetable or beef broth, or if you're making pork knuckle, cook them in the broth from the pork knuckle. Bring the broth to a very light simmer – you don't want it to fully boil because then the raspeballer might break apart.","▢","Use a tablespoon dipped in cold water to shape each raspeball in your hand. Try to make them as smooth as possible and then gently drop them into the simmering broth. Dip the tablespoon in a bowl of cold water between each raspeball.","▢","Let the raspeballer simmer for about 30 minutes. If you're making smoked sausage, you can heat the sausage in the same pot with the raspeballer. Top with fresh chopped parsley.","Mashed Rutabaga","▢","Peel the rutabaga and carrots and cut into small pieces. Boil in water for about 30 minutes, or until tender. Then drain the water, add the cream/milk, butter and nutmeg and mash until smooth.","▢","Serve alongside the raspeballer and meat."],"ingredient_names":["pork knuckle","sausages","potatoes","red potatoes","flour","all purpose flour","salt","bouillon cubes","freshly chopped parsley","swede","carrots","cream","butter","nutmeg"],"allergens":["dairy","gluten"],"diet_flags":[]},{"source_id":"53125","title":"Karbonader (Lean Beef Patties) with Caramelized Onions","category":"Beef","country":"Norway","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/0bpjb11763075817.jpg","youtube_url":"https://www.youtube.com/watch?v=HDWgGMJqvgw","source_url":"https://scandinaviancookbook.com/karbonader/","ingredients":[{"name":"Onion","measure":"2"},{"name":"Butter","measure":"1 tablespoon"},{"name":"Ground Beef","measure":"1 lb"},{"name":"Salt","measure":"1/2 teaspoon"},{"name":"Pepper","measure":"1/2 teaspoon"},{"name":"Nutmeg","measure":"1/2 teaspoon"},{"name":"Cornstarch","measure":"1/2 tbs"},{"name":"Water","measure":"50 ml"},{"name":"Butter","measure":"2 tblsp"}],"steps":["Grate half an onion and set aside. Slice the rest of the onions and fry in butter on low/medium heat until caramelized.","▢","In a bowl, mix together ground beef, grated onion, salt, pepper, nutmeg, potato/corn starch, and water.","▢","Form into a sausage and cut 6 patties. Using a knife make a light grid pattern in each patty.","▢","Brown both sides of the karbonader in butter on high heat, then turn down to low heat and fry for another 2 – 3 minutes.","▢","Serve the karbonader and onions with potatoes, stewed peas, and brown sauce for dinner, or on a slice of bread for lunch or a snack."],"ingredient_names":["onion","butter","ground beef","salt","pepper","nutmeg","cornstarch","water","butter"],"allergens":["dairy"],"diet_flags":[]},{"source_id":"53126","title":"Brun Lapskaus (Norwegian Beef Vegetable Stew)","category":"Beef","country":"Norway","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/6vi2cv1763075785.jpg","youtube_url":"https://www.youtube.com/watch?v=VuLnP0Yu84o","source_url":"https://scandinaviancookbook.com/brun-lapskaus-norwegian-beef-vegetable-root-stew/","ingredients":[{"name":"Olive Oil","measure":"2 tblsp"},{"name":"Beef","measure":"2 Lbs"},{"name":"Onion","measure":"1"},{"name":"Beef Stock","measure":"3 Cups"},{"name":"Swede","measure":"1 small"},{"name":"Celery","measure":"1"},{"name":"Carrots","measure":"4"},{"name":"Parsley","measure":"4"},{"name":"Potatoes","measure":"1 lb"},{"name":"Leek","measure":"1/2"},{"name":"Parsley","measure":"Garnish"}],"steps":["▢","Heat olive oil in a large pot. Cut beef into 1 inch (2.5 cm) cubes and brown in oil.","▢","Dice the onion and add to browning beef. Add the stock and bring to a boil, then lower the heat, cover, and let simmer for about 30 minutes.","▢","Peel and cut the rutabaga and celery root into 1 inch (2.5 cm) cubes. Add to the pot, cover, and continue simmering for another 30 minutes.","▢","Peel and chop the rest of the vegetables into 1 inch (2.5 cm) cubes and add to the pot. Slice the leek into rings. Cover and continue simmering for about 20 minutes. Stir as little as possible.","▢","Top with fresh parsley."],"ingredient_names":["olive oil","beef","onion","beef stock","swede","celery","carrots","parsley","potatoes","leek","parsley"],"allergens":[],"diet_flags":[]},{"source_id":"53133","title":"Asado","category":"Beef","country":"Argentina","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/kgfh3q1763075438.jpg","youtube_url":"https://www.youtube.com/watch?v=q5f6Z6i1hQ8","source_url":"https://www.munchery.com/blog/the-ten-iconic-dishes-of-argentina-and-how-to-cook-them-at-home/","ingredients":[{"name":"Mixed Beef Cuts","measure":"2kg"},{"name":"Chorizo","measure":"4"},{"name":"Morcilla","measure":"2"},{"name":"Salt","measure":"To taste"}],"steps":["Prepare the Fire: Start a wood fire in your grill and let it burn down to coals.","Season the Meat: Generously salt the beef cuts.","Grill the Meat: Place the beef on the grill, starting with the thickest cuts farthest from the coals. Add chorizo and morcilla after the beef has been cooking for a while.","Cook to Perfection: Cook the meat, turning occasionally, until it reaches your desired doneness. Typically, ribs may take up to 2 hours; thinner cuts will cook faster.","Rest and Serve: Let the meat rest for about 10 minutes before slicing. Serve with chimichurri sauce and grilled vegetables.","Pro Tips:","Use a mix of wood and charcoal for a consistent heat source. Wood adds flavor, while charcoal maintains temperature.","Season the meat just before grilling to ensure it retains its moisture and flavor.","Serving Suggestions:","Serve with a side of chimichurri sauce, a fresh tomato salad, and crusty bread. Pair with a robust Malbec wine to complement the rich flavors of the meat."],"ingredient_names":["mixed beef cuts","chorizo","morcilla","salt"],"allergens":[],"diet_flags":[]},{"source_id":"53134","title":"Empanadas","category":"Beef","country":"Argentina","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/q99te31763075494.jpg","youtube_url":"https://www.youtube.com/watch?v=RRNVLC6IAv4","source_url":"https://www.munchery.com/blog/the-ten-iconic-dishes-of-argentina-and-how-to-cook-them-at-home/","ingredients":[{"name":"All purpose flour","measure":"500g"},{"name":"Butter","measure":"200g"},{"name":"Water","measure":"120ml"},{"name":"Salt","measure":"1 tsp"},{"name":"Ground Beef","measure":"500g"},{"name":"Onion","measure":"2 chopped"},{"name":"Egg","measure":"4 Chopped"},{"name":"Green Olives","measure":"100g"},{"name":"Cumin","measure":"1 teaspoon"},{"name":"Paprika","measure":"1 teaspoon"},{"name":"Salt","measure":"To taste"},{"name":"Pepper","measure":"To taste"}],"steps":["Make the Dough: Mix flour and salt in a large bowl. Add butter, using your fingers to blend into a crumbly texture. Gradually add water, mixing until a dough forms. Wrap and chill for 30 minutes.","Prepare the Filling: Cook onions in a pan until translucent. Add ground beef, cooking until browned. Stir in spices, then remove from heat. Once cooled, mix in eggs and olives.","Assemble: Roll out the dough and cut into circles. Place a spoonful of filling in each, fold over, and seal the edges.","Cook: Bake at 200°C (400°F) for 20-25 minutes, or until golden.","Pro Tips:","For a flakier crust, incorporate a tablespoon of vinegar into the dough mixture. This helps prevent gluten formation.","Seal the edges of the empanadas with a fork to ensure they do not open during baking or frying."],"ingredient_names":["all purpose flour","butter","water","salt","ground beef","onion","egg","green olives","cumin","paprika","salt","pepper"],"allergens":["dairy","eggs","gluten"],"diet_flags":[]},{"source_id":"53135","title":"Milanesa","category":"Beef","country":"Argentina","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/wdfa171763065079.jpg","youtube_url":"https://www.youtube.com/watch?v=_G3cyucbB3o","source_url":"https://www.munchery.com/blog/the-ten-iconic-dishes-of-argentina-and-how-to-cook-them-at-home/","ingredients":[{"name":"Beef Cutlet","measure":"4"},{"name":"Egg","measure":"2 Beaten"},{"name":"Breadcrumbs","measure":"200g"},{"name":"Parsley","measure":"2 tbs chopped"},{"name":"Garlic","measure":"2 cloves minced"},{"name":"Salt","measure":"To taste"},{"name":"Pepper","measure":"To taste"}],"steps":["Season the Cutlets: Salt and pepper the cutlets.","Bread the Cutlets: Dip each cutlet in egg, then coat with a mixture of breadcrumbs, parsley, and garlic.","Fry: Heat oil in a large pan over medium heat. Fry the cutlets until golden and cooked through, about 3-4 minutes per side.","Serve: Serve hot with lemon wedges or a side salad.","Pro Tips:","For an extra crispy crust, use panko breadcrumbs mixed with finely grated Parmesan cheese.","Gently pound the cutlets to an even thickness for uniform cooking."],"ingredient_names":["beef cutlet","egg","breadcrumbs","parsley","garlic","salt","pepper"],"allergens":["eggs","gluten"],"diet_flags":[]},{"source_id":"53136","title":"Choripán","category":"Pork","country":"Argentina","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/5i25sg1763075353.jpg","youtube_url":"https://www.youtube.com/watch?v=FNrU5mQKFOE","source_url":"https://www.munchery.com/blog/the-ten-iconic-dishes-of-argentina-and-how-to-cook-them-at-home/","ingredients":[{"name":"Chorizo","measure":"4"},{"name":"Crusty Bread","measure":"4"},{"name":"Chimichurri sauce","measure":"Drizzle"}],"steps":["Grill the Chorizos: Cook the chorizos on a grill or pan until fully cooked, about 10-15 minutes.","Prepare the Rolls: Slice the rolls and toast them lightly on the grill or in a pan.","Assemble: Slice each chorizo lengthwise and place in a roll. Top with a generous amount of chimichurri sauce.","Serve: Enjoy immediately while hot.","Pro Tips:","Grill the chorizo slowly on medium heat to prevent the skin from bursting and to ensure it cooks evenly throughout.","Toast the bread on the grill to absorb some of the chorizo's flavors."],"ingredient_names":["chorizo","crusty bread","chimichurri sauce"],"allergens":["gluten"],"diet_flags":[]},{"source_id":"53140","title":"Matambre a la Pizza","category":"Beef","country":"Argentina","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/wf49qs1763075222.jpg","youtube_url":"https://www.youtube.com/watch?v=X5UxDaNHD30","source_url":"https://www.munchery.com/blog/the-ten-iconic-dishes-of-argentina-and-how-to-cook-them-at-home/","ingredients":[{"name":"Beef Flank Steak","measure":"1 kg"},{"name":"Tomato Sauce","measure":"200g"},{"name":"Mozzarella","measure":"200g"},{"name":"Oregano","measure":"1 tbsp"},{"name":"Green Olives","measure":"100g"},{"name":"Salt","measure":"To taste"},{"name":"Pepper","measure":"To taste"}],"steps":["Prepare the Steak: Season the steak with salt and pepper. Grill one side until half-cooked.","Add Toppings: Spread tomato sauce over the cooked side, then add cheese, oregano, and olives.","Finish Grilling: Grill until the cheese is melted and bubbly.","Serve: Slice and serve hot.","Pro Tips:","Tenderize the matambre by scoring it lightly on both sides. This helps it cook more evenly and absorb the flavors.","Precook the matambre on the grill before adding the toppings to ensure it's fully cooked without burning the cheese."],"ingredient_names":["beef flank steak","tomato sauce","mozzarella","oregano","green olives","salt","pepper"],"allergens":["dairy"],"diet_flags":[]},{"source_id":"53141","title":"Carbonada Criolla","category":"Beef","country":"Argentina","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/8b2msz1763074897.jpg","youtube_url":"https://www.youtube.com/watch?v=MSyvKDBXuKQ","source_url":"https://www.munchery.com/blog/the-ten-iconic-dishes-of-argentina-and-how-to-cook-them-at-home/","ingredients":[{"name":"Beef","measure":"500g"},{"name":"Onion","measure":"1 chopped"},{"name":"Carrots","measure":"2 chopped"},{"name":"Potatoes","measure":"2 chopped"},{"name":"Pumpkin","measure":"1 small"},{"name":"Dried Apricots","measure":"100g"},{"name":"Beef Stock","measure":"2 Litres"},{"name":"Salt","measure":"To taste"},{"name":"Pepper","measure":"To taste"}],"steps":["Brown the Beef: In a large pot, brown the beef cubes. Remove and set aside.","Sauté Vegetables: In the same pot, cook the onion until translucent. Add carrots, potatoes, and pumpkin, cooking for a few minutes.","Simmer: Return the beef to the pot. Add broth and dried apricots. Season with salt and pepper. Simmer for 1-2 hours, until the beef is tender.","Serve: Enjoy hot, with a crusty piece of bread.","Pro Tips:","Brown the beef in batches to ensure it gets a good sear, which adds depth to the stew's flavor.","Adding the fruits towards the end of cooking preserves their texture and adds a subtle sweetness to the dish."],"ingredient_names":["beef","onion","carrots","potatoes","pumpkin","dried apricots","beef stock","salt","pepper"],"allergens":[],"diet_flags":[]},{"source_id":"53142","title":"Spiced tortilla","category":"Vegetarian","country":"Spain","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/7b862e1763194846.jpg","youtube_url":null,"source_url":"https://www.bbcgoodfood.com/recipes/spiced-tortilla","ingredients":[{"name":"Sunflower Oil","measure":"1 tbsp"},{"name":"Onion","measure":"1"},{"name":"Red Chilli","measure":"1"},{"name":"Curry Powder","measure":"2 teaspoon"},{"name":"Cherry Tomatoes","measure":"300g"},{"name":"Potatoes","measure":"500g"},{"name":"Coriander","measure":"Bunch"},{"name":"Egg","measure":"8"}],"steps":["Heat the oil in a large frying pan.","Fry the onion and half the chilli for 5 mins until softened.","Tip in the spices, fry for 1 min more, then add the cherry tomatoes, potatoes and coriander stalks to the pan.","Season the eggs well, pour over the top of the veg and leave to cook gently for 8-10 mins until almost set.","Heat the grill and flash the tortilla underneath for 1-2 mins until the top is set.","Scatter the coriander leaves and remaining chilli over the top, slice into wedges and serve with a green salad."],"ingredient_names":["sunflower oil","onion","red chilli","curry powder","cherry tomatoes","potatoes","coriander","egg"],"allergens":["eggs"],"diet_flags":["pescatarian","vegetarian"]},{"source_id":"53143","title":"Easy Spanish chicken","category":"Chicken","country":"Spain","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/kzxflc1763194887.jpg","youtube_url":"https://www.youtube.com/watch?v=EusTpzrqYK4","source_url":"https://www.bbcgoodfood.com/recipes/easy-spanish-chicken","ingredients":[{"name":"Extra Virgin Olive Oil","measure":"2 tbsp"},{"name":"Onion","measure":"1"},{"name":"Chorizo","measure":"150g"},{"name":"Red Pepper","measure":"1"},{"name":"Yellow Pepper","measure":"1"},{"name":"sweet smoked paprika","measure":"1 teaspoon"},{"name":"Garlic","measure":"4 cloves"},{"name":"Tinned Tomatos","measure":"400g"},{"name":"Green Olives","measure":"150g"},{"name":"Butter Beans","measure":"400g"},{"name":"Chicken Thighs","measure":"8"},{"name":"Parsley","measure":"1 Handfull"}],"steps":["Heat the oven to 200C/180C fan/gas 6. Heat the olive oil in a large ovenproof frying pan over a medium heat and fry the onion, chorizo and peppers along with a pinch of salt and pepper for 15 mins until the veg has softened and the chorizo has released its oils. Add the paprika and garlic, and cook for another few minutes until fragrant.","Tip in the chopped tomatoes, olives and butter beans, stir to combine and season. Nestle in the chicken thighs and season well. Transfer to the oven and bake for 40 mins until the chicken skin is crisp and the meat cooked through and tender. Scatter with the parsley and serve.","Watch after ad (0.04):","3 Budget Egg Ideas"],"ingredient_names":["extra virgin olive oil","onion","chorizo","red pepper","yellow pepper","sweet smoked paprika","garlic","tinned tomatos","green olives","butter beans","chicken thighs","parsley"],"allergens":[],"diet_flags":[]},{"source_id":"53144","title":"Gambas al ajillo","category":"Seafood","country":"Spain","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/ze8uwg1763196123.jpg","youtube_url":"https://www.youtube.com/watch?v=2tZlO8vNMtk","source_url":"https://www.bbcgoodfood.com/recipes/gambas-al-ajillo","ingredients":[{"name":"Raw King Prawns","measure":"12"},{"name":"Garlic Clove","measure":"3"},{"name":"Olive Oil","measure":"100 ml"},{"name":"Cayenne Pepper","measure":"3"},{"name":"Parsley","measure":"1 tablespoon chopped"}],"steps":["Peel the prawns, leaving the tails intact, and, using a cocktail stick, remove the digestive tracts.","Or, if you are using a frying pan rather than a terracotta pot, you can cook the prawns in their shells.","Season with a little sea salt.","Put the garlic, olive oil and chillies in a flameproof terracotta pot or frying pan and set over a high heat.","When the garlic starts to turn golden, add the prawns and cook for 1-2 mins on each side until just pink.","Sprinkle over the chopped parsley and some freshly cracked black pepper, and serve immediately.","If using a terracotta pot, you can take that straight to the table, but be careful with it as the oil and terracotta will remain hot for several minutes."],"ingredient_names":["raw king prawns","garlic clove","olive oil","cayenne pepper","parsley"],"allergens":["shellfish"],"diet_flags":["pescatarian"]},{"source_id":"53145","title":"Jamon & wild garlic croquetas","category":"Pork","country":"Spain","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/zc9cwz1763196177.jpg","youtube_url":"https://www.youtube.com/watch?v=YFMDkUsMazw","source_url":"https://www.bbcgoodfood.com/recipes/jamon-wild-garlic-croquetas","ingredients":[{"name":"Wild Garlic Leaves","measure":"150g"},{"name":"Milk","measure":"350g"},{"name":"Olive Oil","measure":"45g"},{"name":"Flour","measure":"65g"},{"name":"manchego","measure":"35g"},{"name":"jamón ibérico","measure":"80g"},{"name":"Egg","measure":"1"},{"name":"Breadcrumbs","measure":"75g"},{"name":"Vegetable Oil","measure":"1 L"}],"steps":["Wash the wild garlic leaves well in a colander, then pour over boiling water from the kettle until just wilted. Immediately rinse under cold running water, then squeeze out the excess water and finely chop.","Warm the milk in a pan over a low heat until just steaming. Heat the oil or butter in a second pan and, once warm or melted, stir in the flour for a couple of minutes until it starts to brown a little. Gradually add the warm milk, a little at a time, until you have a thick, silky sauce. Bubble for a minute or two, stirring to make sure all the flour has cooked out. Season.","Add the manchego, jamón and wild garlic to the pan, and beat to combine. Tip out onto a lightly oiled baking tray or plate, spread out then cover and chill for at least 1 hr. Will keep chilled for up to 24 hrs.","Lightly oil your hands and shape the mixture into 18-20 even-sized balls. Arrange on a baking tray and freeze for 30 mins to firm up.","Beat the egg in a shallow dish with a little seasoning. Tip the panko into a second dish. Dip each of the croquetas in the egg, then turn to coat in the breadcrumbs. At this point, the raw croquetas can be frozen for up to three months. Pour the oil into a large, deep pan ensuring it is no more than a third full and heat to 170C, or until a cube of bread browns lightly in 30 seconds. Fry the croquetas in batches for 2-3 mins until deeply golden. To cook from frozen, fry at 160C for a few minutes longer until they’re piping hot inside. Remove to a sheet of kitchen paper using a slotted spoon and leave to drain. Serve warm with a glass of sherry."],"ingredient_names":["wild garlic leaves","milk","olive oil","flour","manchego","jamón ibérico","egg","breadcrumbs","vegetable oil"],"allergens":["dairy","eggs","gluten"],"diet_flags":[]},{"source_id":"53147","title":"Arroz con gambas y calamar","category":"Seafood","country":"Spain","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/jc6oub1763196663.jpg","youtube_url":"https://www.youtube.com/watch?v=nFFp0ebOlOo","source_url":"https://www.bbcgoodfood.com/recipes/arroz-con-gambas-y-calamar","ingredients":[{"name":"Raw King Prawns","measure":"24"},{"name":"Olive Oil","measure":"2 tbsp"},{"name":"Onion","measure":"1 small"},{"name":"Bay Leaf","measure":"1"},{"name":"Saffron","measure":"1 pinch"},{"name":"Paella Rice","measure":"450g"},{"name":"Tomato Puree","measure":"2 teaspoons"},{"name":"White Wine","measure":"200ml"},{"name":"Seafood stock","measure":"650ml"},{"name":"Squid","measure":"3 Medium"}],"steps":["Peel and devein most of the prawns (a fishmonger should be able to do this for you), keeping a few whole for decoration, if you like. Heat the olive oil in a large frying pan or shallow flameproof casserole over a medium-low heat and fry the onion for 5 mins until softened. Add the bay leaf, saffron, rice and tomato purée, and cook for 1-2 mins more, stirring.","Pour in the wine and bubble for 1-2 mins, then pour in the seafood stock and 150ml water. Cook for 5 mins, then add the squid, season well and stir to combine. Bring to the boil, then cover and reduce the heat to a gentle simmer. Cook for 12 mins more, adding a little more water if the mixture starts to look dry.","Uncover the pan and stir through the peeled prawns, then arrange any whole prawns on top of the rice mixture. Cover again and simmer for a further 5-6 mins until the prawns are pink and cooked through. Leave to stand for a couple of minutes before serving from the pan."],"ingredient_names":["raw king prawns","olive oil","onion","bay leaf","saffron","paella rice","tomato puree","white wine","seafood stock","squid"],"allergens":["fish","shellfish"],"diet_flags":["pescatarian"]},{"source_id":"53151","title":"Paella","category":"Seafood","country":"Spain","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/9bl20p1763248192.jpg","youtube_url":"https://www.youtube.com/watch?v=vNBuXsTY15E","source_url":"https://www.bbcgoodfood.com/recipes/next-level-paella","ingredients":[{"name":"Olive Oil","measure":"3 tablespoons"},{"name":"Raw tiger prawns","measure":"10"},{"name":"Parsley","measure":"Bunch"},{"name":"Dry sherry","measure":"100 ml"},{"name":"Mussels","measure":"500g"},{"name":"Saffron","measure":"Pinch"},{"name":"Chorizo","measure":"150g"},{"name":"Onion","measure":"1 chopped"},{"name":"Garlic","measure":"3 cloves"},{"name":"Squid","measure":"1 medium"},{"name":"Tomato","measure":"2"},{"name":"Paella Rice","measure":"250g"},{"name":"Broad Beans","measure":"100g"},{"name":"Lemon Zest","measure":"1"}],"steps":["Heat 1 tbsp of the oil in a wide, shallow pan. Add the prawn heads and parsley stalks and sizzle until the heads turn pink, then mash with a potato masher. Pour over the sherry or wine and 300ml water, season with salt and simmer for 10 mins to make a stock, mashing the prawn heads as they cook.","Scatter the mussels into the pan, cover the pan loosely with a lid or tea towel, then put over a high heat for 3-4 mins until the mussels just open. Stir to release the mussel juices, then pour the contents of the pan into a colander set over a large bowl containing the saffron. Let the saffron steep in the stock – you will need 700ml in total, so top up with water if needed and give everything a good stir. Pick the mussels out from the colander, then set aside.","Wipe out the pan and add the rest of the olive oil. Sizzle the chorizo until it releases its oil, then add the onion and garlic and cook until softened. Add the squid and turn over until it turns white. Add the tomatoes and cook down for a minute, then pour over most of the stock, give everything a good stir and bring to the boil. Scatter the rice over the stock, stir well once, then boil vigorously for 5 mins. Reduce the heat to the lowest setting and slowly simmer for 10 mins without stirring until the rice has absorbed most of the liquid.","Tuck the prawn tails into the rice and simmer for 5 mins, turning them over until cooked through. Stir through the mussels and broad beans or peas. Taste the rice – if it is still a little raw but the pan is dry, add a splash more stock and continue to cook; if it’s too soupy, then increase the heat to cook off the last of the stock.","Once the rice is just cooked, turn off the heat and cover with a tea towel for a few minutes. Scatter over the parsley leaves and lemon zest, then season with smoked salt if you like. Stir everything once, then serve straight from the pan, with lemon wedges on the side."],"ingredient_names":["olive oil","raw tiger prawns","parsley","dry sherry","mussels","saffron","chorizo","onion","garlic","squid","tomato","paella rice","broad beans","lemon zest"],"allergens":["shellfish"],"diet_flags":[]},{"source_id":"53152","title":"Pan-fried hake, white bean & chorizo broth","category":"Seafood","country":"Spain","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/4yjart1763248459.jpg","youtube_url":"https://www.youtube.com/watch?v=6hcNBBob_xI","source_url":"https://www.bbcgoodfood.com/recipes/pan-fried-hake-white-bean-chorizo-broth","ingredients":[{"name":"Dried white beans","measure":"450g"},{"name":"Garlic","measure":"4 cloves"},{"name":"Bay Leaves","measure":"2"},{"name":"Thyme","measure":"1 teaspoon"},{"name":"Olive Oil","measure":"6 tablespoons"},{"name":"Bread","measure":"100g"},{"name":"Chorizo","measure":"100g"},{"name":"Onion","measure":"1"},{"name":"Paprika","measure":"3 tsp"},{"name":"Chicken Stock","measure":"1 L"},{"name":"Parsley","measure":"Handful"},{"name":"Hake","measure":"6"}],"steps":["Drain the beans, then tip into a large pan with 2 litres of water. Simmer with the whole garlic cloves, bay leaves and thyme for 30 mins or until cooked and tender. Remove from the heat and set aside.","Meanwhile, heat 2 tbsp oil in a frying pan. Fry the bread with the remaining garlic clove. When golden and crisp, scoop out and drain on kitchen paper. Add the chorizo to the pan, fry until crisp, tip out and keep warm with the bread.","Add another 2 tbsp oil and the onion to the pan, and cook for 5 mins until softened. Stir in the paprika. Drain the beans and add to the onions with the chicken stock and 2 tsp salt. Cook for 5-10 mins. Stir through the parsley and keep warm.","Season the hake and heat the remaining 2 tbsp oil in the frying pan. Put the hake, skin-side down, in the pan and cook for 3-5 mins over a mediumhigh heat to crisp up the skin. Flip the fish over and cook for a further 3-5 mins until cooked through. Spoon the white bean mix into bowls, place the hake on top and finish with the fried bread, chorizo and a little more thyme."],"ingredient_names":["dried white beans","garlic","bay leaves","thyme","olive oil","bread","chorizo","onion","paprika","chicken stock","parsley","hake"],"allergens":["fish","gluten"],"diet_flags":[]},{"source_id":"53154","title":"Clam, chorizo & white bean stew","category":"Seafood","country":"Spain","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/92wbmf1763252334.jpg","youtube_url":"https://www.youtube.com/watch?v=IoRuT7TxDAo","source_url":"https://www.bbcgoodfood.com/recipes/clam-chorizo-white-bean-stew","ingredients":[{"name":"Chorizo","measure":"50g"},{"name":"Onion","measure":"1 chopped"},{"name":"Garlic Clove","measure":"1"},{"name":"Parsley","measure":"Bunch"},{"name":"Vegetable Stock","measure":"200ml"},{"name":"Tinned Tomatos","measure":"400g"},{"name":"Butter Beans","measure":"400g"},{"name":"Sherry vinegar","measure":"1 teaspoon"},{"name":"Clams","measure":"600g"},{"name":"Crusty Bread","measure":"To serve"}],"steps":["Fry the chorizo in a large frying pan with a lid, over a medium heat until it is starting to crisp up and release its oil. Add the onion and cook for 5 mins until starting to soften. Then add the garlic and finely chopped parsley, and fry for 1 min more.","Pour on the stock and tomatoes. Bring to the boil, reduce the heat, then add the beans and sherry vinegar. Simmer for 10 mins until the liquid is slightly reduced.","Scatter over the clams, cover with the lid and steam for 2-4 mins, shaking the pan occasionally until the clams are open. Have a little taste before seasoning, as the clams can be quite salty. Then scatter over the chopped parsley. Eat with lots of crusty bread."],"ingredient_names":["chorizo","onion","garlic clove","parsley","vegetable stock","tinned tomatos","butter beans","sherry vinegar","clams","crusty bread"],"allergens":["gluten","shellfish"],"diet_flags":[]},{"source_id":"53155","title":"Spanish chicken pie","category":"Chicken","country":"Spain","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/8ovxf41763253962.jpg","youtube_url":null,"source_url":"https://www.bbcgoodfood.com/recipes/spanish-chicken-pie","ingredients":[{"name":"Potatoes","measure":"1 kg"},{"name":"Paprika","measure":"3 tsp"},{"name":"Olive Oil","measure":"2 teaspoons"},{"name":"Onion","measure":"2 sliced"},{"name":"Garlic","measure":"2 cloves minced"},{"name":"Tinned Tomatos","measure":"800g"},{"name":"Chicken","measure":"300g"},{"name":"Roasted pepper","measure":"140g"},{"name":"Green Olives","measure":"Handful"}],"steps":["Heat oven to 200C/fan 180C/gas 6. Boil the potatoes for 15-20 mins until tender. Drain, return to the pan, then mash with some seasoning and 2 tsp of the paprika.","Meanwhile, heat the oil in a large pan, then fry the onions and garlic for a few mins until softened. Stir in the remaining paprika for 1 min, add the tomatoes , then, bring to a simmer. Tip into a large ovenproof dish, then stir in the chicken, peppers, olives and some seasoning.","Spoon over the mash, then bake for 15 mins until the mash is golden on top and the sauce is bubbling."],"ingredient_names":["potatoes","paprika","olive oil","onion","garlic","tinned tomatos","chicken","roasted pepper","green olives"],"allergens":[],"diet_flags":[]},{"source_id":"53156","title":"Arroz al horno (baked rice)","category":"Pork","country":"Spain","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/qt4i0n1763256454.jpg","youtube_url":"https://www.youtube.com/watch?v=f-waAIrn2iA","source_url":"https://www.bbcgoodfood.com/recipes/arroz-al-horno-baked-rice","ingredients":[{"name":"Extra Virgin Olive Oil","measure":"2 tbsp"},{"name":"Pork belly slices","measure":"800g"},{"name":"Black Pudding","measure":"150g"},{"name":"Bacon lardon","measure":"100g"},{"name":"Onion","measure":"1 chopped"},{"name":"Red Pepper","measure":"2"},{"name":"Plum Tomatoes","measure":"1 chopped"},{"name":"Garlic Clove","measure":"8"},{"name":"Paprika","measure":"4 teaspoons"},{"name":"Chilli Flakes","measure":"1/2 teaspoon"},{"name":"Dried white beans","measure":"200g"},{"name":"Chicken Stock","measure":"1 1/2 L"},{"name":"Thyme","measure":"6 parts"},{"name":"Paella Rice","measure":"375g"},{"name":"Lemon Juice","measure":"1"}],"steps":["Heat oven to 200C/180C/gas 6. Heat half the oil in a deep frying or sauté pan (or shallow casserole dish) measuring around 30cm in diameter. Over a high heat, colour the pork belly slices on each side in several batches, then transfer to a bowl. Add the remaining oil to the pan and lower the heat to medium, then add the black pudding and bacon and fry all over for several mins. Remove with a slotted spoon. Fry the onion and peppers for around 10 mins until soft and pale gold, then add the tomato and cook until soft. Add the garlic, smoked paprika and chilli flakes and cook for another 2 mins, then put the pork, black pudding and bacon back in the pan. Add the beans, stock and whichever herb you're using, and bring everything to the boil.","Sprinkle the rice around the pork belly, pushing it underneath the stock. Let the stock come to the boil again, season well, then transfer to the oven (leave it uncovered). Cook for 20 mins without stirring, then check to see how the rice is doing. The rice should be tender and the stock absorbed. If it’s not ready, put back in the oven for another 5 mins, then check again. Taste for seasoning.","Squeeze lemon juice over the top and drizzle over some extra virgin olive oil just before serving, if you like."],"ingredient_names":["extra virgin olive oil","pork belly slices","black pudding","bacon lardon","onion","red pepper","plum tomatoes","garlic clove","paprika","chilli flakes","dried white beans","chicken stock","thyme","paella rice","lemon juice"],"allergens":[],"diet_flags":[]},{"source_id":"53157","title":"Chorizo & soft-boiled egg salad","category":"Pork","country":"Spain","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/v8eaed1763257313.jpg","youtube_url":"https://www.youtube.com/watch?v=PfAjfn5dYHE","source_url":"https://www.bbcgoodfood.com/recipes/chorizo-soft-boiled-egg-salad","ingredients":[{"name":"Baby New Potatoes","measure":"500g"},{"name":"Egg","measure":"4"},{"name":"Green Beans","measure":"225g"},{"name":"Chorizo","measure":"225g"},{"name":"Garlic Clove","measure":"1 sliced"},{"name":"Sherry vinegar","measure":"2 tbsp"},{"name":"Parsley","measure":"2 tbsp chopped"}],"steps":["Cook the potatoes in a large pan of boiling salted water for 12 mins, adding the eggs after 6 mins, and the beans for the final 2 mins. Drain everything and cool the eggs under cold running water.","Meanwhile fry chorizo slices for 1-2 mins, until beginning to crisp. Remove from the pan with a slotted spoon and set aside, leaving the oil from the chorizo in the pan. Add the garlic to the pan and cook gently for 1 min.","Remove the pan from the heat, stir in the vinegar and parsley, then toss with the potatoes, beans, chorizo and seasoning. Shell the eggs, cut into quarters and add to the salad."],"ingredient_names":["baby new potatoes","egg","green beans","chorizo","garlic clove","sherry vinegar","parsley"],"allergens":["eggs"],"diet_flags":[]},{"source_id":"53158","title":"Air fryer patatas bravas","category":"Vegetarian","country":"Spain","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/3m8yae1763257951.jpg","youtube_url":"https://www.youtube.com/watch?v=kzLaw6PG2UY","source_url":"https://www.bbcgoodfood.com/recipes/air-fryer-patatas-bravas","ingredients":[{"name":"Potatoes","measure":"900g"},{"name":"Olive Oil","measure":"3  tablespoons"},{"name":"Onion","measure":"1 chopped"},{"name":"Garlic","measure":"1 clove peeled crushed"},{"name":"Paprika","measure":"1 tblsp"},{"name":"Tomato Puree","measure":"1 tblsp"},{"name":"Tinned Tomatos","measure":"225g"},{"name":"Basil Leaves","measure":"To serve"}],"steps":["Soak the potatoes in just-boiled water for 30 mins, then drain and leave to air-dry for 5 mins. Heat the air fryer to 200C. Tip the potatoes into a bowl and drizzle over 1 tbsp of the oil and add 1/2 tsp each of salt and freshly ground black pepper. Mix to coat the potatoes all over, then tip into the air fryer basket and cook for 20-30 mins until crisp and golden.","Meanwhile, heat the remaining oil in a small pan over a medium-low heat and fry the onion for 8-10 mins until softened but not golden. Stir in the garlic and cook for a minute before adding the paprika and cooking for 30 seconds more. Stir in the tomato purée, cook for 1 min, then tip in the chopped tomatoes. Cook for 5-10 mins over a medium heat until thickened slightly.","Once the potatoes are cooked, tip out onto a platter and pour over the tomato sauce. Sprinkle with the basil leaves, then serve."],"ingredient_names":["potatoes","olive oil","onion","garlic","paprika","tomato puree","tinned tomatos","basil leaves"],"allergens":[],"diet_flags":["pescatarian","vegan","vegetarian"]},{"source_id":"53159","title":"Chorizo, potato & cheese omelette","category":"Pork","country":"Spain","tags":["Cheesy"],"image_url":"https://www.themealdb.com/images/media/meals/0y6uvc1763258983.jpg","youtube_url":"https://www.youtube.com/watch?v=K2Ba5BWYXUU","source_url":"https://www.bbcgoodfood.com/recipes/chorizo-potato-cheese-omelette","ingredients":[{"name":"Potatoes","measure":"1 small"},{"name":"Olive Oil","measure":"1 teaspoon"},{"name":"Chorizo","measure":"50g"},{"name":"Egg","measure":"3"},{"name":"Parsley","measure":"Chopped"},{"name":"Cheddar Cheese","measure":"25g"}],"steps":["Cook the potato in boiling water for 8-10 mins or until tender.","Drain and allow to steam-dry.","Heat oil in an omelette pan, add chorizo and cook for 2 mins.","Add the potato and cook for a further 5 mins until the potato starts to crisp.","Spoon pan contents out, wipe pan and cook a 2 or 3-egg omelette in the same pan.","When almost cooked, scatter with the chorizo and potato, parsley and cheese.","Fold the omelette in the pan and cook for 1 min more to melt the cheese."],"ingredient_names":["potatoes","olive oil","chorizo","egg","parsley","cheddar cheese"],"allergens":["dairy","eggs"],"diet_flags":[]},{"source_id":"53160","title":"Pisto con huevos","category":"Vegetarian","country":"Spain","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/0nswfe1763279040.jpg","youtube_url":"https://www.youtube.com/shorts/T43aUS9bG_0","source_url":"https://www.bbcgoodfood.com/recipes/pisto-con-huevos","ingredients":[{"name":"Olive Oil","measure":"2 tblsp"},{"name":"Onion","measure":"2"},{"name":"Garlic Clove","measure":"4 Chopped"},{"name":"Mixed peppers","measure":"5"},{"name":"Oregano","measure":"1 teaspoon"},{"name":"Thyme","measure":"Sprigs of fresh"},{"name":"Bay Leaves","measure":"4 leaves"},{"name":"Courgettes","measure":"2 chopped"},{"name":"Aubergine","measure":"1 chopped"},{"name":"Tomato","measure":"4 large"},{"name":"Egg","measure":"4 large"},{"name":"Parsley","measure":"Handful"}],"steps":["Heat the oil in a large flameproof casserole dish or a cast-iron skillet over a low heat. Add the onions and a sprinkle of salt, cover and cook gently for 15 mins, stirring occasionally. Add the garlic and cook for another 2 mins.","Next, throw in the peppers and cook over a medium heat, covered, for about 5 mins, stirring every so often, until the peppers are just tender.","Mix in the oregano, thyme, bay leaves, some black pepper and a little salt, if needed. Tip in the courgettes and aubergine, combine thoroughly, and cook over a medium heat, covered, for 10 mins. Stir in the tomatoes, cover and cook for 20 mins, stirring occasionally.","Carefully crack the eggs over the pisto – try not to break the yolks. Cook in the sauce on a medium heat for 5-6 mins until the eggs are cooked through but still a little soft, then scatter with parsley before serving"],"ingredient_names":["olive oil","onion","garlic clove","mixed peppers","oregano","thyme","bay leaves","courgettes","aubergine","tomato","egg","parsley"],"allergens":["eggs"],"diet_flags":["pescatarian","vegetarian"]},{"source_id":"53161","title":"Chicken & chorizo rice pot","category":"Chicken","country":"Spain","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/fk80jp1763280767.jpg","youtube_url":"https://www.youtube.com/watch?v=CiY6ZOYRMI4","source_url":"https://www.bbcgoodfood.com/recipes/chicken-chorizo-rice-pot","ingredients":[{"name":"Oil","measure":"1 tblsp"},{"name":"Chicken","measure":"1 whole"},{"name":"Onion","measure":"1 Large Chopped"},{"name":"Red Pepper","measure":"1 chopped"},{"name":"Garlic","measure":"3 Cloves Crushed"},{"name":"Chorizo","measure":"225g"},{"name":"Tomato Puree","measure":"1 tblsp"},{"name":"Thyme","measure":"1 tablespoon chopped"},{"name":"White Wine","measure":"150ml"},{"name":"Chicken Stock","measure":"800ml"},{"name":"Rice","measure":"400g"},{"name":"Parsley","measure":"2 tbs chopped"}],"steps":["Heat the oil in a large flameproof casserole dish and brown the chicken pieces on all sides – you may have to do this in batches. Remove from the dish and put to one side.","Lower the heat, add the onion and pepper, and gently cook for 10 mins until softened. Add the garlic and chorizo, and cook for a further 2 mins until the chorizo has released some of its oils into the dish. Stir in the tomato purée and cook for 1 min more.","Return the chicken pieces to the dish along with the thyme, white wine and stock. Bring the liquid to a boil, cover the dish with a tight-fitting lid and lower the heat. Cook for 30 mins.","Tip in the rice and stir everything together. Cover, set over a low heat and cook for a further 15 mins, or until the rice is cooked and has absorbed most of the cooking liquid. Remove from the heat and leave the dish to sit for 10 mins to absorb any remaining liquid. Season to taste and scatter with parsley to serve."],"ingredient_names":["oil","chicken","onion","red pepper","garlic","chorizo","tomato puree","thyme","white wine","chicken stock","rice","parsley"],"allergens":[],"diet_flags":[]},{"source_id":"53162","title":"Pollo en pepitoria","category":"Chicken","country":"Spain","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/li30ck1763281992.jpg","youtube_url":"https://www.youtube.com/watch?v=dam5k5HCE1Y","source_url":"https://www.bbcgoodfood.com/recipes/pollo-en-pepitoria","ingredients":[{"name":"Saffron","measure":"Pinch"},{"name":"Extra Virgin Olive Oil","measure":"4 tbsp"},{"name":"Garlic Clove","measure":"6"},{"name":"Almonds","measure":"35g"},{"name":"Stale bread","measure":"30g"},{"name":"Parsley","measure":"2 tbs chopped"},{"name":"Chicken Thighs","measure":"8"},{"name":"Onion","measure":"1 chopped"},{"name":"Carrots","measure":"1 chopped"},{"name":"Celery","measure":"1 chopped"},{"name":"Dry sherry","measure":"250ml"},{"name":"Chicken Stock","measure":"350ml"},{"name":"Cinnamon Stick","measure":"1"},{"name":"Cloves","measure":"Pinch"},{"name":"Bay Leaves","measure":"2"},{"name":"Egg","measure":"2"},{"name":"Almonds","measure":"2 tblsp"}],"steps":["Put the saffron in a small bowl with 75ml of just-boiled water. Stir and set aside. Heat 2 tbsp of the oil in a broad, shallow casserole dish. Cook the garlic until pale gold in colour, then add the blanched almonds and bread, and continue to fry until everything is golden. Tip into a food processor with some salt and pepper and the parsley, and whizz together.","Heat 2 more tbsp of the oil in the pan and brown the chicken all over, seasoning as you cook. Put in a bowl and set aside.","Remove all but about 2 tbsp of chicken fat from the pan and cook the onion, carrot and celery until golden. Add the sherry, stirring to dislodge any brown bits that have stuck to the pan. Pour in the stock and the saffron (with its water), and bring to the boil, then turn the heat down to a simmer. Add the spices and bay leaves, and put the chicken back in the pan with any juices. Season and gently cook the chicken for about 40 mins with the lid on.","Transfer the chicken to a bowl again, leaving the sauce in the pan, and cover with foil to keep warm. Remove the yolks from the eggs and roughly chop the whites. Mash the egg yolks in a small bowl and gradually mix in a couple of tbsp of the sauce. Bring the remaining sauce to the boil to reduce a bit (you want it to just coat the chicken), then turn the heat down. Remove the bay and cinnamon stick. Add the egg yolks and cook for a few mins until the mixture has thickened. Stir in the almond mixture that you made earlier (this will thicken the sauce, too). Put the chicken back in the pan and heat it for about 3 mins, spooning the sauce over it. Season to taste.","Scatter over the extra parsley, the almonds pieces and the chopped egg whites (if you’re going to use them). You can serve this straight from the dish with some rice, if you like."],"ingredient_names":["saffron","extra virgin olive oil","garlic clove","almonds","stale bread","parsley","chicken thighs","onion","carrots","celery","dry sherry","chicken stock","cinnamon stick","cloves","bay leaves","egg","almonds"],"allergens":["eggs","gluten","tree_nuts"],"diet_flags":[]},{"source_id":"53164","title":"Spanish Chicken","category":"Chicken","country":"Spain","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/pqulvm1763282839.jpg","youtube_url":"https://www.youtube.com/watch?v=fKqSOn5NCrk","source_url":"https://www.bbcgoodfood.com/recipes/spanish-chicken","ingredients":[{"name":"Chicken Thighs","measure":"8"},{"name":"Onion","measure":"3 sliced thinly"},{"name":"Paprika","measure":"2 teaspoons"},{"name":"Lemon","measure":"Zest and juice of 1"},{"name":"Parsley","measure":"Handful"},{"name":"Chicken Stock","measure":"150ml"},{"name":"Olive Oil","measure":"1 tablespoon"}],"steps":["Heat oven to 190C/170C fan/gas 5. Put all the ingredients into a large, wide ovenproof dish. Mix everything together with your hands and season.","Bake for 45 mins, stirring the onions after 20 mins, until the chicken is golden and the onions tender. Serve with rice."],"ingredient_names":["chicken thighs","onion","paprika","lemon","parsley","chicken stock","olive oil"],"allergens":[],"diet_flags":[]},{"source_id":"53166","title":"Chickpea, chorizo & spinach stew","category":"Pork","country":"Spain","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/xvnx8j1763287209.jpg","youtube_url":"https://www.youtube.com/watch?v=nI2Sm4B3gWU","source_url":"https://www.bbcgoodfood.com/recipes/chickpea-chorizo-spinach-stew","ingredients":[{"name":"Extra Virgin Olive Oil","measure":"4 tablespoons"},{"name":"Onion","measure":"1 chopped"},{"name":"Carrots","measure":"1 Diced"},{"name":"Celery","measure":"1 Diced"},{"name":"Thyme","measure":"3"},{"name":"Bay Leaves","measure":"2"},{"name":"Garlic","measure":"2 cloves chopped"},{"name":"Chorizo","measure":"200g"},{"name":"Cinnamon","measure":"1/4 tsp"},{"name":"Paprika","measure":"1 teaspoon"},{"name":"Chickpeas","measure":"800g"},{"name":"Sherry vinegar","measure":"2 tblsp"},{"name":"Spinach","measure":"400g"}],"steps":["Heat the oil in a large pan, then gently fry the onion for 3-4 mins until it begins to soften.","Stir in the carrot, celery, thyme and bay leaves.","Season, then cook for 2-3 mins, stirring occasionally.","Add the garlic, chorizo, cinnamon and smoked paprika.","Gently fry until the vegetables soften and the chorizo starts to release its oils and crisp up.","Stir in the chickpeas, vinegar and 150ml water, then bring to a simmer for 1-2 mins until the chickpeas have heated up.","Add the spinach, then stir through the chickpeas until it wilts a little.","Remove from the heat, season to taste, then serve warm with crusty bread."],"ingredient_names":["extra virgin olive oil","onion","carrots","celery","thyme","bay leaves","garlic","chorizo","cinnamon","paprika","chickpeas","sherry vinegar","spinach"],"allergens":[],"diet_flags":[]},{"source_id":"53167","title":"Seafood rice","category":"Seafood","country":"Spain","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/5r5rvx1763287943.jpg","youtube_url":"https://www.youtube.com/watch?v=Dr8Nsod20yg","source_url":"https://www.bbcgoodfood.com/recipes/easiest-ever-paella","ingredients":[{"name":"Olive Oil","measure":"1 tbsp"},{"name":"Leek","measure":"1 sliced"},{"name":"Chorizo","measure":"110g"},{"name":"Turmeric","measure":"1 teaspoon"},{"name":"Rice","measure":"300g"},{"name":"Fish Stock","measure":"1 L"},{"name":"Peas","measure":"200g"},{"name":"Frozen Seafood mix","measure":"400g"}],"steps":["Heat the oil in a deep frying pan, then soften the leek for 5 mins without browning.","Add the chorizo and fry until it releases its oils.","Stir in the turmeric and rice until coated by the oils, then pour in the stock.","Bring to the boil, then simmer for 15 mins, stirring occasionally.","Tip in the peas and cook for 5 mins, then stir in the seafood to heat through for a final 1-2 mins cooking or until rice is cooked.","Check for seasoning and serve immediately with lemon wedges."],"ingredient_names":["olive oil","leek","chorizo","turmeric","rice","fish stock","peas","frozen seafood mix"],"allergens":["fish","shellfish"],"diet_flags":[]},{"source_id":"53168","title":"Chorizo & chickpea soup","category":"Pork","country":"Spain","tags":["Soup"],"image_url":"https://www.themealdb.com/images/media/meals/kggfo91763288633.jpg","youtube_url":"https://www.youtube.com/watch?v=I_oZ8r6VxL4","source_url":"https://www.bbcgoodfood.com/recipes/chorizo-chickpea-soup","ingredients":[{"name":"Tinned Tomatos","measure":"400g"},{"name":"Chorizo","measure":"110g"},{"name":"Savoy Cabbage","measure":"140g"},{"name":"Chilli Flakes","measure":"Sprinkling"},{"name":"Chickpeas","measure":"400g can"},{"name":"Chicken Stock","measure":"1"},{"name":"Crusty Bread","measure":"To serve"}],"steps":["Put a medium pan on the heat and tip in the tomatoes, followed by a can of water.","While the tomatoes are heating, quickly chop the chorizo into chunky pieces (removing any skin) and shred the cabbage.","Pile the chorizo and cabbage into the pan with the chilli flakes and chickpeas, then crumble in the stock cube.","Stir well, cover and leave to bubble over a high heat for 6 mins or until the cabbage is just tender.","Ladle into bowls and eat with crusty or garlic bread."],"ingredient_names":["tinned tomatos","chorizo","savoy cabbage","chilli flakes","chickpeas","chicken stock","crusty bread"],"allergens":["gluten"],"diet_flags":[]},{"source_id":"53171","title":"Salt cod tortilla","category":"Seafood","country":"Spain","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/njj1681763297231.jpg","youtube_url":"https://www.youtube.com/watch?v=ga7YoAjGgnA","source_url":"https://www.bbcgoodfood.com/recipes/salt-cod-tortilla","ingredients":[{"name":"Olive Oil","measure":"4 tbsp"},{"name":"Onion","measure":"1 Large Chopped"},{"name":"Jersey Royal Potatoes","measure":"300g"},{"name":"Garlic","measure":"2 cloves chopped"},{"name":"Egg","measure":"8"},{"name":"Parsley","measure":"2 1/2 Tbs"},{"name":"Salt Cod","measure":"300g"}],"steps":["Heat half the oil in a frying pan, and sauté the onion over a medium heat until soft and pale gold – this will take about 8 mins. Remove from the pan, set aside, and add the potatoes to the pan. Cook until they are tender but not falling apart, carefully turning every so often. Cover the pan some of the time to help the slices cook through. Add the onions back to the pan along with the garlic and cook for another 4 mins. Tip into a bowl with the eggs, parsley and some seasoning and mix together. Leave to sit for half an hour.","Meanwhile, put the cod in a saucepan and cover with water. Bring up to a simmer. Remove from the heat, cover and leave for 10 mins. Drain, leave to cool and remove the skin and any bones. Break into large flakes and add to the potato and egg mixture.","Heat the rest of the oil in a non-stick frying pan. Pour in the tortilla mix and cook over a medium-low heat until it is just set and coming away from the sides of the pan. You might need to cover it to help the centre set. Be careful not to overcook it. Put a spatula underneath the tortilla every so often to make sure it isn’t sticking. Slide the tortilla onto a plate, then put the pan on top and flip the tortilla into it, uncooked side-down. Cook over a low heat until golden, or grill until just set. Leave to cool a little before serving."],"ingredient_names":["olive oil","onion","jersey royal potatoes","garlic","egg","parsley","salt cod"],"allergens":["eggs","fish"],"diet_flags":["pescatarian"]},{"source_id":"53172","title":"Patatas bravas","category":"Vegetarian","country":"Spain","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/bvg8sn1763298713.jpg","youtube_url":"https://www.youtube.com/watch?v=2Hup2nypG2w","source_url":"https://www.bbcgoodfood.com/recipes/patatas-bravas-0","ingredients":[{"name":"Olive Oil","measure":"3  tablespoons"},{"name":"Onion","measure":"1 small finely diced"},{"name":"Garlic","measure":"2 cloves chopped"},{"name":"Tinned Tomatos","measure":"225g"},{"name":"Tomato Puree","measure":"1 tablespoon"},{"name":"Paprika","measure":"2 teaspoon"},{"name":"Chilli Powder","measure":"Pinch"},{"name":"Sugar","measure":"Pinch"},{"name":"Parsley","measure":"Chopped"},{"name":"Potatoes","measure":"900g"},{"name":"Olive Oil","measure":"2 tbsp"}],"steps":["Heat the oil in a pan and fry the onion for about 5 mins until softened.","Add the garlic, chopped tomatoes, tomato purée, sweet paprika, chilli powder, sugar and a pinch of salt, then bring to the boil, stirring occasionally.","Lower to a simmer and cook for 10 mins until pulpy.","Can be kept chilled for up to 24 hrs.","Heat oven to 200C/180C fan/gas 6.","Pat the potatoes dry with kitchen paper, then tip into a roasting tin and toss in the olive oil and some seasoning.","Roast for 40-50 mins until crisp and golden.","Tip the potatoes into serving dishes and spoon over the tomato sauce.","Sprinkle with some fresh parsley to serve."],"ingredient_names":["olive oil","onion","garlic","tinned tomatos","tomato puree","paprika","chilli powder","sugar","parsley","potatoes","olive oil"],"allergens":[],"diet_flags":["pescatarian","vegan","vegetarian"]},{"source_id":"53174","title":"Prawns with Romesco sauce","category":"Seafood","country":"Spain","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/u03xhi1763308917.jpg","youtube_url":"https://www.youtube.com/watch?v=miqfHkE6rJY","source_url":"https://www.bbcgoodfood.com/recipes/prawns-romesco-sauce","ingredients":[{"name":"Red Pepper","measure":"1"},{"name":"Garlic Clove","measure":"3 Large"},{"name":"Red Chilli","measure":"1 large"},{"name":"Tomato","measure":"1 large"},{"name":"Shelled Hazelnuts","measure":"10"},{"name":"Almonds","measure":"10"},{"name":"Parsley","measure":"3 sprigs"},{"name":"Bread","measure":"1 sliced"},{"name":"Olive Oil","measure":"120ml"},{"name":"Red Wine Vinegar","measure":"2 tblsp"},{"name":"Tiger Prawns","measure":"400g"}],"steps":["Prepare ahead - halve the pepper lengthways and remove the seeds and stalk. Line a grill pan with foil and put the pepper halves, skin side up, on the grill pan with the whole garlic cloves, chilli and tomato. Grill for 2 minutes, turn the tomato, then grill for a further 2 minutes. Remove the tomato with a large spoon, then peel, quarter and remove the seeds. Then chop the tomato roughly.","Continue grilling the pepper, chilli and garlic for 4-5 minutes, until the pepper and chilli skins have blackened and the garlic is starting to soften (the garlic skin will start to split when it is ready). When cool enough to handle, peel and halve the chilli, and scrape out and discard the seeds. Peel the pepper and roughly chop both the pepper and chilli.","Spread nuts over the foil and grill until toasted. Finely chop the nuts and parsley in a food processor. Tip into a small bowl.","Heat 3 tablespoons of oil in a frying pan, add the pepper, garlic and chilli and fry for 3 minutes. Tear up the bread and add to the pan, turning it in the oil until lightly browned. Pulse in food processor with the tomatoes, salt, vinegar and oil until roughly chopped. Tip into a bowl. Leave to cool and store in fridge for up to 3 days.","On the day add the nuts and parsley to the sauce and mix. Serve in a small bowl on a plate with the peeled prawns. Supply cocktail sticks for spearing the prawns."],"ingredient_names":["red pepper","garlic clove","red chilli","tomato","shelled hazelnuts","almonds","parsley","bread","olive oil","red wine vinegar","tiger prawns"],"allergens":["gluten","shellfish","tree_nuts"],"diet_flags":["pescatarian"]},{"source_id":"53175","title":"Spanish-style slow-cooked lamb shoulder & beans","category":"Lamb","country":"Spain","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/9kwatm1763327074.jpg","youtube_url":"https://www.youtube.com/watch?v=D35ByGgKNaY","source_url":"https://www.bbcgoodfood.com/recipes/spanish-style-slow-cooked-lamb-shoulder-beans","ingredients":[{"name":"Lamb Shoulder","measure":"2.5kg"},{"name":"Olive Oil","measure":"1 tblsp"},{"name":"Onion","measure":"2 chopped"},{"name":"Carrots","measure":"4 Chopped"},{"name":"Garlic Bulb","measure":"1"},{"name":"Chicken Stock","measure":"500ml"},{"name":"Butter Beans","measure":"1200g"},{"name":"Roasted pepper","measure":"450g"},{"name":"Black Olives","measure":"300g"},{"name":"Parsley","measure":"4 tablespoons"},{"name":"Garlic","measure":"4 Cloves Crushed"},{"name":"Hot smoked paprika","measure":"1 tablespoon"},{"name":"Olive Oil","measure":"4 tablespoons"},{"name":"Rosemary","measure":"1/2 teaspoon"}],"steps":["To make the spice mix, combine all of the ingredients together with a large pinch of salt. Slash the lamb shoulder all over with a sharp knife and rub in. If you have the time, marinate for up to 24 hrs, but this is not essential.","Heat the oven to 150C/130C fan/gas 2. Heat the oil in a large flameproof casserole dish or roasting tin over a medium-high heat, add the onions, carrots and garlic and sizzle for 5 mins until the onions and carrots are softened. Pour over the stock, then bring to the boil. Nestle the lamb in the pan and cover, then transfer to the oven and roast for 2 hrs.","Uncover and transfer the lamb to a plate using tongs. Stir the beans, peppers and olives through the stock in the pan, sit the lamb back on top and return to the oven, uncovered, for 1 hr 30 mins until the lamb is cooked through. Transfer the lamb to a board and shred using two forks. Stir the parsley through the braised beans before serving."],"ingredient_names":["lamb shoulder","olive oil","onion","carrots","garlic bulb","chicken stock","butter beans","roasted pepper","black olives","parsley","garlic","hot smoked paprika","olive oil","rosemary"],"allergens":[],"diet_flags":[]},{"source_id":"53176","title":"Spanish tomato bread with jamón Serrano","category":"Pork","country":"Spain","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/hsp1fo1763327867.jpg","youtube_url":"https://www.youtube.com/watch?v=OG9zuXJht7I","source_url":"https://www.bbcgoodfood.com/recipes/spanish-tomato-bread-jamon-serrano","ingredients":[{"name":"Tomato","measure":"4 Chopped"},{"name":"Garlic","measure":"1 clove finely chopped"},{"name":"Olive Oil","measure":"3  tablespoons"},{"name":"Salt","measure":"Pinch"},{"name":"Pepper","measure":"Pinch"},{"name":"Baguette","measure":"20 slices"},{"name":"Serrano Ham","measure":"5 Slices"}],"steps":["Mix together the chopped tomatoes, garlic clove, olive oil, salt and pepper. Keep in the fridge until needed.","To serve, toast 20 slices of baguette. Spoon a little tomato topping on to each piece of toast. Tear 5-6 slices of jamón Serrano into pieces and put one piece on each slice of bread."],"ingredient_names":["tomato","garlic","olive oil","salt","pepper","baguette","serrano ham"],"allergens":["gluten"],"diet_flags":[]},{"source_id":"53177","title":"Spaghetti with Spanish flavours","category":"Pork","country":"Spain","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/vpcqn01763335688.jpg","youtube_url":"https://www.youtube.com/watch?v=BukrisTBv00","source_url":"https://www.bbcgoodfood.com/recipes/spaghetti-spanish-flavours","ingredients":[{"name":"Chorizo","measure":"80g"},{"name":"Spaghetti","measure":"300g"},{"name":"Parsley","measure":"20g"},{"name":"Red Pepper","measure":"2"},{"name":"Olive Oil","measure":"2 tbsp"},{"name":"Parmesan Cheese","measure":"50g"}],"steps":["Put a pan of water on over a high heat to boil. Meanwhile, snip the chorizo into strips with scissors, and chop the parsley and peppers (check for stray seeds first).","When the water is boiling briskly, add the spaghetti with a good measure of salt, stir and return to the boil. Cook for 3 minutes.","In a large frying pan, heat the oil, add the chorizo and peppers and plenty of black pepper. Cook for a minute or so, until heated through and the juices are stained red from the paprika in the chorizo. Scoop half a mugful of pasta water from the pan, drain the remainder and tip the spaghetti into the frying pan.","Add the parsley and parmesan, toss well and splash in the pasta water, to moisten. Hand round extra parmesan at the table."],"ingredient_names":["chorizo","spaghetti","parsley","red pepper","olive oil","parmesan cheese"],"allergens":["dairy","gluten"],"diet_flags":[]},{"source_id":"53178","title":"Fried calamari","category":"Seafood","country":"Spain","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/yhi46r1763330279.jpg","youtube_url":"https://www.youtube.com/watch?v=VcxMq33G-Do","source_url":"https://www.bbcgoodfood.com/recipes/crispy-squid-capers","ingredients":[{"name":"Squid","measure":"300g"},{"name":"Plain Flour","measure":"200g"},{"name":"Capers","measure":"2 tblsp"},{"name":"Garlic","measure":"1 clove peeled crushed"},{"name":"Mayonnaise","measure":"5 tblsp"},{"name":"Vegetable Oil","measure":"For frying"},{"name":"Lemon","measure":"To serve"}],"steps":["Cut the squid into rings about ½cm thick. Tip the flour into a freezer bag and season well. Add the capers, then give everything a good shake to mix together. Tip the squid into the bag, then shake again until all the rings are well coated. Mix together the garlic and mayonnaise, then place in a serving bowl.","Pour some oil into a large pan until it comes about 7cm up the sides, but the pan is no more than a third full. Place over a medium heat and let the oil warm up. To test that the oil is ready, place a small piece of bread in the pan – it should sizzle when it touches the oil.","Remove a handful of squid from the flour and shake off any excess. Gently drop into the oil, then cook for about 3 mins until crisp. Remove with a slotted spoon and place on kitchen paper. Repeat with the remaining squid. Serve straight away with the mayonnaise and lemon wedges."],"ingredient_names":["squid","plain flour","capers","garlic","mayonnaise","vegetable oil","lemon"],"allergens":["eggs","gluten","shellfish"],"diet_flags":["pescatarian"]},{"source_id":"53179","title":"Ham croquetas","category":"Pork","country":"Spain","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/6dpa7m1763331105.jpg","youtube_url":"https://www.youtube.com/shorts/nT8MGiWldHk","source_url":"https://www.bbcgoodfood.com/recipes/ham-croquetas","ingredients":[{"name":"Plain Flour","measure":"75g"},{"name":"Egg","measure":"2 large"},{"name":"Breadcrumbs","measure":"75g"},{"name":"Sunflower Oil","measure":"For frying"},{"name":"Extra Virgin Olive Oil","measure":"4 tbsp"},{"name":"Leek","measure":"1/2"},{"name":"jamón ibérico","measure":"70g"},{"name":"Plain Flour","measure":"60g"},{"name":"Vegetable Stock","measure":"75 ml"},{"name":"Milk","measure":"330ml"},{"name":"Nutmeg","measure":"Grated"}],"steps":["To make the filling, heat the olive oil in a pan until it starts to shimmer. Add the leek and sauté until soft but not coloured. Stir in the ham with a wooden spoon, fry for 1 min, then stir in the flour and fry over a medium heat, stirring occasionally, until the mixture is golden but not burnt – this will take about 5 mins.","Meanwhile, combine the stock and milk in a small pan and heat until steaming but not boiling. Season with a few scrapes of nutmeg. Gradually add the liquid, a few tbsp at a time, stirring constantly.","Once you’ve incorporated all the milk stock, continue to cook the filling over a medium heat for about 10 mins or until it thickens and leaves the sides of the pan when you stir it.","Season with black pepper, taste and adjust the salt if necessary – the ham can be very salty to start with. The filling is now done: it has to be really thick because you don’t want the croquetas to turn into pancakes.","Smooth the mixture onto a baking tray (30 x 20cm is fine). Once it has stopped steaming, cover with cling film to stop it drying out. Leave to cool before putting it in the fridge for 1 hr.","When you're ready for the next stage, line up three bowls: the first filled with the flour, the second with beaten egg and the third with breadcrumbs. Take the ham mixture out of the fridge. Put a little bit of olive oil on your hands to make it easier to roll the croquetas.","Roll a spoonful of the mixture between your palms. The size and shape of the croquetas is up to you, but the easiest is a walnut-sized ball. Then begin coating as follows.","Dunk the croquetas into the flour – you want a dusting – followed by the egg, then the breadcrumbs. Put them on a tray and, when you’ve used up all the mixture, place in the fridge for 30 mins.","If you have a deep-fat fryer, heat the oil to 180C and fry for a couple of mins. If not, heat the oil in a deep, heavy-bottomed saucepan until it starts to shimmer. Then add 5-6 croquetas at a time and fry until golden all over. Once cooked, drain on kitchen paper and eat straight away."],"ingredient_names":["plain flour","egg","breadcrumbs","sunflower oil","extra virgin olive oil","leek","jamón ibérico","plain flour","vegetable stock","milk","nutmeg"],"allergens":["dairy","eggs","gluten"],"diet_flags":[]},{"source_id":"53180","title":"Garlicky prawns with sherry","category":"Seafood","country":"Spain","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/u2lhqb1763331899.jpg","youtube_url":"https://www.youtube.com/watch?v=2hf2xltFbxQ","source_url":"https://www.bbcgoodfood.com/recipes/garlicky-prawns-sherry","ingredients":[{"name":"Olive Oil","measure":"3  tablespoons"},{"name":"Garlic","measure":"3 cloves Chopped"},{"name":"Prawns","measure":"400g"},{"name":"Dry sherry","measure":"2 tbsp"},{"name":"Parsley","measure":"Handful"}],"steps":["Heat the olive oil in a large frying pan.","Tip in the garlic slices and cook for a few secs.","Then stir through the prawns and cook for a couple of mins until they start to turn pink.","Pour over the sherry and cook for a few mins more, just until the prawns are cooked through.","Sprinkle with parsley before serving."],"ingredient_names":["olive oil","garlic","prawns","dry sherry","parsley"],"allergens":["shellfish"],"diet_flags":["pescatarian"]},{"source_id":"53181","title":"Spanish beans with chicken & chorizo","category":"Chicken","country":"Spain","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/bpkxtw1763332446.jpg","youtube_url":null,"source_url":"https://www.bbcgoodfood.com/recipes/spanish-beans-chicken-chorizo","ingredients":[{"name":"Pinto Beans","measure":"300g"},{"name":"Onion","measure":"1 chopped"},{"name":"Paprika","measure":"1 tablespoon"},{"name":"Thyme","measure":"Sprigs of fresh"},{"name":"Bay Leaves","measure":"Pinch"},{"name":"Parsley","measure":"Bunch"},{"name":"Chicken Thighs","measure":"4"},{"name":"Jersey Royal Potatoes","measure":"250g"},{"name":"Chorizo","measure":"250g"},{"name":"Spinach","measure":"100g"}],"steps":["Soak the beans for at least 4 hrs or overnight in a large bowl with plenty of water to cover. Next day, rinse and drain, then put in a large heavy based pan with the onion, paprika, herb bundle and chicken. Pour over enough water or stock to cover, bring to the boil, then reduce the heat, cover and simmer for 45 mins.","Remove the chicken to a plate, then add the potatoes and chorizo to the pan. Continue cooking for 30 mins until the beans and potatoes are tender.","Discard the skin and bones from the chicken and tear into large chunks. Return the chicken to the pan with the spinach and simmer for 5 mins."],"ingredient_names":["pinto beans","onion","paprika","thyme","bay leaves","parsley","chicken thighs","jersey royal potatoes","chorizo","spinach"],"allergens":[],"diet_flags":[]},{"source_id":"53182","title":"Spanish seafood rice","category":"Seafood","country":"Spain","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/c6ghxm1763335584.jpg","youtube_url":"https://www.youtube.com/watch?v=jA-G6k1wT9M","source_url":"https://www.bbcgoodfood.com/recipes/spanish-seafood-rice","ingredients":[{"name":"Olive Oil","measure":"1 tblsp"},{"name":"Onion","measure":"1 chopped"},{"name":"Red Pepper","measure":"1"},{"name":"Yellow Pepper","measure":"1"},{"name":"Garlic Clove","measure":"2 sliced"},{"name":"Paella Rice","measure":"250g"},{"name":"Vegetable Stock","measure":"800ml"},{"name":"Saffron","measure":"Pinch"},{"name":"Frozen Seafood mix","measure":"400g"},{"name":"Lemon","measure":"Juice of 1/2"},{"name":"Parsley","measure":"Handful"}],"steps":["Heat the oil in a large saucepan and soften the onion for 6-7 mins. Add the pepper and garlic, cook for 2 mins more, then stir in the paella rice and cook for 1 min, stirring to coat.","Pour in the stock, add the saffron and bring to the boil. Cook, uncovered, at a gentle bubble, for 20 mins, stirring occasionally until the rice is tender.","Stir in the seafood and lemon juice and cook for 2 mins or until piping hot and completely cooked through. Serve in warm bowls scattered with the parsley."],"ingredient_names":["olive oil","onion","red pepper","yellow pepper","garlic clove","paella rice","vegetable stock","saffron","frozen seafood mix","lemon","parsley"],"allergens":["fish","shellfish"],"diet_flags":["pescatarian"]},{"source_id":"53184","title":"Spanish rice & prawn one-pot","category":"Seafood","country":"Spain","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/sl6vqv1763335988.jpg","youtube_url":"https://www.youtube.com/watch?v=fhz1QjO1tB0","source_url":"https://www.bbcgoodfood.com/recipes/spanish-rice-prawn-one-pot","ingredients":[{"name":"Onion","measure":"1 sliced"},{"name":"Red Pepper","measure":"1 sliced"},{"name":"Green Pepper","measure":"1 sliced"},{"name":"Chorizo","measure":"50g"},{"name":"Garlic","measure":"2 cloves minced"},{"name":"Olive Oil","measure":"1 tblsp"},{"name":"Basmati Rice","measure":"250g"},{"name":"Tinned Tomatos","measure":"400g"},{"name":"Prawns","measure":"200g"}],"steps":["Boil the kettle.","In a non-stick frying or shallow pan with a lid, fry the onion, peppers, chorizo and garlic in the oil over a high heat for 3 mins.","Stir in the rice and chopped tomatoes with 500ml boiling water, cover, then cook over a high heat for 12 mins.","Uncover, then stir – the rice should be almost tender.","Stir in the prawns, with a splash more water if the rice is looking dry, then cook for another min until the prawns are just pink and rice tender."],"ingredient_names":["onion","red pepper","green pepper","chorizo","garlic","olive oil","basmati rice","tinned tomatos","prawns"],"allergens":["shellfish"],"diet_flags":[]},{"source_id":"53185","title":"Chorizo & tomato salad","category":"Pork","country":"Spain","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/6cskio1763338156.jpg","youtube_url":"https://www.youtube.com/watch?v=RFlENguMJNA","source_url":"https://www.bbcgoodfood.com/recipes/chorizo-tomato-salad","ingredients":[{"name":"Beef tomatoes","measure":"3"},{"name":"Red Onions","measure":"1/2"},{"name":"Thyme","measure":"Sprigs of fresh"},{"name":"Sherry vinegar","measure":"1 tablespoon"},{"name":"Extra Virgin Olive Oil","measure":"2 tblsp"},{"name":"Chorizo","measure":"100g"}],"steps":["Put the tomatoes in a bowl with the onion and thyme.","Season, then drizzle with the vinegar and oil.","Let the flavours mingle while you cook the chorizo.","In a hot, dry pan, fry the chorizo slices until browned on both sides.","Serve the tomatoes with the fried chorizo, drizzled with a little oil from the pan."],"ingredient_names":["beef tomatoes","red onions","thyme","sherry vinegar","extra virgin olive oil","chorizo"],"allergens":[],"diet_flags":[]},{"source_id":"53186","title":"Chicken with saffron, raisins & pine nuts","category":"Chicken","country":"Spain","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/4mhr3u1763481087.jpg","youtube_url":"https://www.youtube.com/watch?v=uKWjI2DNq0Q","source_url":"https://www.bbcgoodfood.com/recipes/chicken-saffron-raisins-pine-nuts","ingredients":[{"name":"Chicken","measure":"1.25kg"},{"name":"Olive Oil","measure":"2 tblsp"},{"name":"Garlic","measure":"3 cloves Chopped"},{"name":"Saffron","measure":"Pinch"},{"name":"Dry sherry","measure":"125ml"},{"name":"Chicken Stock","measure":"200ml"},{"name":"Thyme","measure":"1 tbsp"},{"name":"Raisins","measure":"50g"},{"name":"Pine Nuts","measure":"2 tbsp"},{"name":"Parsley","measure":"Handful"}],"steps":["Heat a large frying pan on a high heat and season the chicken. Add the olive oil to the pan, then the chicken. Brown for about 5 mins on each side, remove onto a plate, then set aside.","Lower the heat to medium. In the remaining fat, fry the onions for 3 mins, then add the garlic and saffron. Cook for 3-4 mins more. Add the sherry, then simmer for 3-5 mins until syrupy.","Put the chicken leg pieces back into the pan, tip in the stock, thyme and raisins, cover, then gently cook on a low heat for 20 mins. Add the breast meat and any juices left on the plate. Simmer for 10 mins more until cooked through and the sauce in the pan has reduced.","While the chicken is cooking, heat oven to 200C/180C fan/gas 6. Scatter the pine nuts over a baking sheet, then roast for 10 mins until golden and toasted. Once the chicken has cooked through, season to taste, scatter with pine nuts and parsley, then serve with rice."],"ingredient_names":["chicken","olive oil","garlic","saffron","dry sherry","chicken stock","thyme","raisins","pine nuts","parsley"],"allergens":["tree_nuts"],"diet_flags":[]},{"source_id":"53188","title":"Fašírky","category":"Pork","country":"Slovakia","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/gtpvwp1763363947.jpg","youtube_url":"https://www.youtube.com/watch?v=ecBMVy3p6Ns","source_url":"https://www.slovakia-foods.co.uk/blog/post/fasirky-recipe-how-to-make-authentic-slovak-meat-patties.html","ingredients":[{"name":"Ground Pork","measure":"500g"},{"name":"Onion","measure":"1 medium chopped"},{"name":"Garlic","measure":"2 cloves minced"},{"name":"Bread","measure":"2 sliced"},{"name":"Milk","measure":"1 shot"},{"name":"Egg","measure":"1"},{"name":"Salt","measure":"1 teaspoon"},{"name":"Black Pepper","measure":"1/2 teaspoon"},{"name":"Marjoram","measure":"1 teaspoon"},{"name":"Mustard","measure":"1 tsp"},{"name":"Parsley","measure":"1 tablespoon chopped"},{"name":"Flour","measure":"1/2 cup"},{"name":"Egg","measure":"1 beaten"},{"name":"Breadcrumbs","measure":"1 cup"},{"name":"Vegetable Oil","measure":"For frying"}],"steps":["Prepare the Bread Mixture","Soak the bread slices in milk or water until soft.","Squeeze out excess liquid and mash into small crumbs.","Mix the Ingredients","In a large bowl, combine ground meat, chopped onions, garlic, soaked bread, egg, and seasonings.","Mix well until evenly combined.","Shape the Meat Patties","Take portions of the mixture and shape them into palm-sized patties.","Flatten slightly to help with even cooking.","Coat the Patties","Lightly dust each patty with flour.","Dip into beaten egg, then coat with breadcrumbs for a crispy finish.","Fry the Fašírky","Heat vegetable oil in a pan over medium heat.","Fry the patties for 4-5 minutes per side until golden brown and fully cooked.","Transfer to a paper towel-lined plate to drain excess oil.","Serve and Enjoy","Serve Fašírky hot with mashed potatoes, cabbage salad, or fresh bread.","Enjoy with mustard, pickles, or garlic sauce for extra flavor."],"ingredient_names":["ground pork","onion","garlic","bread","milk","egg","salt","black pepper","marjoram","mustard","parsley","flour","egg","breadcrumbs","vegetable oil"],"allergens":["dairy","eggs","gluten"],"diet_flags":[]},{"source_id":"53190","title":"Bryndzové Halušky","category":"Pork","country":"Slovakia","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/g33c901763365484.jpg","youtube_url":"https://www.youtube.com/shorts/IPF_VpH7FzI","source_url":"https://www.slovakia-foods.co.uk/blog/post/bryndzove-halusky-recipe-a-taste-of-slovakia-national-dish.html","ingredients":[{"name":"Potatoes","measure":"500g"},{"name":"Plain Flour","measure":"200g"},{"name":"Egg","measure":"1"},{"name":"Salt","measure":"1 teaspoon"},{"name":"Bryndza cheese","measure":"250g"},{"name":"Bacon","measure":"200g"},{"name":"Chives","measure":"Garnish"}],"steps":["Prepare the Dough","Grate the potatoes finely using a hand grater or food processor. Place the grated potatoes in a bowl and mix them with flour, egg, and salt until a sticky dough forms. The consistency should be thick but pliable.","Cook the Dumplings","Bring a large pot of salted water to a boil. Using a halušky maker (similar to a spaetzle maker), press the dough directly into the boiling water. If you don’t have one, use a tilted cutting board and a knife to scrape small pieces of dough into the water.","Let the dumplings cook until they float to the surface, usually within 2-3 minutes. Scoop them out with a slotted spoon and set aside in a large bowl.","Prepare the Toppings","Chop the bacon into small pieces and fry in a skillet over medium heat until crispy. If using a bryndza substitute, mix crumbled feta with a dollop of sour cream to mimic the tangy flavour of traditional Slovak sheep cheese.","Assemble the Dish","Toss the cooked dumplings with the bryndza cheese (or substitute) until they’re well-coated and creamy. Top with the crispy bacon and its drippings. Garnish with chopped chives or parsley for an extra touch of colour and flavour."],"ingredient_names":["potatoes","plain flour","egg","salt","bryndza cheese","bacon","chives"],"allergens":["dairy","eggs","gluten"],"diet_flags":[]},{"source_id":"53191","title":"Pad Thai","category":"Seafood","country":"Thailand","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/rg9ze01763479093.jpg","youtube_url":"https://www.youtube.com/watch?v=F86GfZIph8o","source_url":"https://www.bbcgoodfood.com/recipes/easy-pad-thai","ingredients":[{"name":"Rice Noodles","measure":"125g"},{"name":"Lime","measure":"Juice of 3"},{"name":"Cayenne Pepper","measure":"1/2 teaspoon"},{"name":"Muscovado Sugar","measure":"2 teaspoons"},{"name":"Fish Sauce","measure":"2 tablespoons"},{"name":"Vegetable Oil","measure":"2 tablespoons"},{"name":"Tiger Prawns","measure":"200g"},{"name":"Spring Onions","measure":"4 finely sliced"},{"name":"Bean Sprouts","measure":"140g"},{"name":"Peanuts","measure":"25g"},{"name":"Coriander","measure":"Handful"},{"name":"Lime","measure":"2"},{"name":"sweet chilli sauce","measure":"To serve"}],"steps":["Put the noodles in a large heatproof bowl, pour boiling water over them and leave for 4 minutes, then drain and refresh under cold running water.","Put the lime juice, cayenne, sugar and fish sauce in a bowl and mix well. Have all the other ingredients ready by the cooker.","Heat the oil and fry the prawns until warmed through. Add the spring onions and noodles and toss around. Tip in the lime juice mixture, then stir in the beansprouts and half the peanuts and coriander. Cook for 1 minute until everything is heated through.","Pile into a large dish, scatter with the rest of the peanuts and coriander, and serve with lime wedges and sweet chilli sauce."],"ingredient_names":["rice noodles","lime","cayenne pepper","muscovado sugar","fish sauce","vegetable oil","tiger prawns","spring onions","bean sprouts","peanuts","coriander","lime","sweet chilli sauce"],"allergens":["fish","peanuts","shellfish"],"diet_flags":["pescatarian"]},{"source_id":"53192","title":"Panang chicken curry (kaeng panang gai)","category":"Chicken","country":"Thailand","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/0dhtwr1763371444.jpg","youtube_url":"https://www.youtube.com/watch?v=dYZHzK7YfYI","source_url":"https://www.bbcgoodfood.com/recipes/panang-chicken-curry-kaeng-panang-gai","ingredients":[{"name":"Coconut Milk","measure":"400ml"},{"name":"Panang Curry Paste","measure":"1-2tbsp"},{"name":"Chicken Breast","measure":"200g"},{"name":"Green Beans","measure":"100g"},{"name":"Fish Sauce","measure":"2-3 tbsp"},{"name":"Brown Sugar","measure":"1-2tbsp"},{"name":"makrut lime leaves","measure":"2"},{"name":"Basil Leaves","measure":"Handful"},{"name":"Jasmine Rice","measure":"Boiled"},{"name":"Red Chilli","measure":"6"},{"name":"Dried Red Chillies","measure":"4"},{"name":"Shrimp Paste","measure":"1 teaspoon"},{"name":"Garlic","measure":"4 Cloves Chopped"},{"name":"Galangal","measure":"1 tblsp"},{"name":"Lemongrass","measure":"1 tblsp"},{"name":"Lime","measure":"Zest of 2"},{"name":"Ground Nutmeg","measure":"1 teaspoon"},{"name":"Ground Coriander","measure":"1 tsp"},{"name":"Ground Cumin","measure":"1 teaspoon"},{"name":"Peanuts","measure":"2 tblsp"}],"steps":["First, make the curry paste. Use a pestle and mortar to pound together the dried and fresh chillies, shrimp paste, garlic, galangal, lemongrass, lime zest, white pepper, coriander, cumin, nutmeg and peanuts, plus 1 tsp salt. You should have a rough paste. Alternatively, add all the ingredients to a food processor along with 2-3 tbsp of coconut milk and pulse until you have a paste. Store in a lidded jar in the fridge. Will keep for up to two weeks.","Add 2-3 tbsp of the thick part of the coconut milk into a saucepan over a medium-high heat. When the coconut milk starts bubbling, add 1-2 tbsp of the curry paste and stir well for about 1 min, until fragrant.","Stir in the chicken and let it cook for about 3-4 mins until beginning to brown all over. Follow with the French beans and stir well.","Season with the fish sauce and sugar, then add the rest of coconut milk. Mix well, add half the makrut lime leaves and simmer for 3-5 mins until the chicken is cooked through. Taste and add more sugar or fish sauce if necessary – it should be salty and nutty, and the sweetness should come through. Add the Thai basil leaves, give it a quick mix and take off the heat. Serve with steamed jasmine rice, garnished with the sliced chilli and the rest of the makrut lime leaves."],"ingredient_names":["coconut milk","panang curry paste","chicken breast","green beans","fish sauce","brown sugar","makrut lime leaves","basil leaves","jasmine rice","red chilli","dried red chillies","shrimp paste","garlic","galangal","lemongrass","lime","ground nutmeg","ground coriander","ground cumin","peanuts"],"allergens":["fish","peanuts","shellfish"],"diet_flags":[]},{"source_id":"53193","title":"Drunken noodles (pad kee mao)","category":"Beef","country":"Thailand","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/2wx8cm1763373419.jpg","youtube_url":"https://www.youtube.com/watch?v=eJ3w2iJB4x8","source_url":"https://www.bbcgoodfood.com/recipes/drunken-noodles-pad-kee-mao","ingredients":[{"name":"Flat Rice Noodles","measure":"200g"},{"name":"Vegetable Oil","measure":"2 tblsp"},{"name":"Garlic","measure":"3 cloves Chopped"},{"name":"Birds-eye Chillies","measure":"3 chopped"},{"name":"Sirloin steak","measure":"225g"},{"name":"Broccoli","measure":"100g"},{"name":"Basil Leaves","measure":"Handful"},{"name":"Soy Sauce","measure":"4 tbsp"},{"name":"Oyster Sauce","measure":"4 tbsp"},{"name":"Fish Sauce","measure":"1 teaspoon"},{"name":"Sugar","measure":"1 tblsp"}],"steps":["Prepare the noodles following pack instructions, then drain and set aside. Combine all the ingredients for the sauce in a small bowl or jug, and set aside.","Heat the oil in a large wok or frying pan over a high heat and stir-fry the garlic and chilli for 20 seconds until just starting to turn golden. Add the steak and stir-fry for 1 minute until seared and starting to brown. Add the broccoli and stir-fry for another minute, then tip in the noodles and add the sauce. Stir-fry for another 1-2 mins until well combined and piping hot.","Stir through the basil and turn off the heat. Serve immediately to avoid overcooking."],"ingredient_names":["flat rice noodles","vegetable oil","garlic","birds-eye chillies","sirloin steak","broccoli","basil leaves","soy sauce","oyster sauce","fish sauce","sugar"],"allergens":["fish","gluten","shellfish","soy"],"diet_flags":[]},{"source_id":"53194","title":"Tom yum soup with prawns","category":"Seafood","country":"Thailand","tags":["Soup"],"image_url":"https://www.themealdb.com/images/media/meals/l50vz41763422681.jpg","youtube_url":"https://www.youtube.com/watch?v=fvLcZg9gNnE","source_url":"https://www.bbcgoodfood.com/recipes/tom-yum-soup-with-prawns","ingredients":[{"name":"Onion","measure":"200g"},{"name":"Tomato","measure":"150g"},{"name":"Red Chilli","measure":"20g"},{"name":"Galangal","measure":"15g"},{"name":"Lemongrass Stalks","measure":"2"},{"name":"Raw King Prawns","measure":"250g"},{"name":"Chicken Stock Cube","measure":"1"},{"name":"Oyster Mushrooms","measure":"120g"},{"name":"makrut lime leaves","measure":"8"},{"name":"Fish Sauce","measure":"25 ml"},{"name":"Lime juice","measure":"25 ml"},{"name":"Coconut Milk","measure":"70 ml"},{"name":"Thai Chilli Jam","measure":"1 tblsp"},{"name":"Coriander","measure":"Handful"}],"steps":["Pour 1.3 litres water into a large saucepan over a high heat. Add the onion, tomato, chilli, galangal, lemongrass, prawn heads and chicken stock cube. Stir and bring to a boil, then reduce the heat to medium and simmer for 20 mins until the liquid has reduced.","Carefully strain the hot broth into a large heatproof bowl or jug, then discard the prawn heads. Return the strained veg and herb mixture to the saucepan and pour over the broth. Stir through the mushrooms and lime leaves, then cook for 3 mins until the mushrooms are tender.","Add 1 tbsp sugar, the fish sauce, lime juice, coconut milk and prawns. Bring to the boil and cook until the prawns are cooked through, about 1-2 mins. Remove from the heat. Remove the lemongrass, then stir in the Thai chilli jam, if using. Scatter over the coriander to finish, if you like, and serve."],"ingredient_names":["onion","tomato","red chilli","galangal","lemongrass stalks","raw king prawns","chicken stock cube","oyster mushrooms","makrut lime leaves","fish sauce","lime juice","coconut milk","thai chilli jam","coriander"],"allergens":["fish","shellfish"],"diet_flags":[]},{"source_id":"53195","title":"Thai curry noodle soup","category":"Seafood","country":"Thailand","tags":["Soup"],"image_url":"https://www.themealdb.com/images/media/meals/118oj61763423896.jpg","youtube_url":"https://www.youtube.com/watch?v=FN8tcugjCFs","source_url":"https://www.bbcgoodfood.com/recipes/thai-curry-noodle-soup","ingredients":[{"name":"Vegetable Oil","measure":"1 teaspoon"},{"name":"Thai Green Curry Paste","measure":"1 tbsp"},{"name":"Stir-fry Vegetables","measure":"220g"},{"name":"Raw King Prawns","measure":"150g"},{"name":"Coconut Milk","measure":"150ml"},{"name":"Vegetable Stock","measure":"225ml"},{"name":"Udon Noodles","measure":"250g"},{"name":"Coriander","measure":"10g"},{"name":"Basil","measure":"10g"},{"name":"Red Chilli","measure":"1 sliced"},{"name":"Spring Onions","measure":"1 sliced"}],"steps":["Heat the oil in a saucepan over a medium heat and cook the curry paste for 1 min before adding the stir-fry veg and prawns.","Cook for 3 mins until the prawns are mostly pink, then add the coconut milk, veg stock and noodles.","Bring to the boil, then reduce the heat to a simmer and cook for 5 mins until the noodles are cooked through and the veg is tender but still has a bite.","Divide between two bowls and sprinkle over the herbs, chilli and spring onion."],"ingredient_names":["vegetable oil","thai green curry paste","stir-fry vegetables","raw king prawns","coconut milk","vegetable stock","udon noodles","coriander","basil","red chilli","spring onions"],"allergens":["gluten","shellfish"],"diet_flags":["pescatarian"]},{"source_id":"53196","title":"Tom yum (hot & sour) soup with prawns","category":"Seafood","country":"Thailand","tags":["Soup"],"image_url":"https://www.themealdb.com/images/media/meals/9c5nlx1763424766.jpg","youtube_url":"https://www.youtube.com/watch?v=FJer_Cutb2I","source_url":"https://www.bbcgoodfood.com/recipes/tom-yum-hot-sour-soup-prawns","ingredients":[{"name":"Chicken Stock","measure":"700ml"},{"name":"Lemongrass","measure":"1"},{"name":"Galangal","measure":"5 Slices"},{"name":"Coriander","measure":"6"},{"name":"makrut lime leaves","measure":"3"},{"name":"King Prawns","measure":"6"},{"name":"Fish Sauce","measure":"3  tablespoons"},{"name":"Green Chilli","measure":"6 small"},{"name":"Lime juice","measure":"4 tablespoons"}],"steps":["Bring the stock to a boil in a medium-sized saucepan.","Add the lemongrass, galangal, coriander roots and lime leaves, then simmer for 2 mins.","Add the prawns, fish sauce, chillies and lime juice, then return to the boil.","Taste and adjust the seasoning with either more lime juice or fish sauce, then garnish with coriander leaves and serve."],"ingredient_names":["chicken stock","lemongrass","galangal","coriander","makrut lime leaves","king prawns","fish sauce","green chilli","lime juice"],"allergens":["fish","shellfish"],"diet_flags":[]},{"source_id":"53197","title":"Thai pork & peanut curry","category":"Pork","country":"Thailand","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/snmtd61763426568.jpg","youtube_url":"https://www.youtube.com/watch?v=cxryD8ZHCdQ","source_url":"https://www.bbcgoodfood.com/recipes/thai-pork-peanut-curry","ingredients":[{"name":"Vegetable Oil","measure":"1 tablespoon"},{"name":"Spring Onions","measure":"Bunch"},{"name":"Coriander","measure":"Bunch"},{"name":"Pork Tenderloin","measure":"400g"},{"name":"Thai Red Curry Paste","measure":"4 tablespoons"},{"name":"Peanut Butter","measure":"4 tablespoons"},{"name":"Brown Sugar","measure":"1 tablespoon"},{"name":"Soy Sauce","measure":"1 tbsp"},{"name":"Coconut Milk","measure":"400ml"},{"name":"Sweetcorn","measure":"175g"},{"name":"Lime","measure":"Juice of 1"},{"name":"Jasmine Rice","measure":"Steamed"}],"steps":["Heat the oil in a large saucepan or flameproof casserole. Add the spring onions and coriander stalks and cook for 1 min. Add the pork slices and cook for 5 mins until starting to brown.","Stir in the curry paste and peanut butter. After 30 secs, add the sugar, soy and coconut milk, plus ½ can of water. Mix well, put a lid on and leave to simmer for 15 mins, stirring occasionally.","Remove the lid, add the baby corn and increase the heat. Bubble for 3 mins until the corn is cooked and the sauce has thickened a little. Stir in the lime juice and check the seasoning. Can now be frozen for up to 2 months. To cook from frozen: thoroughly defrost, then heat in a pan on the hob until curry is hot all the way through. Serve scattered with the coriander leaves and rice."],"ingredient_names":["vegetable oil","spring onions","coriander","pork tenderloin","thai red curry paste","peanut butter","brown sugar","soy sauce","coconut milk","sweetcorn","lime","jasmine rice"],"allergens":["gluten","peanuts","soy"],"diet_flags":[]},{"source_id":"53198","title":"Thai fried rice with prawns & peas","category":"Seafood","country":"Thailand","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/hblwvg1763478203.jpg","youtube_url":"https://www.youtube.com/watch?v=9wZAYbPcF-I","source_url":"https://www.bbcgoodfood.com/recipes/thai-fried-rice-prawns-peas","ingredients":[{"name":"Vegetable Oil","measure":"2 tbsp"},{"name":"Red Onions","measure":"1 sliced"},{"name":"Garlic Clove","measure":"2 sliced"},{"name":"Red Chilli","measure":"1 sliced"},{"name":"Raw King Prawns","measure":"250g"},{"name":"Brown Rice","measure":"140g"},{"name":"Frozen Peas","measure":"75g"},{"name":"Soy Sauce","measure":"1 tablespoon"},{"name":"Fish Sauce","measure":"1 tablespoon"},{"name":"Coriander","measure":"Bunch"},{"name":"Egg","measure":"4 large"},{"name":"Hotsauce","measure":"To serve"}],"steps":["Heat 1 tbsp of the oil in a wok, add the onion, garlic and chilli, and cook for 2-3 mins until golden.","Add the prawns and cook for 1 min.","Tip in the rice and peas, and keep tossing until very hot.","Add the soy and fish sauce, then stir through the chopped coriander.","Keep warm while you fry the eggs.","Heat the remaining oil in a frying pan and fry the eggs with some seasoning.","Divide the fried rice mix between 4 bowls and top each with a fried egg.","Serve scattered with coriander, with chilli sauce, if you like."],"ingredient_names":["vegetable oil","red onions","garlic clove","red chilli","raw king prawns","brown rice","frozen peas","soy sauce","fish sauce","coriander","egg","hotsauce"],"allergens":["eggs","fish","gluten","shellfish","soy"],"diet_flags":["pescatarian"]},{"source_id":"53199","title":"Thai beef stir-fry","category":"Beef","country":"Thailand","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/kyuxew1763479470.jpg","youtube_url":"https://www.youtube.com/watch?v=N3OI_7zu5sA","source_url":"https://www.bbcgoodfood.com/recipes/thai-beef-stir-fry","ingredients":[{"name":"Vegetable Oil","measure":"2 tbsp"},{"name":"Beef","measure":"400g"},{"name":"Red Chilli","measure":"1 sliced"},{"name":"Oyster Sauce","measure":"2 tblsp"},{"name":"Basil Leaves","measure":"Handful"}],"steps":["Heat a wok or large frying pan until smoking hot.","Pour in the oil and swirl around the pan, then tip in the beef strips and chilli.","Cook, stirring all the time, until the meat is lightly browned, about 3 mins, then pour over the oyster sauce.","Cook until heated through and the sauce coats the meat. stir in the basil leaves and serve with plain rice."],"ingredient_names":["vegetable oil","beef","red chilli","oyster sauce","basil leaves"],"allergens":["shellfish"],"diet_flags":[]},{"source_id":"53200","title":"Prawn stir-fry","category":"Seafood","country":"Thailand","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/96lt871763480970.jpg","youtube_url":"https://www.youtube.com/watch?v=DddM8OGb4Jc","source_url":"https://www.bbcgoodfood.com/recipes/thai-prawn-ginger-spring-onion-stir-fry","ingredients":[{"name":"Raw tiger prawns","measure":"200g"},{"name":"Green Chilli","measure":"1 chopped"},{"name":"Garlic","measure":"3 Cloves Crushed"},{"name":"Coriander","measure":"1  bunch"},{"name":"Caster Sugar","measure":"1 tblsp"},{"name":"Lime","measure":"Juice of 1"},{"name":"Fish Sauce","measure":"3 tbsp"},{"name":"Ground Nut Oil","measure":"2 tablespoons"},{"name":"Ginger","measure":"3cm piece"},{"name":"Spring Onions","measure":"8 slices"},{"name":"Red Pepper","measure":"1 sliced"},{"name":"Water Chestnut","measure":"85g"},{"name":"Bean Sprouts","measure":"100g"},{"name":"Soy Sauce","measure":"1 tablespoon"},{"name":"Rice Noodles","measure":"To serve"},{"name":"Lime","measure":"To serve"}],"steps":["Put the prawns in a bowl. Put the chilli, garlic, coriander stalks (snip these up using scissors first) and caster sugar in a spice grinder or small food processor and whizz together. Add half of the lime juice and the fish sauce, then pour this over the prawns.","Heat 1 tbsp oil in a wok, add the ginger and spring onions and fry for 1 min. Add the red pepper and fry for 1 min, until the pepper starts to soften. Add the water chestnuts and bean sprouts, and toss together until the bean sprouts start to wilt. Add the soy sauce and a really good grind of black pepper, then tip the lot into a serving dish.","Heat the remaining oil in the wok and add the prawns, lifting them out of their juices. Toss for 1-2 mins until they turn pink, add the marinade and swirl the wok quickly, then tip the lot onto the veg. Snip over the coriander leaves and sprinkle on the remaining lime. Serves over noodles with extra lime for squeezing over."],"ingredient_names":["raw tiger prawns","green chilli","garlic","coriander","caster sugar","lime","fish sauce","ground nut oil","ginger","spring onions","red pepper","water chestnut","bean sprouts","soy sauce","rice noodles","lime"],"allergens":["fish","gluten","shellfish","soy","tree_nuts"],"diet_flags":["pescatarian"]},{"source_id":"53201","title":"Stir-fried chicken with chillies & basil","category":"Chicken","country":"Thailand","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/el64dy1763483009.jpg","youtube_url":"https://www.youtube.com/watch?v=fF4GpyiZL8Q","source_url":"https://www.bbcgoodfood.com/recipes/ken-homs-stir-fried-chicken-chillies-basil","ingredients":[{"name":"Vegetable Oil","measure":"2 tablespoons"},{"name":"Chicken","measure":"450g"},{"name":"Garlic","measure":"3 tblsp chopped"},{"name":"Shallots","measure":"3 tblsp chopped"},{"name":"Red Chilli","measure":"3"},{"name":"Fish Sauce","measure":"2 tablespoons"},{"name":"Soy Sauce","measure":"2 tsp"},{"name":"Sugar","measure":"2 tsp"},{"name":"Basil Leaves","measure":"Handful"}],"steps":["Heat a wok or large frying pan until it is very hot, then add 1 tbsp of the oil. When it is very hot, add the chicken and stir-fry over a high heat for 8-10 minutes, until browned all over. Using a slotted spoon, take the chicken from the pan and set aside.","Reheat the wok and add the remaining oil. Toss in the garlic and shallots and stir fry for 3 minutes, until golden brown.","Return the chicken to the wok and add the chillies, fish sauce, dark soy sauce and sugar. Stir fry over a high heat for a further 8-10 minutes or until the chicken is cooked through. Stir in the basil leaves and serve at once."],"ingredient_names":["vegetable oil","chicken","garlic","shallots","red chilli","fish sauce","soy sauce","sugar","basil leaves"],"allergens":["fish","gluten","soy"],"diet_flags":[]},{"source_id":"53202","title":"Thai-style steamed fish","category":"Seafood","country":"Thailand","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/yx8j1i1763484612.jpg","youtube_url":"https://www.youtube.com/watch?v=KQ-dl8fuBlQ","source_url":"https://www.bbcgoodfood.com/recipes/thai-style-steamed-fish","ingredients":[{"name":"Trout","measure":"2"},{"name":"Ginger","measure":"Knob"},{"name":"Garlic Clove","measure":"1 small finely diced"},{"name":"Red Chilli","measure":"1 small finely diced"},{"name":"Lime","measure":"Juice/zest of one"},{"name":"Baby Pak Koi","measure":"3"},{"name":"Soy Sauce","measure":"2 tblsp"}],"steps":["Nestle the fish fillets side by side on a large square of foil and scatter the ginger, garlic, chilli and lime zest over them.","Drizzle the lime juice on top and then scatter the pieces of pak choi around and on top of the fish.","Pour the soy sauce over the pak choi and loosely seal the foil to make a package, making sure you leave space at the top for the steam to circulate as the fish cooks.","Steam for 15 minutes. (If you haven’t got a steamer, put the parcel on a heatproof plate over a pan of gently simmering water, cover with a lid and steam.)"],"ingredient_names":["trout","ginger","garlic clove","red chilli","lime","baby pak koi","soy sauce"],"allergens":["fish","gluten","soy"],"diet_flags":["pescatarian"]},{"source_id":"53203","title":"Thai rice noodle salad","category":"Vegetarian","country":"Thailand","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/6g3rso1763486069.jpg","youtube_url":null,"source_url":"https://www.bbcgoodfood.com/recipes/thai-rice-noodle-salad","ingredients":[{"name":"Vermicelli Rice Noodles","measure":"1/2 bag"},{"name":"Bean Sprouts","measure":"200g"},{"name":"Lime","measure":"Zest and juice of 2"},{"name":"Fish Sauce","measure":"2-3 tbsp"},{"name":"Muscovado Sugar","measure":"1 tsp"},{"name":"Red Onions","measure":"1 sliced"},{"name":"Lettuce","measure":"2 small"},{"name":"Minced Pork","measure":"500g"},{"name":"Ginger","measure":"Knob"},{"name":"Cayenne Pepper","measure":"Pinch"},{"name":"Sunflower Oil","measure":"1 tsp"},{"name":"Sesame Seed","measure":"2 tblsp"},{"name":"Oil","measure":"1 tsp"},{"name":"Sirloin steak","measure":"4"},{"name":"Red Chilli","measure":"1 sliced"}],"steps":["Place the noodles and beansprouts in a heatproof bowl and cover with boiling water. Leave for 4 mins, or until the noodles are tender. Drain, then cool under cold running water and drain again. Return to the bowl.","Stir together the lime zest and juice, fish or soy sauce and sugar. Stir into the noodles with the red onion and lettuce.","To make with mince, heat a little oil in a non-stick frying pan and stir-fry 500g minced pork, a small knob of grated ginger and pinch cayenne pepper or chilli powder for 10 mins, until the mince is browned and cooked through. Mix into the noodles, divide between four bowls and serve warm.","To make with steak, make the rice noodle salad. Heat 1 tsp sunflower oil in a frying pan. Tip 2 tbsp sesame seeds onto a plate. Rub 1 tsp oil into 4 x 175g sirloin steaks and press into sesame seeds. Fry for 5 mins for medium rare, turning halfway. Leave to rest for 5 mins, then thinly slice. Toss 1 deseeded and shredded red chilli, and a handful mint leaves into noodles. Top with steak to serve."],"ingredient_names":["vermicelli rice noodles","bean sprouts","lime","fish sauce","muscovado sugar","red onions","lettuce","minced pork","ginger","cayenne pepper","sunflower oil","sesame seed","oil","sirloin steak","red chilli"],"allergens":["fish","sesame"],"diet_flags":[]},{"source_id":"53204","title":"Red curry chicken kebabs","category":"Chicken","country":"Thailand","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/prjve31763486864.jpg","youtube_url":"https://www.youtube.com/watch?v=XJscdFRT8_8","source_url":"https://www.bbcgoodfood.com/recipes/red-curry-chicken-kebabs","ingredients":[{"name":"Chicken Breasts","measure":"2"},{"name":"Thai Red Curry Paste","measure":"2 tblsp"},{"name":"Coconut Milk","measure":"2 tblsp"},{"name":"Red Pepper","measure":"1 chopped"},{"name":"Courgettes","measure":"1 chopped"},{"name":"Red Onions","measure":"1 cut thin wedges"},{"name":"Lime","measure":"To serve"}],"steps":["Fire up the barbecue or heat a griddle pan to high.","Tip chicken, curry paste and coconut milk into a bowl, then mix well until the chicken is evenly coated.","Thread vegetables and chicken onto skewers.","Cook the skewers on the barbecue or griddle for 5-8 mins, turning every so often, until the chicken is cooked through and charred.","Serve with herby rice, salad and a lime half to squeeze over."],"ingredient_names":["chicken breasts","thai red curry paste","coconut milk","red pepper","courgettes","red onions","lime"],"allergens":[],"diet_flags":[]},{"source_id":"53205","title":"Thai prawn curry","category":"Seafood","country":"Thailand","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/qqlwv91763501559.jpg","youtube_url":"https://www.youtube.com/watch?v=dEMPVKQXSYA","source_url":"https://www.bbcgoodfood.com/recipes/easy-thai-prawn-curry","ingredients":[{"name":"Vegetable Oil","measure":"1 tbls"},{"name":"Onion","measure":"1 chopped"},{"name":"Ginger","measure":"1 tsp"},{"name":"Thai Red Curry Paste","measure":"2 tsp"},{"name":"Tinned Tomatos","measure":"400g"},{"name":"Coconut Cream","measure":"50g"},{"name":"Raw Frozen Prawns","measure":"400g"},{"name":"Coriander","measure":"Chopped"}],"steps":["Heat the oil in a medium saucepan.","Tip in the onion and ginger, then cook for a few mins until softened.","Stir in the curry paste, then cook for 1 min more.","Pour over the chopped tomatoes and coconut cream.","Bring to the boil, then leave to simmer for 5 mins, adding a little boiling water if the mixture gets too thick.","Tip in the prawns, then cook for 5-10 mins more, depending on how large they are.","Serve alongside some plain rice and sprinkle with a little chopped coriander, if you like."],"ingredient_names":["vegetable oil","onion","ginger","thai red curry paste","tinned tomatos","coconut cream","raw frozen prawns","coriander"],"allergens":["shellfish"],"diet_flags":["pescatarian"]},{"source_id":"53206","title":"Thai chicken cakes with sweet chilli sauce","category":"Chicken","country":"Thailand","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/6s3i3p1763488540.jpg","youtube_url":"https://www.youtube.com/watch?v=pT0WoqUZXw0","source_url":"https://www.bbcgoodfood.com/recipes/thai-chicken-cakes-sweet-chilli-sauce","ingredients":[{"name":"Chicken Breast","measure":"2 large"},{"name":"Garlic","measure":"1 clove"},{"name":"Ginger","measure":"1 small"},{"name":"Onion","measure":"1 chopped"},{"name":"Coriander","measure":"4 tbs"},{"name":"Green Chilli","measure":"1 chopped"},{"name":"Olive Oil","measure":"2 tblsp"},{"name":"sweet chilli sauce","measure":"To serve"},{"name":"Lime","measure":"To serve"},{"name":"Spring Onions","measure":"Chopped"},{"name":"Red Chilli","measure":"Chopped"}],"steps":["Toss the chicken, garlic, ginger, onion, coriander and chilli into a food processor and season well.","Blitz until the chicken is finely ground and everything is well mixed.","Use your hands to shape six small cakes.","Heat the oil in a frying pan, then fry the cakes over a medium heat for about 6-8 mins, turning once.","Serve hot, with sweet chilli sauce, lime wedges, coriander, shredded spring onion and red chilli."],"ingredient_names":["chicken breast","garlic","ginger","onion","coriander","green chilli","olive oil","sweet chilli sauce","lime","spring onions","red chilli"],"allergens":[],"diet_flags":[]},{"source_id":"53207","title":"Tom kha gai","category":"Chicken","country":"Thailand","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/ol2xxt1763582263.jpg","youtube_url":"https://www.youtube.com/watch?v=2BbIZwmIP7Q","source_url":"https://www.bbcgoodfood.com/recipes/tom-kha-gai","ingredients":[{"name":"Chicken Stock","measure":"800ml"},{"name":"Coconut Milk","measure":"800g"},{"name":"Galangal Paste","measure":"2 tablespoons"},{"name":"Lemongrass Stalks","measure":"2"},{"name":"Lime Leaves","measure":"8"},{"name":"Chicken Thighs","measure":"500g"},{"name":"Oyster Mushrooms","measure":"300g"},{"name":"Birds-eye Chillies","measure":"6"},{"name":"Caster Sugar","measure":"1 tablespoon"},{"name":"Fish Sauce","measure":"5 tablespoons"},{"name":"Lime","measure":"Juice of 3"},{"name":"Coriander Leaves","measure":"To serve"},{"name":"Rice","measure":"To serve"}],"steps":["Pour the chicken stock and coconut milk into a large saucepan set over a medium heat. Tip in the galangal, lemongrass and lime leaves, and bring to a gentle simmer, around 6-8 mins. Keeping at a gentle simmer, add the chicken. Cook for 8-10 mins until tender and cooked through.","Stir in the mushrooms and chillies, and simmer for a further 3-5 mins until everything is cooked through. Sprinkle in the sugar and 3 tbsp each of the fish sauce and lime juice. Taste and add the remaining if required.","Remove the galangal, lemongrass and lime leaves before serving using a slotted spoon. Ladle into bowls and serve with coriander leaves sprinkled over and steamed rice on the side. Will keep chilled for up to three days. Leave to cool first."],"ingredient_names":["chicken stock","coconut milk","galangal paste","lemongrass stalks","lime leaves","chicken thighs","oyster mushrooms","birds-eye chillies","caster sugar","fish sauce","lime","coriander leaves","rice"],"allergens":["fish","shellfish"],"diet_flags":[]},{"source_id":"53208","title":"Thai coconut & veg broth","category":"Vegetarian","country":"Thailand","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/4k8nzy1763583384.jpg","youtube_url":"https://www.youtube.com/watch?v=1OeM2sdLOPk","source_url":"https://www.bbcgoodfood.com/recipes/thai-coconut-veg-broth","ingredients":[{"name":"Thai Red Curry Paste","measure":"1 ½ tbsp"},{"name":"Vegetable Oil","measure":"1 tsp"},{"name":"Vegetable Stock","measure":"1 L"},{"name":"Coconut Milk","measure":"400ml"},{"name":"Brown Sugar","measure":"2 tsp"},{"name":"Egg Noodles","measure":"175g"},{"name":"Carrots","measure":"2"},{"name":"Chinese Leaf","measure":"1/2"},{"name":"Bean Sprouts","measure":"150g"},{"name":"Cherry Tomatoes","measure":"6"},{"name":"Lime","measure":"Juice of 1"},{"name":"Spring Onions","measure":"3 sliced thinly"},{"name":"Coriander","measure":"Handful"}],"steps":["Place the curry paste in a large saucepan or wok with the oil.","Fry for 1 min until fragrant.","Tip in the vegetable stock, coconut milk and brown sugar. Simmer for 3 mins.","Add the noodles, carrots and Chinese leaf and simmer for 4-6 mins, until all are tender.","Mix in beansprouts and tomatoes.","Add lime juice to taste and some extra seasoning, if you like.","Spoon into bowls and sprinkle with spring onions and coriander."],"ingredient_names":["thai red curry paste","vegetable oil","vegetable stock","coconut milk","brown sugar","egg noodles","carrots","chinese leaf","bean sprouts","cherry tomatoes","lime","spring onions","coriander"],"allergens":["eggs","gluten"],"diet_flags":["pescatarian","vegetarian"]},{"source_id":"53209","title":"Spicy Thai prawn noodles","category":"Seafood","country":"Thailand","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/568t931763584227.jpg","youtube_url":null,"source_url":"https://www.bbcgoodfood.com/recipes/spicy-thai-prawn-noodles","ingredients":[{"name":"Rice Noodles","measure":"200g"},{"name":"Sesame Seed Oil","measure":"1 tablespoon"},{"name":"Egg","measure":"2 Beaten"},{"name":"Red Chilli","measure":"1 chopped"},{"name":"Ginger","measure":"3cm piece"},{"name":"Prawns","measure":"450g"},{"name":"Soy Sauce","measure":"1 tablespoon"},{"name":"Coriander","measure":"Bunch"},{"name":"Mint","measure":"1/2 handful"},{"name":"Lime","measure":"Zest and juice of 1"},{"name":"Peanuts","measure":"Handful"}],"steps":["Cook the noodles following the pack instructions, drain and set aside for later.","Heat the oil in a large frying pan and pour in the beaten egg.","Swirl around the pan to make a thin omelette, cook for 1-2 mins, then flip over and cook the other side for 1 min.","Tip out and slice into thin strips.","Add the chilli and ginger to the pan, fry for 1-2 mins then tip in the noodles, prawns and egg.","Splash in the soy sauce and stir-fry for 1 min more.","Throw in the chopped herbs and pour over the lime juice and zest, then sprinkle over the chopped peanuts and serve."],"ingredient_names":["rice noodles","sesame seed oil","egg","red chilli","ginger","prawns","soy sauce","coriander","mint","lime","peanuts"],"allergens":["eggs","gluten","peanuts","sesame","shellfish","soy"],"diet_flags":["pescatarian"]},{"source_id":"53210","title":"Thai pumpkin soup","category":"Vegetarian","country":"Thailand","tags":["Soup","Haloween"],"image_url":"https://www.themealdb.com/images/media/meals/1brbso1763585098.jpg","youtube_url":"https://www.youtube.com/watch?v=X3BxTRAhgTc","source_url":"https://www.bbcgoodfood.com/recipes/thai-pumpkin-soup","ingredients":[{"name":"Pumpkin","measure":"1.5kg"},{"name":"Sunflower Oil","measure":"4 tsp"},{"name":"Onion","measure":"1 sliced"},{"name":"Ginger","measure":"1 tbsp grated"},{"name":"Lemongrass","measure":"1"},{"name":"Thai Red Curry Paste","measure":"4 tablespoons"},{"name":"Coconut Milk","measure":"400ml"},{"name":"Vegetable Stock","measure":"800ml"},{"name":"Lime juice","measure":"To taste"},{"name":"Sugar","measure":"To taste"},{"name":"Red Chilli","measure":"To serve"}],"steps":["Heat oven to 200C/180C fan/gas 6.","Toss the pumpkin or squash in a roasting tin with half the oil and seasoning, then roast for 30 mins until golden and tender.","Meanwhile, put the remaining oil in a pan with the onion, ginger and lemongrass.","Gently cook for 8-10 mins until softened.","Stir in the curry paste for 1 min, followed by the roasted pumpkin, all but 3 tbsp of the coconut milk and the stock.","Bring to a simmer, cook for 5 mins, then fish out the lemongrass.","Cool for a few mins, then whizz until smooth with a hand blender, or in a large blender in batches.","Return to the pan to heat through, seasoning with salt, pepper, lime juice and sugar, if it needs it.","Serve drizzled with the remaining coconut milk and scattered with chilli, if you like."],"ingredient_names":["pumpkin","sunflower oil","onion","ginger","lemongrass","thai red curry paste","coconut milk","vegetable stock","lime juice","sugar","red chilli"],"allergens":[],"diet_flags":["pescatarian","vegan","vegetarian"]},{"source_id":"53211","title":"Lemongrass beef stew with noodles","category":"Beef","country":"Thailand","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/ntafxw1763586291.jpg","youtube_url":null,"source_url":"https://www.bbcgoodfood.com/recipes/lemongrass-beef-stew-noodles","ingredients":[{"name":"Ginger","measure":"1 tablespoon chopped"},{"name":"Garlic Clove","measure":"2 chopped"},{"name":"Lemongrass Stalks","measure":"3"},{"name":"Coriander Leaves","measure":"2 tblsp"},{"name":"Red Chilli","measure":"2 sliced"},{"name":"Vegetable Oil","measure":"2 tblsp"},{"name":"Beef","measure":"250g"},{"name":"Soy Sauce","measure":"2 tblsp"},{"name":"Five Spice Powder","measure":"1 tsp"},{"name":"Brown Sugar","measure":"1 tsp"},{"name":"Beef Stock","measure":"400ml"},{"name":"Rice Noodles","measure":"100g"},{"name":"Lime","measure":"To serve"}],"steps":["Put the ginger, garlic, lemongrass, coriander and 1 chilli in a food processor, then pulse until puréed.","Heat the oil in a pan over a low heat.","Add the purée and cook for 5 mins.","Stir in the beef, soy, five-spice, sugar and stock.","Put on a lid and bring to the boil, then lower heat and simmer for 1 hr 15 mins.","Remove the lid and cook for a further 15 mins until the beef is tender.","Just before serving, prepare noodles following pack instructions.","Drain well, then divide between 2 bowls and spoon over the beef stew.","Serve sprinkled with the remaining chilli and coriander leaves, with lime wedges for squeezing over."],"ingredient_names":["ginger","garlic clove","lemongrass stalks","coriander leaves","red chilli","vegetable oil","beef","soy sauce","five spice powder","brown sugar","beef stock","rice noodles","lime"],"allergens":["gluten","soy"],"diet_flags":[]},{"source_id":"53212","title":"Thai drumsticks","category":"Chicken","country":"Thailand","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/ittake1763586925.jpg","youtube_url":"https://www.youtube.com/watch?v=lv1tj9FK3f0","source_url":"https://www.bbcgoodfood.com/recipes/fragrant-thai-drumsticks","ingredients":[{"name":"sweet chilli sauce","measure":"2 tablespoons"},{"name":"Orange","measure":"Zest of 1"},{"name":"Orange","measure":"2 tblsp"},{"name":"Garlic","measure":"1 clove peeled crushed"},{"name":"Thai Red Curry Paste","measure":"1 tblsp"},{"name":"Chicken drumsticks","measure":"8"}],"steps":["Heat oven to 200C/180C fan/gas 6 and line a baking tray with foil.","Mix the chilli sauce with the orange zest and juice, garlic, curry paste and ¼ tsp salt.","Add the chicken and coat really well.","Arrange the drumsticks on the foil, spaced apart.","Coat the chicken with any marinade left in the bowl, then roast for 35-40 mins until tender.","Wrap in foil or pack into a food container."],"ingredient_names":["sweet chilli sauce","orange","orange","garlic","thai red curry paste","chicken drumsticks"],"allergens":[],"diet_flags":[]},{"source_id":"53213","title":"Thai-style fish broth with greens","category":"Seafood","country":"Thailand","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/a2ec961763587756.jpg","youtube_url":"https://www.youtube.com/watch?v=rRwnwCd5om8","source_url":"https://www.bbcgoodfood.com/recipes/thai-style-fish-broth-greens","ingredients":[{"name":"Brown Rice Noodle","measure":"100g"},{"name":"Chicken Stock","measure":"500ml"},{"name":"Thai Red Curry Paste","measure":"1 tblsp"},{"name":"Lime Leaves","measure":"4"},{"name":"Fish Sauce","measure":"1 tblsp"},{"name":"White Fish","measure":"200g"},{"name":"Raw King Prawns","measure":"100g"},{"name":"Pak Choi","measure":"2"},{"name":"Coriander Leaves","measure":"Handful"}],"steps":["Cook the noodles following pack instructions. Refresh in cold water and drain well.","Put the stock in a large saucepan and stir in the curry paste, lime leaves, fish sauce and 250ml cold water. Bring to a simmer and cook for 5 mins.","Cut the fish into roughly 3cm cubes and add to the pan. Return to a simmer, then cook for 2 mins uncovered.","Stir in the noodles, prawns and pak choi, and simmer for 2-3 mins or until the fish and prawns are just cooked. Serve in bowls scattered with coriander."],"ingredient_names":["brown rice noodle","chicken stock","thai red curry paste","lime leaves","fish sauce","white fish","raw king prawns","pak choi","coriander leaves"],"allergens":["fish","shellfish"],"diet_flags":[]},{"source_id":"53214","title":"Thai green chicken soup","category":"Chicken","country":"Thailand","tags":["Soup"],"image_url":"https://www.themealdb.com/images/media/meals/7kb44y1763589084.jpg","youtube_url":"https://www.youtube.com/watch?v=3s4Yitd546w","source_url":"https://www.bbcgoodfood.com/recipes/thai-green-chicken-soup","ingredients":[{"name":"Sunflower Oil","measure":"2 tblsp"},{"name":"Onion","measure":"1 chopped"},{"name":"Chicken Thighs","measure":"500g"},{"name":"Garlic Clove","measure":"4 sliced"},{"name":"Thai Green Curry Paste","measure":"280g"},{"name":"Coconut Milk","measure":"400ml"},{"name":"Chicken Stock","measure":"2 Litres"},{"name":"Lime Leaves","measure":"5"},{"name":"Fish Sauce","measure":"2 tblsp"},{"name":"Spring Onions","measure":"1  bunch"},{"name":"Green Beans","measure":"280g"},{"name":"Bamboo Shoot","measure":"150g"},{"name":"Lime","measure":"Juice of 2"},{"name":"Basil","measure":"Bunch"}],"steps":["Heat the oil in your largest pan, add the onion and fry for 3 mins to soften. Add the chicken and garlic, and cook until the chicken changes colour.","Add the curry paste, coconut milk, stock, lime leaves and fish sauce, then simmer for 12 mins. Add the chopped onion tops, green beans and bamboo shoots and cook for 4-6 mins, until the beans are just tender.","Meanwhile, put the lime juice and basil in a narrow jug and blitz with a hand blender to make a smooth green paste. Pour into the soup with the sliced spring onion and heat through. Serve with lime wedges for a light lunch or supper or as a make-ahead starter."],"ingredient_names":["sunflower oil","onion","chicken thighs","garlic clove","thai green curry paste","coconut milk","chicken stock","lime leaves","fish sauce","spring onions","green beans","bamboo shoot","lime","basil"],"allergens":["fish"],"diet_flags":[]},{"source_id":"53217","title":"Shawarma chuck roast wrap","category":"Beef","country":"Saudi Arabia","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/swo87v1763595282.jpg","youtube_url":"https://www.youtube.com/shorts/YLhyRjyLkcE","source_url":"https://cookpad.com/eng/recipes/24415920?ref=search&search_term=saudi+arabia","ingredients":[{"name":"Chuck Roast","measure":"1kg"},{"name":"Beef Stock","measure":"1 cup"},{"name":"Lemon Juice","measure":"3  tablespoons"},{"name":"Ground Cumin","measure":"1 tablespoon"},{"name":"Paprika","measure":"2 tsp"},{"name":"Salt","measure":"1 tsp"},{"name":"Ground Ginger","measure":"1 tsp"},{"name":"Turmeric","measure":"1 tsp"},{"name":"Cayenne Pepper","measure":"1/2 teaspoon"},{"name":"Ground Cinnamon","measure":"1/2 teaspoon"},{"name":"Ground Coriander","measure":"1/2 teaspoon"},{"name":"Ground Clove","measure":"1/4 tsp"}],"steps":["In a dutch oven or slow cooker, add all the spices, beef broth and lemon juice. Stir to combine..","Add the beef and turn to coat, spoon some sauce over the top.","Cover and cook on low for 8-10 hours.","After cooking, remove beef and use two forks to shred. Discard any excess fat.","Skim fat off of the top of the liquid remaining.","Mix shredded beef into sauce. Keep warm until you are ready to serve.","Build wrap by spreading garlic sauce on the pita. Top with beef and add garnishes to your liking.","Fold it burrito style.","Heat a grill pan and grill the wrap."],"ingredient_names":["chuck roast","beef stock","lemon juice","ground cumin","paprika","salt","ground ginger","turmeric","cayenne pepper","ground cinnamon","ground coriander","ground clove"],"allergens":[],"diet_flags":[]},{"source_id":"53218","title":"Chicken Shawarma with homemade garlic herb yoghurt sauce","category":"Chicken","country":"Saudi Arabia","tags":["Kebab"],"image_url":"https://www.themealdb.com/images/media/meals/hcg6l91763596970.jpg","youtube_url":"https://www.youtube.com/watch?v=TROZvPHqP1g","source_url":"https://cookpad.com/eng/recipes/24343467?ref=search&search_term=saudi+arabia","ingredients":[{"name":"Chicken Breast","measure":"1kg"},{"name":"Garlic","measure":"2 cloves minced"},{"name":"Ground Coriander","measure":"1 tblsp"},{"name":"Ground Cumin","measure":"1 tblsp"},{"name":"Ground Cardomom","measure":"1 tblsp"},{"name":"Cayenne Pepper","measure":"1 tsp"},{"name":"Smoked Paprika","measure":"2 tsp"},{"name":"Salt","measure":"2 tsp"},{"name":"Lemon Juice","measure":"2 tblsp"},{"name":"Olive Oil","measure":"3 tablespoons"},{"name":"Greek Yogurt","measure":"1 cup"},{"name":"Garlic","measure":"1 clove peeled crushed"},{"name":"Cumin","measure":"1 tsp"},{"name":"Lemon Juice","measure":"Splash"}],"steps":["Start by cutting your chicken up into reasonably small slices. Grab your ziplock bag and dump the freshly sliced chicken inside.","Add garlic, coriander, cumin, cardomom, cayenne pepper, paprika, salt, pepper, lemon juice and olive oil to the bag. Close the bag and mix thoroughly. Place in fridge for 10-12 hours (shorter is fine but longer is better).","Once ready to cook, heat your fry pan to medium-high and add a tiny bit of olive oil. Fry one side of all of your flatbreads until slightly toasty. Remove from pan, add enough oil to coat the fry pan. Put crumble fries into air fryer on 180 for 15 minutes shaking occasionally.","The pan should be pretty hot by now, add the chicken in 2 batches (unless you have a big fry pan) to avoid overcrowding. The chicken should get a nice sear and darker colour which is perfect. Cook for a further 5-8 minutes or until cooked through. Repeat with next chicken batch.","While chicken is cooking, place your Greek yoghurt into a bowl. Combine garlic, finely chopped mint and parsley, squeeze or so of lemon and cumin. Combine and add salt to taste. In a small bowl, combine 1tsp garlic powder, paprika, cumin, onion powder, oregano, dried parsley, cayenne pepper (optional) mix and leave aside for fries.","Season fries immediately once cooked and add salt to taste. Once the chicken is complete, serve immediately by laying out your flatbread, spreading the sauce evenly over the bread, add lettuce, onion, tomato, fries, chicken, feta and more sauce on top. Serve immediately."],"ingredient_names":["chicken breast","garlic","ground coriander","ground cumin","ground cardomom","cayenne pepper","smoked paprika","salt","lemon juice","olive oil","greek yogurt","garlic","cumin","lemon juice"],"allergens":["dairy"],"diet_flags":[]},{"source_id":"53220","title":"kabse","category":"Chicken","country":"Saudi Arabia","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/utqnjv1763598650.jpg","youtube_url":"https://www.youtube.com/watch?v=lrcUixJEPK0","source_url":"https://cookpad.com/eng/recipes/17108731?ref=search&search_term=saudi+arabia","ingredients":[{"name":"Chicken","measure":"400g"},{"name":"Rice","measure":"1 cup"},{"name":"Green Pepper","measure":"1"},{"name":"Red Pepper","measure":"1"},{"name":"Mushrooms","measure":"2"},{"name":"Sweetcorn","measure":"1"},{"name":"Carrots","measure":"2"},{"name":"Raisins","measure":"Handful"},{"name":"Turmeric","measure":"1 tsp"},{"name":"Kabse Spice","measure":"1 tsp"},{"name":"Salt","measure":"Pinch"},{"name":"Black Pepper","measure":"Pinch"}],"steps":["Caramelize the chicken with olive oil then add a maggi cube and boil it for around 30 minutes.","In another pot, add all the veggies and caramelize them till they are soft.","Once everything is done, add the rice, raisins & spices to the veggies and add 2 and a half cups of water for the rice to cook.","Once the rice is done put everything in the oven."],"ingredient_names":["chicken","rice","green pepper","red pepper","mushrooms","sweetcorn","carrots","raisins","turmeric","kabse spice","salt","black pepper"],"allergens":[],"diet_flags":[]},{"source_id":"53222","title":"Vegetarian Shakshuka","category":"Vegetarian","country":"Saudi Arabia","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/eo0yfb1763600916.jpg","youtube_url":"https://www.youtube.com/watch?v=ZNEos6ybryg","source_url":"https://cookpad.com/eng/recipes/16275721?ref=search&search_term=saudi+arabia","ingredients":[{"name":"Red Onions","measure":"1/2"},{"name":"Red Pepper","measure":"1/2"},{"name":"Tomato","measure":"400g"},{"name":"Cumin","measure":"1/2 teaspoon"},{"name":"Garlic Granules","measure":"1/2 tsp"},{"name":"Cayenne Pepper","measure":"1/2 teaspoon"},{"name":"Paprika","measure":"1 tsp"},{"name":"Egg","measure":"2"},{"name":"Parsley","measure":"Garnish"},{"name":"Chilli Flakes","measure":"Garnish"},{"name":"Toast","measure":"2 sliced"}],"steps":["Fry onion and pepper together on medium heat until onion is soft","Add garlic granules, cook for a minute","Add chopped tomatoes and remaining spices, stir well","Simmer for about 20 minutes","Make indents for in the sauce and crack an egg into each one","Once egg whites are cooked through, garnish and serve with toast"],"ingredient_names":["red onions","red pepper","tomato","cumin","garlic granules","cayenne pepper","paprika","egg","parsley","chilli flakes","toast"],"allergens":["eggs"],"diet_flags":["pescatarian","vegetarian"]},{"source_id":"53227","title":"Rice paper dumplings","category":"Pork","country":"Vietnam","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/sfahy01763752319.jpg","youtube_url":"https://www.youtube.com/shorts/YU09jIusxo4","source_url":"https://www.bbcgoodfood.com/recipes/rice-paper-dumplings","ingredients":[{"name":"White Cabbage","measure":"1/4"},{"name":"Carrots","measure":"1"},{"name":"Shiitake Mushrooms","measure":"100g"},{"name":"Ground Pork","measure":"400g"},{"name":"Garlic","measure":"2 cloves minced"},{"name":"Ginger","measure":"20g"},{"name":"Soy Sauce","measure":"2 tsp"},{"name":"Sesame Seed Oil","measure":"2 tsp"},{"name":"Spring Onions","measure":"3 sliced thinly"},{"name":"Rice Paper Sheets","measure":"20"},{"name":"Vegetable Oil","measure":"75 ml"},{"name":"Soy Sauce","measure":"2 tablespoons"},{"name":"Rice Vinegar","measure":"2 tablespoons"},{"name":"Sesame Seed","measure":"1/2 tbs"},{"name":"Spring Onions","measure":"2 sliced"}],"steps":["Tip the cabbage into a food processor and blitz until finely chopped. Season with ½ tsp salt, toss well and set aside for 15 mins. Tip into a clean tea towel and squeeze out as much water as you can. Tip into a bowl with the carrot, mushrooms, pork mince, garlic, ginger, soy sauce, sesame oil and spring onions. Season with black pepper. Scrunch everything together using your hands, mixing well until everything is combined.","Soak the spring roll sheets for a couple of seconds in a shallow dish of warm water, then transfer to an oiled chopping board. Working with one sheet at a time, spoon 1 heaped tbsp of the filling into the middle, then fold the bottom up and over the filling. Fold down the top of the sheet, then the sides to fully encase and make a neat square. If the dumpling feels a little fragile, soak another sheet and wrap it again. Repeat with the remaining sheets and filling, transferring the dumplings to an oiled plate as you go.","Heat the oil in a large, non-stick frying pan (ensuring it is no more than a third full) over a medium-high heat and fry the dumplings for 3-5 mins until golden brown. Use a slotted spoon or spider to turn them, then cover with a lid and cook for another 3-4 mins until golden. Remove the lid and cook for 1-2 mins.","Meanwhile, combine all the dipping sauce ingredients in small bowl. Serve the dumplings with the dipping sauce on the side."],"ingredient_names":["white cabbage","carrots","shiitake mushrooms","ground pork","garlic","ginger","soy sauce","sesame seed oil","spring onions","rice paper sheets","vegetable oil","soy sauce","rice vinegar","sesame seed","spring onions"],"allergens":["gluten","sesame","soy"],"diet_flags":[]},{"source_id":"53228","title":"Vietnamese caramel trout","category":"Seafood","country":"Vietnam","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/p02vq41763754350.jpg","youtube_url":"https://www.youtube.com/watch?v=3MBbvrUtn74","source_url":"https://www.bbcgoodfood.com/recipes/vietnamese-caramel-trout","ingredients":[{"name":"Golden Caster Sugar","measure":"50g"},{"name":"Fish Sauce","measure":"1 tablespoon"},{"name":"Red Chilli","measure":"1 sliced"},{"name":"Ginger","measure":"large piece"},{"name":"Rainbow Trout","measure":"2"},{"name":"Bok Choi","measure":"2 heads"},{"name":"Lemon","measure":"Juice of 1/2"},{"name":"Coriander","measure":"Sprigs of fresh"},{"name":"Rice","measure":"Steamed"}],"steps":["Put the sugar in a large shallow pan, along with a small splash of water.","Heat gently, swirling the pan, until the sugar has dissolved.","Increase the heat and bubble the syrup until it turns a dark amber colour.","Add the fish sauce, most of the chilli and ginger, then splash in 1 tbsp water to dilute.","Boil again until syrupy, then add the fish fillets, skin-side down, and the bok choi, cut-side down.","Cover the pan with a lid and simmer for 4-5 mins until the fish is cooked and the bok choi has wilted.","Turn off the heat, squeeze over the lemon and scatter with the remaining chilli, ginger and the coriander sprigs. Serve with rice."],"ingredient_names":["golden caster sugar","fish sauce","red chilli","ginger","rainbow trout","bok choi","lemon","coriander","rice"],"allergens":["fish"],"diet_flags":["pescatarian"]},{"source_id":"53229","title":"Steak & Vietnamese noodle salad","category":"Beef","country":"Vietnam","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/st9shl1763755808.jpg","youtube_url":"https://www.youtube.com/watch?v=Lo4_GdyetEU","source_url":"https://www.bbcgoodfood.com/recipes/steak-vietnamese-noodle-salad","ingredients":[{"name":"Brown Rice Noodle","measure":"85g"},{"name":"Rapeseed Oil","measure":"1 tsp"},{"name":"Fillet Of Steak","measure":"250g"},{"name":"Carrots","measure":"2"},{"name":"Chinese Cabbage","measure":"1/2"},{"name":"Spring Onions","measure":"4 finely sliced"},{"name":"Coriander","measure":"Handful"},{"name":"Red Chilli","measure":"1 sliced"},{"name":"Lime","measure":"Juice of 1"},{"name":"Brown Sugar","measure":"2 tsp"},{"name":"Rice Vinegar","measure":"1 tsp"},{"name":"Garlic Clove","measure":"1 chopped"},{"name":"Fish Sauce","measure":"1/2 tbs"}],"steps":["Mix all the ingredients for the dressing together in a bowl with 1 tbsp water until the sugar has dissolved.","Cook the noodles following pack instructions, then plunge into a bowl of cold water to cool completely. Drain the noodles, then add the carrot, cabbage, spring onion and dressing, and toss to combine.","Heat the oil in a frying pan over a high heat. Season the steak, then cook to your liking; 2-3 mins on each side for medium rare. Leave to rest for 5 mins, then slice. Divide the salad and steak slices between bowls and scatter over some coriander to serve."],"ingredient_names":["brown rice noodle","rapeseed oil","fillet of steak","carrots","chinese cabbage","spring onions","coriander","red chilli","lime","brown sugar","rice vinegar","garlic clove","fish sauce"],"allergens":["fish"],"diet_flags":[]},{"source_id":"53231","title":"Vietnamese lamb shanks with sweet potatoes","category":"Lamb","country":"Vietnam","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/7xte3u1763757761.jpg","youtube_url":"https://www.tiktok.com/@shanice_and_lima/video/7280471655959383297","source_url":"https://www.bbcgoodfood.com/recipes/vietnamese-lamb-shanks-sweet-potatoes","ingredients":[{"name":"Ground Nut Oil","measure":"2 tablespoons"},{"name":"Lamb Shanks","measure":"4"},{"name":"Onion","measure":"2"},{"name":"Ginger","measure":"2 tbs chopped"},{"name":"Garlic Clove","measure":"3 sliced thinly"},{"name":"Red Chilli","measure":"1 chopped"},{"name":"Red Chilli","measure":"1 sliced"},{"name":"Brown Sugar","measure":"1 tablespoon"},{"name":"Brown Sugar","measure":"1 tsp"},{"name":"Star Anise","measure":"3"},{"name":"Lemongrass Stalks","measure":"2"},{"name":"Lamb Stock","measure":"1L"},{"name":"Tomato Puree","measure":"1 ½ tbsp"},{"name":"Sweet Potatoes","measure":"4"},{"name":"Fish Sauce","measure":"2 tablespoons"},{"name":"Lime","measure":"Juice of 2"},{"name":"Mint","measure":"Handful"},{"name":"Basil Leaves","measure":"Handful"}],"steps":["Heat oven to 160C/140C fan/gas 3.","Heat 1 tbsp oil in a heavy-bottomed casserole, season the shanks, then brown them 2 at a time on all sides, adding the remaining oil for the second batch.","Remove the lamb and add the onions.","Fry them quite briskly, about 30 secs, add the ginger, garlic and chopped chilli, then turn the heat down and cook for 1 min.","Add 1 tbsp sugar, stir, then add the star anise, lemongrass, stock, purée and seasoning. Bring to the boil.","Cover and cook in the oven for 1½ hrs, then add the sweet potatoes and cook for 1 hr more.","The lamb should be completely tender and almost falling off the bones.","Stir in the fish sauce, lime juice and 1 tsp sugar to just lift the flavour, then scatter with the mint, basil and the sliced chilli to serve."],"ingredient_names":["ground nut oil","lamb shanks","onion","ginger","garlic clove","red chilli","red chilli","brown sugar","brown sugar","star anise","lemongrass stalks","lamb stock","tomato puree","sweet potatoes","fish sauce","lime","mint","basil leaves"],"allergens":["fish","tree_nuts"],"diet_flags":[]},{"source_id":"53232","title":"Vietnamese chicken salad","category":"Chicken","country":"Vietnam","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/pk8wtn1763758591.jpg","youtube_url":"https://www.youtube.com/watch?v=behSkhzKpHI","source_url":"https://www.bbcgoodfood.com/recipes/vietnamese-chicken-salad","ingredients":[{"name":"Rice Noodles","measure":"140g"},{"name":"Carrots","measure":"1"},{"name":"Cucumber","measure":"1/2"},{"name":"Chicken Breasts","measure":"2"},{"name":"Radish","measure":"50g"},{"name":"Red Onions","measure":"1/2"},{"name":"Mint","measure":"Bunch"},{"name":"Peanuts","measure":"25g"},{"name":"Red Chilli","measure":"1 chopped"},{"name":"Lime","measure":"Zest and juice of 1"},{"name":"Fish Sauce","measure":"1 ½ tbsp"},{"name":"Soy Sauce","measure":"1 ½ tbsp"},{"name":"Sesame Seed Oil","measure":"1 ½ tbsp"}],"steps":["To make the dressing, whisk all the ingredients together in a large serving bowl.","Cook the noodles following pack instructions, then drain and add to the bowl with the dressing.","Peel the carrot into long strips using a vegetable peeler.","Do the same for the cucumber, until you reach the seeds (discard them).","Add the carrot and cucumber to the noodle mixture along with the shredded chicken, radishes, red onion and mint.","Toss well to coat in the dressing, scatter over the peanuts and serve."],"ingredient_names":["rice noodles","carrots","cucumber","chicken breasts","radish","red onions","mint","peanuts","red chilli","lime","fish sauce","soy sauce","sesame seed oil"],"allergens":["fish","gluten","peanuts","sesame","soy"],"diet_flags":[]},{"source_id":"53233","title":"Salt & pepper squid","category":"Seafood","country":"Vietnam","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/yxiilf1763759428.jpg","youtube_url":"https://www.youtube.com/watch?v=l1Ik6k22s1I","source_url":"https://www.bbcgoodfood.com/recipes/salt-pepper-squid","ingredients":[{"name":"Corn Flour","measure":"85g"},{"name":"Plain Flour","measure":"85g"},{"name":"Black Pepper","measure":"2 tsp"},{"name":"Szechuan Peppercorns","measure":"2 tsp"},{"name":"Sunflower Oil","measure":"For frying"},{"name":"Squid","measure":"400g"},{"name":"Spring Onions","measure":"Sliced"},{"name":"Green Chilli","measure":"Sliced"},{"name":"Red Chilli","measure":"1 chopped"},{"name":"Cucumber","measure":"1/2"},{"name":"Red Onions","measure":"1 chopped"},{"name":"Rice Vinegar","measure":"100 ml"},{"name":"Caster Sugar","measure":"1 tablespoon"},{"name":"Fish Sauce","measure":"2 tsp"}],"steps":["To make the dipping sauce, mix all the ingredients in a small bowl until the sugar has dissolved, then set aside.","Mix the cornflour and plain flour with both peppers and 2 tsp sea salt in a large bowl, then set aside.","Line a tray with kitchen paper and make sure you have more salt to sprinkle with.","Heat about 7cm of oil to 180C in a deep fryer, wok or deep pan.","If you don’t have a thermometer, you can test it with a cube of bread – it should brown in 20 secs.","Coat the squid well with the flour mix and fry in batches for about 2 mins each or until crisp.","Use a slotted spoon to lift out the squid, then drain on the kitchen paper and sprinkle with a little more salt.","Serve the squid scattered with the spring onion and chilli, with the dipping sauce on the side."],"ingredient_names":["corn flour","plain flour","black pepper","szechuan peppercorns","sunflower oil","squid","spring onions","green chilli","red chilli","cucumber","red onions","rice vinegar","caster sugar","fish sauce"],"allergens":["fish","gluten","shellfish"],"diet_flags":["pescatarian"]},{"source_id":"53234","title":"Salmon noodle soup","category":"Seafood","country":"Vietnam","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/ikizdm1763760862.jpg","youtube_url":"https://www.youtube.com/watch?v=__Kh1sizUAM","source_url":"https://www.bbcgoodfood.com/recipes/salmon-noodle-soup","ingredients":[{"name":"Chicken Stock","measure":"1 L"},{"name":"Thai Red Curry Paste","measure":"2 tsp"},{"name":"Rice Noodles","measure":"100g"},{"name":"Shiitake Mushrooms","measure":"150g"},{"name":"Sweetcorn","measure":"125g"},{"name":"Salmon","measure":"2"},{"name":"Lime","measure":"Juice of 2"},{"name":"Soy Sauce","measure":"1 tablespoon"},{"name":"Brown Sugar","measure":"Pinch"},{"name":"Coriander","measure":"Bunch"}],"steps":["Pour the stock into a large pan, bring to the boil, then stir in the curry paste.","Add the noodles and cook for 8 mins.","Tip in the mushrooms and corn and cook for 2 mins more.","Add the salmon to the pan and cook for 3 mins or until cooked through.","Remove from the heat and stir in the lime juice, soy sauce and a pinch of sugar.","Ladle into 4 bowls and sprinkle over the coriander just before you serve."],"ingredient_names":["chicken stock","thai red curry paste","rice noodles","shiitake mushrooms","sweetcorn","salmon","lime","soy sauce","brown sugar","coriander"],"allergens":["fish","gluten","soy"],"diet_flags":[]},{"source_id":"53235","title":"Vietnamese-style caramel pork","category":"Pork","country":"Vietnam","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/4mzt101763761546.jpg","youtube_url":"https://www.youtube.com/watch?v=qmQe0Qxvyzc","source_url":"https://www.bbcgoodfood.com/recipes/vietnamese-style-caramel-pork","ingredients":[{"name":"Ground Nut Oil","measure":"1 ½ tbsp"},{"name":"Pork Shoulder Steaks","measure":"500g"},{"name":"Shallots","measure":"2 chopped"},{"name":"Ground Ginger","measure":"1 tablespoon"},{"name":"Red Chilli","measure":"1 chopped"},{"name":"Brown Sugar","measure":"75g"},{"name":"Fish Sauce","measure":"1 tablespoon"},{"name":"Chilli Sauce","measure":"2 tsp"},{"name":"Spring Onions","measure":"4"},{"name":"Rice","measure":"Steamed"},{"name":"Pak Choi","measure":"To serve"}],"steps":["Heat 1 tbsp of the oil in a wok over a high heat and stir-fry the pork in batches until browned all over.","Remove with a slotted spoon and set aside.","Turn the heat right down and add the remaining oil, then stir in the shallots, ginger and chilli.","Cook over a low heat for a couple of mins until just starting to soften.","Add the sugar, fish sauce and 200ml water to the pan and stir everything together.","Bring to the boil, stirring, so that the sugar dissolves, then return the pork to the pan.","Bubble vigorously for 8-10 mins until the sauce thickens to coat the meat and become glossy.","Taste and stir in a little more fish sauce, if needed, along with the chilli sauce.","Sprinkle with the spring onions and serve with steamed rice and pak choi."],"ingredient_names":["ground nut oil","pork shoulder steaks","shallots","ground ginger","red chilli","brown sugar","fish sauce","chilli sauce","spring onions","rice","pak choi"],"allergens":["fish","tree_nuts"],"diet_flags":[]},{"source_id":"53236","title":"Vietnamese-style veggie hotpot","category":"Vegetarian","country":"Vietnam","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/4uje7l1763762276.jpg","youtube_url":"https://www.youtube.com/watch?v=OR6jC9gw_Hw","source_url":"https://www.bbcgoodfood.com/recipes/vietnamese-veggie-hotpot","ingredients":[{"name":"Vegetable Oil","measure":"2 tsp"},{"name":"Ginger","measure":"4cm finely chopped"},{"name":"Garlic Clove","measure":"2 chopped"},{"name":"Butternut Squash","measure":"1/2"},{"name":"Soy Sauce","measure":"2 tsp"},{"name":"Brown Sugar","measure":"2 tsp"},{"name":"Vegetable Stock","measure":"200ml"},{"name":"Green Beans","measure":"100g shredded"},{"name":"Spring Onions","measure":"4 sliced"},{"name":"Coriander Leaves","measure":"To serve"},{"name":"Jasmine Rice","measure":"To serve"}],"steps":["Heat the oil in a medium-size, lidded saucepan.","Add the ginger and garlic, then stir-fry for about 5 mins.","Add the squash, soy sauce, sugar and stock.","Cover, then simmer for 10 mins.","Remove the lid, add the green beans, then cook for 3 mins more until the squash and beans are tender.","Stir the spring onions through at the last minute, then sprinkle with coriander and serve with rice."],"ingredient_names":["vegetable oil","ginger","garlic clove","butternut squash","soy sauce","brown sugar","vegetable stock","green beans","spring onions","coriander leaves","jasmine rice"],"allergens":["gluten","soy"],"diet_flags":["pescatarian","vegan","vegetarian"]},{"source_id":"53237","title":"Vietnamese pork salad","category":"Pork","country":"Vietnam","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/g7jomp1763763994.jpg","youtube_url":"https://www.youtube.com/watch?v=_DCJNrNTTB4","source_url":"https://www.bbcgoodfood.com/recipes/vietnamese-pork-salad","ingredients":[{"name":"Golden Caster Sugar","measure":"1 tsp"},{"name":"Lime","measure":"Juice of 2"},{"name":"Red Chilli","measure":"1 chopped"},{"name":"Coriander","measure":"Handful"},{"name":"Sesame Seed Oil","measure":"1 tablespoon"},{"name":"Fish Sauce","measure":"1 tablespoon"},{"name":"Soy Sauce","measure":"1 tablespoon"},{"name":"Pork Tenderloin","measure":"500g"},{"name":"Vegetable Oil","measure":"For brushing"},{"name":"White Cabbage","measure":"1/4"},{"name":"Cucumber","measure":"1 chopped"},{"name":"Celery","measure":"5 chopped"},{"name":"Spring Onions","measure":"3 sliced thinly"},{"name":"Red Chilli","measure":"1 chopped"},{"name":"Lemongrass Stalks","measure":"2 chopped"},{"name":"Lime","measure":"Zest of 1"},{"name":"Coriander","measure":"Handful"},{"name":"Mint","measure":"Handful"}],"steps":["The day before: make the dressing. Put the sugar and lime juice in a pan with 1 tbsp water and bring to the boil to dissolve the sugar. Add the chilli and coriander and stir well, then pulse in a blender until smooth. Tip into a bowl, then stir in the sesame oil, fish sauce, soy sauce and sesame seeds to make a dressing. Cover and chill until needed.","Two hours before serving: heat a griddle pan. Preheat the oven to 200C/gas 6/fan 180C. Brush the pork with oil and griddle on all sides for a few minutes until seared. Transfer to a baking tray and put in the oven for about 10-12 minutes until cooked through. Cool, thinly slice against the grain of the meat. Tip into a bowl and pour over half the dressing.","To serve: toss the remaining salad ingredients in a bowl with the remaining dressing. Pile on to a platter, top with the pork slices and spoon over any juices."],"ingredient_names":["golden caster sugar","lime","red chilli","coriander","sesame seed oil","fish sauce","soy sauce","pork tenderloin","vegetable oil","white cabbage","cucumber","celery","spring onions","red chilli","lemongrass stalks","lime","coriander","mint"],"allergens":["fish","gluten","sesame","soy"],"diet_flags":[]},{"source_id":"53238","title":"Beef pho","category":"Beef","country":"Vietnam","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/pbzcrx1763765096.jpg","youtube_url":"https://www.youtube.com/watch?v=WlosNFMCnE4","source_url":"https://www.bbcgoodfood.com/recipes/beef-pho","ingredients":[{"name":"Beef Stock","measure":"1 L"},{"name":"Onion","measure":"1 large"},{"name":"Ginger","measure":"1 Large Chopped"},{"name":"Cinnamon Stick","measure":"1"},{"name":"Star Anise","measure":"2"},{"name":"Coriander Seeds","measure":"1 tsp"},{"name":"Cloves","measure":"1/2 teaspoon"},{"name":"Sirloin steak","measure":"225g"},{"name":"Palm Sugar","measure":"1 tsp"},{"name":"Fish Sauce","measure":"1 tablespoon"},{"name":"Soy Sauce","measure":"1 ½ tbsp"},{"name":"Rice Noodles","measure":"200g"},{"name":"Spring Onions","measure":"2 sliced"},{"name":"Birds-eye Chillies","measure":"1 small"},{"name":"Basil","measure":"Handful"},{"name":"Coriander","measure":"Handful"},{"name":"Lime","measure":"1"}],"steps":["Tip the beef stock along with 500ml of water into a large saucepan. Sit the onion and ginger in a frying pan over a high heat and char on all sides, around 3-5 mins (you can also do this under your grill). Once charred, add to the beef stock. In the same pan, toast the spices for 2-3 mins and once they begin to smell fragrant, add them to the beef stock as well. Bring the stock to the boil, then turn to a simmer and cook for 30mins before straining.","Meanwhile, cut the fat from the steak and wrap in cling film, then put into the freezer for 15 mins – this will make your steak really easy to slice! Slice it thinly, then cover with cling film again and pop into the fridge.","Taste the beef stock and use the palm sugar, fish sauce and soy to season. Cook the noodles according to package instructions and split between two bowls, topping each with the sliced beef. Bring the stock to the boil and then pour into the bowls (the heat will cook the beef). Top each with the spring onions, chilli slices and herbs. Serve with the lime wedges to squeeze over."],"ingredient_names":["beef stock","onion","ginger","cinnamon stick","star anise","coriander seeds","cloves","sirloin steak","palm sugar","fish sauce","soy sauce","rice noodles","spring onions","birds-eye chillies","basil","coriander","lime"],"allergens":["fish","gluten","soy"],"diet_flags":[]},{"source_id":"53239","title":"Bang bang prawn salad","category":"Seafood","country":"Vietnam","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/4xcfai1763765676.jpg","youtube_url":"https://www.youtube.com/watch?v=Na-6-lzs2wU","source_url":"https://www.bbcgoodfood.com/recipes/bang-bang-prawn-salad","ingredients":[{"name":"Rice Noodles","measure":"140g"},{"name":"Peanut Butter","measure":"3 tablespoons"},{"name":"Coconut Milk","measure":"4 tablespoons"},{"name":"sweet chilli sauce","measure":"3  tablespoons"},{"name":"Spring Onions","measure":"3 sliced thinly"},{"name":"Cucumber","measure":"1 sliced"},{"name":"Bean Sprouts","measure":"300g"},{"name":"Prawns","measure":"200g"}],"steps":["Cook the noodles following pack instructions, then rinse under cold water and drain thoroughly.","In a small saucepan melt together the peanut butter, coconut milk, sweet chilli sauce and half the spring onions, adding 1-2 tbsp of water to loosen the mixture to a drizzling consistency.","Mix the noodles, cucumber and beansprouts in a serving dish.","Top with the prawns, drizzle over the peanut sauce and scatter over the remaining spring onions."],"ingredient_names":["rice noodles","peanut butter","coconut milk","sweet chilli sauce","spring onions","cucumber","bean sprouts","prawns"],"allergens":["peanuts","shellfish"],"diet_flags":["pescatarian"]},{"source_id":"53240","title":"Tofu, greens & cashew stir-fry","category":"Vegetarian","country":"Vietnam","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/minfsc1763766806.jpg","youtube_url":"https://www.youtube.com/watch?v=l8wuWeNy3J4","source_url":"https://www.bbcgoodfood.com/recipes/tofu-greens-cashew-stir-fry","ingredients":[{"name":"Vegetable Oil","measure":"1 tablespoon"},{"name":"Broccoli","measure":"1 head"},{"name":"Garlic Clove","measure":"4 sliced"},{"name":"Red Chilli","measure":"1 sliced"},{"name":"Spring Onions","measure":"1  bunch"},{"name":"Soya Bean","measure":"140g"},{"name":"Pak Choi","measure":"2 heads"},{"name":"Marinated Tofu","measure":"300g"},{"name":"Hoisin Sauce","measure":"1 ½ tbsp"},{"name":"Soy Sauce","measure":"1 tablespoon"},{"name":"Cashew Nuts","measure":"25g"}],"steps":["Heat the oil in a non-stick wok.","Add the broccoli, then fry on a high heat for 5 mins or until just tender, adding a little water if it begins to catch.","Add the garlic and chilli, fry for 1 min, then toss through the spring onions, soya beans, pak choi and tofu. Stir-fry for 2-3 mins.","Add the hoisin, soy and nuts to warm through."],"ingredient_names":["vegetable oil","broccoli","garlic clove","red chilli","spring onions","soya bean","pak choi","marinated tofu","hoisin sauce","soy sauce","cashew nuts"],"allergens":["gluten","soy","tree_nuts"],"diet_flags":["pescatarian","vegan","vegetarian"]},{"source_id":"53241","title":"Vietnamese veg parcels","category":"Vegetarian","country":"Vietnam","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/f698g91763768731.jpg","youtube_url":"https://www.youtube.com/watch?v=k3ciVdNBuK0","source_url":"https://www.bbcgoodfood.com/recipes/vietnamese-veg-parcels","ingredients":[{"name":"Rice Flour Pancakes","measure":"100g"},{"name":"Rice Noodles","measure":"50g"},{"name":"Chicken Breast","measure":"1"},{"name":"Carrots","measure":"1 sliced"},{"name":"Cucumber","measure":"1 sliced"},{"name":"Red Pepper","measure":"1 sliced"},{"name":"Lettuce","measure":"To serve"},{"name":"Coriander","measure":"To serve"},{"name":"Mint","measure":"To serve"},{"name":"Fish Sauce","measure":"4 tablespoons"},{"name":"Rice Vinegar","measure":"2 tablespoons"},{"name":"Lime","measure":"Juice of 1/2"},{"name":"Red Chilli","measure":"1 sliced"}],"steps":["Soak the rice fl our pancakes according to pack instructions or in boiling water for 30 secs. Remove and cool on kitchen paper. Soak the rice noodles according to pack instructions, then drain and cut them into 2cm strips.","Lay a rice pancake on a board and arrange some rice noodles, chicken, vegetables and herb leaves about a third of the way up, leaving a 1cm edge at the side. Fold the sides over the vegetables and then roll up lengthways to make a cigar. Store in the fridge, covered with moist kitchen paper for up to 1 day.","Mix together the ingredients for the dipping sauce and put into a bowl. To serve, arrange the rolls on a plate along with the leaves and herbs. To eat, wrap each roll in a piece of lettuce with a herb sprig and dunk into the sauce."],"ingredient_names":["rice flour pancakes","rice noodles","chicken breast","carrots","cucumber","red pepper","lettuce","coriander","mint","fish sauce","rice vinegar","lime","red chilli"],"allergens":["fish"],"diet_flags":[]},{"source_id":"53242","title":"Barbecue pork buns","category":"Pork","country":"Vietnam","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/tzsy461763769901.jpg","youtube_url":"https://www.youtube.com/watch?v=T3mBULRIcY8","source_url":"https://www.bbcgoodfood.com/recipes/barbecue-pork-buns","ingredients":[{"name":"Sugar","measure":"85g"},{"name":"White Bread Mix","measure":"500g"},{"name":"Sunflower Oil","measure":"1 tablespoon"},{"name":"Bacon","measure":"12"},{"name":"Ginger","measure":"Knob"},{"name":"Garlic","measure":"2 cloves chopped"},{"name":"Soy Sauce","measure":"2 tablespoons"},{"name":"Clear Honey","measure":"3  tablespoons"},{"name":"Tomato Puree","measure":"3  tablespoons"},{"name":"Egg","measure":"1 beaten"}],"steps":["Heat the oven to 200C/fan 180C/gas. Mix the sugar into the bread mix in a large bowl, then add water as instructed on the pack. Bring the dough together with a wooden spoon, then knead on a lightly floured surface for 5 mins until smooth. Put into a large bowl, cover with oiled cling film then leave in a warm place until doubled in size.","Meanwhile, heat the oil in a pan, then fry the bacon until crisp, about 5 mins. Add the ginger and garlic and fry for 1 min until soft, then tip in the soy, honey and tomato purée and stir well. Can be made up to 3 days ahead.","Turn out the dough and knead briefly, then pull into 12 even-sized balls. Flatten with your hands, then put a teaspoon-size blob of the filling in the middle. Draw the dough up and pinch it closed like a purse, then turn the bun over and sit it on a large baking sheet. Cover with oiled cling film and leave to rise for about 30 mins until the dough feels pillowy. Brush with egg and bake for 20 mins until golden. Serve warm with dipping sauce. Can be frozen after second rise for up to 1 month or baked up to a day ahead and re-warmed."],"ingredient_names":["sugar","white bread mix","sunflower oil","bacon","ginger","garlic","soy sauce","clear honey","tomato puree","egg"],"allergens":["eggs","gluten","soy"],"diet_flags":[]},{"source_id":"53243","title":"Vietnamese prawn spiralized rolls","category":"Seafood","country":"Vietnam","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/9r2xrg1763771238.jpg","youtube_url":"https://www.youtube.com/watch?v=lNU0LKVtHC4","source_url":"https://www.bbcgoodfood.com/recipes/vietnamese-prawn-spiralized-rolls","ingredients":[{"name":"Lime","measure":"Juice of 1/2"},{"name":"Rice Vinegar","measure":"2 tablespoons"},{"name":"Palm Sugar","measure":"1 tablespoon"},{"name":"Fish Sauce","measure":"3  tablespoons"},{"name":"Birds-eye Chillies","measure":"1 chopped"},{"name":"Rice Paper Sheets","measure":"6"},{"name":"Mint","measure":"Small bunch"},{"name":"Coriander","measure":"Small bunch"},{"name":"King Prawns","measure":"12"},{"name":"Carrots","measure":"1 large"},{"name":"Courgettes","measure":"1"}],"steps":["Mix all the ingredients for the dipping sauce along with 50ml water in a bowl and set aside to allow the sugar to dissolve and flavour to infuse.","To assemble the rolls, fill a wide bowl with warm water and grab a clean damp tea towel to work on. Dip a rice paper wrapper into the water for a few seconds until it softens then carefully place onto the tea towel.","Put a few mint and coriander leaves in the centre of the wrapper then top with two prawns and a small handful of the spiralized veg, which may need to be cut up if the spirals are too long.","Fold the sides of the wrapper into the centre, over the filling, then fold in the edges, so that the filling is completely encased, then tightly roll. Repeat until all of the wrappers and filling have been used. To serve, slice on a diagonal and eat with the dipping sauce."],"ingredient_names":["lime","rice vinegar","palm sugar","fish sauce","birds-eye chillies","rice paper sheets","mint","coriander","king prawns","carrots","courgettes"],"allergens":["fish","shellfish"],"diet_flags":["pescatarian"]},{"source_id":"53244","title":"Prawn & noodle salad with crispy shallots","category":"Seafood","country":"Vietnam","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/0iryz91763778419.jpg","youtube_url":null,"source_url":"https://www.bbcgoodfood.com/recipes/vietnamese-prawn-noodle-salad-crispy-shallots","ingredients":[{"name":"Rice Noodles","measure":"200g"},{"name":"Prawns","measure":"200g"},{"name":"Red Onions","measure":"1 sliced"},{"name":"Red Chilli","measure":"1 sliced"},{"name":"Cucumber","measure":"1 sliced"},{"name":"Coriander","measure":"Handful"},{"name":"Mint","measure":"Handful"},{"name":"Roasted Peanut","measure":"2 tablespoons"},{"name":"Lime","measure":"Juice of 3"},{"name":"Brown Sugar","measure":"1 tablespoon"},{"name":"Fish Sauce","measure":"2 tsp"},{"name":"Garlic","measure":"1 clove peeled crushed"},{"name":"Shallots","measure":"5 Slices"},{"name":"Vegetable Oil","measure":"For frying"},{"name":"Flour","measure":"Sprinkling"}],"steps":["For the crispy shallots, heat 5cm of oil until hot in a wok.","You will know the oil is hot enough when one piece of shallot sizzles as soon as it’s dropped in.","Toss the shallot slices with flour, shake off excess and fry in the oil until golden.","They fry quickly, about 1 min.","Drain on kitchen paper, sprinkle with salt and set aside.","To make the dressing, mix the lime juice, sugar, fish sauce and garlic and set aside.","In a large mixing bowl, pour boiling water over the noodles.","Leave them for 2 mins or until they are just cooked, then rinse under cold water.","Drain well, shaking the sieve numerous times to get out the excess water, then place back in the bowl.","Add prawns, onion, chilli, cucumber and herbs.","Pour the dressing over, mix, then sprinkle with the shallots and peanuts."],"ingredient_names":["rice noodles","prawns","red onions","red chilli","cucumber","coriander","mint","roasted peanut","lime","brown sugar","fish sauce","garlic","shallots","vegetable oil","flour"],"allergens":["fish","gluten","peanuts","shellfish"],"diet_flags":["pescatarian"]},{"source_id":"53245","title":"Noodle bowl salad","category":"Seafood","country":"Vietnam","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/zry07j1763779321.jpg","youtube_url":"https://www.youtube.com/watch?v=7EAdKeikJ9o","source_url":"https://www.bbcgoodfood.com/recipes/noodle-bowl-salad","ingredients":[{"name":"Rice Noodles","measure":"125g"},{"name":"Sugar Snap Peas","measure":"200g"},{"name":"Sesame Seed Oil","measure":"2 tsp"},{"name":"Spring Onions","measure":"4 sliced"},{"name":"Coriander","measure":"Handful"},{"name":"Hot Smoked Flaked Salmon","measure":"150g"},{"name":"Pretzels","measure":"To serve"},{"name":"Soy Sauce","measure":"3  tablespoons"},{"name":"Clear Honey","measure":"1 tablespoon"},{"name":"Lemon Juice","measure":"1 tablespoon"},{"name":"Ground Nut Oil","measure":"1 tablespoon"},{"name":"Garlic","measure":"1 clove finely chopped"},{"name":"Ginger","measure":"Knob"}],"steps":["Drop the noodles into a large bowl, then pour over enough boiling water to cover.","Tip in the sliced sugar snaps and leave for 4 minutes.","Drain in a colander, put under cold running water to cool off, then drain again.","Tip into a bowl and toss in the sesame oil.","Mix the dressing ingredients.","Pile spring onions, coriander and salmon onto the noodles, pour over the dressing and toss everything together.","Serve with a pretzel or bread roll."],"ingredient_names":["rice noodles","sugar snap peas","sesame seed oil","spring onions","coriander","hot smoked flaked salmon","pretzels","soy sauce","clear honey","lemon juice","ground nut oil","garlic","ginger"],"allergens":["fish","gluten","sesame","soy","tree_nuts"],"diet_flags":["pescatarian"]},{"source_id":"53246","title":"Tangy carrot, cabbage & onion salad","category":"Vegetarian","country":"Vietnam","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/dbazbg1763779999.jpg","youtube_url":"https://www.youtube.com/watch?v=-BJWMkJMIns","source_url":"https://www.bbcgoodfood.com/recipes/tangy-carrot-red-cabbage-onion-salad","ingredients":[{"name":"Carrots","measure":"4 sliced"},{"name":"Red Cabbage","measure":"1/2"},{"name":"Red Onions","measure":"2 sliced"},{"name":"Mint","measure":"Handful"},{"name":"Coriander Leaves","measure":"Handful"},{"name":"Roasted Peanut","measure":"Handful"},{"name":"Lime","measure":"Juice of 2"},{"name":"Ground Nut Oil","measure":"1 tablespoon"},{"name":"Red Chilli","measure":"1 chopped"},{"name":"Brown Sugar","measure":"1 tablespoon"}],"steps":["Tip the carrots, cabbage and onions into a bowl. Make the dressing by stirring the ingredients together until the sugar has dissolved. Pour over salad, tossing the vegetables in the dressing. Add the herbs, toss again, then scatter over the peanuts."],"ingredient_names":["carrots","red cabbage","red onions","mint","coriander leaves","roasted peanut","lime","ground nut oil","red chilli","brown sugar"],"allergens":["peanuts","tree_nuts"],"diet_flags":["pescatarian","vegan","vegetarian"]},{"source_id":"53247","title":"Sea bass with sizzled ginger, chilli & spring onions","category":"Seafood","country":"Vietnam","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/tqd7s21763780609.jpg","youtube_url":"https://www.youtube.com/watch?v=xzDYKZl50FQ","source_url":"https://www.bbcgoodfood.com/recipes/sea-bass-sizzled-ginger-chilli-spring-onions","ingredients":[{"name":"Sea Bass Fillets","measure":"6"},{"name":"Sunflower Oil","measure":"3  tablespoons"},{"name":"Ginger","measure":"Knob"},{"name":"Garlic Clove","measure":"3 sliced thinly"},{"name":"Red Chilli","measure":"3 Large"},{"name":"Spring Onions","measure":"Bunch"},{"name":"Soy Sauce","measure":"1 tablespoon"}],"steps":["Season 6 sea bass fillets with salt and pepper, then slash the skin 3 times.","Heat a heavy-based frying pan and add 1 tbsp sunflower oil.","Once hot, fry the sea bass fillets, skin-side down, for 5 mins or until the skin is very crisp and golden. The fish will be almost cooked through.","Turn over, cook for another 30 seconds - 1 minute, then transfer to a serving plate and keep warm. You’ll need to fry the sea bass fillets in 2 batches.","Heat 2 tbsp sunflower oil, then fry the large knob of peeled ginger, cut into matchsticks, 3 thinly sliced garlic cloves and 3 thinly shredded red chillies for about 2 mins until golden.","Take off the heat and toss in the bunch of shredded spring onions. Splash the fish with 1 tbsp soy sauce and spoon over the contents of the pan."],"ingredient_names":["sea bass fillets","sunflower oil","ginger","garlic clove","red chilli","spring onions","soy sauce"],"allergens":["fish","gluten","soy"],"diet_flags":["pescatarian"]},{"source_id":"53248","title":"Salmon noodle wraps","category":"Seafood","country":"Vietnam","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/prrirc1763781360.jpg","youtube_url":"https://www.youtube.com/watch?v=9j2qftITN-Y","source_url":"https://www.bbcgoodfood.com/recipes/salmon-noodle-wraps","ingredients":[{"name":"Rice Noodles","measure":"100g"},{"name":"Spring Onions","measure":"3 sliced thinly"},{"name":"Petit Pois","measure":"50g"},{"name":"Chilli","measure":"85g"},{"name":"Coriander","measure":"85g"},{"name":"Lime","measure":"85g"},{"name":"Salmon","measure":"300g"}],"steps":["Heat oven to 200C/fan 180C/gas 6.","Put the noodles in a bowl and pour over enough boiling water to just cover them.","Leave for 2 mins, until they are bendable, but not too soft, then drain well.","Return to the bowl with the spring onions, petit pois, salt and pepper and a third of the butter.","Mix well until the butter has melted.","Pile the noodles and vegetables onto two large squares of baking parchment, then sit the salmon on top.","Slice the remaining butter and arrange over the top of the salmon.","Bring the ends of the paper over the fish, fold them together to seal, then tuck the ends of the paper underneath so there are no gaps.","Put the parcels on a baking sheet and bake for 15-20 mins.","Transfer to dinner plates and serve without delay."],"ingredient_names":["rice noodles","spring onions","petit pois","chilli","coriander","lime","salmon"],"allergens":["fish"],"diet_flags":["pescatarian"]},{"source_id":"53250","title":"Vegan banh mi","category":"Vegan","country":"Vietnam","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/sonirb1763782831.jpg","youtube_url":"https://www.youtube.com/watch?v=i0_C3eRTbgg","source_url":"https://www.bbcgoodfood.com/recipes/boxing-day-banh-mi","ingredients":[{"name":"Raw Vegetables","measure":"150g"},{"name":"Vegan White Wine Vinegar","measure":"3  tablespoons"},{"name":"Golden Caster Sugar","measure":"1 tsp"},{"name":"Baguette","measure":"1 large"},{"name":"Hummus","measure":"100g"},{"name":"Tempeh","measure":"175g"},{"name":"Coriander","measure":"Handful"},{"name":"Mint","measure":"Handful"},{"name":"Hotsauce","measure":"To serve"}],"steps":["Put the shredded veg in a bowl and add the vinegar, sugar and 1 tsp salt.","Toss everything together, then set aside to pickle quickly while you prepare the rest of the sandwich.","Heat oven to 180C/160C fan/gas 4.","Cut the baguette into four, then slice each piece horizontally in half.","Put the baguette pieces in the oven for 5 mins until lightly toasted and warm.","Spread each piece with a layer of hummus, then top four pieces with the tempeh slices and pile the pickled veg on top.","To serve, sprinkle over the herbs and squeeze over some hot sauce, then top with the other baguette pieces to make sandwiches."],"ingredient_names":["raw vegetables","vegan white wine vinegar","golden caster sugar","baguette","hummus","tempeh","coriander","mint","hotsauce"],"allergens":["gluten","sesame","soy"],"diet_flags":["pescatarian","vegan","vegetarian"]},{"source_id":"53251","title":"Turkish lahmacun","category":"Beef","country":"Vietnam","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/tqd3ac1763786065.jpg","youtube_url":"https://www.youtube.com/watch?v=8HTa64s8RK8","source_url":"https://www.bbcgoodfood.com/recipes/lahmacun","ingredients":[{"name":"Strong white bread flour","measure":"500g"},{"name":"Fast action yeast","measure":"10g"},{"name":"Corn Flour","measure":"Sprinkling"},{"name":"Tomato","measure":"2"},{"name":"Green Chilli","measure":"2"},{"name":"Spring Onions","measure":"4 Chopped"},{"name":"Parsley","measure":"Bunch"},{"name":"Ground Beef","measure":"250g"},{"name":"Chilli Flakes","measure":"2 tsp"},{"name":"Ground Cumin","measure":"Pinch"},{"name":"Allspice","measure":"1 tsp"},{"name":"Olive Oil","measure":"2 tablespoons"},{"name":"Lemon","measure":"1/2"},{"name":"Red Onions","measure":"1"}],"steps":["Sift the flour into a large bowl, make a well in the middle and sprinkle in the yeast. Pour 125ml water over the yeast, then flick flour over the liquid to create a layer. Cover and leave to rise in a warm place for 15 mins until cracks appear on the surface of that layer.","Use your hands to mix in 250ml more water along with 1 tsp salt and knead the dough for about 10 mins until elastic and no longer sticky. Add a little more flour if you need to. Cover and leave to rise again in a warm place for 30 mins until doubled in size.","Heat the oven to as high as it will go (about 240C/220C fan/gas 9) and sprinkle one or two baking trays thinly with cornmeal.","Pour boiling water from the kettle over the tomatoes, leave to stand briefly, then drain and slip off the skins. Cut the tomatoes in half, cut out the stalks, scoop out the seeds and discard, then chop the flesh.","Halve the chillies lengthways, cut out the stalks, seeds and white inner membrane, then rinse. Cut lengthwise into fine strips, then crosswise into fine dice.","Put the tomatoes, chillies, spring onions, finely chopped parsley, beef mince, spices, 1 tsp salt and ½ tsp freshly ground black pepper into a bowl and mix well.","Take the dough and knead it briefly, then divide into four pieces and shape each into a ball. Roll each ball into a thin circle, place on the prepared baking trays. Spread with a thin layer of the meat mixture.","Bake each flatbread for 10-15 mins until the edges begin to darken. After removing from the oven, sprinkle the lahmacun with the roughly chopped parsley and sliced onion, then squeeze over a few drops of lemon juice. Serve straightaway."],"ingredient_names":["strong white bread flour","fast action yeast","corn flour","tomato","green chilli","spring onions","parsley","ground beef","chilli flakes","ground cumin","allspice","olive oil","lemon","red onions"],"allergens":["gluten"],"diet_flags":[]},{"source_id":"53253","title":"Imam bayildi with BBQ lamb & tzatziki","category":"Lamb","country":"Turkey","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/ampz9v1763787134.jpg","youtube_url":"https://www.youtube.com/watch?v=k8ZMZtdu6Ac","source_url":"https://www.bbcgoodfood.com/recipes/imam-bayildi-bbq-lamb-tzatziki","ingredients":[{"name":"Aubergine","measure":"3"},{"name":"Olive Oil","measure":"2 tablespoons"},{"name":"Onion","measure":"1 chopped"},{"name":"Garlic","measure":"2 cloves chopped"},{"name":"Cinnamon","measure":"1 tsp"},{"name":"Tomato","measure":"8"},{"name":"Parsley","measure":"Bunch"},{"name":"Lamb Loin Chops","measure":"12"},{"name":"Paprika","measure":"Pinch"},{"name":"Lemon","measure":"1"},{"name":"Greek Yogurt","measure":"150g"},{"name":"Cucumber","measure":"1/2"},{"name":"Mint","measure":"2 tbs chopped"}],"steps":["Heat oven to 190C/170C fan/gas 5. Halve the aubergines lengthways and score the flesh side deeply, brush with a good layer of olive oil and put on a baking sheet. Roast for 20 mins or until the flesh is soft enough to scoop out.","Fry the onion in a little oil until soft, add the garlic and cinnamon and fry for 1 min. Once the aubergines are cool enough to handle, scoop out the centres. Roughly chop the flesh and add it to the onions. Halve the tomatoes, scoop the seeds and juice into a sieve set over a bowl, then chop the flesh. Add the chopped tomatoes to the pan and cook everything for 10 mins until nice and soft. Add a little more oil if you need to. Stir in the parsley, leaving a little for scattering at the end.","Lay the aubergine halves in a baking dish and divide the tomato mixture between them. Pour over the juice from the tomatoes, drizzle with more olive oil and bake for 30 mins until the aubergines have collapsed.","Meanwhile, mix the tzatziki ingredients together and put in a small serving bowl.","Season the lamb with salt, black pepper and a pinch of paprika. Griddle, grill or barbecue for 3 mins on each side or until the fat is nicely browned, then put in a serving dish and squeeze over the lemon halves. Scatter the aubergines with parsley, then serve with the lamb and tzatziki."],"ingredient_names":["aubergine","olive oil","onion","garlic","cinnamon","tomato","parsley","lamb loin chops","paprika","lemon","greek yogurt","cucumber","mint"],"allergens":["dairy"],"diet_flags":[]},{"source_id":"53254","title":"Ezme","category":"Vegetarian","country":"Turkey","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/pb6mj11763788331.jpg","youtube_url":"https://www.youtube.com/watch?v=Z1mX-C2fAuc","source_url":"https://www.bbcgoodfood.com/recipes/ezme","ingredients":[{"name":"Tomato","measure":"3 Large"},{"name":"Romano Pepper","measure":"1 medium"},{"name":"Green Chilli","measure":"1 medium"},{"name":"Onion","measure":"1 small"},{"name":"Garlic","measure":"2 cloves minced"},{"name":"Parsley","measure":"25g"},{"name":"Red Pepper Paste","measure":"2 tablespoons"},{"name":"Tomato Puree","measure":"1 tablespoon"},{"name":"Pomegranate Molasses","measure":"2 tablespoons"},{"name":"Pul Biber","measure":"1 tablespoon"},{"name":"Sumac","measure":"2 tsp"},{"name":"Dried Mint","measure":"1 tablespoon"},{"name":"Extra Virgin Olive Oil","measure":"60 ml"}],"steps":["Put the tomatoes and all of the peppers in a food processor and blitz until finely chopped.","Tip out into a sieve, set over a bowl and leave to strain.","Add the onions, garlic and parsley to the food processor and blitz until finely chopped, then set aside.","Add red pepper paste, tomato purée, pomegranate molasses, pul biber, sumac, dried mint and most of the extra virgin olive oil to a serving bowl and whisk well so everything comes together as a sauce.","Tip in the blitzed onion mixture and the strained pepper mixture along with 1 tsp flaky sea salt .","Stir well, then drizzle with the remaining extra virgin olive oil to serve."],"ingredient_names":["tomato","romano pepper","green chilli","onion","garlic","parsley","red pepper paste","tomato puree","pomegranate molasses","pul biber","sumac","dried mint","extra virgin olive oil"],"allergens":[],"diet_flags":["pescatarian","vegan","vegetarian"]},{"source_id":"53255","title":"Grilled aubergines with spicy chickpeas & walnut sauce","category":"Vegetarian","country":"Turkey","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/ctw3ba1763788978.jpg","youtube_url":null,"source_url":"https://www.bbcgoodfood.com/recipes/grilled-aubergines-spicy-chickpeas-walnut-sauce","ingredients":[{"name":"Olive Oil","measure":"4 tablespoons"},{"name":"Onion","measure":"1 chopped"},{"name":"Red Chilli","measure":"1 chopped"},{"name":"Ginger","measure":"2cm piece"},{"name":"Ground Cumin","measure":"1/2 teaspoon"},{"name":"Chickpeas","measure":"400g"},{"name":"Tomato","measure":"200g"},{"name":"Lemon","measure":"Juice of 1/2"},{"name":"Aubergine","measure":"2"},{"name":"Greek Yogurt","measure":"200g"},{"name":"Garlic Clove","measure":"1"},{"name":"Walnuts","measure":"25g"},{"name":"Coriander","measure":"Handful"}],"steps":["Heat 2 tbsp oil in a pan, add the onion and fry until soft and lightly browned, about 10 mins. Add the chilli, ginger and spices and mix well. Stir in the chickpeas, tomatoes and 5 tbsp water, bring to the boil, then simmer for 10 mins. Add a little salt and pepper and the lemon juice.","Arrange the aubergines over a grill pan. Brush lightly with oil, sprinkle with salt and pepper, then grill until golden. Flip them over, brush again with oil, season and grill again until tender and golden.","Mix the yogurt with the garlic, most of the walnuts and coriander and a little salt and pepper. Arrange the aubergine slices over a warm platter and spoon over the chickpea mix. Drizzle with the walnut sauce and scatter with the remaining walnuts and coriander."],"ingredient_names":["olive oil","onion","red chilli","ginger","ground cumin","chickpeas","tomato","lemon","aubergine","greek yogurt","garlic clove","walnuts","coriander"],"allergens":["dairy","tree_nuts"],"diet_flags":["pescatarian","vegetarian"]},{"source_id":"53257","title":"kofta burgers","category":"Lamb","country":"Turkey","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/lgmnff1763789847.jpg","youtube_url":"https://www.youtube.com/shorts/4OsDpyaTKk0","source_url":"https://www.bbcgoodfood.com/recipes/diy-kofta-burgers","ingredients":[{"name":"Lamb","measure":"1kg"},{"name":"Onion","measure":"2"},{"name":"Garlic Bulb","measure":"1"},{"name":"Garam Masala","measure":"6 tablespoons"},{"name":"Coriander","measure":"Bunch"},{"name":"Chilli Sauce","measure":"1 tablespoon"},{"name":"Pita Bread","measure":"8"},{"name":"Tomato","measure":"4 sliced"},{"name":"Red Cabbage","measure":"1/2"},{"name":"Red Onions","measure":"1 sliced"},{"name":"Yogurt","measure":"Small pack"}],"steps":["Tip the mince into a large bowl (use a clean washing-up bowl if you don’t have anything big enough) with all the other burger ingredients and a good pinch of salt.","Roll up your sleeves, get your hands into the mix and squelch everything together through your fingers until completely mixed.","Pat the mix into 16 small burgers.","These may now be frozen for up to 1 month or chilled up to a day ahead.","To cook, heat grill to its highest setting and lay the burgers in a single layer on a baking tray (you may need to do this in batches, depending on how big your tray is).","Grill on the highest shelf for 5-6 mins on each side until browned and cooked through.","Pile burgers onto a platter and serve with all the accompaniments, so everyone can construct their own sandwich."],"ingredient_names":["lamb","onion","garlic bulb","garam masala","coriander","chilli sauce","pita bread","tomato","red cabbage","red onions","yogurt"],"allergens":["dairy","gluten"],"diet_flags":[]},{"source_id":"53258","title":"Hot cumin lamb wrap with crunchy slaw & spicy mayo","category":"Lamb","country":"Turkey","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/jyylmo1763790808.jpg","youtube_url":null,"source_url":"https://www.bbcgoodfood.com/recipes/hot-cumin-lamb-wrap-crunchy-slaw-spicy-mayo","ingredients":[{"name":"Lamb Leg","measure":"4 small"},{"name":"Olive Oil","measure":"2 tsp"},{"name":"Ground Cumin","measure":"1 tsp"},{"name":"Sugar","measure":"1 tablespoon"},{"name":"White Wine Vinegar","measure":"3  tablespoons"},{"name":"Carrots","measure":"2"},{"name":"Spring Onions","measure":"2 sliced"},{"name":"White Cabbage","measure":"400g"},{"name":"Sweet Peppadew Peppers","measure":"5"},{"name":"Mayonnaise","measure":"3  tablespoons"},{"name":"Pita Bread","measure":"4 large"}],"steps":["Heat a griddle pan. Rub the lamb steaks with the oil, cumin and some seasoning. Griddle for about 3-4 mins on each side or until cooked to your liking. Place to one side on a plate to rest.","In a large bowl, stir the sugar into the vinegar until dissolved. Add the carrots, spring onions, cabbage and some seasoning, and toss together.","Blitz the whole peppers and the mayo in a food processor. Add a heap of the salad to each flatbread. Slice the lamb, trimming off any excess fat and lay on top of the salad, drizzling with the resting juices. Spoon over the mayo and scatter with a few of the sliced peppers. Roll up and eat. If using pitta, split and stuff. Serve any extra salad on the side."],"ingredient_names":["lamb leg","olive oil","ground cumin","sugar","white wine vinegar","carrots","spring onions","white cabbage","sweet peppadew peppers","mayonnaise","pita bread"],"allergens":["eggs","gluten"],"diet_flags":[]},{"source_id":"53260","title":"Slow-roast lamb with cinnamon, fennel & citrus","category":"Lamb","country":"Turkey","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/gr4lo51763791826.jpg","youtube_url":"https://www.youtube.com/watch?v=4_mbvxabtJc","source_url":"https://www.bbcgoodfood.com/recipes/slow-roast-lamb-cinnamon-fennel-citrus","ingredients":[{"name":"Lamb Leg","measure":"1"},{"name":"Lemon","measure":"Zest and juice of 1"},{"name":"Olive Oil","measure":"4 tablespoons"},{"name":"Clear Honey","measure":"2 tablespoons"},{"name":"Cinnamon","measure":"1 tablespoon"},{"name":"Fennel Seeds","measure":"1 tablespoon"},{"name":"Ground Cumin","measure":"1 tablespoon"},{"name":"Garlic","measure":"3 Cloves Crushed"}],"steps":["Put the lamb into a large food bag with all the juice and marinate overnight.","The next day, take the lamb out of the fridge 1 hr before you want to cook it. Heat oven to 220C/200C fan/gas 7. Take the lamb out of the marinade (reserve remaining marinade) and pat dry. Rub with half the oil and roast for 15-20 mins until browned. Remove lamb and reduce oven to 160C/140C fan/gas 3.","Mix the zests, remaining oil, honey, spices and garlic with plenty of seasoning. Lay a large sheet of baking parchment on a large sheet of foil. Sit the lamb leg on top, rub all over with the paste and pull up the sides of the foil. Drizzle marinade into base, and scrunch foil to seal.","Roast for 4 hrs, until very tender. Rest, still wrapped, for 30 mins. Unwrap and serve with juices."],"ingredient_names":["lamb leg","lemon","olive oil","clear honey","cinnamon","fennel seeds","ground cumin","garlic"],"allergens":[],"diet_flags":[]},{"source_id":"53261","title":"Chicken wings with cumin, lemon & garlic","category":"Chicken","country":"Turkey","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/4hzyvq1763792564.jpg","youtube_url":"https://www.youtube.com/watch?v=hmJPOVzMvK4","source_url":"https://www.bbcgoodfood.com/recipes/chicken-wings-cumin-lemon-garlic","ingredients":[{"name":"Chicken Wings","measure":"12"},{"name":"Garlic","measure":"2 cloves minced"},{"name":"Lemon","measure":"Zest and juice of 1"},{"name":"Cumin Seeds","measure":"1 tsp"},{"name":"Olive Oil","measure":"2 tablespoons"},{"name":"Honey","measure":"1 tablespoon"}],"steps":["Using a pair of sharp kitchen scissors, cut each wing at the knuckle into two pieces.","Mix the garlic, lemon zest and juice, cumin and oil with plenty of seasoning, then tip into a dish with the chicken wings and toss to coat.","Cover and put in the fridge to marinate for at least 1 hr, or overnight if you have time.","Heat oven to 200C/180C fan/gas 6, or heat an outdoor barbecue.","Bake the chicken wings on an oven tray for 45-50 mins until crisp, or barbecue for 20 mins, drizzling over the honey for the final 10 mins of each method.","Serve on a platter with plenty of paper napkins.","Fill small bowls with olives, pistachios or almonds, dates and pickled chillies and flatbreads to serve alongside, along with the dishes below."],"ingredient_names":["chicken wings","garlic","lemon","cumin seeds","olive oil","honey"],"allergens":[],"diet_flags":[]},{"source_id":"53262","title":"Adana kebab","category":"Lamb","country":"Turkey","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/04axct1763793018.jpg","youtube_url":"https://www.youtube.com/watch?v=Wj7sXu9B_ME","source_url":"https://www.bbcgoodfood.com/recipes/adana-kebab","ingredients":[{"name":"Romano Pepper","measure":"2 large"},{"name":"Lamb Mince","measure":"800g"},{"name":"Red Pepper Paste","measure":"3  tablespoons"},{"name":"Pul Biber","measure":"1 tablespoon"},{"name":"Sunflower Oil","measure":"3  tablespoons"}],"steps":["Finely chop the peppers in a food processor, then tip them in a sieve and press into the sieve so that the peppers release all of their juices. Tip into a bowl along with the mince, red pepper paste, pul biber, 1½ tsp flaky sea salt, and 2 tbsp of the oil. Mix together, kneading well for at least 2-3 mins. If you need to, wet your hands with cold water to prevent the mixture from sticking. The mixture should be sticky when ready. Cover and chill for at least 2 hrs, or up to 12 hrs.","When ready to cook, heat the grill to high or an oven to 220C/200C fan/gas 6. Divide the mixture into 12 equal portions, around 85g each. If you’d like to skewer them, divide into 8 equal portions and roll into balls. Using wet hands, thread the balls onto the end of the skewers, massaging the mixture down the skewers in between the palms of your hands, until evenly distributed. Ensure that the mixture is fully wrapped tightly around the skewers without any exposed metal. Alternatively, lay them on a large baking tray lined with parchment paper if cooking in the oven, or foil if cooking under the grill. Shape into 20cm-long köfte. Wet your fingers with a little cold water and make indents all along the köfte for the traditional shape.","Gently brush each köfte with the remaining 1 tbsp oil and cook under the grill, on the top shelf for 10-12 mins, turning regularly, or cook in the oven for 16-18 mins, until crispy on the outside and juicy in the middle"],"ingredient_names":["romano pepper","lamb mince","red pepper paste","pul biber","sunflower oil"],"allergens":[],"diet_flags":[]},{"source_id":"53263","title":"Turkish lamb pilau","category":"Lamb","country":"Turkey","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/cr2kyr1763793839.jpg","youtube_url":"https://www.youtube.com/watch?v=FXaQK06pMBI","source_url":"https://www.bbcgoodfood.com/recipes/turkish-lamb-pilau","ingredients":[{"name":"Pine Nuts","measure":"Handful"},{"name":"Olive Oil","measure":"1 tablespoon"},{"name":"Onion","measure":"1 Large Chopped"},{"name":"Cinnamon","measure":"2"},{"name":"Lamb","measure":"500g"},{"name":"Basmati Rice","measure":"250g"},{"name":"Lamb Stock","measure":"1"},{"name":"Dried Apricots","measure":"12"},{"name":"Mint","measure":"Handful"}],"steps":["Dry-fry the pine nuts or almonds in a large pan until lightly toasted, then tip onto a plate.","Add the oil to the pan, then fry the onion and cinnamon together until starting to turn golden.","Turn up the heat, stir in the lamb, fry until the meat changes colour, then tip in the rice and cook for 1 min, stirring all the time.","Pour in 500ml boiling water, crumble in the stock cube, add the apricots, then season to taste.","Turn the heat down, cover and simmer for 12 mins until the rice is tender and the stock has been absorbed.","Toss in the pine nuts and mint and serve."],"ingredient_names":["pine nuts","olive oil","onion","cinnamon","lamb","basmati rice","lamb stock","dried apricots","mint"],"allergens":["tree_nuts"],"diet_flags":[]},{"source_id":"53264","title":"Smoky chicken skewers","category":"Chicken","country":"Turkey","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/3um6il1763794322.jpg","youtube_url":"https://www.youtube.com/watch?v=vNDTGF4ppu8","source_url":"https://www.bbcgoodfood.com/recipes/smoky-chicken-skewers","ingredients":[{"name":"Chicken Thighs","measure":"6"},{"name":"Olive Oil","measure":"2 tablespoons"},{"name":"Fennel Seeds","measure":"1 tsp"},{"name":"Ground Cumin","measure":"1 tsp"},{"name":"sweet smoked paprika","measure":"1 tsp"},{"name":"Garlic","measure":"1 clove peeled crushed"},{"name":"Red Wine Vinegar","measure":"1 tsp"},{"name":"Smoky Aïoli","measure":"To serve"}],"steps":["You need 15 skewers: if wooden, soak in water for 10 mins.","Cut chicken into 3cm pieces and place in a bowl.","Add 1 tbsp olive oil, the spices, garlic and vinegar, toss well and season.","You can do this up to a day before and refrigerate.","Thread 2-3 pieces on each skewer.","Pour remaining oil in a frying pan or rub onto a griddle pan.","Get the pan hot and sear the chicken for 3-4 mins on each side – you may have to do this in batches, keeping the cooked skewers warm in a low oven.","Serve with smoky aïoli if you like."],"ingredient_names":["chicken thighs","olive oil","fennel seeds","ground cumin","sweet smoked paprika","garlic","red wine vinegar","smoky aïoli"],"allergens":[],"diet_flags":[]},{"source_id":"53265","title":"Chilli ginger lamb chops","category":"Lamb","country":"Turkey","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/8xuvhj1763794991.jpg","youtube_url":"https://www.youtube.com/watch?v=MNrNHToyvtI","source_url":"https://www.bbcgoodfood.com/recipes/chilli-ginger-lamb-chops","ingredients":[{"name":"Garlic","measure":"4 Cloves Crushed"},{"name":"Ginger","measure":"1 tblsp"},{"name":"Lemon Juice","measure":"1 tblsp"},{"name":"Olive Oil","measure":"1 tblsp"},{"name":"Chili Powder","measure":"1/2 tsp"},{"name":"Cumin","measure":"1 tsp"},{"name":"Lamb Loin Chops","measure":"8"}],"steps":["Put the garlic in a bowl with the ginger, lemon juice, oil, spices and seasoning.","Blitz with a hand blender until smooth, then use to coat the lamb chops on both sides.","Leave to marinate in the fridge for a couple of hours or overnight.","Heat a barbecue until hot.","Barbecue the chops over the coals for 3 mins on each side until cooked but still pink and juicy in the centre."],"ingredient_names":["garlic","ginger","lemon juice","olive oil","chili powder","cumin","lamb loin chops"],"allergens":[],"diet_flags":[]},{"source_id":"53266","title":"Falafel","category":"Vegetarian","country":"Turkey","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/u5e9qq1763795441.jpg","youtube_url":"https://www.youtube.com/watch?v=NZcWedPKysk","source_url":"https://www.bbcgoodfood.com/recipes/spicy-falafels","ingredients":[{"name":"Sunflower Oil","measure":"2 tablespoons"},{"name":"Onion","measure":"1 chopped"},{"name":"Garlic","measure":"1 clove peeled crushed"},{"name":"Chickpeas","measure":"400g"},{"name":"Ground Cumin","measure":"1 tsp"},{"name":"Ground Coriander","measure":"1 tsp"},{"name":"Parsley","measure":"Handful"},{"name":"Egg","measure":"1 beaten"}],"steps":["Heat 1 tbsp oil in a large pan, then fry the onion and garlic over a low heat for 5 mins until softened.","Tip into a large mixing bowl with the chickpeas and spices, then mash together with a fork or potato masher until the chickpeas are totally broken down.","Stir in the parsley or dried herbs, with seasoning to taste.","Add the egg, then squish the mixture together with your hands.","Mould the mix into 6 balls, then flatten into patties.","Heat the remaining oil in the pan, then fry the falafels on a medium heat for 3 mins on each side, until golden brown and firm.","Serve hot or cold with couscous, pitta bread or salad."],"ingredient_names":["sunflower oil","onion","garlic","chickpeas","ground cumin","ground coriander","parsley","egg"],"allergens":["eggs"],"diet_flags":["pescatarian","vegetarian"]},{"source_id":"53267","title":"Aubergine couscous salad","category":"Vegetarian","country":"Turkey","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/02s6gc1763799560.jpg","youtube_url":"https://www.youtube.com/shorts/8ws2Ohy__CQ","source_url":"https://www.bbcgoodfood.com/recipes/aubergine-couscous-salad","ingredients":[{"name":"Aubergine","measure":"1 sliced"},{"name":"Olive Oil","measure":"3  tablespoons"},{"name":"Couscous","measure":"140g"},{"name":"Vegetable Stock","measure":"225g"},{"name":"Cherry Tomatoes","measure":"200g"},{"name":"Mint","measure":"Handful"},{"name":"Goats Cheese","measure":"100g"},{"name":"Lemon","measure":"Juice of 1/2"}],"steps":["Heat grill to high.","Put the aubergine on a baking sheet, brush with oil and season.","Grill for about 15 mins, turning and brushing with more oil halfway, until browned and softened.","Meanwhile, tip the couscous into a large bowl, pour over the stock, then cover and leave for 10 mins.","Mix the tomatoes, mint, goat’s cheese and remaining oil together.","Fluff the couscous up with a fork, then stir in the aubergines, tomato mixture and lemon juice."],"ingredient_names":["aubergine","olive oil","couscous","vegetable stock","cherry tomatoes","mint","goats cheese","lemon"],"allergens":["gluten"],"diet_flags":["pescatarian","vegan","vegetarian"]},{"source_id":"53268","title":"Roasted chicken with creamy walnut sauce","category":"Chicken","country":"Turkey","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/ro8mzj1763800655.jpg","youtube_url":"https://www.youtube.com/watch?v=e8Bn3V3kmpM","source_url":"https://www.bbcgoodfood.com/recipes/roasted-chicken-creamy-walnut-sauce","ingredients":[{"name":"Chicken Thighs","measure":"8"},{"name":"Cumin","measure":"1 tsp"},{"name":"Paprika","measure":"1/2 tsp"},{"name":"Olive Oil","measure":"2 tablespoons"},{"name":"Pita Bread","measure":"6"},{"name":"Chicken Stock","measure":"150ml"},{"name":"Walnuts","measure":"175g"},{"name":"Onion","measure":"1 chopped"},{"name":"Garlic","measure":"2 cloves chopped"},{"name":"Single Cream","measure":"50 ml"},{"name":"Lemon","measure":"Juice of 1"},{"name":"Coriander","measure":"Handful"}],"steps":["Heat oven to 200C/180C fan/gas 6. In a roasting tin, toss together the chicken, cumin, paprika, 1 tbsp olive oil and seasoning. Cook for 40 mins until the chicken is crisp and cooked through.","Meanwhile, tear up 1 pitta bread and place in a small bowl. Pour over a couple of tbsp chicken stock and leave to soak. Dry-fry the walnuts in a frying pan for about 3 mins until golden and toasted. Set aside. Heat the remaining oil in the pan and cook the onion and garlic until softened. Place the softened pitta bread, onion mixture and most of the nuts into a blender. Pour over the rest of the chicken stock and whizz together until a rough paste forms. Return the mixture to the pan. Add the cream and lemon juice, season and keep warm.","When the chicken is cooked, arrange on a platter. Stir the coriander through the sauce and spoon into a bowl. Roughly chop the remaining walnuts and scatter over the chicken. Toast the pittas, cut into wedges and serve alongside"],"ingredient_names":["chicken thighs","cumin","paprika","olive oil","pita bread","chicken stock","walnuts","onion","garlic","single cream","lemon","coriander"],"allergens":["dairy","gluten","tree_nuts"],"diet_flags":[]},{"source_id":"53270","title":"Turkish-style lamb","category":"Lamb","country":"Turkey","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/0p7l6b1763813981.jpg","youtube_url":"https://www.youtube.com/watch?v=RSXfGtom4RQ","source_url":"https://www.bbcgoodfood.com/recipes/turkish-style-lamb","ingredients":[{"name":"Lamb Leg","measure":"4"},{"name":"Seasoning","measure":"2 tsp"},{"name":"Dried Oregano","measure":"1 tsp"},{"name":"Mint","measure":"Bunch"},{"name":"Yogurt","measure":"300g"},{"name":"Pita Bread","measure":"4"},{"name":"Iceberg Lettuce","measure":"1/2"},{"name":"Red Onions","measure":"1 sliced"},{"name":"Lemon","measure":"1"}],"steps":["Heat grill to high.","Season the lamb, then grill for 2 mins on each side until browned, but still very rare.","Meanwhile, mix the seasoning, oregano and half of the mint into one of the tubs of yogurt, smother this over the lamb, then return to the grill for another 2-3 mins or until the yogurt is blistered and the meat is cooked to your liking.","Leave the meat to rest on a board for a few mins while you toast the pittas, shred the lettuce and thinly slice the red onion.","Stir the rest of the mint into the second tub of yogurt.","Thickly slice the meat and stuff into the pitta bread with the salad and minted yogurt.","Squeeze over lemon juice before tucking in, if you like."],"ingredient_names":["lamb leg","seasoning","dried oregano","mint","yogurt","pita bread","iceberg lettuce","red onions","lemon"],"allergens":["dairy","gluten"],"diet_flags":[]},{"source_id":"53273","title":"Roast aubergine with goat's cheese & toasted flatbread","category":"Vegetarian","country":"Turkey","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/iydbwy1763816111.jpg","youtube_url":null,"source_url":"https://www.bbcgoodfood.com/recipes/roast-aubergine-goats-cheese-toasted-flatbread","ingredients":[{"name":"Aubergine","measure":"2 sliced"},{"name":"Extra Virgin Olive Oil","measure":"3  tablespoons"},{"name":"Cherry Tomatoes","measure":"12"},{"name":"Pita Bread","measure":"1"},{"name":"Balsamic Vinegar","measure":"3  tablespoons"},{"name":"Mint","measure":"Handful"},{"name":"Shallots","measure":"1 chopped"},{"name":"Shallots","measure":"1 sliced"},{"name":"Red Chilli","measure":"1 chopped"},{"name":"Goats Cheese","measure":"50g"},{"name":"Rocket","measure":"Handful"}],"steps":["Heat oven to 200C/180C fan/gas 6. Brush the aubergine slices with 1 tbsp of the oil, then season. Arrange on a baking tray or sheet and roast for 20 mins until browned, popping the tomatoes on the tray for the final 5 mins. Tear the flatbread into pieces and place on a separate baking sheet. Brown in the oven for 8 mins, or until crisp, then remove.","For the dressing, in a small bowl, mix the vinegar, mint, chopped shallots, chilli, remaining oil and some salt and pepper.","Scatter the aubergine slices, tomatoes, sliced shallot and crisp flatbread into a serving bowl. Pour over the dressing, sprinkle with the goat’s cheese and scatter over a little rocket."],"ingredient_names":["aubergine","extra virgin olive oil","cherry tomatoes","pita bread","balsamic vinegar","mint","shallots","shallots","red chilli","goats cheese","rocket"],"allergens":["gluten"],"diet_flags":["pescatarian","vegan","vegetarian"]},{"source_id":"53274","title":"Griddled aubergines with sesame dressing","category":"Vegetarian","country":"Turkey","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/yoj48r1763817100.jpg","youtube_url":"https://www.youtube.com/watch?v=332VIeW67VM","source_url":"https://www.bbcgoodfood.com/recipes/griddled-aubergines-sesame-dressing","ingredients":[{"name":"Aubergine","measure":"2 large"},{"name":"Olive Oil","measure":"2 tablespoons"},{"name":"Greek Yogurt","measure":"250g"},{"name":"Tahini Paste","measure":"3  tablespoons"},{"name":"Garlic","measure":"1 clove peeled crushed"},{"name":"Lemon","measure":"Juice of 1"},{"name":"Coriander","measure":"Handful"},{"name":"Parsley","measure":"Handful"},{"name":"Mint","measure":"Handful"}],"steps":["Brush each aubergine slice with some oil, then season.","Heat a griddle pan or barbecue.","When hot, griddle the aubergine slices for 2-3 mins on each side until golden brown and tender.","Mix the yogurt with the tahini, garlic, lemon juice and herbs, then season.","Top the aubergines with the dressing and scatter over extra herb leaves."],"ingredient_names":["aubergine","olive oil","greek yogurt","tahini paste","garlic","lemon","coriander","parsley","mint"],"allergens":["dairy","sesame"],"diet_flags":["pescatarian","vegetarian"]},{"source_id":"53275","title":"Sweet potato salad","category":"Vegetarian","country":"Turkey","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/z458v91763817681.jpg","youtube_url":"https://www.youtube.com/watch?v=RkiKSO0IuVQ","source_url":"https://www.bbcgoodfood.com/recipes/sweet-potato-salad","ingredients":[{"name":"Sweet Potatoes","measure":"1200g"},{"name":"Olive Oil","measure":"1 tablespoon"},{"name":"Shallots","measure":"2"},{"name":"Spring Onions","measure":"4 sliced"},{"name":"Chives","measure":"Bunch"},{"name":"Sherry vinegar","measure":"5 tablespoons"},{"name":"Extra Virgin Olive Oil","measure":"2 tablespoons"},{"name":"Honey","measure":"2 tablespoons"}],"steps":["Heat oven to 200C/180C fan/gas 6.","Toss the sweet potato chunks with the olive oil and some seasoning, and spread on a baking parchment-lined baking sheet.","Roast for 30 - 35 mins until tender and golden.","Cool at room temperature.","When just about cool whisk together all the dressing ingredients with a little more seasoning and gently toss through the potato chunks – use your hands to avoid breaking them up."],"ingredient_names":["sweet potatoes","olive oil","shallots","spring onions","chives","sherry vinegar","extra virgin olive oil","honey"],"allergens":[],"diet_flags":["pescatarian","vegetarian"]},{"source_id":"53277","title":"Lamb & apricot meatballs","category":"Lamb","country":"Turkey","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/72fgzj1764109947.jpg","youtube_url":"https://www.youtube.com/watch?v=o0UbzRZw-GQ","source_url":"https://www.bbcgoodfood.com/recipes/lamb-apricot-meatballs","ingredients":[{"name":"Olive Oil","measure":"2 tablespoons"},{"name":"Red Onions","measure":"2 chopped"},{"name":"Garlic","measure":"4 Cloves Crushed"},{"name":"Ground Cumin","measure":"2 tsp"},{"name":"Ground Coriander","measure":"2 tsp"},{"name":"Tinned Tomatos","measure":"400g"},{"name":"Sugar","measure":"1/2 teaspoon"},{"name":"Mint","measure":"10g"},{"name":"Lamb Mince","measure":"500g"},{"name":"Dried Apricots","measure":"8"},{"name":"Breadcrumbs","measure":"50g"},{"name":"Pita Bread","measure":"To serve"}],"steps":["Heat 2 tsp oil in a pan and soften the onions for 5 mins. Add the garlic and spices and cook for a few mins more. Spoon half the onion mixture into a bowl and set aside to cool. Add the tomatoes, sugar and seasoning to the remaining onions in the pan and simmer for about 10 mins until reduced.","Meanwhile, add the mint, lamb, apricots and breadcrumbs to the cooled onions, season and mix well with your hands. Shape into little meatballs.","Heat the rest of the oil in a non-stick pan and fry the meatballs until golden (in batches if you need to). Stir in the sauce with a splash of water and gently cook everything for a few mins until the meatballs are cooked through. Serve with pitta bread and salad."],"ingredient_names":["olive oil","red onions","garlic","ground cumin","ground coriander","tinned tomatos","sugar","mint","lamb mince","dried apricots","breadcrumbs","pita bread"],"allergens":["gluten"],"diet_flags":[]},{"source_id":"53278","title":"Aubergine & hummus grills","category":"Vegetarian","country":"Turkey","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/zub3s91764110535.jpg","youtube_url":"https://www.youtube.com/watch?v=P5LD03XptB8","source_url":"https://www.bbcgoodfood.com/recipes/aubergine-hummus-grills","ingredients":[{"name":"Aubergine","measure":"2"},{"name":"Vegetable Oil","measure":"2 tablespoons"},{"name":"Bread","measure":"3 sliced thinly"},{"name":"Hummus","measure":"300g"},{"name":"Walnuts","measure":"100g"},{"name":"Parsley","measure":"40g"},{"name":"Cherry Tomatoes","measure":"200g"},{"name":"Lemon","measure":"Juice of 1/2"},{"name":"Extra Virgin Olive Oil","measure":"Splash"}],"steps":["Lay the aubergine out in one layer on a large baking sheet. Brush sparingly with vegetable oil, then season generously. Grill for 15 mins, turning twice and brushing with oil until the slices are softened and cooked through. Meanwhile, whizz the bread into crumbs. Add 2 tsp oil and whizz briefly again, to coat.","Spread a couple of tsps of hummus on top of each slice of aubergine. Tip the breadcrumbs onto a large plate, then press the hummus side of the aubergines into the crumbs to coat. Grill again, crumb-side up, for about 3 mins until golden.","Toss the walnuts, parsley and cherry tomatoes in a bowl, season, then add the lemon juice and olive oil and toss again. Serve the grills with the salad, a dollop more hummus and some pitta bread."],"ingredient_names":["aubergine","vegetable oil","bread","hummus","walnuts","parsley","cherry tomatoes","lemon","extra virgin olive oil"],"allergens":["gluten","sesame","tree_nuts"],"diet_flags":["pescatarian","vegan","vegetarian"]},{"source_id":"53280","title":"Poulet Roti a l'Algerienne (Algerian Roast Chicken)","category":"Chicken","country":"Algeria","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/nlxald1764112200.jpg","youtube_url":"https://www.youtube.com/watch?v=78O6Sv7HNO0","source_url":"https://www.allrecipes.com/recipe/258886/poulet-roti-a-lalgerienne-algerian-roast-chicken/","ingredients":[{"name":"Water","measure":"1 cup"},{"name":"Onion","measure":"1 chopped"},{"name":"Olive Oil","measure":"5 tablespoons"},{"name":"Balsamic Vinegar","measure":"2 tablespoons"},{"name":"Dijon Mustard","measure":"1 tablespoon"},{"name":"Garlic","measure":"3 Cloves Crushed"},{"name":"Black Pepper","measure":"1 tsp"},{"name":"Cayenne Pepper","measure":"1 tsp"},{"name":"Salt","measure":"To taste"},{"name":"Chicken","measure":"1"}],"steps":["Preheat oven to 350 degrees F (175 degrees C).","Mix water, onion, olive oil, balsamic vinegar, Dijon mustard, garlic, black pepper, cayenne pepper, and salt together in a roasting dish. Add chicken; turn until well coated with mixture.","Bake in the preheated oven until an instant-read thermometer inserted into the thickest part of the thigh, near the bone, reads 165 degrees F (74 degrees C), about 1 hour 30 minutes."],"ingredient_names":["water","onion","olive oil","balsamic vinegar","dijon mustard","garlic","black pepper","cayenne pepper","salt","chicken"],"allergens":[],"diet_flags":[]},{"source_id":"53281","title":"Algerian Kefta (Meatballs)","category":"Beef","country":"Algeria","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/8rfd4q1764112993.jpg","youtube_url":"https://www.youtube.com/watch?v=IRadJQNLvPs","source_url":"https://www.allrecipes.com/recipe/153790/algerian-kefta-meatballs/","ingredients":[{"name":"Ground Beef","measure":"1 lb"},{"name":"Garlic","measure":"4 Cloves Crushed"},{"name":"Onion","measure":"1/2 cup"},{"name":"Salt","measure":"To taste"},{"name":"Pepper","measure":"To taste"},{"name":"Plum Tomatoes","measure":"3"},{"name":"Parsley","measure":"1 tsp"},{"name":"Water","measure":"1/2 cup"}],"steps":["Combine ground beef with 1/2 of the minced garlic and 1 tablespoon chopped onion in a large bowl. Mix with your hands until fully incorporated. Shape meat mixture into 1 1/2-inch oblong patties; you should have 12 to 14 meatballs.","Heat a large skillet over medium-high heat. Brown patties in batches in the hot skillet until crispy on both sides and no longer pink in the center, about 10 minutes. Set meatballs aside in a rimmed serving dish.","Reduce heat to medium and stir remaining chopped onion into drippings in the skillet. Season with salt and pepper. Cook, stirring constantly, until onion has softened and turned translucent, about 5 minutes. Stir in remaining garlic and cook for 30 seconds. Stir in Roma tomatoes, dried parsley, and ras el hanout. Pour in water. Cook until tomatoes are soft, about 5 minutes.","Pour tomato sauce over meatballs to serve."],"ingredient_names":["ground beef","garlic","onion","salt","pepper","plum tomatoes","parsley","water"],"allergens":[],"diet_flags":[]},{"source_id":"53283","title":"Chtitha Batata (Algerian Potato Stew)","category":"Vegetarian","country":"Algeria","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/q8pu1k1764114334.jpg","youtube_url":"https://www.youtube.com/watch?v=kpsZQTVVjdk","source_url":"https://www.allrecipes.com/recipe/265319/chtitha-batata-algerian-potato-stew/","ingredients":[{"name":"Garlic","measure":"4 cloves"},{"name":"Red Chilli","measure":"1 small"},{"name":"Ground Cumin","measure":"1 tsp"},{"name":"Paprika","measure":"1 teaspoon"},{"name":"Black Pepper","measure":"1/2 teaspoon"},{"name":"Cayenne Pepper","measure":"1/2 teaspoon"},{"name":"Salt","measure":"1/2 teaspoon"},{"name":"Olive Oil","measure":"2 tablespoons"},{"name":"New Potatoes","measure":"2 Lbs"},{"name":"Tomato Puree","measure":"1 tablespoon"},{"name":"Water","measure":"Boiled"},{"name":"Salt","measure":"To taste"}],"steps":["Combine garlic, chile pepper, cumin, paprika, black pepper, cayenne, and salt in a mortar; grind with a pestle until it forms a paste. Add olive oil and mix dersa well.","Heat a large saucepan over medium heat and stir-fry dersa until fragrant, 2 to 4 minutes. Add potato halves and stir to combine with the dersa. Stir in tomato paste. Pour in enough water to just cover the potatoes and bring to a boil. Reduce heat and simmer until potatoes are tender, about 40 minutes.","Ladle potatoes into a serving bowl. Spoon any remaining sauce over the potatoes."],"ingredient_names":["garlic","red chilli","ground cumin","paprika","black pepper","cayenne pepper","salt","olive oil","new potatoes","tomato puree","water","salt"],"allergens":[],"diet_flags":["pescatarian","vegan","vegetarian"]},{"source_id":"53287","title":"Tajine de Poulet aux Carottes et Patates Douces (Chicken and Sweet Potato Tagine)","category":"Chicken","country":"Algeria","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/d8bfyg1764117503.jpg","youtube_url":"https://www.youtube.com/watch?v=thf-JDXoTVg","source_url":"https://www.allrecipes.com/recipe/258873/tajine-de-poulet-aux-carottes-et-patates-douces-chicken-and-sweet-potato-tagine/","ingredients":[{"name":"Onion","measure":"2 sliced"},{"name":"Celery","measure":"2 sliced"},{"name":"Cilantro","measure":"1/2 bag"},{"name":"Parsley","measure":"1/2 bag"},{"name":"Turmeric","measure":"1/2 tsp"},{"name":"Ground Cumin","measure":"1/2 tsp"},{"name":"Paprika","measure":"1/2 teaspoon"},{"name":"Ground Ginger","measure":"1/4 tsp"},{"name":"Cayenne Pepper","measure":"1/4 tsp"},{"name":"Salt","measure":"To taste"},{"name":"Black Pepper","measure":"To taste"},{"name":"Chicken Thighs","measure":"4"},{"name":"Olive Oil","measure":"Drizzle"},{"name":"Raisins","measure":"1/4 cup"},{"name":"Chicken Stock","measure":"1 cup"},{"name":"Sweet Potatoes","measure":"1 large"},{"name":"Carrots","measure":"3 sliced thinly"},{"name":"Prunes","measure":"1/4 cup"}],"steps":["Combine onions, celery, cilantro, and parsley in a large pot. Stir in turmeric, cumin, paprika, ginger, cayenne pepper, salt, and pepper. Place chicken thighs on top. Drizzle olive oil over chicken. Cover and simmer over low heat until chicken is tender, about 40 minutes.","Place raisins in a small bowl and cover with hot water; let soak for 10 minutes. Drain.","Preheat oven to 400 degrees F (200 degrees C).","Transfer chicken mixture into an oven-safe tagine or casserole dish. Add sweet potato and carrots. Cover with lid or aluminum foil.","Bake in the preheated oven until sweet potato is soft, about 40 minutes. Add drained raisins and prunes. Continue baking, covered, until raisins and prunes are heated through, about 10 minutes."],"ingredient_names":["onion","celery","cilantro","parsley","turmeric","ground cumin","paprika","ground ginger","cayenne pepper","salt","black pepper","chicken thighs","olive oil","raisins","chicken stock","sweet potatoes","carrots","prunes"],"allergens":[],"diet_flags":[]},{"source_id":"53288","title":"Algerian Flafla (Bell Pepper Salad)","category":"Vegetarian","country":"Algeria","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/tbj1bs1764118062.jpg","youtube_url":"https://www.youtube.com/watch?v=JXrS1doDnNg","source_url":"https://www.allrecipes.com/recipe/153802/algerian-flafla-bell-pepper-salad/","ingredients":[{"name":"Green Pepper","measure":"3"},{"name":"Olive Oil","measure":"1 tablespoon"},{"name":"Red Onions","measure":"1 tablespoon chopped"},{"name":"Garlic","measure":"1 clove peeled crushed"},{"name":"Salt","measure":"To taste"},{"name":"Pepper","measure":"To taste"},{"name":"Plum Tomatoes","measure":"1 Diced"}],"steps":["Preheat an oven to 450 degrees F (230 degrees C). Place the whole peppers on aluminum foil. Bake until the skin is spotted black and the peppers are soft, 30 to 45 minutes, turning the peppers once if necessary.","Remove peppers from the oven and set aside to cool for 10 minutes. Peel off the skin and remove the stem and seeds. Chop the roasted peppers into half-inch pieces.","Heat the olive oil in a skillet over medium heat. Stir in the onion and cook, stirring frequently, until the onion has softened and turned translucent, about 5 minutes. Add the garlic, salt, and pepper; stir in the chopped peppers and tomato. Cook over medium heat, stirring occasionally, until the tomato is soft and the mixture is well incorporated, about 5 minutes."],"ingredient_names":["green pepper","olive oil","red onions","garlic","salt","pepper","plum tomatoes"],"allergens":[],"diet_flags":["pescatarian","vegan","vegetarian"]},{"source_id":"53289","title":"Chorba Hamra bel Frik (Algerian Lamb, Tomato, and Freekeh Soup)","category":"Lamb","country":"Algeria","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/p9tebp1764118792.jpg","youtube_url":"https://www.youtube.com/watch?v=2z6IldJl_lQ","source_url":"https://www.allrecipes.com/recipe/264552/chorba-hamra-bel-frik-algerian-lamb-tomato-and-freekeh-soup/","ingredients":[{"name":"Freekeh","measure":"1 cup"},{"name":"Lamb","measure":"12 ounces"},{"name":"Onion","measure":"1 finely chopped"},{"name":"Black Pepper","measure":"1 tsp"},{"name":"Paprika","measure":"1 tsp"},{"name":"Ground Cinnamon","measure":"1 tsp"},{"name":"Salt","measure":"To taste"},{"name":"Vegetable Oil","measure":"3  tablespoons"},{"name":"Cilantro","measure":"1  bunch"},{"name":"Mint","measure":"1  bunch"},{"name":"Celery","measure":"1"},{"name":"Chickpeas","measure":"14 oz jar"},{"name":"Water","measure":"4 cups"},{"name":"Zucchini","measure":"1 Diced"},{"name":"Carrots","measure":"1 Diced"},{"name":"Tomato Puree","measure":"1 tablespoon"},{"name":"Tomato","measure":"3 Medium"},{"name":"Potatoes","measure":"1 Diced"}],"steps":["Place freekeh in a small bowl and cover with cold water. Set aside.","Combine lamb, onion, black pepper, paprika, cinnamon, and salt in a pot. Stir in oil, 1/2 the cilantro, 1/2 the mint, and celery stalk until combined. Simmer over low heat for 15 minutes. Stir in chickpeas; pour in just enough water to cover, and return to a simmer. Stir in zucchini, carrot, and tomato paste.","Set a steamer over the pot; add tomatoes. Cover and steam tomatoes until soft, about 5 minutes. Crush tomatoes using a wooden spoon, so pulp drips into soup. Remove the steamer and discard leftover tomato peels.","Add potato to soup and just enough water to cover. Simmer until potato is soft, about 10 minutes.","Drain freekeh and add to soup. Simmer until soft, about 15 minutes. Remove celery stalk and discard. Sprinkle soup with remaining 1/2 cilantro and remaining 1/2 mint before serving."],"ingredient_names":["freekeh","lamb","onion","black pepper","paprika","ground cinnamon","salt","vegetable oil","cilantro","mint","celery","chickpeas","water","zucchini","carrots","tomato puree","tomato","potatoes"],"allergens":[],"diet_flags":[]},{"source_id":"53294","title":"Zapiekanki","category":"Pork","country":"Poland","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/72lmpt1764122511.jpg","youtube_url":"https://www.youtube.com/watch?v=uely-neGHLM","source_url":"https://www.bbcgoodfood.com/recipes/zapiekanki","ingredients":[{"name":"Baguette","measure":"2"},{"name":"Butter","measure":"1 tablespoon"},{"name":"Vegetable Oil","measure":"2 tsp"},{"name":"Onion","measure":"1 chopped"},{"name":"Mushrooms","measure":"300g"},{"name":"Garlic","measure":"1 clove"},{"name":"Mayonnaise","measure":"1 tablespoon"},{"name":"Cheddar Cheese","measure":"50g"},{"name":"Ham","measure":"75g"},{"name":"Polish Kabanos","measure":"75g"},{"name":"Mozzarella","measure":"50g"},{"name":"Dill","measure":"2"},{"name":"Chives","measure":"1 tablespoon"},{"name":"Tomato Ketchup","measure":"Drizzle"}],"steps":["Heat the oven to 200C/180C fan/gas 6. Bake the baguettes on a baking tray for 8-10 mins, then leave to cool.","Heat 2 tsp of the butter and 1 tsp of the oil in a pan over a low heat and cook the chopped onion for 5 mins until soft. Stir in the mushrooms, turn the heat to medium and cook for 5-10 mins more until the veg is soft and the mushroom liquid has evaporated. Stir in the garlic and cook for 1-2 mins until soft. Season, then stir in the mayonnaise and remove from the heat.","Halve the baguettes lengthways, then return to the baking tray, cut-side up and spread over the mushroom mixture, then sprinkle over the cheddar, ham, kabanos and mozzarella. Bake for 8-10 mins, or until the cheese has melted and turned golden.","Meanwhile, heat the remaining butter and oil in a pan over a medium heat and fry the sliced onions for 5 mins until golden and soft. Remove from the heat and set aside. Once the pizzas are cooked, top with the caramelised onions, dill pickles (if using), the chives and a zig-zag drizzle of ketchup."],"ingredient_names":["baguette","butter","vegetable oil","onion","mushrooms","garlic","mayonnaise","cheddar cheese","ham","polish kabanos","mozzarella","dill","chives","tomato ketchup"],"allergens":["dairy","eggs","gluten"],"diet_flags":[]},{"source_id":"53296","title":"Sauerkraut pierogi","category":"Vegetarian","country":"Poland","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/ckbx1h1764123606.jpg","youtube_url":"https://www.youtube.com/watch?v=eVWBJt2jaPU","source_url":"https://www.bbcgoodfood.com/recipes/pierogi","ingredients":[{"name":"Sunflower Oil","measure":"1 tablespoon"},{"name":"Shallots","measure":"2"},{"name":"Sauerkraut","measure":"150g"},{"name":"Hispi (sweetheart) Cabbage","measure":"150g"},{"name":"Egg","measure":"1 large"},{"name":"Vegetable Oil","measure":"1/2 tbs"},{"name":"Plain Flour","measure":"350g"},{"name":"Vegetable Oil","measure":"For frying"},{"name":"Shallots","measure":"2"},{"name":"Plain Flour","measure":"Dusting"},{"name":"Butter","measure":"45g"},{"name":"Sour Cream","measure":"60 ml"}],"steps":["First, make the crispy shallots. Heat the oil in a saucepan to 180C (a cube of bread will turn golden in 15 secs). Toss the shallots in a little flour and deep-fry for 1 min or until light golden and crispy. Drain on kitchen paper. Can be made up to two days before and kept in an airtight container.","To make the filling, heat the oil in a medium non-stick frying pan and gently fry the shallots for 10 mins until starting to turn golden.","Add the sauerkraut and cabbage, and cook for 5-10 mins until the cabbage has softened. Taste and add a little salt if under-seasoned, or sugar if stringent. Scrape into a bowl and leave to cool completely.","To make the dough, mix the eggs and oil with 125ml water, then gradually add in the flour, mixing well with your hands. Knead it on a well-floured surface until the dough stops sticking to your hands. You should end up with firm, elastic dough. Wrap it in cling film and rest in the fridge for at least 30 mins, or overnight.","Flour your work surface generously. Roll out the dough to a 40cm circle or until the dough is as thick as £1 coin.","Using a 9cm cookie cutter, cut out discs in the dough – you should end up with about 25 discs. Do not throw away the off-cuts – we throw them in with the pierogi when boiling to minimise any waste.","Have a well-floured tray ready. Put 1 tsp of the filling into the centre of each disc. In your hand, fold in half around the filling and seal to create half-moon shapes. Put them on the floured tray, making sure they don’t touch each other.","Bring a large saucepan of salted water to the boil and carefully lower the pierogi in. Boil them for 2 mins or until they float to the top.","Drain and serve with a knob of butter and some soured cream. Finish by sprinkling the crispy shallots on top to serve."],"ingredient_names":["sunflower oil","shallots","sauerkraut","hispi (sweetheart) cabbage","egg","vegetable oil","plain flour","vegetable oil","shallots","plain flour","butter","sour cream"],"allergens":["dairy","eggs","gluten"],"diet_flags":["pescatarian","vegetarian"]},{"source_id":"53297","title":"Pomegranate salad","category":"Vegetarian","country":"Poland","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/fqpqml1764359125.jpg","youtube_url":"https://www.youtube.com/watch?v=wTqashUAid8","source_url":"https://www.bbcgoodfood.com/recipes/pomegranate-salad","ingredients":[{"name":"Olive Oil","measure":"60 ml"},{"name":"Lemon Juice","measure":"2 tablespoons"},{"name":"Honey","measure":"1 tablespoon"},{"name":"Thyme","measure":"2 sprigs"},{"name":"Baby Lettuce Leaves","measure":"100g"},{"name":"Cherry Tomatoes","measure":"250g"},{"name":"Spring Onions","measure":"3 chopped"},{"name":"Red Chilli","measure":"1 chopped"},{"name":"Pomegranate","measure":"1"},{"name":"Feta","measure":"50g"}],"steps":["Combine the olive oil, lemon juice, honey and thyme leaves in a large bowl.","Season well, then tip in the lettuce, tomatoes, spring onions and chilli, and toss to combine.","Scoop out the pomegranate seeds over a bowl and remove any white membrane.","Arrange the dressed salad on a platter, then scatter over the pomegranate seeds and feta."],"ingredient_names":["olive oil","lemon juice","honey","thyme","baby lettuce leaves","cherry tomatoes","spring onions","red chilli","pomegranate","feta"],"allergens":["dairy"],"diet_flags":["pescatarian","vegetarian"]},{"source_id":"53300","title":"Bigos (Polish hunter's stew)","category":"Beef","country":"Poland","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/fl4brj1764361323.jpg","youtube_url":"https://www.youtube.com/watch?v=Oqg_cO4s8ik","source_url":"https://www.bbcgoodfood.com/recipes/bigos","ingredients":[{"name":"White Cabbage","measure":"1 sliced"},{"name":"Beef Stock","measure":"250ml"},{"name":"Mushrooms","measure":"100g"},{"name":"Lard","measure":"2 tablespoons"},{"name":"German Sausages","measure":"400g"},{"name":"Bacon","measure":"250g"},{"name":"Onion","measure":"2 chopped"},{"name":"Beef","measure":"750g"},{"name":"Prunes","measure":"200g"},{"name":"Bay Leaf","measure":"1"},{"name":"Cloves","measure":"2"},{"name":"Peppercorns","measure":"12"},{"name":"Juniper Berries","measure":"4"},{"name":"Allspice Berries","measure":"4"},{"name":"Red Wine","measure":"90 ml"},{"name":"Tomato Puree","measure":"2 tablespoons"}],"steps":["Put the cabbage in a heavy casserole dish, add the stock and cook over a low heat for about 50 mins, until tender.","Cut the soaked mushrooms into strips and save the soaking water. Heat the lard and fry the sausages and bacon, then scoop out, leaving the fat in the pan. Fry the onion in the same pan for 5-8 mins until lightly browned.","Add the mushrooms and their liquid along with all the cooked meat, onions and prunes, then cover and cook for 20 mins. Add the spices, red wine and tomato purée and bring to a simmer, then cover and cook for 1 hr. Season well and leave to cool. Will keep covered and chilled for up to two days. Bigos improves in flavour over a couple of days. Leave to cool first. Reheat until piping hot before serving."],"ingredient_names":["white cabbage","beef stock","mushrooms","lard","german sausages","bacon","onion","beef","prunes","bay leaf","cloves","peppercorns","juniper berries","allspice berries","red wine","tomato puree"],"allergens":[],"diet_flags":[]},{"source_id":"53301","title":"Pork & sauerkraut goulash","category":"Pork","country":"Poland","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/cyuhwp1764362103.jpg","youtube_url":"https://www.youtube.com/watch?v=91FM8lHEGbQ","source_url":"https://www.bbcgoodfood.com/recipes/pork-sauerkraut-goulash","ingredients":[{"name":"Lard","measure":"3  tablespoons"},{"name":"Onion","measure":"4 Chopped"},{"name":"Cumin Seeds","measure":"1 tablespoon"},{"name":"Pork Shoulder","measure":"800g"},{"name":"Garlic","measure":"4 Cloves Crushed"},{"name":"Plain Flour","measure":"2 tablespoons"},{"name":"Paprika","measure":"2 tablespoons"},{"name":"Beef Stock","measure":"1 1/2 L"},{"name":"Bay Leaves","measure":"4"},{"name":"White Sauerkraut","measure":"400g"},{"name":"Whipping Cream","measure":"200ml"},{"name":"Sour Cream","measure":"4 tablespoons"}],"steps":["Heat the lard in a saucepan over a medium heat and fry the finely chopped onion until golden, around 5-8 mins. Tip in the cumin and pork, and fry for 10 mins all over until browned. Add the garlic, season well and scatter over the flour. Cook for about a minute, then add the paprika and cook for 1 min more.","Pour in half of the stock, add the bay leaves, and simmer with the lid on over a low heat for 30 mins.","Add the sauerkraut, remaining stock and a drizzle of the sauerkraut pickling juices. Simmer with the lid for 30 mins, stirring occasionally, until the meat is tender. Stir in the cream and simmer for 5 mins to combine the flavours. Season to taste, the serve garnished with a spoonful of soured cream.","This recipe has been provided by Apetit Online and not been re-tested by us."],"ingredient_names":["lard","onion","cumin seeds","pork shoulder","garlic","plain flour","paprika","beef stock","bay leaves","white sauerkraut","whipping cream","sour cream"],"allergens":["dairy","gluten"],"diet_flags":[]},{"source_id":"53302","title":"Slow-roasted ham with lemon, garlic & sage","category":"Pork","country":"Poland","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/w36ets1764362474.jpg","youtube_url":null,"source_url":"https://www.bbcgoodfood.com/recipes/slow-roasted-ham-with-lemon-garlic-sage","ingredients":[{"name":"Garlic","measure":"5 chopped cloves"},{"name":"Lemon","measure":"Zest of 1"},{"name":"Salt","measure":"15g"},{"name":"Black Pepper","measure":"10g"},{"name":"Vegetable Oil","measure":"50 ml"},{"name":"Pork Shoulder","measure":"2kg"},{"name":"Dry White Wine","measure":"500ml"}],"steps":["Heat the oven to 200C/180C fan/gas 6. Bash the garlic, sage, lemon zest, salt and pepper together using a pestle and mortar until the mixture becomes a paste. Stir in the oil, then spread the mixture over the pork shoulder, avoiding the skin on top. Score the skin using a sharp knife, then rub a large pinch of salt into the skin. Tie the pork together using kitchen string.","Line a large baking tray with a double layer of foil and put the pork on top, skin-side up. Bring the sides of the foil up around the pork to create a parcel, then pour the wine into the tray around the sides. Transfer to the oven and reduce the temperature to 140C/120C fan/gas 1. Roast for 4-5 hrs, or until a meat thermometer inserted into the thickest part of the pork reads 70C.","Turn the oven up to 240C/220C fan/gas 9. Carefully spoon the pork roasting juices from the pan into a saucepan and cook over a medium heat for 10-15 mins, or until reduced by a third. Season to taste.","Meanwhile, arrange the foil around the meat so only the skin is exposed, then return to the oven for 10-15 mins until the skin is puffed up and browned all over. Leave to rest for 20 mins before slicing. Serve with the sauce drizzled over."],"ingredient_names":["garlic","lemon","salt","black pepper","vegetable oil","pork shoulder","dry white wine"],"allergens":[],"diet_flags":[]},{"source_id":"53305","title":"Braised stuffed cabbage","category":"Vegetarian","country":"Poland","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/z267f71764364072.jpg","youtube_url":"https://www.youtube.com/watch?v=RNrZpQaj5us","source_url":"https://www.bbcgoodfood.com/recipes/braised-stuffed-cabbage","ingredients":[{"name":"Cabbage Leaves","measure":"6 large"},{"name":"Olive Oil","measure":"2 tablespoons"},{"name":"Onion","measure":"1 chopped"},{"name":"Rosemary","measure":"2 tsp"},{"name":"Celery","measure":"1 chopped"},{"name":"Basmati Rice","measure":"140g"},{"name":"Cooked Chestnut","measure":"140g"},{"name":"Cranberry","measure":"50g"},{"name":"Vegetable Stock","measure":"300ml"},{"name":"Balsamic Vinegar","measure":"1 tablespoon"},{"name":"Clear Honey","measure":"1 tsp"}],"steps":["Heat oven to 180C/fan 160C/gas 4. Remove the tough central stalk from the cabbage leaves. Bring a large pan of salted water to the boil, add the cabbage, then cook for just 1-2 mins until the leaves are starting to wilt. Drain and refresh under cold running water. Drain well, then pat dry with a tea towel.","Heat the oil in a pan, add the onion, then fry for 5 mins until slightly browned. Add the rosemary and celery, then cook for 8 mins more. Stir in the rice, then cook for a min or so until the grains are glistening. Remove from the heat, stir in the chestnuts and cranberries, then season.","Spoon a little stuffing onto a cabbage leaf, roll up and fold in the sides to enclose the filling. Put in a single layer in a large, oiled, shallow ovenproof dish with the join underneath. Fill the remaining leaves in the same way. Mix the stock, vinegar and honey, then pour over the cabbage. Cover the dish tightly with foil, bake for 1 hr, uncover, then cook for a further 15 mins."],"ingredient_names":["cabbage leaves","olive oil","onion","rosemary","celery","basmati rice","cooked chestnut","cranberry","vegetable stock","balsamic vinegar","clear honey"],"allergens":["tree_nuts"],"diet_flags":["pescatarian","vegetarian"]},{"source_id":"53306","title":"Pork rib bortsch","category":"Pork","country":"Poland","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/om5hsl1764364721.jpg","youtube_url":"https://www.youtube.com/watch?v=SqRP4xYS6wA","source_url":"https://www.bbcgoodfood.com/recipes/pork-rib-bortsch","ingredients":[{"name":"Pork Back Ribs","measure":"1kg"},{"name":"Bay Leaves","measure":"2"},{"name":"Dried white beans","measure":"1 tablespoon"},{"name":"Carrots","measure":"1 large"},{"name":"Onion","measure":"1 sliced"},{"name":"Garlic Clove","measure":"3 sliced thinly"},{"name":"Red Pepper","measure":"1 chopped"},{"name":"Red Chilli","measure":"2 chopped"},{"name":"Beetroot","measure":"2"},{"name":"Potatoes","measure":"3 chopped"},{"name":"Tomato Puree","measure":"3  tablespoons"},{"name":"White Cabbage","measure":"1/2"},{"name":"Parsley","measure":"Handful"},{"name":"Dill","measure":"Handful"},{"name":"Sour Cream","measure":"300g"}],"steps":["Cut the meat into large pieces, put in your largest saucepan and cover with 5 litres water. Bring to the boil over a high heat, skimming away any foam that rises to the surface. Add the bay leaves. Season. Turn the heat down to a simmer and cook for 1 hr, or until the meat is soft and falls off the bone. Add the beans if using dried.","Turn the heat up. Bring back to the boil, then reduce the heat and simmer for another 20 mins – the beans should still be slightly raw. Add the carrots, onions, garlic and pepper. Stir well, then add the chillies, if using. Cook for 15 mins more.","Stir in the beetroot and cook for 10 mins before adding the potatoes. After 15 mins, add the tomato purée to taste and beans, if using canned, and bring to the boil. Cook for 5 mins, add the cabbage and cook for 5 mins more. Season, then garnish with the parsley and dill. Turn off the heat and leave to stand for 5 mins. Serve with soured cream on the side."],"ingredient_names":["pork back ribs","bay leaves","dried white beans","carrots","onion","garlic clove","red pepper","red chilli","beetroot","potatoes","tomato puree","white cabbage","parsley","dill","sour cream"],"allergens":["dairy"],"diet_flags":[]},{"source_id":"53307","title":"Beetroot & red cabbage sauerkraut","category":"Vegetarian","country":"Poland","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/ra2k8a1764365055.jpg","youtube_url":"https://www.youtube.com/watch?v=ly1UeAjydEg","source_url":"https://www.bbcgoodfood.com/recipes/beetroot-red-cabbage-sauerkraut","ingredients":[{"name":"Beetroot","measure":"320g"},{"name":"Red Cabbage","measure":"450g"},{"name":"Onion","measure":"1 small"},{"name":"Caraway Seed","measure":"2 tsp"},{"name":"Sea Salt","measure":"1 tsp"}],"steps":["Tip all the ingredients into a large bowl, add 1-1½ tsp freshly ground black pepper, then scrunch it all together with your hands for 5 mins. You might want to wear gloves to avoid staining your skin with the beetroot juices.","Press the veg down in the bowl with your hands, then cover the surface and up the side of the bowl with a large sheet of compostable cling film or something reusable like a beeswax wrap. Now place another similar-sized bowl on top. Press down hard and add anything heavy (packs of rice or cans work well) to weigh it down so the juices rise to cover the surface. Cover again.","Leave to ferment at room temperature for at least five days, but for maximum flavour, leave for one-five weeks (until the bubbling subsides).","Check the sauerkraut. After a few days, you will see bubbles that have built up as it ferments. Give it a stir, then cover and weigh it down again as before. The cabbage will become increasingly sour the longer it’s fermented, so taste it now and again. When you like the flavour, transfer it to sterilised jars and keep chilled. Will keep chilled for up to six months."],"ingredient_names":["beetroot","red cabbage","onion","caraway seed","sea salt"],"allergens":[],"diet_flags":["pescatarian","vegan","vegetarian"]},{"source_id":"53309","title":"Cucumber & fennel salad","category":"Vegetarian","country":"Poland","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/ei21r61764365935.jpg","youtube_url":"https://www.youtube.com/watch?v=gfNjne0AMb0","source_url":"https://www.bbcgoodfood.com/recipes/cucumber-fennel-salad","ingredients":[{"name":"Cucumber","measure":"1 large"},{"name":"Sugar","measure":"1 tsp"},{"name":"Fennel Bulb","measure":"1 sliced"},{"name":"Sour Cream","measure":"150ml"},{"name":"Lemon","measure":"Juice of 1"},{"name":"White Wine Vinegar","measure":"1 tablespoon"},{"name":"Dill","measure":"Bunch"}],"steps":["Put cucumber in a sieve. Sprinkle with 1 tsp salt and the sugar, then leave for 10 mins. Add fennel.","Mix soured cream, lemon juice, vinegar and dill, then season with black pepper and add to fennel mix."],"ingredient_names":["cucumber","sugar","fennel bulb","sour cream","lemon","white wine vinegar","dill"],"allergens":["dairy"],"diet_flags":["pescatarian","vegetarian"]},{"source_id":"53311","title":"Borsch","category":"Beef","country":"Ukraine","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/804v1j1764367088.jpg","youtube_url":"https://www.youtube.com/watch?v=6CXgPVw_-0g","source_url":"https://www.bbcgoodfood.com/recipes/borsch","ingredients":[{"name":"Beef Shin","measure":"1kg"},{"name":"Onion","measure":"1"},{"name":"Bay Leaf","measure":"1"},{"name":"Potatoes","measure":"2.5kg"},{"name":"Sunflower Oil","measure":"2 tablespoons"},{"name":"Onion","measure":"1 Diced"},{"name":"Carrots","measure":"1"},{"name":"Beetroot","measure":"200g"},{"name":"Red Pepper","measure":"1 chopped"},{"name":"Tinned Tomatos","measure":"200g"},{"name":"Prunes","measure":"6"},{"name":"White Cabbage","measure":"1/2"},{"name":"Kidney Beans","measure":"400g"},{"name":"Creme Fraiche","measure":"100 ml"},{"name":"Dill","measure":"Bunch"},{"name":"Crusty Bread","measure":"To serve"}],"steps":["To make the stock, put the meat, whole onion, bay leaf and 2 litres of lightly salted cold water in a large saucepan. Cook over a very low heat for 1 hr 30 mins or until the beef shin is soft and falls apart easily – this can take up to 3 hrs. Skim off the scum with a spoon from time to time. Break up any larger pieces of beef into the broth, remove the whole onion and discard.","Add the potatoes to the borscht, season well with salt and pepper and cook for 10-15 mins until tender. Meanwhile, heat the sunflower oil in a large, deep frying pan. Add the diced onion and carrot, and cook over a medium heat, stirring, until the carrot is soft and is about to start caramelising.","Add the beetroot and cook for around 5 mins, stirring occasionally. Add the red pepper, if using, and cook for another 2 mins, then add the tomatoes and prunes, stir, then increase the heat and boil to reduce slightly, before adding everything to the borscht.","Add the shredded cabbage and the kidney beans, and cook for 7-10 mins or until tender. Serve with a dollop of sour cream or crème fraîche, lots of chopped dill and some crusty bread."],"ingredient_names":["beef shin","onion","bay leaf","potatoes","sunflower oil","onion","carrots","beetroot","red pepper","tinned tomatos","prunes","white cabbage","kidney beans","creme fraiche","dill","crusty bread"],"allergens":["dairy","gluten"],"diet_flags":[]},{"source_id":"53312","title":"Tangy cabbage slaw","category":"Vegetarian","country":"Ukraine","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/e2g2r21764367568.jpg","youtube_url":"https://www.youtube.com/watch?v=oVuAky9HTlM","source_url":"https://www.bbcgoodfood.com/recipes/tangy-cabbage-slaw","ingredients":[{"name":"Mayonnaise","measure":"250ml"},{"name":"Lemon","measure":"Zest and juice of 1"},{"name":"Cider Vinegar","measure":"2 tablespoons"},{"name":"Wholegrain Mustard","measure":"2 tablespoons"},{"name":"Celery Salt","measure":"1 tsp"},{"name":"White Cabbage","measure":"1/4"},{"name":"Red Cabbage","measure":"1/4"},{"name":"Carrots","measure":"2"},{"name":"Onion","measure":"1 Diced"},{"name":"Celery","measure":"2 sliced"}],"steps":["Whisk together mayonnaise, lemon zest and juice, vinegar, mustard and celery salt in a small bowl, then season generously.","Add cabbage, carrots, onion and celery. Mix well and refrigerate. Can be made up to 1 day ahead."],"ingredient_names":["mayonnaise","lemon","cider vinegar","wholegrain mustard","celery salt","white cabbage","red cabbage","carrots","onion","celery"],"allergens":["eggs"],"diet_flags":["pescatarian","vegetarian"]},{"source_id":"53313","title":"Beetroot latkes","category":"Vegetarian","country":"Ukraine","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/qwicc91764368097.jpg","youtube_url":"https://www.youtube.com/watch?v=pRLuLYQnPiM","source_url":"https://www.bbcgoodfood.com/recipes/beetroot-latkes","ingredients":[{"name":"Rapeseed Oil","measure":"1 tablespoon"},{"name":"Greek Yogurt","measure":"4 tablespoons"},{"name":"Mint","measure":"1/2 bag"},{"name":"Rocket","measure":"150g"},{"name":"Cherry Tomatoes","measure":"130g"},{"name":"Beetroot","measure":"400g"},{"name":"Egg","measure":"1 beaten"},{"name":"Plain Flour","measure":"1 tablespoon"},{"name":"Garlic","measure":"1 clove finely chopped"},{"name":"Caraway Seed","measure":"1 tsp"},{"name":"Ground Cumin","measure":"1/2 teaspoon"},{"name":"Lemon","measure":"Zest of 1"}],"steps":["Heat the oven to 180C/160C fan/gas 4. Make the latkes by combining all of the ingredients.","Heat the oil in a large non-stick pan. Spoon in the mixture to make six round latkes. Fry for 4-5 mins on each side, then transfer to a baking sheet and bake for 10 mins.","Combine the yogurt and mint in a small bowl. Toss the salad leaves and tomatoes together, then serve the latkes with the mint yogurt and salad."],"ingredient_names":["rapeseed oil","greek yogurt","mint","rocket","cherry tomatoes","beetroot","egg","plain flour","garlic","caraway seed","ground cumin","lemon"],"allergens":["dairy","eggs","gluten"],"diet_flags":["pescatarian","vegetarian"]},{"source_id":"53314","title":"Sauerkraut pierogii","category":"Vegetarian","country":"Ukraine","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/gqlxgc1764368767.jpg","youtube_url":"https://www.youtube.com/watch?v=eVWBJt2jaPU","source_url":"https://www.bbcgoodfood.com/recipes/pierogi","ingredients":[{"name":"Sunflower Oil","measure":"1 tablespoon"},{"name":"Shallots","measure":"2 chopped"},{"name":"Sauerkraut","measure":"150g"},{"name":"Hispi (sweetheart) Cabbage","measure":"150g"},{"name":"Egg","measure":"1 beaten"},{"name":"Vegetable Oil","measure":"1/2 tbs"},{"name":"Plain Flour","measure":"350g"},{"name":"Vegetable Oil","measure":"For frying"},{"name":"Shallots","measure":"2 sliced"},{"name":"Plain Flour","measure":"Dusting"},{"name":"Butter","measure":"45g"},{"name":"Sour Cream","measure":"60 ml"}],"steps":["First, make the crispy shallots. Heat the oil in a saucepan to 180C (a cube of bread will turn golden in 15 secs). Toss the shallots in a little flour and deep-fry for 1 min or until light golden and crispy. Drain on kitchen paper. Can be made up to two days before and kept in an airtight container.","To make the filling, heat the oil in a medium non-stick frying pan and gently fry the shallots for 10 mins until starting to turn golden.","Add the sauerkraut and cabbage, and cook for 5-10 mins until the cabbage has softened. Taste and add a little salt if under-seasoned, or sugar if stringent. Scrape into a bowl and leave to cool completely.","To make the dough, mix the eggs and oil with 125ml water, then gradually add in the flour, mixing well with your hands. Knead it on a well-floured surface until the dough stops sticking to your hands. You should end up with firm, elastic dough. Wrap it in cling film and rest in the fridge for at least 30 mins, or overnight.","Flour your work surface generously. Roll out the dough to a 40cm circle or until the dough is as thick as £1 coin.","Using a 9cm cookie cutter, cut out discs in the dough – you should end up with about 25 discs. Do not throw away the off-cuts – we throw them in with the pierogi when boiling to minimise any waste.","Have a well-floured tray ready. Put 1 tsp of the filling into the centre of each disc. In your hand, fold in half around the filling and seal to create half-moon shapes. Put them on the floured tray, making sure they don’t touch each other.","Bring a large saucepan of salted water to the boil and carefully lower the pierogi in. Boil them for 2 mins or until they float to the top.","Drain and serve with a knob of butter and some soured cream. Finish by sprinkling the crispy shallots on top to serve."],"ingredient_names":["sunflower oil","shallots","sauerkraut","hispi (sweetheart) cabbage","egg","vegetable oil","plain flour","vegetable oil","shallots","plain flour","butter","sour cream"],"allergens":["dairy","eggs","gluten"],"diet_flags":["pescatarian","vegetarian"]},{"source_id":"53315","title":"Rosemary braised red cabbage with kabanos","category":"Pork","country":"Ukraine","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/s1jxzl1764369317.jpg","youtube_url":null,"source_url":"https://www.bbcgoodfood.com/recipes/rosemary-braised-red-cabbage-kabanos","ingredients":[{"name":"Red Cabbage","measure":"1/2"},{"name":"Olive Oil","measure":"1 tablespoon"},{"name":"Butter","measure":"Knob"},{"name":"Red Onions","measure":"1 sliced"},{"name":"Red Wine Vinegar","measure":"125ml"},{"name":"Brown Sugar","measure":"140g"},{"name":"Red Chilli","measure":"1 chopped"},{"name":"Rosemary","measure":"2 sprigs"},{"name":"Bramley Apples","measure":"1 chopped"},{"name":"Kabanos Sausages","measure":"8"}],"steps":["Halve the cabbage, remove the tough stem and thinly slice. Place in a large pan with all the other ingredients apart from the sausages, then mix in 300ml water and some salt and pepper.","Bring to a simmer, then reduce the heat, cover with a well-fitting lid and gently cook for 1½ hrs, stirring frequently. If too dry, you can add a little more water.","Add the kabanos to the cabbage mixture, place a lid on the pan and gently simmer for 20 mins. Remove the lid and cook for a further 10 mins. Serve alongside some simple mash or boiled potatoes."],"ingredient_names":["red cabbage","olive oil","butter","red onions","red wine vinegar","brown sugar","red chilli","rosemary","bramley apples","kabanos sausages"],"allergens":["dairy"],"diet_flags":[]},{"source_id":"53317","title":"Beef Empanadas","category":"Beef","country":"Uruguay","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/dxpc7j1764370714.jpg","youtube_url":"https://www.youtube.com/watch?v=RRNVLC6IAv4","source_url":"https://jennyisbaking.com/2019/10/25/traditionelle-uruguayische-empanadas/#recipe","ingredients":[{"name":"Lard","measure":"60g"},{"name":"Water","measure":"340g"},{"name":"Salt","measure":"1 tsp"},{"name":"All purpose flour","measure":"600g"},{"name":"Tomato","measure":"3"},{"name":"Garlic","measure":"1 clove"},{"name":"Red Onions","measure":"1 large"},{"name":"Spring Onions","measure":"Bunch"},{"name":"Sirloin steak","measure":"750g"},{"name":"Dried Oregano","measure":"1 tablespoon"},{"name":"Paprika","measure":"1 tsp"},{"name":"Red Pepper Flakes","measure":"1 tsp"},{"name":"Parsley","measure":"1 tsp"},{"name":"Salt","measure":"To taste"},{"name":"Pepper","measure":"To taste"},{"name":"Egg","measure":"3"},{"name":"Egg Wash","measure":"Splash"},{"name":"Chimichurri sauce","measure":"Drizzle"}],"steps":["For the dough place lard, warm water and salt in a large kneading bowl and stir. Add flour and oregano and either knead five miutes by hand or with the kneading function of your machine. Let rest covered for at least half an hour or overnight in the fridge.","For the filling place tomatoes for about 30 seconds in boiling water, then cool with cold water and peel of skin and cut into cubes. Press garlic through garlic press, cut onions into cubes. Simmer garlic and onions in some olive oil until translucent. Take out onions and garlic and brown the meat at high heat from all sides. Season with all herbs and add the onions, garlic and tomatoes. Let simmer for a few minutes, add salt, pepper and additional spices to taste. You can prepare the meat the night before, chill in fridge if doing so. Boil eggs and also cut into cubes and mix with prepared meat.","Cut dough into half and roll out one half thinnly on floured surface. Cut out circles about 12-15cm in diameter. Mine have a diameter of 12.5 cm. Place about 2-4 teaspoons of filling on one circle, put a bit of water all around the edges and fold over the other half so that you get half moons. Be sure to seal the edges with a fork. Repeat until you have no dough and filling left.","Meanwhile preheat oven to 200 degrees Celsius. Brush empanadas with egg wash and bake about 8 empanadas on a baking sheet lined with parchment paper for about 25min or until golden. Serve warm with chimichurri sauce."],"ingredient_names":["lard","water","salt","all purpose flour","tomato","garlic","red onions","spring onions","sirloin steak","dried oregano","paprika","red pepper flakes","parsley","salt","pepper","egg","egg wash","chimichurri sauce"],"allergens":["eggs","gluten"],"diet_flags":[]},{"source_id":"53318","title":"Torta de fiambre","category":"Pork","country":"Uruguay","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/okl9cm1764371087.jpg","youtube_url":"https://www.youtube.com/watch?v=JIDdt3XPi9U","source_url":"https://jennyisbaking.com/2020/12/30/klassische-torta-de-fiambre-aus-uruguay/#recipe","ingredients":[{"name":"Cheddar Cheese","measure":"150g"},{"name":"Ham","measure":"200g"},{"name":"Egg","measure":"3"},{"name":"Vegetable Oil","measure":"100g"},{"name":"Milk","measure":"240g"},{"name":"All purpose flour","measure":"120g"},{"name":"Baking Powder","measure":"2 tsp"},{"name":"Salt","measure":"1 tsp"},{"name":"Dried Oregano","measure":"To taste"}],"steps":["Line the bottom of a springform of 20-2cm (8-9inches) with parchment paper, I usually leave some overhang as the batter is very liquid and may spill a bit. Preheat oven to 220 degrees Celsius.","Grate the cheese and take out the ham.","Mix all remaining ingredients in a large bowl for about one to two minutes.","Pour half the batter into the prepared pan, it is going to be very liquid. Then place ham and cheese on top and pour the remaining batter on top.","Bake for about 20-25 minutes or until top is golden. Wait for a few minutes before releasing from the pan and enjoy either hot or cold with some fresh herbs."],"ingredient_names":["cheddar cheese","ham","egg","vegetable oil","milk","all purpose flour","baking powder","salt","dried oregano"],"allergens":["dairy","eggs","gluten"],"diet_flags":[]},{"source_id":"53319","title":"Chivito sandwich","category":"Beef","country":"Uruguay","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/j80gmw1764372176.jpg","youtube_url":"https://www.youtube.com/watch?v=tX3fN9AG_ik","source_url":"https://jennyisbaking.com/2019/06/14/lets-grill-chivito-uruguays-national-dish/#recipe","ingredients":[{"name":"Milk","measure":"80g"},{"name":"Butter","measure":"60g"},{"name":"Molasses","measure":"1 tablespoon"},{"name":"Water","measure":"220g"},{"name":"Egg","measure":"9"},{"name":"Bread Flour","measure":"500g"},{"name":"Salt","measure":"10g"},{"name":"Yeast","measure":"10g"},{"name":"Egg Wash","measure":"Splash"},{"name":"Sesame Seed","measure":"Sprinkling"},{"name":"Onion","measure":"4"},{"name":"Sirloin steak","measure":"8"},{"name":"Garlic","measure":"To serve"},{"name":"Bacon","measure":"8"},{"name":"Ham","measure":"8 slices"},{"name":"Mozzarella","measure":"8 slices"},{"name":"Tomato","measure":"4"},{"name":"Lettuce","measure":"1/4"},{"name":"Mustard","measure":"To serve"},{"name":"Chimichurri sauce","measure":"To serve"}],"steps":["For the brioche buns heat the milk with the butter and molasses until the butter has melted. Add the cold water and egg to this mix.","In a large bowl place flour, salt and yeast and mix. Then add the milk and water mix and stir with a wooden spoon until combined. You don't have to knead the dough, it is perfectly fine to do this by hand with a wooden spoon, this doesn't need to be very thorough. Cover with a damp towel and stick in the fridge overnight.","The next morning knead dough on a generously floured surface for a little and cut into eight equal pieces. Shape these into balls and place on a baking sheet lined with parchment paper. Cover again with damp towel and let rise for about an hour or until double in size.","Heat oven to 220 degrees Celsius. Brush the buns with either milk, heavy cream or egg wash and sprinkle with sesame seeds, if desired. Bake for about 15-20min or until golden. Let cool.","For the toppings chop the onions and sauté in a bit of butter, let caramelize, this may take ten to 15 minutes, stir occasionally. Rub the steaks with a bit of garlic and then grill or fry the steaks, the bacon, and eggs with salt and pepper, toast the buns after having cut in half. Spread mustard on one bun half, layer each chivito with steak, a slice of ham, a slice of cheese, one bacon stripe, a tomato slice, and some lettuce. Place fried egg on top and sprinkle generously with chimichurri and some onions right before serving."],"ingredient_names":["milk","butter","molasses","water","egg","bread flour","salt","yeast","egg wash","sesame seed","onion","sirloin steak","garlic","bacon","ham","mozzarella","tomato","lettuce","mustard","chimichurri sauce"],"allergens":["dairy","eggs","gluten","sesame"],"diet_flags":[]},{"source_id":"53326","title":"Venezuelan Sancocho","category":"Beef","country":"Venezuela","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/8859m71764377470.jpg","youtube_url":"https://www.youtube.com/watch?v=w6KNOKkcRBs","source_url":"https://mommyshomecooking.com/easy-venezuelan-sancocho/#recipe","ingredients":[{"name":"Hind Shank","measure":"2 Lbs"},{"name":"Onion","measure":"2 small"},{"name":"Pepper","measure":"1/2"},{"name":"Garlic","measure":"4 Cloves Chopped"},{"name":"Garlic","measure":"4 Cloves Crushed"},{"name":"Leek","measure":"1"},{"name":"Beef Stock","measure":"8 cups"},{"name":"Sweet Red Peppers","measure":"1/2 cup"},{"name":"Scallions","measure":"1/2 cup"},{"name":"Sweetcorn","measure":"2"},{"name":"Cassaba","measure":"1/2 lb"},{"name":"Yautia","measure":"1/2 lb"},{"name":"White Yam","measure":"1/2 lb"},{"name":"Butternut Squash","measure":"1/2 lb"},{"name":"Salt","measure":"To taste"},{"name":"Pepper","measure":"To taste"},{"name":"Cilantro","measure":"Chopped"}],"steps":["Add hind shank, 1 halved small onion, halved bell pepper, 4 whole garlic cloves, the dark green leaves of the leek, and stock to a large stockpot. Cook for 45-60 minutes until the meat is fork-tender. NOTE: the meat can take a bit longer to be fork-tender; that is okay, just add more cooking time if necessary.","When the meat is tender, remove the big pieces of vegetables and bones. Discard.","Add diced onion, 2 minced garlic, mini sweet peppers, sliced leeks (light green part), scallions, yucca, and corn; Mix and simmer covered over medium heat for 5- 8 minutes, until the yucca is starting to soften. NOTE: the yuca can take a bit longer to start softening; that is okay, just add more cooking time if necessary.","Add yautia, white yam, and butternut squash. Mix to combine. Simmer covered over medium heat for 5 – 6 minutes, until all the root vegetables are tender. NOTE: Do not cook too much, or they will fall apart.","Taste and add salt to your taste, if necessary. Add cilantro and the remaining 2 minced garlic cloves. Mix and let simmer for 2 more minutes.","Serve hot in large soup bowls, dividing the meat and vegetables evenly. Add a squish of lime juice and/or hot sauce, if desired. Serve along with arepas and or casabe (cassava bread)."],"ingredient_names":["hind shank","onion","pepper","garlic","garlic","leek","beef stock","sweet red peppers","scallions","sweetcorn","cassaba","yautia","white yam","butternut squash","salt","pepper","cilantro"],"allergens":[],"diet_flags":[]},{"source_id":"53327","title":"Venezuelan Coconut Chicken","category":"Chicken","country":"Venezuela","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/z2sw3o1764378271.jpg","youtube_url":"https://www.youtube.com/watch?v=32rCc85rZJA","source_url":"https://www.reluctantgourmet.com/venezuelan-coconut-chicken/#recipe","ingredients":[{"name":"Chicken Breasts","measure":"2"},{"name":"Onion","measure":"2 chopped"},{"name":"Garlic","measure":"1 clove peeled crushed"},{"name":"Bay Leaves","measure":"4"},{"name":"Black Pepper","measure":"Pinch"},{"name":"Turmeric","measure":"Pinch"},{"name":"Cumin","measure":"Pinch"},{"name":"Salt","measure":"Pinch"},{"name":"Sugar","measure":"1 tablespoon"},{"name":"Tomato","measure":"3"},{"name":"Ginger Paste","measure":"1 tablespoon"},{"name":"Olive Oil","measure":"1/3 cup"},{"name":"Coconut Milk","measure":"1 Can"},{"name":"Water","measure":"1/2 cup"}],"steps":["Cut the chicken up into bite size pieces. Peel and cut the onions, mince the garlic.","Assemble the rest of the ingredients and you are ready to start cooking.","Make the Dish","Heat up a fry pan over medium heat. Add the oil and when hot, sauté the onion until translucent. Remove from pan and transfer to a blender or food processor.","Add tomatoes, garlic, turmeric, cumin, sugar, ginger paste, coconut milk, water and blend smooth.","In the same pan you cooked the onion, add the chicken and brown all sides. This should take about 3 minutes.","Add the blender ingredients and bay leaves to the pan, bring to a simmer and cook until the chicken is white inside and the liquid is creamy. (15 to 20 minutes)","Remove the bay leaves and serve with white rice."],"ingredient_names":["chicken breasts","onion","garlic","bay leaves","black pepper","turmeric","cumin","salt","sugar","tomato","ginger paste","olive oil","coconut milk","water"],"allergens":[],"diet_flags":[]},{"source_id":"53328","title":"Venezuelan Shredded Beef","category":"Beef","country":"Venezuela","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/mq27gf1764436795.jpg","youtube_url":"https://www.youtube.com/watch?v=TPn1BKS5Eio","source_url":"https://livingsweetmoments.com/venezuelan-shredded-beef-made-instant-pot/","ingredients":[{"name":"Skirty Steak","measure":"2 Lbs"},{"name":"Garlic","measure":"2 cloves minced"},{"name":"Onion","measure":"1 chopped"},{"name":"Onion","measure":"1 sliced"},{"name":"Red Pepper","measure":"1 sliced"},{"name":"Tomato","measure":"3 sliced thinly"},{"name":"Beef Stock","measure":"4 cups"},{"name":"Worcestershire Sauce","measure":"2 tsp"},{"name":"Tomato Puree","measure":"1 tablespoon"},{"name":"Cumin","measure":"1 tsp"},{"name":"Tomato Ketchup","measure":"1/4 cup"},{"name":"Salt","measure":"To taste"},{"name":"Pepper","measure":"To taste"},{"name":"Olive Oil","measure":"1 tablespoon"}],"steps":["Season beef with salt, pepper and minced garlic","Chop 1 onion in 4 big wedges","Place in the beef pressure cooker with the 4 wedges of onion and the stock","Pressure cook for 20 minutes","Release the pressure and open the lid","Remove the beef and SAVE 2 cups of stock in another container","With 2 forks, shred the beef. Beef should be tender enough to so easily. If not, cook for another 10 minutes","Press the saute button of the Instant pot. Add the olive oil","When the machine beeps, add the sliced onion, pepper and tomatoes. Cook until tender","Add the shredded beef back in the pot and mix","Pour in 1 1/2 cups of the saved stock, the Worcestershire sauce, tomato paste, ketchup and cumin. Mix","If sauce seems to dry, add a tad more of stock","Season with salt and pepper","Serve!"],"ingredient_names":["skirty steak","garlic","onion","onion","red pepper","tomato","beef stock","worcestershire sauce","tomato puree","cumin","tomato ketchup","salt","pepper","olive oil"],"allergens":["fish","gluten"],"diet_flags":[]},{"source_id":"53329","title":"Arepa pelua","category":"Beef","country":"Venezuela","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/jgl9qq1764437635.jpg","youtube_url":"https://www.youtube.com/watch?v=bSWoRyWI6Fo","source_url":"https://goya.es/en/recipes/arepa-pelua","ingredients":[{"name":"Beef","measure":"500g"},{"name":"Onion","measure":"1"},{"name":"Red Pepper","measure":"1"},{"name":"Garlic","measure":"2 cloves"},{"name":"Cumin","measure":"1 tsp"},{"name":"Oregano","measure":"1 tsp"},{"name":"Paprika","measure":"1 tsp"},{"name":"Beef Stock","measure":"1 L"},{"name":"Water","measure":"2 1/2 cups"},{"name":"Salt","measure":"Pinch"},{"name":"Cheese","measure":"200g"},{"name":"Extra Virgin Olive Oil","measure":"Pinch"}],"steps":["Cook the meat: Place the flank steak in a pot with broth or water and salt. Cook over low heat for about 2 hours, until tender and easy to shred.","Shred the meat: Once cooked, drain and shred the meat using two forks.","Prepare the vegetables: Sauté chopped onion, bell pepper, and garlic in a little oil. Add cumin, oregano, paprika, and salt. Stir in the meat and cook for a few minutes until the flavors are well combined.","Make the dough: In a bowl, mix the cornmeal with warm water and salt until a soft dough forms. Let it rest for 5 minutes.","Form the arepas: Divide the dough into 6 portions, shape into balls, and flatten into thick discs.","Cook: Cook the arepas on a griddle or skillet over medium heat for 2–3 minutes on each side until golden. You can then bake them for a few minutes if you prefer them crispier.","Fill: Slice the arepas open on one side, fill with the hot shredded beef, and top with grated cheese."],"ingredient_names":["beef","onion","red pepper","garlic","cumin","oregano","paprika","beef stock","water","salt","cheese","extra virgin olive oil"],"allergens":["dairy"],"diet_flags":[]},{"source_id":"53330","title":"Cassava pizza","category":"Pork","country":"Venezuela","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/lrfdwz1764438393.jpg","youtube_url":"https://www.youtube.com/watch?v=3fK4zsa2AYM","source_url":"https://goya.es/en/recipes/cassava-pizza","ingredients":[{"name":"Casabe","measure":"6 cut thick slices"},{"name":"Tomato Sauce","measure":"450g"},{"name":"Chorizo","measure":"225g"},{"name":"Turkey Ham","measure":"225g"},{"name":"Sweetcorn","measure":"75g"},{"name":"Green Olives","measure":"40g"},{"name":"Paprika","measure":"55g"},{"name":"Mozzarella","measure":"50g"}],"steps":["Preheat the oven to 200ºC.","Cut the bacon or chorizo into medium pieces and the paprika into strips.","Spread a little tomato sauce and mozzarella cheese on each portion of cassava.","Add the bacon or chorizo, corn, turkey ham, some olives and paprika.","Bake for 7 to 10 minutes.","Remove from the oven and enjoy."],"ingredient_names":["casabe","tomato sauce","chorizo","turkey ham","sweetcorn","green olives","paprika","mozzarella"],"allergens":["dairy"],"diet_flags":[]},{"source_id":"53334","title":"Arepa Pabellón","category":"Beef","country":"Venezuela","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/13fg4j1764441982.jpg","youtube_url":"https://www.youtube.com/shorts/Tb1PPOyqthA","source_url":"https://goya.es/en/recipes/arepa-rellena-con-carne-frijol-y-madurito","ingredients":[{"name":"Corn Arepa Filled With Mozarella Cheese","measure":"2"},{"name":"Fried Ripe Bananas","measure":"1"},{"name":"Black Beans","measure":"1 Can"},{"name":"Pico De Gallo Sauce","measure":"1"},{"name":"Shredded Meat","measure":"2kg"},{"name":"Tomato","measure":"1 chopped"},{"name":"Salt","measure":"Pinch"},{"name":"Pepper","measure":"Pinch"}],"steps":["Prepare the meat in a skillet and add salt and pepper to taste, heat the beans over medium heat in a pan, fry or grill the ripe plantains as indicated on its package and cut the tomato into small cubes. Reserve these ingredients until filling.","Preheat the grill or pan and grill the arepa, putting it once on each side until they are golden brown.","With the help of a knife, open it by the edge through the middle, creating a space to fill it with the ripe plantain, the beans, meat and chopped tomato.","Serve with a little pico de gallo or guacamole dip sauce."],"ingredient_names":["corn arepa filled with mozarella cheese","fried ripe bananas","black beans","pico de gallo sauce","shredded meat","tomato","salt","pepper"],"allergens":["dairy"],"diet_flags":[]},{"source_id":"53335","title":"Jiggs Dinner","category":"Beef","country":"Canada","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/z1tfnw1764443171.jpg","youtube_url":"https://www.youtube.com/watch?v=w-rVGvZXVfs","source_url":"https://canadianfoodfocus.org/recipes/classic-canadian-dishes-jiggs-dinner/","ingredients":[{"name":"Beef","measure":"2 Lbs"},{"name":"Yellow Split Peas","measure":"1 cup"},{"name":"Cabbage","measure":"1 head"},{"name":"Carrots","measure":"6"},{"name":"Turnips","measure":"1 large"},{"name":"Potatoes","measure":"8"},{"name":"Butter","measure":"3  tablespoons"},{"name":"Black Pepper","measure":"To taste"}],"steps":["The night before, break salt beef into big chunks and soak in water overnight, at least 8-10 hours. Put split peas into a bowl and cover with water to soak overnight.","Drain the salt beef and place it into a large stockpot. Cover with fresh water, at least 6-7 litres. Place the split peas into a pease pudding canvas bag or triple layer of cheesecloth and tie, making sure to leave room for peas to expand inside the bag.","Put the bag inside the pot, tying the strings to the outside handle so it doesn't stick to the bottom of the pot with the salt beef. Bring to a boil, then lower the heat and simmer for 2 hours.","Remove the peas pudding bag and empty contents into a bowl, mixing with butter and pepper for taste. Set aside.","Add your cabbage to the pot and boil for 20 more minutes. Then add turnip, carrots and potatoes then boil for 20 more, or until vegetables are tender.","Remove salt beef and vegetables from the pot and put them on a platter.","Use the cooking liquid in two ways; as a pot liquor which some people like to drink or reduce it to make a jus or gravy to pour over the meal."],"ingredient_names":["beef","yellow split peas","cabbage","carrots","turnips","potatoes","butter","black pepper"],"allergens":["dairy"],"diet_flags":[]},{"source_id":"53336","title":"Molasses Baked Beans","category":"Vegetarian","country":"Canada","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/9tddhg1764443699.jpg","youtube_url":"https://www.youtube.com/watch?v=60tmFXd4uoI","source_url":"https://canadianfoodfocus.org/recipes/classic-canadian-dishes-molasses-baked-beans/","ingredients":[{"name":"Dried White Navy Beans","measure":"2 cups"},{"name":"Bacon","measure":"1/2 lb"},{"name":"Onion","measure":"1 medium"},{"name":"Molasses","measure":"1/2 cup"},{"name":"Brown Sugar","measure":"1/4 cup"},{"name":"Cider Vinegar","measure":"2 tablespoons"},{"name":"Mustard","measure":"Ground"},{"name":"Salt","measure":"To taste"},{"name":"Pepper","measure":"To taste"}],"steps":["Place the dried beans into a Dutch oven with 6 cups (1.5 L) of water. Soak overnight.","Drain and pour beans back into the pot with enough water to cover the beans by a couple of inches, cook for 30 minutes until they are tender but still firm. Drain beans, making sure to reserve cooking liquid, set aside.","Preheat the oven to 325 °F (160 °C). While the oven is preheating, cook pork over medium-high heat in the Dutch Oven until fat is rendered and pork is beginning to brown, then add the onion cooking until tender.","Add the beans back to the pot, along with molasses, brown sugar, apple cider vinegar, ground mustard, salt and pepper and 3 cups (750 mL) of reserved bean water.","Bake uncovered for 3 to 5 hours until the beans are tender, and the sauce has thickened, and the edges of the pot get sticky.","(Note: if beans get dry, add another cup of water.)"],"ingredient_names":["dried white navy beans","bacon","onion","molasses","brown sugar","cider vinegar","mustard","salt","pepper"],"allergens":[],"diet_flags":[]},{"source_id":"53340","title":"Hodge Podge","category":"Vegetarian","country":"Canada","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/xihv0c1764447887.jpg","youtube_url":null,"source_url":"https://canadianfoodfocus.org/recipes/classic-canadian-dish-hodge-podge/","ingredients":[{"name":"New Potatoes","measure":"1 lb"},{"name":"Carrots","measure":"1 lb"},{"name":"Green Beans","measure":"1 cup"},{"name":"Peas","measure":"1/2 cup"},{"name":"Dill","measure":"1 tablespoon"},{"name":"Chives","measure":"1 tablespoon"},{"name":"Milk","measure":"3 Cups"},{"name":"Heavy Cream","measure":"1/2 cup"},{"name":"Butter","measure":"1/2 cup"},{"name":"Salt","measure":"1/2 tsp"},{"name":"Black Pepper","measure":"1/4 tsp"}],"steps":["First, cook your vegetables. Bring a large pot of salted water to boil. Par-cook carrots and potatoes for five minutes until carrots and potatoes are fork tender, then blanch the peas and beans for about a minute in the same pot. Strain vegetables and set aside.","In a heavy-bottomed pot or Dutch oven, melt butter over medium heat, add vegetables, and cook to warm through.","Add milk and cream and bring the soup to a boil. Turn the heat down to low and season with salt and pepper.","Add dill and chives and let simmer for at least 10 minutes. Serve warm."],"ingredient_names":["new potatoes","carrots","green beans","peas","dill","chives","milk","heavy cream","butter","salt","black pepper"],"allergens":["dairy"],"diet_flags":["pescatarian","vegetarian"]},{"source_id":"53343","title":"Classic Tourtière","category":"Beef","country":"Canada","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/0sd7ac1764787957.jpg","youtube_url":"https://www.youtube.com/watch?v=PM9TZPUJTiU","source_url":"https://canadianfoodfocus.org/recipes/classic-canadian-dish-classic-tourtiere/","ingredients":[{"name":"Canola Oil","measure":"2 tablespoons"},{"name":"Onion","measure":"1 chopped"},{"name":"Garlic","measure":"2 cloves minced"},{"name":"Ground Beef","measure":"1 lb"},{"name":"Ground Pork","measure":"1 lb"},{"name":"Dried Leaves Of Summer Savoury","measure":"1 tsp"},{"name":"Salt","measure":"To taste"},{"name":"Pepper","measure":"To taste"},{"name":"Ground Clove","measure":"1/2 tsp"},{"name":"Ground Nutmeg","measure":"1/2 tsp"},{"name":"Bay Leaf","measure":"1"},{"name":"Beef Stock","measure":"1 cup"},{"name":"Russet Potato","measure":"1 small"},{"name":"Shortcrust Pastry","measure":"4"},{"name":"Egg","measure":"1 beaten"}],"steps":["Heat oil on medium-high heat in a large sauté pan or skillet, then sauté the onion and garlic until softened, about 5 minutes. Add the ground beef, pork, and spices and cook until the meat is browned.","Add the beef broth and bring it up to a simmer then reduce heat to medium low. Add the grated potato and stir it in. Cook until liquid is almost absorbed, about 15 min. Remove the bay leaves and add salt to taste. Remove the pan from the heat and let the mixture cool completely — it bakes best if the filling is chilled.","Preheat the oven to 375 °F (190 °C). On a lightly floured surface, roll out one disc of the pie dough to less than the 1/4-inch thickness and line the 9-inch pie plate. Fill this with the cooled tourtière mixture and spread out evenly. Roll out the remaining dough to the same thickness, cut a hole in the centre (for steam to escape) and place on top of the filling. Trim the dough to 1/2-inch beyond the edge of the pie plate and pinch the edges of the crust together. Brush the crust with the egg wash.","Bake tourtière for about 45 minutes or until the pastry is a rich golden brown. Let cool for 15 minutes before slicing to serve.","Serves: 8-10 (makes 2 9-inch pies)"],"ingredient_names":["canola oil","onion","garlic","ground beef","ground pork","dried leaves of summer savoury","salt","pepper","ground clove","ground nutmeg","bay leaf","beef stock","russet potato","shortcrust pastry","egg"],"allergens":["eggs","gluten"],"diet_flags":[]},{"source_id":"53345","title":"Jamaican Curry Chicken Recipe","category":"Chicken","country":"Jamaica","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/o5fuq51764789643.jpg","youtube_url":null,"source_url":"https://www.myforkinglife.com/jamaican-curry-chicken/","ingredients":[{"name":"Chicken Thighs","measure":"2 Lbs"},{"name":"Curry Powder","measure":"2 1/2 Tbs"},{"name":"All-purpose Seasoning","measure":"1 tsp"},{"name":"Onion","measure":"1 chopped"},{"name":"Spring Onions","measure":"3 chopped"},{"name":"Green Pepper","measure":"1/2"},{"name":"Garlic","measure":"4 Cloves Chopped"},{"name":"Scotch Bonnet","measure":"1 chopped"},{"name":"Thyme","measure":"3 sprigs"},{"name":"Olive Oil","measure":"3  tablespoons"},{"name":"Water","measure":"1/4 cup"},{"name":"Russet Potato","measure":"1 large"},{"name":"Salt","measure":"To taste"},{"name":"Pepper","measure":"To taste"}],"steps":["Equipment","Dutch Oven","Instructions","Add chicken thighs, all-purpose seasoning, 1 tablespoon of curry powder, onion, green onions, green pepper, garlic cloves, scotch bonnet pepper (if using), and thyme to a large bowl and combine, making sure all chicken pieces are covered with the seasoning. Cover and refrigerate for at least 1 hour or up to overnight.","One the chicken is done marinating, remove onions, peppers, and garlic cloves from chicken and set aside.","Heat olive oil in a large heavy bottom pot over medium heat. Add remaining curry powder and stir, cooking for about 20-30 seconds. Add onions, green pepper, garlic cloves, thyme, and scotch bonnet pepper (if using) to pot and stir until onions have softened, about 3-5 minutes. If your onions and peppers are looking dry, add about 1 tablespoon of water.","Add chicken and ¼ cup of water to the pot. Cover and reduce heat to medium low. Cook, stirring occasionally, for 30-35 minutes.","When there is about 15 minutes remaining, stir in potato and continue to cook covered.","Once chicken is cooked and potatoes are softened, remove from heat. Salt and pepper to taste."],"ingredient_names":["chicken thighs","curry powder","all-purpose seasoning","onion","spring onions","green pepper","garlic","scotch bonnet","thyme","olive oil","water","russet potato","salt","pepper"],"allergens":[],"diet_flags":[]},{"source_id":"53349","title":"Jamaican Pepper Shrimp","category":"Seafood","country":"Jamaica","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/bx07m71764792853.jpg","youtube_url":"https://www.youtube.com/watch?v=ILCmxtCp8jc","source_url":"https://www.myforkinglife.com/jamaican-pepper-shrimp-recipe/#recipe","ingredients":[{"name":"Shrimp","measure":"1 lb"},{"name":"Scotch Bonnet","measure":"2 chopped"},{"name":"All-purpose Seasoning","measure":"1 tablespoon"},{"name":"Ground Annatto","measure":"2 tsp"},{"name":"Allspice","measure":"2 tsp"},{"name":"Shrimp Stock","measure":"3/4 cup"},{"name":"Onion","measure":"1/4 cup"},{"name":"Garlic","measure":"2 cloves minced"},{"name":"White Vinegar","measure":"2 tablespoons"},{"name":"Thyme","measure":"3 sprigs"},{"name":"Salt","measure":"To taste"}],"steps":["In a medium bowl, combine shrimp with minced Scotch Bonnet peppers, all-purpose seasoning, ground annatto, and grounf allspice. Toss well to coat evenly and let marinate for 10 minutes.","Heat a large pan over medium heat. Add the shrimp stock and bring to a gentle simmer. Stir in the diced onion and garlic, cooking until softened and fragrant, about 2 minutes.","Add the seasoned shrimp and thyme sprigs, spreading the shrimp in the pan. Cover and cook for about 5–7 minutes, stirring occasionally, until the shrimp turn bright orange and are cooked through.","Add the white vinegar, stir, and cook for another minute. Taste; add salt to taste. Using a slotted spoon, transfer the shrimp to a plate. Serve hot with some cooking liquid drizzled on top."],"ingredient_names":["shrimp","scotch bonnet","all-purpose seasoning","ground annatto","allspice","shrimp stock","onion","garlic","white vinegar","thyme","salt"],"allergens":["shellfish"],"diet_flags":["pescatarian"]},{"source_id":"53350","title":"Corned Beef and Cabbage – Jamaican Style","category":"Beef","country":"Jamaica","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/kdz63q1764793442.jpg","youtube_url":"https://www.youtube.com/watch?v=Bxjz-q2hioA","source_url":"https://www.myforkinglife.com/corned-beef-and-cabbage-jamaican-style/#recipe","ingredients":[{"name":"Olive Oil","measure":"1 tablespoon"},{"name":"Cabbage","measure":"1/2"},{"name":"Green Pepper","measure":"1 chopped"},{"name":"Onion","measure":"1 chopped"},{"name":"Garlic","measure":"2 cloves minced"},{"name":"Corned Beef","measure":"12 ounces"},{"name":"Plum Tomatoes","measure":"2 chopped"},{"name":"Thyme","measure":"2 sprigs"},{"name":"Tomato Ketchup","measure":"1 tablespoon"},{"name":"Salt","measure":"To taste"},{"name":"Pepper","measure":"To taste"}],"steps":["Heat olive oil in a skillet or Dutch pot over medium-high heat. Add onion and green pepper and sauté for about 3-5 minutes.","Add garlic and stir for about 1 minute.","Add shredded cabbage and stir. Cook for about about 3-5 minutes, stirring often until softened.","Add corned beef, Roma tomatoes, and thyme and stir. Add ketchup and scotch bonnet pepper sauce and stir. Reduce heat and cook on medium for about 3-5 minutes, until the corned beef is heated through. Remove from heat.","Serve with white rice, bread, or on its own."],"ingredient_names":["olive oil","cabbage","green pepper","onion","garlic","corned beef","plum tomatoes","thyme","tomato ketchup","salt","pepper"],"allergens":[],"diet_flags":[]},{"source_id":"53352","title":"Jamaican Instant Pot Rice and Beans","category":"Vegetarian","country":"Jamaica","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/11bvtm1764795135.jpg","youtube_url":"https://www.youtube.com/watch?v=iJm1F-TE8Sk","source_url":"https://www.myforkinglife.com/jamaican-instant-pot-rice-and-beans/#recipe","ingredients":[{"name":"Olive Oil","measure":"1 tablespoon"},{"name":"Onion","measure":"1 chopped"},{"name":"Garlic","measure":"1 clove finely chopped"},{"name":"Spring Onions","measure":"2 chopped"},{"name":"Rice","measure":"2 cups"},{"name":"Coconut Milk","measure":"3/4 cup"},{"name":"Water","measure":"3/4 cup"},{"name":"Salt","measure":"1 1/2 tsp"},{"name":"Allspice","measure":"1/2 tsp"},{"name":"Black Pepper","measure":"1/4 tsp"},{"name":"Kidney Beans","measure":"450g"},{"name":"Thyme","measure":"2 sprigs"}],"steps":["Instructions","Set Instant Pot to \"Sauté.\" Once Hot, add olive oil. Then add yellow onion and stir until softened, about 3 minutes. Add garlic and green onions and stir for about 30 more seconds.","Press “Cancel” on the Instant Pot. Add rice, coconut milk, water, salt, allspice, and black pepper and stir.","Pour undrained kidney beans on top of the rice mixture. Do not stir. Lay sprigs of thyme on top. Cover the Instant Pot, ensuring the valve is set to “Sealing.”","Press “Manual” or “Pressure Cook” on the Instant Pot and set for High pressure for 6 minutes.","Once the pressure cooking time is done, allow it to natural release for 10 minutes, then quick release any remaining pressure by moving valve to \"Venting\"","Open lid and remove thyme sprigs. Fluff rice with fork and Enjoy!","Stove Top Instructions","Heat olive oil in a large pot over medium heat. Add yellow onion and stir until softened, about 3 minutes. Add garlic and green onions and stir for about 30 more seconds.","Add rice, undrained kidney beans, coconut milk, water, salt, allspice, and black pepper and stir until combined. Lay thyme on top. Bring mixture to a simmer.","Cover with a lid and reduce heat to low. Allow to cook for 18 minutes over low heat, then remove from heat. Leave the lid on for an additional 5 minutes.","Open the lid and remove the thyme. Fluff rice with fork. Enjoy."],"ingredient_names":["olive oil","onion","garlic","spring onions","rice","coconut milk","water","salt","allspice","black pepper","kidney beans","thyme"],"allergens":[],"diet_flags":["pescatarian","vegan","vegetarian"]},{"source_id":"53354","title":"Jamaican Curry Goat","category":"Goat","country":"Jamaica","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/uc9qp11764796575.jpg","youtube_url":"https://www.youtube.com/watch?v=SrX2KMsWbF4","source_url":"https://www.myforkinglife.com/jamaican-curry-goat/#recipe","ingredients":[{"name":"Goat Meat","measure":"3 Lbs"},{"name":"Jamaican Curry Powder","measure":"2.5 tbsp"},{"name":"Ground Ginger","measure":"1/2 tsp"},{"name":"All-purpose Seasoning","measure":"1/2 tsp"},{"name":"Allspice","measure":"1/4 tsp"},{"name":"Onion","measure":"1 chopped"},{"name":"Garlic","measure":"6 cloves sliced"},{"name":"Thyme","measure":"3 sprigs"},{"name":"Oil","measure":"2 tablespoons"},{"name":"Water","measure":"1 1/4 cup"},{"name":"Scotch Bonnet","measure":"1"},{"name":"Russet Potato","measure":"1 large"},{"name":"Salt","measure":"To taste"},{"name":"Pepper","measure":"To taste"}],"steps":["Equipment","6QT Pressure cooker","Instructions","Rinse goat meat with vinegar and water.","Season goat meat with 1 ½ tablespoon curry powder, all-purpose seasoning, ground ginger, allspice, onion, garlic cloves, and thyme. Marinate for at least 4 hours or up to overnight.","Remove onion and garlic from goat and set aside.","Set an electric pressure cooker, like an Instant Pot, on high sauté and add oil. Add goat meat and brown, about 2-3 minutes per side. Remove goat from insert and add 1 tablespoon oil and remaining curry powder and sauté for about 10 seconds. Then add onions and garlic and sauté until softened. About 4 minutes. If the onions look dry, add a little water and continue to sauté.","Add goat and water to the pressure cooker and cover the pressure cooker. Cook for 40 minutes on high pressure. Allow to naturally release for 10 minutes, then release the remaining pressure.","Once all the pressure has been released, open the pressure cooker. Place on sauté for 10-15 minutes, add potatoes and a whole scotch bonnet pepper. Cook until potatoes have softened. Remove scotch bonnet pepper."],"ingredient_names":["goat meat","jamaican curry powder","ground ginger","all-purpose seasoning","allspice","onion","garlic","thyme","oil","water","scotch bonnet","russet potato","salt","pepper"],"allergens":[],"diet_flags":[]},{"source_id":"53357","title":"Jamaican Rice and Peas","category":"Vegetarian","country":"Jamaica","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/pkyvrn1764878267.jpg","youtube_url":"https://www.youtube.com/watch?v=swVY-6tUK5g","source_url":"https://www.myforkinglife.com/jamaican-rice-and-peas/#recipe","ingredients":[{"name":"Rice","measure":"2 cups"},{"name":"Coconut Milk","measure":"380g"},{"name":"Kidney Beans","measure":"450g"},{"name":"Water","measure":"1 cup"},{"name":"Kosher Salt","measure":"2 tsp"},{"name":"Ground Allspice","measure":"1/2 tsp"},{"name":"Black Pepper","measure":"1/4 tsp"},{"name":"Spring Onions","measure":"3"},{"name":"Thyme","measure":"2 sprigs"},{"name":"Scotch Bonnet","measure":"1"}],"steps":["Equipment","Dutch oven","Add rice, coconut milk, kidney beans, water, kosher salt, allspice, and black pepper to a large pot and stir until combined. Lay green onions, thyme and Scotch bonnet pepper on top. Bring mixture to a boil.","Once boiling, reduce heat to low and cover with a lid. Allow to cook covered for 18 minutes over low heat, then remove from heat. Leave the lid on for an additional 5 minutes.","Open the lid and remove the green onion, Scotch bonnet pepper, and thyme. Fluff the rice and peas with a fork. Serve and enjoy."],"ingredient_names":["rice","coconut milk","kidney beans","water","kosher salt","ground allspice","black pepper","spring onions","thyme","scotch bonnet"],"allergens":[],"diet_flags":["pescatarian","vegan","vegetarian"]},{"source_id":"53358","title":"Chicken Mandi","category":"Chicken","country":"India","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/er4d081765186828.jpg","youtube_url":null,"source_url":null,"ingredients":[{"name":"Chicken","measure":"1"},{"name":"Basmati Rice","measure":"2 cups"},{"name":"Water","measure":"4 cups"},{"name":"Onion","measure":"1 large"},{"name":"Garlic","measure":"4 cloves"},{"name":"Green Chilli","measure":"2"},{"name":"Salt","measure":"1 ½ tsp"},{"name":"Oil","measure":"3 tablespoons"},{"name":"Turmeric Powder","measure":"1 tablespoon"},{"name":"Coriander","measure":"1 teaspoon"},{"name":"Cardamom","measure":"½ tbsp"},{"name":"Cloves","measure":"¼ teaspoon"},{"name":"Cinnamon","measure":"1/2 tsp"},{"name":"Pepper","measure":"1 tsp"},{"name":"Bay Leaf","measure":"2"}],"steps":["Clean and cut the chicken; marinate briefly with salt, turmeric and a little oil.","Rinse and soak basmati rice 20–30 minutes.","In a large pot, heat ghee/oil. Fry chopped onion until golden. Add minced garlic and green chillies and fry 1–2 min.","Add whole spices (cardamom, cloves, cinnamon, bay leaves) and ground spices (coriander, cumin). Stir until fragrant.","Add chicken pieces, brown lightly and add enough water/chicken stock to cover. Simmer until chicken is nearly cooked.","Remove chicken; measure remaining liquid and add soaked rice. Bring to a boil, then reduce heat, cover and cook rice until almost done.","Return the chicken to the rice pot on top, cover tightly and steam on low for 10–15 min so flavors meld.","(Optional) For authentic smoky aroma: heat a small charcoal until red hot, place it on a small foil cup in the centre of the pot, add a tsp of butter/oil on the coal then cover immediately to trap smoke for 5–10 minutes. Remove coal.","Garnish with fried onions, chopped coriander and serve with chutney or raita."],"ingredient_names":["chicken","basmati rice","water","onion","garlic","green chilli","salt","oil","turmeric powder","coriander","cardamom","cloves","cinnamon","pepper","bay leaf"],"allergens":[],"diet_flags":[]},{"source_id":"53359","title":"Beef Mandi","category":"Beef","country":"India","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/1nalo51765188375.jpg","youtube_url":null,"source_url":null,"ingredients":[{"name":"Basmati Rice","measure":"1 kg"},{"name":"Beef Stock","measure":"5 Cups"},{"name":"Onion","measure":"2 medium"},{"name":"Garlic","measure":"5 chopped cloves"},{"name":"Green Chilli","measure":"2"},{"name":"Tomato","measure":"1 small"},{"name":"Salt","measure":"2 1/2 Tsp"},{"name":"Oil","measure":"3  tablespoons"},{"name":"Turmeric Powder","measure":"1 ½ tsp"},{"name":"Cardamom","measure":"1/2 tsp"},{"name":"Cloves","measure":"1/2 tsp"},{"name":"Bay Leaf","measure":"1/2 tsp"}],"steps":["Wash the beef and cut into large pieces. Season lightly with salt and turmeric.","Heat ghee/oil in a large pot. Add sliced onions and sauté until light golden.","Add garlic, green chilies, and tomato; cook until softened.","Add the mandi spice mix: coriander, cumin, black pepper, cinnamon, cardamom, cloves, and bay leaves.","Add beef pieces and stir on medium heat until the meat is well coated with spices.","Pour in water or beef stock. Cover and simmer until beef is tender (about 1.5–2 hours depending on cut).","Remove beef carefully and set aside. Strain and measure the broth.","Add washed, soaked basmati rice to the broth (usually 1 cup rice = 1.5–2 cups liquid). Adjust seasoning and bring to a boil.","Lower heat, cover, and cook the rice until fluffy.","Place the beef pieces over the rice and steam on low heat for 10 minutes so flavors combine.","Optional: For smoky flavor, place a small hot charcoal on foil in the pot, add 1 tsp butter/oil, immediately cover for 5 minutes. Remove coal before serving.","Fluff rice and serve beef mandi with salad or chutney."],"ingredient_names":["basmati rice","beef stock","onion","garlic","green chilli","tomato","salt","oil","turmeric powder","cardamom","cloves","bay leaf"],"allergens":[],"diet_flags":[]},{"source_id":"53362","title":"Jamaican Curry Shrimp Recipe","category":"Seafood","country":"Jamaica","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/n7h5zs1765318909.jpg","youtube_url":"https://www.youtube.com/watch?v=Lnaj4duQ7hs","source_url":"https://www.myforkinglife.com/jamaican-curry-shrimp/#recipe","ingredients":[{"name":"Jumbo Shrimp","measure":"1 lb"},{"name":"Jamaican Curry Powder","measure":"2.5 tbsp"},{"name":"All-purpose Seasoning","measure":"1 tsp"},{"name":"Olive Oil","measure":"2 tablespoons"},{"name":"Onion","measure":"1 sliced"},{"name":"Red Pepper","measure":"1 sliced"},{"name":"Green Pepper","measure":"1 sliced"},{"name":"Scotch Bonnet","measure":"1 sliced"},{"name":"Garlic","measure":"3 cloves Chopped"},{"name":"Unsweetened Coconut Milk","measure":"380g"},{"name":"Tomato Ketchup","measure":"1/2 tbs"},{"name":"Thyme","measure":"4 sprigs"},{"name":"Salt","measure":"To taste"},{"name":"Pepper","measure":"To taste"}],"steps":["Season shrimp with 1 Tablespoon of curry powder and all-purpose seasoning and set aside for about 10 minutes while you prepare the other ingredients like chopping your onions, peppers, and garlic.","Heat 2 Tablespoons of olive oil in a large skillet over medium heat. Add sliced yellow onion, red bell pepper, green bell pepper, scotch bonnet pepper, if using, and chopped garlic and stir for 5 minutes, until peppers are slightly softened.","Add 1.5 Tablespoons of curry powder to the skillet and stir for an additional minute.","Then add coconut milk, seasoned shrimp, ketchup, and thyme, making sure the shrimp is covered in the sauce.","Allow the sauce to come to a simmer and continue to cook over medium heat, stirring occasionally and flipping the shrimp halfway, until the shrimp is fully cooked on both sides. This should take about 5-6 minutes. Salt and pepper to taste."],"ingredient_names":["jumbo shrimp","jamaican curry powder","all-purpose seasoning","olive oil","onion","red pepper","green pepper","scotch bonnet","garlic","unsweetened coconut milk","tomato ketchup","thyme","salt","pepper"],"allergens":["shellfish"],"diet_flags":["pescatarian"]},{"source_id":"53365","title":"Chinese Orange Chicken","category":"Chicken","country":"China","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/s73ytv1765567838.jpg","youtube_url":"https://www.youtube.com/watch?v=-222Dutomek","source_url":"https://www.simplyrecipes.com/recipes/chinese_orange_chicken/","ingredients":[{"name":"Orange","measure":"Zest of 1"},{"name":"Orange Juice","measure":"1/4 cup"},{"name":"Soy Sauce","measure":"1/4 cup"},{"name":"Water","measure":"1/4 cup"},{"name":"Rice Vinegar","measure":"1/3 cup"},{"name":"Cornstarch","measure":"1 tablespoon"},{"name":"Sesame Seed Oil","measure":"1 tablespoon"},{"name":"Sugar","measure":"1/2 cup"},{"name":"Chicken Thighs","measure":"650g"},{"name":"Egg","measure":"2 large"},{"name":"Salt","measure":"1 tsp"},{"name":"Black Pepper","measure":"1/4 tsp"},{"name":"Cornstarch","measure":"1/2 cup"},{"name":"All purpose flour","measure":"1/2 cup"},{"name":"Vegetable Oil","measure":"2 cups"},{"name":"Garlic","measure":"2 cloves chopped"},{"name":"Shallots","measure":"1 chopped"},{"name":"Scallions","measure":"Sliced"},{"name":"Sesame Seed","measure":"Garnish"},{"name":"Rice","measure":"To serve"}],"steps":["Make the orange sauce:","Whisk together sauce ingredients in a medium bowl. Set aside.","Prep the chicken:","Cut chicken into about 1-inch cubes. Whisk eggs with salt and black pepper in a bowl and add chicken. Stir together.","In a separate bowl, whisk together flour and cornstarch. Remove chicken from eggs with a slotted spoon or tongs, letting excess egg drain off, then transfer to cornstarch mixture and coat well.","Fry the chicken:","Add oil to a large 10- to 12-inch skillet. Heat over medium-high heat until it reaches 350°F. If you don’t have a thermometer, you can also test the temperature by sprinkling in some flour. If the oil is hot enough, it should fizzle immediately.","Once oil is hot, fry the chicken in two batches. The oil might not completely cover the chicken—that’s okay. Cook for 3 to 4 minutes. Flip the chicken pieces and cook until the chicken is cooked through, about 3 to 4 more minutes. Total cook time is about 6 to 8 minutes.","Remove fried chicken cubes and transfer to a plate lined with paper towels, so the chicken can drain. Repeat until all the chicken is cooked.","Simmer the chicken in the sauce:","Once chicken is done, pour out hot oil and wipe pan clean. Add a fresh tablespoon of oil along with chopped garlic and shallot. Cook for a minute and then add the sauce. Simmer the sauce until it starts to thicken.","Once the sauce is lightly bubbling, add fried chicken and toss together to coat. The sauce should continue to thicken and stick to the chicken. Let simmer for a minute or two more. Serve orange chicken over cooked white rice, garnished with sesame seeds and fresh scallions.","Did you love this recipe? Let us know with a rating and review!","LEFTOVERS! The orange chicken keeps well in the fridge for 5 days. Reheat in a skillet with a splash of water over low heat. Freeze the orange chicken for up to 3 months, but be sure to thaw it before reheating so the chicken doesn’t clump together."],"ingredient_names":["orange","orange juice","soy sauce","water","rice vinegar","cornstarch","sesame seed oil","sugar","chicken thighs","egg","salt","black pepper","cornstarch","all purpose flour","vegetable oil","garlic","shallots","scallions","sesame seed","rice"],"allergens":["eggs","gluten","sesame","soy"],"diet_flags":[]},{"source_id":"53366","title":"Beef and Broccoli Stir-Fry","category":"Beef","country":"China","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/m0p0j81765568742.jpg","youtube_url":"https://www.youtube.com/watch?v=BBABeZjlRM8","source_url":"https://www.simplyrecipes.com/recipes/broccoli_beef/","ingredients":[{"name":"Soy Sauce","measure":"1 tsp"},{"name":"Dry sherry","measure":"1 tsp"},{"name":"Cornstarch","measure":"1/2 tsp"},{"name":"Black Pepper","measure":"1/8 teaspoon"},{"name":"Sirloin steak","measure":"1 lb"},{"name":"Oyster Sauce","measure":"2 tablespoons"},{"name":"Dry sherry","measure":"1 tsp"},{"name":"Soy Sauce","measure":"1 tablespoon"},{"name":"Chicken Stock","measure":"1/4 cup"},{"name":"Broccoli","measure":"1 lb"},{"name":"High Heat Cooking Oil","measure":"2 tablespoons"},{"name":"Garlic","measure":"2 cloves minced"},{"name":"Cornstarch","measure":"1 tsp"},{"name":"Water","measure":"1 tablespoon"}],"steps":["Marinate the beef:","Stir together the beef marinade ingredients (1 teaspoon soy sauce, 1 teaspoon Chinese rice wine, 1/2 teaspoon cornstarch, 1/8 teaspoon black pepper) in a medium bowl.","Add the beef slices and stir until coated. Let stand for 10 minutes.","Prepare the sauce:","Stir together the sauce ingredients (2 tablespoons oyster sauce, 1 teaspoon Chinese rice wine, 1 teaspoon soy sauce, 1/4 cup chicken broth) in a small bowl. Set aside.","Blanch or steam the broccoli:","Bring a pot of water to a boil. Add the broccoli and cook until crisp-tender, about 2 minutes. Drain thoroughly.","Stir-fry the beef:","Heat a large frying pan or wok over high heat until a bead of water sizzles and instantly evaporates upon contact. Add the cooking oil and swirl to coat.","Add the beef and immediately spread it out all over the surface of the wok or pan in a single layer (preferably not touching).","Let the beef fry undisturbed for 1 minute. Flip the beef slices over, add the garlic to the pan, and fry for an additional 30 seconds to 1 minute until no longer pink.","Add the sauce, cornstarch, and broccoli:","Pour in the sauce and the cornstarch slurry (1 teaspoon cornstarch dissolved in 1 tablespoon of water). Stir until the sauce boils and thickens, about 30 seconds. Stir in the broccoli.","Serve immediately, with steamed rice or on its own."],"ingredient_names":["soy sauce","dry sherry","cornstarch","black pepper","sirloin steak","oyster sauce","dry sherry","soy sauce","chicken stock","broccoli","high heat cooking oil","garlic","cornstarch","water"],"allergens":["gluten","shellfish","soy"],"diet_flags":[]},{"source_id":"53367","title":"Chicken Fried Rice","category":"Chicken","country":"China","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/wuyd2h1765655837.jpg","youtube_url":"https://www.youtube.com/watch?v=mUr-7wjhHuU","source_url":"https://www.simplyrecipes.com/recipes/chicken_fried_rice/","ingredients":[{"name":"Chicken Thighs","measure":"1 lb"},{"name":"Salt","measure":"1 tsp"},{"name":"Canola Oil","measure":"3  tablespoons"},{"name":"Egg","measure":"3 Large"},{"name":"Onion","measure":"2/3 Cup"},{"name":"Garlic","measure":"2 cloves minced"},{"name":"Ground Ginger","measure":"2 tsp"},{"name":"Carrots","measure":"1 large"},{"name":"Peas","measure":"2/3 Cup"},{"name":"Jasmine Rice","measure":"4 cups"},{"name":"Scallions","measure":"2 sliced"},{"name":"Chinese five spice powder","measure":"1/2 tsp"},{"name":"Soy Sauce","measure":"2.5 tbsp"},{"name":"Sesame Seed Oil","measure":"1 tsp"}],"steps":["Fried rice is best made with leftover rice that's at least a day old. Otherwise it becomes gummy in the skillet.","If you don’t have any leftover rice from the night before, cook a batch of rice and spread it on a large baking sheet or several large plates. Let the rice dry out for about 1 to 2 hours before using it for fried rice.","Rice sticks to the pan very easily, so make sure to use a wok or pan that doesn’t have a sticky surface. I usually cook stir-fries in my seasoned carbon steel wok, but cast iron or nonstick pans work well, too. You might need to add a little more oil if things aren’t releasing easily.","Prepare the chicken:","Chop the chicken into small 1/4-inch to 1/2-inch cubes. Sprinkle 1/2 teaspoon of salt over the chicken and mix to combine. Set the chicken aside for about 10 minutes (I usually use this time to chop all the vegetables).","Scramble the egg:","Heat a wok or large sauté pan over medium-high heat. Swirl in a tablespoon of oil and add the whisked eggs. Use a spatula to quickly scramble the eggs, breaking the curds into smaller pieces as they come together. Transfer the eggs to a plate.","Cook the chicken:","Add another tablespoon of oil in the wok or pan. Add the chicken and cook for 4 to 5 minutes, stirring occasionally. Turn off the heat and transfer the cooked chicken to a plate.","Using your spatula, scrape off any chicken bits that are still stuck to the wok so they don't burn during the next step. You can also use paper towels to wipe down your wok or pan.","Cook the vegetables:","Swirl 1 tablespoon of oil into the wok over medium-high heat. Add the diced onions and cook them for 1 minute, until they start to soften. Mix in the minced garlic and ginger and cook until fragrant, about 30 seconds. Add the diced carrots and cook for 2 minutes, stirring frequently. Add 1/2 teaspoon salt and the peas, and stir to incorporate.","Cook the rice:","Add the rice to the wok or pan on top of the vegetables and stir to combine. Using the back of your spatula, smash any large chunks of rice to break them apart. Add the white and green parts of the sliced scallions (save the dark green parts) and five-spice powder. Stir to incorporate. If the rice starts to stick to the pan, stir in a little more oil.","Drizzle the soy sauce and sesame oil over the rice and stir to incorporate. Stir in the cooked chicken, scrambled eggs, and the dark parts of the scallions. Stir briefly to bring it together, and cook for another 1 to 2 minutes.","Serve:","Taste, and add more soy sauce if necessary. Serve immediately."],"ingredient_names":["chicken thighs","salt","canola oil","egg","onion","garlic","ground ginger","carrots","peas","jasmine rice","scallions","chinese five spice powder","soy sauce","sesame seed oil"],"allergens":["eggs","gluten","sesame","soy"],"diet_flags":[]},{"source_id":"53368","title":"Singapore Noodles with Shrimp","category":"Seafood","country":"China","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/f3cxnc1765656994.jpg","youtube_url":"https://www.youtube.com/watch?v=DiFUyPAGoug","source_url":"https://www.simplyrecipes.com/recipes/singapore_noodles_with_shrimp/","ingredients":[{"name":"Sesame Seed Oil","measure":"2 tsp"},{"name":"Soy Sauce","measure":"2 tablespoons"},{"name":"Seasoned Rice Vinegar","measure":"2 tablespoons"},{"name":"Vermicelli Rice Noodles","measure":"6 oz"},{"name":"Egg","measure":"2 large"},{"name":"Ground Ginger","measure":"2 tblsp"},{"name":"Garlic","measure":"1 clove finely chopped"},{"name":"Carrots","measure":"2"},{"name":"Jalapeno","measure":"1 sliced"},{"name":"Onion","measure":"1/2"},{"name":"Salt","measure":"1/2 tsp"},{"name":"Ham","measure":"4 oz"},{"name":"Napa Cabbage","measure":"1/2"},{"name":"Scallions","measure":"4"},{"name":"Red Pepper","measure":"1/2"},{"name":"Curry Powder","measure":"2 tsp"},{"name":"Shrimp","measure":"1/2 lb"},{"name":"Cilantro Leaves","measure":"2 tablespoons"}],"steps":["For the sweet onion, look for Vidalia, OSO Sweet, or Walla Walla. The super-sweet varieties are more suited to this stir-fry because at the end of cooking, the onion still has a slight crunch.","Make the sauce:","In a bowl, combine the sesame oil, soy sauce, and rice vinegar.","Cook the rice noodles:","Bring a large saucepan of water to a boil, add the noodles, and use tongs to turn them so they are submerged. Cook for 2 minutes, or until they are tender but still have some bite (they will cook a little more once you add them to the skillet).","Drain, rinse with cold water, and use scissors to snip the noodles several times to break them up into shorter lengths.","Scramble the eggs:","In a small bowl whisk together the eggs. Heat the skillet or Dutch oven over medium heat. Add 1 tablespoon of the peanut or canola oil. Add the eggs and scramble them for 2 minutes, or until they form large, soft curds. Transfer them from the pan to a plate or bowl.","Cook the vegetables:","Add 1 tablespoon of the remaining oil to the pan. When it is hot, add the ginger, garlic, carrots, jalapeño, onion, and salt. Cook, stirring constantly, for 2 minutes or until the vegetables start to soften.","Add the remaining ingredients:","Sprinkle the vegetable mixture with the remaining 1 tablespoon peanut or canola oil. When the oil is hot, add the ham, cabbage, scallions, red pepper, and curry powder to the pan. Cook, stirring constantly, for 1 minute.","Add the shrimp and cook, stirring, for 3 more minutes or until the shrimp are bright pink and cooked through.","Add the noodles in batches:","Add the eggs, the sauce mixture, and half the noodles to the pan. Toss for 1 minute.","Add the remaining noodles and continue tossing for 1 minute more until they are thoroughly combined and the mixture is heated through.","Serve:","Taste for seasoning and add more salt or soy sauce, if you like. Sprinkle with cilantro leaves and serve."],"ingredient_names":["sesame seed oil","soy sauce","seasoned rice vinegar","vermicelli rice noodles","egg","ground ginger","garlic","carrots","jalapeno","onion","salt","ham","napa cabbage","scallions","red pepper","curry powder","shrimp","cilantro leaves"],"allergens":["eggs","gluten","sesame","shellfish","soy"],"diet_flags":[]},{"source_id":"53369","title":"Silken Tofu with Sesame Soy Sauce","category":"Vegetarian","country":"China","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/j9nray1765657692.jpg","youtube_url":"https://www.youtube.com/shorts/bSLv5vFn5Z0","source_url":"https://www.simplyrecipes.com/silken-tofu-with-sesame-soy-sauce-recipe-6979877","ingredients":[{"name":"Silken Tofu","measure":"16 ounces"},{"name":"Soy Sauce","measure":"3  tablespoons"},{"name":"Chinese Sesame Sauce","measure":"2 tablespoons"},{"name":"Scallions","measure":"1 sliced"},{"name":"Sesame Seed","measure":"2 tsp"}],"steps":["Prepare the tofu:","Drain the tofu and gently remove it from its packaging onto a large plate. Carefully slice the tofu into 1/2-inch slabs widthwise. With the palm of your hands, gently push the sliced tofu sidewise so that they fan out over the plate.","Garnish with toppings and serve:","Drizzle the soy sauce and sesame sauce on top. Then garnish it with scallions and sesame seeds, and serve.","Tightly cover leftovers and refrigerate for up to 2 days. You can enjoy it cold straight out of the fridge or you can reheat it by microwaving in 30-second increments until warmed through"],"ingredient_names":["silken tofu","soy sauce","chinese sesame sauce","scallions","sesame seed"],"allergens":["gluten","sesame","soy"],"diet_flags":["pescatarian","vegan","vegetarian"]},{"source_id":"53370","title":"Egg Foo Young","category":"Seafood","country":"China","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/47y6ii1765658818.jpg","youtube_url":"https://www.youtube.com/watch?v=XVTJrkgW304","source_url":"https://www.simplyrecipes.com/egg-foo-young-recipe-6890222","ingredients":[{"name":"Unsalted Beef Stock","measure":"1 cup"},{"name":"Soy Sauce","measure":"1 tablespoon"},{"name":"Shaoxing Wine","measure":"1 tablespoon"},{"name":"Oyster Sauce","measure":"1 tablespoon"},{"name":"Pepper","measure":"1/2 tsp"},{"name":"Cornstarch","measure":"1 tablespoon"},{"name":"Water","measure":"1 tablespoon"},{"name":"Cornstarch","measure":"1 tablespoon"},{"name":"Water","measure":"1 tablespoon"},{"name":"Egg","measure":"8 large"},{"name":"Kosher Salt","measure":"1/2 tsp"},{"name":"Sugar","measure":"1/4 tsp"},{"name":"Spring Onions","measure":"1"},{"name":"Mung Bean Sprouts","measure":"1 cup"},{"name":"Shrimp","measure":"20"},{"name":"Vegetable Oil","measure":"3 Cups"},{"name":"Jasmine Rice","measure":"2 cups"}],"steps":["Make the gravy:","In a small saucepan, add the beef stock, soy sauce, Shaoxing wine, oyster sauce, and white pepper powder over medium heat. Whisk together and bring to a simmer.","Combine the cornstarch and water in a small bowl and whisk to dissolve. Add to the saucepan and whisk until the gravy thickens and coats the back of the spoon, 2 to 3 minutes. Cover the saucepan with a lid and keep it warm on the lowest possible heat.","Make the egg foo young batter:","In a medium bowl, whisk together the cornstarch and water until dissolved. Add the eggs, salt, and sugar. Whisk until well combined and there are no more egg white clumps.","Add the green onion, bean sprouts, and shrimp. Stir until everything is evenly coated.","Fry the egg foo young:","Add the vegetable oil to a large wok; it should reach about 2 inches up the sides. Heat the oil over medium-high heat to 350°F, or until vigorous bubbles form around an inserted wooden chopstick.","With a ladle, gently and slowly add 1/4 of the omelet batter. Egg foo young should immediately bubble and puff up like magic. Fry until golden brown and crispy on each side, about 2 minutes per side. If there are any light spots, use a ladle to gently baste it with hot oil.","Tip","Egg foo young can be a bit tricky to flip. The easiest method is to put a tool in each hand (a spider, slotted spoon, tongs, and large chopsticks are all good candidates) and gently coax the omelet over, pulling up on one side and pushing down and around on the other.","Remove the omelet and place it on a paper towel-lined baking sheet. Let it cool for 5 minutes. Meanwhile, repeat with the remaining batter to make 4 omelets. If needed, add more oil to the pan between batches.","Serve and enjoy:","Plate each egg foo young over a bed of rice. Spoon the warm gravy over the top and serve immediately."],"ingredient_names":["unsalted beef stock","soy sauce","shaoxing wine","oyster sauce","pepper","cornstarch","water","cornstarch","water","egg","kosher salt","sugar","spring onions","mung bean sprouts","shrimp","vegetable oil","jasmine rice"],"allergens":["eggs","gluten","shellfish","soy"],"diet_flags":[]},{"source_id":"53371","title":"Sichuan Style Stir-Fried Chinese Long Beans","category":"Vegetarian","country":"China","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/i0610h1765659464.jpg","youtube_url":"https://www.youtube.com/watch?v=7mzLphZJ3xc","source_url":"https://www.simplyrecipes.com/recipes/sichuan_style_stir_fried_chinese_long_beans/","ingredients":[{"name":"Chinese Long Beans","measure":"1/2 lb"},{"name":"Peanut Oil","measure":"1 tablespoon"},{"name":"Dried Chillies","measure":"6"},{"name":"Sichuan Pepper","measure":"1 tsp"},{"name":"Salt","measure":"1/4 tsp"},{"name":"Sugar","measure":"1/2 tsp"},{"name":"Sesame Seed Oil","measure":"1 tablespoon"},{"name":"Soy Sauce","measure":"Splash"}],"steps":["Chinese long beans can be found in both green and purple varieties. Both have similar flavors and textures, and either kind can be used for this recipe.","If you don't have a wok, use a sturdy, large sauté pan that has at least a two-inch lip."],"ingredient_names":["chinese long beans","peanut oil","dried chillies","sichuan pepper","salt","sugar","sesame seed oil","soy sauce"],"allergens":["gluten","peanuts","sesame","soy"],"diet_flags":["pescatarian","vegan","vegetarian"]},{"source_id":"53372","title":"Chinese Tomato Egg Stir Fry","category":"Vegetarian","country":"China","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/rwvw8q1765660071.jpg","youtube_url":"https://www.youtube.com/watch?v=Wn8ox93Qhus","source_url":"https://www.simplyrecipes.com/chinese-tomato-egg-recipe-7562056","ingredients":[{"name":"Plum Tomatoes","measure":"1 lb"},{"name":"Vegetable Oil","measure":"1 tablespoon"},{"name":"Eggs","measure":"5 Large"},{"name":"Sesame Seed Oil","measure":"1 tsp"},{"name":"Chicken Bouillon Powder","measure":"2 tsp"},{"name":"Sugar","measure":"2 tsp"},{"name":"Pepper","measure":"1/2 tsp"},{"name":"Salt","measure":"1/4 tsp"},{"name":"Spring Onions","measure":"1"},{"name":"Jasmine Rice","measure":"2 cups"}],"steps":["You can use chicken broth in place of the chicken bouillon powder. Add 1/4 cup of broth followed by 2 teaspoons of cornstarch dissolved in 1 tablespoPrepare the tomatoes:","Slice the tomatoes in half. Remove the tough stem from each half that connects to the vine. Cut each half into equal thirds (you’ll get 6 slices from each tomato).","Make the soft scrambled eggs:","In a cold, 8 to 10-inch nonstick skillet, add the vegetable oil and beaten eggs. Turn the heat to medium. Once a thin layer of eggs is just beginning to cook on the bottom, push the eggs in one direction to create layers of scrambled eggs.","Cook, gently stirring the whole time, until the scramble eggs are mostly set but still slightly wet and shiny, 2 to 5 minutes. Remove the eggs to a plate and, if needed, wipe out the pan.","Stir-fry the tomatoes and seasonings:","Add the sesame oil to the pan followed by the tomatoes and stir-fry over medium heat until the tomatoes are softened but not mushy, about 3 minutes. Add the chicken bouillon powder, sugar, and white pepper. Toss until combined and the sugar and bouillon have dissolved, about 1 minute.","Add eggs, stir-fry, and garnish:","Add the eggs back to the pan with the tomatoes. Stir-fry for about 2 minutes to heat through and combine. Taste, adding salt only if needed. Sprinkle with the green onions and serve with steamed rice.on of water, plus salt to taste."],"ingredient_names":["plum tomatoes","vegetable oil","eggs","sesame seed oil","chicken bouillon powder","sugar","pepper","salt","spring onions","jasmine rice"],"allergens":["eggs","sesame"],"diet_flags":[]},{"source_id":"53374","title":"Sichuan Eggplant","category":"Vegetarian","country":"China","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/1oz4nb1765687990.jpg","youtube_url":"https://www.youtube.com/watch?v=j54Af9gBmzo","source_url":"https://www.simplyrecipes.com/recipes/sichuan_eggplant/","ingredients":[{"name":"Egg Plants","measure":"1.5 pounds sliced"},{"name":"Peanut Oil","measure":"2 tablespoons"},{"name":"Chicken Stock","measure":"1/4 cup"},{"name":"Sugar","measure":"2 tsp"},{"name":"Soy Sauce","measure":"1/2 tsp"},{"name":"Chilli Bean Paste","measure":"1 ½ tbsp"},{"name":"Sichuan Pepper","measure":"2 tsp"},{"name":"Ginger","measure":"2 tsp"},{"name":"Garlic","measure":"5 cloves"},{"name":"Cornstarch","measure":"1 tsp"},{"name":"Apple Cider Vinegar","measure":"2 tsp"},{"name":"Scallions","measure":"4 Chopped"},{"name":"Cilantro","measure":"Garnish"}],"steps":["This recipe calls for asian eggplants, or Japanese eggplants. They are long and thin compared to a European or globe eggplant, and much more tender and delicate. If you can't find them you can substitute globe eggplant, but the dish is really best with the asian eggplant.","*A lot of grocery stores have Asian ingredient aisles now. You should be able to find chili-bean paste, a mixture of preserved chilies mixed with mashed soybeans, there or at any Asian market. (Do not confuse with black bean paste or chili-garlic paste.)","**Sichuan peppercorns are available at some stores and online for quite cheap. They aren't spicy like other peppers but rather have a citrusy flavor and induce a tingly, numbing sensation like a carbonated drink.","Prep eggplant, chili sauce, cornstarch slurry, vinegar and scallions:","Begin your mise en place. Quarter the eggplant lengthwise and chop into large batons and set aside.","In a small bowl, mix together the chicken stock, sugar, and soy sauce and set it aside.","In a second bowl, mix together the chili bean paste, garlic, ginger, and sichuan peppercorns and set it aside.","In a third bowl, mix together the cornstarch with a tablespoon of water and set it aside.","Lastly, in a fourth bowl, mix together the scallions and vinegar and set it aside.","Sauté eggplant:","Place the oil in a wok or large sauté pan over medium-high heat until the oil is almost smoking. Add the eggplant and sauté, allowing it to sit for a few seconds each time you move it to allow it to brown and blister. If the eggplant absorbs all the oil and some pieces don't get any then add a little more oil.","Add the chili bean paste, garlic, ginger, and sichuan peppercorns and sauté:","until fragrant, about 30 seconds.","Add the chicken stock mixture:","turn the heat to medium-low and simmer for 90 seconds.","Add the cornstarch mixture:","and stir together until the sauce thickens a bit.","Add the scallions and vinegar:","and cook for 15 seconds to diffuse their harsh flavors a bit.","Garnish with cilantro and serve."],"ingredient_names":["egg plants","peanut oil","chicken stock","sugar","soy sauce","chilli bean paste","sichuan pepper","ginger","garlic","cornstarch","apple cider vinegar","scallions","cilantro"],"allergens":["eggs","gluten","peanuts","soy"],"diet_flags":[]},{"source_id":"53375","title":"Shrimp With Snow Peas","category":"Seafood","country":"China","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/fpl3mv1766433431.jpg","youtube_url":"https://www.youtube.com/watch?v=RmbTaEqabN4","source_url":"https://www.simplyrecipes.com/recipes/shrimp_with_snow_peas/","ingredients":[{"name":"Cornstarch","measure":"2 tsp"},{"name":"Dry sherry","measure":"1 tablespoon"},{"name":"Kosher Salt","measure":"1/2 tsp"},{"name":"Shrimp","measure":"1 lb"},{"name":"Peanut Oil","measure":"2 tablespoons"},{"name":"Ground Ginger","measure":"1 tablespoon"},{"name":"Garlic","measure":"3 cloves Chopped"},{"name":"Snow Peas","measure":"1/2 lb"},{"name":"Soy Sauce","measure":"2 tsp"},{"name":"Chicken Stock","measure":"1/4 cup"},{"name":"Scallions","measure":"4"},{"name":"Sesame Seed Oil","measure":"2 tsp"}],"steps":["You can also use sugar snap peas for this recipe. Save prep time by prepping the peas, ginger, and garlic while the shrimp is marinating.","Marinate the shrimp:","Mix all marinade ingredients in a large bowl, then add the shrimp. Toss to coat. Let sit for 15 to 20 minutes while you prep the peas, ginger, and garlic.","Stir-fry the ginger and garlic:","Heat a wok or large sauté pan over high heat for 1 minute. Add the peanut oil and let it get hot, about 30 seconds. Add the ginger and garlic and toss to combine. Stir-fry for about 30 seconds.","Add the shrimp, snow peas, soy sauce, stock:","Add the shrimp and all the marinade to the pan (scrape out all the marinade with a rubber spatula). Add the snow peas, soy sauce and chicken stock. Stir-fry until the shrimp turns pink, about 2 minutes.","Add the scallions and finish with sesame oil:","Add the scallions and stir-fry 1 more minute. Turn off the heat and add the sesame oil. Toss to combine once more and serve with steamed rice."],"ingredient_names":["cornstarch","dry sherry","kosher salt","shrimp","peanut oil","ground ginger","garlic","snow peas","soy sauce","chicken stock","scallions","sesame seed oil"],"allergens":["gluten","peanuts","sesame","shellfish","soy"],"diet_flags":[]},{"source_id":"53376","title":"Sweet and Sour Chicken","category":"Chicken","country":"China","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/arzs741766434335.jpg","youtube_url":"https://www.youtube.com/watch?v=cblsP5S9PhU","source_url":"https://www.simplyrecipes.com/recipes/sweet_and_sour_chicken/","ingredients":[{"name":"Chicken Thighs","measure":"1 lb"},{"name":"Egg White","measure":"1 large"},{"name":"Kosher Salt","measure":"1 tsp"},{"name":"Cornstarch","measure":"2 tsp"},{"name":"Pineapple Chunks","measure":"10 oz"},{"name":"Pineapple Juice","measure":"1/4 cup"},{"name":"White Vinegar","measure":"1/4 cup"},{"name":"Tomato Ketchup","measure":"1/4 cup"},{"name":"Brown Sugar","measure":"3  tablespoons"},{"name":"Oil","measure":"4 tsp"},{"name":"Red Pepper","measure":"1 chopped"},{"name":"Yellow Pepper","measure":"1 chopped"},{"name":"Ginger","measure":"1 tsp"}],"steps":["Coat the chicken with egg white:","In a bowl, combine the chicken with the egg white, 1/2 teaspoon kosher salt, and cornstarch. Stir to coat the chicken evenly. Let sit for 15 minutes at room temperature or up to overnight in the refrigerator.","Make the sweet and sour sauce:","Whisk together the pineapple juice, vinegar, ketchup, 1/2 teaspoon kosher salt, and brown sugar.","Stir-fry the chicken over high heat:","Heat a large frying pan or wok over high heat until a bead of water instantly sizzles and evaporates. Pour in 1 tablespoon of cooking oil and swirl to coat. It's important that the pan is very hot.","Add the chicken and spread the pieces out in one layer. Let the chicken fry untouched for 1 minute, until the bottoms are browned.","Flip and fry the other side for 1 minute. The chicken should still be pinkish in the middle. Dish out the chicken onto a clean plate, leaving as much oil in the pan as possible.","Stir-fry the bell pepper and ginger:","Reduce the heat to medium and add the remaining 1 teaspoon of cooking oil. Let the oil heat up before adding the bell pepper chunks and ginger. Fry for 1 minute.","Add the pineapple, sauce, and then, the chicken:","Add the pineapple chunks and the sweet and sour sauce. Turn up the heat to high. When the sauce is simmering, add the chicken pieces back in.","Let simmer for 1 to 2 minutes, until the chicken is cooked through. Timing depends on how thick you've cut your chicken. The best way to tell if the chicken is done is to take a piece out and cut into it. If it's pink, add another minute to the cooking.","Adjust the seasoning and serve:","Taste the sauce and add more brown sugar or vinegar to suit your tastes, if you’d like.","Serve hot with steamed white or brown rice."],"ingredient_names":["chicken thighs","egg white","kosher salt","cornstarch","pineapple chunks","pineapple juice","white vinegar","tomato ketchup","brown sugar","oil","red pepper","yellow pepper","ginger"],"allergens":["eggs"],"diet_flags":[]},{"source_id":"53377","title":"Napa Cabbage with Dried Shrimp","category":"Seafood","country":"China","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/9nh4dl1766435484.jpg","youtube_url":"https://www.youtube.com/watch?v=Fj0JALB4_5k","source_url":"https://www.simplyrecipes.com/napa-cabbage-dried-shrimp-recipe-5208805","ingredients":[{"name":"Dried Shrimp","measure":"2 tablespoons"},{"name":"Boiling Water","measure":"3/4 cup"},{"name":"Napa Cabbage","measure":"1 head"},{"name":"Peanut Oil","measure":"2 tablespoons"},{"name":"Scallions","measure":"4 Chopped"},{"name":"Ginger","measure":"1 tablespoon"},{"name":"Soy Sauce","measure":"1 tablespoon"},{"name":"Water","measure":"1 tablespoon"},{"name":"Cornstarch","measure":"2 tsp"},{"name":"Kosher Salt","measure":"1 tsp"},{"name":"Pepper","measure":"1/2 tsp"}],"steps":["Dried shrimp gives this Chinese dish a punch of salty umami flavor. You can find it at an Asian grocery store in the frozen or refrigerated section. Look for small-sized dried shrimp, about a 1/4-inch in size. If you use medium or large dried shrimp, hydrate the shrimp with more water (1 cup for medium-sized shrimp, 1 1/4 cup for large) and for longer time (45 to 60 minutes), then chop it up into smaller 1/4-inch chunks. To make this recipe vegetarian, omit the dried shrimp and use four or five dried shiitake mushrooms, rehydrated, and sliced thin.","Rehydrate the dried shrimp:","Place the dried shrimp in a small bowl and pour the boiling water over it. Cover with a small plate and let sit for 30 minutes so the shrimp can rehydrate. The shrimp will be lighter in color and plump up slightly.","Prep the cabbage:","Meanwhile, split the napa cabbage in half lengthwise. Rinse the cabbage and shake it dry. Cut out the core of the cabbage and discard.","Set out two large bowls. Cut the remaining cabbage into 1-inch pieces, putting the thicker white pieces at the bottom of the cabbage into one bowl and the top thinner leafy green pieces into the other bowl.","Drain the shrimp:","Once the shrimp has rehydrated, drain it and discard the liquid.","Cook the shrimp and cabbage:","In a large wok or skillet over high heat add the peanut oil, swirling it around to coat the pan.","Heat until the oil looks shimmering hot, then carefully add the scallions, ginger, and rehydrated shrimp, paying specially attention as the wet ingredients may cause the hot oil to splatter. Toss with a spatula until the scallions are bright green and the entire mixture is fragrant, about 1 minute.","Add the thicker white part of the napa cabbage to the pan and lower the heat to medium high. Continue to cook and stir for 3 to 4 minutes, or until the edges of the cabbage pieces start to look slightly translucent but the center of the cabbage pieces are still opaque white.","Reduce the heat to medium low and add the leafy green pieces of cabbage into the pan. Cook until the leaves are wilted, about 2 minutes.","Make a cornstarch slurry:","In a small bowl, combine the soy sauce, cold water, and cornstarch, stirring to make a slurry. Then pour over the cabbage and continue to cook and stir until a sauce has thickened slightly to the consistency of whole milk.","Season the stir fry:","Season the stir fry with salt and pepper, then taste and add more salt and pepper if you wish. The cabbage will be translucent and silky looking, with specks of dried shrimp all over."],"ingredient_names":["dried shrimp","boiling water","napa cabbage","peanut oil","scallions","ginger","soy sauce","water","cornstarch","kosher salt","pepper"],"allergens":["gluten","peanuts","shellfish","soy"],"diet_flags":["pescatarian"]},{"source_id":"53398","title":"Kadu Borani","category":"Vegetarian","country":"Afghanistan","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/walmi81779552709.jpg","youtube_url":"https://www.youtube.com/shorts/DQmh54vl4LE","source_url":"https://www.afghanaid.org.uk/kadu-borani-recipe","ingredients":[{"name":"Squash","measure":"1 medium"},{"name":"Onion","measure":"5 chopped"},{"name":"Green Chilli","measure":"To taste"},{"name":"Oil","measure":"Splash"},{"name":"Turmeric","measure":"1 tsp"},{"name":"Garlic","measure":"1 Bulb"},{"name":"Sugar","measure":"7 tablespoons"},{"name":"Salt","measure":"1/2 tsp"},{"name":"Water","measure":"2 cups"},{"name":"Yogurt","measure":"4 tablespoons"}],"steps":["Peel the squash and cut it into pieces 1cm wide. Deep fry it in oil until golden and set aside.","Using the same pan and oil, deep fry the onions until golden. Remove the onions and grind with the garlic (if using garlic paste, mix it into the onions once ground).","Add a small amount of oil to a pan on medium heat. Once hot, add the turmeric. Mix the salt into one cup of water and add it to the turmeric. Add a layer of squash, then a layer of onion and garlic. Repeat this step until the squash, onion and garlic have been used up.","Add the sugar and one cup of water. Turn the heat down and cook until the water has reduced.","Add 1-2 tablespoons of melted curd to a plate, add the squash on top with another layer of melted curd. At last, add some green chilli and serve!"],"ingredient_names":["squash","onion","green chilli","oil","turmeric","garlic","sugar","salt","water","yogurt"],"allergens":["dairy"],"diet_flags":["pescatarian","vegetarian"]},{"source_id":"53400","title":"Mastawa Lamb and Rice","category":"Lamb","country":"Afghanistan","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/4kzx4d1779554755.jpg","youtube_url":null,"source_url":"https://www.afghanaid.org.uk/mastawa-recipe","ingredients":[{"name":"Lamb","measure":"700g"},{"name":"Onion","measure":"3 Medium"},{"name":"Turmeric","measure":"1 tsp"},{"name":"Orange","measure":"1 large"},{"name":"Rice","measure":"150g"},{"name":"Natural Yoghurt","measure":"500g"},{"name":"Garlic Clove","measure":"4 Cloves Crushed"},{"name":"Vegetable Oil","measure":"1 tblsp"},{"name":"Dried Dill","measure":"1 tablespoon"},{"name":"Black Pepper","measure":"1 tablespoon"},{"name":"Chickpeas","measure":"1 Can"},{"name":"Salt","measure":"To taste"}],"steps":["Place the meat cut into pieces, in a large pan with the onions. Add the turmeric and enough water to cover. Bring to the boil then cook gently until the meat is very tender and can easily be removed from the bones.","While the meat is cooking, cut the orange peel into thin match style pieces, removing as much pith as possible. Leave to soak in a bowl of water.","When the meat is tender, remove from the pan and when cool enough, remove the meat from the bones and shred the meat into strips with your hands. Return the meat to the pan.","Wash the short grain rice and then add to the pan with salt according to taste. The juices should cover the rice by about 2cm, add more water if necessary. Bring back to the boil, then reduce the heat to medium and cook with the lid off, stirring from time to time until the rice is \"al dente\" and the liquid is absorbed.","Add the natural yoghurt, and stir in well but carefully. Fry the crushed cloves of garlic in the oil and add to the dish along with the dill, black pepper, the chickpeas and extra salt to taste.","Mix in well, then cover the top of the pan with a clean thick cloth and the lid. Leave on a low heat for about half an hour to allow the flavours to absorb.","Enjoy with some warm nan bread for extra comfort."],"ingredient_names":["lamb","onion","turmeric","orange","rice","natural yoghurt","garlic clove","vegetable oil","dried dill","black pepper","chickpeas","salt"],"allergens":["dairy"],"diet_flags":[]},{"source_id":"53404","title":"Tavë Kosi Baked Lamb and Yogurt","category":"Lamb","country":"Albania","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/a1mi7t1779643816.jpg","youtube_url":"https://www.youtube.com/watch?v=sinI-D-vhKU","source_url":"https://www.myalbanianfood.com/recipe/albanian-tave-kosi/","ingredients":[{"name":"Lamb","measure":"600g"},{"name":"Butter","measure":"20g"},{"name":"Olive Oil","measure":"2 tablespoons"},{"name":"Rice","measure":"70g"},{"name":"Oregano","measure":"2 tsp"},{"name":"Boiling Water","measure":"450ml"},{"name":"Garlic","measure":"2 cloves chopped"},{"name":"Salt","measure":"Pinch"},{"name":"Pepper","measure":"Pinch"},{"name":"Butter","measure":"50g"},{"name":"Flour","measure":"2 tablespoons"},{"name":"Greek Yogurt","measure":"750g"},{"name":"Eggs","measure":"6"},{"name":"Salt","measure":"Pinch"},{"name":"Pepper","measure":"Pinch"}],"steps":["Baking the Lamb","In a large pan (with a lid) melt the butter and olive oil together then add the diced lamb. Brown the lamb on a medium heat, this will take around 5 minutes.","Add the garlic, oregano, 300ml of water and season with salt and pepper. Mix well before covering with the lid. Leave to simmer for 50 minutes mixing a couple of times ensuring the lamb doesn’t start to burn.","The juices should have nearly all boiled away so another 150ml of water should be added along with the rice. Mix altogether, bring to the boil, place the lid on and leave for just 10 minutes. It’s advised to check at around 8 minutes – you want the liquid to be evaporated with just moist coating of oily water left over the lamb and rice.","Place the lamb and rice into a casserole dish, the mixture should fully cover the base and have at least 2 inches spare for the yogurt. Alternatively you can split into four ceramic bowls.","Making a Roux","In a small saucepan melt the butter over a medium heat and then add two tablespoons of flour while continuously stirring for two minutes (add a little extra flour if needed). The roux should not be thick but not too runny, the colour will darken slightly. Pour the roux into a bowl and keep to one side.","Making the Yogurt Mixture","In a mixing bowl add the yogurt, eggs and season with salt and pepper. Mix together then add the roux continuing to mix fast for a minute to ensure the roux and yogurt are thoroughly combined.","Pour the yogurt mixture over the baked lamb and rice and sprinkle on a little oregano.","Cooking","Place on the bottom shelf of the oven on 180 degrees for 35 minutes then move it up to the middle for a further 10 minutes. The Tavë kosi is ready when the yogurt has risen up high and a golden crust formed.","Leave to cool for 5 – 10 minutes before serving."],"ingredient_names":["lamb","butter","olive oil","rice","oregano","boiling water","garlic","salt","pepper","butter","flour","greek yogurt","eggs","salt","pepper"],"allergens":["dairy","eggs","gluten"],"diet_flags":[]},{"source_id":"53405","title":"Tavë me Presh ska Mish Meatless Leek Bake","category":"Vegetarian","country":"Albania","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/p5m3w21779644533.jpg","youtube_url":"https://www.youtube.com/watch?v=uRAmHFjVMEA","source_url":"https://www.myalbanianfood.com/recipe/albanian-tave-presh-meatless-leek-bake/","ingredients":[{"name":"Leek","measure":"500g"},{"name":"Red Pepper","measure":"3 diced"},{"name":"Rice","measure":"200g"},{"name":"Garlic","measure":"1 clove finely chopped"},{"name":"Vegetable Stock","measure":"1 L"},{"name":"Paprika","measure":"1 tsp"},{"name":"Oregano","measure":"1 tsp"},{"name":"Parsley","measure":"1 tsp"},{"name":"Basil","measure":"1 tsp"},{"name":"Salt","measure":"Pinch"},{"name":"Pepper","measure":"Pinch"},{"name":"Olive Oil","measure":"Splash"}],"steps":["Prepare the dish","Fry the leeks in a small dash of olive oil for a few minutes until they start to brown.","Prepare the Dish","Add the roasted red peppers, garlic, stock, herbs, salt, pepper and paprika. Give it a good stir, add the rice and stir again.","Leave it to come to the boil. Leave to simmer for 2 minutes.","Pour the mixture into a baking tray with a depth of 2 inches or more. Mix thoroughly and ensure equally levelled out.","Cooking","Place on the bottom self of a preheated oven at 180 degrees. Leave to bake for 1 hour.","Serving","Once cooked turn off the oven and keeping the door open leave the leek bake to cool for 10 minutes before serving."],"ingredient_names":["leek","red pepper","rice","garlic","vegetable stock","paprika","oregano","parsley","basil","salt","pepper","olive oil"],"allergens":[],"diet_flags":["pescatarian","vegan","vegetarian"]},{"source_id":"53407","title":"Lakror me Kungull Summer Squash Pie","category":"Vegetarian","country":"Albania","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/ae4rwb1779645576.jpg","youtube_url":"https://www.youtube.com/watch?v=k4aYxqlevGQ","source_url":"https://www.myalbanianfood.com/recipe/summer-squash-pie/","ingredients":[{"name":"Squash","measure":"2"},{"name":"Eggs","measure":"2"},{"name":"Flour","measure":"300g"},{"name":"Baking Powder","measure":"1/4 tsp"},{"name":"Olive Oil","measure":"Splash"}],"steps":["Preparation","In a mixing bowl mix together the summer squash, sugar, eggs and baking soda. Add the flour and continue to mix, you are looking for a thick sticky mixture. Add a bit more flour if the mixture is still thin and slightly runny.","In a large round baking tray (about 2 inches deep) rub some olive oil over the base and edges.","Scoop the mixture onto the tray and spread out evenly, then pour a small amount of olive oil onto you hand and rub it in circles gently over the top of the mixture. This should flatten it and leave it with a slightly shiny glossing.","Cooking","Bake in the oven for 40 minutes on 180 degrees – the top should be a golden brown once cooked.","Serving","Leave to cool before slicing into squares and serving."],"ingredient_names":["squash","eggs","flour","baking powder","olive oil"],"allergens":["eggs","gluten"],"diet_flags":["pescatarian","vegetarian"]},{"source_id":"53410","title":"Presh me Oriz Leek and Rice Bake","category":"Lamb","country":"Albania","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/sjfgbc1779647169.jpg","youtube_url":"https://www.youtube.com/watch?v=se2DU0httvg","source_url":"https://www.myalbanianfood.com/recipe/albanian-leek-and-rice-bake/#google_vignette","ingredients":[{"name":"Leek","measure":"500g"},{"name":"Lamb Mince","measure":"400g"},{"name":"Onion","measure":"1 Diced"},{"name":"Rice","measure":"200g"},{"name":"Lamb Stock","measure":"1 L"},{"name":"Salt","measure":"Pinch"},{"name":"Pepper","measure":"Pinch"},{"name":"Olive Oil","measure":"Splash"}],"steps":["Cooking","Fry the leeks in a small dash of olive oil for a few minutes until they start to brown.","Add the onions and mince and fry until everything is browned. Ensure you keep stirring to prevent the leeks catching and burning.","Add the rice and stir together for a few minutes ensuring the rice is well blended and coated in any juices.","Add the lamb stock, salt and pepper. Give it a good stir and leave it to come to the boil. Leave to boil for 2 minutes.","Baking","Pour the mixture into a large baking tray, place on the bottom self of a preheated oven at 180 degrees. Leave to bake for up to 1 hour. The dish is ready when all the liquid is evaporated and the rice is soft.","Serving","Once cooked turn off the oven and keeping the door open leave the leek and rice bake to cool for 10 minutes before serving."],"ingredient_names":["leek","lamb mince","onion","rice","lamb stock","salt","pepper","olive oil"],"allergens":[],"diet_flags":[]},{"source_id":"53412","title":"Lakra me Mish Cabbage and Meat Stew","category":"Beef","country":"Albania","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/mobh1l1779648766.jpg","youtube_url":"https://www.youtube.com/watch?v=KAsoWvGbpGk","source_url":"https://www.myalbanianfood.com/recipe/lakra-me-mish/","ingredients":[{"name":"Beef","measure":"500g"},{"name":"Cabbage","measure":"1 Diced"},{"name":"Paprika","measure":"2 tsp"},{"name":"Tomato Puree","measure":"3 tsp"},{"name":"Red Pepper","measure":"2 diced"},{"name":"Onion","measure":"1 Diced"},{"name":"Chilli Flakes","measure":"1/4 tsp"},{"name":"Salt","measure":"Pinch"},{"name":"Pepper","measure":"Pinch"},{"name":"Olive Oil","measure":"Splash"},{"name":"Boiling Water","measure":"1 L"}],"steps":["Cooking","Add some olive oil to a saute pan or saucepan (one with a lid). One heated add in the onions, diced beef, red peppers and fry for 5 minutes stirring occasionally. The meat should be fully browned.","Add the paprika, tomato puree, chilli flakes and season with salt and pepper. Mix together and continue to fry for 2 minutes.","Add the cabbage and stir the mixture together. Fry the mixture while stirring occasionally for 3-5 minutes. Most of the oil should have burned away.","Pour the boiling water into the pan, ensuring that the water level completely covers the cabbage, plus about 1 inch above it. Put on the lid and bring to the boil.","Leave to simmer for 2.5 hours. The stew is ready when the cabbage is soft and meat tender.","Serving","Serve into wide bowls and leave to cool for 5 minutes."],"ingredient_names":["beef","cabbage","paprika","tomato puree","red pepper","onion","chilli flakes","salt","pepper","olive oil","boiling water"],"allergens":[],"diet_flags":[]},{"source_id":"53416","title":"Trinxat (Potato, Cabbage and Bacon Hash)","category":"Pork","country":"Andorra","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/khpso71779732715.jpg","youtube_url":"https://www.youtube.com/shorts/Ro-S7zlFvN4","source_url":"https://www.internationalcuisine.com/trinxat/#wprm-recipe-container-12938","ingredients":[{"name":"Cabbage","measure":"1/2"},{"name":"Russet Potato","measure":"2 medium"},{"name":"Bacon","measure":"4 Chopped"},{"name":"Garlic","measure":"2 cloves minced"},{"name":"Parsley","measure":"1 tablespoon"},{"name":"Salt","measure":"To taste"},{"name":"Pepper","measure":"To taste"}],"steps":["Bring salted water to boil in a large pot.","Add in the cabbage and potatoes, cook until tender about 30-40 minutes","When tender, drain, very well.","Return the vegetables to the pot and turn on the burner to low. Let steam","Meanwhile cook up the bacon, reserving the fat for frying the hash.","Chop up the bacon, into small pieces.","Mash the potatoes and cabbage with a potato masher and add in the minced garlic.","Add in salt and pepper to taste.","Using a form for individual servings, press the hash mixture into the form with bacon on top, fry in the reserved bacon fat until golden brown, flip over and repeat on the other side.","Remove form and garnish with chopped parsley.","If you want to make one big hash, just use a skillet, pressing the hash into the skillet with the bacon pieces and reserved fat, then flip over once golden brown. Cut into servings.","Garnish with chopped parsley."],"ingredient_names":["cabbage","russet potato","bacon","garlic","parsley","salt","pepper"],"allergens":[],"diet_flags":[]},{"source_id":"53417","title":"Pa Amb Tomaquet (Bread with Tomato)","category":"Vegetarian","country":"Andorra","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/lz9rw91779733434.jpg","youtube_url":"https://www.youtube.com/watch?v=nFoQ5K-7_24","source_url":"https://www.gimmesomeoven.com/tomato-rubbed-bread-pa-amb-tomaquet-pan-con-tomate/#recipe","ingredients":[{"name":"Bread","measure":"2 sliced"},{"name":"Garlic","measure":"2 cloves"},{"name":"Tomato","measure":"3 chopped"},{"name":"Extra Virgin Olive Oil","measure":"Splash"},{"name":"Sea Salt","measure":"To taste"}],"steps":["Toast the bread slices -- either in a toaster, or by baking them in the oven at 400°F -- until crispy and golden.  (Toasting/baking time will totally depend on the type and thickness of your bread.)","Take a clove of garlic and rub it cut-side-down all over the top of a slice of bread.","Take a tomato half and rub it cut-side-down all over the top of the bread.","Drizzle the bread evenly with a hint of olive oil.  Sprinkle with a pinch of salt.","Repeat with the remaining slices of bread.  Then serve immediately while they're nice and warm!"],"ingredient_names":["bread","garlic","tomato","extra virgin olive oil","sea salt"],"allergens":["gluten"],"diet_flags":["pescatarian","vegan","vegetarian"]},{"source_id":"53418","title":"Cambodian Stir-fried Morning Glory with Pork, Fermented Soybeans, and Garlic","category":"Pork","country":"Cambodia","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/wympxc1779734808.jpg","youtube_url":"https://www.youtube.com/watch?v=_LsP1TP4P9Q","source_url":"https://mitziemee.com/recipe-cambodian-stir-fried-morning-glory/","ingredients":[{"name":"Morning Glory","measure":"1  bunch"},{"name":"Minced Pork","measure":"150g"},{"name":"Soya Bean","measure":"2 tablespoons"},{"name":"Garlic","measure":"4 Cloves Chopped"},{"name":"Oil","measure":"For frying"},{"name":"Fish Sauce","measure":"Dash"},{"name":"Sugar","measure":"Dash"},{"name":"Chilli","measure":"Sprinkling"}],"steps":["In a wok or large pan, heat 1 tablespoon of vegetable oil over medium heat. Once the oil is hot, add the garlic and stir-fry for about 30 seconds, until fragrant but not burnt.","Add the minced pork to the pan and break it up with a spatula. Stir-fry until the pork is fully cooked and browned, about 2-3 minutes.","Stir in the fermented soy beans and cook for another minute, mixing it thoroughly with the pork.","Toss in the cut morning glory and stir-fry for 2-3 minutes to retain its bright green colour and crisp texture.","Check the seasoning and adjust with fish sauce or sugar if needed. Transfer to a serving dish and serve immediately with steamed rice."],"ingredient_names":["morning glory","minced pork","soya bean","garlic","oil","fish sauce","sugar","chilli"],"allergens":["fish","soy"],"diet_flags":[]},{"source_id":"53419","title":"Crispy fried fish with ginger and fermented soybeans (trey chien chuon)","category":"Seafood","country":"Cambodia","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/9q1ci41779735714.jpg","youtube_url":"https://www.youtube.com/watch?v=V0G3ODvMg0k","source_url":"https://mitziemee.com/recipe-cambodian-fried-fish-ginger-fermented-soybeans/","ingredients":[{"name":"Ginger","measure":"2 cups"},{"name":"Fish fillet","measure":"1 lb"},{"name":"Tempura Flour","measure":"2 tablespoons"},{"name":"Oil","measure":"2 cups"},{"name":"Garlic","measure":"4 cloves"},{"name":"Soya Bean","measure":"800g"},{"name":"Sugar","measure":"1/2 tbs"},{"name":"Water","measure":"1/2 cup"},{"name":"Spring Onions","measure":"3"}],"steps":["Fry the ginger in plenty of oil until golden and slightly crispy. Set aside for later.","Cut the fish into strips. Dredge the fish in a very thin layer of tempura flour.","Fry the fish in plenty of oil until golden brown and crispy. You can use the same oil as you were using to fry the ginger.","Crush the garlic and chop it into small pieces. Chop the spring onion.","Drain the fermented soybeans using a colander. If you are using salted beans (soybeans in a very salty brine), you need to wash the beans in water before you add them to the dish.","Add a tablespoon of oil to a deep pan or a large pot, and sauté the garlic until slightly golden.","Add the soybeans and stir fry for a few minutes. If the soybeans are very salty, add ¼- ½ tablespoon sugar to balance the flavor.","Add water and fry for a minute.","Just before serving, stir in the fried ginger, the spring onion, and the crispy fish. Serve with steamed rice."],"ingredient_names":["ginger","fish fillet","tempura flour","oil","garlic","soya bean","sugar","water","spring onions"],"allergens":["fish","gluten","soy"],"diet_flags":["pescatarian"]},{"source_id":"53421","title":"BEEF LOK LAK (Lok Lak Sach Ko)","category":"Beef","country":"Cambodia","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/t2b8bn1779737789.jpg","youtube_url":"https://www.youtube.com/watch?v=3oWgjFhQQW0","source_url":"https://www.chefnak.com/beef-lok-lak","ingredients":[{"name":"Beef Tenderloin","measure":"1 kg"},{"name":"Garlic","measure":"5 cloves"},{"name":"Oil","measure":"2 tablespoons"},{"name":"Palm Sugar","measure":"1.5 tablespoon"},{"name":"Sea Salt","measure":"1 tsp"},{"name":"White Wine","measure":"2 tablespoons"},{"name":"Oyster Sauce","measure":"2 tablespoons"},{"name":"Soy Sauce","measure":"2 tablespoons"},{"name":"Sesame Seed Oil","measure":"1.5 tablespoon"},{"name":"Lettuce","measure":"500g"},{"name":"Tomato","measure":"400g"},{"name":"Onion","measure":"200g"},{"name":"Eggs","measure":"4"},{"name":"Sea Salt","measure":"1.5 tablespoon"},{"name":"Kampot Pepper","measure":"1 tablespoon"},{"name":"Lime juice","measure":"1 tablespoon"}],"steps":["Fry the eggs sunny-side up and set aside. Finely chop the garlic. Wash the lettuce leaves and drain well. Thinly slice the onion and tomatoes.","Cut the beef tenderloin into 2–3 cm cubes. Marinate with sea salt, palm sugar, Chinese cooking wine, oyster sauce, soy sauce, and sesame oil. Mix well.","Heat a frying pan on high heat with cooking oil. Add chopped garlic and stir until the garlic browns lightly. Add the marinated beef (with all the marinade) and cook for 5–7 minutes, depending on how rare you want the beef.","Dry roast the black Kampot peppercorns in a frying pan over medium-low heat for 2–3 minutes until fragrant. Grind the roasted pepper, place it in a bowl, then add sea salt and lime juice. Mix well.","On a serving plate, arrange a bed of lettuce, then layer tomatoes, then onions. Spoon the cooked beef over the vegetables and place fried eggs on top. Serve with the Kampot pepper sauce and fragrant steamed rice.","Sear hot and fast, Lok Lak is at its best when the beef stays tender and juicy, with a bold, bright dipping sauce to cut through the richness."],"ingredient_names":["beef tenderloin","garlic","oil","palm sugar","sea salt","white wine","oyster sauce","soy sauce","sesame seed oil","lettuce","tomato","onion","eggs","sea salt","kampot pepper","lime juice"],"allergens":["eggs","gluten","sesame","shellfish","soy"],"diet_flags":[]},{"source_id":"53423","title":"Meang Nem","category":"Seafood","country":"Cambodia","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/5rk8vc1779740302.jpg","youtube_url":null,"source_url":"https://www.chefnak.com/meang-nem","ingredients":[{"name":"Dried Shrimp","measure":"50g"},{"name":"Rice","measure":"40g"},{"name":"Coconut","measure":"100g"},{"name":"Orange Zest","measure":"20g"},{"name":"Chilli","measure":"3"},{"name":"Peanuts","measure":"50g"},{"name":"Pickled Scallion Heads","measure":"100g"},{"name":"Pickled Scallion Head Brine","measure":"30 ml"},{"name":"Galangal","measure":"25g"},{"name":"Shallots","measure":"30g"},{"name":"Orange Juice","measure":"20 ml"},{"name":"Lime juice","measure":"50 ml"},{"name":"Fish Sauce","measure":"50 ml"},{"name":"Palm Sugar","measure":"50g"}],"steps":["Rinse the rice, soak in water for about 10 minutes, then drain well. Heat a wok or large skillet over medium heat. Add the rice and stir constantly until evenly dark golden brown and very fragrant, about 5 minutes. Transfer to a bowl to cool. Grind finely using a spice grinder or mortar and pestle, then sift through a fine mesh strainer to remove any large pieces. Set aside.","Thinly slice the shallots lengthwise. Finely chop the galangal, pickled scallion heads, chili peppers, and bitter orange zest. Coarsely grind the roasted peanuts. Heat a frying pan over low heat, add shredded coconut, and toast, stirring, for 2–3 minutes. Set aside.","In a large bowl, combine lime juice, bitter orange juice, palm sugar, pickled scallion brine, and fish sauce. Stir until fully dissolved and well mixed.","In a mixing bowl, combine dried shrimp, toasted coconut, chopped aromatics, and dressing. Mix well. Add roasted rice powder and stir again. Top with coarsely ground roasted peanuts.","Place the salad on a large plate. Let each guest spoon a little onto their own small plate, wrap in leafy greens with vegetables, and enjoy in bite-size portions.","For a vegetarian version, omit the dried shrimp and fish sauce. Season to taste with soy sauce and a pinch of sea salt, keeping the sweet-sour balance."],"ingredient_names":["dried shrimp","rice","coconut","orange zest","chilli","peanuts","pickled scallion heads","pickled scallion head brine","galangal","shallots","orange juice","lime juice","fish sauce","palm sugar"],"allergens":["fish","peanuts","shellfish"],"diet_flags":["pescatarian"]},{"source_id":"53427","title":"Lao Naem Khao","category":"Pork","country":"Laos","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/0dypw51779817467.jpg","youtube_url":"https://www.youtube.com/watch?v=qDWN61Ib4A4","source_url":"https://cookingwithlane.com/naem-khao-crispy-coconut-rice-salad/","ingredients":[{"name":"Jasmine Rice","measure":"3 Cups"},{"name":"Coconut","measure":"1"},{"name":"Oil","measure":"Splash"},{"name":"Sour Pork Sausage","measure":"2 cups"},{"name":"Pickled Garlics","measure":"2 diced"},{"name":"Lime","measure":"Juice of 1"},{"name":"Fish Sauce","measure":"2 tablespoons"},{"name":"Sugar","measure":"1 tablespoon"},{"name":"Onion","measure":"1 sliced"},{"name":"Shallots","measure":"1 sliced"},{"name":"Spring Onions","measure":"3 finely chopped"},{"name":"Cilantro","measure":"1 cup"},{"name":"Hot Mint","measure":"1/2 cup"},{"name":"Mint","measure":"1/2 cup"},{"name":"Roasted Peanut","measure":"1/4 cup"},{"name":"Vegetables","measure":"To serve"},{"name":"Lettuce","measure":"To serve"}],"steps":["Slice the onion and shallots thinly. Let them soak in a ice water bath while preparing the rest of the meal.","Grate the coconut. Put in a large bowl.","Add the coconut in a large bowl. Add the rice. Using your hands, mix the coconut and rice together.","Roll the mixture to form 2-inch rice ball croquettes.","Heat up the cooking oil in a pot or pan.","Beat two eggs and a large bowl. Dip the balls into the egg mixture. Then, drop the balls into the cooking oil.","Allow the balls to turn a dark amber brown color. Deep fry until crispy, crunchy, and golden. Remove and set on paper towel to drain excess oil.","Once cooled, break apart the rice balls and add into a larger bowl.","Drain the onion and the shallots.","Make sure you tear the pork sausage up into small pieces. You can use a knife too, but the traditional method is tearing.","In the large bowl, add in the onion, shallots, sour pork sausage, pickled garlic, lime juice, fish sauce, sugar, cilantro, hot mint, regular mint.","Top with peanuts. Serve with Lettuce, dry chilli, and other fresh vegetables.","Preserving Naem Khao Recipe","Naem Khao can be kept in the refrigerator for 4 days. It can then be served chilled.","It should not be frozen.","Serving Naem Khao","Nam Khao is generally served with lettuce leaves and a variety of different herbs like hot mint, mint, basil, and perilla."],"ingredient_names":["jasmine rice","coconut","oil","sour pork sausage","pickled garlics","lime","fish sauce","sugar","onion","shallots","spring onions","cilantro","hot mint","mint","roasted peanut","vegetables","lettuce"],"allergens":["fish","peanuts"],"diet_flags":[]},{"source_id":"53428","title":"Camaro Grelhado Com Molho Cru (Grilled Prawns with Green Onion Sauce)","category":"Seafood","country":"Angola","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/jg4r991779916649.jpg","youtube_url":null,"source_url":"https://www.196flavors.com/wprm_print/camarao-grelhado-com-molho-cru","ingredients":[{"name":"Prawns","measure":"1 lb"},{"name":"Garlic","measure":"2 cloves minced"},{"name":"Spring Onions","measure":"1/2 cup"},{"name":"Ground Cumin","measure":"1 tsp"},{"name":"Salt","measure":"1/4 tsp"},{"name":"White Vinegar","measure":"4 tablespoons"},{"name":"Water","measure":"4 tablespoons"}],"steps":["Make the sauce by combining all the ingredients and grinding them into a paste.","Put the prawns on the skewers and brush with sauce.","Grill until done (they should lose their translucent color), about 3-4 minutes on each side.","Serve with extra sauce on the side."],"ingredient_names":["prawns","garlic","spring onions","ground cumin","salt","white vinegar","water"],"allergens":["shellfish"],"diet_flags":["pescatarian"]},{"source_id":"53432","title":"Slow-cooked, Wadadli-spiced Cubano pork belly","category":"Pork","country":"Antigua and Barbuda","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/t1hg8s1780087329.jpg","youtube_url":null,"source_url":"https://www.theguardian.com/food/2020/jul/04/andi-oliver-antiguan-feast-recipes-slow-cooked-pork-belly-corn-chilli-lime-mango-chow-spiced-bread-butter-pudding","ingredients":[{"name":"Olive Oil","measure":"175ml"},{"name":"Coriander","measure":"4 tablespoons"},{"name":"Parsley","measure":"4 tablespoons"},{"name":"Oregano","measure":"6 tablespoons"},{"name":"Mint","measure":"6 tablespoons"},{"name":"Red Chilli","measure":"2"},{"name":"Green Chilli","measure":"1"},{"name":"Orange","measure":"Zest and juice of 2"},{"name":"Lime","measure":"Zest and juice of 2"},{"name":"Grapefruit","measure":"Juice of 1"},{"name":"Garlic","measure":"40g"},{"name":"Ground Cumin","measure":"3 tsp"},{"name":"Ground Allspice","measure":"2 tablespoons"},{"name":"Salt","measure":"To taste"},{"name":"Black Pepper","measure":"To taste"}],"steps":["Blitz all the marinade ingredients in a food processor or with a hand blender. Lay the pork in a large dish, pour over the marinade, then turn the meat in the mixture, rubbing in the marinade all over and making sure every bit of the belly is coated. Cover the dish and leave overnight in the fridge.","The next day, heat the oven to 140C (120C fan)/275F/gas 1. Lift the meat out of its marinade (don’t wipe off any that sticks to the joint, though; just leave most of the marinade behind in the dish) and transfer to a large roasting dish. Cover with foil, slip into the oven and roast for four and a half hours – every now and then (say, three or four times over the whole cooking period), take the dish out of the oven, lift off the foil lid and spoon the juices from the bottom of the dish over the meat. Return the foil lid, then put back in the oven.","After the time is up, remove the foil, turn up the heat to 180C (160C fan)/350F/gas 4 and give the pork a final blast – after 15-20 minutes, the top will take on a lovely colour and the meat should be yielding and soft enough to cut with a spoon.","To make crackling shards to serve with the meat, heat the oven to 200C (180C fan)/390F/gas 6 and line a roasting tray with baking paper. Lightly score the skin from the pork belly with a sharp knife, then rub it with a three or four fat pinches of salt – I also like to add a few caraway, cumin or fennel seeds at this point (use anything that takes your fancy). Cut the skin into long strips and lay these fat side down on the lined tray (you can, of course, leave it whole, but I think its pleasing to dress the plate with long, golden shards of crackling). Lay a second sheet of baking paper on top of the skin, then put a second baking tray of the same size on top, and roast for 45 minutes to an hour (if by this point the crackling has not gone crisp, just put it back in the oven and carry on roasting it until it has).","Cut or pull the pork apart, top with finely chopped coriander and flat-leaf parsley and shards of crackling, if you have made them, and serve at once"],"ingredient_names":["olive oil","coriander","parsley","oregano","mint","red chilli","green chilli","orange","lime","grapefruit","garlic","ground cumin","ground allspice","salt","black pepper"],"allergens":[],"diet_flags":[]},{"source_id":"53437","title":"Leg of Lamb Armenian-Style","category":"Lamb","country":"Armenia","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/vy6k391780090969.jpg","youtube_url":null,"source_url":"https://www.armenianmuseum.org/armenian-recipes/leg-of-lamb-armenian-style","ingredients":[{"name":"Lamb Leg","measure":"1"},{"name":"Garlic","measure":"1 Bulb"},{"name":"Garlic","measure":"1 Bulb"},{"name":"Parsley","measure":"1 1/2 cup"},{"name":"Onion","measure":"1 cup"},{"name":"Black Pepper","measure":"1 tablespoon"},{"name":"Balsamic Vinegar","measure":"1 cup"},{"name":"Olive Oil","measure":"1/2 cup"},{"name":"Mint","measure":"1/4 cup"},{"name":"Salt","measure":"To taste"}],"steps":["Place all of the above ingredients into your roaster pan at least two days before you want to eat.","Stir occasionally throughout the days to distribute marinade evenly.","Bake at a 350-degree oven for 1 hour to 1 1/2 hours or until meat is not red when sliced.","You can also make these on skewers if you wish to go through the process of spearing the meat with other veggies to grill. Freezes well."],"ingredient_names":["lamb leg","garlic","garlic","parsley","onion","black pepper","balsamic vinegar","olive oil","mint","salt"],"allergens":[],"diet_flags":[]},{"source_id":"53440","title":"Balchi di Pisca","category":"Seafood","country":"Aruba","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/qqwhw51780093126.jpg","youtube_url":null,"source_url":"https://www.visitaruba.com/aruba-recipes/balchi-di-pisca/","ingredients":[{"name":"Salt Cod","measure":"1"},{"name":"Potatoes","measure":"3 Medium"},{"name":"Tomato","measure":"1"},{"name":"Green Pepper","measure":"1/2"},{"name":"Onion","measure":"1 medium"},{"name":"Garlic","measure":"1 clove peeled sliced"},{"name":"Tobasco Sauce","measure":"1/2 tsp"},{"name":"Nutmeg","measure":"Dash"},{"name":"Salt","measure":"To taste"},{"name":"Pepper","measure":"To taste"},{"name":"Egg","measure":"1"}],"steps":["These delectable fish balls can also be made with salmon or fish fillets. Substitute one large can of salmon or one pound of any white fish for the cod.","Soak for twenty-four hours:","1 salted cod, or bakijow Discard the water.","Place cod in saucepan with fresh water to cover. Simmer gently until the fish flakes easily when tested with the tines of a fork. Strain, reserving a bit of the broth. De bone the cod and set it aside for later use. In a saucepan, bring to boil in water to cover: 3 medium potatoes, peeled and diced When the potatoes are tender, drain them well. Add the cod and mash the two ingredients thoroughly together.","Place in the container of an electric blender:","1 tomato, peeled and chopped","1/2 green pepper, chopped","1 medium onion, peeled and chopped","1 clove garlic, slivered","1/2 tsp. Tabasco sauce, or minced hot pepper","Dash of nutmeg","Salt and pepper to taste","Blend for a few seconds and pour the sauce over the mashed fish mixture. Combine these ingredients well and add 1 egg, beaten Mixture should be stiff enough to mold into balls about one and a half inches in diameter, If it's too dry, add the fish stock a tablespoon at a time. Fry the balls in hot, deep fat until golden brown."],"ingredient_names":["salt cod","potatoes","tomato","green pepper","onion","garlic","tobasco sauce","nutmeg","salt","pepper","egg"],"allergens":["eggs","fish"],"diet_flags":["pescatarian"]},{"source_id":"53443","title":"Satee","category":"Beef","country":"Aruba","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/dqxtlh1780153831.jpg","youtube_url":null,"source_url":"https://www.visitaruba.com/aruba-recipes/satee/","ingredients":[{"name":"Onion","measure":"1 chopped"},{"name":"Garlic","measure":"2 cloves"},{"name":"Lemons","measure":"Juice of 2"},{"name":"Sugar","measure":"2 tablespoons"},{"name":"Soy Sauce","measure":"1 cup"},{"name":"Salt","measure":"1 tsp"},{"name":"Ground Coriander","measure":"1 tsp"},{"name":"Oil","measure":"1 cup"},{"name":"Beef","measure":"4-5 pound"},{"name":"Oil","measure":"1 cup"},{"name":"Soy Sauce","measure":"2 tablespoons"}],"steps":["To make the marinade for the satee put in the container of an electric blender:","1 large onion, coarsely chopped 2 cloves of garlic","Juice of 2 lemons","2Tbs. of sugar 1 cup of soy sauce","1 tsp. salt 1 tsp. ground coriander for beef (or chicken) or 1 tsp. ground ginger for pork","1 cup of oil","Blend thoroughly and pour over:","5 lbs. of beef or pork tenderloin, cubed","DO NOT marinate overnight, but only for a few hours.","Place the meat on: 36 skewers","Blend well:","1 cup of oil","2 Tbs. Soy sauce","Pour into a large shallow dish.","To keep meat from becoming dry, roll each skewer in seasoned oil before frying.","Satee is also excellent when barbecued."],"ingredient_names":["onion","garlic","lemons","sugar","soy sauce","salt","ground coriander","oil","beef","oil","soy sauce"],"allergens":["gluten","soy"],"diet_flags":[]},{"source_id":"53444","title":"Tirolean Dumplings","category":"Pork","country":"Austria","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/jbw8m11780155348.jpg","youtube_url":null,"source_url":"https://www.austria.info/en-gb/recipes/tirolean-dumplings/","ingredients":[{"name":"Bread","measure":"200g"},{"name":"Milk","measure":"200ml"},{"name":"Smoked Ham","measure":"100g"},{"name":"Eggs","measure":"3"},{"name":"Shallots","measure":"2"},{"name":"Butter","measure":"Knob"},{"name":"Parsley","measure":"2 tablespoons"},{"name":"Flour","measure":"2 tablespoons"},{"name":"Salt","measure":"To taste"},{"name":"Pepper","measure":"To taste"},{"name":"Nutmeg","measure":"Pinch"},{"name":"Butter","measure":"Garnish"},{"name":"Parsley","measure":"Garnish"}],"steps":["Finely chop the shallots, and dice the smoked ham or sausage into small cubes. Heat some butter or clarified butter in a pan and sweat the onions in it until translucent. Add the meat and the parsley and fry together briefly before removing from the heat.","Place the bread in a bowl. Beat the milk with the eggs and season well with salt, pepper and nutmeg. Pour over the bread. Stir in the sausage and onion paste and mix in the flour. Mix together to form a relatively firm paste (adding more bread or flour if necessary) and season again according to taste. Smooth the surface of the dough out and leave to stand for approx. 30 minutes.","Heat up a good quantity of salted water in a large pan. Use the paste to form smaller dumplings (for use as a garnish in soups) or medium-sized dumplings, as required. Moisten the hands regularly with cold water during this stage so that the dumplings take on smooth forms.","Place in boiling water, bring back to the boil, turn down the heat, and simmer gently for 8-20 minutes, depending on the size.","Remove from the water, dry off well and serve up garnished with chopped parsley and melted butter (which has been taken on a nut-brown colour)."],"ingredient_names":["bread","milk","smoked ham","eggs","shallots","butter","parsley","flour","salt","pepper","nutmeg","butter","parsley"],"allergens":["dairy","eggs","gluten"],"diet_flags":[]},{"source_id":"53445","title":"Kaspressknödel - Cheese Dumplings","category":"Vegetarian","country":"Austria","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/x26z3y1780155760.jpg","youtube_url":null,"source_url":"https://www.austria.info/en-gb/recipes/cheese-dumplings/","ingredients":[{"name":"Bread","measure":"250g"},{"name":"Cheese","measure":"250g"},{"name":"Eggs","measure":"2"},{"name":"Salt","measure":"Pinch"},{"name":"Parsley","measure":"Pinch"},{"name":"Potatoes","measure":"3"},{"name":"Flour","measure":"100g"},{"name":"Milk","measure":"250ml"},{"name":"Onion","measure":"1 small"},{"name":"Butter","measure":"For frying"}],"steps":["Mix the cubed white bread with the milk, season with salt, and let the mixture rest for a while.","Now add the shredded potatoes, the grated cheese, eggs, and parsley.","Melt the butter and fry the cubed onions until golden brown in colour and put into the mixture.","Add the flour and gently knead the dough. Shape it into round dumplings, gently press them flat and fry them on both sides in butter until golden brown.","Serve in clear broth."],"ingredient_names":["bread","cheese","eggs","salt","parsley","potatoes","flour","milk","onion","butter"],"allergens":["dairy","eggs","gluten"],"diet_flags":["pescatarian","vegetarian"]},{"source_id":"53447","title":"Tafelspitz","category":"Beef","country":"Austria","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/svf3d01780298321.jpg","youtube_url":null,"source_url":"https://www.austria.info/en-gb/recipes/tafelspitz/","ingredients":[{"name":"Beef Brisket","measure":"1.5kg"},{"name":"Carrots","measure":"1  bunch"},{"name":"Celeriac","measure":"1"},{"name":"Parsnips","measure":"2"},{"name":"Parsley","measure":"Sprigs of fresh"},{"name":"Leek","measure":"1/2"},{"name":"Onion","measure":"1 large"},{"name":"Bay Leaf","measure":"2"},{"name":"Peppercorns","measure":"5"},{"name":"Salt","measure":"Pinch"}],"steps":["Slice the unpeeled onion in half widthways and fry off the cut surfaces without fat until fairly well browned.","Put around 3 litres of water into a large saucepan. Add the root vegetables, leek, halves of onion, bay leaves, and peppercorns and bring to a boil. Add the washed meat and bones and, depending on the type of meat, allow to cook until softened in gently simmering water, which will take around 2 1⁄2 – 3 hours. Add more water as required and skim off any foam from the surface.","Season well with salt, but only after a good 2 hours.","Once the meat has softened, remove it from the pan and keep it warm in some of the liquid from the soup. Season the remainder of the soup again with salt to taste, and strain it (optional). Serve with semolina dumplings or \"Frittaten\" (sliced pancakes - a traditional Austrian soup garnish) and freshly chopped chives as a starter. Afterwards, slice the boiled beef by cutting on the bias and arrange it on pre-heated plates, or serve in the hot soup in a decorative soup tureen.","Serve with roast potatoes, a bread and horseradish mix, green beans in a dill sauce, or creamed spinach and chive sauce. If the root vegetables are to be served at the same time, cook some of them separately to be served al dente."],"ingredient_names":["beef brisket","carrots","celeriac","parsnips","parsley","leek","onion","bay leaf","peppercorns","salt"],"allergens":[],"diet_flags":[]},{"source_id":"53449","title":"Kelem dolmasi","category":"Lamb","country":"Azerbaijan","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/7vdtqi1780160088.jpg","youtube_url":null,"source_url":"https://travelbystove.blogspot.com/2012/01/recipes-from-azerbaijani.html","ingredients":[{"name":"Lamb Mince","measure":"500g"},{"name":"Cabbage","measure":"1 large"},{"name":"Onion","measure":"8 oz"},{"name":"Salt","measure":"Pinch"},{"name":"Pepper","measure":"Pinch"},{"name":"Turmeric","measure":"1/2 tsp"},{"name":"Cinnamon","measure":"1/2 tsp"},{"name":"Cilantro","measure":"2 tablespoons"},{"name":"Dill","measure":"2 tablespoons"},{"name":"Rice","measure":"2 oz"},{"name":"Chickpeas","measure":"2 oz"},{"name":"Lamb Fat","measure":"3 oz"},{"name":"Tomato Puree","measure":"1 tablespoon"},{"name":"Water","measure":"3  tablespoons"}],"steps":["First boil the rice for eight minutes. Meanwhile, peel and finely chop the onion. Then chop the herbs.","The recipe didn't really say what to do with the chickpeas (also known of course as garbanzo beans), beyond soaking them overnight and rinsing them. I used canned chickpeas, since I've never actually seen them dried. I decided to chop/mash them slightly so they would better incorporate into the filling.","Chickpeas (or garbanzo beans) roughly chopped","Now mince the lamb (I used my mini food processor). Here's where I ran into another problem: what to do with the lamb fat this recipe calls for? Mince it? Melt it? Does lamb fat even melt? I decided to mince mine. Thankfully, my husband doesn't actually read this blog because he'd be horrified if he knew I put fat in the dolma on purpose.","Minced lamb and its good friend, minced fat. Ew.","The ingredients for the dolma stuffing include onion, cilantro, chickpeas and turmeric.","Anyway, now get your hands into all that slimy raw meat and mix in the onion, spices, chickpeas, rice, chopped herbs and fat. Add a little salt and pepper for good measure. In fact, based on my results I would say to err on the side of a little extra salt and pepper.","Mix well with your hands until the stuffing looks something like this.","Fill the biggest saucepan you own with salted water and bring it to a boil over high heat. Now pull the outer leaves off of the cabbage (save them) and drop the rest of it, whole, into the water. Let it boil for three or four minutes, turning it if the water level isn't quite high enough to completely cover it.","The reason you are doing this is because it's difficult to get whole cabbage leaves off of an American cabbage. The cabbages you typically buy in our supermarkets come in very tight round balls, and because the leaves are crispy they will snap and crack when you try to pull them off in an un-blanched state. Blanching them for a few minutes makes it so they will come right off without tearing.","Now carefully take the cabbage out of the water (but keep the water boiling) and let it cool for a minute or two so you don't burn your fingers. Carefully pull the leaves off the cabbage, cutting them at the base if you have to do so to loosen them. Try to get them off in one piece. If the inner leaves are still crispy, return the cabbage to the boiling water for another three or four minutes. Repeat until all of the useable leaves are free.","Blanched cabbage leaves","Now put the leaves on a cutting board and cut out the tough stalks (save them). Cut the largest leaves in half.","Remove the tough inner stalk and set aside. Cut larger leaves in two.","Put a heaping tablespoon of the filling in the middle of each leaf, making a short cylinder shape. Fold the ends over the filling, then roll tightly (as if you are making a tiny burrito).","This is not much of a cylinder, but you get the idea.","Fold the edges over ...","Then roll, as if you were making a really small burrito.","Your finished dolma should look kind of like this, only without the hole in the middle.","Put all of the discarded cabbage leaves, stalks etc. into the bottom of a stockpot. I know, this seems a little strange. What you're basically going to be doing is steaming the dolma, with the discarded cabbage pieces forming the base of your steamer. Carefully place the dolma on the bed of cabbage leaves.","These dolma are resting on top of discarded cabbage leaves.","Add water to the stockpot up to about the top of the discarded leaves. Don't cover the dolma.","Now here's where you have to get a bit creative. The dolma needs to be weighted down so it doesn't unwrap during cooking. I used a metal pie pan, and then I put my mortar on top of it. You could also use a dessert plate with something heavy on top of it, but it would need to be an oven-safe one.","The dolma need to be weighted down during cooking so they don't unwrap. Just improvise.","Bring the water to a boil, then simmer for 25 minutes.You might have to use your ears to figure out if the water is actually boiling; I personally couldn't see what was in my pot after I weighted it down.","Meanwhile, make a simple tomato sauce out of the tomato paste and water. Heat it up for a few minutes over a medium flame. After the dolma have been cooking for 25 minutes, pour the sauce over them and cook for another five minutes."],"ingredient_names":["lamb mince","cabbage","onion","salt","pepper","turmeric","cinnamon","cilantro","dill","rice","chickpeas","lamb fat","tomato puree","water"],"allergens":[],"diet_flags":[]},{"source_id":"53451","title":"Bangladeshi fish curry with daikon","category":"Seafood","country":"Bangladesh","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/r7mcjm1780261264.jpg","youtube_url":null,"source_url":"https://www.greatbritishchefs.com/recipes/bangladesh-fish-curry-recipe","ingredients":[{"name":"White Fish","measure":"450g"},{"name":"Daikon Radish","measure":"450g"},{"name":"Vegetable Oil","measure":"4 tablespoons"},{"name":"Garlic","measure":"4 cloves"},{"name":"Onion","measure":"1 medium"},{"name":"Salt","measure":"2 tsp"},{"name":"Ground Turmeric","measure":"1 tsp"},{"name":"Ground Coriander","measure":"2 tsp"},{"name":"Chilli Powder","measure":"2 tsp"},{"name":"Green Chilli","measure":"2"},{"name":"Coriander Leaves","measure":"Handful"},{"name":"Lime","measure":"1"}],"steps":["If you are using rohu fish it will usually be frozen. Soak it in cold water for 30-45 minutes to defrost and while still a little firm, descale and cut each steak into quarters and wash in cold saltwater a few times. Drain and set aside. If using an alternative such as cod, cut into 2 ½ inch chunks then rinse, drain and set aside","Top and tail the daikon and peel using a potato peeler. Cut in half widthways then cut each half down the middle, lengthways. Now slice into 2cm-thick half-moon pieces. Rinse and set aside","Place a large, shallow saucepan over a medium heat and add the oil. When the oil is hot add the crushed garlic and stir for a minute until pale golden","Add the onion paste and salt and cook for 3-5 minutes, until the onion softens and becomes translucent, stirring occasionally","Pour in 200ml of water then cover and cook for 10 minutes, stirring once or twice","After 10 minutes add the ground spices and stir for a couple of minutes so that the spices cook through. Cover and cook for 5 minutes over a low heat then stir in the daikon. After a minute or so add 200ml of water. Cover and cook for 10 minutes on a medium heat","Add the fish pieces to the pan and mix thoroughly so that the fish is coated in the spices. Gently shake the pan and cover and cook for 5 minutes on medium heat. It is very important not to stir the pot after this stage","Meanwhile, boil some water. After the 5 minutes are over carefully pour 500ml hot water into the pan. When doing this pour into the sides of the pan so that you don’t pour boiling water directly onto the fish","Give the pan a gentle shake then cover and simmer over high heat for 15 minutes. Add the chopped coriander and chillies and continue cooking for another 5 minutes then turn off the heat. Serve immediately with rice and the lime wedges"],"ingredient_names":["white fish","daikon radish","vegetable oil","garlic","onion","salt","ground turmeric","ground coriander","chilli powder","green chilli","coriander leaves","lime"],"allergens":["fish"],"diet_flags":["pescatarian"]},{"source_id":"53453","title":"Bengali Chicken Curry with Potatoes","category":"Chicken","country":"Bangladesh","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/9ya6o71780262651.jpg","youtube_url":null,"source_url":"https://www.allrecipes.com/recipe/215055/bengali-chicken-curry-with-potatoes/","ingredients":[{"name":"Olive Oil","measure":"2 tablespoons"},{"name":"Onion","measure":"2 diced"},{"name":"Ginger Garlic Paste","measure":"1 tablespoon"},{"name":"Tomato","measure":"2 diced"},{"name":"Cayenne Pepper","measure":"1 tsp"},{"name":"Curry Powder","measure":"1 tsp"},{"name":"Garam Masala","measure":"1 tsp"},{"name":"Ground Turmeric","measure":"1 tsp"},{"name":"Ground Cumin","measure":"1 tsp"},{"name":"Chicken Breast","measure":"4"},{"name":"Red Potatoes","measure":"2 large"},{"name":"Cilantro","measure":"1/2 cup"}],"steps":["Heat the olive oil in a large skillet over medium-high heat.","Cook and stir the onions in the hot oil until translucent, about 5 minutes.","Add the ginger-garlic paste and continue cooking another 5 minutes.","Reduce heat to medium; stir the tomatoes into the mixture and cook until the tomatoes are pulpy, 5 to 10 minutes.","Season with the cayenne pepper, curry powder, garam masala, turmeric, and cumin; cook and stir another 5 minutes.","Add the chicken and potatoes to the mixture in the skillet; simmer, stirring occasionally, until the potatoes are tender and the chicken is no longer pink in the center, about 20 minutes.","Sprinkle the cilantro over the mixture and continue simmering another 10 minutes. Serve hot."],"ingredient_names":["olive oil","onion","ginger garlic paste","tomato","cayenne pepper","curry powder","garam masala","ground turmeric","ground cumin","chicken breast","red potatoes","cilantro"],"allergens":[],"diet_flags":[]},{"source_id":"53455","title":"Chicken Liver Pate Recipe","category":"Chicken","country":"Barbados","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/hob03q1780264260.jpg","youtube_url":null,"source_url":"https://www.totallybarbados.com/articles/barbados-recipes/chicken-liver-pate/","ingredients":[{"name":"Chicken Liver","measure":"1lb"},{"name":"Bacon","measure":"1/2 lb"},{"name":"Garlic","measure":"1 clove"},{"name":"Onion","measure":"1 large"},{"name":"Ground Mustard","measure":"2 tsp"},{"name":"Salt","measure":"To taste"},{"name":"Pepper","measure":"To taste"},{"name":"Milk","measure":"Splash"},{"name":"Sherry","measure":"1 tablespoon"}],"steps":["Clean livers of sinews and gall.","Put into a fireproof casserole with all other ingredients roughly chopped.","Season and cover with milk.","Put the lid on the casserole and cook in a slow oven (300ºF) for 2 hours.","Liquidize in a blender.","Adjust seasoning.","Add sherry or brandy.","Put in a dish and cover with melted butte"],"ingredient_names":["chicken liver","bacon","garlic","onion","ground mustard","salt","pepper","milk","sherry"],"allergens":["dairy"],"diet_flags":[]},{"source_id":"53457","title":"Barbados Pepperpot","category":"Beef","country":"Barbados","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/5tf8j11782236249.jpg","youtube_url":"https://www.youtube.com/watch?v=9L2nQEBRPdg","source_url":"https://www.totallybarbados.com/articles/barbados-recipes/barbados-pepperpot/","ingredients":[{"name":"Pigs Trotters","measure":"2"},{"name":"Oxtail","measure":"2 Lbs"},{"name":"Lime juice","measure":"Splash"},{"name":"Garlic","measure":"3 cloves"},{"name":"Scotch Bonnet","measure":"2"},{"name":"Onion","measure":"1 large"},{"name":"Cinnamon Stick","measure":"1"},{"name":"Cloves","measure":"2"},{"name":"Sugar","measure":"Pinch"},{"name":"Salt","measure":"Pinch"},{"name":"Basil","measure":"Sprinkling"},{"name":"Thyme","measure":"Sprinkling"},{"name":"Beef","measure":"2 Lbs"}],"steps":["Wash the stewing steak and place it in the mixing bowl with the lemon or lime juice.","Set that to one side; while you slice the garlic into tiny slices, slice the onion. Chop the basil and thyme.","Now you need to be very careful when you slice the scotch bonnet peppers; you want these in fine pieces, which you can either do with a long knife trying not to touch the pepper, or you can wear rubber gloves to cut it up. Wash your hands straight afterward and do not touch your eyes; these peppers really burn your hands and eyes if they make contact with the skin!","Now rinse the lime or lemon juice off the stewing steak. And cut the meat into cubes.","Also, chop the pig’s trotters and the oxtail into cubes.","Fill the large saucepan with water and bring to a boil.","Add the pig’s trotters.","When the pig’s trotters have boiled, drain the excess water, and now add the stewing steak and cover with fresh hot water.","Now add your chopped garlic, onion, and peppers.","Now add the cinnamon stick, cloves, basil, and thyme and a pinch of salt and sugar to taste.","Now simmer until the meat is tender. The flavor of this dish comes out over a few days and therefore gets tastier each time you reheat it; make sure you always reheat the entire pot to boiling point."],"ingredient_names":["pigs trotters","oxtail","lime juice","garlic","scotch bonnet","onion","cinnamon stick","cloves","sugar","salt","basil","thyme","beef"],"allergens":[],"diet_flags":[]},{"source_id":"53459","title":"Chicken and Potato Roti","category":"Chicken","country":"Barbados","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/mp9z0i1782238092.jpg","youtube_url":"https://www.youtube.com/watch?v=2ehdHb1rcAQ","source_url":"https://www.totallybarbados.com/articles/barbados-recipes/chicken-potato-roti-recipe/","ingredients":[{"name":"Flour","measure":"1 lb"},{"name":"Shortening","measure":"3  tablespoons"},{"name":"Salt","measure":"Pinch"},{"name":"Water","measure":"Splash"},{"name":"Chicken Breast","measure":"6"},{"name":"Parsley","measure":"Pinch"},{"name":"Thyme","measure":"Pinch"},{"name":"Jerk","measure":"Pinch"},{"name":"Salt","measure":"Pinch"},{"name":"Sugar","measure":"Pinch"},{"name":"Black Pepper","measure":"Pinch"},{"name":"Onion","measure":"2 large"},{"name":"Garlic","measure":"4 cloves"},{"name":"Scotch Bonnet","measure":"1"},{"name":"Potatoes","measure":"1/2 lb"}],"steps":["Add a pint of chicken stock to the simmer and put three tablespoons of sugar into a large saucepan on high; cook until the sugar caramelizes, then add the cubed chicken breasts and stir until the chicken browns.","Add chopped onions, garlic, parsley, thyme, jerk seasoning, salt, and the whole scotch bonnet pepper – do not cut up the pepper! Reduce the heat to low and let this simmer for 25 minutes.","In a large mixing bowl, sift the flour, and add a pinch of salt to taste.","Now add the first tablespoon of shortening, and with your fingers, rub the flour into the shortening until it forms a breadcrumb-like consistency.","Then add the second tablespoon of shortening and rub against the flour until it looks like breadcrumbs.","Now add the third tablespoon of shortening and repeat the process.","You should by now have used all the flour. Your bowl should be all breadcrumb-like; if you still have fresh flour, use another tablespoon of shortening until your fresh flour is all used up.","Add a small amount of water and mix with a butter knife; keep adding small amounts until your mixture forms a soft dough.","Now dust your surface with flour and roll out your pastry; you want to roll wafer-thin rounds – this mixture should make at least 12 roti skins.","Cover with a tea towel while returning to the pot.","Now peel the potatoes and cube them into small bite-size pieces.","After 25 minutes of simmering, add 1/2 pint of water and the potatoes to the pool.","Now cover and cook for 30 minutes on low heat.","Turn a flat baking tray upside down, lightly cover with foil, and place on the stovetop on high; cook each roti skin for 1 minute on each side until brown but not crisp.","Now pile up your cooked roti skins, remove the pot after 30 minutes, and remove the whole scotch bonnet.","Take the entire pot to the table with a pile of plates; each person assumes the roti skin, lays it flat on the scale, spoons some filling into the middle of the roti skin, and folds around the filling eats enjoy."],"ingredient_names":["flour","shortening","salt","water","chicken breast","parsley","thyme","jerk","salt","sugar","black pepper","onion","garlic","scotch bonnet","potatoes"],"allergens":["gluten"],"diet_flags":[]},{"source_id":"53461","title":"Macaroni Pie","category":"Pasta","country":"Barbados","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/kpiu4t1782242131.jpg","youtube_url":"https://www.youtube.com/watch?v=38dxvOH7Z-s","source_url":"https://www.totallybarbados.com/articles/barbados-recipes/macaroni-pie-recipe/","ingredients":[{"name":"Macaroni","measure":"250g"},{"name":"Butter","measure":"1 tablespoon"},{"name":"Cheddar Cheese","measure":"375g"},{"name":"Egg","measure":"1"},{"name":"Milk","measure":"250ml"},{"name":"Ground Onion","measure":"2 tsp"},{"name":"Mustard","measure":"1 tsp"},{"name":"Pepper","measure":"1 tsp"},{"name":"Salt","measure":"1 tsp"},{"name":"Cayenne Pepper","measure":"1/2 tsp"},{"name":"Breadcrumbs","measure":"2 tablespoons"},{"name":"Butter","measure":"2 tsp"},{"name":"Cheddar Cheese","measure":"2 tablespoons"}],"steps":["Bring water to a boil and add the broken-up macaroni, elbows, and salt. Cook uncovered until tender but not overcooked (about 8 minutes).","Preheat a moderately hot oven to 350F, 180C, or Gas Mark 4.","Drain the macaroni thoroughly, put it back into the same hot saucepan cooked in, and mix in the butter.","Grate the cheese and mix it with the macaroni while it is still warm.","Whisk the egg until fluffy, and add the milk, onion powder, white pepper, salt, pepper sauce, and mustard. Pour in with the macaroni and mix.","Place in a greased ovenproof casserole dish. Top with butter, some grated cheese, and fine breadcrumbs. Bake in the center of the oven for about 30-45 minutes, depending on the dish’s depth."],"ingredient_names":["macaroni","butter","cheddar cheese","egg","milk","ground onion","mustard","pepper","salt","cayenne pepper","breadcrumbs","butter","cheddar cheese"],"allergens":["dairy","eggs","gluten"],"diet_flags":["pescatarian","vegetarian"]},{"source_id":"53463","title":"Belgian Meatballs in Liège Syrup Sauce","category":"Beef","country":"Belgium","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/gjjlzc1782496055.jpg","youtube_url":null,"source_url":"https://junedarville.com/belgian-meatballs.html","ingredients":[{"name":"Minced Beef","measure":"300g"},{"name":"Minced Pork","measure":"300g"},{"name":"Onion","measure":"1 chopped"},{"name":"Garlic","measure":"1 clove peeled crushed"},{"name":"Egg","measure":"1"},{"name":"Breadcrumbs","measure":"4 tablespoons"},{"name":"Mustard","measure":"1 tablespoon"},{"name":"Parsley","measure":"1 tablespoon"},{"name":"Salt","measure":"Pinch"},{"name":"Pepper","measure":"Pinch"},{"name":"Oil","measure":"Splash"},{"name":"Onion","measure":"2 sliced"},{"name":"Butter","measure":"1 tablespoon"},{"name":"Brown Sugar","measure":"1 tablespoon"},{"name":"White Wine Vinegar","measure":"2 tablespoons"},{"name":"Mustard","measure":"2 tablespoons"},{"name":"Sirop De Liège","measure":"4 tablespoons"},{"name":"Beef Stock","measure":"1 cup"},{"name":"Bay Leaf","measure":"1"},{"name":"Beer","measure":"Splash"}],"steps":["Make the meatballs","Mix the minced meat with the onion, garlic, egg, breadcrumbs, mustard, parsley, salt, and pepper.","Shape into meatballs. Traditionally, Liège restaurants serve **one or two very large meatballs**, depending on appetite.","For weeknight cooking, I keep mine smaller so they brown faster and cook through quickly.","Brown the meatballs","Heat butter or oil in a large pan.","Brown the meatballs on all sides until they have a nice crust.","Remove them from the pan and set aside.","Start the sauce","In the same pan, melt 1 tbsp butter.","Add the sliced onions and cook until soft and lightly caramelised.","Sprinkle in the brown sugar and let it melt into the onions.","Deglaze and add the stock","Add the vinegar and scrape up all the browned bits from the pan.","Stir in the mustard and Liège syrup.","Pour in the beef stock (and beer if using).","Add the bay leaf.","Stir until the syrup dissolves and the sauce looks glossy.","Simmer and adjust","Return the meatballs to the pan.","Cover and simmer gently for 25–30 minutes (less if your meatballs are small, longer if they’re traditional large boulets). Stir occasionally and let the sauce thicken naturally.","Taste and adjust: more syrup for sweetness, more vinegar for tang, more mustard for depth. The sauce should be sweet‑sour, rich, and velvety.","Serve with fries or mashed potatoes."],"ingredient_names":["minced beef","minced pork","onion","garlic","egg","breadcrumbs","mustard","parsley","salt","pepper","oil","onion","butter","brown sugar","white wine vinegar","mustard","sirop de liège","beef stock","bay leaf","beer"],"allergens":["dairy","eggs","gluten"],"diet_flags":[]},{"source_id":"53464","title":"Flemish Hutsepot","category":"Pork","country":"Belgium","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/2lywl71782496853.jpg","youtube_url":null,"source_url":"https://junedarville.com/hutsepot.html","ingredients":[{"name":"Floury Potatoes","measure":"600g"},{"name":"Carrots","measure":"200g"},{"name":"Turnips","measure":"200g"},{"name":"Leek","measure":"250g"},{"name":"Sausages","measure":"4"},{"name":"Onion","measure":"1 small"},{"name":"Garlic","measure":"3 cloves"},{"name":"Bay Leaf","measure":"2"},{"name":"Thyme","measure":"4 sprigs"},{"name":"Chicken Stock","measure":"600ml"},{"name":"Mustard","measure":"1 tablespoon"},{"name":"Unsalted Butter","measure":"1 tablespoon"},{"name":"Salt","measure":"Pinch"},{"name":"Pepper","measure":"Pinch"}],"steps":["Peel and chop the onion and garlic. Add both to a large pan with the butter and place it over medium heat.","Let the onion and garlic sweat for 5 minutes. Then add the chopped potatoes, bay leaves and thyme and stir well. Cook for another 5 minutes.","In the meantime peel and slice the carrots. Peel the turnip. Dice it into bite-size pieces. Slice the leek in half lengthwise. Rinse it well to remove any sand. Add the vegetables to the potatoes and onion. Also add the mustard and chicken stock and season with pepper and salt.","Stir all the ingredients well and cover the pan with a lid. Cook the hutsepot for about 20 to 25 minutes or until all the vegetables and potatoes are tender. Stir regularly. Add extra water if necessary. In the meantime pan fry the sausages in a little oil or butter until golden brown and cooked through. Keep warm.","Once the potatoes start to fall apart, stir and turn it all into a mushy and chunky vegetable stew. Check the seasoning and add extra pepper, salt or mustard to taste.","Scoop the hutsepot onto deep plates and top with the sausage. Serve hot with an extra dollop of mustard if you like."],"ingredient_names":["floury potatoes","carrots","turnips","leek","sausages","onion","garlic","bay leaf","thyme","chicken stock","mustard","unsalted butter","salt","pepper"],"allergens":["dairy"],"diet_flags":[]},{"source_id":"53466","title":"Belgian Waterzooi Chicken","category":"Chicken","country":"Belgium","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/nmxec11782498644.jpg","youtube_url":null,"source_url":"https://junedarville.com/waterzooi.html","ingredients":[{"name":"Chicken Legs","measure":"1"},{"name":"Chicken Breast","measure":"1"},{"name":"Water","measure":"3 Cups"},{"name":"Carrots","measure":"1 small"},{"name":"Leek","measure":"2"},{"name":"Celery","measure":"1"},{"name":"Potatoes","measure":"100g"},{"name":"Garlic","measure":"2 cloves"},{"name":"Rosemary","measure":"1 Sprig"},{"name":"Cream","measure":"1 1/2 cups"},{"name":"Bay Leaf","measure":"2"},{"name":"Unsalted Butter","measure":"1 tablespoon"},{"name":"Egg Yolks","measure":"1"},{"name":"Pepper","measure":"Pinch"},{"name":"Salt","measure":"Pinch"}],"steps":["Put the chicken, water and one garlic clove in a large saucepan. Place it over medium-high heat until boiling. Then turn the heat low, cover the pan and simmer the chicken for 10 minutes. Remove the chicken leg and breast. Keep the fresh chicken stock for later.","Let the chicken cool. Then dice the chicken breast up. Pick the meat off the leg. Discard any bones and skin. Slice the leek, celery and carrot finely (julienne). Add the butter, rosemary and bay leaves to a large pan and place it over medium heat until melted.","Then add the sliced vegetables. Season with pepper and salt.","Stir and cook the vegetables for 3 minutes. Then add the shredded and diced chicken.","Cover the pan and cook the chicken and vegetables for 5 minutes. Then add the cream and ½ cup (120 ml) of the fresh chicken stock.","Look at this delicious waterzooi recipe! Do try out my chunky chicken stew with fresh leeks, celery, carrots and lots of cream... This is Belgian comfort food!","Cover the pan and cook the stew for 20 minutes until the potatoes are tender. Add the egg yolk and 2 tablespoons of the warm cream from the pan to a cup. Whisk and add it back to the pan to thicken the sauce.","Stir all the ingredients and then turn the heat very low. Check the seasoning and add extra pepper or salt to taste. Remove the rosemary and bay leaves. Divide the stew over deep plates and drizzle with the remaining cream sauce. Serve hot."],"ingredient_names":["chicken legs","chicken breast","water","carrots","leek","celery","potatoes","garlic","rosemary","cream","bay leaf","unsalted butter","egg yolks","pepper","salt"],"allergens":["dairy","eggs"],"diet_flags":[]},{"source_id":"53467","title":"Liegeoise Salad","category":"Vegetarian","country":"Belgium","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/ji3mho1782499823.jpg","youtube_url":null,"source_url":"https://junedarville.com/salade-liegeoise.html","ingredients":[{"name":"Potatoes","measure":"350g"},{"name":"Green Beans","measure":"200g"},{"name":"Eggs","measure":"2"},{"name":"Bacon","measure":"125g"},{"name":"Onion","measure":"2 tbs chopped"},{"name":"Olive Oil","measure":"3  tablespoons"},{"name":"White Wine Vinegar","measure":"2 tablespoons"},{"name":"Mustard","measure":"1 tsp"},{"name":"Parsley","measure":"2 tablespoons"},{"name":"Pepper","measure":"Pinch"},{"name":"Salt","measure":"Pinch"}],"steps":["Scrub the potatoes well but don't peel them. Cut them into bite-size pieces. Add them to a large pan water and a pinch of salt. Bring it to a good boil. Cook the potatoes until tender and then remove them using a slotted spoon. Keep the potatoes at room temperature.","Trim and clean the green beans. Add them to the pan of hot water you boiled the potatoes in. Cook the green beans until nearly tender (keep them crunchy). Strain and refresh them immediately under cold running tap water to stop the cooking process.","Add the bacon to a large non-stick pan and place it over medium heat. Cook the bacon for a couple of minutes until cooked through. Then take the pan off the heat and let the bacon cool down a little.","Combine the olive oil, vinegar and mustard. Transfer the cooked potatoes, green beans, bacon, chopped onion, parsley and vinaigrette. Season with pepper and salt.","Stir well. Check the seasoning and add extra vinegar, pepper or salt to taste. Transfer the salad to a large serving bowl or 2 deep plates and garnish with the boiled eggs. Serve lukewarm."],"ingredient_names":["potatoes","green beans","eggs","bacon","onion","olive oil","white wine vinegar","mustard","parsley","pepper","salt"],"allergens":["eggs"],"diet_flags":[]},{"source_id":"53468","title":"Belgian Stoemp","category":"Pork","country":"Belgium","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/byolko1782500400.jpg","youtube_url":null,"source_url":"https://junedarville.com/stoemp.html#wprm-recipe-container-131911","ingredients":[{"name":"Sausages","measure":"2"},{"name":"Potatoes","measure":"450g"},{"name":"Savoy Cabbage","measure":"200g"},{"name":"Garlic","measure":"3 cloves"},{"name":"Parsley","measure":"1 Handfull"},{"name":"Onion","measure":"1 small finely diced"},{"name":"Unsalted Butter","measure":"3  tablespoons"},{"name":"Beer","measure":"1 cup"},{"name":"Whole Milk","measure":"60ml"},{"name":"Nutmeg","measure":"Pinch"},{"name":"Pepper","measure":"Pinch"},{"name":"Salt","measure":"Pinch"}],"steps":["Add the chopped potatoes and garlic to a high pan and fill it with tap water until the potatoes are fully submerged.","Add some salt. Then place the pan over high heat and bring the potatoes to a boil. Cook them until tender. In the meantime rinse and drain the savoy cabbage. Slice it up finely.","Add a tablespoon of butter to a large non-stick pan. Place it over medium-high heat. Once melted, add the savoy cabbage. Season with a pinch of pepper and salt.","Stir fry the cabbage for 15 to 20 minutes or until the cabbage is soft and tender. Then turn the heat off and take the cabbage off the heat. In the meantime, pan fry the sausages (or sliced bacon if you are using both) in a non-stick pan in a tablespoon of butter or oil until golden brown and cooked through.","Transfer the sausages (and bacon) to a plate and cover with a lid or tinfoil to keep the meat warm. In the same greasy pan, add the sliced onion and extra butter and cook it gently over medium heat for 10 minutes until softened. (I often add diced bacon as well, if I only serve the stoemp with sausages.)","Then add the beer and turn the heat up. Let the beer reduce until you get a nice beer and onion sauce (you can add a little flour or sauce thickener if you like). Add the pan fried meat back to the pan and cover to keep warm.","Drain the cooked potatoes and garlic, add them back to the pan you cooked them in together with the pan fried cabbage and chopped parsley. Sprinkle with some pepper, salt and nutmeg. Also add the milk and the rest of the unsalted butter.","Mash the potatoes, parsley and cabbage up. Add extra butter or milk if necessary. Also check the seasoning and add extra pepper, nutmeg or salt to taste if necessary. Scoop the cabbage mash onto plates and top with the pan fried sausages (and bacon). Drizzle with the beer and onion sauce. Serve hot."],"ingredient_names":["sausages","potatoes","savoy cabbage","garlic","parsley","onion","unsalted butter","beer","whole milk","nutmeg","pepper","salt"],"allergens":["dairy","gluten"],"diet_flags":[]},{"source_id":"53469","title":"Beef pumpkin Stew","category":"Beef","country":"Botswana","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/k07k271782502861.jpg","youtube_url":null,"source_url":"https://www.honeyandbirch.com/pumpkin-beef-stew-recipe/#recipe","ingredients":[{"name":"Beef","measure":"3 Lbs"},{"name":"All purpose flour","measure":"1/2 cup"},{"name":"Butter","measure":"3  tablespoons"},{"name":"Onion","measure":"1 cup"},{"name":"Garlic","measure":"1 clove peeled crushed"},{"name":"Beef Stock","measure":"4 cups"},{"name":"Pumpkin Puree","measure":"3 Cups"},{"name":"Worcestershire Sauce","measure":"1 tablespoon"},{"name":"Kosher Salt","measure":"1 tablespoon"},{"name":"Black Pepper","measure":"1 teaspoon"},{"name":"Potatoes","measure":"3 Lbs"},{"name":"Carrots","measure":"1 lb"},{"name":"Thyme","measure":"4 sprigs"}],"steps":["Cut the beef into 1-inch chunks. Dredge the beef in the flour until all of the beef sides are covered.","In a large soup pot, melt the butter over medium high-heat. In small quantities, brown the beef on all sides, removing the browned beef and setting it aside in a large bowl as you go. When the beef is browned, add the onion and the garlic to the pot. Sauté the onion and garlic for one minute, scraping the bottom of the pot as you stir.","Return the browned beef to the pot and add the beef stock, pumpkin puree, Worcestershire sauce, salt, and pepper. Stir well and bring to a boil. Once the liquid is boiling, reduce heat to medium-low and simmer for 3 hours, stirring occasionally.","Add the potatoes, carrots and thyme sprigs to the pot and increase heat to medium. Cook for an additional 30 minutes. Salt to taste and serve."],"ingredient_names":["beef","all purpose flour","butter","onion","garlic","beef stock","pumpkin puree","worcestershire sauce","kosher salt","black pepper","potatoes","carrots","thyme"],"allergens":["dairy","fish","gluten"],"diet_flags":[]},{"source_id":"53470","title":"Seswaa","category":"Beef","country":"Botswana","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/p7eid81782503889.jpg","youtube_url":null,"source_url":"https://www.myburntorange.com/how-to-make-seswaa/","ingredients":[{"name":"Beef","measure":"1 kg"},{"name":"Onion","measure":"1"},{"name":"Bay Leaf","measure":"3"},{"name":"Salt","measure":"To taste"},{"name":"Black Pepper","measure":"Sprinkling"},{"name":"Water","measure":"1 Litre"}],"steps":["Pre heat the oven to 160 degrees Celsius. Cut the meat into large chunks then brown in a dish suitable for slow cooking in the oven such as a cast iron casserole dish.","Add the whole peeled onion, salt, cracked black pepper, water and bay leaves. Bring to the boil then cover and place into the oven for 4 hours.","After 4 hours, remove from oven and place onto the stove burner in order to cook off most of the remaining liquid. Use a wooden spoon to pound or mash up the meat, the meat should fall apart quite easily. and will appear shredded. You may brown the meat further if desired.","Check seasoning then serve with polenta or the more traditional thick cornmeal porridge known as pap or sadza, and a side of green vegetables."],"ingredient_names":["beef","onion","bay leaf","salt","black pepper","water"],"allergens":[],"diet_flags":[]},{"source_id":"53478","title":"Grilled corn with garlic mayo & grated cheese","category":"Vegetarian","country":"Brazil","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/k1if4d1782589892.jpg","youtube_url":null,"source_url":"https://www.bbcgoodfood.com/recipes/grilled-corn-garlic-mayo-grated-cheese","ingredients":[{"name":"Corn On The Cob","measure":"6"},{"name":"Garlic","measure":"2 cloves minced"},{"name":"Mayonnaise","measure":"6 tablespoons"},{"name":"Parmesan","measure":"4 tablespoons"},{"name":"Coriander","measure":"2 tablespoons"},{"name":"Lime","measure":"1"}],"steps":["Boil the corn cobs for 5 mins.","Leave in the water until you’re ready to grill them.","Mix the garlic and mayonnaise in a small bowl.","Just before barbecuing, remove the cobs from the pan, pat dry and rub the mayonnaise into each one.","Season the cobs and grill them until marks appear, about 5 mins.","Remove and scatter over the Parmesan and coriander.","Squeeze lime over to serve."],"ingredient_names":["corn on the cob","garlic","mayonnaise","parmesan","coriander","lime"],"allergens":["dairy","eggs"],"diet_flags":["pescatarian","vegetarian"]},{"source_id":"53480","title":"Creamy Aji green sauce","category":"Vegetarian","country":"Brazil","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/81j8iu1782590903.jpg","youtube_url":null,"source_url":"https://www.bbcgoodfood.com/recipes/creamy-aji-green-sauce","ingredients":[{"name":"Coriander","measure":"Bunch"},{"name":"Jalapeno","measure":"2"},{"name":"Spring Onions","measure":"2"},{"name":"Garlic","measure":"1 clove"},{"name":"White Wine Vinegar","measure":"1 tablespoon"},{"name":"Lime","measure":"Juice of 1"},{"name":"Cumin","measure":"Pinch"},{"name":"Mayonnaise","measure":"4 tablespoons"}],"steps":["Put all the ingredients in a blender or food processor and mix into a sauce. Add seasoning, then pour into a serving bowl."],"ingredient_names":["coriander","jalapeno","spring onions","garlic","white wine vinegar","lime","cumin","mayonnaise"],"allergens":["eggs"],"diet_flags":["pescatarian","vegetarian"]},{"source_id":"53481","title":"Bahia-style Moqueca prawn stew","category":"Seafood","country":"Brazil","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/e2kcut1782591669.jpg","youtube_url":null,"source_url":"https://www.bbcgoodfood.com/recipes/bahia-style-moqueca-prawn-stew","ingredients":[{"name":"Raw King Prawns","measure":"450g"},{"name":"Lime juice","measure":"75 ml"},{"name":"Garlic","measure":"3 cloves Chopped"},{"name":"Coconut Oil","measure":"3  tablespoons"},{"name":"Spring Onions","measure":"4 Chopped"},{"name":"Onion","measure":"1"},{"name":"Red Pepper","measure":"1 chopped"},{"name":"Chilli Flakes","measure":"1 tsp"},{"name":"Paprika","measure":"2 tsp"},{"name":"Plum Tomatoes","measure":"3 chopped"},{"name":"Coconut Milk","measure":"400ml"},{"name":"Coriander","measure":"2 tbs chopped"},{"name":"Rice","measure":"To serve"}],"steps":["Place the prawns in a bowl with 2 tbsp of the lime juice, 1 tsp of salt and 1 tbsp of the chopped garlic. Chill for 1 hr.","Heat the coconut oil in a large saucepan. Add the spring onion and onion and fry for 5 mins, then add the red pepper, chilli flakes, paprika and remaining garlic.","Pour in the tomatoes, coconut milk and a little salt. Bring to a simmer and let reduce for 10 mins. Add the prawns, all the marinade and remaining lime juice. Gently simmer until the prawns turn white, about 3 mins. Serve with the fresh coriander and rice."],"ingredient_names":["raw king prawns","lime juice","garlic","coconut oil","spring onions","onion","red pepper","chilli flakes","paprika","plum tomatoes","coconut milk","coriander","rice"],"allergens":["shellfish"],"diet_flags":["pescatarian"]},{"source_id":"53482","title":"Black bean & meat stew - feijoada","category":"Beef","country":"Brazil","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/xrxz7h1782592711.jpg","youtube_url":null,"source_url":"https://www.bbcgoodfood.com/recipes/black-bean-meat-stew-feijoada","ingredients":[{"name":"Black Beans","measure":"250g"},{"name":"Bacon","measure":"100g"},{"name":"Pork Back Ribs","measure":"500g"},{"name":"Chorizo","measure":"3"},{"name":"Pork Shoulder","measure":"500g"},{"name":"Onion","measure":"3 chopped"},{"name":"Garlic","measure":"4 Cloves Chopped"},{"name":"Chilli Flakes","measure":"Pinch"},{"name":"Oil","measure":"Drizzle"},{"name":"Bay Leaf","measure":"2"}],"steps":["Heat a large heavy-based saucepan with a fitted lid, add the bacon and fry until crisp. Remove and keep the oil in the pan. In batches sear the ribs, sausages and pork shoulder. Season each batch with salt and pepper.","Remove the meat and set aside. Add the onion, garlic and chilli to the pan. Pour in a little olive oil if it needs more. Season with salt and pepper and fry for 8 mins or until soft.","Add the meat, bay leaves, white wine vinegar and drained beans. Cover with just enough water to cover, about 650ml. Bring to a boil and reduce the heat to a low simmer. Cover and cook for 2 hrs, or until the beans are soft and the meat is tender. If there is too much liquid in the pot take the lid off in the last hr. You can also use a slow cooker on the short method (4 hr) or make a quick version using a pressure cooker in batches for 30 mins each. Another method is to cook it in the oven for 3-4 hrs at 160C/140C fan/gas 3.","Serve with rice, a sprinkle of parsley or coriander, hot pepper sauce and orange slices."],"ingredient_names":["black beans","bacon","pork back ribs","chorizo","pork shoulder","onion","garlic","chilli flakes","oil","bay leaf"],"allergens":[],"diet_flags":[]},{"source_id":"53483","title":"Acaraje black-eyed pea fritters with shrimp filling","category":"Seafood","country":"Brazil","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/dxs5t71782678369.jpg","youtube_url":null,"source_url":"https://www.bbcgoodfood.com/recipes/caraje-black-eyed-pea-fritters-shrimp-filling","ingredients":[{"name":"Black Eyed Peas","measure":"800g"},{"name":"Garlic","measure":"1 clove"},{"name":"Green Chilli","measure":"1"},{"name":"Red Onions","measure":"1 small finely diced"},{"name":"Plain Flour","measure":"2 tablespoons"},{"name":"Salt","measure":"1 tsp"},{"name":"Chilli Powder","measure":"1 tsp"},{"name":"Baking Powder","measure":"1 tsp"},{"name":"Vegetable Oil","measure":"For frying"},{"name":"Red Onions","measure":"1 sliced"},{"name":"Ginger","measure":"1 tablespoon chopped"},{"name":"Garlic","measure":"2 cloves"},{"name":"Red Chilli","measure":"1 chopped"},{"name":"Raw tiger prawns","measure":"150g"},{"name":"Vegetable Oil","measure":"1 tablespoon"},{"name":"Plum Tomatoes","measure":"2"},{"name":"Coriander","measure":"1 tablespoon chopped"},{"name":"Lime","measure":"Juice of 1"}],"steps":["Make the filling by placing the onion, ginger, garlic, chilli, and some salt into food processor. Purée until smooth. Heat the oil in a frying pan and pour the purée into it. Fry for 5 mins or until cooked through. Add the prawns, tomatoes and chopped coriander. Squeeze in the lime and add salt to taste. Cook for 3 mins, or until the prawns have cooked through. Remove from the heat.","Drain and rinse the black-eyed peas. Pour into a food processor with the garlic and chili. Purée until smooth. Scrape into a bowl and add the onion, flour, salt, chilli powder and baking powder. Mix and roll into 16 balls.","Heat the oven to 190C/170C fan/gas 5. Heat 8cm of the palm or vegetable oil in a wok or small heavy pan. When a small piece of bread sizzles, drop 4-5 balls into the oil. Fry until golden and crisp, about 4-5 mins. Drain on kitchen paper and repeat until they are all finished. You can keep them warm in the oven while you finish. Slice the fritters open down the centre and spoon the prawn filling in. Serve with hot sauce."],"ingredient_names":["black eyed peas","garlic","green chilli","red onions","plain flour","salt","chilli powder","baking powder","vegetable oil","red onions","ginger","garlic","red chilli","raw tiger prawns","vegetable oil","plum tomatoes","coriander","lime"],"allergens":["gluten","shellfish"],"diet_flags":["pescatarian"]},{"source_id":"53486","title":"Easy White Bean Soup","category":"Vegetarian","country":"Bulgaria","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/p5nzbk1782680889.jpg","youtube_url":null,"source_url":"https://cookinglsl.com/bulgarian-white-bean-soup/","ingredients":[{"name":"Cannellini Beans","measure":"1 lb"},{"name":"Onions","measure":"2 medium"},{"name":"Vegetable Oil","measure":"2 tablespoons"},{"name":"Red Pepper","measure":"2 medium"},{"name":"Tomato Puree","measure":"1/3 cup"},{"name":"Carrots","measure":"2 medium"},{"name":"Water","measure":"6 cups"},{"name":"Dried Mint","measure":"1 tsp"},{"name":"Thyme","measure":"1/2 tsp"},{"name":"Summer Savoury","measure":"1 tsp"},{"name":"Black Pepper","measure":"1 tsp"},{"name":"Salt","measure":"1 tsp"},{"name":"Parsley","measure":"Garnish"}],"steps":["Place beans in a large pot and cover with cold water. Soak for at least 4 hours or overnight. Drain and rinse, before you use in the soup.","Chop one of the onions and leave the other one whole. Chop carrots.","Heat oil on a large pot over medium heat. Add the onion and carrots. Cook for 2 minutes. Add beans, water, peppers, head of onion, salt, pepper, summer savory, mint, thyme, Vegeta and tomato puree. Stir, bring to a boil, then reduce to a simmer and cook for 2 hours, or until the beans are tender.","Remove the peppers and whole onion. Mash the onion. Peel peppers and chop. Return to the pot.","Add more salt and pepper, if needed. Garnish with chopped parsley. Serve."],"ingredient_names":["cannellini beans","onions","vegetable oil","red pepper","tomato puree","carrots","water","dried mint","thyme","summer savoury","black pepper","salt","parsley"],"allergens":[],"diet_flags":["pescatarian","vegan","vegetarian"]},{"source_id":"53488","title":"Cabbage with Ground Beef","category":"Beef","country":"Bulgaria","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/brmxra1782681940.jpg","youtube_url":null,"source_url":"https://cookinglsl.com/ground-beef-cabbage-recipe/#wprm-recipe-container-59951","ingredients":[{"name":"Olive Oil","measure":"2 tablespoons"},{"name":"Ground Beef","measure":"1 lb"},{"name":"Onion","measure":"1 small"},{"name":"Carrots","measure":"2 medium"},{"name":"Red Pepper","measure":"1 medium"},{"name":"Tomato Puree","measure":"1 tablespoon"},{"name":"Garlic","measure":"2 cloves"},{"name":"Salt","measure":"1/2 tbs"},{"name":"Black Pepper","measure":"1/2 tbs"},{"name":"Smoked Paprika","measure":"1 tsp"},{"name":"Ground Cumin","measure":"1/4 tsp"},{"name":"Cabbage","measure":"1/2"},{"name":"Apple Cider Vinegar","measure":"1 tsp"},{"name":"Water","measure":"1 cup"},{"name":"Parsley","measure":"2 tbs chopped"}],"steps":["Heat a large skillet or braiser over medium heat on the stovetop. Add the olive oil.","A braiser with cooked ground beef","Cook the Meat:","Add the ground meat to the pan. Use a potato masher or wooden spoon to break it into small pieces. Cook for 3–4 minutes until browned.","Add Vegetables and Seasoning:","Stir in the onion, carrots, red pepper, garlic, and tomato paste. Season with salt, black pepper, smoked paprika, ground cumin, and Italian seasoning (if using). Cook for 2–3 minutes, stirring frequently.","A braiser with cooked ground beef, carrots, onions, peppers, garlic and seasoning.","Add Cabbage and Liquid:","Add the chopped cabbage, apple cider vinegar or lemon juice (if using), and water. Stir well to combine. Reduce the heat to medium-low, cover, and cook for 30 minutes. Stir occasionally to prevent the cabbage from sticking to the bottom of the pan.","A pot with cooked ground beef, vegetables and cabbage on a stove top","Check for Doneness:","Uncover and check the texture of the cabbage. If necessary, increase the heat to medium-high and cook for an additional 5–7 minutes to evaporate excess liquid and finish cooking.","A braiser with cooked ground meat and cabbage dish on a stove top","Garnish and Serve:","Sprinkle with chopped parsley or fresh herbs before serving."],"ingredient_names":["olive oil","ground beef","onion","carrots","red pepper","tomato puree","garlic","salt","black pepper","smoked paprika","ground cumin","cabbage","apple cider vinegar","water","parsley"],"allergens":[],"diet_flags":[]},{"source_id":"53489","title":"Potato Moussaka Recipe","category":"Beef","country":"Bulgaria","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/08ez421782683409.jpg","youtube_url":null,"source_url":"https://cookinglsl.com/potato-moussaka-recipe-bulgarian/#wprm-recipe-container-38787","ingredients":[{"name":"Vegetable Oil","measure":"1 tablespoon"},{"name":"Ground Beef","measure":"1 lb"},{"name":"Onion","measure":"1/3 cup"},{"name":"Garlic","measure":"1 clove peeled crushed"},{"name":"Tomato Sauce","measure":"1/4 cup"},{"name":"Tomato Puree","measure":"2 tablespoons"},{"name":"Salt","measure":"1 tsp"},{"name":"Black Pepper","measure":"1/4 tsp"},{"name":"Summer Savoury","measure":"1 tsp"},{"name":"Water","measure":"2 cups"},{"name":"Potatoes","measure":"2 Lbs"},{"name":"Carrots","measure":"1/4 cup"},{"name":"Milk","measure":"2 cups"},{"name":"Dried Mint","measure":"1/2 tsp"},{"name":"Butter","measure":"6 tablespoons"},{"name":"Flour","measure":"1/2 cup"},{"name":"Salt","measure":"1/2 tsp"},{"name":"Egg Yolks","measure":"3"},{"name":"Feta","measure":"1/2 cup"},{"name":"Ground Nutmeg","measure":"1/4 tsp"}],"steps":["Preheat oven to 350 F.","Heat oil in a skillet. Add the ground meat and cook, breaking it down with a wooden spoon for 6-7 minutes, until browned. Add onion and garlic. Add carrots (optional).Add salt, black pepper, dried mint, summer savory, thyme (optional), tomato sauce and tomato paste. Cook for 2-3 minutes, stirring frequently.","Grease a 9×9 or 9×13 baking dish with oil.","Add in the drained potatoes and meat mixture. Stir to evenly distribute the meat into the potatoes.","Add cold water to the baking dish, so it just covers the top of the potatoes.","Bake for 40-50 minutes, until the water is absorbed by the potatoes and they are fully cooked.","In the mean time prepare the Bechamel sauce (or the Bulgarian Style Topping).","For the Bechamel:","In a bowl, swish egg yolks. Set aside.","Melt butter in a saucepan. add flour. Cook for 3 minutes on medium heat, stirring frequently.","Slowly add the milk, whisking to incorporate. Add salt and nutmeg. Cook for 3 minutes, until thickened. Let the mixture cool for 5 minutes. Add in the egg yolks (with feta). Let the sauce stand at room temperature, while the potatoes and meat are cooking.","Pour the sauce over the cooked potatoes. Top with cheese. Bake for 15 minutes, until golden. You can broil for 1-2 minutes, if the top is not getting to the desired golden color.","For the Bulgarian Moussaka topping:","In a bowl beat together eggs, yogurt, milk, flour, then add salt and baking soda.","Pour over the moussaka . Top with cheese. Bake for 10-15 minutes, until golden."],"ingredient_names":["vegetable oil","ground beef","onion","garlic","tomato sauce","tomato puree","salt","black pepper","summer savoury","water","potatoes","carrots","milk","dried mint","butter","flour","salt","egg yolks","feta","ground nutmeg"],"allergens":["dairy","eggs","gluten"],"diet_flags":[]},{"source_id":"53490","title":"Cottage Cheese And Feta Stuffed Peppers","category":"Vegetarian","country":"Bulgaria","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/w0rsga1782683912.jpg","youtube_url":null,"source_url":"https://cookinglsl.com/cottage-cheese-stuffed-peppers/#wprm-recipe-container-59383","ingredients":[{"name":"Red Pepper","measure":"4"},{"name":"Feta","measure":"100g"},{"name":"Cottage Cheese","measure":"200g"},{"name":"Chives","measure":"1 tablespoon chopped"},{"name":"Parsley","measure":"1 tablespoon chopped"},{"name":"Salt","measure":"1/4 tsp"},{"name":"Lemon Juice","measure":"1 tablespoon"}],"steps":["Cut the peppers lengthwise and remove the seeds.","In a bowl combine 3.5 oz (100 grams) Feta cheese, 7 oz (200 grams) cottage cheese, 1 tbsp chopped chives (optional), 1 tbsp chopped parsley (optional), 1/4 tsp salt (more or less to taste) and 1 tbsp lemon juice.","Fill the peppers with the mixture. Top with chopped chives and parsley.","Serve."],"ingredient_names":["red pepper","feta","cottage cheese","chives","parsley","salt","lemon juice"],"allergens":["dairy"],"diet_flags":["pescatarian","vegetarian"]},{"source_id":"53491","title":"Shopska Salad","category":"Vegetarian","country":"Bulgaria","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/bqx8mc1782684286.jpg","youtube_url":null,"source_url":"https://cookinglsl.com/shopska-salad-recipe-bulgarian-tomato-and-cucumber-salad/#wprm-recipe-container-35244","ingredients":[{"name":"Cucumber","measure":"1 sliced"},{"name":"Tomatoes","measure":"3 Cups"},{"name":"Red Onions","measure":"1/4"},{"name":"Green Pepper","measure":"1 chopped"},{"name":"Salt","measure":"1 tsp"},{"name":"Olive Oil","measure":"1/4 cup"},{"name":"Feta","measure":"1/3 cup"},{"name":"Parsley","measure":"2 tbs chopped"}],"steps":["Combine vegetables in a bowl and sprinkle salt on top. Let it stand for 5 minutes. Add the oil. Top with feta and parsley. Serve."],"ingredient_names":["cucumber","tomatoes","red onions","green pepper","salt","olive oil","feta","parsley"],"allergens":["dairy"],"diet_flags":["pescatarian","vegetarian"]},{"source_id":"53495","title":"Amok Trey – Cambodian Fish Curry","category":"Seafood","country":"Cambodia","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/diuub11782687570.jpg","youtube_url":null,"source_url":"https://recipes-for-life.com/cambodian-recipes/","ingredients":[{"name":"Fish fillet","measure":"1 lb"},{"name":"Coconut Milk","measure":"1 Can"},{"name":"Red Curry Paste","measure":"2 tablespoons"},{"name":"Fish Sauce","measure":"1 tablespoon"},{"name":"Brown Sugar","measure":"1 tsp"},{"name":"Chicken Stock","measure":"1 cup"},{"name":"Egg","measure":"1"},{"name":"Kaffir Lime Leaves","measure":"2"},{"name":"Vegetable Oil","measure":"1 tablespoon"},{"name":"Banana Leaves","measure":"Handful"},{"name":"Cilantro","measure":"Garnish"},{"name":"Lime","measure":"Garnish"}],"steps":["In a medium bowl, combine the coconut milk, red curry paste, fish sauce, palm sugar, and broth, whisking until smooth—this ensures no lumps in the sauce.","Heat the vegetable oil in a large skillet over medium heat (about 350°F) for 30 seconds until shimmering.","Pour the coconut milk mixture into the skillet and bring it to a gentle simmer, stirring occasionally, which should take about 3-4 minutes.","Add the fish cubes and kaffir lime leaves to the skillet, submerging them fully in the sauce.","Reduce the heat to low, cover the skillet, and let it cook for 10 minutes until the fish is opaque and flakes easily with a fork—avoid overcooking to keep it tender.","Stir in the beaten egg slowly, cooking for 2 more minutes until the sauce thickens slightly, which adds a rich, custard-like texture.","While the curry simmers, prepare the banana leaves by briefly passing them over a gas flame for 10 seconds to make them pliable, or use parchment paper as a handy alternative.","Spoon the curry into the center of each banana leaf square, folding the edges to form a tight packet to trap steam.","Place the packets in a steamer basket over boiling water and steam for 10 minutes until heated through and fragrant.","Carefully unwrap the packets and garnish with fresh cilantro and lime wedges before serving"],"ingredient_names":["fish fillet","coconut milk","red curry paste","fish sauce","brown sugar","chicken stock","egg","kaffir lime leaves","vegetable oil","banana leaves","cilantro","lime"],"allergens":["eggs","fish"],"diet_flags":[]},{"source_id":"53496","title":"Bai Sach Chrouk – Grilled Pork with Rice","category":"Pork","country":"Cambodia","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/f0cdwk1782688162.jpg","youtube_url":null,"source_url":"https://recipes-for-life.com/cambodian-recipes/","ingredients":[{"name":"Pork Shoulder","measure":"650g"},{"name":"Coconut Milk","measure":"1/4 cup"},{"name":"Soy Sauce","measure":"3  tablespoons"},{"name":"Oyster Sauce","measure":"2 tablespoons"},{"name":"Honey","measure":"2 tablespoons"},{"name":"Garlic","measure":"4 cloves"},{"name":"Black Pepper","measure":"1 tsp"},{"name":"Jasmine Rice","measure":"2 cups"},{"name":"Water","measure":"4 cups"},{"name":"Vegetable Oil","measure":"1 tablespoon"},{"name":"Cucumber","measure":"1 sliced"},{"name":"Cilantro Leaves","measure":"Garnish"}],"steps":["In a large bowl, combine the coconut milk, soy sauce, oyster sauce, honey, minced garlic, and black pepper to make the marinade.","Add the thinly sliced pork shoulder to the marinade, ensuring each piece is fully coated, then cover and refrigerate for at least 30 minutes to allow the flavors to penetrate.","While the pork marinates, rinse the jasmine rice under cold water until the water runs clear to remove excess starch, which helps prevent clumping.","In a medium pot, combine the rinsed rice and 4 cups of water, bring to a boil over high heat, then reduce to a simmer, cover, and cook for 15 minutes until the water is absorbed and the rice is tender.","Heat a grill pan or outdoor grill to medium-high heat (about 400°F) and lightly brush with vegetable oil to prevent sticking.","Remove the pork from the marinade, shaking off any excess, and place it on the hot grill, cooking for 3-4 minutes per side until nicely charred and cooked through with an internal temperature of 145°F.","Tip: Avoid overcrowding the grill pan to ensure even browning and proper caramelization of the marinade.","Once the pork is grilled, let it rest for 5 minutes before slicing to retain its juices and tenderness.","Tip: If you prefer a saucier dish, simmer the leftover marinade in a small saucepan for 5 minutes until slightly thickened and drizzle it over the pork.","Fluff the cooked rice with a fork to separate the grains and serve it warm alongside the grilled pork slices.","Arrange the thinly sliced cucumber and fresh cilantro leaves on top as a refreshing garnish.","Tip: For an extra kick, serve with a side of pickled vegetables or a squeeze of lime juice to balance the rich, savory flavors."],"ingredient_names":["pork shoulder","coconut milk","soy sauce","oyster sauce","honey","garlic","black pepper","jasmine rice","water","vegetable oil","cucumber","cilantro leaves"],"allergens":["gluten","shellfish","soy"],"diet_flags":[]},{"source_id":"53497","title":"Nom Banh Chok – Cambodian Noodle Soup","category":"Chicken","country":"Cambodia","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/6g9gif1782688663.jpg","youtube_url":null,"source_url":"https://recipes-for-life.com/cambodian-recipes/","ingredients":[{"name":"Water","measure":"8 cups"},{"name":"Chicken Thighs","measure":"1lb"},{"name":"Garlic","measure":"4 Cloves Crushed"},{"name":"Vegetable Oil","measure":"2 tablespoons"},{"name":"Fish Sauce","measure":"1 tablespoon"},{"name":"Salt","measure":"1 tsp"},{"name":"Sugar","measure":"1 tsp"},{"name":"Rice Noodles","measure":"8 oz"},{"name":"Bean Sprouts","measure":"2 cups"},{"name":"Mint","measure":"1 cup"},{"name":"Lime","measure":"1"},{"name":"Red Chilli","measure":"1"}],"steps":["Heat the vegetable oil in a large pot over medium heat until it shimmers, about 2 minutes.","Add the minced garlic and sauté until fragrant and lightly golden, about 1 minute, stirring constantly to prevent burning.","Add the chicken pieces and cook until they turn opaque on all sides, about 5 minutes, stirring occasionally.","Pour in the 8 cups of water and bring to a boil over high heat, which should take about 8 minutes.","Reduce the heat to low, stir in the fish sauce, salt, and sugar, and simmer uncovered for 20 minutes to develop the flavors.","While the broth simmers, cook the rice noodles according to package instructions until al dente, then drain and rinse under cold water to stop the cooking.","Divide the cooked noodles evenly among four bowls.","Ladle the hot broth and chicken over the noodles in each bowl.","Top each bowl with bean sprouts, chopped mint leaves, and optional red chili slices.","Serve immediately with lime wedges on the side for squeezing over the soup."],"ingredient_names":["water","chicken thighs","garlic","vegetable oil","fish sauce","salt","sugar","rice noodles","bean sprouts","mint","lime","red chilli"],"allergens":["fish"],"diet_flags":[]},{"source_id":"53498","title":"Samlar Kari – Khmer Red Curry","category":"Chicken","country":"Cambodia","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/k5qzdl1782689660.jpg","youtube_url":null,"source_url":"https://recipes-for-life.com/cambodian-recipes/","ingredients":[{"name":"Vegetable Oil","measure":"1 tablespoon"},{"name":"Chicken Thighs","measure":"1 lb"},{"name":"Onion","measure":"1 medium chopped"},{"name":"Garlic","measure":"3 Cloves Crushed"},{"name":"Ginger","measure":"1 tablespoon"},{"name":"Red Curry Paste","measure":"2 tablespoons"},{"name":"Coconut Milk","measure":"1 can"},{"name":"Chicken Stock","measure":"1 cup"},{"name":"Fish Sauce","measure":"1 tablespoon"},{"name":"Brown Sugar","measure":"1 tablespoon"},{"name":"Bamboo Shoot","measure":"1 cup"},{"name":"Red Pepper","measure":"1 sliced"},{"name":"Basil","measure":"Pinch"},{"name":"Lime","measure":"To serve"}],"steps":["Heat 1 tbsp vegetable oil in a large pot or Dutch oven over medium-high heat until it shimmers, about 2 minutes.","Add 1 lb chicken pieces to the pot and cook until browned on all sides, approximately 5–7 minutes, stirring occasionally to prevent sticking.","Remove the chicken from the pot and set it aside on a plate, leaving any oil and juices in the pot.","Reduce the heat to medium and add 1 sliced onion to the pot, cooking until softened and translucent, about 4 minutes.","Stir in 3 cloves minced garlic and 1 tbsp grated ginger, cooking for 1 minute until fragrant to avoid burning.","Add 2 tbsp red curry paste to the pot and cook for 1 minute, stirring constantly to toast the spices and deepen the flavor.","Pour in 1 can coconut milk and 1 cup chicken broth, scraping the bottom of the pot to incorporate any browned bits for extra richness.","Stir in 1 tbsp fish sauce and 1 tbsp palm sugar until fully dissolved, then return the browned chicken to the pot.","Bring the mixture to a gentle boil, then reduce the heat to low, cover, and simmer for 15 minutes to allow the flavors to meld.","Add 1 cup bamboo shoots and 1 sliced red bell pepper to the pot, simmering uncovered for an additional 5 minutes until the vegetables are tender-crisp.","Remove the pot from the heat and stir in 1 cup Thai basil leaves until just wilted, about 1 minute, to preserve their fresh aroma.","Serve the curry hot, garnished with lime wedges for a bright, acidic finish."],"ingredient_names":["vegetable oil","chicken thighs","onion","garlic","ginger","red curry paste","coconut milk","chicken stock","fish sauce","brown sugar","bamboo shoot","red pepper","basil","lime"],"allergens":["fish"],"diet_flags":[]},{"source_id":"53499","title":"Prahok Ktis – Pork and Coconut Dip","category":"Pork","country":"Cambodia","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/g80f4t1782690273.jpg","youtube_url":null,"source_url":"https://recipes-for-life.com/cambodian-recipes/","ingredients":[{"name":"Ground Pork","measure":"1 lb"},{"name":"Coconut Milk","measure":"1 cup"},{"name":"Prahok","measure":"3  tablespoons"},{"name":"Vegetable Oil","measure":"2 tablespoons"},{"name":"Garlic","measure":"4 Cloves Crushed"},{"name":"Shallots","measure":"2 chopped"},{"name":"Chilli","measure":"2"},{"name":"Brown Sugar","measure":"1 tablespoon"},{"name":"Fish Sauce","measure":"2 tablespoons"},{"name":"Lime","measure":"Juice of 1"},{"name":"Cilantro","measure":"Garnish"}],"steps":["Heat 2 tbsp vegetable oil in a large skillet over medium-high heat until shimmering, about 1 minute.","Add 4 cloves minced garlic and 2 finely chopped shallots to the skillet, stirring constantly until fragrant and lightly golden, 2-3 minutes.","Tip: Keep the heat medium to prevent burning—garlic can turn bitter if overcooked.","Add 1 lb ground pork to the skillet, breaking it up with a spoon, and cook until no pink remains, 5-7 minutes.","Stir in 3 tbsp prahok and cook for 1 minute to blend the flavors, mashing it slightly into the pork.","Pour in 1 cup coconut milk, stirring to combine, then reduce heat to medium-low and simmer for 10 minutes until the mixture thickens slightly.","Tip: Simmer gently to avoid curdling the coconut milk—a steady bubble is ideal.","Add 2 tbsp fish sauce, 1 tbsp palm sugar, and 2 minced Thai chilies, stirring until the sugar dissolves, about 2 minutes.","Remove the skillet from heat and stir in 2 tbsp lime juice, mixing thoroughly.","Tip: Add lime juice off the heat to preserve its fresh, tangy flavor without cooking it out.","Transfer the dip to a serving bowl and garnish with ¼ cup chopped fresh cilantro.","Let the dip cool for 5 minutes before serving to allow the flavors to meld."],"ingredient_names":["ground pork","coconut milk","prahok","vegetable oil","garlic","shallots","chilli","brown sugar","fish sauce","lime","cilantro"],"allergens":["fish"],"diet_flags":[]},{"source_id":"53501","title":"Num Pang – Cambodian Baguette Sandwich","category":"Chicken","country":"Cambodia","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/o93jur1782769321.jpg","youtube_url":null,"source_url":"https://recipes-for-life.com/cambodian-recipes/","ingredients":[{"name":"Baguette","measure":"4"},{"name":"Chicken Thighs","measure":"1 lb"},{"name":"Soy Sauce","measure":"1/4 cup"},{"name":"Honey","measure":"2 tablespoons"},{"name":"Vegetable Oil","measure":"2 tablespoons"},{"name":"Carrots","measure":"1/2 cup"},{"name":"Daikon Radish","measure":"1/2 cup"},{"name":"Rice Vinegar","measure":"1/4 cup"},{"name":"Sugar","measure":"1 tablespoon"},{"name":"Mayonnaise","measure":"1/4 cup"},{"name":"Sriracha","measure":"1 tablespoon"},{"name":"Cilantro Leaves","measure":"1/2 cup"},{"name":"Cucumber","measure":"1/4 cup"}],"steps":["In a medium bowl, whisk together the soy sauce and honey to create a marinade.","Add the chicken thigh strips to the marinade, ensuring each piece is fully coated, and let it sit for 20 minutes at room temperature.","While the chicken marinates, combine the julienned carrots, daikon radish, rice vinegar, and granulated sugar in a separate bowl, stirring until the sugar dissolves to pickle the vegetables.","In a small bowl, mix the mayonnaise and sriracha sauce thoroughly to make a spicy aioli.","Heat the vegetable oil in a large skillet or wok over medium-high heat until it shimmers, about 2 minutes.","Add the marinated chicken strips to the hot skillet in a single layer, cooking for 4-5 minutes per side until they reach an internal temperature of 165°F and develop a golden-brown crust.","While the chicken cooks, lightly toast the split baguettes in a toaster oven or under a broiler for 2-3 minutes until just crisp on the edges.","Spread a generous layer of the spicy aioli on the inside of each toasted baguette.","Drain the pickled carrots and daikon radish from their liquid, then layer them onto the bottom half of each baguette.","Place the cooked chicken strips evenly over the pickled vegetables in each sandwich.","Top the chicken with fresh cilantro leaves and thinly sliced cucumber.","Close the sandwiches by pressing the top half of each baguette down gently."],"ingredient_names":["baguette","chicken thighs","soy sauce","honey","vegetable oil","carrots","daikon radish","rice vinegar","sugar","mayonnaise","sriracha","cilantro leaves","cucumber"],"allergens":["eggs","gluten","soy"],"diet_flags":[]},{"source_id":"53502","title":"Khmer Banh Xeo – Cambodian Savory Pancake","category":"Pork","country":"Cambodia","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/xrv78g1782769859.jpg","youtube_url":null,"source_url":"https://recipes-for-life.com/cambodian-recipes/","ingredients":[{"name":"Rice Flour","measure":"1 cup"},{"name":"Cornstarch","measure":"1/4 cup"},{"name":"Coconut Milk","measure":"1 1/4 cup"},{"name":"Water","measure":"3/4 cup"},{"name":"Ground Turmeric","measure":"1/2 tsp"},{"name":"Pork belly slices","measure":"1/2 lb"},{"name":"Bean Sprouts","measure":"1 cup"},{"name":"Onion","measure":"1/2"},{"name":"Vegetable Oil","measure":"2 tablespoons"},{"name":"Fish Sauce","measure":"Splash"}],"steps":["Whisk together rice flour, cornstarch, coconut milk, water, and turmeric in a bowl until smooth, then let rest for 15 minutes—this hydrates the flour for better texture.","Heat a 10-inch non-stick skillet over medium-high heat (375°F) and add 1/2 tablespoon of vegetable oil.","Sauté pork belly slices for 3–4 minutes until lightly browned, then push to one side of the skillet.","Add onion slices and cook for 1 minute until slightly softened.","Stir the batter briefly and pour about 1/2 cup into the skillet, immediately swirling to coat the bottom thinly.","Scatter bean sprouts over half of the pancake and cover the skillet with a lid for 2 minutes to steam the sprouts.","Uncover and cook for another 3–4 minutes until the edges curl and turn golden brown and crispy.","Fold the pancake in half over the bean sprouts using a spatula, then transfer to a plate.","Repeat steps 2–8 with remaining batter and ingredients, adding oil as needed to prevent sticking.","Serve immediately with fish sauce for dipping."],"ingredient_names":["rice flour","cornstarch","coconut milk","water","ground turmeric","pork belly slices","bean sprouts","onion","vegetable oil","fish sauce"],"allergens":["fish"],"diet_flags":[]},{"source_id":"53503","title":"Samlar Machu Kreung – Cambodian Sour Stew","category":"Chicken","country":"Cambodia","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/bmbvjk1782770310.jpg","youtube_url":null,"source_url":"https://recipes-for-life.com/cambodian-recipes/","ingredients":[{"name":"Chicken Thighs","measure":"1 lb"},{"name":"Vegetable Oil","measure":"1 tablespoon"},{"name":"Water","measure":"4 cups"},{"name":"Tamarind Paste","measure":"2 tablespoons"},{"name":"Fish Sauce","measure":"1 tablespoon"},{"name":"Sugar","measure":"1 tsp"},{"name":"Pineapple Chunks","measure":"1 cup"},{"name":"Cherry Tomatoes","measure":"1 cup"},{"name":"Green Beans","measure":"1 cup"},{"name":"Lemongrass","measure":"1 Stalk"},{"name":"Kaffir Lime Leaves","measure":"2"},{"name":"Chilli","measure":"1 sliced"}],"steps":["Heat 1 tbsp vegetable oil in a large pot over medium-high heat until it shimmers, about 1 minute.","Add 1 lb boneless, skinless chicken thighs to the pot and cook until browned on all sides, approximately 5-7 minutes, stirring occasionally to prevent sticking.","Pour 4 cups water into the pot and bring to a boil, then reduce heat to a simmer.","Stir in 2 tbsp tamarind paste, 1 tbsp fish sauce, and 1 tsp sugar until fully dissolved, about 1 minute.","Add 1 stalk lemongrass and 2 kaffir lime leaves to the pot, then cover and simmer for 10 minutes to infuse the broth with flavor.","Tip: Bruising the lemongrass before adding helps release its essential oils for a more aromatic stew.","Add 1 cup pineapple chunks, 1 cup cherry tomatoes, and 1 cup green beans to the pot, stirring gently to combine.","Simmer uncovered for 10-12 minutes, or until the green beans are tender but still crisp and the tomatoes start to soften.","Tip: Avoid overcooking the vegetables to maintain their vibrant color and texture in the final dish.","Stir in 1 Thai chili and simmer for an additional 2 minutes to incorporate the heat.","Tip: Taste the broth and adjust with extra tamarind paste or fish sauce if desired, but do so gradually to avoid overpowering the balance.","Remove the pot from heat and discard the lemongrass and kaffir lime leaves before serving.","Present the stew hot in bowls, optionally garnished with fresh herbs like cilantro."],"ingredient_names":["chicken thighs","vegetable oil","water","tamarind paste","fish sauce","sugar","pineapple chunks","cherry tomatoes","green beans","lemongrass","kaffir lime leaves","chilli"],"allergens":["fish"],"diet_flags":[]},{"source_id":"53504","title":"Macaroni Pudding","category":"Pasta","country":"Cayman Islands","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/hbte551782770868.jpg","youtube_url":null,"source_url":"https://www.ourcayman.ky/en-us/about/more-about-cayman/recipes","ingredients":[{"name":"Macaroni","measure":"4 cups"},{"name":"Evaporated Milk","measure":"4 cups"},{"name":"Water","measure":"1 cup"},{"name":"Sugar","measure":"3 Cups"},{"name":"Salt","measure":"2 tsp"},{"name":"Eggs","measure":"4"},{"name":"Butter","measure":"1/4 cup"},{"name":"Raisins","measure":"1 cup"},{"name":"Nutmeg","measure":"2 1/2 Tsp"},{"name":"Vanilla","measure":"2 tablespoons"}],"steps":["Add macaroni to large pan with sufficient water to cover (approximately 4 cups).","Add salt and bring to boil until tender (approximately 25 -30 minutes).","Meanwhile, beat eggs and sugar together, then add vanilla and nutmeg. Mix well and set aside.","In a separate medium sauce pan, heat evaporated milk plus 1 cup of water and butter to almost a boiling point.","Remove from heat and add to sugar mixture. Drain cooked macaroni.","Add macaroni and raisins to the milk mixture and stir well. (This mixture will have quite a bit of liquid, but this will form a nice custard textured pudding once baked.) Grease a large baking dish with butter or margarine, add the macaroni mixture and sprinkle with additional nutmeg.","Bake at 350° F for 1 hour or until golden brown. (Pudding should be firm enough to cut, but moist and not dry)."],"ingredient_names":["macaroni","evaporated milk","water","sugar","salt","eggs","butter","raisins","nutmeg","vanilla"],"allergens":["dairy","eggs","gluten"],"diet_flags":["pescatarian","vegetarian"]},{"source_id":"53505","title":"Conch Fritters","category":"Seafood","country":"Cayman Islands","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/nmtq3n1782772031.jpg","youtube_url":null,"source_url":"https://www.ourcayman.ky/en-us/about/more-about-cayman/recipes","ingredients":[{"name":"Conchs","measure":"Can"},{"name":"Green Pepper","measure":"1/2"},{"name":"Red Pepper","measure":"1/2"},{"name":"Onion","measure":"2 large"},{"name":"Chilli","measure":"2"},{"name":"Lime","measure":"Juice of 2"},{"name":"Garlic","measure":"2 tbsp chopped"},{"name":"Black Pepper","measure":"1 tablespoon"},{"name":"Salt","measure":"1 tablespoon"},{"name":"Basil","measure":"1 tsp"},{"name":"Red Pepper Flakes","measure":"1 tsp"},{"name":"Egg","measure":"1"},{"name":"All purpose flour","measure":"10 tblsp"},{"name":"Vegetable Oil","measure":"For frying"}],"steps":["Note: Make the conch mix the day before and store in the refrigerator to allow time for flavours to meld together. Tartar sauce can also be prepared beforehand. Just combine all the ingredients and mix well. Cover and refrigerate.","Use your food grinder to grind together the conch pieces, red and green peppers, onions and hot peppers. Once done, add in your lime juice, minced garlic, black pepper, salt, dried basil, and red pepper flakes; make sure to mix it thoroughly. Then add your egg and mix again. Lastly, add your flour one tablespoon at a time and mix until combined. You can either plastic wrap it and let sit in the fridge for an hour or overnight.","Once you're ready to fry, fill the deep-frying pan with about 1 ½ to 2 inches of a high heat oil of your choice. Turn stove on to a medium-low heat.","Use two spoons to form 1-inch balls and drop them into the hot oil one at a time. Each fritter should fry about 5-7 minutes or until golden brown and the inside is cooked. Repeat until you have used all the conch mixture. Serve with your tartar sauce and lime wedges."],"ingredient_names":["conchs","green pepper","red pepper","onion","chilli","lime","garlic","black pepper","salt","basil","red pepper flakes","egg","all purpose flour","vegetable oil"],"allergens":["eggs","gluten","shellfish"],"diet_flags":["pescatarian"]},{"source_id":"53506","title":"Rice and Beans","category":"Vegetarian","country":"Cayman Islands","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/j8c1d51782772399.jpg","youtube_url":null,"source_url":"https://www.ourcayman.ky/en-us/about/more-about-cayman/recipes","ingredients":[{"name":"Kidney Beans","measure":"1/2 bag"},{"name":"Coconut Milk","measure":"1 Can"},{"name":"Onion","measure":"1 Diced"},{"name":"Scotch Bonnet","measure":"3"},{"name":"Black Pepper","measure":"1 tablespoon"},{"name":"Salt","measure":"1/2 tbs"}],"steps":["Cook beans until tender, add rice, coconut milk, onion, black pepper and salt, and add enough water to just cover the ingredients. Place Scotch Bonnet peppers on top, careful not to burst them. Simmer until rice is tender. Remove pepper before serving."],"ingredient_names":["kidney beans","coconut milk","onion","scotch bonnet","black pepper","salt"],"allergens":[],"diet_flags":["pescatarian","vegan","vegetarian"]},{"source_id":"53509","title":"Fried Crab","category":"Seafood","country":"Cayman Islands","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/rprcc51782774240.jpg","youtube_url":null,"source_url":"https://www.ourcayman.ky/en-us/about/more-about-cayman/recipes","ingredients":[{"name":"Crab Meay","measure":"1 lb"},{"name":"Onions","measure":"2 medium"},{"name":"Scotch Bonnet","measure":"1"},{"name":"Black Pepper","measure":"1/2 tsp"},{"name":"Salt","measure":"To taste"},{"name":"Oil","measure":"1/4 cup"}],"steps":["Wash crabs and boil in large pot of water for 15 minutes, remove from boiling water and cool. Crack legs and open backs to remove all meat, set aside.","Remove seeds from scotch bonnet pepper and dice pepper and onions. Sauté onions and scotch bonnet peppers in oil over medium heat until onions begin to get transparent. Add crab meat, black pepper and salt, stirring occasionally. Cook over medium heat for an additional 5 to 10 minutes.","Serve with “bread kind”, a local dish that consists of a variety of starchy vegetables including pumpkin, squash, plantain, potato, cassava and breadfruit.","Optional: Seasoned crab meat may also be stuffed in cleaned crab backs and baked. Cover stuffed backs with foil paper and bake at 350 degrees for 30 minutes."],"ingredient_names":["crab meay","onions","scotch bonnet","black pepper","salt","oil"],"allergens":["shellfish"],"diet_flags":["pescatarian"]},{"source_id":"53510","title":"Cayman-Style Lobster","category":"Seafood","country":"Cayman Islands","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/wkhwqr1782774765.jpg","youtube_url":null,"source_url":"https://www.ourcayman.ky/en-us/about/more-about-cayman/recipes","ingredients":[{"name":"Lobster","measure":"6"},{"name":"Chicken Stock","measure":"1/2 cup"},{"name":"Red Pepper","measure":"1/2 cup"},{"name":"Green Pepper","measure":"1/2 cup"},{"name":"Onion","measure":"1/2 cup"},{"name":"Garlic","measure":"2 cloves minced"},{"name":"Scotch Bonnet","measure":"1/2"},{"name":"Salt","measure":"To taste"},{"name":"Pepper","measure":"To taste"},{"name":"Thyme","measure":"To taste"},{"name":"Cornstarch","measure":"2 tsp"},{"name":"Olive Oil","measure":"2 tablespoons"}],"steps":["Rinse lobster under cold running water. Bring water and salt to boil in a 12 quart pot. Quickly plunge lobsters, headfirst, into boiling water. Cover and boil for 20 minutes or until lobsters turn red.","Remove lobster and allow it to cool. Remove lobster tails and cut shell down to middle to remove the meat. Cut the tail meat down the middle to remove the vein inside. Remove large claws and smaller legs by twisting them away from the body. A nut cracker can be used to crush the claw and legs to remove the meat inside.","Chop lobster meat. Heat butter or olive oil in large pan over low heat. Sauté red, green and scotch bonnet peppers, thyme and garlic. Add salt and chicken stock to pan. Then, add lobster meat and sauté for 10 to 15 minutes. Thicken sauce with the corn starch and water mixture.","Serve with your choice of vegetables, salad and/or rice."],"ingredient_names":["lobster","chicken stock","red pepper","green pepper","onion","garlic","scotch bonnet","salt","pepper","thyme","cornstarch","olive oil"],"allergens":["shellfish"],"diet_flags":[]},{"source_id":"53511","title":"Salt Beef and Beans","category":"Beef","country":"Cayman Islands","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/dnd87q1782775269.jpg","youtube_url":null,"source_url":"https://www.ourcayman.ky/en-us/about/more-about-cayman/recipes","ingredients":[{"name":"Corned Beef","measure":"1 lb"},{"name":"Kidney Beans","measure":"1 1/2 cup"},{"name":"Scotch Bonnet","measure":"1"},{"name":"Scallions","measure":"2"},{"name":"Thyme","measure":"1/4 tsp"},{"name":"Garlic","measure":"1 clove finely chopped"},{"name":"Water","measure":"2 cups"},{"name":"Coconut Milk","measure":"3 Cups"},{"name":"Bay Leaf","measure":"2"},{"name":"Allspice","measure":"6"},{"name":"Garlic","measure":"2 cloves"}],"steps":["Cover the diced salt beef with water and bring to a boil.","Repeat as necessary, draining and replacing water to eliminate some of the brine.","In a separate pan, place beans in water, add coconut milk, bay leaves, pimento seeds, whole garlic, whole scotch bonnet pepper and scallions.","Slowly bring to a boil and simmer for about 2 hours, or until beans are tender.","Add salt beef, onions, thyme and crushed garlic and simmer for another 20 minutes.","Adjust seasonings if necessary.","Remove the bay leaves and scotch bonnet pepper, being careful not to burst the pepper.","Serve with white rice and your choice of salad or vegetables."],"ingredient_names":["corned beef","kidney beans","scotch bonnet","scallions","thyme","garlic","water","coconut milk","bay leaf","allspice","garlic"],"allergens":[],"diet_flags":[]},{"source_id":"53512","title":"Conch Stew","category":"Seafood","country":"Cayman Islands","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/mlkjeu1782775816.jpg","youtube_url":null,"source_url":"https://www.ourcayman.ky/en-us/about/more-about-cayman/recipes","ingredients":[{"name":"Conchs","measure":"2 Lbs"},{"name":"Onion","measure":"1"},{"name":"Green Pepper","measure":"1/2"},{"name":"Red Pepper","measure":"1/2"},{"name":"Scallions","measure":"2"},{"name":"Salt","measure":"1 tsp"},{"name":"Black Pepper","measure":"1/4 tsp"},{"name":"Seasoning","measure":"1/4 tsp"},{"name":"Coconut","measure":"1"},{"name":"Flour","measure":"1 tablespoon"},{"name":"Chilli","measure":"To taste"},{"name":"All purpose flour","measure":"1 cup"},{"name":"Vegetable Oil","measure":"1/2 tbs"},{"name":"Salt","measure":"Dash"},{"name":"Water","measure":"Splash"}],"steps":["Conch Stew Cooking Directions","Clean conch meat and pound to tenderize. Boil conch for 2 - 3 hours or until tender. Make Sea Pie while conch cooks (instructions below). Once cool, cut conch in bite size pieces and season. Add all ingredients, except flour, to pan and simmer for 10 to 20 minutes. Mix flour with 1 cup water and pour into pan to thicken. Add Sea Pie pieces and continue to cook for an additional 10 minutes.","Sea Pie Cooking Directions","Make dough with flour, pinch of salt and water so that you can roll out as thin as possible, then cut into 2 ½” x 2 ½” squares. Let set for 30 minutes then stretch squares to thin them out and add to conch stew mixture.","Serve with white rice, plantain, breadfruit or your choice of vegetables."],"ingredient_names":["conchs","onion","green pepper","red pepper","scallions","salt","black pepper","seasoning","coconut","flour","chilli","all purpose flour","vegetable oil","salt","water"],"allergens":["gluten","shellfish"],"diet_flags":["pescatarian"]},{"source_id":"53514","title":"Chilean Empanada","category":"Pork","country":"Chile","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/q4xgij1782851193.jpg","youtube_url":null,"source_url":"https://www.allrecipes.com/recipe/185584/chilean-empanada/","ingredients":[{"name":"Butter","measure":"1 tablespoon"},{"name":"Onion","measure":"1 large"},{"name":"Garlic","measure":"1 tsp minced"},{"name":"Dried Oregano","measure":"1 tsp"},{"name":"Cumin","measure":"1 tsp"},{"name":"Salt","measure":"1/2 tsp"},{"name":"Black Pepper","measure":"1/2 tsp"},{"name":"Ground Pork","measure":"1 lb"},{"name":"Raisins","measure":"1 cup"},{"name":"Black Olives","measure":"1 cup"},{"name":"Eggs","measure":"3 Large"},{"name":"Water","measure":"1 cup"},{"name":"Shortening","measure":"1 cup"},{"name":"All purpose flour","measure":"5 Cups"},{"name":"Salt","measure":"2 tsp"},{"name":"Eggs","measure":"2 Beaten"}],"steps":["Make the filling: Melt butter in a large skillet over medium heat. Add onion, garlic, oregano, cumin, salt, and pepper; cook and stir until onion is golden brown, 5 to 7 minutes. Add pork and cook until completely browned and crumbly, 7 to 10 minutes more. Drain fat from the skillet. Stir in raisins, olives, and hard-cooked eggs.","Whisk water and cornstarch together in a small bowl; pour into the skillet and stir until liquid thickens. Remove from the heat and set aside.","Make the dough: Whisk milk and melted shortening together in a bowl until evenly blended. Stir flour and salt together in a separate large bowl. Pour milk mixture into flour mixture; whisk until well combined and a dough forms. Let rest for 10 minutes.","Preheat the oven to 400 degrees F (200 degrees C). Line a baking sheet with parchment paper.","Roll dough on a lightly floured surface to a thickness of 1/8 inch. Cut into 12 circles with a round cookie cutter or glass. Spoon filling into the center of each circle. Fold each circle in half and press the edges with a fork to seal. Brush the tops with beaten egg. Place empanadas onto the prepared baking sheet.","Bake in the preheated oven until golden brown, about 25 minutes."],"ingredient_names":["butter","onion","garlic","dried oregano","cumin","salt","black pepper","ground pork","raisins","black olives","eggs","water","shortening","all purpose flour","salt","eggs"],"allergens":["dairy","eggs","gluten"],"diet_flags":[]},{"source_id":"53517","title":"Pastel de Papas (Chilean Potato Pie)","category":"Beef","country":"Chile","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/h031jy1782853081.jpg","youtube_url":null,"source_url":"https://www.allrecipes.com/recipe/210774/chilean-potato-pie-pastel-de-papas/","ingredients":[{"name":"Potatoes","measure":"5 Cups"},{"name":"Butter","measure":"2 tablespoons"},{"name":"Salt","measure":"To taste"},{"name":"Eggs","measure":"2 Beaten"},{"name":"Vegetable Oil","measure":"1/2 cup"},{"name":"Onion","measure":"1 Diced"},{"name":"Garlic","measure":"1 clove peeled crushed"},{"name":"Tomato","measure":"2 diced"},{"name":"Tomato Puree","measure":"1 tablespoon"},{"name":"Ground Beef","measure":"1 lb"},{"name":"Panquehue Cheese","measure":"2 tablespoons"},{"name":"Parsley","measure":"1/2 tsp"},{"name":"Cayenne Pepper","measure":"1 pinch"},{"name":"Salt","measure":"To taste"},{"name":"Black Pepper","measure":"To taste"}],"steps":["Place potatoes into a large pot and cover with salted water; bring to a boil. Reduce the heat to medium-low and simmer until tender, about 20 minutes.","While the potatoes are cooking, heat oil in a large skillet over medium heat. Add onion; cook and stir until translucent, about 5 minutes, adding garlic for the last minute. Stir in diced tomatoes and tomato paste; cook until tomatoes soften and begin to lose their shape, 3 to 5 minutes.","Add ground beef to the skillet; cook and stir until browned and crumbly, about 10 minutes. Stir in Panquehue cheese, parsley, and cayenne pepper; season with salt and pepper. Turn off the heat and let sit until needed.","Preheat the oven to 350 degrees F (175 degrees C). Grease a 2-quart baking dish.","Drain potatoes in a colander, then allow to steam dry for 1 to 2 minutes. Transfer potatoes back to the pot, add butter and salt, and mash until smooth. Let cool until just warm, 5 to 10 minutes, then stir in beaten egg.","Spread 1/2 of the mashed potatoes over the bottom of the prepared baking dish. Layer ground beef mixture over top, then completely cover with remaining potatoes.","Bake in the preheated oven until potatoes are hot and lightly browned on top, about 40 minutes."],"ingredient_names":["potatoes","butter","salt","eggs","vegetable oil","onion","garlic","tomato","tomato puree","ground beef","panquehue cheese","parsley","cayenne pepper","salt","black pepper"],"allergens":["dairy","eggs"],"diet_flags":[]},{"source_id":"53518","title":"Empanadas Fritas de Queso","category":"Vegetarian","country":"Chile","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/9tllzd1782853513.jpg","youtube_url":null,"source_url":"https://www.allrecipes.com/recipe/134319/empanadas-fritas-de-queso/","ingredients":[{"name":"All purpose flour","measure":"3 Cups"},{"name":"Baking Powder","measure":"1 tsp"},{"name":"Salt","measure":"1/2 tsp"},{"name":"Lard","measure":"2 tablespoons"},{"name":"Milk","measure":"1 cup"},{"name":"Egg","measure":"1 beaten"},{"name":"Swiss Cheese","measure":"1 cup"}],"steps":["Sift the flour, baking powder, and salt into a large mixing bowl. Combine the lard and milk in a saucepan, and heat until the milk is hot. Pour the hot milk into the flour mixture, and stir until a dough forms. Turn out onto a floured surface, and knead until smooth and elastic. Cover, and allow to rest for 15 minutes.","Preheat oven to 375 degrees F (190 degrees C).","Roll the dough out on a floured surface 1/4-inch thick. Cut into 4-inch rounds. Brush the outer edges of each circle with beaten egg, and fill with a small mound of cheese. Fold each circle in half to form a half-moon; press the edges with your fingers or a fork to seal. Place the empanadas onto a parchment paper-lined baking sheet. Brush the tops with remaining egg.","Bake in preheated oven until golden-brown, about 20 minutes.","Alternatively, the empanadas may be deep fried in 375 degrees F (190 degrees C) oil. If deep frying, do not brush the outsides of the empanadas with egg. Drain on paper towels."],"ingredient_names":["all purpose flour","baking powder","salt","lard","milk","egg","swiss cheese"],"allergens":["dairy","eggs","gluten"],"diet_flags":[]},{"source_id":"53520","title":"Pastel de Choclo","category":"Chicken","country":"Chile","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/47abic1782854326.jpg","youtube_url":null,"source_url":"https://www.allrecipes.com/recipe/268354/pastel-de-choclo/","ingredients":[{"name":"Eggs","measure":"2"},{"name":"Onions","measure":"2 chopped"},{"name":"Garlic","measure":"2 cloves minced"},{"name":"Salt","measure":"1 tsp"},{"name":"Paprika","measure":"1/2 tsp"},{"name":"Black Pepper","measure":"To taste"},{"name":"Ground Beef","measure":"1 lb"},{"name":"Chicken","measure":"1/2"},{"name":"Raisins","measure":"2 tablespoons"},{"name":"Green Olives","measure":"2 tablespoons"},{"name":"Sweetcorn","measure":"3 cans"},{"name":"Basil","measure":"2 tsp"},{"name":"Butter","measure":"1 tablespoon"},{"name":"Milk","measure":"1 cup"},{"name":"Sugar","measure":"2 tsp"},{"name":"Salt","measure":"To taste"}],"steps":["Place eggs in a saucepan and cover with water. Bring to a boil, remove from heat, and let eggs stand in hot water for 15 minutes.","Meanwhile, heat oil in a skillet over medium heat. Add onions, garlic, 1 pinch salt, ¼ teaspoon paprika, and black pepper; cook until fragrant, about 2 minutes. Add beef, remaining 1 teaspoon salt, remaining ¼ teaspoon paprika, and black pepper; cook and stir until beef mostly browned, about 5 minutes. Add chicken, raisins, and olives.","Remove eggs from hot water, cool under cold running water, and peel. Roughly chop; add to beef mixture. Keep pino warm.","Combine corn and basil in a blender or the bowl of a food processor; blend until smooth. Pour into a saucepan over medium heat. Add butter; cook and stir until thickened, 7 to 10 minutes. Stir in milk, 2 teaspoons sugar, and salt; cook until thickened to a paste, about 15 minutes more.","Preheat the oven to 350 degrees F (175 degrees C).","Spread pino into a baking dish. Cover with corn paste; sprinkle a little sugar on top.","Bake in the preheated oven until golden brown on top, about 20 minutes."],"ingredient_names":["eggs","onions","garlic","salt","paprika","black pepper","ground beef","chicken","raisins","green olives","sweetcorn","basil","butter","milk","sugar","salt"],"allergens":["dairy","eggs"],"diet_flags":[]},{"source_id":"53528","title":"Chuletas de Cerdo a la Criolla (Pork Chops in Creole Sauce)","category":"Pork","country":"Colombia","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/087fu71783802698.jpg","youtube_url":null,"source_url":"https://www.mycolombianrecipes.com/chuletas-de-cerdo-a-la-criolla-pork-chops-in-creole-sauce/#recipe","ingredients":[{"name":"Pork Chops","measure":"4"},{"name":"Vegetable Oil","measure":"2 tablespoons"},{"name":"Garlic","measure":"3 Cloves Crushed"},{"name":"Mustard","measure":"Melted"},{"name":"Ground Cumin","measure":"1 tablespoon"},{"name":"Tomato","measure":"3 diced"},{"name":"Onions","measure":"2 sliced"},{"name":"Cilantro","measure":"1/4 cup"},{"name":"Salt","measure":"To taste"},{"name":"Black Pepper","measure":"To taste"}],"steps":["Place the pork chops in a zip lock plastic bag. Add the mustard, cumin, garlic, salt and pepper.","Refrigerate for 1 hour or overnight. Be sure the pork chops are evenly covered.","In a large skillet, heat the oil over medium heat. Place the pork chops into the skillet and cook for 3 minutes per side. Remove the pork from the pan and keep aside on a warm plate.","Add the onions and tomatoes to the same skillet where the pork was browned, adding an additional tablespoon of oil if needed. Cook over high heat for about 5-7 minutes or until browned and softened, stirring frequently to avoid burning. Add the reserved cooked pork chops and cover, reduce the heat to medium-low and simmer until the pork is tender and barely pink in the center, about 15 minutes. Divide the chops among plates, spoon the sauce over the top, add the cilantro and serve immediately."],"ingredient_names":["pork chops","vegetable oil","garlic","mustard","ground cumin","tomato","onions","cilantro","salt","black pepper"],"allergens":[],"diet_flags":[]},{"source_id":"53530","title":"Creamy Mustard Chicken","category":"Chicken","country":"Colombia","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/4htbtm1783803558.jpg","youtube_url":null,"source_url":"https://www.mycolombianrecipes.com/mustard-creamy-chicken/#recipe","ingredients":[{"name":"Chicken Legs","measure":"8"},{"name":"Paprika","measure":"1 tsp"},{"name":"Salt","measure":"1 tsp"},{"name":"Black Pepper","measure":"1 tsp"},{"name":"Olive Oil","measure":"4 tablespoons"},{"name":"Garlic","measure":"3 Cloves Crushed"},{"name":"Onion","measure":"1/2 cup"},{"name":"Chicken Stock","measure":"2 cups"},{"name":"Mustard","measure":"2 tablespoons"},{"name":"Heavy Cream","measure":"1 cup"},{"name":"Honey","measure":"1 tablespoon"},{"name":"Parsley","measure":"Garnish"}],"steps":["Pat the chicken dry and season the pieces with salt, pepper and paprika.","Heat a saucepan over medium high heat and add the oil. Let the oil heat for a few seconds. Add the chicken and cook to sear all the sides turning the pieces a couple of times until they are golden browned about 10 minutes.","Transfer the browned chicken to a plate and set a side. Add the onions and garlic to the skillet and cook for about 2 minutes or until soft. Add the chicken broth, mustard, honey and cream. Season with salt and black pepper.","Stir well and return the chicken pieces to the pan. Cover the pan and cook over medium low for about 45 minutes or until the chicken is cooked. The final temperature for chicken legs should be 170˚F.","Serve warm over white rice and garnish with chopped parsley."],"ingredient_names":["chicken legs","paprika","salt","black pepper","olive oil","garlic","onion","chicken stock","mustard","heavy cream","honey","parsley"],"allergens":["dairy"],"diet_flags":[]},{"source_id":"53531","title":"Chicken in Orange Sauce Recipe (Pollo a la Naranja)","category":"Chicken","country":"Colombia","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/uuns781783804024.jpg","youtube_url":null,"source_url":"https://www.mycolombianrecipes.com/chicken-in-orange-sauce-pollo-a-la-naranja/#recipe","ingredients":[{"name":"Chicken Legs","measure":"4"},{"name":"Olive Oil","measure":"2 tablespoons"},{"name":"Butter","measure":"2 tablespoons"},{"name":"Onion","measure":"1/2 cup"},{"name":"Red Pepper","measure":"1"},{"name":"Garlic","measure":"3 cloves Chopped"},{"name":"Salt","measure":"1 tsp"},{"name":"Black Pepper","measure":"1/2 tsp"},{"name":"Chicken Stock","measure":"1 cup"},{"name":"Orange Juice","measure":"1/2 cup"},{"name":"Brown Sugar","measure":"3  tablespoons"},{"name":"Cilantro","measure":"1/4 cup"}],"steps":["Place the olive oil and butter in a large sauce pan over medium heat. Add the chopped onions, red bell pepper and garlic. Cook for about 3 minutes, stirring often until the vegetables are soft.","Add the chicken legs and season with salt and pepper. Cook for about 1 minute on each side.","Add the chicken broth, orange juice and cook for about 2 minutes scraping the bottom of the pan with a wooden spoon. Add the brown sugar and cover the pot. Reduce the heat to medium and cook for about 45 minutes or until chicken is cooked.","Spoon the sauce over the chicken and serve over white rice. Garnish with fresh cilantro."],"ingredient_names":["chicken legs","olive oil","butter","onion","red pepper","garlic","salt","black pepper","chicken stock","orange juice","brown sugar","cilantro"],"allergens":["dairy"],"diet_flags":[]},{"source_id":"53532","title":"Creamy Corn Soup Recipe","category":"Vegetarian","country":"Colombia","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/yf5eyw1783804464.jpg","youtube_url":null,"source_url":"https://www.mycolombianrecipes.com/corn-soup-crema-de-mazorca/#recipe","ingredients":[{"name":"Corn On The Cob","measure":"4"},{"name":"Water","measure":"6 cups"},{"name":"Chicken Stock Cube","measure":"2"},{"name":"Garlic","measure":"2 cloves chopped"},{"name":"Salt","measure":"1/2 tsp"},{"name":"Pepper","measure":"1/2 tsp"},{"name":"Cilantro","measure":"2 tablespoons"},{"name":"Potatoes","measure":"1/2 cup"},{"name":"Scallions","measure":"1/2 cup"},{"name":"Heavy Cream","measure":"1 cup"}],"steps":["Place the corn, water, chicken or vegetable bouillon, garlic, salt, pepper, cilantro, potatoes and scallions in a large pot and bring to a boil. Reduce heat to medium low and simmer for approximately 4 minutes or until the corn is tender.","Remove from the heat. Puruée the soup in a blender and return to the pot, add the cream and heat over medium heat for 15 minutes, stirring occasionally.","Pour into bowls, garnish with cilantro and potato sticks.","Notes","*Fresh corn or frozen corn will work for this soup recipe. I usually use fresh corn, but I use organic corn kernels in the winter to make this soup.","*To store: Place cooled corn soup in an airtight container and store in the fridge for up to 3 days."],"ingredient_names":["corn on the cob","water","chicken stock cube","garlic","salt","pepper","cilantro","potatoes","scallions","heavy cream"],"allergens":["dairy"],"diet_flags":[]},{"source_id":"53533","title":"Breaded Steak Recipe (Lomo de Res Apanado)","category":"Beef","country":"Colombia","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/lmwaf61783805434.jpg","youtube_url":null,"source_url":"https://www.mycolombianrecipes.com/breaded-steak-lomo-de-res-apanado/#recipe","ingredients":[{"name":"Beef","measure":"2 Lbs"},{"name":"Alinos Sauce","measure":"1 cup"},{"name":"All purpose flour","measure":"1 cup"},{"name":"Breadcrumbs","measure":"2 cups"},{"name":"Ground Cumin","measure":"1 tsp"},{"name":"Eggs","measure":"3"},{"name":"Salt","measure":"To taste"},{"name":"Black Pepper","measure":"To taste"},{"name":"Parsley","measure":"2 tablespoons"},{"name":"Oil","measure":"For frying"}],"steps":["Place each piece of steak in between two large pieces of plastic and using a mallet, pound it until it is about ¼″ to ½″ thick. Place the pounded steak in a glass container, add the aliños sauce and let it rest for about 3 hours or overnight in the fridge.","Add the flour, bread crumbs, spices and parsley to a plate or bowl.","Cover the steak on all sides with the flour mixture, then the eggs, and finally the flour mixture again.","Once the pieces of steak are coated, you can either add them right to a pan with oil for cooking or layer them on parchment paper until ready to fry.","Add the oil to a large skillet over medium heat. As soon as it begins to smoke lightly, add the breaded steak and cook it for about 3 to 4 minutes per side or until golden brown. Take them out of the oil and place on a plate lined with paper towels to drain off any excess oil and serve."],"ingredient_names":["beef","alinos sauce","all purpose flour","breadcrumbs","ground cumin","eggs","salt","black pepper","parsley","oil"],"allergens":["eggs","gluten"],"diet_flags":[]},{"source_id":"53536","title":"Black Beans Hotpot","category":"Vegetarian","country":"Costa Rica","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/81ahfr1784394567.jpg","youtube_url":null,"source_url":"https://www.recipesfromcostarica.com/recipes","ingredients":[{"name":"Black Beans","measure":"400g"},{"name":"Onion","measure":"1 large"},{"name":"Green Pepper","measure":"1"},{"name":"Red Pepper","measure":"1"},{"name":"Celery","measure":"1/3 cup"},{"name":"Garlic","measure":"4 Cloves Crushed"},{"name":"Ground Cumin","measure":"1 1/2 tsp"},{"name":"Oregano","measure":"1 tablespoon"},{"name":"Salt","measure":"1 1/2 tsp"},{"name":"Black Pepper","measure":"2 tsp"},{"name":"Water","measure":"5 Cups"}],"steps":["Add all the ingredients in the Instant pot, Lock the lid on and set the Instant Pot to High Pressure for 35 minutes.","Once the beans are done cooking, let the pressure release naturally for 20 minutes before releasing the remaining pressure. Open and serve!","Let the beans get cool completely before saving them in the fridge or freezer."],"ingredient_names":["black beans","onion","green pepper","red pepper","celery","garlic","ground cumin","oregano","salt","black pepper","water"],"allergens":[],"diet_flags":["pescatarian","vegan","vegetarian"]},{"source_id":"53539","title":"Picadillo de Vainicas (Green Beans Picadillo)","category":"Beef","country":"Costa Rica","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/2ncui81784396094.jpg","youtube_url":null,"source_url":"https://www.recipesfromcostarica.com/recipes","ingredients":[{"name":"Green Beans","measure":"1 lb"},{"name":"Flank Steak","measure":"2 cups"},{"name":"Onion","measure":"1/2 cup"},{"name":"Pepper","measure":"1/2 cup"},{"name":"Garlic","measure":"3 cloves"},{"name":"Thyme","measure":"1 tsp"},{"name":"Salt","measure":"1 tsp"},{"name":"Black Pepper","measure":"1/2 tsp"},{"name":"Water","measure":"1/2 cup"}],"steps":["In a medium-size pot over medium heat add some olive oil, onions, pepper, and garlic and cook until onion is translucent.","In the meantime, finely chopped the green beans.","Add to the pot, the shredded meat, green beans, thyme, salt and pepper, and mix well. Add the water, cover and cook for 15 minutes, uncover and cook for 5 more minutes or until the green beans are soft."],"ingredient_names":["green beans","flank steak","onion","pepper","garlic","thyme","salt","black pepper","water"],"allergens":[],"diet_flags":[]},{"source_id":"53540","title":"Pollo en Salsa","category":"Chicken","country":"Costa Rica","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/4o13oe1784396585.jpg","youtube_url":null,"source_url":"https://www.recipesfromcostarica.com/recipes","ingredients":[{"name":"Chicken Thighs","measure":"4"},{"name":"Oregano","measure":"1 tsp"},{"name":"Cumin","measure":"1 tsp"},{"name":"Salt","measure":"1 tsp"},{"name":"Pepper","measure":"1 tsp"},{"name":"Achiote Paste","measure":"1 1/2 tsp"},{"name":"Garlic","measure":"4 Cloves Crushed"},{"name":"Onion","measure":"1 medium"},{"name":"Tomato","measure":"1 large"},{"name":"Red Pepper","measure":"1/2"},{"name":"Chicken Stock","measure":"2 cups"}],"steps":["Chopped pepper, onion and tomato and set aside. Turn on Instant Pot in sauteed setting for 8 minutes. Add a little bit of olive oil and add, onion, garlic, tomato, bell pepper, cumin, oregano salt and pepper and sauteed for 4 minutes.","​","Add the chicken and cook for 2 minutes on each side often, mixing often. Add the chicken stock , cover and set the pressure cooker on high for 20 minutes. When done release the pressure and if need it, add a little bit more salt. I like to serve it with some of the juice over rice and beans."],"ingredient_names":["chicken thighs","oregano","cumin","salt","pepper","achiote paste","garlic","onion","tomato","red pepper","chicken stock"],"allergens":[],"diet_flags":[]},{"source_id":"53541","title":"Gallo pinto","category":"Vegetarian","country":"Costa Rica","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/ytogg31784397116.jpg","youtube_url":null,"source_url":"https://www.recipesfromcostarica.com/recipes","ingredients":[{"name":"Black Beans","measure":"2/3 Cup"},{"name":"Rice","measure":"1 1/4 cup"},{"name":"Onion","measure":"2 tablespoons"},{"name":"Pepper","measure":"2 tablespoons"},{"name":"Cilantro","measure":"2 tablespoons"},{"name":"Salsa Lizano","measure":"1/2 tsp"},{"name":"Salt","measure":"1/2 tsp"},{"name":"Cumin","measure":"1/2 tsp"},{"name":"Pepper","measure":"1/4 tsp"}],"steps":["Heat up a pan over medium high heat, add olive oil and let it get hot. Add onions, peppers, cilantro, garlic, cumin, salt and pepper, cook for 3 to 5 min until onion is translucent.","Mix in the beans, stir and reduce heat to medium, add the Lizano sauce, stir and cook for 5 more minutes.","Add the rice, stir and cooked for a few more minutes, to incorporate all the flavors in the rice. The time to cook it I will depend of how you like your gallo pinto, some people like it a little wet and some other like it a little toasted or dry.","I prefer it not too dry, so I cook it for about 5 to 7 min."],"ingredient_names":["black beans","rice","onion","pepper","cilantro","salsa lizano","salt","cumin","pepper"],"allergens":[],"diet_flags":["pescatarian","vegan","vegetarian"]},{"source_id":"53545","title":"Ropa Veija","category":"Beef","country":"Cuba","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/thvft91784576451.jpg","youtube_url":null,"source_url":"https://www.delish.com/cooking/recipe-ideas/a40741177/ropa-vieja-recipe/","ingredients":[{"name":"Flank Steak","measure":"2 Lbs"},{"name":"Kosher Salt","measure":"3 tsp"},{"name":"Vegetable Oil","measure":"4 tablespoons"},{"name":"Red Pepper","measure":"1"},{"name":"Yellow Pepper","measure":"1"},{"name":"Onion","measure":"1"},{"name":"Garlic","measure":"6 cloves"},{"name":"Tomato Puree","measure":"2 tablespoons"},{"name":"Smoked Paprika","measure":"1 tablespoon"},{"name":"Cumin","measure":"2 tsp"},{"name":"Dried Oregano","measure":"2 tsp"},{"name":"Dry White Wine","measure":"1/2 cup"},{"name":"Tinned Tomatos","measure":"1 Can"},{"name":"Bay Leaf","measure":"2"},{"name":"Pimento Stuffed Olives","measure":"1 cup"},{"name":"Rice","measure":"To serve"},{"name":"Black Beans","measure":"To serve"},{"name":"Cilantro","measure":"1/4 cup"}],"steps":["Cut steak into 4 rectangular pieces. Pat dry with paper towels; season all over with 1 1/2 teaspoons salt.","In a large pot over medium-high heat, heat 2 tablespoons oil. Working in batches, cook steak until browned on both sides, 5 to 6 minutes. Transfer to a plate.","In same pot over medium heat, heat remaining 2 tablespoons oil. Cook bell peppers, onion, and 1 1/2 teaspoons salt, stirring occasionally, until slightly softened, 4 to 5 minutes. Add garlic, tomato paste, paprika, cumin, and oregano and cook, stirring occasionally, until vegetables are softened and spices are aromatic, 1 to 2 minutes more.","Add wine, scraping any browned bits from bottom of pan, and cook, stirring occasionally, until reduced by half, about 2 minutes. Add tomatoes with their juices and bay leaves. Mash down on tomatoes to break up, then nestle beef into stew. Add water to cover beef, if needed, and bring to a simmer. Reduce heat to medium-low; cover and simmer until steaks are tender enough to shred, 2 1/2 to 3 hours. Transfer steaks to a plate and finely shred with 2 forks.","Stir shredded steak back into stew. Bring to a simmer and cook, stirring, until liquid has reduced to a sauce that coats steak, 5 to 10 minutes. Stir in olives; season with salt.","Spoon ropa vieja over rice and beans. Top with cilantro."],"ingredient_names":["flank steak","kosher salt","vegetable oil","red pepper","yellow pepper","onion","garlic","tomato puree","smoked paprika","cumin","dried oregano","dry white wine","tinned tomatos","bay leaf","pimento stuffed olives","rice","black beans","cilantro"],"allergens":[],"diet_flags":[]},{"source_id":"53547","title":"Cuban Sandwich","category":"Pork","country":"Cuba","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/djdg8l1784578885.jpg","youtube_url":null,"source_url":"https://www.delish.com/cooking/recipe-ideas/a64854750/homemade-cuban-sandwiches-recipe/","ingredients":[{"name":"Pork Chops","measure":"1 lb"},{"name":"Kosher Salt","measure":"Pinch"},{"name":"Vegetable Oil","measure":"2 tablespoons"},{"name":"Orange","measure":"Juice/zest of one"},{"name":"Lime","measure":"Juice/zest of one"},{"name":"Dried Oregano","measure":"2 tsp"},{"name":"Ground Black Pepper","measure":"1 tsp"},{"name":"Garlic Powder","measure":"1 tsp"},{"name":"Dijon Mustard","measure":"2 tablespoons"},{"name":"Mayonnaise","measure":"2 tablespoons"},{"name":"Cuban Bread","measure":"8 oz"},{"name":"Unsalted Butter","measure":"1 tablespoon"},{"name":"Swiss Cheese","measure":"4 oz"},{"name":"Deli Ham","measure":"8 oz"},{"name":"Dill Pickles","measure":"2"}],"steps":["Place pork chops in a 3-qt. glass baking dish. Using a fork, poke holes into pork all over; season all over with 1 tsp. salt. Drizzle with oil and toss to coat.","In a small bowl, combine orange zest and juice, lime zest and juice, oregano, pepper, garlic powder, cumin, and onion powder. Add half of marinade to pork and let rest 10 to 15 minutes.","Meanwhile, arrange a rack in center of oven; preheat to 425°. Add mustard and mayonnaise to remaining marinade and stir until smooth.","Transfer pork to oven and roast until an instant-read thermometer inserted into thickest part registers 140°, 15 to 20 minutes.","To build sandwiches, cut loaf in half crosswise, then cut each piece in half lengthwise for 4 pieces total. Spread butter on outside of bread on the top and bottom. Spread mustard mixture on cut sides of bread. On 2 bread pieces, layer each with 2 oz. cheese, 4 oz. ham, half of roast pork, 4 pickle slices, and remaining 2 oz. cheese. Close with remaining bread pieces and wrap each sandwich in foil.","Heat a large cast-iron skillet over medium heat. Place foil-wrapped sandwiches in skillet, then place another heavy skillet on top to create a homemade sandwich press. If you don’t have another heavy skillet, weigh the pan down with another lighter skillet or baking sheet, then top with couple of canned goods.","Grill sandwiches, turning halfway through, until toasted and cheese is melted, 3 to 4 minutes per side. Cut each sandwich in half and serve."],"ingredient_names":["pork chops","kosher salt","vegetable oil","orange","lime","dried oregano","ground black pepper","garlic powder","dijon mustard","mayonnaise","cuban bread","unsalted butter","swiss cheese","deli ham","dill pickles"],"allergens":["dairy","eggs","gluten"],"diet_flags":[]},{"source_id":"53549","title":"Chicken Salad With Mushrooms and Bacon","category":"Chicken","country":"Denmark","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/t5rgav1784659936.jpg","youtube_url":null,"source_url":"https://denmark.dk/people-and-culture/recipes/chicken-salad/","ingredients":[{"name":"Chicken Breast","measure":"300g"},{"name":"Shallots","measure":"1"},{"name":"Mayonnaise","measure":"3  tablespoons"},{"name":"Creme Fraiche","measure":"4 tablespoons"},{"name":"Dijon Mustard","measure":"3 tsp"},{"name":"Apple Cider Vinegar","measure":"1 tablespoon"},{"name":"Bacon","measure":"100g"},{"name":"Mushrooms","measure":"250g"},{"name":"Parsley","measure":"Sprigs of fresh"},{"name":"Salt","measure":"To taste"},{"name":"Pepper","measure":"To taste"}],"steps":["Place chicken breast in a saucepan and cover with water. Bring to a boil, add 1 tsp salt and simmer for approximately 15 minutes. Allow chicken to cool and then shred meat with two forks.","Finely chop shallot/red onion.","Stir mayonnaise, crème fraîche, Dijon mustard and apple cider vinegar to combine. Season with salt, pepper and extra Dijon mustard to taste. Combine with onion and chicken.","Fry bacon until crisp and transfer to plate lined with paper towels.","Rinse mushrooms, slice and fry in the same pan as bacon until golden (approximately 5 minutes). Season with a bit of salt and pepper.","Arrange your chicken salad in a serving dish, topped with crisp bacon, mushrooms and chopped parsley. Serve on a slice of light or dark bread."],"ingredient_names":["chicken breast","shallots","mayonnaise","creme fraiche","dijon mustard","apple cider vinegar","bacon","mushrooms","parsley","salt","pepper"],"allergens":["dairy","eggs"],"diet_flags":[]},{"source_id":"53553","title":"Frikadeller - Danish Meatballs","category":"Pork","country":"Denmark","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/bnhfa71784662834.jpg","youtube_url":null,"source_url":"https://denmark.dk/people-and-culture/recipes/danish-meat-balls/","ingredients":[{"name":"Onion","measure":"1 large"},{"name":"Garlic","measure":"1 clove"},{"name":"Minced Pork","measure":"500g"},{"name":"All purpose flour","measure":"1 tablespoon"},{"name":"Oats","measure":"1 tablespoon"},{"name":"Milk","measure":"1/2 cup"},{"name":"Egg","measure":"1"},{"name":"Salt","measure":"1 tablespoon"},{"name":"Ground Black Pepper","measure":"1 tsp"},{"name":"Butter","measure":"2 tablespoons"}],"steps":["Finely chop onion and garlic.","Stir salt into minced meat. Add the dry ingredients, then onion and garlic, then the egg. and lastly the milk. Stir the meat mixture until it is firm. Refrigerate for at least 30 minutes. You can also make the mixture one day in advance and refrigerate.","Heat a pan over medium heat. Add butter to the pan and use a spoon to form frikadeller (meatballs) in your preferred size. We recommend using about 2 tablespoons of mixture per frikadelle.","Fry until they develop a nice browned crust on both sides and are cooked all the way through.","Serve hot with a classic potato salad on the side."],"ingredient_names":["onion","garlic","minced pork","all purpose flour","oats","milk","egg","salt","ground black pepper","butter"],"allergens":["dairy","eggs","gluten"],"diet_flags":[]},{"source_id":"53554","title":"Open-faced Sandwich With Potato","category":"Pork","country":"Denmark","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/wooxjq1784663522.jpg","youtube_url":null,"source_url":"https://denmark.dk/people-and-culture/recipes/open-sandwich-with-potato/","ingredients":[{"name":"New Potatoes","measure":"500g"},{"name":"Bacon","measure":"4 slices"},{"name":"Mayonnaise","measure":"4 tablespoons"},{"name":"Chives","measure":"Handful"},{"name":"Rye Bread","measure":"8 slices"},{"name":"Red Onions","measure":"2"},{"name":"All purpose flour","measure":"1/2 cup"},{"name":"Vegetable Oil","measure":"1 1/4 cup"},{"name":"Sea Salt","measure":"Pinch"}],"steps":["Scrub the potatoes clean and place in a small saucepan with water and 1 tablespoon of salt. Bring to a boil and simmer the potatoes for about 10 minutes. Turn off the heat and let the potatoes stand in the water for 5 minutes. Drain the potatoes and allow to cool slightly. Remember that potatoes come in various sizes, so the cooking time may vary – if they do not easily glide off of a fork when speared and lifted out of the water, they are not done yet.","Fry bacon slices and transfer to a dish lined with paper towels.","Peel the red onion and slice in thin rings.","Transfer the flour to a bowl and toss the onions in the flour. Remove onions and shake off excess flour.","Heat the oil in a saucepan over medium heat. You can test whether the oil is hot enough by adding a small piece of onion to the saucepan. If the oil bubbles around the onion, the oil is ready.","Transfer as many onion rings to the saucepan as can fit in one layer. Do not add too many onion rings at once.","Fry the onions for a couple of minutes until they are golden brown. Transfer onions to a dish lined with paper towels and sprinkle with salt. Repeat the process until all onions are fried.","Butter a slice of dark rye bread and arrange round potato slices (or, if the potatoes are very small, halved potatoes) on top. Top your open potato sandwich with a good mayonnaise, crispy fried onions, fried bacon and sliced chives."],"ingredient_names":["new potatoes","bacon","mayonnaise","chives","rye bread","red onions","all purpose flour","vegetable oil","sea salt"],"allergens":["eggs","gluten"],"diet_flags":[]},{"source_id":"53557","title":"Extra crispy chicken wings","category":"Chicken","country":"Dominica","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/feh9k21784665694.jpg","youtube_url":null,"source_url":"https://dominicagourmet.com/extra-crispy-chicken-wings/","ingredients":[{"name":"Chicken Wings","measure":"2 Lbs"},{"name":"Salt","measure":"To taste"},{"name":"Black Pepper","measure":"1 tablespoon"},{"name":"Garlic Powder","measure":"1 tablespoon"},{"name":"Turmeric","measure":"1 tsp"},{"name":"Oil","measure":"For frying"},{"name":"Cassava","measure":"1 1/2 cup"}],"steps":["Wash chicken and pat dry","Place in a large bowl","Season with garlic, salt, pepper and turmeric (you can expand your seasoning options if you'd like.","Marinate for at least an hour","Pour some tapioca flour on a plate","Coat the wings with the cassava flour and place them on a rack or plater to set. Leave them for at least 30minutes to an hour.","Heat the oil in the saucepan until it’s hot.","Place wings in pan on medium heat, until light brown.","Drain on a paper towel, and let the wings rest for at least 10 minutes, then return the wings to the hot pan on high heat and fry until golden brown.","Enjoy!"],"ingredient_names":["chicken wings","salt","black pepper","garlic powder","turmeric","oil","cassava"],"allergens":[],"diet_flags":[]},{"source_id":"53561","title":"Codfish deviled eggs","category":"Seafood","country":"Dominica","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/vayi021784668764.jpg","youtube_url":null,"source_url":"https://dominicagourmet.com/codfish-deviled-eggs-recipe/","ingredients":[{"name":"Eggs","measure":"12"},{"name":"Mayonnaise","measure":"7 tablespoons"},{"name":"Mustard","measure":"1 tsp"},{"name":"Pepper","measure":"To taste"},{"name":"Salt","measure":"To taste"},{"name":"Paprika","measure":"Pinch"},{"name":"Chives","measure":"Garnish"},{"name":"Black Pepper","measure":"Garnish"},{"name":"Codfish Bulljaw","measure":"Topping"}],"steps":["Bring eggs to a boil for 15 minutes. Let eggs sit in the water for another 5. Run under cold water","let eggs further cool","Rest eggs","Peel eggs","Cut eggs in half and remove egg yolks, place them in bowl","Mash egg yolks in a bowl","Combine all ingredients except for chives and peppercorns","Put the mixture in a piping bag or plastic bag","Fill egg slices with the mixture","Add codfish on the wider side of the egg","Garnish with crushed peppercorn and chive"],"ingredient_names":["eggs","mayonnaise","mustard","pepper","salt","paprika","chives","black pepper","codfish bulljaw"],"allergens":["eggs","fish","shellfish"],"diet_flags":["pescatarian"]},{"source_id":"53565","title":"Chicken Lollipop","category":"Chicken","country":"Dominica","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/nz0lg71784671684.jpg","youtube_url":null,"source_url":"https://dominicagourmet.com/chicken-lollipop-recipe/","ingredients":[{"name":"Chicken Wings","measure":"2 Lbs"},{"name":"Black Pepper","measure":"1 tablespoon"},{"name":"Paprika","measure":"1 tablespoon"},{"name":"Garlic","measure":"1 tablespoon"},{"name":"Salt","measure":"1 tablespoon"},{"name":"Cornstarch","measure":"4 tablespoons"}],"steps":["Wash chicken with lemon","Drain and season chicken","Using shears, cut through the meat at the tip of the drumettes","Add all seasoning ingredients to the drumettes","Pour oil into a deep fryer, or saucepan to the level of about 5 inches so that the chicken will be submerged","Fry until medium brown, add your favorite sauce (I used honey garlic barbecue sauce) to place in the oven","Or fry until golden brown if you're not putting it in the oven","Using a silicon brush add sauce to chicken and place in the oven"],"ingredient_names":["chicken wings","black pepper","paprika","garlic","salt","cornstarch"],"allergens":[],"diet_flags":[]},{"source_id":"53573","title":"Papaya salad","category":"Vegetarian","country":"Dominica","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/7ytdtz1784833420.jpg","youtube_url":null,"source_url":"https://dominicagourmet.com/green-papaya-salad-with-fried-snapper/","ingredients":[{"name":"Green Papaya","measure":"1/2"},{"name":"Lemon Juice","measure":"1 tablespoon"},{"name":"Salt","measure":"To taste"},{"name":"Carrots","measure":"1"},{"name":"Cherry Tomatoes","measure":"1 cup"},{"name":"Spring Onions","measure":"1/2 cup"},{"name":"Roasted Peanut","measure":"1/4 cup"},{"name":"Garlic","measure":"1 tablespoon"}],"steps":["Cut, peel and shred papaya. I used a hand julienne shredder. If you don't have a shredder, use a grater.","Peel and shred carrots.","Cut green onions really small","Slice tomatoes down the middle","I then combined all ingredients","I topped it with the peanuts"],"ingredient_names":["green papaya","lemon juice","salt","carrots","cherry tomatoes","spring onions","roasted peanut","garlic"],"allergens":["peanuts"],"diet_flags":["pescatarian","vegan","vegetarian"]},{"source_id":"53576","title":"Carrot and Bean Fritters","category":"Vegetarian","country":"Estonia","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/xjii2g1784836867.jpg","youtube_url":null,"source_url":"https://estoniancuisine.com/2021/01/15/carrot-and-bean-fritters-porgandi-oakotletid/#more-12384","ingredients":[{"name":"Carrots","measure":"400g"},{"name":"Canned Beans","measure":"200g"},{"name":"Garlic","measure":"4 cloves"},{"name":"Flour","measure":"1 tablespoon"},{"name":"Breadcrumbs","measure":"1 cup"},{"name":"Thyme","measure":"Pinch"},{"name":"Parsley","measure":"Pinch"},{"name":"Salt","measure":"Pinch"},{"name":"Pepper","measure":"Pinch"},{"name":"Thyme","measure":"Pinch"},{"name":"Oil","measure":"Splash"}],"steps":["Pour the beans into the sieve, remove liquid.","Grate carrots and add beans, Mix and mash together. Season with garlic, thyme, salt and pepper.","Form the dough into round buns, dip them slightly into the bread crumbs, and press the fritters.","Fry fritters in hot oil for a short time until the fritters are browned.  Place on the greased or /baking paper-lined oven plate and bake at 200C for 10 minutes."],"ingredient_names":["carrots","canned beans","garlic","flour","breadcrumbs","thyme","parsley","salt","pepper","thyme","oil"],"allergens":["gluten"],"diet_flags":["pescatarian","vegan","vegetarian"]},{"source_id":"53577","title":"Sauerkraut and Fish Salad","category":"Seafood","country":"Estonia","tags":[],"image_url":"https://www.themealdb.com/images/media/meals/2i0plx1784837241.jpg","youtube_url":null,"source_url":"https://estoniancuisine.com/2021/01/09/sauerkraut-and-fish-salad-hapukapsa-kalasalat/","ingredients":[{"name":"Sauerkraut","measure":"200g"},{"name":"Smoked Haddock","measure":"100g"},{"name":"Egg","measure":"1"},{"name":"Rye Bread","measure":"2 sliced"},{"name":"Oil","measure":"200g"},{"name":"Honey","measure":"Drizzle"},{"name":"Salt","measure":"Pinch"}],"steps":["Boil eggs and toast bread slices.","mix together salad dressing. NB! you can serve this salad with sour cream dressing. It would be different but still very delicious","Mix together sauerkraut, sliced egg, fish and bread pieces. Serve"],"ingredient_names":["sauerkraut","smoked haddock","egg","rye bread","oil","honey","salt"],"allergens":["eggs","fish","gluten"],"diet_flags":["pescatarian"]}]$seed$::jsonb) as r(source_id text, title text, category text, country text, tags text[], image_url text, youtube_url text, source_url text, ingredients jsonb, steps jsonb, ingredient_names text[], allergens text[], diet_flags text[])
on conflict (source_id) do update set title = excluded.title, category = excluded.category, country = excluded.country, tags = excluded.tags, image_url = excluded.image_url, youtube_url = excluded.youtube_url, source_url = excluded.source_url, ingredients = excluded.ingredients, steps = excluded.steps, ingredient_names = excluded.ingredient_names, allergens = excluded.allergens, diet_flags = excluded.diet_flags;
